(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["561"] = {"atoms": {"561.1": {"x": [[1, "ذي الأمد الأقصى في شرح أسماء الله الحسنى وصفاته العلى\rتحرير: الإمام الحافظ أبي بكر محمد بن عبد الله بن محمد ابن العربي المعافري الإشبيلي المتوفى سنة 543 هـ\rضبط نصه: عبد الله التوراتي\rخرج أحاديثه ووثق نقوله: أحمد عروبي\rالسفر الأول\rدار الحديث الكنانية"], [153, "قال الإمام الحافظ أبو بكر محمد بن عبد الله ابن العربي المعافري رضي الله عنه وعن آبائه فيما حدّثنا به:\rالحمد لله قبل كل مقال، وعلى كل حال، وفي كل زمان وعند كل مثوى وارتحال، فبحمده يُستفتح الباب، ويستنتجح الطلاب، ويُستمنح اللباب، ويقضى كل مفترَض، ويُبلغ جميع الغرض، وبالإقرار بالتقصير عن القيام بالثناء عليه يكون الانتهاء إليه، وبالعجز عن معرفته يتوصل إلى معرفته.\rأما بعد، فقد كنت متشوقاً إلى قرع باب العلم بربي، متشوفاً إلى مطالعة حضرته وما فيها من عجائب المعارف وفنون المعلومات، فوفّق بفضله إلى سواء سبيله، ويسر العثور على دليله، وميز جملة العلم من تفصيله، وقيّض من العالِمينكل شهم الفؤاد، مستن السَّداد، ذي صدر باليقين رحْب، وبحر في التبيين عذب، قد حلب العلمَ أشطُرَه، وحواه أكثره، وتمرن به حِذقاً وجدلاً، وأحسن به اعتقاداً وعملاً، وسبّب بخيرته الوصول إليهم، والوفودَ\r"], [154, "عليهم، وسنى الرحلى التي بها تنال البغية، وتحفظ الملة، فهداني الله بهم اللقم، واستقبل بي الأتم، وأسامني في أنضر الرياض، وسقاني من أعذب الحياض، فملأت دلوي إلى عقد كربه، وأبتُ خالياً عن غموم الجهل وكُرَبه، موقَرَ الحقائب، موفَّر الرغائب.\rوبعد أن ترامت بي النوى أقصاها، عطفت بي إلى الوطن أسباب وألقت عصاها، وأنا أحاول في كل حين تجديد العهد بما قيدت، وتأكيد ما وعيت، ونظم ما جمعت، حتى أعلِّقه عِقداً في جيد المعالي، وأنصبه تاجاً على هامة الأيام والليالي، وأعتدّه قربة، ليوم الكربة، أرجو أن أكون ممن شرفهم الله بالذكر، وخصهم بالعلم، فقال: {وَمَا كَانَ الْمُؤْمِنُونَ لِيَنفِرُوا كَافَّةً فَلَوْلَا\r"], [155, "نَفَرَ مِن كُلِّ فِرْقَةٍ مِّنْهُمْ طَائِفَةٌ لِّيَتَفَقَّهُوا فِي الدِّينِ وَلِيُنذِرُوا قَوْمَهُمْ إِذَا رَجَعُوا إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ} [التوبة: 122].\rفكان أفضل ما انتدبتُ إليه، وعقدتُ العزم عليه، التعريفُ بالله تعالى، والتفسير لأسمائه الحسنى وصفاته العلى، فنظمت فيها شتيت تعليقي، وصدعتُ بتبيانها وعاء تحقيقي، وجلوتُ نكتاً طالما شددت إليها الحزام، طبعت عليها الختام، فهذا أوان جلاها، وهذه جواهرها وحلاها.\rوقد سبق إلى هذا المعنى جماعة من المتقدمين، فجاؤوا مستأخرين ومستقدمين، ومنهم من أوعب وأطنب، ومنهم من هذب وقرّب، وما استولى على المرغوب، ولا قرطس المطلوب، إلا بعض أشياخي، فإنه جمع فيها كتاباً صغير الحجم، استوعب جملاً عظيمة، وأشار إلى أمور بديعة، هتك بها حجاب الإخفاء، وقام فيها بواجب جمل الاحتفاء، وعلى كثرة ما جمعنا فيها، وأوثقنا من مبانيها، وأوضحنا لمعانيها، فإنا على منواله ننسج، وفي\r"], [156, "سبيله نستنهج، وربما اقتحم فيها - على سيرته - أموراً لا تطاق، وجاء بألفاظ يضيق عنها النطاق، سنفاوضه منها فيما أمكن، ونعرض عما استبهم، احتشاماً لجانبه الرفيع، واغتناماً لبيانه البديع.\rوالله ولي التوفيق في كل حال، الملي بالتمييز بين الحق والمحال، إنه شديد المِحال، لا رب غيرُه.\rتراجم الكتاب:\rاعلموا - أفادكم الله عِرفانه، ومنحكم تِبيانه - أن مدار الكلام فيه ينبني على أربعة أقطاب:\r- القطب الأول: في ذكر أسماء الله عز وجل على الجملة والتفصيل، وذكر مواردها واختلاف الروايات فيها.\r- القطب الثاني: في ذكر سوابق وفواتح لا بد من تقديمها، بياناً لما عسى أن يستبهم من أغراضه.\r- القطب الثالث: في شرح معانيها وإيضاح مقتضاها.\r-القطب الرابع: في ذكر متممات بها يكمل المقصود، ويحصل بفضل الله المطلوب.\r"], [157, "وكل قطب منها يشتمل على فصول، وأصول، وتمهيدات، وفروع وتقسيمات، بها يقع الشفاء لمرض جهالتها.\rوقد علم الله سبحانه أنا لم نألُ ذلك كله، ولا فرطنا في معنى من معانيه، بل انتقينا من كلام العلماء كل غريبة، وأوردنا كل بديعة، وعقّبناه من الاجتهاد ما نتضرع إلى الله في أن يقرُنَه بالسداد، سالكين في سبيل الاستيفاء ما يمكن به الوفاء، مع إيعاب في خالص اللباب، واختصار لا يُخل بالمراد، واقتصار على المهم والاقتصاد، آمّين الأمد الأقصى في معرفة الأسماء الحسنى وأفعاله تعالى، حتى أوفينا على العدد، واستولينا بفضل الله الأمد، فله الحمد رب العالمين، لا رب غيره.\r"], [159, "القطب الأول:\rفي ذكر أسماء الله تعالى على الجملة والتفصيل وذكر مواردها / واختلاف الروايات فيها\rوفيه خمسة فصول:\r"], [161, "الفصل الأول:\r"]], "pg": [1, 161]}, "561.2": {"x": [[161, "في ذكر الأحاديث الواردة في هذا الباب وتعديد الأسماء فيها\rاعلموا - جعلكم الله ممن سمع العلم ووعاه، ثم قيده ورعاه - أن الثابت عن النبي صلى الله عليه وسلم أنه قال: (إن لله تسعة وتسعين اسماً، مائةً إلا واحداً، الله وِتْرٌ يحب الوتر، من أحصاها دخل الجنة)، من غير تفسير للأسماء، ولا تعديد لذكرها.\rوروى جماعة من العلماء عن شعيب بن أبي حمزة، عن أبي الزناد الحديثَ بعينه، فعدّدها فقال: (هو الله الذي لا إله إلا هو الرحمن، الرحيم، الملك، القدوس، السلام، المؤمن، المهيمن، العزيز، الجبار، المتكبر،\r"], [162, "الخالق، البارئ، المصور، الغفار، القهار، الوهاب، الرزاق، الفتاح، العليم، القابض، الباسط، الخافض، الرافع، المعز، المذل، السميع، البصير، الحكم، العدل، اللطيف، الخبير، الحليم، العظيم، الغفور، الشكور، العلي، الكبير، الحفيظ، المُقيت، الحسيب، الجليل، الكريم، الرقيب، المجيب، الواسع، الحكيم، الودود، المجيد، الباعث، الشهيد، الحق، الوكيل، القوي، المتين، الولي، الحميد، المُحصي، المبدئ، المعيد، المحيي، المميت، الحي، القيوم، الواجد، الماجد، الواحد، الصمد، القادر، المقتدر، المقدم، المؤخر، الأول، الآخر، الظاهر، الباطن، الوالي، المتعالاي، البر، التواب، المنتقم، العفو، الرؤوف، مالك الملك، ذو الجلال والإكرام، المقسط، الجامع، الغني، المغني، المانع، الضار، النافع، النور، الهادي، البديع، الباقي، الوارث، الرشيد، الصبور).\rورويت معدودةً في الحديث بعينه عن أبي هريرة من طريق ابن سيرين، فذكرها وذكر فيها أسماءً ليست في حديث شعيب، وأسقط منها أيضاً أسماءً رُويت من تلك الطريق.\r"], [163, "ونص ما فيها من طريق ابن سيرين غيرُ ما تقدم ذكرُه: (الرب، المنان، البارئ، الكافي، الدائم، المولى، النصير، الجميل، الصادق، المحيط، المبين، القريب، الفاطر، العلام، المليك، الأكرم، المُدبِّر، الوتر، ذو المعارج، ذو الطَّول، ذو الفضل).\rرواه عن ابن سيرين أيوبُ وهشامُ بن حسان، رواه عنهما عبد العزيز بن الحصين، وليس بالقوي عند أهل الحديث، وشعيب بن أبي حمزة وإن كان عندهم ثقة مأموناً، لكن لا يُعلم هل تفسير هذه الأسماء في الحديث أم من قول الراوي، والظاهر أنها من قول الراوي لوجهين:\rأحدهما: أن أصحاب الصحيح لم يذكروها.\rوالثاني: أن فيها تفسيراً بزيادة ونقصان لا يليق بالمرتبة العليا النبوية.\r"], [164, "وروي عن سفيان بن عيينة أنه سئل عن تعديد الأسماء حين روى الحديث مطلقاً، فأملّها على أصحابه، وقال: (في فاتحة الكتاب خمسة أسماء: يا الله، يا رب، يا رحمن، يا رحيم، يا ملك.\rوفي البقرة ستة وعشرون اسماً: يا محيط، يا قدير، يا عليم، يا حكيم، يا تواب، يا بصير، يا واسع، يا بديع، يا سميع، يا كافٍ، يا رؤوف، يا شاكر، يا الله، يا واحد، يا غفور، يا عليم، يا قابض، يا باسط، يا لا إله إلا هو، يا حي، يا قيوم، يا علي، يا عظيم، يا ولي، يا غني، يا حميد.\rوفي آل عمران أربعة أسماء: يا قدير، يا وهّاب، يا سريع، يا خبير.\rوفي النساء ستة أسماء: يا رقيب، يا حسيب، يا شهيد، يا عفو، يا مُقيت، يا وكيل.\rوفي الأنعام خمسة أسماء: يا فاطر، يا قاهر، يا واحد، يا لطيف، يا خبير.\r"], [165, "وفي الأعراف اسمان: يا محيي، يا مميت.\rوفي الأنفال اسمان، يا نعم المولى، ويا نعم النصير.\rوفي هود سبعة أسماء: يا حفيظ، يا قريب، يا مجيب، يا قوي، يا مجيد، يا ودود، يا فعّالاً لما يريد.\rوفي الرعد اسمان: يا كبير، يا متعال.\rوفي إبراهيم اسم: يا منان.\rوفي الحجر اسم: يا خلاق.\rوفي مريم اسمان: يا صادق، يا وارث.\rوفي الحج اسم: يا باعث.\rوفي المؤمنين اسم: يا كريم.\rوفي النور ثلاثة أسماء: يا حق، يا مبين، يا نور.\rوفي الفرقان اسم: يا هادي.\rوفي سبأ اسم: يا فتاح.\rوفي المؤمن أربعة أسماء: يا غافر، يا قابل التوب، يا شديد، يا ذا الطَّول.\rوفي والذاريات ثلاثة أسماء: يا رزاق، يا ذا القوة، يا متين.\rوفي والطور اسم: يا بر.\r"], [166, "وفي واقتربت اسم: يا مقتدر.\rوفي الرحمن ثلاثة أسماء: يا باقٍ، يا ذا الجلال، والإكرام.\rوفي الحديد أربعة أسماء: الأول، الآخر، الظاهر، الباطن.\rوفي الحشر عشرة أسماء: يا قدوس، يا سلام، يا مؤمن، يا مهيمن، يا عزيز، يا جبار، يا متكبِّر، يا خالق، يا بارئ، يا مصوِّر.\rوفي البروج اسمان: يا مبدئ، يا معيد.\rوفي قل هو الله أحد اسمان: يا أحد، يا صمد).\rقال الإمام الحافظ رضي الله عنه: وإذا استقريتَ ما عدده وتتبعتَه في القرآن ألفيتَه قد أغفلَ ما كان حقه الذِّكر وَذَكَرَ سواه، وذلك أنه قال في بعض السور أسماءً أخذها من الأفعال، وترك في بعضها أسماءً منصوصة، كما فعل في سورة البقرة، إذ عدد فيها ستة وعشرين اسماً، وأسقط منها أسماء: شاكر، وإله، وواحد، وقريب، وزاد فيها اسم قابض وباسط من الأفعال، وكذلك فعل في بعض السور.\rولو سلكنا هذا المسلك لأربت الأسماء على هذا المُدرَك، واستع الكلام وانحل النظام، وقد تابعه في ذلك محمد بن شعبان، فذكرها بلفظها على سورها حرفاً بحرف.\r"], [167, "ثم قال: (وقد قيل: إن تعديد الأسماء: الله، الرحمن، الرحيم، الإله، الرب، الملك، القدوس، السلام، المؤمن، المهيمن، العزيز، الجبار، المتكبر، الخالق، البارئ، المصور، الحليم، العليم، السميع، البصير، الحي، القيوم، الواسع، اللطيف، الخبير، الحنان، المنان، البديع، الودود، الغفور، الشكور، المجيد، المبدئ، المعيد، النور، الهادي، الأول، الآخر، الظاهر، الباطن، العفو، الغفار، الوهاب، القادر، الأحد، الصمد، الوكيل، الكافي، الباقي، الحميد، المُقيت، الدائم، المتعالي، ذو الجلال، والإكرام، المولى، النصير، الحق، المبين، الباعث، المجيب، المحيي، المميت، الجميل، الصادق، الحفيظ، المحيط، الكبير، القريب، الرقيب، الفتاح، التواب، القديم، الولي، الفاطر، الرزاق، العلام، الرؤوف، المدبِّر، المالك، القاهر، الهادي، الشاكر، الكريم، الرفيع، الشهيد، الواحد، ذو الطول، ذو المعارج، ذو الفضل، الخلاق، الكفيل، الجليل، العلي، العظيم، الغني، المليك، المقتدر، الأكرم).\rوهذا كله قاصر عن المراد، يتزيَّف بالانتقاد.\r"], [168, "ولقد تتبعناها في كتاب الله، وقرأناه واستقريناه قصدَ ذلك، فوجدتها على ما أسطِّره، وهي:\r(بسم الله الرحمن الرحيم: سورة الحمد لله فيها خمسة أسماء: الله، الرب، الرحمن، الرحيم، ملك.\rسورة البقرة فيها ثلاثون اسماً: محيط، قدير، عليم، حكيم، ذو الفضل العظيم، بصير، واسع، بديع السماوات، سميع، التواب، العزيز، رؤوف، شاكر، إله، واحد، غفور، شديد العذاب، قريب، شديد العقاب، سريع الحساب، حليم، خبير، حي، قيوم، علي، عظيم، ولي، غني، حميد، مولى.\rسورة آل عمران فيها عشرة أسماء: عزيز، ذو انتقام، وهاب، قائم بالقسط، جامع الناس، مالك الملك، خير الماكرين، شهيد، خير الناصرين، وكيل.\rسورة النساء فيها سبعة أسماء: الرقيب، الحسيب، كبير، العفو، النصير، مقيت، جامع المنافقين والكافرين في جهنم جميعاً.\rسورة المائدة فيها اسمان: علام الغيوب، خير الرازقين.\rسورة الأنعام فيها سبعة عشر اسماً: فاطر، قاهر، شيء، شفيع، خير الفاصلين، الحق، أسرع الحاسبين، القادر، فالق الحب والنوى، فالق\r"], [169, "الإصباح، جاعل الليل سكناً، مخرج الحي من الميت، ومخرج الميت من الحي، سريع العقاب، خالق كل شيء، اللطيف، الحَكَم.\rسورة الأعراف فيها أربعة أسماء: خير الحاكمين، خير الفاتحين، أرحم الراحمين، خير الغافرين.\rسورة براءة: مخزي الكافرين.\rسورة هود فيها سبعة أسماء: أحكم الحاكمين، حفيظ، مجيب، قوي، مجيد، ودود، فعال لما يريد.\rسورة يوسف فيها ثلاثة أسماء: المستعان، القهّار، الحافظ.\rسورة الرعد فيها ستة أسماء: ذو مغفرة، عالم الغيب والشهادة، الكبير، المتعال، شديد المحال، القائم على كل نفس بما كسبت.\rسورة الحِجر فيها اسمان: الوارث، الخلاق.\rسورة النحل فيها واحد: كفيل.\rسورة الكهف فيها ثلاثة أسماء: مقتدر، ذو الرحمة، الموئل.\rسورة مريم فيها اسم واحد، حَفِيّ.\rسورة طه فيه اسمان: الملك، خير وأبقى.\rسورة اقترب فيها ثلاثة أسماء: الحاسب، خير الوارثين، الفاعل.\rسورة الحج فيها اسم واحد: المكرِم.\rسورة المؤمنين فيها اسمان: أحسن الخالقين، خير المنزِلين.\r"], [170, "سورة النور فيها اسمان: المبين، نور السماوات والأرض.\rسورة الفرقان فيها اسم: الهادي.\rسورة النمل اسم: الكريم.\rسورة الروم اسم: محيي الموتى.\rسورة سبأ فيها الفتاح.\rسورة فاطر اسم واحد: شكور.\rسورة ص اسم واحد: الغفار.\rسورة الزمر فيها اسمان: سالم، كافٍ.\rسورة المؤمن فيها خمسة أسماء: غافر الذنب، قابل التوب، ذو الطول، رفيع الدرجات، ذو العرش.\rسورة فصلت اسم: ذو عقاب.\rسورة الزخرف فيها اسم: المبرِم.\rسورة الدخان فيها ثلاثة أسماء: المنذِر، المرسِل، المنتقم.\rسورة ق: أقرب إليه من حبل الوريد.\rسورة والذاريات فيها خمسة أسماء: الموسِع، الماهد، الرزاق، ذو القوة، المتين.\rسورة والطور فيها اسم واحد: البَر.\r"], [171, "سورة اقتربت فيها اسم واحد: المليك.\rسورة الرحمن فيها اسم واحد: ذو الجلال والإكرام.\rسورة الواقعة فيها ثلاثة أسماء: الخالق، الزارع، المنشئ.\rسورة الحديد فيها أربعة أسماء: الأول، الآخر، الظاهر، الباطن.\rسورة المجادلة فيها اسمان: رابع ثلاثة، سادس خمسة.\rسورة الحشر فيها عشرة أسماء: القدوس، السلام، المؤمن، المهيمن، العزيز، الجبار، المتكبر، الخالق، البارئ، المصور.\rسورة المعارج فيها: ذو المعارج.\rسورة المدثر فيها اسم واحد: أهل التقوى وأهل المغفرة.\rسورة سبِّح فيها اسم واحد: الأعلى.\rسورة القلم فيها اسم واحد: الأكرم.\rسورة التوحيد فيها اسمان: أحد، صمد).\rوقد زاد بعض علمائنا فيها: (شيء، موجود، كائن، ثابت، نفس، عين، ذات، داع، مستجيب، مصلٍّ، قائل، متكلم، مبقٍ، مفنٍ، غيور، قاضٍ، مقدِّر، فرد، مُبْلٍ، جاعل، موجد، مبدع، ذارئ).\r"], [172, "قلتُ: ومن هذا ما جاء على لفظه في كتاب الله وسنة نبيه، ومنها ما أخذه من فعل، ومنها ما جاء مضافاً فذكره مجرداً عن الإضافة، وكذلك وجدناه في سائر الأسماء المتقدمة.\rوَهَمٌ:\rقال بعض المتأخرين: (وقد جرت عادة الحكام في تغليظ الأيمان وتوكيدها إذا أحلفوا الرجلَ لخصمه أن يقولوا: بالله الطالب الغالب المهلك المدرك، وليس شيءٌ من هذا يستحق أن يُطلق في باب صفات الله تعالى، وإنما استحسنوا ذكرها في الأيمان ليَردعوا بها الحالف عن تَقَحُّمِ الباطل).\rتنبيه:\rأما قوله: (قد جرت عادة الحكام)، فليس كما قال، بل سبق بذلك قول السلف من الفقهاء والتابعين قبلهم، حتى قال الشافعي: (إنه يُغلَّظ بذلك)، وعيَّن هذه الألفاظ، فدلَّ على أنها كانت عندَهم حينئذ معهودةً.\rوأما قوله: (وليس شيء من هذا يستحق أن يُذكر في صفات الله)، فلغوٌ، بل ذلك جائز في ذكره لا في باب التعديد للتسعة والتسعين، ولكن في باب التعظيم لله والإخبار عن جلاله وعظيم أفعاله.\rوقوله: (وإنما استحسنوا ذكرَها في الأيمان ليقع بها الردعُ)، دليلٌ على ما قلناه، وأنه لا يقع الردع إلا بغاية التعظيم لله سبحانه، وبحسب قصد التعظيم واللفظ الدالِّ عليه يكون الزجرُ فيه.\r"], [173, "الفصل الثاني:\r"]], "pg": [161, 173]}, "561.3": {"x": [[173, "في الآيات الواردة في هذا الباب\rاعلموا - وفقكم الله - أنه كان من حقنا أن نبدأ بالآيات قبل الأخبار، ولكنا أخرناها عنها لثلاثة أوجه:\rأحدها: أن الآي مجملة والأخبار مفسَّرة، والبداية بذكر المجمل وإن كانت معتادة في الترتيب، لكن ذكرُ الآي هاهنا عارض، وهذا إنما يكون في المقاصد.\rالثاني: أن الأخبار تأتي في الأسماء للحاجة إليها فيها، فلذلك أفردنا الآيات وتعدادها وذكرناها بعدها.\rالثالث: أنا ذكرنا الأخبار لتمهيد سبيل البيان، وتحقيق مقاصد الكتاب أولاً، وبعد ذلك يأتي ذكرُ ما يُفتقر إليه، إن شاء الله تعالى.\rالآية الأولى: قوله تعالى: {وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا وَذَرُوا الَّذِينَ يُلْحِدُونَ فِي أَسْمَائِهِ} [الأعراف: 180].\rوفيها عدة مسائل، مقصدنا منها هاهنا ثماني مسائل:\r"], [174, "المسألة الأولى: سبب نزولها\r"]], "pg": [173, 174]}, "561.4": {"x": [[174, "روي أن المشركين سمعوا المسلمين يدعون الله مرة، والرحمن مرة، والقادر مرة، فقالوا: ينهانا عن عبادة الأصنام وهو يدعو آلهة كثيرة، فنزلت: {وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا}.\rالمسألة الثانية: قوله: {الأَسْمَاءُ الْحُسْنَى}\r"]], "pg": [174, 174]}, "561.5": {"x": [[174, "فيها ثلاثة أقوال:\rالأول: قال بعض علمائنا: في ذلك دليلٌ على أن الاسم هو المسمى، لأنه لو كان غيرَه لوجب أن تكون الأسماء لغير الله.\rالثاني: قال آخرون منهم: المراد به التسميات، لأنه سبحانه واحدٌ، والأسماءَ جمعٌ، فلا بد من صرف اللفظ عن ظاهره إلى المجاز، ومعناه: ولله التسميات، إذ لا يجوز أن يكون للذات الواحدة إلا اسم واحد، ولا تكون لها أسماء كثيرة على الحقيقة إلا على معنى التسميات، كالذِّكر والمذكور.\rالثالث: قال آخرون منهم: المعنى: ولله الصفات، وكل اسم لله صفة له، ثم ينقسم إلى ما يقال فيه: هو هو، وإلى ما يقال فيه: هو غيره، وإلى ما لا يقال فيه: إنه هو ولا غيرُه، على ما يأتي بيانُه.\r"], [175, "المسألة الثالثة: ما هي هذه الأسماء؟\r"]], "pg": [174, 175]}, "561.6": {"x": [[175, "وفي ذلك ثلاثة أقوال:\rالأول: أنها أسماء الله كلها التي فيها التعظيم والإكبار.\rالثاني: أنها أسماؤه التسعة والتسعون التي ذكرها النبي صلى الله عليه وسلم.\rالثالث: أنها الأسماء التي دلت عليها دلائل التوحيد، وهي سبعة: الموجود، القادر، العالم، السميع، البصير، المريد، الحي، المتكلم.\rوعلى هذا بنينا القول في كتابنا هذا، وكل اسم إلى هذه رددناه، وبها نُطناه وعقَدناه.\rالمسألة الرابعة: ما معنى وصفها بالحسنى؟\r"]], "pg": [175, 175]}, "561.7": {"x": [[175, "فيه خمسة أقوال:\rالأول: أن معنى وصفها بذلك ما فيها من العلو والتعظيم والتقديس والتطهير، فكل أمر معظم يسمى به.\rالثاني: أن وصفها بالحسنى ما وَعَدَ فيها من الثواب عند الذِّكر للعبد، وجزيل العطاء عند التوسل بالدعاء.\rالثالث: ما مالت إليه القلوب من الرحمة والكرم والعَفو.\rالرابع: أن حُسنها شرفُ العلم بها، فإن شرفَ العلم إنما هو بشرف المعلوم، والله سبحانه أشرف الموجودات، وقد تكلمنا في الحُسن في كتاب\r"], [176, "المقسط بما فيه مَقنعٌ عظيم، وبينا وجوه إطلاقاته ومعانيه، ومن حصّل الحُسْنَ من آحاد هذه المعاني فقد أخذ بحظ وافر منها كفاه، ومن حصل حُسنها كلها أناله الغاية من الثواب ووفاه.\rالخامس: أنه معرفة الواجب في وصفه، والجائز في نعته، والممتنع المحال في حقه، والعقول محجوبة عن الهجوم عليه، والشرع دليل مرشد إليه، فإذا نبّه الشرع الغافلَ، وذكّر الذاهل، دل العقلُ عليه للعرفان في الجملة، وكمّل الشرعُ البيان، فنحن نقفُ عند بيانه، وبيانُه على أقسام، يأتي ذكرُها إن شاء الله.\rالمسألة الخامسة: ما معنى قوله: {فَادْعُوهُ بِهَا}؟\r"]], "pg": [175, 176]}, "561.8": {"x": [[176, "والدعاء لا يكون إلا بعد المعرفة بالمدعوّ، فبها يُعرف، وبها يُدعى، وفي ذلك ثلاثة أقوال:\rالأول: تعظيمنا له بذكر صفات التعظيم، وذلك عبادة.\rالثاني: الرغبة إليه بذكر وجه الرغبة بما يليق بها من الأسماء، كسؤال الرحمة بالرحيم، والكفاية بالكافي، والهبة بالوهاب، وما في معنى ذلك كله من الرغائب ومتعلقاتها من الأسماء.\rالثالث: أن الله سبحانه تعرف إلى أوليائه بصفاته وأسمائه، إذ لا يمكن أن يُعرف إلا كذلك، فبيّن لهم الواجبَ والجائز من ذلك، وعرّفهم بما يستحيل\r"], [177, "عليه، وذلك لأن العقول مجوبة عن جلاله، ممنوعة عن إدراكه، فآذن الله سبحانه بالأسماء عبادة نفسه، وأذن لهم فيها، وجعلها طريقاً إلى المعرفة، ووسيلة في الرغبة والطلبة، فلذلك اقتصرنا على ما أذن فيه، ولم نتعدّه إلى غيره.\rالمسألة السادسة: قوله تعالى: {وَذَرُوا الَّذِينَ يُلْحِدُونَ "]], "pg": [176, 177]}, "561.9": {"x": [[177, "فِي أَسْمَائِهِ}\rفيه قولان:\rالأول: أنه منسوخ بآية القتال.\rالثاني: أنه تهديد.\rوهذان القولان وهم، أما النسخ فلا يصح فيه، لأن الجزية يبذلون على ذلك، والرق يُضرب عليهم معه، وأما التهديد ففاسد جداً، لأن الخطاب لنا دونهم، فكيف نُهدَّد على فعلهم، وإنما يكون التهديد للفاعل خاصة.\rوالصحيح أنه أمر صريح لنا بنبذ عقيدتهم والتبري من قولهم.\rالمسألة السابعة: قوله {يُلْحِدُونَ}\r"]], "pg": [177, 177]}, "561.10": {"x": [[177, "فيه ثلاثة مقاصد:\rالأول: تصريفه لغة:\rقال الكسائي: (ألحد: مال، وَلَحَدَ: رَكِنَ)."], [178, "الثاني: ألحد: مارى وجادل، ولحد: مال، وقيل: هما بمعنى واحد، وهو الصحيح عندي.\rالمقصد الثاني: في معناه:\rإذا ثبت هذا، فالإلحاد: هو العُدول والمَيل، فكل مائل لاحد.\rالمقصد الثالث: في وجوه الإلحاد:\rوالإلحاد على ستة أوجه:\rالأول: التكذيب.\rالثاني: التشريك.\rالثالث: الزيادة على ما أُذِنَ فيه - على ما يأتي تفسيرُه - وذلك تشبيه.\rالرابع: النقصان منه، وذلك تعطيل.\rالخامس: تغييرها لفظاً.\rالسادس: تغيير تأويلها وتفسيرها.\rالمسألة الثامنة: [في معنى الحُسن في أسماء العباد]\r"]], "pg": [177, 178]}, "561.11": {"x": [[178, "إذا علمتم الحُسن في أسماء الله تعالى فاعلموا الحسن في أسمائكم، وذلك بخمسة أوجه:"], [179, "الأول: أن يسمى المرء بأسماء الأنبياء والصالحين، وقد روى المغيرة بن شعبة قال: (لما قدمتُ نجران سألوني فقالوا: إنكم تقرؤون {يَا أُخْتَ هَارُونَ} [مريم: 37]، وموسى قبل عيسى بكذا وكذا، فلما قدمتُ على رسول الله صلى الله عليه وسلم ذكرتُ له ذلك فقال: إنهم كانوا يسمون بأسماء أنبيائهم والصالحين قبلَهم).\rالثاني: أن يسمى بكل اسم يوافق المقاصد الجائزة والأغراض المستحبة، ويجتنب الألقاب المستهجنة والأسماء المستكرهة، فقد روي أن النبي صلى الله عليه وسلم قال لرجل: (ما اسمك؟ قال: مُرة، فأعرض عنه، وقال لآخر: ما اسمك؟ قال: يعيش، قال: احلُب). وروي أن ابنة لعمر كان يقال لها عاصية، فسماها رسول الله صلى الله عليه وسلم جميلة.\r"], [180, "الثالث: أن يعدل عن الأسماء التي فيها تزكية النفس، فقد روي أن زينب بنت أبي سلمة قالت: (سُميتُ بَرَّةً، فقال رسول الله صلى الله عليه وسلم: لا تزكوا أنفسكم، الله أعلم بأهل البِر منكم، فقالوا: بم نسميها؟ قال: سموها زينب).\rالرابع: أن الله تعالى كما أوجب لأسمائه الوصف الحسن، فلقد أحسن أسماءنا سبحانه بأن سمانا المؤمنين والمسلمين، والتائبين والعابدين، والحامدين والسائحين، وكل اسم فاضل وخطط كريمة وهبها لنا.\rالخامس: وهو الأشرف والأعظم، أن جعل أسماءنا من أسمائه، فسمانا المؤمنين من المؤمن، والعالمين من العالم، والشاهدين من الشهيد، وكذلك كل اسم وصفنا به مما وصف به نفسه، وهذه رتبة عظيمة لا يوازيها شيء، وهو أن يتفق العبدُ والمولى في لفظ الاسم، ولكن المعنى مختلف كما يأتي بيانه في كل اسم إن شاء الله تعالى.\rالآية الثانية: قوله تعالى: {تَبَارَكَ اسْمُ رَبِّكَ ذِي الْجَلَالِ وَالْإِكْرَامِ} [الرحمن: 77]\rفيه ثلاث مسائل:\rالمسألة الأولى: قوله: {تَبَارَكَ}.\r"]], "pg": [178, 180]}, "561.12": {"x": [[180, "الثانية: قوله: {اسْمُ رَبِّكَ}.\rالثالثة: قوله: {ذِي الْجَلَالِ وَالْإِكْرَامِ}.\r"], [181, "المسألة الأولى: في قوله: {تَبَارَكَ}.\r"]], "pg": [180, 181]}, "561.13": {"x": [[181, "وفيه للعلماء أربعة أقوال:\rالأول: تقدَّس، قاله الفرَّاء.\rالثاني: تعاظم.\rالثالث: تفاعل من البركة، وهي الزيادة في النفع، ومنه قوله: {وَجَعَلَنِي مُبَارَكًا} [مريم: 30]، معناه نفاعاً للخلق، قاله الزجاج.\rالرابع: تبارك: دام، مأخوذ من برك البعير، وهو إذا لزِق بالأرض، ومنه: مبارك الإبل، أي مواضعها التي تستقر فيها.\rفأما القولان الأولان فلا يشهد لهما النقل ولا الاشتقاق، وأما القولان الآخران فصحيحان فيه، فإنه يصح أن يقال: إنه من البركة التي هي النفع والخير، ويصح أن يقال: إنه من البُروك الذي هو الثبات والدوام، فإذا كان من البركة الذي هو النفع كان من صفات الأفعال، كقولك: خلق ورزق، وإن قلنا: إنه من البروك الذي هو الدوام كان عبارة عن صفات الذات، ورجع إلى الباقي الذي لا يفنى، وكلاهما صحيح في وصفه تعالى، واجب له.\rالمسألة الثانية: في قوله: {اسْمُ رَبِّكَ}.\r"]], "pg": [181, 181]}, "561.14": {"x": [[181, "وقد اتفق علماؤنا - رحمة الله عليهم - على أن قوله: {اسْمُ} صلة في الكلام، والمعنى: تبارك ربك، إذ لا يصح أن يكون هذا المعنى المعبَّر عنه بتبارك إلا لله سبحانه.\r"], [182, "قال الإمام الحافظ رضي الله عنه: هذا ضَيْقُ نطاق عن تحقيق المعاني، ومن الحق عليكم أن تعلموا أن معنى قولهم في الاسم صلة أي زيادة، وكيف يصح أن يقال فيه: إنه زيادة، وما تقدم من تفسير التبارك بالأقوال الأربعة المتقدمة يصح أن يكون مضافاً إلى اسم الله سبحانه، مخبَراً به عنه، ولا يكون الاسم صلة في الكلام ولا زيادة فيه، فإن اسم الله تعالى الذي يُذكَر به حقه أن يُقدَّس ويعظم، وينزه ويكرم، ويؤمن به ولا يلحد فيه، كما أن الرب يستحق ذلك سبحانه، واستحقاق أسمائه لذلك إنما هو لحرمتها بكونها أسماءً له، وحق أسماء الله تعالى أن يضاف إليها النفع والبركة، فكل شيء أضيف إليها وأخبر عنه قبلُ بها، وَقُدِّمَ بين يدي ذكره ذكرُها، فإنه مبارك فيه، مجتلبٌ إن كان خيراً مرجواً، مدفوعٌ إن كان شراً متوقعاً.\rوحق أسماء الله أن يكون تعظيمُها والإيمان بها وحرمتها وجلالها ثابتاً دائماً لا ينقطع ولا يذهب، فقد صح معنى التبارك فيها على الأقوال الأربعة، فلأي شيء يُقضى بكون الاسم صلةً فيها؟\r"], [183, "نعم، ويكون ذلك أقوى في إضافة هذه المعاني لله سبحانه، لأنه إذا كان اسمه يستحق ذلك لحُرمته، فهو سبحانه باستحقاق ذلك في ذاته أولى وأحرى، وهذا بيّن عند الإنصاف.\rفإن قيل: فهلا قلتم: إن معنى قوله: {اسْمُ}: ربُّك، لأن الاسم هو المسمى على ما استقر من قول العلماء، فسيأتي الجواب عنه إن شاء الله تعالى.\rالمسألة الثالثة: في قوله تعالى: {ذِي الْجَلَالِ وَالْإِكْرَا"]], "pg": [181, 183]}, "561.15": {"x": [[183, "مِ}\rقد قرأها ابن عامر: ذو الجلال، بالرفع، عائداً به على الاسم، وقرأت الجماعة بالخفض، عائداً به على الرب تعالى، فإن قلنا بالخفض عائداً على الرب فسيأتي شرحه في باب شرح الجليل والكريم، وإن قلنا فيه برفع (ذو) عائدين به على الاسم فهو صحيح، على ما بيّناه\r"], [184, "من وجوب الجلال للاسم والكرامة بلا خلاف بين المؤمنين، وبإصفاق من أدلة العقول.\rالآية الثالثة: قوله: {سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى} [الأعلى: 1]\rقال علماؤنا - رحمة الله عليهم -: قوله: {اسْمَ} صلة، والمعنى: سبِّح ربَّك، وإنما قالوا ذلك لاعتقادهم أن التسبيح والتنزيه لا يصح إضافته إلى اسم الله، وقد بينا صحة إضافة التقديس والتنزيه إلى اسم الله تعالى كما يُضاف إليه، بل حققنا وجوبه، وبهذا التبيين لذلك والتبين لهلا يبقى إشكال فيه لمنصف.\rوأما قوله: {سَبِّحِ} فهو باتفاق من العلماء: نزِّه وقدِّس.\rوقال بعض المتأخرين: معنى سبح: اسبَح بقلبك في بحار ملكوته، مأخوذ من قوله: {فِي فَلَكٍ يَسْبَحُونَ} [الأنبياء: 33]، و {إِنَّ لَكَ فِي النَّهَارِ سَبْحًا طَوِيلًا} [المزمل: 6].\r"], [185, "والذي أراه فيه - بعد طول لا يحتمله هذا الكتاب - أن قوله: {سَبِّحِ} وسبحان الله اسم موضوع للتقديس والتنزيه غير مشتق من شيء، ولا مجتمِع مع غيره في معنى، والله أعلم.\rالآية الرابعة: قوله تعالى: {هَلْ تَعْلَمُ لَهُ سَمِيًّا} [مريم: 65]\rوفيه ثلاثة أقوال:\rالأول: هل تعلم له نظيراً.\rالثاني: هل تعلم أحداً تسمى باسمه، المعنى: هل تعلم أحداً تسمى اللهَ غيرُه؟\rالثالث: هل تعلم أحداً يستحق من الصفات ما يستحقه الله تعالى.\rوهذه الأقوال كلها صحيحة مجتمعة، فإنه تعالى ليس له نظير في ذاته، ولا في صفاته، ولا في أسمائه. أما الله فلا يسمى به أحد سواه، وأما غيره من الأسماء فإن تسمى به أحد - بإذنه تعالى في ذلك له - فإنه يُفارقه في المعنى؛ بأن يكون لله تعالى في معناه المنزلة العليا وللعبد السفلى، على ما يأتي بيانُه في كل اسم منها، إن شاء الله تعالى.\r"], [186, "الفصل الثالث: في الاسم الأعظم\r"]], "pg": [183, 186]}, "561.16": {"x": [[186, "وكان الذي دعانا إلى تقييد هذا الفصل، وحدانا نحوه، ما روى بريدة عن النبي صلى الله عليه وسلم أنه سمع رجلاً يقول: (اللهم إني أسألك بأنك الله الذي لا إله إلا أنت، الأحد الصمد، الذي لم يلد ولم يولد، ولم يكن له كفواً أحد، فقال: لقد دعا الله باسمه الأعظم الذي إذا دُعي به أجاب، وإذا سُئل به أعطى).\rوروي عن أنس بن مالك قال: (دخل النبي صلى الله عليه وسلم المسجد ورجل قد صلى وهو يدعو، وهو يقول في دعائه: اللهم لا إله إلا أنت، الحنان، بديع السماوات والأرض، ذو الجلال والإكرام، فقا النبي صلى الله عليه وسلم: أتدرون بما دعا الله؟ دعا الله باسمه الأعظم؛ الذي إذا دُعي به أجاب، وإذا سُئل به أعطى).\r"], [187, "وورد في بعض الآثار أن: (اسم الله الأعظم: الله لا إله إلا هو الحي القيوم).\rوقد ورد معناه في الصحيح كما يأتي إن شاء الله تعالى.\rوفيه مسألتان:\rالمسألة الأولى: في معنى تسميته بأنه أعظم.\r"]], "pg": [186, 187]}, "561.17": {"x": [[187, "الثانية: في تعيينه.\rأما المسألة الأولى: في معنى تسميته بذلك\rفنقول - وبالله التوفيق -: إنه يحتمل أن يكون تعيينُ هذا الاسم بصفة الأعظم لمعانٍ خمسة:\rأحدها: الاختصاص به، ومنعُ الغير أن يُشارَك في التسمية به.\rالثاني: عموم معانيه، وكثرة متعلَّقاته.\rالثالث: عظيم ثوابه.\rالرابع: لزوم الإجابة له.\r"], [188, "الخامس: عدم معرفته وتعاليه عن الإحاطة به.\rأما الأول: وهو قِسم الاختصاص، فإن أسماء الله تعالى على قسمين:\rأحدهما: ما يجوز التسمي به، على ما تقدم.\rالثاني: ما لا يجوز التسمي به لأحد من الخلق، وهما اسمان: الله، والرحمن.\rفأما الرحمن: فإنه وإن كان لا يجوز لأحد أن يسمى به، فقد تعدى بعض الكفرة فتسمى به مضافاً، فإنه كان يقال لمسيلمة: رحمان اليمامة.\rوأما قولك: (الله)، فإن الله مَلَكَ القلوب والألسنة عنه، فلا يجوز لأحد أن يتسمى به شرعاً، ولا يوجد ذلك لأحد من الخلق تعدياً، فهو أعظم بهذا المعنى.\r"], [189, "وأما الثاني: وهو قسم العموم وكثرة المتعلقات، فليس في أسماء الله تعالى أكثر متعلَّقاً ولا أعم مقتضى من قولك (الله)، فإن جميع الأسماء تدخل فيه، ولفظه يضم معناها ويقتضيه.\rفإذا قيل: من الرب؟ من الملِك؟ من القدوس؟ من الخالق؟ من الوهاب؟ فالجواب في جميع ذلك (الله)، فإليه منتهى التفسير، وهو غاية السائل في الجواب، وإليه يرجع كل من يَعبد سواه، ولذلك قال تعالى: {وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ} [لقمان: 24].\rوأما الثالث: وهو عِظَمُ الثواب، فلا ثواب أعظم من الثواب على ذكر الله بقولك: (الله). لقد روي عن النبي صلى الله عليه وسلم أنه قال لأبي بن كعب: (أَيُّ آية في كتاب الله أعظم؟ فقال: {اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ}، فقال: ليَهْنِئْكَ العلمُ يا أبا المنذر)، وقد بدأ الله كتابَه من جملة أسمائه فقال: {الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ} [الفاتحة: 1]، واختتمه به من جملة أسمائه فقال: {قُلْ أَعُوذُ بِرَبِّ النَّاسِ. مَلِكِ النَّاسِ. إِلَهِ النَّاسِ} [الناس: 1 - 3].\rوأما الرابع: وهو لزوم الإجابة له، ففي ذلك آثار كثيرة، منها: قوله تعالى: {فَنَادَى فِي الظُّلُمَاتِ أَن لَّا إِلَهَ إِلَّا أَنتَ سُبْحَانَكَ} [الأنبياء: 86]، فاستجاب له، ومنها: الحديث الذي رويناه أيضاً في قول القائل: (اللهم إني أسألك بأنك الله\r"], [190, "الذي لا إله إلا أنت، فقال النبي صلى الله عليه وسلم: إنه اسم الله الأعظم)، ثم فسر العظيم بأنه إذا دُعي به أجبا، وإذا سُئل به أعطى.\rوأما الخامس: وهو قسم عدم المعرفة به، فإنه مبني على أصل وهو:\r"], [191, "الفصل الرابع:\r"]], "pg": [187, 191]}, "561.18": {"x": [[191, "وهو أنه هل يجوز أن يكون لله سبحانه اسمٌ استأثر بعلمه لم يُطلع عليه أحداً من خلقه أو لم يُطلعنا عليه وقد علمَه غيرُنا؟\rوقد اختلف فيه علماؤنا - رحمة الله عليه - على قولين:\rفقال أكثرهم: لا ننكر أن تكون لله سبحانه أسماءٌ قد استأثر بها، لم يطلعنا عليها، ولا وصلت إلينا.\rوقال بعضهم: كل اسم لله تعالى حَسُنَ وصفُه به فقد أخبرنا به ودلنا عليه. وتعلق الأكثرون بأدلة:\rأحدها: ما روي عن النبي صلى الله عليه وسلم أنه كان يقول في سجوده: (لا أحصي ثناءً عليك، أنت كما أثنيتَ على نفسك).\r"], [192, "ثانيها: ما روي عنه أيضاً صلى الله عليه أنه قال: وذكر حديث الشفاعة: (فأخِرُّ ساجداً بين يدي ربي، فأحمدُه بمحامد يعلمنيها حينئذ لا أعلمها الآن).\rثالثها: ما روي أن النبي صلى الله عليه وسلم كان يقول: (اللهم إني عبدك، ابن عبدك، ابن أمتك، ناصيتي بيدك، ماضٍ في حكمك، عدل في قضاؤك، أسألك بكل اسم سميت به نفسك، أو أنزلته في كتابك، أو علمته أحداً من خلقك، أو استأثرت به في علم الغيب عندك)، الحديث إلى آخره.\rوالصحيح عندي أنه ليس له اسم ولا صفة إلا وقد اطّلع عليه رسول الله صلى الله عليه وسلم، ألم تعلموا أنه قد أطلع على ملكوت السماوات والأرض، والجنة والنار، وبلَغ موضعاً سمع فيه صريف الأقلام، وعاين التقدير والتدبير، ومقامات الملائكة تحت القهر والتسخير.\rوقد صحح الله العقول فينا، ونصب الآيات والأعلام، ونبّه على الأدلة، وعلّم سداد النظر وجريان الفِكَرِ، واستفاد بذلك الموفَّقون معرفةَ الله تعالى بأسمائه الحسنى، وصفاته العُلى، وأفعاله العُدلى؛ التي لا يمكن في العقل\r"], [193, "الإخلال بشيء منها، ولا يُتصور على جميع العالمين خفاؤها، وقد تقررت فصولها، وصحت فروعها وأصولها، واستقامت في العقائد متعلَّقاتها وأحكامُها، فعلِم الخلقُ أنه تعالى: موجود، عالم، قادر، حي، مريد، بديع، سميع، بصير، متكلم، وليس بعد ذلك اسمٌ إلا يرجع إليها، ولا حكمٌ إلا يتعلق بها، حسبما نبينه بعد.\rولو فرضنا للباري تعالى صفة أو اسماً من الأصول لم نطلع عليه لم نثق بما علمنا، ولا كان لنا اعتدادٌ بما عقلنا، وإنما الذي يصح في تأويل هذه الأخبار التي تقدَّم احتجاجُ علمائنا بها؛ أن الثناء والحمد يكون بمحامد وأدعية تعود كلها إلى هذه الأصول، كما أنه قد يعلم العالمُ أدعيةً ويتحقق ثناءً وذِكراً، ثم يأتيه بعد ذلك مأثورٌ من دعاء وثناء يقع منه موقعَ استحسان، ويرى فيها وجوهاً من المحامد لم تكن عندَه، ولكنها راجعةٌ بالمعاني إلى ما سبق لديه، وهذا كافٍ على هذا الاختصار في هذا الغرَض، والله الهادي للبيان لا رب غيرُه.\rالمسألة الثانية: [في تعيين الاسم الأعظم]\r"]], "pg": [191, 193]}, "561.19": {"x": [[193, "إذا ثبت هذا وقلنا في أحد الأقسام: إن معنى تسميته بأنه أعظم: عدمُ المعرفة به، فوجه تسميته في ذلك بأنه أعظم أنه عظُم عن إدراكه، وجل عن إحاطة الخلق به وتعيينه، وهو الذي رآه بعضُ علمائنا واعتقده، أن اسم الله الأعظم مخبوءٌ في جملة الأسماء كليلة القدر في ليالي رمضان، وساعة يوم\r"], [194, "الجمعة في ساعات اليوم، على ما يأتي بيانه في اللواحق إن شاء الله، واحتج على ذلك بوجهين:\rأحدهما: أن الرواية قد اختلفت عن النبي صلى الله عليه وسلم في اسم الله الأعظم عن بُريدة وأنس كما تقدم، ولو كان معيَّناً ما اختلف نقلُه.\rثانيهما: أنه قال: (إذا دُعي به أجاب، وإذا سُئل به أعطى)، وقد نرى من يسأله بالله وبما رُوي في الحديث ولا تكون إجابة.\rوالجواب عنه من وجهين:\rأحدهما: أنا نقول: إن الرواية وإن اختلفت عن النبي صلى الله عليه وسلم في ذلك، فإنما جاء الاختلاف في الأوصاف والتوابع، كقولك: (الله)، مع الاتفاق على الابتداء بالله وبلا إله إلا الله.\rجواب آخر: وأما قوله: إنا نرى الداعي يدعو به ولا يُستجاب له، فبيانُه في تأويل قوله: {أُجِيبُ دَعْوَةَ الدَّاعِ} [البقرة: 185]، في كتاب المُشكلَين.\rوالتحقيق فيه: أن الإجابة تكون بوجوه:\rمنها: تعيين ما سأله فيه، وذلك بشروط، ومنها: بالتعويض عما طلب، ومنها: بالادخار على ما جاء في الحديث.\r"], [195, "وفي هذا الفصل بدائع في كتاب المشكلين، نفع الله به بعزته.\rوأما الخبر المروي وهو قوله صلى الله عليه وسلم: (لله تسعة وتسعون اسماً من أحصاها دخل الجنة، الله وتر يحب الوتر)، فإنه حديث صحيح بديع، فيه فصول تأتي مفسرة في مواضعها، والمقصود منها ها هنا ثلاثة فصول:\rالفصل الأول:\r"]], "pg": [193, 195]}, "561.20": {"x": [[195, "إن هذا الحديث فيه إثبات هذه الأسماء، وليس فيه نفيُ ما عداها، والدليل عليه أن هذا الكلام هو قضيةٌ واحدة لا قضيتان، ومعنى ذلك أن خبر إن - وهو الفائدة - في قوله: (من أحصاها)، فكأن الباري تعالى أراد أن يعرِّف عبادَه أن التسعة والتسعين إذا أحصيت أورثت الجنة، لا أن يعرف أن له تسعاً وتسعين اسماً خاصة، كقولك: لزيد ثوبان حسنان للجمعة، لا يمنع أن يكون له غيرُهما، والدليل القاطع وُجدانُنا له نيفاً على مائة اسم.\rفإن قيل: ليست تلك أسماءً، وإنما هي صفات، قلنا: عن هذا خمسة أجوبة:\rالأول: أن نقول: دعنا من تَمْرَتان، هذا كلام الجهل والخِذلان، والسخفاء من النسوان والولدان، والطلبة من المنتسبين إلى معرفة اللسان، فخذ هذا من عالم بالوجهين، واعلم أن الاسم والصفة وإن اختلفا في اللفظ والاشتقاق فهما في المقصد واحد، والدليل القاطع عليه قوله: {بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ}، فجعلها أسماءً، وهي كلها أو منها مشتقة قطعاً، جارية على الفعل لفظاً ووروداً، وهذا لا يفهمه إلا ريانُ من اللغة والأصول.\r"], [196, "الثاني: تعديدها تسعة وتسعين اسماً، وهو سبحانه واحد، وقد تقدّم ذلك في قوله: {وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى}.\rالثالث: قوله: (من أحصاها)، وفيه لغتان:\rالأولى: أحصاها، مهموزة اللام، ومعناه: أعلمَ غيرَه بها مستوفاة كاملة.\rالثانية: أحصاها، غير مهموزة اللام، وفيه خمسة تأويلات:\rالأول: عدَّدها.\rالثاني: أطاقها، يعني عمل بها.\rالثالث: علِمها، من الحصاة؛ وهي العقل، قال طَرَفَةُ:\rوإن لسان المرء ما لم تكن له ... حصاةٌ على عوراته لَدليلُ\rالرابع: أن يقرأ جميع القرآن حتى يختمه، فإنه مشتمل عليها قطعاً، ولذلك عددناها قرآنية لنستوفي جميعَها.\rالخامس: حفظها، كما روي في الصحيح: (لا يحفظها عبد مسلم إلا دخل الجنة)، واختُلف فيه: فقيل: معناه حفظها بالاعتقاد الحسن والعمل الصالح، وقيل: المراد به علمها مفصَّلةً.\r"], [197, "والصحيح عندي: أن المراد به مَن علمها، وكل عالم عادٌّ، وكل عاد عامل، فتكمل له الفائدة، أو غير عامل فتنقص، وكل عامل مفيد سواه أو غير مفيد، فيُنمى فضله ويَتعدى، أو يقف فلا يتحدى، والحمد لله على ما أنعم به من الهدى.\rوباقي أسئلة الحديث يأتي في اللواحق عند أقصى المدى إن شاء الله تعالى، فمن أراد جمعَها فليؤلِّفْها من الموضعين، ومن راعى الترتيب نزَّلها في المنزلتين، والله الموفق برحمته.\r"], [198, "الفصل الخامس: في بيان مآخذ أسماء الله وصفاته\r"]], "pg": [195, 198]}, "561.21": {"x": [[198, "اعلموا - وفقكم الله - أنه قد استقر في عقائد أهل السنة أن العقل لا يقتضي لله عبارةً باسم ولا صفة، وإنما طريق ذلك الشرع، إذ لا حكمَ للعقل إلا في الحقائق والمعاني، فأما العبارات فإنما طريقها السمع، وقد بينا ذلك في كتاب المتوسط والمقسط وغيرهما، ودللنا عليه بما يوضح أن العقل يقتضي الحقائق والمعاني، والسمع يدل على الألفاظ والعبارات، فأغنى ذلك عن إعادته.\rوقد جرى بين شيخ السنة أبي الحسن رضي الله عنه وبين الجُبَّائي في ذلك كلام، وذلك أن الجبائي قال: أصف الباري بأنه جوادٌ ولا أصفه بأنه سخي، قال له الشيخ أبو الحسن: لم كان ذلك؟ قال: لأنه مأخوذ من قولهم: أرض سَخاوية: إذا كانت سهلةً ليّنة.\rقال: فقلت له: ولا تقل أيضاً إنه جواد، لأنه مأخوذ من قولهم: فرس جواد: إذا كان واسع الخطو.\r"], [199, "وكذلك قال الجُبائي: إن البارئ لا يوصف بأنه موقِن، وإن وُصف بأنه عالم، قال: لأن اليقين علم يزول به الشك، وعلم الله تعالى لم يُزل شكاً.\rفقال له الشيخ أبو الحسن: فلا تقل أيضاً إنه عالم، لأن العالم هو الذي يجوز أن يشكَّ فيما علم بزوال علمه، أو يكون علمُه بعد شك، ولا يمكن الفصلُ بين الأمرين إلا بما يرجع القول فيه عليه.\rوهذا يدل على أن أسماءه تعالى وصفاته إنما أخذت توقيفاً ووحياً، إلا فيمن لا يُحسن ذلك لعُجمة لسانه؛ فيدعوه بما يعظِّمه في لغته لضرورة العجز، وهذا إجماع.\rبديعة:\rكل ما تقدم ذكره من حصر مدارك أسماء الله تعالى وصفاته في مورد التوقيف وسبيل الوحي فإنما ذلك فيما طريقُه الإثبات، كقولنا: عالم، وقادر، وحيّ ونحوُه، فأما باب النفي فلا يحصره ضبط، وإنما هو مطلق العبارة في كل مستحيل على الله تعالى، فنقول: إنه ليس بكذا في كل معنى لا يجوز عليه، وليس لذلك ضبطٌ يحويه، إلا أن نقول: إنما ننفي عنه ما يؤدي إلى حدثه\r"], [200, "أو حدث معنى فيه، أو قلبه عن حقيقته، أو التشبيه بخلقه، أو تكذيبه في خبره، أو تجويره في فعله.\rمزيد تحقيق:\rقال علماؤنا: لم يخفَ على ذي لُبٍّ أن دلائل العقل تقتضي للرب تعالى صفاتٍ لا بد من كونه عليها، ولا غنىً بنا نحن عن إثباتها له.\rقلت: هذا إنما كان يصح لو خلا عقلٌ عن توقيف ووحي، وإلا فالذي أعتقده أن العقول قاصرةٌ لا تستقل بذواتها في إدراكها لصانعها على التفصيل؛ حتى يُمدَّها الله بنوره على ألسنة رسله، فبعد ذلك يظهر ما لها بدركه استقلال، دون ما لا بد من تعريفه به ابتداءً، وقد بينا ذلك في عدة مواضع.\r"], [201, "القطب الثاني:\rفي ذكر السوابق والفواتح المقدِّمة لهذا الكتاب\r"], [202, "ص 202\r"], [203, "السابقة الأولى: [حقيقة الاسم والمسمى والتسمية والوصف والصفة]\rنذكر فيها حقيقة الاسم والمسمى والتسمية والوصف والصفة، فإن علماءنا - رضي الله عنهم - قد بالغوا القول في ذلك، وجاذبوا المخالفين فيه أطراف الكلام، حتى لووا على البيان مُلاءة التحقيق، وعقدوا فيه كل ركن وثيق، وقد تكلمنا على ذلك في كتاب المقسط بما يغني عن إعادته، من شرق حقائق ذلك، واستيعاب الخلاف، وتسطير الأدلة والأسئلة والأجوبة وذكر المختار.\rوأما الآن في هذه الحال فإنما نذكر العقيدة في معرض البيان الكافي للبيب فنقول:\r"], [204, "إن عبارات النحويين والمتكلمين قد اختلفت في ذلك اختلافاً متبايناً، ومدارُ البيان فيه على أربعة معانٍ:\rتسمية، واسم، وَمُسَمِّ، ومسمى.\rفالتسمية: ذِكر المخبر عن المعنى وحده أو صفته أو فعله.\rوالاسم: ما به ذُكِرَ وَعُبِّرَ عن غيره.\rوالمسمى: المراد بالذكر، والمسمى: هو الموصوف بالتسمية أو الفاعل لها.\rويعبَّر عنه من وجه آخر قريب بين بأن يقال:\rإن التسمية هي الخبر عن المعنى، والاسم هو الخبر، والمسمى هو المخبَر عنه، والمسمي هو المخبِر بالخبر.\rوأما الوصف والصفة؛ فإن الوصف قول القائل الدال على المعنى والصفة المعنى المدلولُ عليه بالوصف، فرجع الاسم إلى مدلول ذكر الذاكر، والوصف إلى قول القائل الدال على المعنى، ورجعت الصفة إلى ذلك المعنى المدلول عليه بالوصف.\rومحصوله أن الوصف: الذكرُ الدال على الصفة، والتسمية: الذكر الدال على الاسم، مثاله: زيد قائم، فقولك: زيد: تسمية، وضعُ الزاي والياء والدال\r"], [205, "على هذا الوجه المخصوص والترتيب المعين: تسمية، لأنه قُصد بترتيب هذه الحروف على هذا الوجه ونظمها التعريف بذات زيد، وهي التسمية، وهذا النظم الذي هو الزاي والياء والدال: اسم، ومفهومه المعرَّف به: مسمى، وهو المخبَر عنه.\rوقولك: قائمٌ: وصف، مدلوله صفة لها اسم هو القيام، وصار الوصف قولاً يدل على اسم بزيادة معنى.\rوقد تجرَّد الصفة عن الذات فيخبَر عنها مفردةً، وتقدَّر في العقل متوحِّدة، وذلك العلم مثلاً.\rوقد يدل القول على الاسم والصفة معاً، كقولك: عالم وقائم، فإنه يدل على مسمى له صفة هي أيضاً اسمه، قد تعبِّر العربُ بكل واحد منهما عن الآخر مجازاً لقُربه منه، على عادتها في المجاز.\rيزيدُه تحقيقاً لديك: أن هاهنا خبراً، ومخبَراً عنه، وجهةَ الخبر، ومخبَراً به، ومخبِراً:\r"], [206, "فالخبر: هو الحديث المطلق.\rوجهة الخبر: هي التسمية أو الكُنية أو نحوُها من الألقاب.\rوالمخبَر به: هو الاسم.\rوالمخبَر عنه: هو المسمى.\rوالمخبِر: هو المسمي.\rفهذا لُباب ما نصرناه في كتب الأصول، يدنو من اصطلاح اللغويين والمتكلمين، لئلا تنفِر عنه الطائفتان.\r"], [207, "السابقة الثانية: [هل الاسم هو المسمى؟]\rقال علماؤنا - رحمهم الله - في أن الاسم هو المسمى أم لا، مع سائر الطوائف قولاً كثيراً، وأتعبوا في ذلك خواطرهم، ومن أنصف ولم يتعسف لم يشكَّ في فساد القول بأن الاسم المسمى، فإن لأهل اللغة في ذلك طرقاً رتَّبوها على قوانين العرب، إفسادُها خَبَلٌ، والخروج عنها وَهَلٌ، وعجباً لهم - على جلالة أقدارهم - كيف نازعوا خصومَهم هذه المسألة، وهم - بشهادة الله - في غنى عنها، فإن الذي يُحوِج إلى النظر في هذا المعنى أمران:\r"], [208, "أحدهما: الوقوف على حقيقته.\rالثاني: النظر في فائدته وعاقبته.\rأما الوقوف على حقيقته فليس من مخصَّصات الأصول، وإنما هو نظر عربي، إذ هو من مطلَقات الألفاظ العربية.\rوأما فائدته وعاقبته فليس له في الأصول فائدة ترجى، ولا عاقبة تخشى.\rفإن قيل: بلى، إن فيه كل ذلك؛ أما الحقيقة فإن كل لفظٍ مفيدٍ لا بد له من حقيقة، والنظرُ في تلك الحقيقة من مقتضيات الأصول، وأما فائدته وعاقبته فإذا قلتم: إن الاسم غيرُ المسمى، حكمتم أن أسماء الباري أغيارٌ له، وذلك لا يجوز.\rالجواب: أن كل حقيقة يدل عليها لفظ ليست من خصائص علم الأصول، بل هي مطلوبُ كل علم، وإنما الحقائق التي يختص بها الأصوليون ثلاث: معرفة الجائز والواجب والمستحيل، والتمييز بين ذواتها ومتعلَّقاتها.\rوأما الحقيقة التي بيناها في هذا الباب فلا يُتصور فيها خلافٌ مع الإنصاف.\r"], [209, "وأما ما زعموا من تخوف العقبى في أن تكون الأسماء أغياراً لله تعالى فنحن لم نطلق في كلامنا أن الاسم هو المسمى أو غيره، إنما بينا أمراً وشرحنا معنى، وأوضحنا أن التسمية حقيقة مختصة بذاتها، متميزةٌ عن المسمى وعن الاسم وعن المسمى به والمسمي، وأن كل واحد من هؤلاء متميز عن الآخر بخاصيته وحقيقته.\rفأما النظر في إطلاق الغيرية فباب آخر، ونحن نبين ذلك بياناً شافياً - إن شاء الله تعالى - فنقول:\rإن قال لنا قائل: فهل تقولون: إن الاسم هو غير المسمى؟\rقلنا: أما في حق المحدَث فهو غيره، وأما في حق الباري فلا نطلِقه، وليس ذلك لأمر يرجع إلى الحقائق، وإنما هو لأجل أن أسماء\r"], [210, "الباري تعالى وصفاته لا نقول إنها أغيارٌ له، ولا أنها هي هو؛ لمعنى يرجع إلى حقيقة الغيرية لا لمعنى يرجع إلى الحقائق النفسية، لا يرتبط بشيء من معنى التسميات والمعاني والحقائق الممهدة.\rدستورٌ، وهي:\r"], [211, "السابقة الثالثة: [انتقاد مقالة أبي إسحاق الإسفَراييني في الاسم والمسمى]\rقال أبو المعالي: (قال الأستاذ أبو إسحاق - إمام هذا الفن -: جملةٌ\r"], [212, "في الاسم والتسمية والمسمى يتدرب بها المسترشد، ويتفطن لمدارك الحقائق، قال:\rكلامنا يدور على التسمية والاسم والمسمى، فإذا قال الله تعالى: كلامي صدق، كانت التسمية والاسم والمسمى واحداً، إذ كلامه التسمية، وهو المسمى بعينه، وهو الاسم.\rوإذا قال الله تعالى: إني أنا الله، فالاسم هو المسمى، والتسمية ليست غير المسمى، وليست هي هو، فإن التسمية: قول الله تعالى، والمسمى بقوله إني أنا الله: ذات الله، وقول الله تعالى لا يقال فيه هو الله، ولا يقال فيه هو غير الله.\rوإذا قال الله تعالى: أنا العالم، فليس الاسم هو المسمى ولا غيرُه، إذ الاسم: العِلم، وليست التسمية الاسم والمسمى ولا غيرَهما، إذ التسمية: قوله، وليس قوله عينَ علمه، ولا غيرَ علمه.\rوإذا قال الله تعالى: أنا الخالق، فالاسم غيرُ المسمى، فإن المسمى: هو الله، والاسم: الخَلْقُ، والتسمية غير الاسم، وليست غير المسمى، وإنما كانت غير الاسم من حيث كانت قولاً لله، وقوله يغاير خَلقه، وليست غير المسمى، فإن المسمى: هو الله، وليس قولُ الله غيرَ الله سبحانه وتعالى.\r"], [213, "وإذا قال الواحد من الخلق: الله، فالتسمية غير الاسم والمسمى، والاسم هو المسمى، إذ التسمية قول القائل من الخَلق.\rوإذا قال الواحد منا: الله عالمٌ، فالتسمية غير الاسم والمسمى، ولا يقال في الاسم - وهو العِلم - إنه المسمى ولا غيرُه.\rوإذا قال القائل: الله الخالق، فالتسمية غير المسمى، ولا يمكن إطلاق القول بأن التسمية غيرُ الاسم، فإن الاسم هو الخلق، وقول هذا القائل من الخلق، فلا يمكن إطلاق هذا القول بأن التسمية غير الاسم.\rوإذا قال القائل: الله الرازق، فنُطلق القول بأن التسمية غير الاسم، فإن الاسم هو الرزق، وليس القول من قبيل الرزق).\rقال الإمام الحافظ رضي الله عنه: أما قوله: (إذا قال الله: كلامي حق كانت التسمية والاسم والمسمى واحداً)، فظاهر جداً، لأن بكلامه أخبر عن كلامه، وكذلك لو قال العبد: كلامي صدق لكان الأمر كذلك، ولتساوى فيه القديم والمحدَث.\r"], [214, "وأما قوله: إذا قال: (أنا الله فإنا نقول: إن التسمية هي الاسم، ولا نقول إنها غير المسمى)، لأن الغيرية عند علمائنا لا تجوز بين القديم وصفاته وأسمائه، إذ حقيقة الغيرين ما جاز افتراقُهما، وأنا لا أقول ذلك، بل حقيقة الغيرين عندي ما تميز كل واحد منهما عن صاحبه بخاصة، جاز افتراقُهما أو لم يجُز، ومن جعل حد الغيرين ما قالوه فليس في اللغة ولا في الشريعة ما يدل عليه، والحقيقة تعضُدُ ما أشرنا إليه.\rوقد قال كثير من علمائنا: يجوز أن يقال في صفات الله: إنها خلافُ الله، ولا فرق بين الخِلاف والغير في هذا المعنى، ألا ترى أن العرض يستحيلُ وجودُه دون الجوهر وليس به، وهذا نحوٌ من ذلك، وإن لم يكن من حقيقته.\rوقول الأستاذ هاهنا (الاسم هو المسمى) غلط بيّن، لأنه إذا قال الله: أنا الله، فقوله: هو تسميته، وهو اسمه والمسمى ذاته، وليست هي القول، فيكون الاسم والمسمى واحداً.\rوأما قوله: (إذا قال الله: أنَّا العالِم فليس الاسم هو المسمى ولا غيره، إذ الاسم العِلم)، فقول ضعيف، لأن العلم وإن كان صفةً يعبِّر عنها اسمٌ فليست من أسماء الله، إنما اسمه العالِم الدال عليه وعلى علمه الذي هو صفته، ولا فرق بين قول الله: أنا الله، وبين قوله: أنا العالم، إلا من جهة كثرة الإفادة والدلالة، لأن القول (الله) يدل على الوجود خاصة في قول، والعالِم يدل على الوجود بزيادة معنى، وفي قول: يدل القول (الله) على وجود وزيادة معانٍ كثيرة، ويدل القول (العالم) على وجود وزيادة معنى واحد.\r"], [215, "وأما قوله: إذا قال: أنا الخالق فلا فرق بينه وبين قوله: العالِم في باب التسمية، وإنما يفترقان في أن:\rأحدهما: وهو العالِم، يدل على وجودٍ وصفة لا يقال فيها - على مذهبه -: إنها الله ولا غيره.\rوالثاني: يدل على وجود وصفة يقال: إنها غير الله.\rوإنما الذي يختص بغرَضه أن الله تعالى قال: {أَنْزَلَهُ بِعِلْمِهِ} [النساء: 166]، فقوله ليس بغير لذاته ولا لعلمه، ولا هو هو، وقال تعالى: {هَذَا خَلْقُ اللَّهِ} [لقمان: 11]، فقوله ليس بغير لذاته، وهما مغايران لخلقه، وهو مغاير لهما.\rوقد قال النبي صلى الله عليه وسلم: (قال الله: عطائي كلام)، فقوله ليس بغير له، وهما غيران لعطائه.\rفهذا تحقيق بالغ يشفي، وعجباً لهذين الإمامين على جلالة قدرهما أصولاً ولغة كيف خفي عليهما هذا، ولم يبق بعد هذا إلا ذِكْرُ إطنابٍ في\r"], [216, "المقالات والدلالات، والأسئلة والانفصالات، إلا أن الأمر مع التبين قريب، وبما ذكرتُه لك يرتفع التثريب، وينفع التدريب، ويذهب الترتيب.\rتتميم:\rإذا علمتم معنى الاسم والوصف فالأسماء بعد هذا على قسمين:\rأحدهما: يدل على مجرد الذات، ومنها ما يدل على الذات والصفات، فإذا قلت: زيدٌ، دل على الوجود مطلقاً، وإذا قلت: عالِم، دل على ذات وصفة، فاقتضى هذا الاسم مسمى وموصوفاً، ودخلت فيه الصفة.\rوالأصل في العربية أن كل قول دل على الوجود مطلقاً فهو: اسم، وما دل على معنى زائد عليه فهو: وصف، ولكنهم يُطلقون الاسم على الوصف، ولا يُطلقون الوصف على الاسم، وسترى في أسماء الله تعالى ما يدل على الوجود المطلق وهو قليل، وما يدل على الوجود المقترن بالصفة وهي كثير، إن شاء الله.\r"], [217, "السابقة الرابعة: [في أن طريق إثبات أسماء الله تعالى هو التوقيف وأن العقل لا مدخل له فيه ذلك]\rنقول: لو تُركنا ومقتضياتِ العقول وطرقَ النظر في المعقول، لم نسمِّ الباري تعالى باسم، ولا وصفناه بصفة، ولا وضعنا له في عباراتنا وسماً، فإن أسماءنا واقعة على معانٍ قاصرة، ومسميات حادثة، وصفات ناقصة، فأنى لهذا النقصان بأن يعبَّر به عن ذي الجلال والكمال؟!\rولهذا ضلت طوائفُ في جهتي التقسيم في هذا الباب من تفريط وإفراط، ففرَّطت جماعةٌ من الملحدة الذين اقتصروا على مبادئ قواعد العقول، ولم يعوِّلوا على الشرع المنقول، فقالت: لا نسمي الباري باسم، ولا نصفه بصفة فعطَّلوا.\r"], [218, "وأفرطت طوائف من المشبهة فقالت: نطلق عليه كل اسم، وننسُب إليه كل فعل.\rوامتن الله على طوائف الحق بقصد السبيل فقالوا كما قال مولاهم: {وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا وَذَرُوا الَّذِينَ يُلْحِدُونَ فِي أَسْمَائِهِ} [الأعراف: 180] يعني يميلون فيها عن طريق الحق؛ إما إلى تعطيل، وإما إلى تشبيه، وإما إلى سوء تأويل، فوصفه المحقِّقون بما وصف به نفسه، وحملوا ذلك فيه على أصح الوجوه وأكمل المعاني.\rولقد فاوضتُ في هذا الباب بعينه رئيسَ الحقائق فقال لي: (إنه لا سبيل إلى إطلاق لفظ على الحقيقة في أسماء الباري وصفاته، وإنما ذلك كله مجاز، فإن المعاني الإلهية تقصُر عنها الأسماء الحادثة)، وقال في موطن آخر: (إن الحقائق إنما هي في الحق للإله وصفاته، فأما العبيد فهم أهل المجاز).\rوهذان القولان صحيحان، لأنهما بنظرين مختلفين، كل واحد منهما صحيح في نفسه وفي جهته، وذلك أنك إذا نظرت إلى حقيقة المخلوق وما يعبَّر عنها من الألفاظ وجدتها كلها ممتنع في حق الله إطلاقُها على الوجه\r"], [219, "الذي يعبَّر به عنها في الخالق تعالى، وإذا نظرت إليها في حق الخالق وجدتها على الكمال والتمام والتنزُّه عن الآفة.\rوالصحيح أنها حقيقةٌ في حق الخالق، مجازٌ في حق المخلوق، ولولا المعاني المحدَثةُ المتفقةُ مع المعاني القديمة في أصل الحقيقة، وفي الأسماء الدالة المخالفة لها في الجلال والتقديس والكمال بكل وجه من وجوه المعاني، ما كان لأحد سبيلٌ إلى معرفة الله سبحانه حسب ما قررناه في كتاب المقسط وغيره.\r"], [220, "السابقة الخامسة: [اختلافهم في إثبات أسماء الله تعالى بطريق خبر الآحاد وما كان فيه معنى التعظيم]\rاتفقوا رضي الله عنهم على أنه يسمى بما سمى به نفسه في كتابه العزيز، أو في خبر متواتر، واختلفوا بعد ذلك في طريقين:\rأحدهما: فيما يرد من طريق الآحاد، والأكثر على جوازه، فأما من منعه فقال: لأن خبر الواحد لا يوجب العلم، وأما من جوّزه - وهو الصحيح - فقال: إن خبر الواحد وإن كان لا يوجب العلم فإنه يوجب العمل، على حسب ما رتبناه في كتب الأصول، والتضرع إلى الله والدعاء إليه بأسمائه عمل، فاز بما يقتضي العمل من طريق الآحاد.\rالثاني: ما كان من الأسماء يقتضي التعالي والتقديس، ولم يرد به خبر، فأكثرهم على أنه لا يجوز أن يسمى به.\r"], [221, "ومنهم من قال: يجوز، وهو الصحيح عندي؛ والعمدة فيه ثلاثة أمور:\rأحدها: أن ألسنة السلف والخلف كانت منطلقةً في الابتهال إلى الله والتضرع إليه بكل لفظ يقتضي التعالي والتقديس حياةَ الرسول صلى الله عليه وسلم وبعد موته، وذلك بيّن لمن بلّ غليلَه من بحر الآثار، وأبلّ عليلَه من دواء الأخبار.\rالثاني: أن أحد معاني قوله: {وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى}، هذا الوجه على ما بيناه في تأويله قبل هذا.\rالثالث: - وهو العمدة الثابتة - أن كل معنى يجري في الخاطر من تعظيم الله سبحانه فقد جاء في الكتاب والسنة، وما لم يأت فيهما لا يجري في ميدان الخاطر ولا يقذفه بحر الوهم.\rيزيده تأكيداً: أن دليل العقل يقتضي وجوبَ معانٍ لله يستحيل خلوُّه تعالى منها، ويقتضي أيضاً إحالةَ معانٍ لا يجوز كونُه على شيء منها، ويقتضي جوازَ معانٍ عليه لا يُحكم له فيها بنفي ولا إثبات، فأما المعنى الواجب فيُحكم له به كما يُحكم بإحالة الثاني وهو المستحيل، ويتوقفُ في الحكم الثالثِ وهو الجائز حتى يرد به توقيف، وذلك بخمسة طرق:\r"], [222, "الأول: ظاهر كتاب.\rالثاني: ظاهر سنة.\rالثالث: إجماع الأمة.\rالرابع: أن يكون له معنى معقول يجوز على الباري، ويقتضي له الجلال والتقديس، فإنه يجوز - عندي - أن يسمى به، لما قدَّمناه.\rالخامس: خبر آحاد.\r"], [223, "السابقة السادسة: [أقسام أسماء الله تعالى]\rقال علماؤنا: أسماؤه تعالى وأوصافه تعالى على ثلاثة أقسام:\rمنها: ما يرجع إلى الذات خاصة.\rومنها: ما يرجع إلى الصفات.\rومنها: ما يرجع إلى الأفعال.\rفالأول: قولنا: موجود؛ شيءٌ واحدٌ في الأصح من المعاني، والأول منها على ما يأتي بيانُه.\rوالثاني: قولنا: عالم، قادر، مريد، حي.\rوالثالث: خالق، ونحوه.\rالنوع الثاني: أن هذه الأقسام الثلاثة تدخل عليها ثلاثة أقسام أخر، منها ما يختص بأنه يرجع إلى الذات لا يحتمل غيرَه، ومنها ما يختص بأنه من صفات الفعل لا غير، ومنها ما يكون بمعنى من صفات الذات، ويكون بمعنى آخر من صفات الفعل.\rفالأول: قولنا: إنه عالم، فهذا يرجع إلى الذات، لأنه يدل على العلم القائم بها، وكونها على هذه الصفة.\rوالثاني: كقولنا: إنه خالق، فهذا يرجع إلى الفعل الموجود لا يحتمل غيره في أول الوجوه، وأولاها على ما يأتي بيانُه في موضعه، وكقولنا: إنه رازق.\rالثالث: قولنا: إنه حكيم، فإنه يكون راجعاً إلى العلم بوجه، ويكون راجعاً إلى إتقان الفعل، على ما يأتي بيانُه إن شاء الله.\rالنوع الثالث: أنها تنقسم ثلاثة أقسام من وجه آخر:\r"]], "pg": [198, 223]}, "561.22": {"x": [[223, "منها ما يرجع إلى معنى مشتق من معنى يرجع إلى غيره، كقولنا في الباري تعالى: إنه مطاعٌ ومعبودٌ.\rومنها: ما يرجع إلى ذاته خاصة، كقولنا: موجود.\rومنها: ما يرجع إلى كون ذاته على معان وأحوال، كقولنا: إنه عالم، قادر، مريد، حي، وقد تقدم شرع الثاني والثالث من هذا النوع.\rفأما الأول فلا يُطلق عليه منه إلا ما كان سليما عن النقائص، بريئاً من الآفات، إذ لا يقال: إنه منكور، ويقال: إنه مشكور، ولا يقال: إنه مذموم، ويقال: إنه محمود.\rوأما الثاني والثالث فبيانُهما يأتي مستوفى، إن شاء الله.\r"], [224, "السابقة السابعة: [في صحة معرفة الله وهل يمكن التساوي فيها؟]\rإن معرفة الله واجبة على كل مكلف، واختلف الناس في معرفته:\rفمنهم من قال: لا تصح معرفته لبشر على التحقيق، وإنما يَعرف الله الله، وعبروا عن حقيقة الإيمان فيه بأن العجز عن الإدراك إدراك، ونسبوه إلى أبي بكر الصديق رضي الله عنه.\rومنهم من قال: تصح معرفته.\rومن قال تصح معرفته اختلفوا:\rفمنهم من قال: إن الخلق كلهم يتساوون في معرفته؛ من ملَك مقرب، أو نبي مرسل، أو ولي صالح.\r"], [225, "ومنهم من قال: لا، بل يتفاوتون في معرفته بحسب تفاوت درجاتهم.\rولكل قول من هذه الأقوال وجهٌ قد أوضحناه في كتاب المقسط، إلا أنا نشير هاهنا إلى الصحيح فنقول:\rأما قول من قال: لا تصح معرفته لبشر؛ فإن عنى أن العارف بأن الله تعالى لا أول له مثلاً، فنظر في نفي الأولية عنه وقال: إني لا أقدِّر وجوداً له في حال إلا ووجوده سابقٌ تلك الحال، وذلك التقدير أبداً، وهكذا دائماً في التقدير والنظر، حتى ينقطع به النظر وتفنى التقديرات، وسبق الوجود متقدم عليه، فهذا مما لا وصول له إليه، ولا وقوف له عليه، فهذا صحيح.\rوإن عنى من قال: إن معرفته تصح؛ أنك إذا قلت: لا أقدِّر الوجود للباري تعالى في حال إلا ووجوده سابق له، فهذه معرفة صحيحة كافية لا يمكن غيرها، ولا يُكلَّف سواها، فهو صحيح.\rوأما من قال - بعد الإقرار بصحة المعرفة -: إن الخلق يتساوون في معرفته، فإن عنى بالتساوي التساوي في العلم بوجوده تعالى وقدرته وعلمه وحياته وإرادته ونفي الأولية عنه واستحالة العدم في المستأنف وما أشبه هذا من أحوال أوصاف الإله وأسمائه فصحيح.\rوإن عنى به التساوي في فصول المعرفة به وفنونها وتعلق العلم بأسمائه الحسنى، وصفاته العُلى وأفعاله وحكمته؛ وما يتعلق بذلك من أحكام العموم فيها والخصوص ومتعلقاتها، والتوصل بكل دليل إليه ونحو ذلك مما تنمي به المعرفة، ويزيد به الإيمان بزيادة المعلومات والتصديقات والمعارف والأدلة، فلا يصح التساوي فيه أبداً.\r"], [226, "وهذا هو معنى التفاوت عند من رآه، لا معنى له سواه، وقد بسطنا القول فيه في موضعه بسطاً يوضح لكل مُطالعٍ مَطالعه، وهذه جملة ذلك، والله أعلم.\r"], [227, "السابقة الثامنة: {هل يجب معرفة أسماء الله تعالى على التفصيل؟]\rإن معرفة الله إذا كانت واجبة فلا نقول عَرَفه، إلا من عرف أسماءَه الحسنى وصفاته العلى، وذلك لا يتفق إلا للآحاد، فأما الجَمَّاء فلا يَخلُصون من ذلك من ذلك إلا إلى معرفة آحاد منها، وأصول من جملتها، كالوجود والعلم والقدرة والإرادة والحياة والكلام والسمع والبصر، ونفي النقائص والآفات، فهذه جملة لا بد لك مؤمن منها.\rويتركب على ذلك من الأحكام نفيُ النهاية في الوجود والذات والصفات، والتحديد في التوحيد والخلق والاختراع، ألّا ترى واحداً إلا هو، ولا خالقاً ولا مخترعاً غيره، حتى إن بعض المتأخرين من المتصوفة غلا\r"], [228, "في هذا الباب، وقال في ذلك قولاً شرحناه مع ما يلزم مَنْ رأى كمال المعرفة في كتاب المقسط، وليس من أدب العبد ألا يعرف اسم مولاه، ولا من أدب الجار ألا يعرف اسم جاره، فكيف لا تعرف الخليقة أسماءَ مولاها التي تتوسل بها إليه وتتضرع، وتدفع بها المَضراتِ عنها وتنتفع.\r"], [229, "السابقة التاسعة: [في ما يجوز للخلق التسمي به من أسماء الله تعالى]\rإن الباري تعالى أذن للعباد بأن يتسمَّوا بأسماء تشارك أسماءه الحسنى في اللفظ، وبعد هذا فمن الواجب أن تعلموا أن كل اسم تسمى به الباري سبحانه ويطلَق على المحدَث فللباري فيه اختصاص، ولولا ذلك لوقعت المماثلة المستحيلة بين الرب والمربوب، والمولى والعبيد.\rوقد هام لأجلها قوم في أودية المجاهل، فمن قائل بالتشبيه بين الإله والعبيد، وهذا هدمٌ للتوحيد، ومن متحرز بزُعمه، وإن كان قد وقع في الجهل برُغمه، فقال: إن كل اسم من أسمائه تعالى - إلا قولنا: الله - فإن العبد مطلوبٌ بأن يتكسّب فيه وصف الإله به على قدر استطاعته، حتى قال آخر وصرح: إن التخلق بأخلاق الباري مندوبٌ إليه.\r"], [230, "والذي أوقعهم في ذلك أثر يُروى ويُؤثَر إلى النبي صلى الله عليه وسلم أنه قال: (تخلَّقوا بأخلاق الله)، وهذا الحديث باطل، ولو كان صحيحاً لكان معناه ظاهراً.\rوأخلاق الله تعالى، هي كل صفة محمودة، يكون الثناء عليها في الشريعة موجوداً، كالتقوى والجود وكظم الغيظ والعفو، فهذه وأمثالها أخلاق الله وأخلاق القرآن وأخلاق النبي صلى الله عليه وسلم، أي الأخلاق التي مدح الله، وورد الثناء عليها في القرآن، وكان عليها الأنبياء عليهم السلام، كما يقال في المساجد (بيوت الله)، أي عظَّمها الله ودعا إلى ذلك فيها.\rوقد عقدنا في كل اسم فصلاً في الاختصاصات الإلهية التي يتميز بها الإله من العبيد، ولو لم يكن في هذا المجموع سواها لظهر به على سائر مجموعات هذا الباب، فكيف وتتبَعه فوائدُ عظيمةٌ سواها.\r"], [231, "السابقة العاشرة: في وجه ترتيب الكلام في كتابنا هذا على الأسماء\rفنقول: إن علماءنا رضي الله عنهم بنوا الكلام فيه على الحديث المروي عن أبي هريرة المعقَّب بتفسير الأسماء، فأما نحن فاستخرنا الله تعالى على أن نرتب القول فيه على درجات الترقي في معرفة الله، ونسلك فيها السبيل الموصلة إلى العلم به على نحو ما قررناه في كتب الأصول؛ من النظر في الوجود والقدرة والعلم والحياة والإرادة والكلام والسمع والبصر، وهكذا على الترتيب الواجب حتى نصل إلى آخر المعارف، ولكن بعد أن نتكلم على قولنا في اسم الله تعالى، وبعد الفراغ منه ننعطف على الترتيب الواجب، ونعقِد في التكلم على كل اسم منها عقوداً:\r"], [232, "عَقْدٌ في مورده.\rوعقد في شرحه لغةً.\rوعقد في شرحه عقيدةً.\rوعقد في تنزيل معنى الاسم؛ نبين فيه الاختصاص للرب به، والفرق الذي يكون بينه وبين المخلوق الفاصل لوجه الاشتراك في التسمية، خلا ما يتبع ذلك من تمهيدات وتتميمات في الأسئلة والاعتراضات، وإلحاق الخفيات بالجليات، وذلك في بعض الأسماء، وإلى الله نتضرع في منح التوفيق، والإرشاد إلى التحقيق لا رب غيرُه.\r"], [233, "ص 234\r"], [234, "[القطب الثالث: في شرح معانيها وإيضاح مقتضاها]\r"], [235, "ص 236\r"], [236, "القول في ذِكرنا له (بالله) سبحانه:\rاعلموا - وفقكم الله - أن البداية بهذا الاسم واجبة لأربعة أوجه:\rأحدها: أنه أعظم الأسماء معاني.\rالثاني: أنه أكثرها ثواباً.\rالثالث: أنه أعمها تفسيراً، لأنك إذا أخبرت عنه سبحانه (بالله) كفى في التعريف به والذكر له، وإذا أخبرت بأسمائه عنه رجعت في التفسير إليه، فتقول: الملك هو الله، القادر هو الله، العالم هو الله، الخالق هو الله، وهكذا إلى آخر الأسماء.\rالرابع: أن التسمي به ممنوع لغيره منع إيجاد، فلا يتسمى به أحد بحال، لا منع تشرع، فلما كان أمّاً في الأسماء الحسنى وأصلاً، وجبت البداية به لذلك، والقول فيه وفيما يليه يكمُلُ في أربعة فصول كما عقدنا آنفاً.\rالأول: في مورده شريعةً.\rالثاني: في شرحه لغةً.\rالثالث: في شرحه عقيدةً.\rالرابع: في التنزيل.\rالفصل الأول: في مورده شريعةً\r"]], "pg": [223, 236]}, "561.23": {"x": [[236, "فنقول - وبالله التوفيق -: إن قولنا (الله) ورد به الكتاب والسنة وأجمعت عليه الأمة، وهو أم الأسماء وأصلها كما تقدم بيانُه، وكذلك أيضاً ورد\r"], [237, "قولك (إله)، قال سبحانه: {وَلِيَعْلَمُوا أَنَّمَا هُوَ إِلَهٌ وَاحِدٌ} [إبراهيم: 54]، وقال النبي صلى الله عليه وسلم للقيطٍ وافد بني المنتفق: (فلعَمْرُ إلهك)، وخرّجه أبو داود، وقال بعض شيوخ الصوفية: إنه اسم الله الأعظم، لأنه لا يتطرق إليه حذفٌ بسقوط حرف.\rبيانه: أنك إذا حذفتَ الألف بقي المعنى كاملاً، تقول: {لِّلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ} [البقرة: 283]، وإذا حذفت اللام الواحدة بقي (له)، تقول: {هُوَ الْغَنِيُّ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ} [يونس: 68]، وإذا حذفت اللام الثانية بقي (هو)، تقول: {هُوَ اللَّهُ الَّذِي لَا إِلَهَ إِلَّا هُوَ} [الحشر: 22]، فيكون المعنى ببقاء حرف واحد أتم ما كان كما كان ببقاء الحروف كلها.\rوقد قال ابن فورك: (إن قولك (هو) كلمة مركبة من حرفين: الهاء، وهي من حروف الحلق، والواو، وهي من حروف الشفتين، والحلق أول محالّ الحروف، والشفتان آخرها، فدل ذلك على أن منه المبتدا وإليه المنتهى).\rوهذه أغراض صوفية محوِّمة على الحقائق، وإن كان لم يقع بها أُنسٌ لكم، وابن فورَك شيخ من شيوخهم، وإمام مقدَّم فيهم.\r"], [238, "الفصل الثاني: في شرحه لغةً\r"]], "pg": [236, 238]}, "561.24": {"x": [[238, "وقد رأينا بعد إنعام النظر أن نمزج القول في هذا الفصل وفي الذي يليه - وهو القول في بيان شرحه عقيدةً - ها هنا خاصة، لاضطرارنا إلى ذلك في إظهار البيان وتقارب الفصلين، وفيه خمس مسائل:\rالمسألة الأولى: في سرد الأقوال\r"]], "pg": [238, 238]}, "561.25": {"x": [[238, "وقد نخّلنا الأقوال في هذا الاسم وتوخّينا الأقرب إلى الإشكال فيها، فألفيناها عشرة أقوال مقتطعة من نيف على عشرين قولاً طالعناه فيه، تنبني على قولين:\rالأول: أن قولك: الله اسم للرب سبحانه، يجري في العبارة عنه به مجرى الأسماء الأعلام في المخلوقين، وهي قولُنا: زيد وعمرو.\r"], [239, "والثاني: أنه مشتق من معنى موجود بذاته سبحانه، يجري في العبارة عنه مجرى الأسماء المشتقة فيه سبحانه وفي المخلوقين، وهي قولنا: العالم القادر.\rوالذين قالوا: إنه مشتق اختلفوا في ذلك على تسعة أوجه تذكر مرسلة مجموعة غير مضبوطة بنظام ترتيب:\rالأول: أنه الله بمعنى المحتجِب.\rالثاني: أنه الله بمعنى العالي.\rالثالث: أنه الذي يُفزَع إليه في الحوائج.\rالرابع: أنه مشتق من الوَلَهِ؛ وهي خفَّةٌ تصيب الرجل من طرب أو حُزن.\rالخامس: أنه من الوله وهو التحيُّر.\rالسادس: أنه مشتق من الإقامة.\rالسابع: أنه المعبود.\rالثامن: أنه المستق للعبادة.\r"], [240, "التاسع: أنه القادر على إخراج الشيء من العدم إلى الوجود.\rالمسألة الثانية: في التوجيه\r"]], "pg": [238, 240]}, "561.26": {"x": [[240, "فأما من قال: إنه اسم غير مشتق وأنه يجري في التعبير عنه به مجرى الاسم العلم في غيره، فاحتج بأنه لو كان مشتقاً من صفة لسمي به من قامت تلك الصفة به، وقد قال تعالى: {هَلْ تَعْلَمُ لَهُ سَمِيًّا} [مريم: 65]، جاء في التفسير: هل تعلم أحداً تسمى بالله غيره.\rوأما قول من قال: إنه بمعنى المحتجب فقال: إنه يقال: لاهَ، بمعنى احتجب، وأنشد:\rلاهت فما بَرَزَتْ يوماً بجارحة ... يا ليتَها برزتْ حتى نحيّيها\rوأنشد:\rلاه ربي عن الخلائق طُرّاً ... خلقَ الخلقَ لا يُرى ويرانا\rوإنما احتجب بالأنوار، والله سبحانه دونه سبعون حجاباً من نور:\r"], [241, "أولها: السراج، فالمرء يرى أنه إذا نظر إليه لمحة أو لمحتين قدر عليه، فإن أدام النظر إليه عشي بصرُه وَعَلَتْهُ سَمادير.\rثانيها: القمر، وهو مثل السراج في المعنى المتقدم، ولكنه أبلغ منه فيه.\rالثالث: الشمس، والمرء لا يستطيع أن يلمَحَها إلا خَطفاً، ولو تكلفتَ ذلك لذهب بصرُك بالجملة.\rفهذه ثلاثة أنوار من أنوار الله، وحجبه سبعة وستون حجاباً، نسبة كل واحد من ذلك إلى ما يليه نسبة السراج إلى القمر، ونسبة القمر إلى الشمس، فكيف يستطيع أحد على رؤيته، حتى إذا كُشف الغطاء وقوي البصر، وذلك في ثلاثة مواطن:\rأولها: بالموت، فإنه ينظر حينئذ إلى ما كان قبل، لا يقدر على النظر إليه من الملائكة والملكوت، بنزول الأقضية، وصعود الأعمال، وجريان التدبيرات، وبث المقادير في المخلوقات، وعن ذلك عبر قوله تعالى: {فَكَشَفْنَا عَنكَ غِطَاءَكَ فَبَصَرُكَ الْيَوْمَ حَدِيدٌ} [ق: 22].\r"], [242, "ثانيها: بالحشر، فإنه ينكشف له به غطاءٌ عن عظائم النشور وأهوال المواقف وعجائبها.\rثالثها: بدخول الجنة، فإنه ينكشف به الغطاء الأعظم، وتقوى الأبصار والبصائر، وترتقي حالة العبد من الحيلة إلى الحَوْل، فكل ما أراد كان، ويستسخر الوِلدانَ والغلمانَ فيما يريده من غير افتقار إليهم، وتصلُح حينئذ الأبصار لرؤية خالقها، فيكشف رداء الكِبر عن وجهه، وهو آخر الحجب، فيراه الخلق، فما أعطوا قبلَها لا يرون أنه لَذة.\rوأما من قال: إن لاه بمعنى علا، فقال: إنه يرجع إلى معنى احتجب، لأنه إن توهم فيه متوهم أنه علو المسافة والمكان فهو عن ذلك متعال، وإن اعتقد فيه علو المنزلة والجلال فهو فيه صحيح، والمعنى مشهور في اللغة، يقال: لاهت الشمس إذا علت، وأنشدوا:\rوأعجلْنا إلاهةَ أن تؤوبا\r"], [243, "وسميت به الشمس لأنها في الغاية من العلو، ولذلك لم يُرَ في المخلوقات أعلى منها سنى وسناءً، ولذلك وَهِمَ بها إبراهيم صلى الله عليه وسلم في أحد الأقوال، فقال: هذا ربي، وضل بها سبأ حين دوخ الأرض وداسها وغلب ملوكَها، وساسها فتخلف عن أهل مملكته حتى ساءهم طول غيبته، ثم برز وقال: إني لما بلغت ما بلغت، ونلت من الأمل ما نلت، رأيت أنه تعيّن علي حق الشكر، فلم أر بذلك أحق من الشمس فسجدت لها عند طلوعها، فاسجدوا معي، فكان ذلك أول عبادة الشمس.\rوأما من قال: إنه الله بمعنى يُفزَع إليه في الحوائج والنوائب: فقال: إنه كقولك: لِحاف: لما يُلتحف به، ولِفاع: لما يُتلفَّع به، وأنشد:\rولِهتُ إليكم في بلايا تنوبُني ... فألفيتُكم فيها كِراماً أماجدا\r"], [244, "قاله الحارث بن أسد في جماعة من أهل السنة.\rوأما من قال: إنه مشتق من الوله، فقال: هو معنى يصيب الرجل من الخفة لطرب أو حزن، وأنشد:\rولهتْ نفسي الطروبُ إليكمْ ... ولهاً حال دون طَعْمِ الطعامِ\rوأما من قال: إنه من التحير، فقال: إنما سُميت الشمس إلاهةً لأن الأبصار تتحير فيها.\rوأما من قال: إنه بمعنى أقام، فقال: إنه من المعروف في لسان العرب، أَلِهَ بالمكان: إذا أقام به، وأنشد:\rألِهنا بدار ما تبينُ رسومُها ... كأن بقاياها وِشامٌ على اليدِ\rوأما من قال: إنه من العبادة فعلاً أو وجوباً أو استحقاقاً، فأخذه من قولهم: تألَّه: إذا تعبَّد، وأنشد قول رؤبة:\rلله در الغانيات المُدَّهِ ... سبَّحنَ واسترجعن من تألُّهِ\r"], [245, "وكانت العرب تقول في الجاهلية: فلان يتأله: إذا تعبد، وسميت الأصنام التي كانت تعبدها آلهة لأنهم كانوا يتعبدون إليها.\rتمهيد:\r"]], "pg": [240, 245]}, "561.27": {"x": [[245, "كما اختلف الناس في اشتقاق هذا الاسم، كذلك اختلف أهل اللسان في ذلك؛ فقال الكوفيون: أصله (لاهٌ)، ثم دخلته الألف واللام فصار (الله)، وقال البصريون: أصله (إله) وهو المختار.\rقال سيبويه: سألتُ الخليل عن هذا الاسم فقال: أصله إله، فأُدخلت الألف واللام بدلاً من الهمزة. وقيل: الأصل (إلاه)، ثم أدخلت الألف واللام، فقيل: الإلاه، ولم يكن بين الهمزتين إلا حرف ساكن، والساكن لا يحجز حَجزاً متمكِّناً، فكانت الهمزتان كأنهما ملتقيتان، ومن شأنهم إذا التقت الهمزتان أن يخفِّفوا إحداهما أو يُسقِطوا، ولو خُففت هاهنا إحداهما أدى إلى اجتماع الساكنين، ولو أسقطت الهمزة الأولى وقد جُلبت ليُتوصل بها إلى النطق بالساكن الذي هو اللام لاحتيج إلى غيرها، فكان إسقاط الأخرى أولى، وكأن اللامان قد اجتمعا وأولهما ساكن، ومن شأنهم أن يُدغِموا الحرفين إذا اجتمعا من جنس واحد وأولهما ساكن، فأدغموا لام المعرفة في لام إله، فقيل: الله، ثم لزم حرف التعريف الكلمة حتى صار كأنه جزء منها لما كان عوضاً من الهمزة الذاهبة، فقيل: يا لله، ونودي كما نودي الذي والتي.\r"], [246, "والقول في ذلك كثير لسعة هذه الصناعة وتمدد أطرافها، وهذا القدر كافٍ في الإشارة إلى أوائلها، والصحيح قول سيبويه، فخذوه كذلك حتى تُمعِنوا النظر فيه بتطريقه، وإنما ينبغي لكم الاعتناء بأقوال أهل التحقيق، فنقول وهو:\rالمسألة الثالثة: في تنقيح الأقوال\r"]], "pg": [245, 246]}, "561.28": {"x": [[246, "أما قول القائل: إنه بمعنى احتجب، فلا تشهد له لغة ولا اشتقاق، وما احتج به قائله من الشعر موضوع، ويرده من الحقيقة أنه مبصِرٌ لنفسه، ولا يُنكر منكِر أنه جائز أن يكون مبصَراً للملائكة أو بعضهم، ولا منكَر عندنا في أن يراه كل راء، وهو إله في كل حال وفي كل موضع.\rوبهذا الوجه يفسُد قول من قال: إنه بمعنى علا، لأن اللغة تبطله، وإن كان المعنى يصح منه، وليس كل معنى صحيح في نفسه يطلق عليه اسم غيره لغة إلا بموردها، ولا شريعة إلا بإذنها.\rوبه أيضاً يفسُد قول من قال: إنه بمعنى أنه يُفزع إليه في الحوائج؛ لعدم وروده في اللغة كذلك، ولأنه لم يزل إلهاً في كل حال، والفزع إليه في النوائب مخصوص ببعض الأحوال، ولأن البارئ إله للخلق، ولا يَفزع إليه منه\r"], [247, "إلا الحيوان العاقل، فيخرج عن هذا الاشتقاق من أن يكون إلهاً لجميع المخلوقات، فوجب أن يُحمل على وصف عام.\rوبهذا يفسد يقول من قال إنه مأخوذ من الوله، بمعنى الطرب أو التحير، لأنه كما قدّمنا أمرٌ مخصوص وحال حادثة.\rوكذلك يفسد قول من قال: إنه من الإقامة، لأنه معنى لا يُعرف لغة، وبيتهم من الشعر الذي ذكروا فيه موضوع مجهول، وأيضاً فإنه لو كان من الإقامة لكان لمن له إقامة بموضعٍ حَظٌّ من الإلهية.\rوأما قول من قال: إنه بمعنى المعبود، فيفسُد من خمسة أوجه:\rأحدها: أن غير الباري قد يُطاع ويُعبد، ويكون مطاعاً معبوداً، ولا يكون بها إلهاً.\rالثاني: أنه إنما كان معبوداً عند وجود العبادة، وهو إله في كل حال.\rالثالث: أنه معبود من بعض الخلق، وهو إله لجميعهم، وبهذا فسد أكثرُ ما تقدم.\rالرابع: - وهو دقيق - أنه إنما كان إلهاً لأوصاف هو عليها، ويكون معبوداً لوصف يكون عليه العابد من عبادته له، فكيف يكون إلهاً بأمر يَرجعُ إلى\r"], [248, "غيره يجوز أن يوجد وأن لا يوجد؟ حتى لو قدّرنا عدمَ العبادة من العابد لم يجُز تقدير عدم الألوهية، ولا شيئاً منها من الإله، ولأجله احترز بعضهم فقال: هو المستحق للعبادة، وهو أيضاً فاسد من وجهين:\rأحدهما: أن استحقاق العبادة بما يفعله من النعم، وهو إله قبل الفعل، إله عند تقدير عدم الفعل.\rالثاني: أنه لم يزل إلهاً كما قلنا، ولا يصح أن يقال: لم يزل مستحقاً للعبادة، لاستحالة كون العبادة فيما لم يزل، واستحالة أن يستحق ما لا يصح كونه في حال الاستحقاق، وقريب منه من عبّر بالإيجاب.\rالخامس: أنه لو كان إلهاً من معنى يرجع إليه من غيره كالعبادة والفزَع لكان اسمه لذلك من بناء المفعول كالمعبود والمُطاع، وقولنا: (الله) ليس من أبنية المفعول.\rفإن قيل: فقد تتبعتم الأقوال بالاعتراض والنقض فما المختار؟\rوهو:\rالفصل الثالث: في شرحه عقيدةً\r"]], "pg": [246, 248]}, "561.29": {"x": [[248, "قلنا: اختلف المحققون من علمائنا - رحمهم الله - في تنخيل هذا المعنى على قولين: فمنهم من قال: إن معنى ذلك أنه القادر على إخراج الشيء من العدم إلى الوجود، وذلك أن هذا الاسم لما كان مختصاً به لا يشاركه أحدٌ فيه كان معناه المعنى الذي يخصه ويباين فيه غيرَه، ولا يشاركه فيه أحدٌ حتى\r"], [249, "يكون اللفظ طِبقاً لمعناه ومماثلاً في اختصاصه له، وهذا هو الذي اختاره الشيخ أبو الحسن إمام السنة.\rومنهم من قال: إنه اسم مختص بالباري يجري في الاختصاص مجرى الأسماء الأعلام في غيره، وأنا إلى هذا القول أميل، لأنه أسلم من الاعتراض، وأصوب عند التتبع، ولأنا لما رأينا كل قول لا يخلص، وكان جميعُها معترَضاً كان هذا أولاها.\rألا ترى أن قول شيخ السنة على رونقه لا معنى له؛ لأنه يقال له: من أين جعلت معناه: ما اختص به دون سواه، وَلِمَ يَلزم أن يكون المعنى مختصاً كما كان اللفظ مختصاً؟\rوأيضاً فإنه إن كان الاختصاص في اللفظ موجِباً للاختصاص في المعنى فنقول: معناه الذي اجتمعت له الأسماء الحسنى والصفات العلى، المنزه عن مماثلة الخلق، المقدس عن النقائص والآفات، فهذا هو الله.\rوالدليل عليه أنك إذا فسرت كل ما يجب أو يجوز له أو يستحيل عليه قلت: لله أو هو الله، فهذا الاختصاص أولى، والإعلام أقوى وأمضى، وكلاهما على هذا الوجه سواء.\r"], [250, "وليس في هذا الاسم حظ في التنزيل لأجل استبداد الباري به، وقد قال بعض المتأخرين - مشيراً إلى ذلك -: (إن كل اسم لله يصلح للتخلق إلا قولنا: الله، فإنه للتعلق لا للتخلق)، وقد بينا معنى التخلق فيما تقدم.\r[مقدمة في بيان العلة في البَدء بأسماء التنزيه]:\rوبعد هذا البيان في هذا الاسم ننعطف على بيان سائر الأسماء على الترتيب الواجب فيها، ونعقد مقدمةً فنقول:\rإن المقصد معرفة الله تعالى وتوحيده والإيمان به، فهو المطلوب من الرسل، والحكمة المبعوث لأجلها جميع الأنبياء، والمُعظَم الأعلى في التكليف، وعنه عبَّر قولك: (لا إله إلا الله) الذي هو أصل التوحيد وعمود الإسلام، وفيه البداية بالتنزيه قبل الإثبات، وبنفي النقائص قبل التقريظ بصفات الجلال والكمال، فنحن على هذا المنوال ننسج، وعلى هذا الركن نعتمد، وسيشترك كثير من الأسماء في التنزيه والإثبات للكمال والجلال بمعانٍ\r"], [251, "كثيرة، ولكنا نذكر في التنزيه ما نراه أصلاً فيه، ونبقي على رسم الاحتمال أسماءً ترد في مواضع نشير إلى احتمال التنزيه فيها، حتى نكون جامعين بين الطرفين، حائزين للأمدين.\rوالفرق الأصلي بين أسماء التنزيه والإثبات للكمال، أن كل اسم أفاد معنى قائماً بالذات فهو اسم كمال وجلال، وكل اسم عاد إلى نفي نقص أو آفة فإنه تنزيه.\rوأول أسماء التنزيه وأولاها الواحد، فبه نبدأ، وعليه نرتب باقي أسماء هذا القسم.\rالفصل الرابع: في التنزيل\r"]], "pg": [248, 251]}, "561.30": {"x": [[251, "اعلموا - وفقكم الله - أن الباري سبحانه يختص بهذا الاسم لفظاً ومعنى، أما اللفظ فلا يطلق إلا عليه، وأما المعنى فله فيه أحكامٌ عشَرةٌ:\r"], [252, "الأول: القدرة على الخلق، فلا يحدث إلا ما يخلق.\rالثاني: لا يكون إلا ما يريد.\rالثالث: أنه القاهر الذي لا يُقهر.\rالرابع: أنه الغالب الذي لا يُغلب.\rالخامس: أنه الذي لا يصح التكليف إلا منه.\rالسادس: أنه الذي لا تجوز العبادة إلا له.\rالسابع: أنه الذي لا ترتفع الرغبة إلا إليه.\rالثامن: أنه الذي لا تكون الرهبة إلا منه ولديه.\rالتاسع: أن المبدأ والمنتهى إليه.\rالعاشر: أنه لا يُنتظر البذل والمنع واستدفاعُ الضر إلا منه.\rالمنزلة الثانية للعبد:\rوله فيها مراتب عشر:\rالأولى: التبري من الحول والقوة إليه، والإقرار بما نزل بك منه.\rالثانية: أن تسلم إليه كُلَّك، وتحمل عليه كَلَّك.\rالثالثة: أن لا تجزع من الفقر والضر.\r"], [253, "الرابعة: ألا تفرح بالغنى والصحة.\rالخامسة: ترك التدبير وشهود التقدير.\rالسادسة: التسليم للمراد.\rالسابعة: الرضى بالقضاء.\rالثامنة: ملازمة المأمور ومجانبة المزجور.\rالتاسعة: الأمن من غيره.\rالعاشرة: الخوف من مكره.\rومن خصائص العبودية ما يروى أن يحيى بن معاذ قال له بعض الملحدة: (أخبرني عن الله ما هو؟\rفقال له يحيى: إله واحد.\rقال: فكيف هو؟\rقال يحيى: إله قادر.\rقال: فأين هو؟\rقال يحيى: بالمرصاد.\rقال له: لست عن هذا أسألك.\r"], [254, "قال له يحيى: فالذي تَعني صفة المخلوق، فأما صفة الخالق فما أخبرتك).\r"], [255, "ص 256\r"], [256, "أسماء التنزيه\r"], [257, "ص 258\r"], [258, "القول في الواحد\rاعلموا - أرشدكم الله - أن أول أسماء التنزيه وأَولاها: الواحد، لأنه ركن التوحيد، وعليه مدار الإخلاص ومبناه، لفظاً ومعنىً؛ ولذلك وقعت البداية بالتنزيه به في كلمة التوحيد أولاً، والتصريح بالواحد فيها آخراً، فقال: لا إله إلا الله، ولكنا لما رأينا أن القول في الواحد مبني على القول في أنه موجود رتبناه عليه وصدَّرناه به ليقع البيان مرتباً شافياً.\rفنقول:\rتكلم العلماء - رحمهم الله - في كونه شيئاً، نفساً، عيناً، موجوداً، ذاتاً، فهذه أسماء نحن نذكرها في غاية الشرح، ثم نتبعها بأخواتها، ثم نعطف على بيان الواحد بعد هذا، إن شاء الله.\r"], [259, "الاسم الأول: شيءٌ\r[الفصل الأول: في مَورده]\rوقد ورد به القرآن، قال الله تعالى: {قُلْ أَيُّ شَيْءٍ أَكْبَرُ شَهَادَةً قُلِ اللَّهُ} [الأنعام: 20]، ولم يجر له ولا لأمثاله ذِكْرٌ في تعديد التسعة والتسعين اسماً؛ لأنه ليس من أسماء التضرع، ولكن جرى ذكرُه في ألفاظ النبي صلى الله عليه وسلم قصدَ التبيين والإخبار، كما ورد في القرآن حسَبما بيناه آنفاً.\rولا بد وقد انتهى القول بنا إلى هذا المقام من مقدمة، وهي أن ما يُذكر به الباري سبحانه على قسمين:\rأحدهما: ما يوصف به على وجه البيان له والدلالة عليه.\rوالثاني: ما يذكر به على معنى التعبد والتضرع إليه.\rفإذا ذُكر على معنى البيان فهو عام، وتقع المشاركة فيه بين الخلق وبينه، في إطلاقه كثيراً لضرورة تمييز الخالق من المخلوق، وما ذُكر به على معنى التضرع والابتهال ينبغي أن يكون على غاية الجلال والكمال، فإن الكبير الكريم وَالمَلِكَ العظيم إذا تُوسل إليه ذكر بأفضل صفاته استنزالاً واستدراراً لنِعَمه،\r"], [260, "وإذا أُخبر عنه انطلق اللسان في ذكره بكل ما يُحتاج إليه في البيان عنه، ولذلك روي عن النبي صلى الله عليه وسلم أنه قال في وصف قوم يحبهم الله: (وقوم ساروا ليلتَهم حتى إذا كان النوم أحب إليهم مما يُعدل به فوضعوا رؤوسهم، فقام أحدُهم يتملقني ويتلو آياتي).\rفإذا علمتم هذا فهذه الألفاظ الخمسة وما جرى مجراها لا تصلح للتضرع والابتهال، وإنما هي ألفاظ بيان واستدلال، وهذه المقدمة خير لواعيها من الدنيا وما فيها.\rالفصل الثاني: في معناه لغةً\r"]], "pg": [251, 260]}, "561.31": {"x": [[260, "اعلموا أن علماء اللسان اختلفوا في قولهم (شيء) هل هو مشتق أم لا؟ على ثلاثة أقوال:\rأحدها: أنه اسم مشتق؛ واختلفوا أيضاً في جهة اشتقاقه على قولين:\rفمنهم من قال: إنه فَعْلٌ - بإسكان العين - مصدر شاء يشاء شيئاً، ثم سُمي بالمصدر، كما قيل للذي يُشرب: شراب، وللذي يُكتب: كتاب، قالوا: فالشيء بالحقيقة هو الإرادة، ثم قيل للواقع عن الإرادة وقول المراد: شيء.\r"], [261, "الثاني: أن وزنه فعيل كنصيب وخميس، وكأن أصله شَيْيِءٌ، وكثُر استعماله في الكلام فاستُثقل اجتماعُ الياءين مع كسرة، ويكون فعيل فيه بمعنى مفعول، كجريح بمعنى مجروح، وقتيل بمعنى مقتول، ويرجع إلى المراد في التقدير.\rقالوا: وإنما قلنا ذلك فيه لأنا رأيناه لا ينصرف، لأنه لو كان شيء فَعلاً بإسكان العين وجمعُه أفعال، لصُرف الجميع، كما يُصرف أكلابٌ وأشياخٌ، ثم لما رأوا الجمع غير منصرف تباينوا في وجه امتناع الصرف تبايناً عظيماً لم يَحْلَ أكثرُهم فيه بِطائل.\rالثاني: أنه اسم غير مشتق، وإنما هو اسم موضوع للإثبات والوجود، ويقال: شيء، بمعنى موجود، كما يقال: لا شيء، بمعنى معدوم.\rالثالث: أنه على وصفين، تارة يقع مشتقاً، وتارة يقع علماً موضوعاً للإبانة عن الوجود، والأشبه عندي أنه مشتق.\rالفصل الثالث: في شرحه عقيدةً\r"]], "pg": [260, 261]}, "561.32": {"x": [[261, "اعلموا - رحمكم الله - أن المتكلمين اختلفوا في معنى هذه الكلمة على نحو من عشرين قولاً؛ على ما حكاه شيخ السنة في كتاب المختزَن\r"], [262, "الكبير، في أقوال ساقطة يطول ذِكرها والتتبع لإفسادها، ونحن لم نتعرض لموضعها في كتب الأصول، فكيف أن نذكرَها هاهنا، وهي فيه تَبَعٌ.\rوالذي نفتقر إليه هاهنا تحقيق معناه خاصة، وذلك أن ما اختلف فيه علماء اللغة قد سردناه، وإذا حققناه وتحققناه علمنا أن اللفظ متى جرى مشتقاً وصحّ معناه به لم يكن لإنكار اشتقاقه وجهٌ.\rوقد ظهر تصرفُ (شي) وجريانُه على الفعل، وأنه مصدر سُمي به، فلا وجه لإنكاره.\rفإن قيل: بل هو عَلَمٌ موضوع، والدليل عليه أمران:\rأحدهما: أنه على الوجه الذي أشرتم إليه يكون الشيء هو المراد، والباري لا تتعلق به الإرادة، لأن الإرادة إنما تتعلق بالمحدَث.\rالثاني: أنه إن قلتم: إن الإرادة لما تعلقت بالمُحدث خاصة، وكان شيئاً موجوداً، لأنه مرادٌ شبَّهتم به الموجود الأول على المجاز، وهو تعالى شيءٌ باتفاق العلماء من الطائفتين؛ المُؤالِفة والمُخالِفة.\rالجواب: أنا نقول: ليس هذا الفن المسؤول عنه من باب كثير من الناس، وإنما هو للمتبحرين المتغلغلين في علم اللسان والحقائق معاً، ولقد كاشفتُ المحققين من المشيخة رضي الله عنهم، والذي تحصَّل من لُباب القول فيه بعد حذف فضوله الذي يستقل بدرْكها الفَطِنُ: أن قولنا: شيءٌ، مصدر يُسمى به الموجود، كما قلنا وطردنا ودللنا عليه وبيّنّا.\r"], [263, "وأما قولهم: إن إطلاقه مجاز في حق الباري، فكذلك نقول: إنه في الأصل مجاز، ولكن غلب عليه الاستعمال حتى امَّحت حقيقتُه وصار مجازه أحق به، ومن ذلك في اللغة كثير يطول تَعداده، واستعمال المجاز في حق الله سبحانه جائزٌ باتفاق من الأمة، لا سيما مجاز غلب عليه الاستعمال فحق.\rولقد قال لي أعظم العلماء رتبةً وأقواهم عارضة: (إن أحداً من البشر لا يستطيع أن يعبِّر عن الله إلا مجازاً)، كما بيناه قبل، فكيف أن يتردد في ذلك في لفظ قُصد به البيان دون التضرع والابتهال؟ لا سيما والمجاز نوع من اللغة، كما أن الحقيقة نوع، والغرض بهما حُسْنُ التعبير في البيان عن المراد، ولهذه الدقيقة ما قلنا: إنه للبيان لا للتضرع.\rيزيده بياناً: أن جهماً وإخوانه من المبتدعة قالوا: لا نسمي الباري شيئاً؛ وإنما ابتدع هذه البدعة بعد مضي عصر من أهل الإسلام، أجمعوا على إطلاق ذلك عليه حين وجدوه في كتاب الله مضافاً إليه، ولكنه لما نظر\r"], [264, "إلى ظاهر الاشتقاق وأن إضافة ذلك إلى الله محال ذهِل بخِذلانه عن إطلاق اللفظ في الكتاب، ودرس لبُّه عن فهم هذا اللباب، وقد بينا القول فيه على وجه لم يبق فيه مستغلَق، ولا سببٌ لأحد فيه متعلَّق.\rفإن قيل: لو كان شيء مشتقاً مصدراً جاء على فعل شاء لجُمع على الأشياء ولصُرف، لأن كل فعل جمع على أفعال ينصرف، فلما لم ينصرف أشياء دل على أنه لفظ جامد جارٍ على غير ما ذكرتم.\rالجواب: أنا نقول: نحن إنما تكلمنا في قولنا شيء، وطردنا القول فيه بالبيان حتى أنهيناه حقه، ونحن نجمعه على أفعال ونصرفه إذا نوينا ذلك به، وإذا ذكرنا أشياء ولم نصرفها جرت على وجه آخر بيانه في كتب\r"], [265, "العربية، عليه جاء قوله تعالى: {لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ} [المائدة: 101].\rوجواب آخر: وذلك أن فَعلاً إذا جمع على أفعال في السالم صُرف، وفعل جمع على أفعال في المعتل، والمعترض لم نر له في ذلك مثالاً يناقضنا به، ولذلك قال علماء العربية: إن وزن أشياء أفعِلاء، وقال آخرون: لها وزن آخر، ولم يجعلها أحد منهم جمع شيء أفعالاً.\rوهذا القدر كافٍ للبيب المنصف، وربما لمحه من يزوي حاجبه، وَيَهُزُّ مناكبَه، ولكن لا بد - بفضل الله - له من منصف يمسح جوانبه، ويشرح عجائبه.\r"], [266, "اللفظ الثاني: نَفْسٌ\rوفيه ثلاثة فصول:\rالأول: في مورده.\rالثاني: في شرحه لغة.\rالثالث: في شرحه حقيقةً، وهو مندرج في الفصل الثاني.\rالفصل الأول: في مورده\r"]], "pg": [261, 266]}, "561.33": {"x": [[266, "قال الله تعالى: {كَتَبَ رَبُّكُمْ عَلَى نَفْسِهِ الرَّحْمَةَ} [الأنعام: 54]، وقال: {وَيُحَذِّرُكُمُ اللَّهُ نَفْسَهُ} [آل عمران: 30]، وقال: {تَعْلَمُ مَا فِي نَفْسِي وَلَا أَعْلَمُ مَا فِي نَفْسِكَ} [المائدة: 116]، فهذه أصول بينة في إضافة النفس إلى الله، ولم يرد في جملة التسعة والتسعين، لأنه ليس باسم تضرع، وجرى ذكرُه في اللفظ للنبي صلى الله عليه وسلم قصدَ التبيين.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [266, 266]}, "561.34": {"x": [[266, "فنقول: إنه يرد مطلقاً على خمسة معانٍ:\rالأول: إطلاق العرب النفس على الشيء نفسِه، وعلى هذا ورد قوله: {وَيُحَذِّرُكُمُ اللَّهُ نَفْسَهُ} [آل عمران: 30]، وقوله: {كَتَبَ رَبُّكُمْ عَلَى نَفْسِهِ الرَّحْمَةَ} [الأنعام: 54]، وتقول: جاء زيدٌ نفسُه.\r"], [267, "والمعنى: أن قول القائل جاء لما كان يحتمل الحقيقة بأن يكون شخصُه قد وصل إلى الموضع المقصود وحصل فيه، وإما بأن تكون مقدمته الدالة على مجيئه قد ظهرت، فيُخبِر عن المستقبل بالماضي اتكالاً على أمارته الدالة عليه، أو بأن يكون يعايَن فيه أو تُرى آثاره الدالة على أنه قد كان جاء معلومةً، والأول مجاز، والثاني حقيقة، فقولك: (نفسُه) يَدفع المجاز ويوجب وجودَ الشخص حقيقةً في المحل المقصود.\rالثاني: إطلاق العرب النفس على الروح، تقول العرب: فاضت نفس فلان، أي خرجت روحه، وبه سُميت النفس نفساً؛ لأنه من النفَس، كالروح من الريح في أحد الوجوه، وعليه حُمل قوله: (أجد نفَس ربكم من قِبل اليَمَنِ)، أي تنفيسُه الكُرَبَ بالأنصار ومعاضَدَتهم له، أو بفتح مكة.\rالثالث: إطلاق العرب النفس على الدم، وجهه: أن بقاء الروح في الجسد لما كان مقروناً ببقاء الدم، وخروجَه مقروناً بخروجه من إحدى الجهتين سمي نفساً.\r"], [268, "الرابع: إطلاق العرب النفس على الغيب، تقول: في نفسي أن أفعل كذا وكذا، أي هذا مما أضمره في غيبي، وعليه خرج قوله تعالى: {تَعْلَمُ مَا فِي نَفْسِي وَلَا أَعْلَمُ مَا فِي نَفْسِكَ} [المائدة: 116]، أي: تعلم غيبي وإضماري، ولا أعلم غيبك ولا الخَفي من قضائك.\rالخامس: تقول العرب: جاء من ذي نفسه، ومن ذات نفسه، قال أهل العربية: أي طَبْعاً، والذي عندي أنه أراد جاء بما ظهر له لا برأي رآه له غيره.\rالفصل الثالث: [في شرحه عقيدةً]\r"]], "pg": [266, 268]}, "561.35": {"x": [[268, "إذا علمتم وجوه الإطلاق فالحقيقة منه ثلاثة، والمجاز اثنان، وتحقيق ذلك من فن اللغة، وكل واحد من الإطلاقات جائز في حق الله، مستعمل فيه كتاباً وسنةً، إلا كون النفس بمعنى الدم، وكونه بمعنى الروح، يُقال: نفسُ الباري، ويُعنى به: هو تعالى، ويقال: نفس الباري، يعني: تنفيسُه الكُرَبَ، ويقال: نفس الباري، بمعنى: غيبِه، وأكثر ما يُطلِقه المتكلمون على الباري نفسِه، وهو على ما قُلناه تصرُّفاً واعتقاداً.\r"], [269, "اللفظ الثالث: عَيْنٌ\rوفيه ثلاثة فصول:\rالفصل الأول: في مورده شريعةً\r"]], "pg": [268, 269]}, "561.36": {"x": [[269, "وقد قال الله تعالى: {وَاصْنَعِ الْفُلْكَ بِأَعْيُنِنَا} [هود: 37]، وقال: {وَلِتُصْنَعَ عَلَى عَيْنِي} [سورة طه: 39]، وقال: {وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا} [سورة الطور: 48].\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [269, 269]}, "561.37": {"x": [[269, "لفظ العين يرد لغة على وجوه يكثر تعدادها، جاء في كل واحد منها بمعنى مشترك الدلالة، والذي يتعلق منه بما نحن فيه أنه يقال:\rالعين في مصدر عان يَعين عَيناً: إذا ظهر، ومنه: العين الماء الجاري على وجه الأرض، وسُميت العين الناظرة عيناً لأن فيها وبها تظهر المرئيات، وقد جاء الظاهر في أسمائه تعالى على ما يأتي بيانُه، إن شاء الله.\rوتقول العرب: جاء زيدٌ عينُه، على معنى التأكيد، كما تقول: جاء فلان نفسُه، ويعنون بقولهم: (عينه): ظهورَ شخصه وتحقيق رؤيته من غير مجاز فيه برؤية مقدمة له أو أثر دال على مجيئه.\r"], [270, "الفصل الثالث: في شرحه عقيدةً\r"]], "pg": [269, 270]}, "561.38": {"x": [[270, "اعلموا أن الإطلاقات التي جاءت بذكر العين مضافاً إلى الله تعالى ليست على معنى الإثبات له الذي أشرنا إليه فيمعنى الشيء والنفس، وإنما وردت عبارةً عن بصر الباري للمبصَرات، فيكون ذلك من الصفات المشكِلات؛ كالوجه واليدين اللواتي شرحنا معناها في موضعه، ولكن أطلقه علماؤنا على الباري تعالى بمعنى أنه شيءٌ نفسٌ، وذلك بوجهين:\rأحدهما: أنهم رأوا العرب تقول: جاء زيدٌ عينُه، كما تقول: جاء زيد نفسُه، ويَعنون به الإثبات، ولا يفرِّقون بينهما.\rالثاني: أنهم رأوا اللفظ قد ورد في صفاته في القرآن، فأجروا اللفظ عليه لوجود المعنى فيه، ولورود الإطلاق به، لما كان من الصفات الممدَّحة، فذلك أقرب في الاستعمال.\r"], [271, "اللفظ الرابع: ذَاتٌ\rوفيه ثلاثة فصول:\rالفصل الأول: في مورده شرعاً\r"]], "pg": [270, 271]}, "561.39": {"x": [[271, "لفظ ذات لم يرد في القرآن ولا في السنة على لسان النبي صلى الله عليه وسلم، وإنما ورد في شِعر خُبيب حين أسره أهل مكة، فلما أخرجوه للقتل قال:\rوذلك في ذات الإله وإن يشا ... يبارِك على أوصال شِلْوٍ مُمَزَّعِ\rوقد روي في حديث أبي بن كعب عن النبي صلى الله عليه وسلم أنه قال: (إن ذات الدين عند الله الحَنيفية المسلمة).\r"], [272, "الفصل الثاني: في شرحه لغةً\r"]], "pg": [271, 272]}, "561.40": {"x": [[272, "اعلموا أن الذات في اللغة كلمة تستعمل صفة للمؤنث، وأختها التي، كما أن ذو كلمة تستعمل صفة للمذكر، وأخوه الذي، إلا أن الذات لا تأتي بمعنى التي، وذو يأتي بمعنى الذي، كقول الشاعر:\rوبئري ذو حفرتُ وذو طويتُ\rومعنى إضافتها التوصل بها إلى وصف الموصوف بما أضيف إليه. تقول: فلان ذو علم، فتصفه به، كما تقول: عالم؛ وفلانة ذات جمال، كما تقول: جميلة. وكلاهما وصف، إلا أن أحدهما أطول عبارة من الثاني، والمعنى فيهما واحد.\rوقد يتفق الوصفان في اللفظ؛ كما تقول: فلانة ذات جمال، وفلانة جميلة.\rوقد يختلفان؛ كما تقول: فلانة ذات مال، وفلانة غنية، فتنقله على المعنى.\rويضاف تارة إلى المعاني، وتارة إلى الأعيان، وعليه جاء قول الله تعالى: {وَاللَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ} [التغابن: 4]، وقوله: {ذَاتَ الْيَمِينِ وَذَاتَ الشِّمَالِ} [الكهف: 18]، وقول النبي صلى الله عليه وسلم: (ذات الدين عند الله)، وقول خبيب: (وذلك في ذات الإله)، وقول النابغة:\r"], [273, "مَجَلَّتُهُمْ ذاتُ الإله ودينُهم\rوالمعنى في قول خبيب: وذلك في الخَصلة المختصة بالإله، وهي طاعتُه، والمعنيُّ بالذات في قول النابغة إن رويناه محلتهم بالحاء المهملة: المنزل المختص بالإله، وهو بيت المقدس وأرض الأردن، وإن رويناه مَجَلَّتهم بالجيم فيعني به كتابَهم المنزَل من عند الله المختص به، وهي الحكم والمواعظ الزاجرة عن الفواحش والمنكرات.\rوكما يضاف إلى النكرات فيقال: فلان ذو علم، فقد يضاف إلى المعارف فيقال: ذو زيد، والمعني به: الشخص المختص بهذا الاسم.\rوهذه جملة كافية في المقدمات، وقد بسطنا القول فيها في كتاب مُلجئة المتفقِّهين.\rالفصل الثالث: في شرحه عقيدةً\r"]], "pg": [272, 273]}, "561.41": {"x": [[273, "إذا ثبت هذا فاعلموا - أفادكم الله المعارف - أن علماءنا تكلموا في هذه اللفظة بوجهين:\r"], [274, "أحدهما: إطلاقهم ذكر الذات.\rالثاني: نسبتهم إليه ذلك في تقسيمهم الأوصاف على ضَربين؛ ذاتي ومعنوي.\rفأما إطلاقهم ذِكر الذات غيرِ مضافة، وهي لم ترد في كلام العرب إلا مضافة، فذلك جائز قصد التعبير والإفهام، لا يمنع من ذلك حكم عربي، بل هو جارٍ في أساليب العربية، مستمر على هداها، فإنا كما نقول: ذات مال، فنجمع بين الذات والمال في هذه الإضافة، ثم نُفرد المال فنقول: مال، فيُفيد، كذلك نفرد الذات فنقول: ذات، فتفيد، فإن الكلمة بانفرادها تفيد معرفة، وباجتماعها مع غيرها تفيد عِلماً.\rفلما كانت الذات في لسان العرب تقع وصفاً للمعاني والأعيان مضافةً إلى ما يفيد وصفَها بما أضيفت إليه، ووردت في الشريعة مضافة إلى الباري تعالى، أطلقها علماؤنا في الخبر عن الله سبحانه إذا احتاجوا إلى ذلك، وفي التعبير عن سائر الأشياء على الذات المجردة، خاصة إذا أرادوا إفادتها مفردة قصد البيان، وهذا كلام وارد على سواء الطريق، بالغ في فن التحقيق.\r"], [275, "وأما نسبتهم إليها بقولهم: وصفٌ ذاتي ومعنوي، فلا يجري على أسلوب العربية.\rولا يجوز في اللسان، لأن ياء النسب لا تجتمع مع هاء التأنيث لأمر معلوم عندهم.\r"], [276, "اللفظ الخامس: موجود\rوفيه ثلاثة فصول:\rالفصل الأول: في مورده شريعةً\r"]], "pg": [273, 276]}, "561.42": {"x": [[276, "اعلموا أنه لفظ أطلقه علماؤنا عليه سبحانه، وقالوا: إنما أطلقناه عليه بإجماع الأمة، وهذا وهم منهم، فإن الأمة لم تجمع عليه لوجهين:\rأحدهما: أنه لم يجر في ألفاظ الصحابة والتابعين، وإنما كان إطلاقه بين المتكلمين.\rالثاني: أن من المتكلمين من خالف فيه، فقال: لا أقول إنه موجود.\rوالصحيح أن علماءنا أطلقوه حين احتاجوا إليه لورود الشرع به، وذِكر الله سبحانه في كتابه له مخبراً عن نفسه، قال تعالى: {وَوَجَدَ اللَّهَ عِندَهُ فَوَفَّاهُ حِسَابَهُ} [سورة النور: 38]، وهذا إذن صريح ونص صحيح في إطلاق\r"], [277, "اللفظ، وهو من قبيل المعبود والمستعان، على ما يأتي بيانُه في موضعه، إن شاء الله.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [276, 277]}, "561.43": {"x": [[277, "الموجود في لسان العرب هو المعلوم، لا فرق عندهم بين قولهم: وجدته أجدُه وجداناً فهو موجودي، كما قالوا: علمتُه أعلمه عِلماً فهو معلومي، والدليل عليه قوله تعالى: {وَوَجَدَ اللَّهَ عِندَهُ}.\rالفصل الثالث: في شرحه حقيقةً\r"]], "pg": [277, 277]}, "561.44": {"x": [[277, "وهو المعتقد، وفيه ثلاث مسائل:\rالمسألة الأولى:\r"]], "pg": [277, 277]}, "561.45": {"x": [[277, "اعملوا - بصَّركم الله الحقائق - أن بعض علمائنا قالوا: إن قولنا موجود يُستعمل على وجهين:\rأحدهما: مقيد، وهو كقول القائل: وجدت الشيء أجده فهو موجودي، بمعنى علمته فهو معلومي.\rالثاني: المطلق الذي ليس فيه تقييدٌ ولا إضافة، فهذا لا يقال فيه وجدته، ولا هو موجودي، وهو الذي يُراد به الثبوتُ المطلق، والكون الذي هو خلاف المعدوم، والرب سبحانه موصوفٌ بالوجهين جميعاً.\rقال الإمام الحافظ رضي الله عنه: هذا كلام فاسد، فإنه تحكمٌ في التقسيم، وسردُ ما لا أصل له في التعلم والتعليم، فإنا نقول:\r"], [278, "إن الموجود في اللغة هو المعلوم بعد طلب، ليس له في اللغة معنى سواه، ومن أطلق من العلماء الموجود على الثابت إنما هو اصطلاح منهم لا مدخل له في اللغة، وعجباً لهذا العالم، فإنه قال:\r(كيف يصح أن يقال فيه: إنه موجود على معنى أنه معلوم، يقتضي كونه على هذا موجوداً أكثر من تعلق العلم به، والعلم يتعلق بالمنفي المعدوم كما يتعلق بالثابت، والرب ثابت، فدل على أن ذِكر الموجود فيه عبارة عن الثابت المطلق، عُلم أو لم يُعلم).\rوهذا إغفال عظيم، فإن قول (معلوم) الذي يفسره قول (موجود) يوصف به تعالى ويتعلق به، ويلزم على قولك (معلوم) ما يلزم على قولك (موجود)، فكما يوصف بأنه معلوم مع أنه ثابت، والعلم يتعلق بالثابت والمنفي، كذلك يوصف بأنه موجود سواء بسواء، وهذا يدل على أنه لا فرق بينهما.\rالمسألة الثانية:\r"]], "pg": [277, 278]}, "561.46": {"x": [[278, "أنكر جهمٌ وصِنوه من الملحدة وصفه بأنه موجود، وزعموا أن فيه تشبيهاً بالمحدَث، وإذا أقروا بكونه معلوماً ففيه أيضاً تشبيه به، وحقيقة الشبه قد بيناها في كتب الأصول، وحددنا المثلين وبينا ما يجتمعان فيه من الأوصاف، حتى يَثبُت لهما هذا الوصف بما يقع به البيان، وقد دللنا على أنه موجود بما يبين فساد مقالة جهم وصِنوِه.\r"], [279, "المسألة الثالثة: في تحقيق القول فيه\r"]], "pg": [278, 279]}, "561.47": {"x": [[279, "اعلموا - رزقكم الله الإنصاف - أن علماءنا - رحمة الله عليهم - قالوا: إن العلم يتعلق بالمعدوم كما يتعلق بالموجود، واختلفوا لذلك في حده، وكان الأستاذ أبو إسحاق يَحُدُّ العلم بأنه معرفة الشيء؛ وكان أحبارُنا ينكرون ذلك عليه، وقالوا: كيف يُحَدُّ العلم بأنه معرفة الشيء، والمعدوم معلوم وليس بشيء؟\rوقال المتحققون بالصناعة هاهنا: إن المعدوم ليس بشيء حقيقة، ولكنِ العلمُ لا يتعلق بالمعدوم مضافاً إلى حالة العدم، فإن ذلك لا يمكن تصويرُه ولا تقديرُه، بل العلم أبداً لا يتعلق إلا بموجود محقق أو بموجود مقدر، فإذا عُدم الموجود أو كان معدوماً لم يتقدر له وجود، فالعلم إنما يتعلق بحالته الماضية مقدرة في الخَلَدِ أو بحالته الأُنُفِ مقدرةً في الوجود أيضاً، وإن كان مما لا يمكن فيه وجودٌ كالمعدوم المستحيل وجودُه، فإنما يتعلق به\r"], [280, "العلم على تقدير الوجود أن لو كان، فأما تقدير تعلق العلم أو تصوره بالعدم المحض على غير إحالة على وجود محقق أو مقدر فذلك مما لا يتكلم به بشر.\rفثبت بهذا أن وصفنا له تعالى بأنه موجود، كوصفنا له بأنه معلوم، حسب ما ورد ذلك منه مخبِراً به عن نفسه ومنا، من غير أن يتعين له بذلك حكمٌ، ولا يتغير له به وصف.\rوهذا فصل عجيب وفق الله لفهمه، وبعد ذلك استعمله علماؤنا في الكائن الثابت، وعلى هذا يقال: الله موجود، واجد لنفسه، موجود لنفسه، والخلق له واجدون، وهو لنا موجود لقوله: {وَوَجَدَ اللَّهَ عِندَهُ} [النور: 38].\r"], [281, "اللفظ السادس: ثابت\rوفيه ثلاثة فصول:\rالفصل الأول: في مورده شريعةً\r"]], "pg": [279, 281]}, "561.48": {"x": [[281, "وفيه تندغم الفصلان الباقيان لقربهما منه.\rاعلموا أنه لفظٌ لم يرد به قرآن ولا سنة ولا أجمعت عليه الأمة، لكن استعمله علماؤنا - رحمة الله عليهم - في العبارة عن الموجود الذي لم يَشُبْ وجودَه ريبٌ، وهو لفظ تستعمله العرب في المعاني فتقول: ثبت هذا العلم وهذا الحكم، كما تستعمله في الأجسام، قال تعالى: {أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِي السَّمَاءِ} [إبراهيم: 24]، وهو اسم بيان وتعليم، لا اسم تضرع وابتهال.\r"], [282, "اللفظ السابع: كائن\rوفيه ثلاثة فصول:\rالفصل الأول: في مورده شريعةً\r"]], "pg": [281, 282]}, "561.49": {"x": [[282, "وفيه تندغم الفصلان.\rاعلموا أنه لفظ لم يرد به كتاب ولا سنة ولا أجمعت عليه الأمة، لكنْ علماؤنا - رضي الله عنهم - أطلقوه اسماً لمّا رأوا الله قد أخبر به عن نفسه فعلاً في قوله: {وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا}، {عَزِيزًا حَكِيمًا}، {بِكُلِّ شَيْءٍ عَلِيمًا} [النساء: 95 - 157 - 32].\rوهذا عندي وهم، لأن الكائن فاعلٌ من كان، وكان عبارة عن حالة ماضية للمخبَر عنه في الحقيقة، وذلك يرد خبراً عن المعدوم كما يرد خبراً عن الموجود، فتقول: كان الشيء معدوماً، كما تقول: كان موجوداً ثم عدم، فلا وجه لإضافته إلى الباري مطلقاً ولا وصفه به، فيقال: إنه كائن.\rنعم، ولا يقال في الموجود حتى يضاف إلى ما كان عليه أو يكون، فيخبَر عنه تقييداً بما يصح الخبر به عنه، والله أعلم.\r"], [283, "اللفظ الثامن: القائم\rوفيه ثلاثة فصول:\rالفصل الأول: في مورده شريعةً\r"]], "pg": [282, 283]}, "561.50": {"x": [[283, "قال تعالى: {أَفَمَنْ هُوَ قَائِمٌ عَلَى كُلِّ نَفْسٍ بِمَا كَسَبَتْ} [الرعد: 33]، وقال تعالى: {اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ} [البقرة: 255]، وفي قراءة عمر: الحي القَيَّام، وفي مصحف ابن مسعود: القَيِّم.\rوروى أبو راشد الأزدي أنه ورد على النبي صلى الله عليه وسلم فقال له رسول الله صلى الله عليه وسلم: (ما اسمك؟ قال: عبد العزى أبو معاوية، قال: بل أنت عبد الرحمن أبو\r"], [284, "راشد، قال: فمن ذا الذي معك؟ قال: مولاي، قال: ما اسمه؟ قال: قيوم، قال: لا، ولكنه عبد القيوم) رواه الدارقطني، ورواه عبد الغني الحافظ كذلك.\rورواه ابن رِشدين قال: (ما اسم مولاك؟ قال: القَموم، قال: بل اسمه القيوم)، والدارقطني وعبد الغني أحفظ وأوثق.\rوقال علماؤنا - رحمة الله عليهم -: الباري تعالى قائم بنفسه، معناه أنه لا يفتقر في وجوده إلى سواه.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [283, 284]}, "561.51": {"x": [[284, "هذا اللفظ عند استقراء موارده يرد في إطلاق اللغة على ثلاثة أوجه:\r"], [285, "[الأول]: يقال: قام فلان إذا انتصب وعلا، كما يقال قعد لانخفاضه.\rالثاني: يقال: فلان قائم بهذا الأمر: مستقل به، حتى ينقضي الغرض فيه والمراد منه.\rالثالث: أن القيام: الملازمة للشيء، كما قال تعالى: {إِلَّا مَا دُمْتَ عَلَيْهِ قَائِمًا} [آل عمران: 75]، ومنه أو هو قولهم: الحرب قائمة بين بني فلان، وقولهم: البيت قائم بهذه الخشبة، وربما كان من الثاني، وهو الأشبه.\rالفصل الثالث: في بيان حقيقته\r"]], "pg": [284, 285]}, "561.52": {"x": [[285, "وفيه خمس مسائل:\rالمسألة الأولى:\r"]], "pg": [285, 285]}, "561.53": {"x": [[285, "اعلموا - وفقكم الله - أن الناس اختلفوا في موارد اللغة التي سيقت:\rفمنهم من قال: إنها حقيقة.\rومنهم من قال: إن الأول حقيقة، وباقيها مجازٌ عليه، وملحق في حد التشبيه به.\rوأنا إلى هذا الآن أميَل؛ لما بينته في غير كتاب من أن كل معنى محسوس سابق للمعنى المعقول متقدم عليه، فإذا سمت العرب محسوساً بمعنى وسمت به المعقول فالمعقول محمولٌ على المحسوس ضرورةً، لأنه الثاني، وهذا بديعٌ في بابه قررناه في كتاب المحصول وغيره.\r"], [286, "المسألة الثانية: في قول العلماء في وصف الباري به\r"]], "pg": [285, 286]}, "561.54": {"x": [[286, "اختلفت عباراتهم في ذلك على وجوه كثيرة ذكرناها في كتاب المقسط، أصولها ثلاثة:\rفمنهم من قال: معنى كونه قائماً بنفسه: أنه لا يحتاج في وجوده إلى مكان.\rومنهم من قال: معنى كونه قائماً بنفسه: أنه موصوف بصفاته العُلى، وهذه حقيقة.\rومنهم من قال: إن معناه: أنه مستغن عن كل شيء، كما يقال: فلان قائم بنفسه في هذا الأمر.\rوالصحيح أن وصفه بأنه قائم لا يصح مطلقاً حتى يضاف إلى ما يتبين به المراد فيه؛ لاختلاف اللفظ المطلق منه عليه.\rفإن قلت: إنه قائم على كل نفس بما كسبت فصحيح معنى، وارد شرعاً.\rوإن قلت: إن الباري قائم بنفسه فهذا معنى صحيح، لكنه لم يرد به شرع، وإنما أطلقه علماؤنا لاحتياجهم في البيان إلى استغناء الباري عن كل شيء في كل وجه، ووجدوا العرب تسمي المستقل بالأمر: قائماً به، ووجدوا اللفظ نفسه وارداً في الشرع فعبروا به عنه.\r"], [287, "المسألة الثالثة: في معنى قوله: {أَفَمَنْ هُوَ قَائِمٌ عَلَى كُلِّ نَفْسٍ بِمَا كَسَبَتْ} [الرعد: 33]\rاختلفت في ذلك عبارةُ العلماء على أربعة أقوال:\rالأول: قائم عليها بما كسبت من رزق تفضلاً.\rالثاني: قائم عليها بما كسبت من عمل يحفظه عليها، فيكون الأول خارجاً مخرج الامتنان، والثاني مخرج الوعيد.\rالثالث: قائم عليها منشئٌ لها، مطلع عليها، لا يخفى عليه من أمرها شيء.\rالرابع: أن المراد بذلك الملائكة الموكلون على بني آدم. المعنى: أن الملائكة الموكلين بالحفظ للخلق لا يستوون مع الأصنام، فكيف خالق الملائكة ومدبرها ومن هو قائم عليها؟\rوهذا القول الرابع وإن كان مفيداً للمعنى ولكنه مجاز جداً، والأقوال الأول أشبه لأنها ظاهرة وحقيقة، فلا يُعدل عنها لغير ضرورة.\rالمسألة الرابعة: في المختار\r"]], "pg": [286, 287]}, "561.55": {"x": [[287, "أما بعد بيان الأقوال والاحتمالات لغة وحقيقة، وإتباعها بذكر عبارات العلماء في تفسيره، فلا يظهر إلا أنه لفظ مقيد، فهو قائم على كل نفس بجميع معاني القيام؛ من خلق وحفظ ورزق، وكل معنى يتعلق بها.\rوإذا كان قائماً عليها بكل وجه فهو غني عنها بالإطلاق كما بيناه، فهذا صحيح، والتفسير الذي ذكرنا واجب، وما عبر به العلماء سائغ في البيان دون التضرع، وهذا نهاية في البيان والاختصار، والله الموفق لا رب غيره.\r"], [288, "المسألة الخامسة: في القيوم\r"]], "pg": [287, 288]}, "561.56": {"x": [[288, "قد تقدم مورده، وشرحه في اللغة يطول، لكن اختصاره أن القيوم في اللغة: فيعول من قام، أصله القيووم، فلما اجتمعت الياء والواو وسبق الساكن شُدِّدَ على الياء، وأما القيام فهو الفيعال، أصوله القيوام، فلما اجتمعت الواو والياء والسابق ساكن شدد على الياء، وقال: أهل الحجاز يصرفون الفعَّال إلى الفيعال، يقولون للصوّاغ: صيّاغ.\rوأما القيم فاختلفوا فيه، فقال سيبويه: وزنه الفيعل، وأصله القيوم، فلما اجتمعت الياء والواو وسبق الساكن أبدل من الواو ياءٌ وأدغموا فيها التي قبلها فصارت ياءً مشددة؛ كما في سيد وميت وهين ولين وأخواتها.\rوأنكر الفراء هذا وقال: ليس في أبنية العرب فيعِل، وقال في الأمثلة كلها: أصله فعيل بكسر العين على وزن كريم وظريف، وكان يلزمهم أن يجعلوا الواو ألفاً لانفتاح ما قبلها، ثم يسقطونها لسكونها وسكون الياء التي\r"], [289, "بعدها، فلما فعلوا ذلك صار فعيل على لفظ فعِل، فزادوا ياءً على الياء ليكمُل بها بناءُ الحرف، والحي أصله الحَيْوُ، فلما اجتمعت الياء والواو والسابق ساكن جُعلتا ياء مشددة.\rوبعد معرفة شرحه لغة فقد قال علماؤنا فيه ثلاثة أقوال:\rالأول: أن القيوم هو الدائم الذي لا يزول.\rوالثاني: أنه القيم على كل شيء بالرعاية له، والمدبر لجميع أمور العالَم.\rالثالث: أنه الذي لا تفنيه الدهور، ولا يتغير بانقلاب الأمور.\rفعلى القول الأول يكون بمعنى الباقي الدائم، وعلى القول الثاني يكون بمعنى الحفيظ والمدبر، وعلى القول الثالث يكون بمعنى الثابت القدوس.\rوالصحيح عندي أنه مبالغةُ قائم من قام إذا أطلق، فإذا أضيف كان بمعنى المضاف إليه، كما قلنا في تأويل القائم على كل نفس بما كسبت إذا أضيف إليها وإذا أفرد عنها، والله أعلم.\r"], [290, "الاسم التاسع: الكافي\rوفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [288, 290]}, "561.57": {"x": [[290, "قال الله تعالى: {أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ} [الزمر: 36]، ووردت به السنة في حديث أبي هريرة من طريق عبد العزيز بن الحصين، وكان النبي صلى الله عليه وسلم إذا فرغ من طعامه قال: (الحمد لله الذي أطعمنا وسقانا وكفانا وآوانا، وكم ممن لا كافي له ولا مؤوي).\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [290, 290]}, "561.58": {"x": [[290, "قال بعض علمائنا: الكفاية دفع المكروه المخوف، يقال: كفاه يكفيه إذا دفع عنه.\rالفصل الثالث: في شرحه حقيقةً\r"]], "pg": [290, 290]}, "561.59": {"x": [[290, "فيه مسألتان:\r"], [291, "المسألة الأولى: في تحقيق المعنى\r"]], "pg": [290, 291]}, "561.60": {"x": [[291, "اعلموا - وفقكم الله - أن حقيقة الكفاية: القيام بالشيء والاستقلال به، ومنه قول العرب: فلان كافيك من رجل، ورجلان كافياك من رجل، ومررت برجل كافيك من رجال. والكُفية: القوت، وجمعها كُفىً.\rالمسألة الثانية:\r"]], "pg": [291, 291]}, "561.61": {"x": [[291, "إذا علمتم حقيقة الكفاية فيحتمل على هذا أن يكون الكافي من كفى، أي قام بالأمر، كقوله: {كَفَى بِاللَّهِ شَهِيدًا} [الرعد: 43]، {وَكَفَى بِاللَّهِ حَسِيبًا} [الأحزاب: 39]، فيعود معناه إلى قوله: القائم والقيوم، ويحتمل أن يكون من كفاه: إذا دفع عنه الحاجة إلى الكُفية أو المضَرَّة، وعليه يدل قوله: (وكم ممن لا كافيَ له ولا مُؤوي) فيعود إلى صفات الفعل.\r"], [292, "اللفظ العاشر: حَقٌّ\rوهو اسم بديع من أسمائه الحسنى، ووصف من أوصافه العُلى، اختص به المتعبدون من هذه الأمة، فلا يُخبِرون عنه إلا به، لما عاينوا من كثرة الباطل، وشاهدوا من غلبة المُحال، عظُم قدرُه في الملة، وعم ذكره في الشريعة.\rأما عِظَمُ قدره فلأن مبنى الدين كله عليه؛ وأما عموم ذكره فلأنه ينطلق على كل فرع وأصل وقول وعمل، وتستعمله كل طائفة، وتدعيه كل أمة، ونحن نشبع القول فيه، ونبين جميع موارده ومعانيه، بحول الله وفضله.\rوفيه أربعة فصول:\rالفصل الأول: في مورده شريعةً\r"]], "pg": [291, 292]}, "561.62": {"x": [[292, "اعلموا أن القرآن ورد به والسنة، وأجمعت عليه الأمة، قال الله تعالى: {ثُمَّ رُدُّوا إِلَى اللَّهِ مَوْلَاهُمُ الْحَقِّ} [الأنعام: 62]، وقال: {فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ} [طه: 116]، وقال تعالى: {أَنَّ اللَّهَ هُوَ الْحَقُّ الْمُبِينُ} [النور: 25]، وقال النبي صلى الله عليه وسلم في دعائه: (أنت الحق، وقولك الحق، ووعدك الحق)، إلى آخر الخبر.\r"], [293, "الفصل الثاني: في شرحه لغة\r"]], "pg": [292, 293]}, "561.63": {"x": [[293, "اعلموا - وفقكم الله - أن الحق في اللغة: مصدر حق الشيءُ يحق حقاً: إذا كان موجوداً.\rوينطلق على الاعتقاد والقول والعمل، ومنه قوله صلى الله عليه وسلم المأثور عنه: (السحر حق، والعين حق)، أي موجود صحيح، وهذا هو المعنى اللغوي، لأن العرب لم تتكلم إلا في المحسوسات، وقد قال الشاعر:\rقد قيل ما قيل إن حقاً وإن كذباً\r"], [294, "وتقول العرب: إن فلاناً الرجل حق الرجل، والشجاع حق الشجاع، وحاق الشجاع، وحاقة الشجاعة.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [293, 294]}, "561.64": {"x": [[294, "وفيه أربع مسائل:\rالمسألة الأولى: في سرد أقوال علماء الإسلام فيه\r"]], "pg": [294, 294]}, "561.65": {"x": [[294, "وقد أورد عنهم المؤلفون في ذلك أحد عشر قولاً:\rالأول: أن الحق في صفة الله تعالى: هو الموجود الذي ليس بمنتفٍ ولا معدوم، وقد تقدم ذلك في شرحه لغة، وكل موجود حق، وكل حق موجود عندهم، وعلى هذا جاء قوله صلى الله عليه وسلم: (أنت الحق، وقولك الحق، ووعدك الحق، ولقاؤك حق، والجنة حق، والنار حق، والساعة حق)، المعنى في أحد وجوه ذلك كله: الموجود، مع ما يأتي بيانه إن شاء الله، وكذلك روي: (السحر حق والعين حق)، أي ذلك موجود، وإن كان باطلاً لأنه منهي عنه.\rالثاني: الحق في صفة الله: أي ذو الحق، كما قلنا في العدل إنه العادل، لأنه سبحانه هو الذي يُحِقُّ كل حق.\rالثالث: أن الحق: هو الله تعالى في قوله: {وَلَوِ اتَّبَعَ الْحَقُّ أَهْوَاءَهُمْ} [المؤمنون: 71].\r"], [295, "الرابع: أن الحق: هو القرآن لقوله: {حَتَّى جَاءَهُمُ الْحَقُّ وَرَسُولٌ مُبِينٌ} [الزخرف: 29]، وقوله: {بَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ فَيَدْمَغُهُ} [الأنبياء: 18]، وقال: {مَا نُنَزِّلُ الْمَلَائِكَةَ إِلَّا بِالْحَقِّ} [الحجر: 8].\rالخامس: أن الحق: الإسلام، قال تعالى: {وَقُلْ جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ} [الإسراء: 81].\rالسادس: أنه العدل، لقوله: {يَوْمَئِذٍ يُوَفِّيهِمُ اللَّهُ دِينَهُمُ الْحَقَّ} [النور: 25]، ومنه قوله: {الْحَاقَّةُ. مَا الْحَاقَّةُ} [الحاقة: 1]، لأنها تُحِقُّ المعاني، وقال بعضهم: الحاقة: الكائنة، وهو وهم ليس هذا موضع بيانه، وقيل: الحاقة لأنها تحق كل إنسان بعمله، وقيل: تحق الكفار الذين حاققوا الأنبياء، يقال: حاققته فحققته، أي خصمته.\rالسابع: أن الحق: المال المتعيَّن في الذمة، لقوله تعالى: {وَلْيُمْلِلِ الَّذِي عَلَيْهِ الْحَقُّ} [البقرة: 282].\rالثامن: الصدق، ومنه قوله تعالى: {وَعْدَ اللَّهِ حَقًّا} [النساء: 122]، ومنه قوله: (أنت الحق، وقولك الحق)، بأحد معانيه.\rالتاسع: الحق: الواجب، ومنه قوله: {حَقِيقٌ عَلَى أَن لَّا أَقُولَ عَلَى اللَّهِ إِلَّا الْحَقَّ} [الأعراف: 105]، أي واجب علي أن لا أقول على الله إلا الصدق، وقوله: {وَكَانَ حَقًّا عَلَيْنَا نَصْرُ الْمُؤْمِنِينَ} [الروم: 47]، وقال تعالى: {فَإِنْ عُثِرَ عَلَى أَنَّهُمَا اسْتَحَقَّا إِثْمًا} [المائدة: 107]، أي استوجبا، وقال تعالى: {وَلَكِنْ\r"], [296, "حَقَّ الْقَوْلُ مِنِّي} [السجدة: 13]، أي وجب في أقوى معانيه، وقال صلى الله عليه وسلم: (حق على كل مسلم أن يغتسل في كل أسبوع يوماً) وقال في الحديث: (إن الوتر حق)، أي واجب.\rالعاشر: الحق: المِلك، ومنه قوله: {مِنَ الَّذِينَ اسْتَحَقَّ عَلَيْهِمُ الْأَوْلَيَانِ} [المائدة: 107]، أي مُلِكَ، ومنه استحقاق الأعيان المبتاعة، أي تملكها.\rالحادي عشر: الحق: الحزم، ومنه قوله: (ما حق امرئ مسلم يبيت ليلتين إلا ووصيته مكتوبة عنده).\rالمسألة الثانية: القول في الباطل\r"]], "pg": [294, 296]}, "561.66": {"x": [[296, "وإنما تعرضنا له لأنه ضد الحق في جميع وجوهه ومحتملاته، وبعض معرفة الأضداد سبب معين على معرفة أضدادها، وقد قال تعالى: {وَلَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ} [البقرة: 188]، وقال تعالى: {رَبَّنَا مَا خَلَقْتَ هَذَا\r"], [297, "بَاطِلًا} [آل عمران: 191]، وقال النبي صلى الله عليه وسلم: (أصدق كلمة قالها الشاعر: ألا كل شيء ما خلا الله باطلُ)، وإن كان السبيل إلى معرفة الباطل معرفةُ الحق فلا بد من تخصيصه بالذكر.\rأما الباطل في العقليات، فقال علماؤنا: هو المعدوم؛ وقال بعضهم: هو المستحيل.\rوأما الباطل في السمعيات: فكل قول وعمل لا ينعقد شرعاً ولا يفيد حكماً.\rالمسألة الثالثة: في المختار\r"]], "pg": [296, 297]}, "561.67": {"x": [[297, "اعلموا - وفقكم الله - أنا إذا استقرينا معاني الحق من جميع وجوهه، ومعاني الباطل من كل جهاته، ألفينا أن الحق هو ما له فائدة مقصودة، والباطل ما لا فائدة فيه، سواء كان معدوماً أو موجوداً، فقد تتعلق بالمعدوم فائدة كما تتعلق بالموجود، والدليل عليه قوله تعالى: {مَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ} [الأحقاف: 3]، أي لفائدة مقصودة، وهي الثواب والعقاب، يؤكده قوله: {رَبَّنَا مَا خَلَقْتَ هَذَا بَاطِلًا} [آل عمران: 191]، أي ما خلقتهما لأنفسهما دون فائدة تتعلق بهما، وهي الحشر والثواب والعقاب، يحققه\r"], [298, "قوله: {أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَاكُمْ عَبَثًا} [المؤمنون: 115]، فقد تتعلق بالعدم فائدة كما تتعلق بالوجود، فيكون العدم حقاً بهذا المعنى، وقد تتعلق بالمعنى فائدة من وجه، فيكون حقاً ويَعرى عن الفائدة فيكون باطلاً، ولهذا قال صلى الله عليه وسلم: (أصدق كلمة قالها الشاعر: ألا كل شيء ما خلا الله باطل).\rونحن نتأوله ونبين معناه، لحرمة تصديق النبي صلى الله عليه وسلم له وتصويبه إياه، فنقول:\rإن الحق المطلق هو الله تعالى، إن أمره كله مفيد مقصود، لا يتعرى عن ذلك من جميع جهاته كيفما صرَّفتَه، ولهذا قال صلى الله عليه وسلم: (أنت الحق، ووعدك الحق)، الحديث، فأحق الأشياء الله، وأحق الأقوال لا إله إلا الله، وأحق المواعيد وعد الله، وأحق المخلوقات لقاء الله، بيان أن كل شيء منه، كذلك لا يتعلق به حكم إلا وهو مفيد مقصود، فصار حقاً من كل وجه، وسواه باطل من كل وجه، أو باطل من وجه، وما سواه معدوم لا يفيد ولا يتعلق به مقصود، وموجود تتعلق به فائدة ومقصود.\r"], [299, "وأما المعدوم الذي لا تتعلق به فائدة ولا مقصود فهو باطل مطلقاً، وهو كون شريك لله في ملكه وإله آخر معه، وهذا معنى قوله: {ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ هُوَ الْبَاطِلُ} [الحج: 62]، ويقال: كل موجود سوى الله حق من حيث وجوده، لكنه باطل من حيث يتطرق الفناء والعدم إليه.\rفإن اقترن بذلك أن الله تعالى حرمه ونهى عنه كالسحر والعين صار حقاً من وجه واحد وهو الوجود، وهو معنى قوله في الأثر: (السحر حق)، وصار باطلاً من وجهين:\rأحدهما: تطرق الفناء إليه.\rوالثاني: تحريم الله له.\rفكل مخلوق سوى الله فهو باطل من حيث تطرق الفناء والعدم إليه، فقد صدق إذاً قول الشاعر:\rألا كل شيء ما خلا الله باطلُ\rإما من وجه وإما من وجهين كما بيناه، وبهذا المعنى صدَّقه النبي صلى الله عليه وسلم.\rالمسألة الرابعة: في الفرق بين الحق والحقيقة\r"]], "pg": [297, 299]}, "561.68": {"x": [[299, "وقد اختلف العلماء فيه على قولين:\r"], [300, "الأول: قال علماء الأصول والفقه: الحقيقة: كون الشيء موجوداً، والحق: كونه مشروعاً، فكل حق حقيقة، وليس كل حقيقة حقاً، قالوا: وهذا معنى قوله في الأثر: (السحر حق).\rوالثاني: قال علماء الزهد: الحق: ما كان من صفات القلوب من المعارف والعقائد، والحقيقة ما كان من أوصاف الجوارح من الأعمال، وتعلقوا في ذلك بما روي عن النبي صلى الله عليه وسلم أنه قال لحارثة: (كيف أصبحت؟ قال: مؤمناً حقاً، قال له النبي صلى الله عليه وسلم: لكل حق حقيقة، فما حقيقة إيمانك؟) الحديث، فأشار بالحق إلى العقيدة، وبالحقيقة إلى الأعمال والتقوى.\rوالذي يصحح أن الحق ما بيناه من قبل في المختار، والحقيقة أن كل ما دل عليه وبينه فإنه فعيلة، من حق الشيء يَحُقُّهُ فهو حاق له أي: فاعل، وحاقة فاعلة، وحقيق وحقيقة فعيل وفعيلة منه، فكأنه قال له: لكل حق يدَّعى دليل عليه وشاهد له، فما دليلك على حقك الذي تدَّعي؟\rوقد غلب على ألسنة أهل الزهد في ذكر الله (الحق)، كما غلب على ألسنة أهل الأصول (الباري)، لأن أولئك استدلوا عليه بصفاته، فأخبر عنهم بقوله: {وَمَا تَكُونُ فِي شَأْنٍ} [يونس: 61]، وهؤلاء استدلوا عليه بأفعاله، فقال: {أَوَلَمْ يَنظُرُوا فِي مَلَكُوتِ السَّمَاوَاتِ وَالْأَرْضِ} [الأعراف: 185].\r"], [301, "الفصل الرابع: في التنزيل المنزلة العليا للرب تعالى في وصف ال"]], "pg": [299, 301]}, "561.69": {"x": [[301, "حق\rويَجمع ذلك ثلاثة أحكام:\rالأول: أنه له على العموم والإطلاق من كل وجه، لأنه لم يسبق وجوده عدم، ولا يتطرق إليه فناء.\rالثاني: أنه لا يكون في قوله كذب، ولا في وعده خلف.\rالثالث: أنه ليس في فعله عبث، فذاته حق، وصفاته حق، وأفعاله حق؛ حسب ما جمعه رسول الله صلى الله عليه وسلم في قوله: (أنت الحق، وقولك الحق، ولقاؤك حق)، فقوله: (أنت الحق) للذات، (وقولك حق) للصفات، (ولقاؤك حق) للأفعال.\rالمنزلة الثانية للعبد\rوهي ثلاثة أحكام:\rالأول: أن يرى نفسه باطلاً، لأنه مسبوق بعدم ملحق بفناء.\rالثاني: أن لا يقول إلا حقاً، كما قال تعالى: {حَقِيقٌ عَلَى أَن لَّا أَقُولَ عَلَى اللَّهِ إِلَّا الْحَقَّ} [الأعراف: 105].\rالثالث: أن لا يفعل إلا حقاً.\r"], [302, "تكملة في ترتيب الأخبار الواردة بهذه الأسماء\rقال جماعة من علمائنا: أول أسماء الإثبات (شيء)، لأنه أعمها وأشملها للمخبر عنه، ولا يقع على المعدوم إلا مجازاً، وهذا فاسد جداً، وإنما قصروا فيه لأنه من باب العربية، وكثرتهم لم يتمرنوا بها، وإنما أخذوا منها المقدار الذي يفتقر إليه الناظر.\rوخذوها نصيحة: كل من نظر في علم وقصد أن يأخذ منه المقدار الذي يحتاج إليه لم يحصل منه على شيء، وكل من نظر فيه ليستولي عليه ربما حصل له منه المقدار الذي يحتاج إليه، ولذلك قال بعض العلماء: العلم إن لم تعطه كلك لم يعطك بعضه، وإن أعطيته كلك كنت منه على خطر في إعطاء البعض.\rوالصحيح في هذا:\r"], [303, "أن أول أسماء الإثبات: معلوم، وموجود.\rوثانيها: عين، وذات، ونفس، وثابت، وكائن، وقائم.\rوثالثها: شيء.\rورابعها: حق.\rوإنما قلنا ذلك لأن قولنا شيء يعبر به عن المراد، وقد يكون معلوماً موجوداً غير مراد، ولا يكون مراداً إلا معلوماً، فثبت أن الشيء في الدرجة الثالثة من الإثبات.\rوقولهم: إن الشيء لا ينطلق على المعدوم إلا مجازاً قول مطلق يفتقر إلى التحقيق المتقدم، فإن العدم المحض لا يسمى شيئاً، ولا يتعلق به علم كما بيناه، وهذه إشارة ومقدمة يركب عليها الفطن ما يليق بها.\rوإذا انتهى بنا القول إلى هذا المقام، وبينا هذه الأسماء المتقدمة، فنرجع إلى القول في الواحد، وهو الأول من أسماء التنزيه، فنقول:\r"], [304, "[القول في اسم الواحد]\rهو اسم مشكل المعنى واللفظ، متشعب القول لغةً وحقيقةً، وسنجمع فيه بين غاية البيان ونهاية الاختصار، بمعونة الله، وفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [301, 304]}, "561.70": {"x": [[304, "اعلموا أنه اسم ورد به القرآن، قال تعالى: {وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ} [البقرة: 163]، ووردت به السنة، فإنه فسر في حديث أبي هريرة كما تقدم إيراده، وله نظائر في اللفظ والمعنى منها: الأحد، والوحيد، والفرد، والوتر، فهي خمسة.\rأما الأحد، فقد ورد به القرآن، قال تعالى: {قُلْ هُوَ اللَّهُ أَحَدٌ} [الإخلاص: 1]، وليس في حديث أبي هريرة.\rوأما الوتر، فليس له في القرآن ذكر، ولكن في الصحيح في حديث أبي هريرة: (لله تسعة وتسعون اسماً، مائة إلا واحد، الله وتر يحب الوتر)، وعدّد الأسماء من طريق شُعيب فلم يذكره، وعددها من طريق عبد العزيز بن الحصين فذكره.\r"], [305, "وأما الوحيد، فنعقد فيه فصلاً.\rوأما الفرد، فليس له في القرآن ولا في السنة ذكر، ولكن ذكره علماؤنا وتكلموا عليه.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [304, 305]}, "561.71": {"x": [[305, "فنقول: أما الواحد في اللغة فله معنيان:\rأحدهما: مفتتح العدد، وهو مشهور.\rوالثاني: المستبِد بالشيء المنفرد به، ومنه قول الشاعر:\rيا واحد العرب الذي ... ما في الأنام له نظير\rوله تسعة أبنية:\rالأول: الواحد، وقد تقدم.\rالثاني: أحد.\rالثالث: الوحيد.\rالرابع: الوحِد، بكسر الحاء.\rالخامس: الوحَد، بفتح الحاء.\rالسادس: الوحْد، بإسكان الحاء.\rالسابع: المَوحَد، على وزن مَفعل.\rالثامن: أُحاد.\rالتاسع: أوحد.\rأما الأحد، فاختلف العلماء فيه على قولين:\r"], [306, "أحدهما: أنه بمعنى وَحَد بفتح الواو والحاء، وهو الواحد، والهمزة منقلبة عن واو، وذلك كثير في اللغة.\rالثاني: أن معناهما مختلف، والدليل عليه ثلاثة أمور:\rالأول: أن أحداً نفيٌ لما يُذكر معه من العدد، والواحد اسم لمفتتح العدد.\rالثاني: أن قولنا: واحد، يستعمل في الإثبات، وقولنا: أحد، يستعمل في الجحود، تقول في الأول: جاءني واحد، فتثبته وتنفي ما عداه، وتقول في النفي: الثاني: ما جاءني أحد، المعنى لم يأتني واحد ولا اثنان ولا أكثر من ذلك ولا أقل، وتقول: ما جاءني واحد، فالمعنى نفي المجيء عن واحد وإثباته لأكثرمنه في العدد.\rالثالث: أن قولنا: أحد، يستعمل فيما يعقل خاصة، وواحد يستعمل فيما يعقل وفيما لا يعقل، وقد اعتذر أهل العربية عن قول النابغة:\rوما بالربع من أحدِ إلا الأواريَّ\rبالاعتذار الحسن المشهور، وقد قال بعض علماء العربية: إن الواحد: هو المنفرد بالذات الذي لا يضامه أحد، والأحد: هو المنفرد بالمعنى، يقال للمتناهي في الفعل: هو أحد الأحدين، ففرق بينهما من هذا الوجه.\r"], [307, "وأما الوحيد، فهو فعيل من فاعل، وهو الواحد، ومعناه المنفرد، قال الله تعالى: {ذَرْنِي وَمَنْ خَلَقْتُ وَحِيدًا} [المدثر: 11].\rوأما الواحد فيحتمل معنيين:\rأحدهما: أن يكون فعلاً سمي به كما سمي بسائر الأفعال.\rالثاني: أن يكون اسم فاعل، وفي تصريف فعله قولان:\rأحدهما: أن يقال: وحَد يحِد وَحْداً فهو واحد ووحِد بكسر الحاء فَعِلٌ منه، ووحد بفتح الحاء كالاسم منه.\rالثاني: أنه وحِد يَوْحَدُ فهو وحِد، كما يقال: حذر من حاذر، وجزع من جازع، وفطن في اسم الفاعل خاصة دون التصريف.\rوأما وحد بفتح الحاء فهو بمعنى الواحد المنفرد، قال النابغة:\rكأن رحلي وقد زال النهار بنا ... يوم الجليل على مستأنِسٍ وَحَدِ\rقال ابن العربي: ورأيت بعضهم قد قال: إنه يُصرَّف فعلُه، فيقال: وحد - بفتح الحاء - يوحد - بضمها - فهو وحد، كما يقال: حسن يحسن فهو حسن.\r"], [308, "وأما وحْد بإسكان الحاء، فقال علماؤنا: إذا سمي بالمصدر جرى ذلك مجرى اسم الفاعل وأدى معناه، كما يقال: عدل وعدل.\rوأما الموحد، فهو مفعل بمعنى واحد، ويقال كذلك إلى المعشر، قال الشاعر:\rولكنما أهلي بواد أنيسُه ... ذئابٌ تبغَّى الناسَ مثنى وَمَوْحَدُ\rوأما أُحاد، فهو فعال معدول عن واحد؛ واختلف أهل العربية هل يُتجاوز به رُباع أم لا، كما اختلفوا هل هو بمعنى واحد أم لا على قولين، واختلفوا أيضاً في مثنى وثلاث هل هو بمعنى اثنين وثلاث دون تكرير أم هو بمعنى اثنين اثنين وثلاث ثلاث بتقدير التكرير، وفي ذلك تحقيق عظيم بيناه في سورة النساء من كتاب أحكام القرآن.\r"], [309, "وأما أوحد، فهو أفعل من واحد، وذلك بيّن.\rوأما الفرد، فيقال بإسكان الراء وفتحها وكسرها، ويقال: الفريد والفارد بمعنى واحد، ومنه قوله: {وَلَقَدْ جِئْتُمُونَا فُرَادَى} [الأنعام: 94]، وهو جمعه، كما يقال: أسارى في جمع أسير، وقدامى في جمع قديم، وقال الشاعر:\rربيتهم تسعة حتى إذا اتسقوا ... أصبحتُ منهم كقرن الأعضب الفرد\rبفتح الراء وكسرها، ويروى: الوحد بفتح الحاء وكسرها أيضاً، ومنه أيضاً قول النابغة:\rكسيف الصيقل الفرد\rوهو المنفرد الذي ليس له نظير ولا مشارك.\rقال ابن العربي: وقد رأيت بعض المتأخرين قال فيه: وفردان على وزن سكران ومثاله، وأظنه أخذه من الجمع، والصحيح ما قدمته فيه.\r"], [310, "وأما الوتر، فهو عبارة عن كل عدد لا زوج له، وهو التو، ومنه الحديث: (الاستجمار تو).\rالفصل الثالث: في شرحه حقيقةً وعقيدةً\r"]], "pg": [305, 310]}, "561.72": {"x": [[310, "وفيه ست مسائل:\rالمسألة الأولى: في تحقيق معاني هذه الألفاظ\r"]], "pg": [310, 310]}, "561.73": {"x": [[310, "اعلموا أن حقيقة الواحد: هو الذي لا ينقسم ولا يتزيد، نقل إلى الجملة الجامعة، وإلى الرجل الذي لا نظير له مجازاً، وعليه يتركب الوحَد والوحِد والوحيد.\rوأما حقيقة الأحد، فقد أشكلت على الخلق حتى عوَّل المحققون فيه على أن الواحد مفتتَح العدد، والأحد: موضوع لنفي ما يُذكر معه من العدد، ولذلك نستعمل قولنا (أحد) في النفي دون الإثبات.\r"], [311, "وهذا القول نظر إلى الظاهر من الألفاظ، وعدول عن بحث المعاني، وحقيقته ليست مبنية على المعدود، وإنما هي موضوعة لعدم التجزي، لكن كل متجزئ معدود، فالعدد من لوازمه لا من حقائقه، وبين الحقيقة واللازمة تباين عظيم، وقد غلط في الحقائق لأجل جهلهم بالفرق بين الحقيقة واللازم كثير من الكبراء، لأنه غرض لا يطيقه إلا طويل النفس في النظر، وضرب لا يبطش فيه إلا شديد الساعد في وقائع الفكر.\rوأما قول علمائنا: إنه لا يستعمل إلا في النفي فباطل، ألا ترى أنه يقال: جاء أحد الثلاثة، ويراد واحد الثلاثة، وأظهر من هذا وأعظم قوله تعالى: {قُلْ هُوَ اللَّهُ أَحَدٌ} [الإخلاص: 1]، حتى قال المحققون من علمائنا: إن قولك: (أحد) اسم اختص به الباري من لفظ الواحد، كما اختص بالرحمن من لفظ الرحمة، ولذلك لم يستعمل أحد إلا في من يعقل، والواحد: يستعمل في من يعقل ومن لا يعقل، وهذه الخصيصة إنما كانت له لاختصاص الباري تعالى به، وحقيقة الأحد: الواحد الذي لا يكون معه عدد، ولذلك جرى في النفي الذي لا معدود فيه ولا عدد معه أكثر من جريانه في الإثبات.\rوأما الوتر فقال بعض علمائنا: إن حقيقة الوتر واحد لا زوج له، وليس ذلك صحيحاً، لأن الثلاث وتر ولها زوج، وكذلك كل وتر من العدد، فحقيقته إذن كل عدد لا ينقسم على الصحة، وأطلق على الباري سبحانه عبارةً عن استحالة الانقسام أصلاً.\r"], [312, "وأما الفرد، فحقيقته: الذي لا شبه له، وهو مجاز الواحد، فصار الفرد حقيقة مجاز الواحد، وهذا من أبدع أنواع التحقيق.\rالمسألة الثانية: في حقيقة التوحيد\r"]], "pg": [310, 312]}, "561.74": {"x": [[312, "هو تفعيل من وحدت، وهو على ثلاثة أنواع:\rالأول: وهو أشرفها، توحيد الله لنفسه، وهو بوجهين:\rأحدهما: علمه بأنه واحد كقوله: {شَهِدَ اللَّهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ} [آل عمران: 18].\rالثاني: إخباره عن وحدانيته كقوله: {وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ} [البقرة: 163].\rالثاني من الأول: توحيده للخلق بإعطاء التوحيد لهم وتوفيقهم له.\rالثالث: توحيد الخلق له، وهو اعتقادهم أنه واحد.\rالرابع: شهادة الخلق له، كقوله: {وَالْمَلَائِكَةُ وَأُولُو الْعِلْمِ} [آل عمران: 18].\rالمسألة الثالثة: في تركيب المعنى الاعتقادي على الشرح اللغوي\r"]], "pg": [312, 312]}, "561.75": {"x": [[312, "إذا تحققتم - وفقكم الله - حقيقته، فاعلموا أن الباري واحد في ذاته بالوجهين؛ الحقيقة والمجاز.\rأما الحقيقة فإنه لا ينقسم؛ وبذلك صار واحداً، ولكن ما لا يتجزأ على قسمين:\rأحدهما: ينثني، كالجوهر والنقطة.\r"], [313, "والثاني: لا ينثني، وهو الله سبحانه، فإنه لا ينثني أي ليس بمفتتح للعدد، ولا يشبهه أحد، ولذلك صار واحداً حقيقة.\rوأما بالمجاز، فإنه لا نظير له، لاستحالة الاتصال بالأشكال، ووجوب كونه متوحداً بصفاته، ولا شريك أيضاً له، فصار واحداً في ذاته بعدم التجزي، واحداً في صفاته، واحداً في أفعاله ومخلوقاته، وكل واحد من هذه الأوجه الثلاثة واجب في وصفه، فلا قسيم له في الذات، ولا شبيه له في الصفات، ولا شريك له في تدبير المصنوعات، لأنه لو كان منقسماً كان قابلاً للتركيب، وما احتمل التركيب محدَث، وما احتمل القِسمة ليس بواحد، بل يكون شيئين فأكثر من ذلك، ولو كان له شبيه في صفاته كان مستحقاً للإلهية كاستحقاق من هي له، وأدى ذلك إلى القول بتناهي مقدوراتهما، ووجب به حدثُهما.\rولو كان له شريك في مصنوعاته وكان جائزاً وقوع التمانع بينهما لتصور اختلاف المرادَين، وأدى ذلك إلى عجزهما أو عجز أحدهما، والأخر هو الإله، فوجب لذلك وصف الواحد له بالوجوه الثلاثة على كمال معانيها.\r"], [314, "المسألة الرابعة:\r"]], "pg": [312, 314]}, "561.76": {"x": [[314, "اختلف الناس في الوحيد، فمنهم من قال: إن الباري تعالى لا يوصف به لأنه ورد مورد الذم؛ قال الله تعالى: {ذَرْنِي وَمَنْ خَلَقْتُ وَحِيدًا} [المدثر: 11]، يعني: مفرداً فقيراً لا مال له ولا ولد، ثم خلقت له المال والولد.\rومنهم من قال: إن قوله (وحيداً) وصف راجع إلى الباري تعالى: التقدير: ذرني ومن خلقته وحدي، لم يشرَكني فيه أحد، فأنا أتولى عذابه يوم القيامة كما توليت خلقه.\rوحقيقة العبارة فيه على ألسنة العربية أن قوله (وحيداً) على التأويل الأول حال من قولك: من الذي يعود عليه ضمير المفعول المحذوف، التقدير: ذرني ومن خلقتُه وحيداً، وعلى التأويل الثاني يكون وحيداً حال من ضمير الفاعل، وهي التاء في قوله: خلقت، وهذا منهج ضعيف، لا تثبت بمثله أسماء الباري وأوصافه، والذم عليه أغلب وفيه أظهر.\rالمسألة الخامسة: في الفرد\r"]], "pg": [314, 314]}, "561.77": {"x": [[314, "وهو كما قلنا: اسم لم يرد به كتاب ولا سنة، لكنه لما كان في معنى الواحد سمي به على أحد القولين في تسميته؛ بما هو في معنى مدح مما لم يرد به أثر، والمختار تركه، لأن فيما ورد غنى عنه.\rالمسألة السادسة: في الوتر\r"]], "pg": [314, 314]}, "561.78": {"x": [[314, "وأما الوتر فإذا كانت حقيقته أنه لا ينقسم، فذلك هو الباري بالحقيقة، لاستحالة تأليفه وتبعيضه والتجزي عليه.\r"], [315, "الفصل الرابع: في التنزيل\r"]], "pg": [314, 315]}, "561.79": {"x": [[315, "إذا علمتم معنى الواحد بما قدمناه فلله سبحانه في ذلك أحكام يختص بها، أما أحكامه في الواحد فخمسة:\rالأول: أنه لا يصح الخروج عن ملكه.\rالثاني: أنه لا يجوز عليه التشبيه.\rالثالث: أنه لا يجوز عليه التبعيض.\rالرابع: أنه لا حد لسلطانه.\rالخامس: أنه لا يجوز الاتكال على غيره.\rوأما أحكامه في الأحد: فإنه لا يجوز عليه الاتصال والمماسة، ولا تصح فيه الزيادة والنقصان.\rوأما الفرد: فحكمه فيه أنه لا تصح له الزوجة والولد.\rوأما الوتر: فحكمه فيه أنه لا يوصف بصفة يصح وصف غيره بها، إذ له فيه اختصاص ومباينة، وفي ذلك كلام طويل ذكرناه في كتب الأصول.\rالمنزلة الثانية للعبد:\rوهي لا تكون له بالحقيقة؛ فإنه يتجزأ ويتبعض، ولكن تكون له بالمجاز من معناه أحكام جِماعها ألا يكون له نظير من الخلق في علمه ولا في\r"], [316, "إيمانه ولا في عمله، فيكون حينئذ واحداً في أبناء جنسه، وهذه المنزلة هي لمحمد صلى الله عليه وسلم، ويتفاضل الخلق بعده فيها تفاضلاً يعجز الخلق عن إحصائه.\r"], [317, "القول في المَلِكِ\rوهو الثاني من أسماء التنزيه:\rاعلموا - وفقكم الله وأرشدكم - أن معرفتكم بهذا الاسم من أوكد أبواب التوحيد، ومن مهمات الأسماء، لأن باب التعديل والتجوير يدور عليه، ووصف التنزيه والكمال في الإثبات معاً يستند إليه، وفيه أربعة فصول:\rالفصل الأول: في مورده شريعةً\r"]], "pg": [315, 317]}, "561.80": {"x": [[317, "وفيه ثلاث صيغ: الملك والمالك والمليك، وقد ورد القرآن بالكل، قال الله تعالى: {الْمَلِكُ الْقُدُّوسُ} [الحشر: 23]، {الْمَلِكُ الْحَقُّ} [المؤمنون: 116]، وقال: {مَالِكِ يَوْمِ الدِّينِ} [الفاتحة: 4]، و {مَالِكَ الْمُلْكِ} [آل عمران: 26]، وقال: {عِندَ مَلِيكٍ مُّقْتَدِرٍ} [القمر: 55]، وجاء في الأخبار كثيراً، وجاء في حديث أبي هريرة من طريق شعيب: الملك، ومن طريق عبد العزيز بن الحصين: المليك، بالياء للمبالغة.\rالفصل الثاني في معناه لغة\r"]], "pg": [317, 317]}, "561.81": {"x": [[317, "وقد اتفق أرباب اللسان على أنه في اللغة دائر على الشد والربط. ومنه قولهم: ملكتُ العجين: إذا أُحكمت جميع أجزائه والتأمت.\r"], [318, "وملكت كفي بالطعن: إذا أحكمتَ التصرف به واستوليت بالمعرفة والقدرة عليه. قال قيس بن الخطيم يصف طعنة:\rملكت بها كفي فأنهرت فتقها ... يرى قائم من دونها ما وراءها\rوقال أوس بن حُجر يصف قوساً:\rفملَّك بالليط الذي فوق قشرها ... كغِرقئ بَيض كنَّه القيضُ من عَل\rيعني بقوله: ملّك أي شد، ويقال لعقد النكاح: إملاك، لما يرتبط به من الحل وصلة الرحم وغير ذلك من الأحكام.\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [317, 318]}, "561.82": {"x": [[318, "وفيه سبع مسائل:\r"], [319, "الأولى: في ذكر اختلاف الناس فيه.\rالثانية: في كونه من صفات التنزيل والكمال واحتماله للأفعال.\rالثالثة: في أي الصيغ أبلغ فيه وأعم.\rالمسألة الرابعة: أي الاسمين أبلغ من اسم ملك أو مالك؟\r"]], "pg": [318, 319]}, "561.83": {"x": [[319, "الخامسة: في لفظ الملك الوارد في الشرع الذي تنبني عليه الأحكام أهو حقيقة أم مجاز؟\rالسادسة: في وصف الكافر بأنه مالك.\rالسابعة: هل يسمى الباري بسلطان؟\rالمسألة الأولى: في ذكر اختلاف الناس فيه\r"]], "pg": [319, 319]}, "561.84": {"x": [[319, "فمنهم من قال: حقيقة الملك: القدرة على الإنشاء والإيجاد، ويكون معناه على هذا الوجه معنى قولنا: (إله)، لأن الإله هو: القادر على الإيجاد والإنشاء، وهو قول أكثر علمائنا.\rالثاني: أن حقيقة الملك جواز التصرف على الإطلاق، وهو اختيار إمام السنة أبي الحسن في كتاب التفسير الكبير المسمى بالمختزَن.\rالثالث: قال بعضهم: هو المتصرف على الإطلاق.\r"], [320, "الرابع: أن الملك: هو الذي لا يتطرق إليه نقص ولا يُعجزه أمر.\rوكلها راجع إلى معناه لغة لمن تثبته، وكذلك كل اسم منها، فإن الشد والربط وجواز التصرف ثمرة القدرة، والقدرة سببه، فتارة يعبَّر عن المعنى بسببه، وتارة يعبر عنه بثمرته، كما قررناه في كتب الأصول، وهكذا كل اسم، وستراه بعد إن شاء الله.\rوعلى كل الأقوال فلا ملك في الحقيقة إلا الله وحده، لأنا إن قلنا: إن المالك هو القادر على الأشياء، فهو سبحانه المنفرد بذلك.\rوكذلك إن قلنا: هو الذي يجوز له التصرف على الإطلاق، فهو الله وحده، لأن من عداه لا يتصرف على الإطلاق، وإنما تصرفه محجور مقصور على أوصاف، مخصوص بوجه، مقدر بوقت.\rوإن قلنا: هو الشد والربط، فمن يشُد ويربِط إلا الله وحده، وهل الشد والربط إلا بالقدرة التي تصدر عنها المخلوقات.\rوإن قلنا - وهو الصحيح -: إنه الذي لا يتطرق إليه نقص ولا يُعجزه أمر، فبين أنه الله وحده، ولا يقال لغير الباري ملك إلا على المجاز، بمعنى جواز التصرف خاصة لا بغيره فإنه محال، إلا لله فإنه واجب، وإلى هذا المعنى وقعت الإشارة بقوله: {فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ} [المؤمنون: 116].\r"]], "pg": [319, 320]}, "561.85": {"x": [[321, "المسألة الثانية: اختلف الناس هل هو من صفات الذات أم من صفات الفعل؟\rوذلك يتركب على معناه اللغوي الذي تقدم ذكرُه؛ وإنما صار من صار إلى أنه من صفات الفعل لاعتقاده أن الملك هو المتصرف، وذلك يستدعي وجود الموجودات، وقد كان الله ولا شيء غيره، فركَّب عليه أن المُلك من صفات الأفعال، وأنه إنما صار ملكاً بعد وجود الأفعال، وقد قدمنا أن حقيقة الملك القدرة على الإيجاد وجواز التصرف، وبذلك يكون المالك مالكاً لأعيان تصرف فيها أو لم يتصرف لما كان التصرف له جائزاً، إذ كان عليه قادراً، أو بصفة من يقدر عليه.\rونحن نعتقد ونقول بما ثبت من الأدلة أن الباري لم يزل ملكاً على معنى أنه قادر على الإيجاد، جائز له التصرف على الإطلاق، والمعدوم مملوك في حال عدمه، أي مملوك له إيجاده، جائز له أن يوجده كيف أراد، فإذا وجد تصرف فيه سبحانه كيف شاء.\rوكما قلنا: إن المعدوم مقدور له ومعلوم ومذكور، ولا يقتضي وصفنا له بذلك وجوده وثبوته، لأن جميع ما أضفناه إليه ووصفناه به يرجع إلى غيره، من علم العالم به، وقدرة القادر عليه، وذكر الذاكر له، فكذلك ملك المالك إياه، وهذا دقيق، يأوي إلى عظيم من التحقيق، وفيه غنية لمن أنصف وكان له لب.\r"], [322, "المسألة الثالثة: في كونه ملكاً، هل هو كونه قادراً أم لا؟\r"]], "pg": [321, 322]}, "561.86": {"x": [[322, "نقول: قال بعض علمائنا: إنه لا معنى للملك أكثر من أنه القادر؛ وقال بعضهم: إنها صفة للقادر، إذا كان عليها قيل: إنه قادر مالك، وكان له ملك، ومعنى ذلك جواز التصرف له على الإطلاق كما بيناه، فتكون نسبة التصرف إليه مع ارتفاع الحظر عنه وانتظار الإذن من غيره مرتفعاً عن صفته، وبه يتم المعنى ويكمل المقصود.\rوقال بعضهم: الملك: الذي له الكمال في التنزيه عن النقص، والاستيفاء لصفات الجلال، وهو حقيقته.\rفإن قيل: فالذي يقول من علمائكم: إن الملك هو القادر قد ساعد القدرية على تفسير الملك بالقدرة.\rفالجواب: أنه لا سواء بينهم، لأنا نعتقد أن الله هو القادر على الإيجاد وحده، وهم يقولون: إن العبد يقدر على الإيجاد، وذلك باطل قطعاً حسب ما بيناه في كتب العقائد.\rوفيه بع ذلك تفصيل طويل لا يدخل في الاختصار، إنما هو من التكميلات والتتميمات لما سبق عليها من التوطئة والمقدمات.\r"], [323, "لُبابه: أن ملك الله عام لك موجود؛ كان من كسب العباد أو لا كسب لهم فيه، كما هو به عالم لا يشذ شيء عن ملكه، كما لا يخرج عن علمه، وهم يقولون: إن أفعال العباد لا يملكها الله، تعالى عن قولهم، وقد علم الكل أن صفة الملك مدح وتعظيم، فكيف يُسلب عنه بعض متعلقاتها؟ وأي فرق بين سلب البعض أو سلب الكل لاستحالة صفة النقص عليه ووجوب الكمال له؟\rفثبت أنه مالك لكل مملوك، عالم بكل معلوم، وأنهما قرينان لا يجوز أن يذهب مملوك عن ملكه، أو يخرج مقدور عن قدرته، كما أخبر تعالى عن صفته بقوله: {الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى. لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ الثَّرَى} [طه: 5 - 6]، وهذا فن يجب الاعتناء به في معنى أسماء الله وصفاته لما بينا من انبناء التعديل والتجوير عليه.\rوأصل العقيدة الصحيحة في ذلك أنه المالك لكل فعل، ولا يصح أن يكون عليه حظر من حاظر، فوجب أن يحسن منه جميع ما فعل على الابتداء، ولا يصح أن يقبُح منه شيء، لاستحالة أن يكون غير مالك لشيء، أو أن\r"], [324, "يكون عليه زجر ونهي، فيجب الحكم بتحسين جميع أفعاله، وحصل الفرق بينه وبين غيره من حيث يمتنع فيه مِثل وصفه.\rوهذا معنى فات القدرية، لا يقدرون عليه ولا يعتقدون الحق فيه، وإذا انتهيت إليه تحققت سر القدر والقضاء الذي انفرد فيه سبحانه بالحكم والإمضاء، وعن هذه الجملة عبر النبي صلى الله عليه وسلم بقوله: (سبحان ذي الملك والملكوت، سبحان ذي العزة والجبروت).\rالمسألة الرابعة: أي الاسمين أبلغ من اسم ملك أو مالك؟\r"]], "pg": [322, 324]}, "561.87": {"x": [[324, "اعلموا - وفقكم الله وبصّركم - أن هذا باب يتعلق باللغة، فتعمق فيه أربابها وتسوروا على معنى العقائد فيه بتكلفهم ما ليس من بابهم، والتطويل باستيفاء الجمل والتفاصيل يقطع بالغرض المفترض، فنخص القول بمعنى لطيف الجِرم، مُستولٍ على العلم، فنقول:\rذهب قوم: إلى أن قولنا: (مالك) أبلغ، لأنه أعم، لثلاثة أوجه:\rالأول: أنك تضيفه إلى الخاص والعام فتقول: مالك الدار والثوب والدابة، كما تقول: مالك الملوك ومالك الأرض.\r"], [325, "الثاني: أنه ينطلق على (مالك) القليل كما ينطلق على (مالك) الكثير)، ولا يقال: (ملك) إلى على الكثير.\rالثالث: أنك تقول: مالك الملك ولا تقول: ملك الملك، قال الله تعالى: {قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ} [آل عمران: 26].\rوذهب قوم: إلى أن (ملكاً) أعم من (مالك)، لثلاثة أوجه:\rالأول: أنك تقول: ملك الطيور والجوارح، كما تقول: ملك الآدميين، ولا تقول: مالك الطيور.\rالثاني: أن الملك: من اتسع ملكه.\rالثالث: أن (ملكاً) بناؤه فعل، ومالكاً بناؤه فاعل، وفعل أبلغ من فاعل، كجزع من جازع، وحذر من حاذر.\rفإذا قابلت بين هذه الستة الأوجه وجدت أن (ملكاً) أوسع متعلقاً من (مالك)، وأبلغ من بناءً، وأمدح منه ذكراً، والله أعلم.\rالمسألة الخامسة: في لفظ الملك الوارد في الشرع الذي تنبني عليه الأحكام أهو حقيقة أم مجاز؟\rالجواب: أن هذا كله توسع ومجاز، والمعنى فيه والمقصود به الفرق بين من يجوز له التصرف وبين من لا يجوز له.\r"], [326, "فإن قيل: قد قلتم: إن معنى كونه مالكاً جواز التصرف له، فإذا كان المالك في الشرع من يجوز التصرف له فاجعلوه حقيقة فيه.\rفالجواب: أنا قلنا في حقيقة المالك: من يجوز له التصرف، على الإطلاق، ومعناه: ابتداء من غير إذن آذن ولا حظر حاظر، ولا تجويز ولا تخصيص ولا تعيين، والمتصرف شرعاً إنما تصرف بعد هذه الشروط والتجويزات كلها.\rفإن قيل: فلم يكون ذلك مجازاً مع استعماله في اللغة وإطلاقه في الشريعة؟\rالجواب: أنا نقول: كل إطلاق لا بد له من حقيقة ومجاز، وقد قلنا: إن الحقيقة فيه ما أوضحناه، وأن المجاز سواه، ولا يتصور أن تكون له حقيقة غيره، وأن المجاز بعد ما ذكرناه.\rفإن قيل: وكيف تختلف اللغة في هذا القول، والحقيقة والبيان وقع باللغة عنها فوجب أن يكون بمعناها؟\rالجواب: أنا نقول: وقع البيان باللغة العربية عن وصف الرب بأنه ملك ومالك، وعن وصف العبد بأنه مالك وملك، واستحال أن يجري الوصف فيهما على معنى واحد لاستحالة التماثل، فوجب التباين فيه، فكانت الحقيقة للرب أقرب لأنها له بالاستحقاق وعلى الكمال والوجوب، وكان المجاز\r"], [327, "للعبد لأن الملك له موهوب هبة عارية ناقص، وإلى هذا كله وقعت الإشارة بقوله: {قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَن تَشَاءُ} [آل عمران: 26].\rالمسألة السادسة: في وصف الكافر بأنه مالك\r"]], "pg": [324, 327]}, "561.88": {"x": [[327, "فقال بعضهم: إن الله تعالى يُملك الكافر، واستظهر على ذلك بقوله تعالى: {أَلَمْ تَرَ إِلَى الَّذِي حَاجَّ إِبْرَاهِيمَ فِي رَبِّهِ أَنْ آتَاهُ اللَّهُ الْمُلْكَ} [البقرة: 258].\rوقال بعضهم: إن الله لا يُملك الكافرين، والذي آتاه الله الملك إبراهيم، وهذا ضعيف من وجهين:\rأحدهما: اللغة، وذلك أن الله تعالى قال بعده: {أَلَمْ تَرَ إِلَى الَّذِي حَاجَّ إِبْرَاهِيمَ فِي رَبِّهِ أَنْ آتَاهُ اللَّهُ الْمُلْكَ}، أي: لأن آتاه الله الملك، المعنى: أنه اغتر بالملك الذي أعطاه الله إياه، فجادل إبراهيمَ عليه السلام في الله، فالذي جادل مغتراً بالله مغتراً بالملك هو الكافر، فكانت محاجة الكافر بالملك، فقال: أنا أحيي وأميت، وكانت محاجة إبراهيم بالنبوة، لأن آتاه الله العلم، ولذلك بُهت الكافر.\rوأما الحقيقة فإن إبراهيم لم يكن وقت المحاجة ملكاً، وإنما كانت له نبوة مبتدأة محفوفة بالمكاره والثواب، واستمرت الحال كذلك من الامتحان إلى حين.\r"], [328, "يُحققه: أن الله تعالى قال مخبراً عن الكافر في قصة يوسف عليه السلام: {وَقَالَ الْمَلِكُ إِنِّي أَرَى سَبْعَ بَقَرَاتٍ سِمَانٍ} [يوسف: 43]، فصح أن الكافر سمي به، لكن الفرق بينه وبين الخالق يتبين في المنازل والمعاني في الفصل الرابع.\rالمسألة السابعة: هل يسمى الباري بسلطان؟\r"]], "pg": [327, 328]}, "561.89": {"x": [[328, "وبيانه يأتي في اللواحق مع نظائره، إن شاء الله تعالى.\rالفصل الرابع: في التنزيل\r"]], "pg": [328, 328]}, "561.90": {"x": [[328, "اعلموا أن المرء إذا انتهى إلى هذا المقام من المعرفة حصل بين منزلتين:\rإحداهما: علمه بربه.\rوالثانية: علمه بنفسه، وهذه حاله في كل اسم منها.\rأما المنزلة الأولى وهي علمه بربه، فقد تحقق المنتهي إلى هذا الأمد أنه الملك الذي يستغني في ذاته العُليا وصفاته وأسمائه الحسنى عن غيره، ويحتاج إليه غيره، بل لا يستغني عنه شيء في شيء، فلاوجود لغيره به كان أولاً، والبقاء له منه ثانياً، والصفات إليه فيه ثالثاً، فكل شيء سواه فهو له ملك مفتقر إليه، وهو الغني عن كل شيء، فهو الملك حقيقة، وهو الملك\r"], [329, "على الإطلاق من غير تقييد، بما تقدم من الأدلة وسبق من البراهين، فبحكم ذلك اختص بنعوت اقتضاها كونه ملكاً؛ جماعها إحدى عشرة:\rالأول: أنه يعز من يشاء، ويذل من يشاء، ويستحيل عليه الإذلال.\rالثاني: أنه المملك لغيره، السالب له.\rالثالث: أنه الممكِّن لسواه، المانع له.\rالرابع: أنه يولي ويعزل، ولا يتوجه عليه العزل.\rالخامس: أنه المنفرد بالعز والسلطان، لا يُشاركه فيه أحد.\rالسادس: أنه يقضي ولا يقضى عليه.\rالسابع: أن الإنفاق إليه، يَرزق ولا يُرزق، ويطعِ ولا يطعَم.\rالثامن: أنه يؤلم ولا يتألم.\rالتاسع: أنه يضر وينفع، ولا يتوجه عليه الضرر والنفع.\rالعاشر: أنه يَحرس ولا يُحرس.\rالحادي عشر: أن العرْض عليه، والثواب والعقاب إليه، والعفو لا يُرجى إلا لديه.\r"], [330, "وفي كل نعت منها آية وحديث يدل عليه، وهذا الأمد الأقصى إذا تبصرت فيه يقع بك عليه.\rوأما المنزلة الثانية للعبد: وهي علمه بنفسه:\rلما كان فقيراً إلى الله تعالى من كل وجه وفي كل حالة، لم يتصور أن يكون له ملك مطلق، وإن كان للعبد استغناء عن غيره، فهو محتاج إلى ربه، ولقد يحتاج إليه بعض الأشياء من وجه، ويحتاج هو من كل وجه، فله بما يُحتاج إليه حظ من الملك حقير، به صح أن يسمى ملكاً، صار إليه من قبَل ربه، فكان عظيماً لشرف الجهة التي تصيَّر إليه بها، وقد سمى النبي صلى الله عليه وسلم بهذا المعنى من كان له قوت ومنزل غنياً، ومن كان له خادم ملكاً، فكان غنياً\r"], [331, "بحُكم استغنائه عن مفاقر عدم هذه الأعيان، وكان ملكاً لتصرفه فيها، بحكمه عليها ورفع المؤن عنه فيها، وحقيقة مجاز الملك في العباد: من تجرد عن كل رق إلا لله تعالى، واستغنى عن غيره به، ولذلك معيار ومقدمة.\rأما المقدمة\rفهو ملك لمملكته الخاصة، وهي ذاته، فرعيته فيها جوارحه وحواسه، وجنوده شهوته وغضبه وهواه، فإذا ملك هذه المعاني فأطاعته الرعية وتصرفت الأجناد على مقتضى أمره ولم تملكه واستولى عليها ولم تغلبه فهو ملك في ذاته، وإلى هذا المعنى وقعت الإشارة بقوله: {رَبِّ قَدْ آتَيْتَنِي مِنَ الْمُلْكِ} [يوسف: 101]، أراد به في أحد الوجهين: ملكَه لنفسه حين امتنع من امرأة العزيز حال المُراودة.\rوأما المعيار:\rفإذا استغنى عن كل الناس واحتاج كل الناس إليه فهو الملك في الأرض خاصة، وهذه منزلة الأنبياء صلوات الله عليه، فإنهم استغنوا في الهداية عن\r"], [332, "كل أحد إلا عن الله، واحتاج إليهم في ذلك كل أحد، ويليهم في ذلك العلماء لأنهم ورثتهم، وحظهم من المُلك بقدر حظهم من إرشاد العباد وهدايتهم واستغنائهم في ذلك عن غيرهم، ولهذه الصفات يقرُب العبد من الملائكة في المعنى، ويتوصل به إلى الملك في جنة المأوى، فيتنقل من ملك إلى ملك كما قال تعالى: {وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًا وَمُلْكًا كَبِيرًا} [الإنسان: 20].\rوإلى هذا المعنى أشار بعض العارفين حين قال له بعض المريدين: أوصني، فقال له: (كن ملكاً في الدنيا ملكاً في الآخرة)، فأحاله على الغاية، وأرشده إلى البداية والنهاية، وهذا القدر من المُلك عَطيةٌ من الملِك المطلق.\rوأما مِلك الأعيان الدنيوية والجواهر المالية فهو إلى أن يكون رقاً بما يرتبط به من الجشع والطمع، ويلزمه من الشغب والتعب، أقرب منه إلى أن يكون مُلكاً، ولذلك قال بعض العلماء حين قال له بعض ملوك الدنيا: (ما حاجتك؟ فقال العالِم: أوَلي تقول هذا، ولي عبدان هما سيداك: الحرص والهوى).\rوقد أحسن بعض الشعراء حين قال:\rملكتُ نفسي وكنت عبداً ... فزال رقي وطاب عيشي\rأصحبتُ أرضى بحكم ربي ... إن لم أكن راضياً فأَيْشي\r"], [333, "القول في معنى وصفه بأنه ذو العرش\rوهو الثالث من أسماء التنزيه، وفيه ثلاثة فصول:\rالفصل الأول: في مورده\r"]], "pg": [328, 333]}, "561.91": {"x": [[333, "اعلموا - وفقكم الله - أن هذا الاسم مما ورد به نص القرآن، قال الله سبحانه: {رَفِيعُ الدَّرَجَاتِ ذُو الْعَرْشِ} [غافر: 15]، وكل اسم ورد مقروناً بقولك: (ذو)، فهو من الأسماء والصفات.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [333, 333]}, "561.92": {"x": [[333, "أما قولنا: (ذو)، فقد تقدم شرحه في الكلام على لفظ الذات، وأما العرش فاختلف أهل اللغة فيه على قولين:\rفمنهم من قال: إنه مخلوق عظيم لله، هو أعظم المخلوقات جثة.\rوالثاني: أنها المخلوقات بجملتها، ومنه قول الشاعر:\rتداركتُما الأحلاف قد ثُلَّ عرشُها ... وذُبيانُ قد زلت بأقدامها النعلُ\r"], [334, "وقال آخر:\rبعد ابن جفنة وابن هاتك عرشهِ ... والحارثين تؤملون فَلاحاً\rوقال آخر:\rقد نال عرشاً لم ينله نائلٌ ... إنس ولا جن ولا ديَّارُ\rوقال آخر:\rعُروشٌ تفانوا بعد عز وإمَّةٍ ... هووا بعدما نالوا السلامة والغنى\rومعنى هذا: مالك العرش ورافعه ومعظمه، كما جاء في الأثر: أنه وجد بمكة حَجر مزبور فيه بالخط الأول: (أنا الله ذو بكة)، يعني خالقها ومعظمها.\r"], [335, "الفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [333, 335]}, "561.93": {"x": [[335, "أما علماء الإسلام فاتفقوا على أن العرش مخلوق عظيم لله، هو أعظم المخلوقات قدراً وجثة، وأعلاها جهة ورتبة، وقد بينا حقيقة ذلك في كتاب المشكلين، ولكنا نشير ها هنا إلى الحق فيها على رسم الاختصار فنقول:\rأما لفظ العرش في اللغة فينطلق على معنيين:\rأحدهما: موضع مخصوص يرتب للكبير يكون عليه.\rوالثاني: جميع حال المرء وما يتعلق به.\rولا ينكر منصف أن يأتي هذا اللفظ في الشريعة على هذين المعنيين، وإنما ينبغي تحقيق متناول وروده حيث ورد؛ وإذا تتبع النحرير هذا وجده على قسمين:\rأحدهما: لا يصح فيه متناول إلا مخلوق مخصوص.\rوالثاني: يحتمل أن يتناول ذلك المخلوق المخصوص، ويحتمل أن يتناول جميع المخلوقات؛ ونحن نذكر من ذلك نبذة يسيرة من الأمثلة:\rفأما القسم الأول: فقوله: {وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ وَكَانَ عَرْشُهُ عَلَى الْمَاءِ} [هود: 7]، فقد بين الله أن هذا المخلوق الذي هو العرش المخصوص كان مخلوقاً والماء تحته، والسماوات والأرض\r"], [336, "وما بينهما من المخلوقات في حيز العدم، وقول النبي صلى الله عليه وسلم حين وصف الجنة فقال: (وفوق ذلك عرش الرحمن، ومنه تنفجر أنهار الجنة)، فهذان نصان صريحان لا يكون العرش فيهما إلا مخلوقاً مخصوصاً.\rوأما القسم الثاني: فقوله تعالى: {الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى} [طه: 5]، وقول النبي صلى الله عليه وسلم: (إن الله لما خلق الخلق كتب لهم كتاباً فهو عنده فوق عرشه؛ إن رحمتي سبقت غضبي)، فيحتمل أن يكون هذا اللفظ في الآية والحديث متناوِلاً لهذا المخلوق المخصوص، ويحتمل أن يتناول جميع المخلوقات، ومن هذا القبيل الثاني قوله: {هُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ} [الحديد: 4].\rفأما قوله: {رَفِيعُ الدَّرَجَاتِ ذُو الْعَرْشِ} [غافر: 15]، فيحتمل أيضاً الوجهين، ويصح أن يتناول كل واحد من القسمين، لكن الظاهر فيه عندي أن يكون المراد به المخلوق المخصوص العظيم المقدار، العالي المرتبة الذي ليس فوقه مخلوق؛ يلي صفحته العُليا العدم، وتلي صفحته السفلى الجنة، فإنه سقفها على ما بيناه في اسم رفيع الدرجات.\r"], [337, "القول في اسم القُدوس والسُّبُّوح\rوإنما جمعناهما لكون معناهما واحداً، وهما الرابع والخامس من أسماء التنزيه، وفيها أربعة فصول:\rالفصل الأول: في موردهما\r"]], "pg": [335, 337]}, "561.94": {"x": [[337, "فأما القدوس فهو اسم ورد به القرآن والسنة، قال الله تعالى: {الْمَلِكُ الْقُدُّوسُ} [الحشر: 23]، وقال النبي صلى الله عليه وسلم في سجوده: (سبوح قدوس)، وورد مفسراً في حديث أبي هريرة المتقدم، وأجمعت عليه الأمة لفظاً، وخص الله بفضله أهل السنة به عَقداً.\rوأما السبوح فليس في القرآن، ولا ورد في حديث أبي هريرة المفسر، ولكن جاء في ذكر التسبيح كما تقدم.\rالفصل الثاني: في معناه لغة\r"]], "pg": [337, 337]}, "561.95": {"x": [[337, "وقد ذكر أهل العلم فيه ثلاث عبارات:\r"], [338, "[الأول]: قال بعضهم: هو الطاهر من العيوب، المنزه عن الأنداد والأولاد.\rالثاني: قال بعضهم: هو المطهر من ذلك، والقدس: الطهارة، ومنه سمي بيت المقدس، معناه: البيت الذي يطهَّر من الذنوب، وقيل: البيت الذي طهر من الكفار وعمر بالموحدين، لقوله تعالى: {يَا قَوْمِ ادْخُلُوا الْأَرْضَ الْمُقَدَّسَةَ الَّتِي كَتَبَ اللَّهُ لَكُمْ} [المائدة: 21]، وقيل للجنة: حظيرة القدس، لطهارتها على آفات الدنيا، والقَدَس: السطل الكبير، لأنه يُتطهر به، وأنشدوا لرؤبة:\rدعوت رب العزة القدوسا ... دعاء من لا يقرع الناقوسا\rوسمي جبريل روح القدس؛ لأنه مطهر من كل عيب ودنس، ينزل على كل مطهر من الأنبياء، ولم يأت في الكلام فُعول بضم الفاء إلا السبوح والقدوس، ويقال أيضاً بفتح القاف، وهو قياس الأسماء.\r"], [339, "وقيل في الثالث: القدوس المبارك، والقدس: البركة.\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [337, 339]}, "561.96": {"x": [[339, "وفيه ثلاث مسائل:\rالمسألة الأولى: في اختلاف الناس فيه\r"]], "pg": [339, 339]}, "561.97": {"x": [[339, "نقول: اختلف علماؤنا - رحمة الله عليهم - هل كونه سبوحاً قدوساً يرجع إلى معنى خاص يسمى قدساً وسبحة، أو وصفه بذلك يرجع إلى نفي محض على معنى القول في الوحدانية؟\rفمنهم من قال: إن ذلك ليس يرجع إلى معنى خاص، بل معنى ذلك أنه منزه عن النقص باستحقاق صفات الكمال في معنى الإلهية، إذ لا يليق به أن يكون له شريك أو شبيه أو تلحقه آفة، لم يزل كذلك ولا يزال، قدسه المقدسون أم لا.\rومنهم من قال: إنه وصف على الاختصاص، كالعلم والإرادة والكلام.\rوسترى تحقيق هذه الأغراض في كتاب المقسط، وهو وإن كان أمراً قريباً في الاعتقاد لا يُحيل اعتقادنا الاختلاف فيه، فهو أمر بعيد في الأدلة، تطول فيه مسافة النظر، فألحقناه ببابه واقتصرنا على النبذة الدالة هاهنا، والصحيح عندي أنه ليس بوصف خاص، وإنما هو نفي للنقائص وتنزيه محض.\rالمسألة الثانية: في تركيب معناه على غيره\r"]], "pg": [339, 339]}, "561.98": {"x": [[339, "قال علماؤنا - رحمة الله عليهم -: إن وصفه بذلك يتوجه على ثلاثة أقسام:\r"], [340, "أحدها: أنه مسبَّح على الإطلاق، فهو مسبِّح لنفسه، مقدِّس لها في الأزل، يخبِر عنها بما يجب لها من صفات العلى والأسماء الحسنى.\rالثاني: أنه مسبَّح لخلقه بتسبيحهم له وتقديسهم، فجرى مجرى كونه معبوداً مطاعاً، فيكون وصفاً يرجع إليه من غيره.\rالثالث: أنه ذو القدس والنزاهة، على معنى نفي النقائص.\rالمسألة الثالثة: في تحقيق المآخذ فيه\r"]], "pg": [339, 340]}, "561.99": {"x": [[340, "قد علمتم - أرشدكم الله - أن القدس في اللغة: الطهارة، والتقديس: التطهير، ورأيتم ما سردنا لكم من أقوال علمائنا لغة وحقيقة، وفي ذلك كله تسامح في القول وخلط للحقيقة، فرأينا أن نجلوها بالتفصيل والتحقيق، في كل فن وطريق، فنقول:\rإن لفظ قدوس على بناء فعول، برفع القاف منه ورفع الفاء من بنائه من أبنية أسماء الفاعلين، كما أنه بفتح القاف من أبنية الفاعلين، وقد جاء في الأسماء مثله بضم الفاء من بنائه، وهو ذُرّوح لواحد الذراريح، ضبطناه في عدة مواضع على جماعة الأشياخ بضم الذال، وإذا كان هكذا لم يصح أن يكون تأويله الطاهر، وإن كان معنى الطاهر فيه حقيقة، ولكنه من دلائل القدوس ومقتضياته، لا من تفسيره ومعناه الخاص له الأولِ في الأولى به،\r"], [341, "وبين المعنى الذي هو تفسير للفظ وبين المعنى الذي هو من مقتضياته بون كبير بيناه من قبل، وسترى أمثاله.\rوإنما قلنا ذلك لأن بناء القدوس والسبوح، بناء اسم فاعل يتعدى من فعل يتعدى، وقولنا (طاهر) بناء فاعل لا يتعدى من فعل لا يتعدى، فلا يصح أن يكون أحدهما تفسيراً للآخر، ولا يصح أيضاً أن يكون تأويله المطهَّر بنصب الهاء وتشديدها بناء المفعول، ولا يصح لذلك أيضاً أن يكون تأويله المبارك، لأن البركة غرض مغاير للقدس، ولا يصح تفسيره بها.\rوإنما يجب أن يكون تأويله لغة: المطهِّر المنزِّه بكسر الهاء والزاي من الاسمين والعين من بنائهما بناء أسماء الفاعلين، وإن كان كل فاعل يتعدى يقتضي مفعولاً، وكل مفعول يقتضي فاعلاً، ولكن الفاعل هاهنا أحق وأسبق، لأنه كان تعالى في الأزل قدوساً سبوحاً، ولم يكن هنالك مقدس ولا مسبح إلا هو، أخبر تعالى بقوله عن اسمه ووصفه، وإذا تبين هذا لم يكن له معنى إلا أنه المقدس لنفسه بإخباره عنها بالتوحيد والإجلال والإكرام، واستحالة النقائص عليه، وعجز الأوهام عنه، فرجع الكلام إلى إخباره عن نفسه أو خلقه للأدلة الدالة على تقديسه وتطهيره وتوحيده، أو إلى تقديسه لخلقه وتطهيره لهم على مقادير مخصوصة وفي معان معينة، فيعود حينئذ إلى الخالق، ويرجع إلى صفات الأفعال، ويطيح غير ذلك من التأويلات.\r"], [342, "فتبصروا في هذا، فإنه لا يتم لأحد معرفة هذه الأغراض إلا أن يكون ريان من اللغة، ذا عرفان بالحقائق، فأما مع الظماء من ذلك والخوى فلا ينبغي أن يتعرض لذلك ولا يتصدى.\rالفصل الرابع: في التنزيل\r"]], "pg": [340, 342]}, "561.100": {"x": [[342, "إذا ثبت هذا العقد للعبد توضحت له منزلتان؛ العليا لله والسفلى له.\rفأما العليا للرب تعالى:\rفنعته بالقدوس، وتعيين التقديس له، فإنه يوجب له أوصافاً عشرة:\rالأول: تقديسه عن الشركاء.\rالثاني: تقديسه عن النظراء.\rالثالث: تقديسه عن الأضداد.\rالرابع: تقديسه عن الأولاد.\rالخامس: تقديسه عن الأوهام.\rالسادس: تقديسه عن التحديد.\rالسابع: أنه لا تدركه الأبصار بالتصوير.\rالثامن: تقديسه عن الحاجة إلى الخلق.\rالتاسع: أن تطهير غيره إليه.\rالعاشر: - وهو فائدتها - أن له الكمال في كل وصف لاستحالة النقص عليه.\r"], [343, "تنبيه على وهم:\rقال بعض المتأخرين من علمائنا: (القدوس: هو المنزه عن كل وصف يدركه حس أو يتصوره خيال ووهم أو يختلج به ضمير، لأنه في الغاية من التقدس والتطهر)، فلو وقف هاهنا وأمسك عنانه فيه لكان حسناً، ولكنه أسرف فقال: (ولست أقول إنه منزه عن العيوب والنقائص، فإن ذلك يكاد يقرب من سوء الأدب، فليس يحسن أن يقول القائل: ملك البلد ليس بحائك ولا حجام، فإن نفي الوجود يكاد يوهم الوجود، وفي ذلك الإيهام نقص، بل أقول: إنه منزه عن أوصاف الكمال التي يظنها أكثر الخلق كمالاً، فإن الخلق نظروا إلى أوصاف كمالهم فوصفوه بها وهو منزه عنها).\r"], [344, "قال الإمام الحافظ رضي الله عنه: مرتبة هذا القائل عظيمة ووهمه أعظم، هذا تعمق لا طائل وراءه ولا تحقيق معه، بل نقدس الله ونسبحه عن كل عيب ونقص، وليس ما نقدسه عنه ممكناً في حقه، وإنما قدسناه عما نسبه الكفار إليه، وقد نفى الله سبحانه عن نفسه الشريك والصاحبة والولد، وكل محال نسبه إليه أهل الباطل والضلال، وكان ذلك غاية في التوحيد ونهاية الأدب في الإيمان.\rوإنما فاتته دقيقة من التحقيق، وهي: أنا لا نبتدئ نحن بنفي وصف عنه من الباطل لم يقله قائل ولا نسبه إليه مبطل، وكان ذلك حينئذ أمراً معدوداً في التكلف، محسوباً من سوء الأدب، فأما وقد تكلم المبطلون بالمحال، واقتحموا ورطات الضلال، فتقديسه وتنزيهه عن ذلك فرض وجب، لا يُحسب من جملة سوء الأدب، وهذا بيّن لمن كان له في الحقائق قلب ومتقلَّب.\rالمرتبة السفلى للعبد\rوهي بأن ينزِّه نفسه عن الشهوات، وماله عن الشبهات، وقلبه عن الغفلات، وجوارحه عن المخالفات، ومطامعه عن الملاحظات، ويترفع عما\r"], [345, "تشاركه فيه البهائم من الإدراكات، فيترقى بذلك إلى معالم الأرض والسماوات، وما فيها من العبر والآيات، فإذا حصل في هذا المقام فقد تبحبح في حظيرة القدس.\r"], [346, "القول في اسم السلام\rوفيه أربعة فصول، وهو السادس من أسماء التنزيه\rالفصل الأول: في مورده\r"]], "pg": [342, 346]}, "561.101": {"x": [[346, "وقد ورد به القرآن والسنة وأجمعت عليه الأمة، قال الله تعالى: {السَّلَامُ الْمُؤْمِنُ الْمُهَيْمِنُ} [الحشر: 23]، وقال: {وَاللَّهُ يَدْعُو إِلَى دَارِ السَّلَامِ} [يونس: 25]، يعني: إلى دار الله، لقول النبي صلى الله عليه وسلم في حديث الشفاعة: (فأستأذن على ربي في داره)، وورد في حديث أبي هريرة المفسَّر مفسَّراً، وفي الصحيح عن ابن مسعود أن النبي صلى الله عليه وسلم قال: (فإن الله هو السلام)، وفي حديث أبي هريرة أنه كان يقول بعد السلام: (اللهم أنت السلام، ومنك السلام، تباركت ذا الجلال والإكرام).\r"], [347, "وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [346, 347]}, "561.102": {"x": [[347, "وفيه كلمتان:\rإحداهما: ذو.\rوالثانية: السلام.\rفأما قولنا: (ذو)، فقد سبق بيانه، وأما السلام فهو والسلامة: مصدران كالرضاع والرضاعة، وكذلك قولنا: (سلام عليكم) في التحية، هو كنحو هذا، وقد بينا تحقيق القول فيه في كتاب شرح الترمذي بما يُغني عن ذكره هاهنا لأنه ليس من بابه.\rالفصل الثالث: في شرحه حقيقة وعقيدة\r"]], "pg": [347, 347]}, "561.103": {"x": [[347, "اتفق العلماء - رحمة الله عليهم - على أن معنى قولنا في الله: (السلام): النسبة، تقديره: ذو السلام.\r"], [348, "والنسبة في كلام العرب على ثلاثة أوجه:\rأحدها: بالياء، كقولك: أسدي وبكري.\rوالثاني: بالجمع، كقولك: المهالبة، والصقالبة، والأزارقة.\rوالثالث: بذي وذات، كقولك: رجلٌ مالٌ، وكبشٌ صافٌ، وامرأة عاشق، وناقة ضامر، أي: رجل ذو مال، وكبش ذو صوف، وامرأة ذات عشق، وناقة ذات ضُمر.\rثم اختلفوا في توجيه النسبة على ثلاثة أقوال:\rالأول: معناه: الذي سَلِمَ من كل عيب، وبرئ من كل آفة ونقص يليق بسواه من المخلوقات.\rالثاني: معنى ذو السلام: أي المسلِّم على عباده، كما قال: {سَلَامٌ قَوْلًا مِّن رَّبٍّ رَّحِيمٍ} [يس: 58].\rالثالث: أن معناه: سلم الخلق من ظلمه.\r"], [349, "والصحيح أنه: ذو السلام من كل وجه، فذاته برئت من الفناء والحوادث، وصفاته برئت عن النقائص، وأفعاله برئت عن العيب والظلم، فإذا قلنا: إنه السلام، بمعنى أن ذاته سلمت من العيب، وصفاته من النقص، وأفعاله من الظلم، فهو بمعنى القدوس سواءً، فركِّبه عليه.\rوإذا قلنا: إنه بمعنى قول القائل: سلام عليكم، فهو من صفات المعنى، كالعلم والقدرة، ويدل عليه قوله مخبراً عن حال الدنيا: {قُلِ الْحَمْدُ لِلَّهِ وَسَلَامٌ عَلَى عِبَادِهِ الَّذِينَ اصْطَفَى} [النمل: 59]، وكما قال مخبراً عن حال الآخرة: {سَلَامٌ قَوْلًا مِّن رَّبٍّ رَّحِيمٍ} [يس: 58].\rوإذا قلنا: إنه بمعنى السلامة من الظلم، كان من صفات الفعل، كالخالق والبارئ ونحوه.\rوالصحيح أنه السلام بالمعاني كلها على التمام والكمال، في الذات والوجود والصفات والفعل، وبمعنى الكلام والقول.\rالفصل الرابع: في التنزيل\r"]], "pg": [347, 349]}, "561.104": {"x": [[349, "إذا علم العبد أن الرب تعالى هو السلام بهذه المعاني كلها؛ فليعلم أن المنزلة العليا فيها لله تعالى، ويجب له من ذلك ستة أحكام:\r"], [350, "الأول: أن السلام به ومنه وله، وليس في الوجود سلام إلا وهو إليه منسوب، وعليه محسوب، وهو جملة لما بعده، وما يأتي تفسير له.\rالثاني: أنه سليم عن النقص.\rالثالث: أن تحيته منه لأهل طاعته في دنياه وآخرته.\rالرابع: أن السلامة منه لمن عبده بهبة الإخلاص والتوفيق، لرسم الامتثال بوصف التحقيق والمراد.\rالخامس: أن السلامة منه لمن عصاه في حال دون حال.\rالسادس: أن السلامة منه لمن كفر به في الدنيا، فهو على العموم والتمام في كل متعلَّق.\rالمنزلة السفلى للعبد\rوذلك بأن يسلم قلبه عن الصفات المذمومة حتى يأتي الله بقلب سليم، ولسانَه عن الأقوال المكروهة فيلقى الله ذا لهجة، وأفعالَه عن المخالفات فيلقاه متَّقياً.\r"], [351, "وإلى هذا المعنى وقعت الإشارة بقوله: (المسلم من سلم المسلمون من لسانه ويده).\rوأقوى من ذلك أن يسلم من ذلك من آذاه، فهو يرى ربه تعالى قد سلم الكافر من معاجلته في الدنيا بالعقوبة مع ما يأتيه من الكفر.\rوقد روي أن رسول الله صلى الله عليه وسلم لم ينتقم لنفسه قط، وقد روي أن بعض العلماء سمع رجلاً يغتاب آخر فقال له: (هل غزوت هذا العام؟ قال: لا، قال: فكيف سلم منك الكفار ولم يسلم منك المسلمون؟)\rوهذا مَهيَع لمن احتذى واتبع، ومنهج لمن شرح صدره وثلج.\r"], [352, "القول في اسم العزيز\rوهو السابع من أسماء التنزيه، وفيه أربعة فصول\rالفصل الأول: في مورده\r"]], "pg": [349, 352]}, "561.105": {"x": [[352, "وهو اسم ورد به القرآن، قال الله تعالى: {الْعَزِيزُ الْجَبَّارُ} [الحشر: 23]، وورد في حديث أبي هريرة المفسر، وأجمعت عليه الأمة لفظاً ومعنىً، ولكن فاز أهل السنة بتوفيته حقه على ما يأتي بيانه.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [352, 352]}, "561.106": {"x": [[352, "اختلفت عبارات العلماء باللسان في العبارة عنه على سبعة أقوال:\r"], [353, "الأول: أن العزيز هو: المنيع الذي لا يُلحق ولا يُنال، تقول العرب: حصن عزيز، إذا كان لا يوصل إليه، ومنه قول الهُذلي يصف العُقاب:\rحتى انتهيتُ إلى فراش عزيزةٍ ... سوداء روثةُ أنفها كالمِخصفِ\rالثاني: أن يكون العزيز: الغالب، مأخوذاً من قوله تعالى: {وَعَزَّنِي فِي الْخِطَابِ} [ص: 23]، أي: غلبني، وقول العرب: مَن عَز بَز، تعني: من غلب سلب، وتصريفه: عز يعُز، بضم العين في المستقبل.\rالثالث: أن يكون بمعنى الشدة والقوة، ومنه قوله تعالى: {فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ} [يس: 14]، أي: قوينا وشددنا، ومنه قولهم: أرض عَزاز، وهي\r"], [354, "التي تشتد عليها الأقدام، ومنه قولهم في المثل: (إذا عز أخوك فهِن)، بكسر الهاء، المعنى: إذا اشتد أخوك فلِن، وتصريف فعله: عز يعَز، بفتح العين في المستقبل.\rالرابع: أن يكون بمعنى: نفاسة القَدر، يقال: شيء عزيز: إذا عُدم مثاله، وتصريفه: عز يعِز، بكسر العين.\rالخامس: أن يكون بمعنى: المعز، فعيل بمعنى مفعل، وذلك كثير في القرآن ولغات العرب، قال تعالى: {عَذَابٌ أَلِيمٌ} يعني: مؤلماً.\rالسادس: أنه عزيز عند أوليائه، لا يؤثِرون على طاعته شيئاً، ويكون فعيل فيه بمعنى مفعول، كقولهم: كف خضيب، ورجل قتيل.\r"], [355, "السابع: أن يكون عزيزاً بمعنى الإضافة، المعنى: عزيز عليه أولياؤه، كما قال تعالى: {عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ} [التوبة: 128].\rالفصل الثالث في شرحه حقيقة\r"]], "pg": [352, 355]}, "561.107": {"x": [[355, "وفيه أربع مسائل:\rالمسألة الأولى: في ضبط هذه المعاني اللغوية\r"]], "pg": [355, 355]}, "561.108": {"x": [[355, "وقد ذكرنا فيها سبعة أوجه حسب ما عددها العلماء، ولكنها ترجع إلى ثلاثة في التحقيق، وإنما كان كذلك لأن التصريف فيها على ثلاثة أقسام، إما فتح العين من الفعل المستقبل، وإما ضمها، وإما كسرها، إذ لا يصح أن يزيد المعنى على الفعل المتصرف.\rوالأوجه الثلاثة صحيحة في اللغة، ومعانيها وإن كانت متباينة في اللفظ، صحيحة في المعنى، وما خرج عنها من بقية الأقسام راجع إليها.\rالمسألة الثانية:\r"]], "pg": [355, 355]}, "561.109": {"x": [[355, "قال بعض علمائنا: (العزيز: الذي تشتد الحاجة إليه)، وليس هذا من معاني لفظ العزيز، فإنه لا يتفسر به ولا يتصرف به، وإنما هو\r"], [356, "من لوازمه في بعض الوجوه، وليس معنى الشيء كل ما كان من لوازمه ومقتضاه، وإنما معناه ما كان طبقاً عليه مأخوذاً من لفظه، ونضرب لذلك مثالاً يكشفه لكم، فنقول:\rلفظ (البيت) يفيد: السطح والجدار والسقف والباب إفادة طبقية مقابلة لمعناه، لا تخرج عنه، وتقتضي البنّاء والنجّار اقتضاءً لازماً، إذ لا تقوم إلا به، ولكنه ليس من تفسيره وليس من معناه، وليس كل ممتنع تشتد الحاجة إليه، وإنما تشتد الحاجة إلى الممتنع الذي يكون معدوم النظير في بعض الأحوال، فإذا فهمتم هذا علمتم أنه لا يصح تأويل العزيز بما تشتد الحاجة إليه، لا لغة ولا حقيقة.\rالمسألة الثالثة: في تركيب هذه المعاني اللغوية على الحقيقة ال"]], "pg": [355, 356]}, "561.110": {"x": [[356, "إلهية\rاعلموا أنا إذا قلنا: إن العزيز: هو الذي لا يُنال ولا تطمع فيه الآمال، مع جواز ذلك عليه، فالذي يستحيل الوصول إليه بكل وجه - إذ لا حد له ولا جهة - أولى أن يسمى عزيزاً، بل فيه هي الحقيقة، وهو العزيز حقاً.\r"], [357, "وإذا قلنا: إن العزيز: هو الغالب، مع جواز أن تنقلب الحال عليه فيعود مغلوباً، فالغالب: الذي لا يتصور أن يعارَض، فكيف أن يغلب المصرف للغلبة الذي يجعلها دولاً؛ تارة لقوم وأخرى لآخرين، أولى أن يكون عزيزاً، وهذا عقد لم يصح إلا لأهل السنة، فإن القدرية وأخوانهم من اليهود يقولون: إن الله سبحانه يُعصى كرهاً ولا يطاع طوعاً، وتعالى أن يكون في مُلكه ما لا يريد.\rوإذا قلنا: إن العزيز هو القوي مع أن القوة له موهوبة، وقد يعود بعد ذلك عاجزاً، فالقوي الذي لا تزول قوته ولم توهب له، بل هي أزلية أبدية أولى أن يكون عزيزاً.\rوإذا قلنا: إن العزيز هو النفيس القَدْرِ الذي يقل وجود مثله، فالذي يستحيل وجود مثله أو ضده أولى أن يكون عزيزاً، بل هي الحقيقة فيه.\rوإذا قلنا: إن العزيز بمعنى: المعز، وهو واهب القدرة ومعطيها، فذلك بالحقيقة له دون من هي بيده عاريّة، فإن العزة لله جميعاً، عزته التي هي\r"], [358, "صفته، وعزته التي يهبها لخلقه، كما أن العلم كله له، علمه الذي هو صفة ذاته، وعلمه الذي وهبه للخلق.\rوإذا قلنا: إنه عزيز عند أوليائه، فمعناه: أن قلوبَهم مملوءةٌ من تعظيمه، وألسنتَهم منطلقةٌ بالثناء عليه، وجوارحهم مستخدَمة له، لم يشركوا معه غيره في عقد ولا قول ولا عمل، كما فعل غيرهم، حيث أخبر عنهم بقوله: {وَمَا يُؤْمِنُ أَكْثَرُهُم بِاللَّهِ إِلَّا وَهُم مُّشْرِكُونَ} [يوسف: 106]، وكما أنه عزيز عند أوليائه كما بينا، فهو عزيز عند أعدائه بالمعنى الأول، فإنه يعز عليهم أن يهتدوا إليه أو يستدلوا عليه.\rوإذا قلنا: إنه عزيز بالإضافة، فأولياؤه أعزاء عليه، بما أكسبهم من العزة، ووهبهم من التوفيق في الدنيا، وجواره في الأخرى. وهو عزيز بهذه المعاني كلها سبحانه.\rالمسألة الرابعة: في شرح العزة\r"]], "pg": [356, 358]}, "561.111": {"x": [[358, "اختلف علماؤنا - رحمة الله عليهم - في شرح العزة:\rفمنهم من قال: إن العزة: صفة خاصة ومعنى زائد عن الذات، بها كان عزيزاً، كالعلم صفة خاصة ومعنى زائد على الذات، كان به عالماً.\rومنهم من قال: إن العزة: عبارة عن مجموع خصال؛ منها: إحاطة علمه، وعموم قدرته، وأنه لا يخرج موجود عن إرادته.\r"], [359, "هذا هو القول الصحيح كما أشرنا إليه وبيناه قبل في اسم القدوس، وأن القدوسية ليست بصفة خاصة، وإنما هي: عبارة عن الوجود المنزَّه عن النقص والنظير، كذلك العزيز: هو الذي لا يُنال بتوهيم ولا تفكير، ولا يلحقه مثال المتشوف في معنى.\rوتحقيق ذلك: أن العزيز إن كان الممتنع الذي لا يُنال فليس الامتناع وصفاً خاصاً، وإنما هو: عبارة عن موجود لا حد له ولا جهة، وذلك تقديس له، وعبارة عن تنزهه عن الآفات. وإن كان العزيز هو الغالب، فذلك عبارة عن فعل يفعله، وهو حينئذ من صفات الأفعال.\rوإن كان العزيز بمعنى: القوي فهو القادر، وله القدرة، وهي صفة معلومة.\rوإن كان بمعنى: نفاسة القدر، فهو كالأول في أنه تنزيه.\rوما في معاني العزيز هو من صفات الفعل كالغالب لا يرجع إلى معنى يتعلق بالذات، وهذا يدُلك على أنه ليس بصفة مخصوصة، ولكن تحقيق هذه الوجوه قد سبق، وأنها ثلاثة كما تقدم.\rفإن قيل: فما معنى قوله: {سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ} [الصافات: 180]، فجعل العزة مربوبة وهي صفة من صفات الله؟\r"], [360, "أجاب عنه ابن فورك بأن قال: (ليس معنى هذا تلك العزة التي هي صفة، وإنما معناه أنه عز عما يصفونه، المراد بذلك: الإنكار على من وصفه من المشركين بالولد، والتقدير: سبحان ربك الرب الذي عز عما يصفونه).\rقال الإمام الحافظ رضي الله عنه: هذا كلام لا يُنجيه عما وقع السؤال عنه من إضافة العزة إلى الربوبية، والجواب الصحيح: أن العلم والقدرة والإرادة والعزة وسائر الصفات الإلهية التي ينطلق اسمها على القديم والمحدَث كلها تضاف إلى الله تعالى، أما القديمة فتضاف إليه تحقيقاً ووصفاً، وأما المحدثة فتضاف إليه تقديراً وخلقاً ومِلكاً، فالعلم له صفة وله خَلق، والعزة له صفة وله خلق، أعطى منها العبد المحدث ما شاء ووهبه ما أراد، فهو المتصف بالعزة القديمة الأصلية، وهو المالك للعزة المحدثة.\rوبينه قوله تعالى: {مَن كَانَ يُرِيدُ الْعِزَّةَ فَلِلَّهِ الْعِزَّةُ جَمِيعًا} [فاطر: 10]، يعني بقوله: {جَمِيعًا} الصفة القديمة والمخلوقة المملوكة، وقوله: {رَبِّ الْعِزَّةِ} يعني: العزة المحدثة المملوكة، ويكون معنى الآية: أنه سبحانه رب العزة، يعطيها للخلق فيعتزون عما يكرهون، ويدفعون ما لا يستحسنون، بالمقدار الذي آتاهم منها، فهو سبحانه بما وجب له من ذلك وما خلق وما ملك أولى أن يعتز عما نسب إليه، وهذا معنى بديع، فافهموه إن شاء الله.\r"], [361, "الفصل الرابع: في التنزيل\r"]], "pg": [358, 361]}, "561.112": {"x": [[361, "المنزلة العليا للرب تعالى\rلا يخفى على من تأمل كلامنا أن الباري تعالى إذا كان عزيزاً وله العزة على الوجوه التي أوضحناها والمعاني التي بيناها فإن ذلك يقتضي له ستة عشر حكماً:\rالأول: أنه عزيز لا يرام بوهم، فكيف بجارحة.\rالثاني: أنه لا يخالَف في المراد، بل تنفذ إرادته على العموم في كل موجود.\rالثالث: أنه لا يوجد له مثل، وبذلك كان إلهاً.\rالرابع: أنه لا يُحط عن المنزلة، وكل عزيز إلى الحط والذلة.\rالخامس: أنه لا يخوَّف بالتهديد، فإن العواقب بيده والأمر كله له.\rالسادس: أنه لا مَخلصَ منه لعموم القدرة وشمول الإحاطة.\rالسابع: أنه ملجأ الهاربين، كما قال النبي صلى الله عليه وسلم: (لا ملجأ ولا منجى منك إلا إليك).\r"], [362, "الثامن: أنه منتهى مطالب المريدين، فإن كل مطلوب إذا عرضت الغاية فيه والمآل انتهى بك إليه، فهو الأمل المنتهى في كل مراد ومطلوب، قال الله تعالى: {وَأَنَّ إِلَى رَبِّكَ الْمُنتَهَى} [النجم: 42].\rالتاسع: أن عليه طريق العارفين، قال سبحانه: {أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ} [فصلت: 53].\rالعاشر: أن عليه ثواب العاملين، قال تعالى: {فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ} [النساء: 100].\rالحادي عشر: أنه لا يدخل في التحديد.\rالثاني عشر: أنه لا يُزاد، {لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا} [الأنبياء: 22]، {وَلَعَلَا بَعْضُهُمْ عَلَى بَعْضٍ} [المؤمنون: 91].\rالثالث عشر: أن رحمته تستنزل بالتملق.\rالرابع عشر: أنه لا تلحقه آفة لتقدسه عن النقائص.\rالخامس عشر: أنه يعذب من يشاء، ويرحم من يشاء، لا حكم للخليقة فيه.\rالسادس عشر: أنه يَذل عند عزته الأعزاءُ، ويَشرف بتشريفه الأذلاء، فالمرء يرى أنه لا أذل من كلب، ولكنه قرنه بأوليائه، وذكره بتشريف كلامه.\r"], [363, "المنزلة الثانية للعبد:\rقد بينا أن العزة لله يهبها لمن يشاء، فلا يعطيها إلا لأهل طاعته على مقدار أعمالهم، وأعظمها للأنبياء، ثم الذين يلونهم، ثم الذين يلونهم، في الدنيا والآخرة.\rأما في الدنيا فبالمعاني اللغوية المتقدمة، وأما في الأخرى فبجوار الله تعالى.\rوعلى العبد في انتهائه إلى هذا المقام أربعة أحكام:\rالأول: أن يخلع عن قلبه إعزازَ المخلوق.\rوالثاني: أن يمحو عن لسانه تعظيمه.\rوالثالث: أن ينزِّه بدنه عن خدمة غيره؛ وأرشق عبارة في ذلك قولُ بعض علماء الإشارة: (حقيقة المعرفة أن تحقِر الأقدار سوى قدْره، وتمحو الأذكار حاشى ذكره)، وأفقه كلام فيه ما روي في الأثر أنه: (من تواضع لغني ذهب ثلثا دينه).\r"], [364, "قال بعض العلماء: (إنما قال ثلثا دينه لأن المرء بثلاثة أشياء: بقلبه ولسانه وبدنه، فإذا استخدم اللسان والبدن في تعظيم الغني ذهب الثلثان من دينه، وبقي الثلث وهو أثر قلبه)، وما أصدق قول من قال: (ليس العز بالماء والطين والتكبر على المساكين، إنما العز بطاعة رب العالمين).\rالرابع: ألا يطلب العز إلا منه، ولا يكون العز إلا في طاعته.\r"], [365, "القول في اسم الجبار\rوهو الثامن من أسماء التنزيه، وفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [361, 365]}, "561.113": {"x": [[365, "وقد ورد به الكتاب والسنة وأجمعت عليه الأمة، قال الله سبحانه: {الْجَبَّارُ الْمُتَكَبِّرُ} [الحشر: 23]، وقال النبي صلى الله عليه وسلم: (لن تملئ جهنم حتى يضع الجبار فيها قدمه)، وقد بيناه في كتاب المشكلين، وأجمعت الأمة على وصفه بأنه الجبار.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [365, 365]}, "561.114": {"x": [[365, "فيه أربع عبارات:\rالأولى: أنه مأخوذ من قول العرب: تجبر النَّبْتُ: إذا علا واكتمل، ومنه قولهم: رجل جبار: أي طويل، ونخلة جبارة: إذا فات الأيدي جناها، قاله ابن الأنباري.\r"], [366, "الثاني: أن الجبار هو المتكبر، وسيأتي بيانه إن شاء الله تعالى.\rالثالث: أنه فعال، من قولهم: جبر كذا: إذا أصلحه، ومنه قول الشاعر:\rقد جَبر الدينَ الإلهُ فَجَبَرْ\rالرابع: أنه فعال، من قولهم: جبر فلان فلاناً على الشيء: إذا أكرهه عليه، ويقال: أجبره أيضاً، بالألف.\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [365, 366]}, "561.115": {"x": [[366, "وفيه ثلاث مسائل:\rالمسألة الأولى: في تركيب الحقيقة على الألفاظ اللغوية\r"]], "pg": [366, 366]}, "561.116": {"x": [[366, "فنقول: كيف ما تصرف معنى الجبار في اللغة بالوجوه التي وصفناها فإنها كلها موجودة في حق الله حقيقة على وصف الكمال.\rفإنه إذا كان معنى الجبار مأخوذاً من قولهم: نخلة جبارة، فمعناه حقيقة فيه كامل، لأنه لا يناله وهم، ولا يحيط به علم، فكيف أن يتصل به جسم؟\r"], [367, "وإن كان مأخوذاً من قولهم: جبر كذا: إذا أصلحه، فمن يجبر الكسير، ويُثري الفقير، ويغني المَفاقر من الرزق، ويسد الخلل في المعاش من الرتق إلا الله تعالى.\rوإن كان مأخوذاً من الإكراه، فهو الذي يَجبر الخلق على ما أراد، والذي يحصل مراده دون كل مراد، ولا يجري في سلطانه إلا ما يريد، تنفذ مشيئته في كل أحد، ولا تناله مشيئة أحد.\rفإن قيل: فإذا قلتم: إن الله سبحانه جبار، لأنه يجبُر الخلق على مراده فأنتم إذا مجبِرة، وقد نفيتم ذلك عن أنفسكم، فكيف تقرون به؟\rالجواب: أن الدليل قد قام على أن الجبار فعال من قولهم: جبر: إذا أكره، لأنه وارد في اللغة، جارٍ في العقول، شرفٌ في الأفعال، وذلك يتعلق بوجهين:\rالأول: أنه يخلق في العباد ما يكرهون وهم لا يقدرون على دفعه، كالحركات الضرورية، والزمانات والمكاره، ولا خلاف في هذا.\r"], [368, "الثاني: أنه إذا أراد شيئاً كان، وإذا أراد العبد شيئاً لا يريده هو تعالى لم يكن، فتيسيره لمُراده دون مراد غيره جبر لهم، إذ لا يتصرفون إلا على حكم الإرادة، فلا يخرج أحد عن قبضته، وتتقاصر الأوهام دون معرفته، كما نهى آدم عن أكل الشجرة وأراده فواقعه آدم، وأمر إبليس بالسجود ولم يرد فامتنع منه.\rوعنه وقعت الإشارة بقوله: {وَلَكِن كَرِهَ اللَّهُ انبِعَاثَهُمْ فَثَبَّطَهُمْ} {التوبة: 46]، وإن كان قد أمر جميعهم بالجهاد، ولكنه خلق الكسل والأسباب القاطعة بالخلق، لأنه لم يرد مسيرَهم حين قعدوا.\rالمسألة الثانية: في كونه من صفات التنزيه أو من صفات الذات أو "]], "pg": [366, 368]}, "561.117": {"x": [[368, "من صفات الفعل؟\rاعلموا - وفقكم الله - أنه إذا قلنا: إن وصفه بجبار بمعنى: نخلة جبارة، فهو تنزيه محض على ما بيناه وفسرناه، ويقرُب من معنى القدوس، وعلى هذا هو جبار في الأزل، وفيما لا يزال.\rوإن قلنا: إنه بمعنى: تجبَّر، إذا تكبر، ففي موضعه يكون بيانه، إن شاء الله.\rوإن كان مأخوذاً من قولهم: جبر: إذا أصلح أو إذا أكره، فإنه يرجع إلى معنى الفعل، ويكون حينئذ من صفات الفعل، وذلك بعد خلق الخلق الذين أصلحهم أو أكرههم.\r"], [369, "فهو صحيح في المعاني كلها، لأنه الجبار ذاتاً، والجبار فعلاً، وسترى تفسير الجبار بمعنى: المصلح في باب اسم الرب، والجبار بمعنى المكرم في باب الكريم.\rالمسألة الثالثة: {في الفرق بين الجبرية والقدوسية]\r"]], "pg": [368, 369]}, "561.118": {"x": [[369, "إذا علمتم أن الجبار هو الله تعالى على المعاني المتقدمة كلها بالتمام، فإن علماءنا قالوا: هو جبار من الجبرية والجبروَّة؛ واتفقوا على أنها ليست بصفة خاصة ترجع إلى معنى زائد على الذات، وإنما ترجع إلى ما قدمنا بيانه من أنه مستحق لصفات التعالي والتعظيم على الوجه الذي لا يستحقه سواه ولا يَثبت لغيره، بخلاف القدوسية، وذلك لأن الجبرية تنزيه خاص، والقدوسية تنزيه عام يدخل تحته كل تنزيه، فلما كان الوصف بالقدوسية عاماً تردد في النظر أنه معنى، وأنه وصف خاص يشمل أنواعاً من التنزيهات، منها الجبار وغيره، أو هو بعمومه وشموله لهذه الوجوه كلها من التنزيه تنزيه أيضاً، على ما بيناه من قبل.\rالفصل الرابع: في التنزيل\r"]], "pg": [369, 369]}, "561.119": {"x": [[369, "اعلموا - يسر الله الهداية لنا ولكم - أن العبد إذا تحقق وصف ربه بأنه الجبار على التمام والكمال بهذه المعاني، فإنه يتحقق أن للباري تعالى بذلك أوصافاً يختص بها، وهي اثنا عشر:\r"], [370, "الأول: أنه يستغني عن الأتباع، فلا يتكثر بهم من قلة، ولا يستنصر بهم عن ذلة، كما قال تعالى: {وَلَمْ يَكُن لَّهُ وَلِيٌّ مِّنَ الذُّلِّ} [الإسراء: 111].\rالثاني: أنه لا يحنو عند التعذيب بعد الحجة، وإن كان يجيب المضطر إذا استقال من العثرة.\rالثالث: أنه لا يشق عليه البذل، إذا أعطى أعطى عن سعة، وإذا منع منع عن حكمة، من غير تكلف ولا مؤونة، كما روي عن النبي صلى الله عليه وسلم أنه قال: (قال الله: عطائي كلام، ومنعي كلام، وإماتتي كلام، وإحيائي كلام، إنما قولي لشيء إذا أردته أن أقول له: كن، فيكون).\rالرابع: أنه لا يكترث بالناكثين، ولا يفرح بالمخلصين، كما روى أبو ذر عن النبي صلى الله عليه وسلم: (قال الله: يا عبادي، لو أن أولكم وآخركم، وإنسكم وجنكم، اجتمعوا على أتقى قلب رجل ما زاد ذلك في ملكي، عبادي، لو أن أولكم وآخركم، وإنسكم وجنكم، اجتمعوا على أفجر قلب رجل ما نقص ذلك من ملكي).\rالخامس: أنه لا يتلهف على ما لم يكن، ولا يتمنى ما لا يكون.\rالسادس: أنه لا يؤثر فيه الكون والفساد، ولا يبالي بالعدم والوجود.\r"], [371, "السابع: أنه لا يُعارض في الفعل.\rالثامن: أنه لا يطالب بالعلة، كما قال تعالى: {لَا يُسْأَلُ عَمَّا يَفْعَلُ} [الأنبياء: 23].\rالتاسع: أنه لا يُحجَر عليه في إرادة.\rالعاشر: أنه لا يتوجه عليه الطلب بالإلزام، إنما هو دعاءٌ وتضرع.\rالحادي عشر: أنه لا يجب عليه الفعل.\rالثاني عشر: أنه وإن كان لا سبيل إليه فلا بد منه.\rالمنزلة الثانية للعبد:\rوهي في ثلاثة أحوال:\rالأول: أن يلزم حال الافتقار لما هو عليه من الافتقار، كما روي عن النبي صلى الله عليه وسلم أنه كان يقول: (اللهم أحيني مسكيناً، وأمتني مسكيناً، واحشرني في زمرة المساكين).\rالثاني: أن يتدرع ثوب الاستكانة، وإن عظمت منه المكانة، كما قال النبي صلى الله عليه وسلم: (اللهم اغفر لي خطئي وعمدي، وكل ذلك عندي).\r"], [372, "الثالث: أن يستجير عند غلبة الجبابرة بعزة سلطانه، كما قال النبي صلى الله عليه وسلم: (اللهم إليك أشكو ضعف قوتي، وقلة حيلتي، وهواني على الناس، يا أرحم الراحمين، أنت رب المستضعفين، وأنت ربي، إلى من تكلني، إلى بعيد يتجهمني، أو إلى عدو ملكته أمري، إن لم يكن بك علي غضب فلا أبالي، ولكن عافيتك أوسع لي، أعوذ بنور وجهك الذي أشرقت به الظلم وصلح عليه أمر الدنيا والآخرة من أن تُحل غضبك بي، أو تُنزل سخطك علي، لك العتبى حتى ترضى، ولا حول ولا قوة إلا بك).\r"], [373, "القول في اسم المتكبر\rوهو الاسم التاسع من أسماء التنزيه، وفيه أربعة فصول\rالفصل الأول: في مورده\r"]], "pg": [369, 373]}, "561.120": {"x": [[373, "وقد ورد به القرآن وأجمعت عليه الأمة، قال تعالى: {الْجَبَّارُ الْمُتَكَبِّرُ} [الحشر: 23]، ولم يختلف أحد من الناس في وصفه تعالى بذلك.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [373, 373]}, "561.121": {"x": [[373, "اعلموا - أرشدكم الله - أن المتكبر هو المتفعل، من تكبَّر أي: تعاظم، وهو أن يرى غيره حقيراً بالإضافة إلى نفسه، يقال: تكبر واستكبر إذا كان كذلك، ومنه قول الله تعالى مخبِراً عن قوله لإبليس: {أَسْتَكْبَرْتَ أَمْ كُنتَ مِنَ الْعَالِينَ} [ص: 75].\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [373, 373]}, "561.122": {"x": [[373, "وفيه أربع مسائل:\rالمسألة الأولى\r"]], "pg": [373, 373]}, "561.123": {"x": [[373, "اختلف العلماء في العبارة عنه على أربعة أقوال:\r"], [374, "الأول: أن المتكبر هو المتعالي عن صفات الخلق.\rالثاني: أنه تكبر على عُتاة خلقه فقصمهم.\rالثالث: أن المتكبر: المتعالي عن صفات الخلق، واستحقاقه لنعوت الجلال، وتقدسه عن النقص، وأن تكبره وكونه كذلك عائدٌ إلى وجود ذاته على هذه الأوصاف من التقديس والتنزيه، وذلك يعود إلى وصف ذاتي.\rالرابع: أن تكبره: قصمه للعتاة من خلقه، فيعود إلى صفات الفعل.\rالمسألة الثانية: في تحقيق المعنى فيه\r"]], "pg": [373, 374]}, "561.124": {"x": [[374, "اعلموا - وفقكم الله - أن علماءنا لما نظروا نظر التحقيق إلى اختلاف العبارات في المتكبر، فلم يروا فيها غوصاً على الحقيقة فقال من حقق منهم: إن المتكبر هو المتفعل من تكبَّر، وذلك يفيد اكتساب الفعل، لأن بناء تفعل واستفعل في اللغة موضوع لاكتساب الفعل، وذلك محال في حق الإله، فهذه تاء التخصيص وليست تاء الاكتساب، وهذا ظاهر يفتقر إلى بيان جلي.\rوالتحقيق فيه عندي: أن المتكبر في وصف الباري إن عاد إلى صفة الفعل فذلك أمر كان بعد أن لم يكن، فيكون كسائر الأفعال المخلوقة، وإن عاد إلى وصف الذات فنقول حينئذ: إن التفعل في حق المخلوق عبارة عن كونه على تلك الصفة، وكذلك في حق الخالق، لكنْ صفةُ المخلوق حادثة، وصفة\r"], [375, "الخالق لا أول لها، فالعبارة واحدة، والحقيقة في وجود تلك الصفة فيها واحدة، وهما يختلفان في الحدوث والقِدم، ولا يؤثر ذلك في الحقيقة.\rوبعد هذا التفهيم يحسُن أن يعبَّر عن التاء في حقه تعالى بالاختصاص، وفي حق المحدَث بالاكتساب.\rفيقال في حق المخلوق: تكبر: إذا اكتسب الكِبر وتعاطاه، وهو أن يرى نفسه فوق الخلق، ويَخرجَ عن سمة العبد من المذلة.\rويقال في حق الله تعالى: تكبر: من الكبرياء، أي تنزَّه عن وصف المخلوق وتفرد بالصفات العُلى.\rوإنما كان الكِبر في حق المخلوق مذموماً لأن الخلق محل النقص وموضع المذلة والخضوع، فإذا تكبر تكلف وتعاطى وتعدى، فإن الكبرياء لله تعالى في الأرض والسماء، فإذا تعاطى أن يتصف بغير ما يليق به وخرج باعتقاده عن حده صار لأجل ذلك مذموماً مدحوراً، كما قيل لإبليس، فإنه لما أُمر بالسجود كان من حقه أن يلتزم وصف العبد بالامتثال، فتعاطى المخالفة، ورأى نفسه فوق ما أمر به، وجهل حقيقة التفضيل، وظنها في حق المخلوق في الأوصاف الذاتية.\r"], [376, "وحقيقة ذلك أن الجلال والتفضيل في الوصف الذاتي ليس إلا لله تعالى، وأن التفضيل في حق المخلوق إنما هو تفضيل الخالق له وإخباره عن ذلك فيه، فكل ما خلق تعالى فضلاً فهو الفضل، وجهل إبليس بذلك أحقَّ اللعنةَ عليه.\rالمسألة الثالثة: في تحقيق القول في الكبرياء، هل هي تنزيه أو "]], "pg": [374, 376]}, "561.125": {"x": [[376, "وصف معنوي؟\rقد سردنا أقوال علمائنا في ذلك على نصوصها، والذي يقتضيه الدليل ما قدمناه من أن المتكبر في الحادث: هو الذي يرى نفسه فوق الخلق، والمتكبر بالحقيقة والوجوب هو الله، وهو فوق الخلق لتنزهه عن صفات النقص، ووجوب الكمال له في صفات الكمال بتنزيهها عن الآفات، فصار تنزيهاً محضاً.\rفالباري تعالى متكبر حقيقة بهذا المعنى، وهو يرى نفسه فوق الخلق، ويعلمها كذلك ويخبر عنها، وتكبر على الخلق بأن حجبهم عن النظر إليه، وألزمهم وصف القصور عن الاطلاع عليه، كما قال النبي صلى الله عليه وسلم في صفة أهل الجنة: (وما بينهم وبين أن ينظروا إلى ربهم إلا رداء الكبرياء على وجهه في جنة عدْن)، ويتكبر على العصاة، فهو متكبر تنزيهاً، متكبر علماً، متكبر بالكلام\r"], [377, "والإخبار، متكبر بالحجاب، متكبر بالعقاب والانتقام، فهو المتكبر بالإطلاق حقاً وصدقاً.\rالمسألة الرابعة: في بيان اختصاص الباري بهذين الاسمين\r"]], "pg": [376, 377]}, "561.126": {"x": [[377, "اعلموا - وفقكم الله - أن قوله: {الْجَبَّارُ الْمُتَكَبِّرُ} على حسب ما بيناهما من الأسماء المختصة لله تعالى بمعنى المدح، وهما في تسمية العبد وصف للذم، وإنما كان كذلك لأن الجبرية والكبرياء - كما قلنا - تناقض حال العبد وتضاده، فلم تكن له بحال، وتجب للباري تعالى فاختصت به.\rونكتة ذلك المفسِّرة له الكاشفة لخفائه: أن أسماء الله تعالى في جواز الإطلاق والإخبار بها لفظاً عنه وعن العباد على أربعة أضرب:\rالأول: ما لا يجوز أن يخبَر بها عن العبد بحال، كقولنا: الله والرحمن، ولهذا قال تعالى: {قُلِ ادْعُوا اللَّهَ أَوِ ادْعُوا الرَّحْمَنَ} [الإسراء: 110].\rالثاني: ما يكون في صفة الله تعالى واجباً، وفي صفة العبد جائزاً، كالعالم والقادر.\rالثالث: ما يكون في حق الله حقاً، وفي حق العبد باطلاً، كقولنا: الجبار المتكبر، للمعنى الذي بيناه.\rالرابع: ما يخبَر به عن الله تعالى وعن العبد، لكن يكون جائزاً في حق الله تعالى بمعنى، ويكون في حق المخلوق جائزاً بمعنى آخر يستحيل ذلك المعنى\r"], [378, "على الله تعالى، مثاله: قولنا: الخالق، فإن له أربعة معانٍ: الإخبار عن الله تعالى، جائز منها بثلاثة معانٍ، والمعنى الواحد جائز في حق العبد، محال في حق المتكبر المتعالي سبحانه، على ما يأتي بيانه إن شاء الله.\rفهذه نكتة تكشف لك سراً عظيماً من أسرار أسماء الله تعالى، وتكشف لك عن دقيقة في حق افتراق الاشتراك في الإطلاق على الله سبحانه وعلى العبد في ألفاظ الأسماء ومعانيها.\rالفصل الرابع: في التنزيل\r"]], "pg": [377, 378]}, "561.127": {"x": [[378, "إذا علم العبد معنى هذا الاسم تحقق أن للباري تعالى في ذلك أحكاماً تسعة:\rالأول: أنه لا مقدار لشيء عنده إلا بما وصفه، لما بيناه من أن التفضيل للذوات ليس للمخلوقات.\rالثاني: أنه لا يؤثَّر فيه اللوم.\rالثالث: أن الهيبة له ومنه، فإن قيل: وكيف تكون الهيبة له وقد شتمه الكفار ونسبوا إليه ما لا ينبغي؟ كما قال تعالى: {يشتمني ابن آدم ولم يكن له أن يشتمني).\r"], [379, "الجواب: أننا نقول: ما قالوا ذلك وهم يعتقدونه شتماً، إنما قالوه وهم يعتقدونه تعظيماً وتوقيراً، فلذلك أطلق به ألسنتهم.\rالرابع: أنه لا يلزمه الثواب، فإن العبادة تجب له بحق المِلك.\rالخامس: أنه لا يَهاب العواقب.\rالسادس: أنه لا يخلق للنفع، ولا يوجد للدفع.\rالسابع: أنه لا تتوجه عليه المنة بالطاعات، فإنها خلق له.\rالثامن: أنه لا يَشرف بالأتباع، ولا ينحط بالأعداء.\rالتاسع: أنه لا يأمر ولا ينهى لفائدة يجتلبها ولا مضرة يدفعها، لتقدسه عن ذلك كله.\rالمنزلة السفلى للعبد\rعليه فيها أربعة أحكام:\rالأول: أن يتواضع لله كلما حدثت له رفعة.\rالثاني: أن يستحقر باعتقاده كل شيء بالإضافة إلى الله سبحانه.\rالثالث: أن يتواضع لأولياء الله على مقادير منازلهم.\rالرابع: أن يتعاظم على الكافر والعاصي والغني على مقاديرهم، وكيفية التعاظم على كل واحد منهم من أحكام الدين، وهو مذكور في كتب إصلاح الأعمال.\r"], [380, "القول في اسم العلي\rوهو العاشر من أسماء التنزيه، وفيه أربعة فصول\rالفصل الأول: في مورده\r"]], "pg": [378, 380]}, "561.128": {"x": [[380, "هو اسم ورد به القرآن والسنة وأجمعت عليه الأمة، قال الله تعالى: {فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ} [غافر: 12]، وورد مفسَّراً في حديث أبي هريرة، وله أربعة أبنية: العلي، والعالي، والأعلى، والمتعالي.\rفأما العلي: فقد ورد كما تقدم.\rوأما العالي: فهو فاعل منه.\rوأما الأعلى: فهو بناء أفعل منه، وقد ورد به القرآن، قال تعالى: {سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى} [الأعلى: 1]، وكان النبي صلى الله عليه وسلم يقول في صلاته: (سبحان ربي الأعلى).\rوأما المتعالي: فورد في القرآن، قال تعالى: {الْكَبِيرُ الْمُتَعَالِ} [الرعد: 9].\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [380, 380]}, "561.129": {"x": [[380, "أما العلي في اللغة فهو: فعيل بمعنى فاعل، تقول: علا يعلو علواً فهو عالٍ، وأعلى: أفعل منه، ومتعال: متفاعل منه. وله معنيان:\r"], [381, "أحدهما: علو المكان، كالحائط على الأس، والسقف على الحائط.\rوالثاني: علو المكانة، كعلو الشريف على الوضيع، وكعلو العليم على الجهول.\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [380, 381]}, "561.130": {"x": [[381, "وفيه ثلاث مسائل:\rالمسألة الأولى: في كشف الحقيقة والمجاز فيه\r"]], "pg": [381, 381]}, "561.131": {"x": [[381, "إذا عرفتم - وفقكم الله - معنى العلو في اللغة بقسميه، فحقيقته علو المكان، ويُستعمل في علو المكانة مجازاً، لما قدمناه من حمل المعاني المعقولة على المحسوسة، وتلك سبيلٌ مَهْيَعٌ، ويُستعمل في الإطلاق على وجهين:\rأحدهما: أن يقال: علا فلان، إذا اكتسب فضيلة.\rالثاني: أن يقال: علا إذا تنزه عن رذيلة، وظهر هذا المجاز في الاستعمال حتى غلب الحقيقة أو صار مثلها، وقد أنشد النابغة الجَعْدي بحضر النبي صلى الله عليه وسلم:\r(بلغْنا السماء مجدَنا وعلاءَنا ... وإنا لنرجو فوق ذلك مظهراً\rفقال: إلى أين يا أبا ليلى؟ قال: إلى الجنة).\rوقال المتأخرون:\rمن كان فوق محل الشمس موضعُه ... فليس يرفعُه شيءٌ ولا يَضَعُ\r"], [382, "المسألة الثانية: في سرد الأقوال في تفسير العلي\r"]], "pg": [381, 382]}, "561.132": {"x": [[382, "اختلفت عبارات الناس في تفسير العلي على أربعة أقوال:\rفقالت طائفة من المشبهة: علوه علو مكان، والمراد به كونه فوق العرش، كالملك على الفراش، مكاناً بمكان، وتمكناً بتمكن، تعالى عن ذلك.\rالثاني: قال أهل السنة: علوه علو مكانة، وهي استحقاقه لصفات الكمال، واستيجابه غاية المدح والتعظيم، من العلم الشامل، والقدرة الكاملة، والإرادة النافذة، والكلمة الصادقة، والسنّة الجارية، لا يُعجزه شيء، ولا يشبهه شيء، ولا يفوته شيء، إلى غير ذلك من الأحكام الإلهية التي هي كمال استحقاق الربوبية.\rالثالث: قالت طائفة من العلماء: قد يكون العلو القهر والغلبة، كما قال تعالى: {وَلَعَلَا بَعْضُهُمْ عَلَى بَعْضٍ} [المؤمنون: 91].\rالرابع: قالت طائفة من العلماء: هو عالٍ بمعنى: أنه منزه عن صفات الحدوث والتشبيه والتحديد.\rالمسألة الثالثة: في تحقيق هذه الأقوال\r"]], "pg": [382, 382]}, "561.133": {"x": [[382, "أما قول المشبهة إنه علو مكان، فقد ثبت فيه استحالة المكان عليه، فإنه خلق الجهة والمكان، وهو كما كان، لا يتغير شريفُ صفاته بما أوجد من مخلوقاته.\r"], [383, "وأما قول الجماعة: إن العلو في المكانة استيجابه لصفات الكمال، فما ذاك بالحقيقة والكمال إلا له.\rوأما من قال: إنه بمعنى الغلبة والقهر، فحسن في اللفظ، لكنه راجع إلى ما قبله، فإنه مَن كان أكمل صفةً وأحق بنعت الجلال كان غالباً لمن دونه قاهراً له، فكان هذا ثمرةَ ما قبله من المعنى وفائدته، لا أن يُقال فيه: إنه قول آخر غيره.\rوأما من قال: إنه علي عن صفات النقص، فحسن جداً، فإنه علي بصفات الكمال، علي بمعاني التنزيه ونفي النقص بالآفات، وكثير يرد هذا في أسماء الله الحسنى، فهو سبحانه علي بما هو عليه من صفات الكمال، متعالٍ عن صفات النقص، أعلى من غيره من الخلق، وإن كان ليس لغيره علو، فإن علو الخلق من علوه، كما أن عزتهم من عزته.\r"], [384, "وهذا التنزيه للأسماء المذكورة بما أضفناه إليها من تركيب الصفات المخصوصة لا يفطن له إلا غوَّاصٌ عن الخفايا، بصير بمعاطف الزوايا.\rالفصل الرابع: في التنزيل\r"]], "pg": [382, 384]}, "561.134": {"x": [[384, "اعلموا - أعلى الله أقداركم بالعلم - أن للباري تعالى بهذا الاسم - وهو العلي - أحكاماً يختص بها في المنزلة العليا الواجبة له، جِماعها عشَرةٌ:\rالأول: علوه عن المكان.\rالثاني: علوه عن مالك يملكه.\rالثالث: علوه عن الآمر والناهي.\rالرابع: علوه عن التحديد.\rالخامس: علوه عن الحَجْر.\rالسادس: علوه عن الحاجة.\rالسابع: علوه عن المساواة.\rالثامن: علوه عن الإدراك.\rالتاسع: أن إليه العلو والانحطاط، قال سبحانه: {يَرْفَعِ اللَّهُ الَّذِينَ آَمَنُوا مِنْكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ} [المجادلة: 11].\rالعاشر: أنه لا يُسأل عما يفعل.\r"], [385, "المنزلة السفلى للعبد\rوهي ترتبط بركنين:\rأحدهما: طلب العلو في المعرفة.\rوالثاني: العمل بالتواضع.\r"], [386, "القول في اسم الكبير\rوهو الحادي عشر من أسماء التنزيه وفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [384, 386]}, "561.135": {"x": [[386, "وقد ورد به القرآن، قال تعالى: {فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ} [غافر: 12]، وقال: {الْكَبِيرُ الْمُتَعَالِ} الرعد: 9]، وقال تعالى: {قُلْ أَيُّ شَيْءٍ أَكْبَرُ شَهَادَةً قُلِ اللَّهُ شَهِيدٌ} [الأنعام: 19]، وقال: {وَلَذِكْرُ اللَّهِ أَكْبَرُ} [العنكبوت: 45]، وورد مفسراً في حديث أبي هريرة، وأجمعت الأمة على قولهم: الله أكبر، في الأذان والصلاة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [386, 386]}, "561.136": {"x": [[386, "قال علماء اللغة: قولنا: (كبير) هو فعيل من كَبرَ، وهو يقال بكسر الباء وضمها، وهما معنيان مختلفان، فإذا كان مكسور الباء في الماضي كان بفتحها في المستقبل، ويكون عبارة عن كبرة السن، وهو التقدم في الوجود، ومنه قول الشاعر:\r"], [387, "جميلُ كبرتَ وأودى الشبابُ ... فقلتُ مجيباً لها: فاقصِري\rفمن سبق صاحبه في الوجود فهو أكبر منه، تقول العرب: فلان أكبر من فلان سناً، وفلان أسن من فلان، وقد روي في الأثر أن عثمان بن عفان سأل قباث بن أشيم أخا بني يَعْمُر بن ليث: (أنت أكبر أم رسول الله صلى الله عليه وسلم؟ فقال: رسول الله أكبر مني، وأنا أقدم منه في الميلاد).\rوإذا كان مضموم الباء في الماضي كان بضمها في المستقبل أيضاً، وهو عبارة عن معنيين:\rأحدهما: كمال الذات والصفات، وهو التقدم في المنزلة والسبق في المرتبة، تقول العرب: فلان أكبر سناً من فلان، وكلاهما هو المعنى في نسبة الكبير إلى الكبير المتعالي.\r"], [388, "الثاني: كبَر الجثة، تقول العرب للسمين الثخين الوافر الأجزاء إذا قرنته إلى ضعيف قضيف هزيل: هذا أكبر من هذا: أي أكثر أجزاءً، وهذا محال في حق الله تعالى على ما يأتي بيانه، إن شاء الله.\rالفصل الثالث: في تركيب المعنى الاعتقادي على اللغوي\r["]], "pg": [386, 388]}, "561.137": {"x": [[388, "المسألة الأولى]:\rاعلموا - أرشدكم الله - أنا إذا قلنا بقول أهل اللغة: إن الكبير هو: السابق المتقدم في الوجود بمدة محدودة، فالباري تعالى هو الكبير بالحقيقة، لأنه قد قام الدليل على أنه سابق للعالم بغير تحديد، إذ لا أول له، لأنه لو كان له أول لكان محدَثاً يفتقر إلى من يُحدثه، فثبت أنه سبق وجوده وجودَ العالم بغير تحديد.\rوإن قلنا: إن الكبير هو: المتقدم في الرتبة بجلال الذات وكمال الصفات، فالباري هو الكبير بالحقيقة في الوجهين جميعاً، فإن وجوده أسبق، وذاتَه وصفاتِه أكمل.\rوأما كبر الجثة بكثرة الأجزاء فمحال في حق الله تعالى، لأنه ليس بجسم مؤلف من مجموع جواهر وآحاد أجزاء، لاستحالة الحدوث عليه، ووجوب السبق الذي ليس له أول، واستحالة الفناء عليه.\r"], [389, "المسألة الثانية: في تنزيل الإطلاق بين الحقيقة والمجاز فيهما\r"]], "pg": [388, 389]}, "561.138": {"x": [[389, "اعلموا أن إطلاقات قولنا: (الكبير)، حيث وقعت تحتمل أن تكون حقيقة فيهما، وتحتمل أن تكون الحقيقة واحدة في بادئ الرأي، وإذا أمعنت النظر صح بعد استداده أنه حقيقة في كثرة الأجزاء، منقول إلى كبر المنزلة وعظم القدر، لما بيناه من أن كبر الأجزاء محسوس، وكبر القدر معلوم بنظر العقل، والمُشاهَد المحسوس هو الأول في العلم، والمعلوم بنظر العقل محمول عليه معلوم به كما قدمناه؛ لأن العرب لما شاهدت كبر الجثة وعبرت عنه بالكبر ثم علمت كبر المنزلة وتضاعفَها بدليل العقل حملته على الأول وعبرت به عنه.\rوهذا بناء على أن اللغة متواضَعة، فلو قلنا: إنها موضوعة بالوحي والتعليم لآدم وبنيه، ففيه نظر آخر، وطريق مغاير لهذا، ولكن مآلُه إليه، ومرجعه عليه، وذلك مبيَّن في أصول الفقه، وهذه دقيقة لا يهتدي إليها الغواصون، كما أنه لا يتفطن له إلا المتحذِّقون، وهذا وإن لم نستوفِ فيه وجوهَ التقسيم فهو بيّن عند ذوي التفهيم.\r"], [390, "المسألة الثالثة: في تعديد الأسماء المتعقلة بهذا الاسم وترتيب"]], "pg": [389, 390]}, "561.139": {"x": [[390, "ها\rاعلموا أن الكبير إذا عرفتم معناه فالأكبر أفعل منه، والمتكبر: متفعل منه، وكابِر: فاعل منه، وكُبّار وكُبار: فُعال، مخفَّف العين ومشددها منه.\rفأما المتكبر والكبير فقد سبق تأويلهما، وأما الأكبر فقد اختلف الناس فيه:\rفمنهم من قال: إنه بمعنى كبير، ومنهم من أجراه على بابه في التفضيل، واحتج بأن أفعل لا يقال إلا على مشترَكَين في شيء، ثم تظهر مَزيةٌ لأحدهما على الآخر فيه، فيخبِر بأفعل عنه، واستحالة الاشتراك بين الباري وسواه ثابتة، لأنه ليس كمثله شيء، فالتفضيل بأفعل فيه غير جائز.\rقالوا: وأفعل بمعنى فاعل وفعيل كثير في اللغة، ألم تروا إلى قول الفرزدق:\rإن الذي سمَك السماءَ بنى لها ... مجداً دعائمُه أعز وأطولُ\rفي نظائرَ لهذا من شعر ومَثل. وهذه جهالة بالتوحيد أوقعت في قلب اللغة، فإن لفظة أفعل قد وردت في حق الباري تعالى في مواضع كثيرة؛ في العلم وغيره، وقد اتفق المؤمنون على أن من تمام التوحيد أن يقول المسلم: الله ورسوله أعلم.\rونحن وإن كنا ننزه الباري تعالى من لفظ الشَّرِكة والاشتراك لما فيهما من إيهام الفساد، فنقول:\r"], [391, "إنه لا خلاف ولا شك في أنا نطلق الوجود والعلم والقدرة والكِبَر ونحو ذلك من الصفات على الباري تعالى وعلى المخلوق، ونقول: إنها في الله كاملة مقدسة، وفي العبد ناقصة، فهو في الله أجل وأكمل، وإن كانت متساوية في الإطلاق، فإنها تختلف في الجلال والكمال، والحكمة في خلقها في المخلوق الاستدلال بها على الخالق، وفي كونها ناقصةً الاستدلال بها على كما الخالق، ولا يصح مخلوق كامل بنفي الآفات واستيفاء الجلال أبداً، فقد صحت المفاضلةُ على بابها، وهو كمال التوحيد وغاية المعرفة، ولو لم يكن في هذا الكتاب إلا التوصلُ إلى هذا الأمد لكفى لكل أحد.\rوقد قال علماؤنا - رحمة الله عليهم -: إن الحكمة في جعل ذلك في الأذان والصلاة تنبيه المكلف على أن الذي دعاه إليه المؤذن من الصلاة ودخل هو فيه منها أجلُّ وأعلى من كل شيء هو فيه من أمر الدنيا، فيحضه ذلك على المبادرة إليه والإقبال عليه.\rوهذا صحيح جارٍ على أسلوب اللغة المَهْيَعِ، فكيف يصح أن يُهدم بابٌ من أبواب الأبنية بجهالة لا تصح، ويُستشهد عليه بشواهد من الشعر محتملة؟\rوالتوحيد محفوظ في كل وجه، وما قاله الفرزدق هو الحُجة، لأنه أراد: أعز وأطول من غيره من بيوت العرب أو الناس أو قبيلتهما.\r"], [392, "يزيده تأييداً ويوضحه تمهيداً: أن النبي صلى الله عليه وسلم يوم أحدٍ حين قال الكفار: اعلُ هبل، اعلُ هبل، قال في الجواب: (الله أعلى وأجل)، وقد قال النبي صلى الله عليه وسلم تسليماً لأبي ذر وقد رآه يستطيل على عبد له: (الله أقدر منك يا أبا ذر)، وهذان نصان في جري (أفعل) في إثبات الفضل لله تعالى على العبد في القدرة والجلال، ولا يبقى بعد هذا مضطرَبٌ في جواز الإطلاق، وقد صح المعنى وارتفع اللَّبس من كل وجه، والحمد لله.\rوأما: كابر وكُبار وكُبَّار، فهي أمثلة جارية في اللغة والكتاب، ولم ترد في حق الله تعالى، فما ورد في حق الله أكفى وأجلى وأدخل في الأسماء الحسنى.\r"], [393, "وأما الأكبر فهو: (أكبر) معرَّفٌ بالألف واللام، وقد روي في سنن أبي داود ورواه غيره أن النبي صلى الله عليه وسلم قال في الدعاء: (الله أكبر الأكبر)، معناه: أكبر من أن يقال فيه: أكبر، كما تقول: زيد أفضل الأفضل، المعنى: زيد أفضل الجنس الأفضل.\rالفصل الرابع: في التنزيل\r"]], "pg": [390, 393]}, "561.140": {"x": [[393, "إذا انتهى العبد إلى هذا المقام علم أن للباري تعالى في ذلك أحكاماً يختص بها خمسة:\rالأول: أنه لا يُتصور عليه المقدار.\rالثاني: أنه لا يجوز عليه التقدير.\rالثالث: أنه لا يُرد عليه شيء من التدبير.\rالرابع: أنه لا يُخالَف في الأمور.\rالخامس: أنه لا يُكبِّره تكبير المكبِّرين.\rالمنزلة الثانية للعبد\rإذا علم العبد جلال ربه، فإن قيل له: كبير، أو استحق وصف كبير فبوجهين:\r"], [394, "أحدهما: العلم بالله.\rالثاني: الطاعة له.\rوتفاوتُ الأحوال في هذه المراتب بحسب اختلاف أحوال الناس في إدراكها.\r"], [395, "القول في اسم الجليل\rوهو الثالث عشر من أسماء التنزيه، وفيه أربعة فصول\rالفصل الأول: في مورده\r"]], "pg": [393, 395]}, "561.141": {"x": [[395, "هذا اسم لم يرد في الكتاب، لكنه ورد في حديث أبي هريرة المفسَّر، وورد في القرآن ذو الجلال؛ ولا فرق في لسان العرب بين قولك: ذو الجلال وبين قولك: الجليل، كما لا فرق بين قولك: ذو العلم وبين قولك: العالم، وعجباً لما في حديث أبي هريرة، فإنه لما فسر الراوي الأحاديث جمع فيها بين الجليل وبين ذي الجلال والإكرام.\rوروي في يوم أحد أن المشركين نادوا: اعلُ هُبل، فقال النبي صلى الله عليه وسلم: (قولوا الله أعلى وأجل)، وأجمعت علماء الأمة على جواز وصفه به، لأن فعيلاً من فَعالٍ وأفعلَ جارٍ جائز.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [395, 395]}, "561.142": {"x": [[395, "اعلموا أن الجليل: فعيل من جل، ولفظ جل في اللغة له خمسة معانٍ:\rالأول: أن جل: أعطى مطلقاً، ومنه قوله: إن لي فرساً أُجِلُّها كل يوم فَرَقاً، أي أعطيها إياه عَلَفاً.\rالثاني: أن أجلَّ أعطى كثيراً، قال يعقوب: يقال: أتيته فما أجلَّني ولا أحشاني، أي: ما أعطاني كثيراً ولا قليلاً.\r"], [396, "الثالث: أن جل بمعنى: أسن، ومنه الحديث: (جاء إبليس في صورة شيخ جليل)، أي مُسن، ومنه قول كُثَيِّر:\rوَجُنَّ اللواتي قلنَ: عَزَّةُ جلَّتِ\rأي: أسنَّت.\rالرابع: جل: عظم قدره.\rالخامس: أن جل: التقط الجِلَّةَ، وهي البَعْرُ.\rويمكن كما قدمنا أن يدخل بعض هذه الأقسام على بعض، ولكن سردُها هكذا أوعبُ للمعنى وأبلغُ في الفهم.\rالفصل الثالث: في شرحه حقيقةً\r"]], "pg": [395, 396]}, "561.143": {"x": [[396, "وفيه خمس مسائل:\rالمسألة الأولى: في تفصيل الحقيقة والمجاز من هذه الإطلاقات\r"]], "pg": [396, 396]}, "561.144": {"x": [[396, "أما الأصل الذي قررناه من تركيب المعقول على المحسوس فيقتضي أن قولهم: (جل) بمعنى: أعطى، وجل بمعنى: أسن متعارضان، لا يكاد يظهر الفرق بينهما، فنقول بالظاهر: إنهما حقيقتان.\r"], [397, "وأما جل بمعنى: عظم قدره، فمحمول عليه.\rوأما جل بمعنى: التقط الجِلة - وهو البعر -، فمحمول على قولهم: جل: عظم قدره، حمل المفازة على الفوز على رسم التفاؤل.\rفتنخل من هذا أن اللفظين الأولين حقيقتان، وأن اللفظ الثاني بمعنى العِظَمِ مجازٌ محمول عليه، وأن الثالث وهو بمعنى التقط الجلة مجاز على الثالث محمول، فهو مجازُ مجازٍ، وهو من دقيق النظر معلوم، وفي حقيقة الاستنباط معدود.\rالمسألة الثانية: في تركيب المعنى الاعتقادي على اللغوي\r"]], "pg": [396, 397]}, "561.145": {"x": [[397, "اعلموا - أرشدكم الله - أنا إذا قلنا: إن جل بمعنى التقط البعر، استحال أن يُضاف ذلك إلى الله سبحانه.\rوإن قلنا: إن جل بمعنى: أعطى، فهو المعطي، ومعناه مبيَّن فيه.\rوإن قلنا: إن جل بمعنى أسنّ، أي: تطاول مداه واستمر وجوده بُرهة، فالباري تعالى مستمر الوجود إلى غير غاية، غير مسبوق وجوده في بداية،\r"], [398, "وهو معنى الأول والآخر، وسيأتي بيان ذلك.\rوإن قلنا: إن الجليل هو: العظيم المقدار الموصوف بنعوت الجلال، فهو للباري بالحقيقة، وذلك يرجع إلى استحقاق الرفعة التي لا يُساوى فيها من استغنائه عن كل غير، وقدرته على كل شيء، المحيط علمُه بكل معلوم، الذي لا شريك له ولا نظير، حسب ما تقدم، هذا معنى جلاله وكبريائه، وبمجموع هذه الأوصاف وُصف بأنه جليل كبير.\rالمسألة الثالثة: في القول في جلال الله وكبريائه وعظمته\r"]], "pg": [397, 398]}, "561.146": {"x": [[398, "اختلف علماؤنا - رحمة الله عليهم - في الجلال والعظمة هل هما وصف خاص يرجع إلى معنى زائد على الذات أم هي عبارة ترجع إلى مجموع أوصاف؟ كاختلافهم في القُدّوسية والعزة.\rوالصحيح أنها: عبارةٌ عن مجموع أوصاف، كما قدمناه، وهي: شمول العلم، وعموم القدرة والإرادة، وعدم النظير، واستحالة الآفات\r"], [399, "عليه؛ والدليل عليه أنك إذا أردت أن تحقق في ذلك معنى يغاير ما قامت عليه الأدلة من الصفة أو يزيد عليها لم تجد إلى ذلك سبيلاً، لكون ذلك مستحيلاً.\rالمسألة الرابعة: في القول في مجموع هذه الأسماء\r"]], "pg": [398, 399]}, "561.147": {"x": [[399, "وهي: العلي، والكبير، والعظيم، والجليل، هل ترجع إلى معنى واحد في الشرف والقدر، أم لها معانٍ متعددة يختص كل واحد من الأسماء بواحد من المعاني؟\rفنقول: هذا فن دقيق في الأسماء، لم يخضه بيانُ أحد من العلماء، وإن كان جرى ذلك تبعاً في حوارهم، وجاء مُدْرَجاً في ترديد اعتبارهم، وقد اختلفوا فيه على قولين:\rفمن قائل: إن هذه الأسماء ترجع إلى معنى واحد؛ هو كمال الذات والصفات.\rومنهم من فرَّق بينهما، وجعل لكل واحد معنى خاصاً فقال:\rإن العلي: هوا لذي لا رتبة فوق رتبته، وذلك بالإضافة إلى درجات الموجودات، كالعلو في الأجسام، بالإضافة إلى المراقي والدرجات.\r"], [400, "والكبير: هو الموجود الكامل الذات.\rوالجليل: هو الموجود الكامل الصفات.\rوالعظيم: هو الموجود الكامل الذات والصفات.\rودليل ذلك أنك إذا نظرت إلى الموجود الجماد وجدت له رتبة تزيد على العدم، وإذا نظرت إلى الموجود النامي وجدت له رتبة تزيد على الجماد، وإذا نظرت إلى الحي وجدت له رتبة تزيد على النامي، وإذا نظرت إلى العاقل وجدت له رتبة تزيد على الحي، فترى المراتب تتزايد بحسب صفات الموجودات.\rفإذا نظرت إلى الموجود الذي لا أول له وجدت له زيادة على الموجود الذي له أول، وإذا نظرت إليه فعلمت دوام الوجود له وجدت له زيادة في الرتبة على الفاني المنقطع الوجود، وإذا نظرت إليه فوجدته جامعاً لكل خصلة شريفة متقدساً عن كل نقيصة رأيت له رتبة على الموجود الناقص المعرَّض للآفات، وينتهي بك الترقي في درجات النظر إلى رتبة علياء عقلية لا مزيد وراءها، وهي رتبة الإلهية، فذلك المستحق لتلك الرتبة هو الله تعالى.\rفتقول حينئذ: هو العلي، لأنك وصلت إلى معرفته باعتبار درجات عقلية متفاوتة، كما وصلت إلى العلو المحسوس بالارتقاء إلى درجات حسية، فهو لأجل ذلك: العلي.\rوأما الكبير: فهو يرجع إلى موجود كامل الذات، وتفسير ذلك الكمال: أن تكون الذات غير منقطعة الوجود في الطرفين؛ حتى لا يكون لها مبدأ ولا\r"], [401, "منتهى، وأن يكون منها كل ابتداء وإليها كل انتهاء، وذلك هو الله تعالى، فهذا معنى يختص به اسم الكبير.\rوأما العظيم: فهو يرجع إلى موجود لا يحيط به نظر العقل، فإنك إذا تأملت المحسوسات وجدتها قسمين: أحدهما يحيط به البصر، والآخر يعجز عن الإحاطة به؛ كالسماء والأرض والهواء والبحر، فإذا قدَّرت موجوداً يستحيل أن تحيط به البصيرة فهو الله تعالى، وهذا معنى يختص به اسم العظيم.\rوأما الجليل: فهو عبارة عن موجود كامل الصفات، له الغنى والملك والقدوسية والعلم والقدرة، وهو الله سبحانه، فهذا معنى يختص به اسم الجليل.\rالمسألة الخامسة: في المختار\r"]], "pg": [399, 401]}, "561.148": {"x": [[401, "نقول: لا يخفى على ذي بصيرة أن هذه الأسماء على جلالها وجلال المسمى بها لا تكون مترادفة يعبَّر بها عن معنى واحد، والدليل عليه أن معانيها متغايرة، فمعنى العلي مغاير لمعنى الكبير والعظيم، فإن العرب تعبر بالعلي عن الرفيع المنزلة، وبالكبير تعبر عن المتقدم في الوجود، وتعبر بالعظيم عن الكثير الأجزاء، وقد تتداخل هذه الأسماء في بعض المعاني.\rفلما رأى بعض علمائنا تداخل هذه الأسماء في بعض وجوهها، وَذَهِلَ عن المعاني التي يختص كل واحد منها بها عن صاحبه، قال: إنها بمعنى واحد؛ ولما نظر بعضهم إلى تغاير معانيها، قال: إن معانيها متغايرة متعددة، فعيَّن\r"], [402, "لها فروقاً تُتصور ولا تُتبصر، وتتطرق وإن لم تتحقق. وإنما الصحيح في ذلك أن تتبصر معانيها المختصة، وتأخذ لكل لفظ معنى يختص به، فتُفرده بتفسيره.\rفأما التعيين المتقدم فإنه نظر متشعب غير ملتئم، فإنه قد يقول له القائل: إن ما فسرت به معنى العظيم هو معنى الكبير، وما فسرت به معنى الجليل هو معنى العلي، وقد قَلبتَ معنى كل واحد فأعطيته لصاحبه.\rولولا التطويل الممل، مع ما غلب على الخلق من الزهد في العلم والكسل، لسردتُ لكم شرح ذلك حتى تلحظوه بعين التفهيم على سبيل مستقيم.\rوالذي يتنخل من ذلك أن التغاير في معاني هذه الأسماء مقطوع به، وتعيين التغاير مظنون غير مقطوع به، اللهم إلا أن المقطوع به أن الكبير أعم متعَلقاً ومقتضىً من العظيم، وأن الجليل أعم متعلقاً من الكبير، وأن العلي أعم متعلقاً من الجليل، وذلك يتبين بنظر معانيها، واعتبار مقتضياتها التي عددناها، وهذا أمد ما علمته منتهى لأحد.\r"], [403, "الفصل الرابع: في التنزيل\r"]], "pg": [401, 403]}, "561.149": {"x": [[403, "إذا علم العبد مولاه ذا الجلال وانتهى إلى هذا المقام، تحقق أن للباري تعالى بذلك أحكاماً يختص بها:\rالأول: أنه يَجل عن أن يدرَك ما له من المقدار.\rالثاني: أنه يجل عن أن يكون عِلة للحدوث.\rالثالث: أنه يجب الانقياد له.\rالرابع: أن المقدار يقع بطاعته.\rالخامس: أنه ليس بجليل إلا من رَفَعَهُ.\rالسادس: أنه يَجل عن أن يَجري عليه ما يَدل على الحدوث.\rالمنزلة السفلى للعبد\rوذلك في ثلاثة أوجه:\rالأول: العلم بالله، والتعليم للغير.\rالثاني: التقوى في نفسه، والتقويم لغيره بالأمر بالمعروف والنهي عن المنكر.\rالثالث: التواضع لله سبحانه في العَقد والقول والعمل.\r"], [404, "القول في اسم المجيد\rوهو الاسم الرابع عشر من أسماء التنزيه، وفيه أربعة فصول.\rالفصل الأول: في مورده شريعةً\r"]], "pg": [403, 404]}, "561.150": {"x": [[404, "أما المجيد، فاسم ورد به القرآن والسنة، وأجمعت عليه الأمة، قال الله تعالى: {إِنَّهُ حَمِيدٌ مَّجِيدٌ} [هود: 73]، وقال: {ذُو الْعَرْشِ الْمَجِيدُ} [البروج: 15]، اتفق القُراء عليه برفع الدال إتباعاً لقوله: {ذُو الْعَرْشِ}، وهو الله، والماجد: فاعل منه، وقد وردا معاً في تفسير حديث أبي هريرة؛ وروى أبو إدريس الخَولاني عن أبي ذر عن النبي صلى الله عليه وسلم أنه قال: قال الله: (يا عبادي إني حرمت الظلم على نفسي ... فلا تظالموا .. ) الحديث الطويل، خرَّجه مسلم وزاد غيره فيه - وهو هنّاد -: (ذلك بأني جواد ماجد).\rالفصل الثاني: في شرحه لغة\r"]], "pg": [404, 404]}, "561.151": {"x": [[404, "اعلموا أن المجيد عند العرب هو: الواسع الكرم، الجزيل العطاء. وأصل المجد في كلامهم: الكثرة، ومنه المثل السائر: في كل\r"], [405, "شجر نار، واستمجدَ المَرْخُ والعَفار. ويقال: مَجَدَتِ الإبل تَمْجَدُ بنصب العين في المستقبل: إذا رعت في الخِصب، وأمجدها صاحبها، ويقال: أمجدتُ الدابة: إذا أكثرتَ عَلَفَهَا؛ ومجيد: فعيل منه بمعنى مفعِل، ويقال: المجد: الشرف والعظمة، ومنه يقال: مَجُدَ الرجل يمجد مجداً فهو ماجد، والمبالغة منه: مجيد، كظريف من ظَرُفَ، وكريم من كرُم، لكنه لم يرد منه ظارف ولا كارم، وورد: ماجد، والتمجيد: التعظيم.\rقال أمية بن أبي الصلت:\rمجِّدوا الله فهو للمجد أهلٌ\rوقال النابغة:\rلهم لواءٌ بكفي ماجد بطل\r"], [406, "الفصل الثالث: في شرحه عقيدة\r"]], "pg": [404, 406]}, "561.152": {"x": [[406, "فيه خمس مسائل:\rالمسألة الأولى: في تحقيق معنى المجد\r"]], "pg": [406, 406]}, "561.153": {"x": [[406, "إذا استقريتَ مورده في اللغة وجدته يرجع إلى الكثرة؛ لأن مجدَ المَرْخِ والعَفار: كثرة ناره، ومجد الإبل: سِمَنُها في المرعى، ومجد الشرف: كثرة الخصال والمناقب.\rالمسألة الثانية: في تركيب المعنى الاعتقادي على اللغوي\r"]], "pg": [406, 406]}, "561.154": {"x": [[406, "إذا ثبت أن المجد راجع إلى الكثرة، فمجد الباري تعالى هو: كثرة جلاله وشرفه وأسمائه الحسنى وصفاته العلى، كثرة تخرج عن طوق البشر في العد والإحصاء، كما قال النبي صلى الله عليه وسلم: (لا أحصي ثناءً عليك، أنت كما أثنيت على نفسك)، فلا كمال إلا وهو له، ولا نقص إلا وهو منزهٌ عنه.\rوالكمال وإن كان بطريقين:\rأحدهما: خصال شريفة.\rوالثاني: نقائص منفية.\rفالكمال الأعظم إنما هو نفي النقائص، لأن نفي النقائص يجمع ثبوت الخصال الشريفة، إذ عدمُها منقصة، وليس ثبوت الخصال الشريفة ينفي النقائص، فإنه قد يكون في الكريم خصال جليلة، وتكون فيه نقائص،\r"], [407, "فتتعارض أو تتغالب، والمجيد بالحقيقة والشريف على الإطلاق: من كمَلت خصاله وانتفت النقائص عنه، وذلك معدوم في البشر واجب للإله، فهو المجيد بالحقيقة.\rالمسألة الثالثة: في تركيب المعنى\r"]], "pg": [406, 407]}, "561.155": {"x": [[407, "اختلف علماؤنا - رحمة الله عليهم - في المجد على وجهين:\rفمنهم من قال: إنه صفة خاصة كالعلم والقدرة.\rومنهم من قال: إنما هي عبارة عن استجماع صفات التعالي فيه، واستيجابه لنفي النقائص عنه.\rوالصحيح أنه ليس بصفة خاصة، وإنما هو عبارة عن استجماع صفات التعالي؛ لما بيناه من أن المجد في لسان العرب: الكثرة والسعة، وإذا ثبتت الكثرة للباري تعالى ثبتت من غير إحصاءٍ بعدٍّ ولا تخصيص بوصف.\rتنبيه على وهم:\rوقد قال بعض الأشياخ الأجلة: إن المجيد هو: الشريف ذاته، الجميل فَعاله، الجزيل نواله، وذلك لأن شرف الذات إذا قارنه حُسن الفَعال\r"], [408, "وكثرة العطاء كان مجداً، وكأنه يجمع اسم الجليل والوهاب والكريم، وهذا بعيد من ثلاثة أوجه:\rأحدها: أنها دعوى لا تشهد لها لغة، ولا يعضدها أثر، وليس لدليل العقل فيها مدخل.\rالثاني: أن التعيين لمعاني الأسماء إما أن يكون بالنظر إلى اشتقاقها ومقتضاها في اللغة، وإما أن يكون بما يَرِدُ من تفسيرها في الآثار، وهذا التعيين الذي ذكره لا تعطيه اللغة ولا ورد به الأثر.\rالثالث: أنه يعارَض بوجوه منها - وهو أقواها - أن يقال له: بل المجيد: الشريف الذات، الكامل الصفات، الجميل الأفعال، فلم حذفت ركنَ كمال الصفات وهو أولى وأعظم من جمال الأفعال.\rالثاني: أن يقال: بل المجيد: الشريف الذات، الكامل الصفات، الغفور للخطايا الموبقات، المضاعِف للثواب والحسنات، وهذه معارضات لا جواب عنها، وتكثر أمثالها، فلا معنى لهذا التعيين بحال.\rالمسألة الرابعة: في كونه من صفات الذات أو من صفات الأفعال\r"]], "pg": [407, 408]}, "561.156": {"x": [[408, "وعلماؤنا في ذلك على طريقين:\r"], [409, "أحدهما: قال بعضهم: اتفق معظم أصحابنا على أن المجد من صفات الأفعال، إذ هو عبارة عن كثرة العطاء.\rالثاني: ما قال بعض الأشياخ: من أنه شرف الذات وكثرة النوال على ما قدمنا.\rوالصحيح أن المجد: الكثرة، كما بينا، فإذا أضيف إلى الباري تعالى اقتضى كثرة لا تخرج على طريق الإحصاء، ولا يتناولها العدد والاستقصاء، وذلك كما بيناه بكمال الصفات ونفي الآفات، فكان من أوصاف التنزيه التي لا مدخل لها في أسماء الصفات ولا في أسماء الأفعال.\rالمسألة الخامسة:\r"]], "pg": [408, 409]}, "561.157": {"x": [[409, "قد سبق أن المجيد والماجد وردا اسمين معدودين في حديث أبي هريرة المفسَّر، ولو صح تعديدهما اسمين - مع أن المجيد فعيل من فاعل - لصح تعديد العالم والعليم والعلّام ثلاثةَ أسماء، وقد ورد القرآن بجميعها، وهذا ما لا يصح في معقول، ولا يقوله أحد من أهل المعرفة بالأصول، اللهم إلا لو أراد عَادٌّ عَدَّ الأسماء كلها لصح له ذلك، إذ هي من جملة أسمائه.\r"], [410, "فأما إن أراد إحصاء التسعة والتسعين وكرر منها صيغتين في اسم ليكمل له بذلك العدد المقصود لزمه أن يكرر أبنية سائر الأسماء، وإلا كان متحكماً تحكماً محضاً لا وجه له، وهذا يدل على أن ذلك التفسير إنما هو من قول بعض الرواة الذين يلحقهم التقصير ويجوز عليهم التناقض في القول.\rالفصل الرابع: في التنزيل\r"]], "pg": [409, 410]}, "561.158": {"x": [[410, "إذا عرفتم - عرّفكم الله المشكلات - معنى المجيد: فإن له فيه تعالى المنزلة العليا التي تقتضي له بذلك اختصاصاً في الأحكام، جماعها أربعة:\rالأول: أنه لا يساوى فيما له من صفات المدح، لأنه المنفرد بالكمال.\rالثاني: أنه لا يمكن رده ولا دفعه.\rالثالث: أنه لا يوصف بقدرة على ما يوجب ذمه.\rالرابع: أنه ما لم يكن من غيره بأمره لا يحمد وصفه.\rالمنزلة الثانية للعبد\rإذا علم العبد أن مجد ربه كما سبق وضوحه - أن المجد: كثرة الخصال ونفي النقائص - فليجتهد في أن تكثر خصاله، وأن يجتنب ما نهي عنه، وحينئذ يكون ماجداً.\r"], [411, "القول في اسم الجميل\rوهو الخامس عشر من أسماء التنزيه، وفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [410, 411]}, "561.159": {"x": [[411, "هو اسم لم يرد به قرآن، ولا له في السنة أثر في الصحيح، لكن روي في حديث أبي هريرة من طريق عبد العزيز بن الحصين، وجاء في الأثر: (إن الله جميل يحب الجمال)، وورد في الصحيح: (رأيت ربي في أحسن صورة)، فدار هذا اللفظ في ألسنة العلماء، وحشوا به كتبهم وتأولوه بقلوبهم.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [411, 411]}, "561.160": {"x": [[411, "وله في اللغة ثلاثة معان:\rالأول: جمال الصورة والخِلقة، يقال: جمُل الرجل يجمُل جمالاً: إذا كان حسن الوجه.\rالثاني: جمال الأخلاق، كما يقال: خُلُقٌ جميل وخلق حسن.\rالثالث: أن يكون جميل بمعنى: مُجمِل، فعيل بمعنى مُفعِل.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [411, 411]}, "561.161": {"x": [[411, "وفيه ثلاث مسائل:\r"], [412, "المسألة الأولى: في تحقيق المعنى\r"]], "pg": [411, 412]}, "561.162": {"x": [[412, "أما جمال الصورة، فإن الله خلق في القلوب العلم بجمال الصورة وبسبيل الجمال، فترى الصورة الجميلة يميزها كل أحد ويخصها بالمعرفة من غيرها لموافقتها للقلوب لا للأبصار، من غير معرفة بوجه السبب في استحسانها، وقد يكون الجمال عاماً في جميع أجزاء الصورة، وقد يكون خاصاً في أكثرها أو في بعضها، فللشَّعر أوصاف، الأسود السبِط أحسنه، وللون أوصاف، الأبيض المشرَب أحسنه، وللعين أوصاف، الكحل أحسنه، وللأنف أوصاف، الشمم أحسنه، وللعنق أوصاف، الغيد أحسنه؛ وهكذا في جميع الأجزاء.\rفإذا كانت الصورة على وصف جمال في بعض الأعضاء، فأدركها البصر، فألقى إلى النفس ما أدرك، مالت النفس إليها بسحب ذلك المقدار، إن كثيراً فكثيراً، وإن قليلاً فقليلاً، حتى لو اتفق أن يكون كل جزء من الصورة مخصوصاً بوصف جمال، فيكون الجمال عاماً فيها، لكانت النفس متعجبة منها، مستغرقة فيها، وذلك ما لم يكن في المخلوقات، وإنما هو في الحور العين، ما خلا يوسف صلى الله عليه وسلم، فقد روي أنه أوتي شطر الحسن.\r"], [413, "واختلف العلماء في تأويله: فمنهم من قال: معنى الشطر: النصف.\rومنهم من قال: معناه أوتي الحسن كله، وأخذوه من معنى الشطر في اللغة، وهو: القصد والنحو، أي جعل حسنه على قصد واحد ونحو واحد، لم يخص به عضو دون عضو، وكأنه قد أوتي جميع وجوه الجمال في جميع الأجزاء، وهو الأصح في تأويله، فقد رأيت صوراً أوتيت أكثر وجوه الجمال.\rوأما جمال الأخلاق: فهو كونها على الصفات المحمودة، وهي معلومة.\rوأما معنى الإجمال الذي هو الإحسان فهو: الابتداء بالنعمة، والزيادة على مقدار الجزاء في العمل، وسيأتي بيانه إن شاء الله.\rالمسألة الثانية: في الاعتقاد فيه\r"]], "pg": [412, 413]}, "561.163": {"x": [[413, "أما جمال الصورة بتناسب الحُسن في الأجزاء، فمحال على الله تعالى، لأنه ليس بمركب ولا بمتجزء ولا متصوِّر.\rوأما جمال الأخلاق وهي الصفات الباطنة فهي: كونها على الصفات المحمودة من العلم والعدل والحكمة ونحوها، فإن كان الباري جميلاً بهذا المعنى فإن صفاته العلى وأسماءه الحسنى على غاية الجمال والكمال، منزهة عن النقص والاختلال، حسب ما تقدم بيانه.\rفإن قيل: فإذا أحلتم جمال الصورة في حق الباري، فما معنى قوله في الحديث: (رأيت ربي في أحسن صورة)؟ فالجواب: قد بيناه في كتاب المشكلين/ ونكتته أحد ثلاثة معاني:\r"], [414, "إما أن يكون مناماً، وإما أن يكون في أحسن صفة أي: راضياً، وإما أن يكون عائداً على الرائي.\rالمسألة الثالثة: في الفرق بين الجليل والجميل\r"]], "pg": [413, 414]}, "561.164": {"x": [[414, "اختلف علماؤنا - رحمة الله عليهم - في ذلك:\rفمنهم من قال: إن صفات الجلال إذا نُسبت إلى البصيرة المدركة لها سميت جمالاً، ومعناه: أن الجمال حال تعود إلى صفات الكمال عند تعلق العلم بها، فهي جميلة بالإضافة إلى البصيرة، وملائمة لها ملاءمة يدرك صاحبها منها أكثر مما يدركه الناظر بالبصر إلى الصورة الجميلة.\rومنهم من غاير بينهما فقال: (إن الله إذا كاشف القلوب بنعت جماله عطشتْ، وإذا كاشفها بوصف جلاله دهشتْ).\rفأما قول الأول فضعيف، فإن جمال الله وجلاله لم يزل ولا يزال، تعلقت به بصيرة أو لم تتعلق، وجد عالم بذلك أو لم يوجد، بل إن العالم بجلاله يحدث له جمال لم يكن قبل، ولا نقول ملاءمة، فإنها أخت المناسبة التي يأتي بيان فسادها إن شاء الله.\r"], [415, "وأما قول الثاني، فهي عبارة صوفية مشكلة إلا على المتمرن بأغراضهم، ومعناه: أن الجمال لله هو كمال الصفات، فإذا نظر العبد إلى الباري وصفاته العلى، وما هو عليه من التقدس، ومباينتهما لوصف المخلوقين دَهِشَ في أول الأمر، حتى إذا أمعن في النظر وتحقق جمال الله، وهو كونه على ما هو عليه من تحقيق صفات الكمال، ومباينته للمخلوقين طلب الإكثارَ من ذلك، وقال: {وَقُل رَّبِّ زِدْنِي عِلْمًا}، فسمى ذلك عطشاً.\rالفصل الرابع: في التنزيل\r"]], "pg": [414, 415]}, "561.165": {"x": [[415, "إذا انتهى العبد إلى هذا المقام علم أن الباري تعالى مباين للمخلوقين بثلاثة أحكام: كمال الذات، وكمال الصفات، وكمال الأفعال.\rوعلم أن على العبد اكتساب جمالين:\rأحدهما: جمال الأخلاق برياضة النفس.\rوالثاني: جمال الأفعال بالعدل.\r"], [416, "القول في اسم الحسيب\rوهو السادس عشر من أسماء التنزيه، وفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [415, 416]}, "561.166": {"x": [[416, "ورد به القرآن، قال تعالى: {وَكَفَى بِاللَّهِ حَسِيبًا} [النساء: 6]، ووردت به السنة في حديث أبي هريرة المفسر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [416, 416]}, "561.167": {"x": [[416, "له في اللغة ستة معان:\rالأول: حسيب بمعنى: مُحسِب، فعيل بمعنى مفعل، كقولهم: أليم، بمعنى مؤلم، تقول العرب: نزلتُ بفلان فأكرمني وأحسبني، أي: أعطاني حتى قلت: حسبي، معناه: يكفيني؛ وقد قال ابن عباس في قوله: {يَا أَيُّهَا النَّبِيُّ حَسْبُكَ} [الأنفال: 64]، معناه: كافيك الله، ومنه قوله: {عَطَاءً حِسَابًا} [النبأ: 36].\rومنه قول الشاعر:\r"], [417, "ونقفي وليدَ الحي إن كان جائعاً ... ونُحسبه إن كان ليس بجائعِ\rالثاني: الحسب: الكرم، قال سماك بن حرب في كلام له: ما حسَّبوا ضيفَهم أي: ما أكرموه.\rالثالث: المحاسب: فعيل بمعنى مفاعل، كالجليس والأكيل والشريب، ومنه قوله: {كَفَى بِنَفْسِكَ الْيَوْمَ عَلَيْكَ حَسِيبًا} [الإسراء: 14].\rالرابع: الحسيب: الشريف، وهو الذي يعد مآثر كثيرة ومناقب عديدة.\rالخامس: الحسيب: فعيل من حاسِب، إذا عد، كما قال تعالى: {الشَّمْسُ وَالْقَمَرُ بِحُسْبَانٍ} [الرحمن: 5].\rالسادس: الحسيب: فعيل من حَسِبَ، وهو الذي يحسب الشيء، أي: يظنه من غير تحقيق.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [416, 417]}, "561.168": {"x": [[417, "وفيه ثلاث مسائل:\rالمسألة الأولى: في تحقيق القول فيه\r"]], "pg": [417, 417]}, "561.169": {"x": [[417, "اعلموا - وفقكم الله - أن (ح س ب) يتصرف في لسان العرب على الستة الأوجه المتقدمة، إلا أن قولنا: حسيب، لا يكون من بناء الثاني، فإن\r"], [418, "ذلك بناء مضاعف ولا يتأتى منه فعيل، وما عداه صحيح المعنى جاري التصريف.\rالمسألة الثانية: في تحقيق العقيدة فيه\r"]], "pg": [417, 418]}, "561.170": {"x": [[418, "سائر المعاني ترجع إلى أربعة معان:\rأحدها: الشرف.\rوالثاني: العدد.\rوالثالث: الكفاية.\rوالرابع: الظن.\rومن الناس من يرد الأول وهو الشرف، إلى الثاني؛ وهو العدد، والصحيح خروجه عنه.\rالمسألة الثالثة:\r"]], "pg": [418, 418]}, "561.171": {"x": [[418, "نقول: هذه المعاني كلها جائزة في حق الباري تعالى مع اختلافها، فإذا ركبتها وجدتها صحيحة، إلا الحسيب بمعنى الظان فإنه محال في حقه.\rفإما كونه حسيباً من الشرف والجلال فذلك له حقيقة، وهو المعنى الأول فيه، فإن جلال الله لا يُحصى، وثناؤه لا يستقصى، كما قال صلى الله عليه وسلم:\r"], [419, "(أنت كما أثنيت على نفسك)، وعلى هذا يكون من صفات التنزيه، فإن من ثنائه نفي النقائص.\rوأما كونه حسيباً من الكفاية، فهو الكافي لا كافي سواه.\rوأما الحسيب بمعنى: المحاسِب، فهو الباري تعالى في الدنيا والآخرة، قال تعالى: {إِنَّمَا نَعُدُّ لَهُمْ عَدًّا} [مريم: 84]، وقال تعالى: {وَكَفَى بِنَا حَاسِبِينَ} [الأنبياء: 47]، وقال: {وَاللَّهُ سَرِيعُ الْحِسَابِ} [البقرة: 202]، وقال: {وَهُوَ أَسْرَعُ الْحَاسِبِينَ} [الأنعام: 62]، وقد حققنا في كتب الأصول حسابه للخلق وبينا كيفيته، ويشترك فيه مع المُحصي، ويكون على هذين المعنيين من صفات الأفعال.\rالفصل الرابع: في التنزيل المنزلة العليا للرب\r"]], "pg": [418, 419]}, "561.172": {"x": [[419, "هذا الاسم يختص بثلاثة أحكام:\rالأول: أنه المستحق للحمد على الانفراد.\rالثاني: أنه الكافي وحده؛ وإن تصوَّر من الخلق كَافٍ، فالكفاية له لأنه سبحانه هو المسخِّر له الميسر له.\rالثالث: أنه المحاسب على الصغير والكبير {لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً إِلَّا أَحْصَاهَا} [الكهف: 49]، فيغفر لمن يشاء ويعذب من يشاء.\r"], [420, "المنزلة الثانية للعبد\rفي ثلاثة أحكام:\rالأول: أن يعلم أنه عاجز عن الثناء على ربه.\rالثاني: أنه إن علم أنه لا كافي له سواه لم يطلب حاجة من غيره.\rالثالث: أن يحاسِب نفسَه قبل أن يحاسَب.\r"], [421, "القول في اسم الصمد\rوهو الاسم السابع عشر من أسماء التنزيه، وفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [419, 421]}, "561.173": {"x": [[421, "قد ورد به القرآن، قال تعالى: {قُلْ هُوَ اللَّهُ أَحَدٌ. اللَّهُ الصَّمَدُ} [الإخلاص: 1 - 2]، وقال النبي صلى الله عليه وسلم في حديث أبي هريرة: (لله تسعة وتسعون اسماً)، وذكر في التفسير الصمد، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [421, 421]}, "561.174": {"x": [[421, "اختلفت عبارات العلماء في تفسيره على عشرة أقوال:\rالأول: الصمد: السيد.\rالثاني: الذي يُصمَد إليه في الحوائج، أي: يُقصد في الأمور.\rالثالث: الصمد الذي قد انتهى سؤدَدُه، قال الشاعر:\rألا بكر الناعي بخيرَي بني أسدْ ... بعمرو بن مسعود وبالسيد الصمدْ\r"], [422, "الرابع: الصمد: الدائم.\rالخامس: الصمد: الصُّلب من الأماكن، قال أبو النجم:\rيغادر الصمد كظهر الأجدلِ\rالسادس: أن الصِّماد: عِفاص القارورة، فعلى هذا يكون الصمد: الذي يمنع الكوائن من الفساد والاختلال.\rالسابع: الصمد: الباقي بعد فناء الخلق، قاله ابن مسعود.\rالثامن: الذي لا جوف له، قاله ابن عباس.\rالتاسع: الذي فسره بقوله: {لَمْ يَلِدْ وَلَمْ يُولَدْ. وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ} [الإخلاص: 3 - 4].\r"], [423, "العاشر: الصمد: المصمَت؛ الذي هو شيء واحد، لقرب صمد من صمت، فإن الصمد: القصد، ويقال: بِتُّ على صُمات ذلك: أي على قصده، ولأن الدال والتاء حرفا بدل ينوب كل واحد منهما عن صاحبه.\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [421, 423]}, "561.175": {"x": [[423, "وفيه ثلاث مسائل:\rالمسألة الأولى: في بيان مآخذ هذه الأقوال\r"]], "pg": [423, 423]}, "561.176": {"x": [[423, "قد سبق بيان ما حضرَنا في تفسير هذا الاسم من أقوال العلماء، وهي على ثلاثة أقسام:\rمنها: قسم يعضده الاشتقاق، كقولنا فيه: إنه الذي يُصمَد إليه في الحوائج.\rومنها: ما يعضده الاستشهاد، كقوله: إن الصمد الصلب من الأماكن.\rومنها القسم الثالث: وهو ما يعضده النقل، كقول ابن عباس وابن مسعود، وهما هما علماً وشرفاً.\rولكل واحد وجه ومتعلق، وسنتتبعه بالبحث والتنقير حتى يَخلُص الحق من بين النظير والنظير.\r"], [424, "المسألة الثانية: في تركيب المعنى الاعتقادي على اللغوي\r"]], "pg": [423, 424]}, "561.177": {"x": [[424, "اعلموا - وفقكم الله - أنا إذا قلنا: إن الصمد هو: السيد، أو: الذي انتهى سؤدده، فسيأتي ذلك في تفسيره في موضعه، وهو اسم السيد.\rوإن قلنا: إنه الذي يصمد إليه في الحوائج، فلا يصمد بالحقيقة إلا لمن الأمور إليه، وقبضه الكل بيديه، له يتملق الخلق ويتضرعون، وإليه يلجأ المضطرون.\rوإن قلنا: إن الصمد: الدائم والباقي، فليس الدوام والبقاء بالحقيقة إلا لله وحده، لأنه لا يدركه فناء، ولا لوجوده انقضاء.\rوإن قلنا إن الصمد الصلب من الأماكن الذي لا تؤثر فيه المناسم والحوافر، فالباري تعالى هو الذي لا يتصور فيه توهم، فكيف أن يتعلق به تأثر.\rوإن قلنا: إن الصمد: هو الذي يمنع الشيء من الفساد فلا حافظ للمخلوقات من الاختلال إلا هو تعالى، فتأمل السماوات هل ترى فيها تفاوتاً أو فطوراً أو كسفاً أو تهويراً، {إِنَّ اللَّهَ يُمْسِكُ السَّمَاوَاتِ وَالْأَرْضَ أَن تَزُولَا} [فاطر: 41].\r"], [425, "وإن قلنا: إن الصمد: هو الذي لا جوف له، فإن الله خلق الخلق قسمين: فمنهم المصمت كالجماد، ومنهم المجوف كالجن والإنس والبهائم، ولذلك يروى أن إبليس طاف بآدم حين خلق طيناً، فلما صكه وطن داخله، قال: هذا خلق خلقاً لا يتماسك.\rفالمصمت كالجماد يستغني عن الغذاء، والمجوف يحتاج إلى الغذاء بحكم العادة لا بمقتضى الجبلة والخلقة، وإلا فمن الجائز أن يبقى المجوف دون غذاء كالجماد، ومن الجائز افتقار الجامد إلى الغذاء كالمجوف، والتجويف من أوصاف التركيب ومن نعوت الحاجة إلى الغير.\rفالباري الذي ليس بمؤلف ولا مركب ولا يوصف بالافتقار إلى الخلق أولى بأن يكون صمداً، وقد كان من أصنام الكفرة مصمَت، وكان منها مجوف، فليس المدح في نفي صورة التجويف، لأن المشاركة في ذلك موجودة في ذي التركيب والتأليف، ولا يكون المدح إلا بصفة الاختصاص التي لا توجد المشاركة فيها ولا تتصور، وإنما وقع المدح بكناية التجويف، وهو عدم الحاجة إلى الغذاء، كما قال تعالى: {وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ} [الأنعام: 14].\r"], [426, "وإن قلنا: إنه: الذي {لَمْ يَلِدْ وَلَمْ يُولَدْ. وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ} [الإخلاص: 3 - 4]، فهذه الخصال الجليلة والصفات الكريمة تحتمل أن تكون تفسيراً، وتحتمل أن تكون فائدة مجردة، والصحيح أنها فائدة مجردة لأنه ظاهرها، فمن ادعى أنها تفسير فذلك تفسير لا برهان عليه.\rوإن قلنا: إن الصمد هو: المصمَت الذي هو شيء واحد، فالذي هو شيء واحد بالحقيقة هو الله سبحانه، وما عداه أشياء لا شيء، أو شيء يجوز أن يكون مع غيره مؤلَّفاً أشياءَ.\rالمسألة الثالثة: في المختار\r"]], "pg": [424, 426]}, "561.178": {"x": [[426, "قد قدمنا لكم أقوال العلماء بنصها، وركَّبنا عليها نعوتَ الباري باحتمالها، وبينا في المسألة الأولى أن الأقوال كلها دائرة بين الثلاثة الأقسام السابق بيانُها، وأصح هذه الأقوال في النظر وأقواها عند تعارض الخواطر والفكر، ثلاثة أقوال:\rالأول: أنه السيد، وهو من أوصاف التنزيه، وسيأتي بيانه إن شاء الله.\rالثاني: أنه الشيء الواحد الذي ليس بمؤلف من أشياء مختلفة.\rالثالث: أنه الذي يصمَد إليه في الحوائج، وهذا هو الباري بالحقيقة، فإنه السيد الأعظم، وهو الذي ليس بمؤلف من أشياء مختلفة ولا من أشياء متماثلة، وهو الذي يصمد إليه بالحقيقة.\r"], [427, "وما روي عن ابن عباس قريب مما نقل عن أهل اللغة، وما روي عن ابن مسعود مما لا أعلم وجهه، ولو صح نقل معنى هذين الاسمين من هذين الخبرين لكان ذلك أقوى حجة وأوضح محجة، ولكنهما جاءا من طريق ضعيفة.\rفإذا كان الصمد: السيد أو، الشيء الواحد، فهو في لسان العرب اسم، كقولنا: جمَل وبطَل.\rوإن قلنا: إنه: الذي يصمد إليه في الحوائج، فيكون حينئذ صفة في حكم اللسان العربي، ويكون وزنه فَعَلاً مفتوح الفاء والعين، من مصدر وزنه فعلاً مفتوح الفاء وساكن العين، فيكون بناؤه بناء العبارة عن المفعول؛ كالخبَط من الخبْط، ويكون حينئذ من باب اسم المعبود والمستعان على ما يأتي بيانه، ويكون أيضاً من صفات الأفعال، فإن القصد إليه من عباده كان بعد خلقهم، وقد كان صمداً قبل خلقهم بمعنى، ويكون بعد خلقهم صمداً بمعنى، حتى تكمل له الصمدية بجميع المعاني.\rالفصل الرابع في التنزيل\r"]], "pg": [426, 427]}, "561.179": {"x": [[427, "المنزلة العليا لله\rفي هذا الاسم تقتضي له أحكاماً ثلاثة:\rالأول: أنه لا يجري في الوهم.\rالثاني: أن الكون منه.\r"], [428, "الثالث: أنه يُقصد في الطلب.\rالمنزلة السفلى للعبد\rوهي لا تكون إلا بمعنى واحد، وهو أن يقصد في مطالب الدنيا بهداية الخلق، وفي مطالب الآخرة بالعلم، وللعباد في ذلك تفاوت في المراتب؛ أعلاها مرتبة: النبوة، وتليها مرتبة ورثتهم؛ وهم العلماء، ثم الذين يلونهم، هكذا إلى آخر المرتبة.\r"], [429, "القول في اسم الغني\rوهو الاسم الثامن عشر من أسماء التنزيه، وفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [427, 429]}, "561.180": {"x": [[429, "وقد ورد به القرآن والسنة، قال الله تعالى: {هُوَ الْغَنِيُّ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ} [يونس: 68]، وورد في تفسير حديث أبي هريرة اسم الغني، وأجمعت الأمة عليه.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [429, 429]}, "561.181": {"x": [[429, "اعلموا - أغناكم الله بالعلم - أن قولنا: غني، فعيل من غني يغنى غنى فهو غني: إذا كان له مال أو أقام بمكان، وكلاهما يرجع إلى معنى واحد وهو: الاكتفاء بالشيء عن غيره، والاجتزاء به عن سواه.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [429, 429]}, "561.182": {"x": [[429, "وفيه مسألتان:\rالمسألة الأولى: [في تركيب المعنى اللغوي على الاعتقادي]\r"]], "pg": [429, 429]}, "561.183": {"x": [[429, "إذا علمتم معناه لغةً، فإنه تعالى غني بالوجهين جميعاً على التمام والكمال، وأشرف الوجوه والأحوال.\r"], [430, "فإذا كان الغني من كان له عرض من الدنيا محدود فالغني الذي له ما في السماوات وما في الأرض أولى باسم الغني وأحق به، بل هو الغني عن السماوات والأرضين وعن جميع المخلوقات، فإنه لم يخلقها عن حاجة عرضت له، ولا ليسد مفاقر نزلت به، وإنما خلقها بحكمة.\rوإن كان من دام بمكان مدة من الزمان يسمى غنياً، فالدائم الذي لم يزل ولا يزال موجوداً ولا يتطرق إليه فناء أولى أن يكون غنياً، فهو دائم الوجود، غني عن الأمكنة والمخلوقات، فهو الغني حقاً.\rالمسألة الثانية: [في وجه كون الغني صفة تنزيه]\r"]], "pg": [429, 430]}, "561.184": {"x": [[430, "إذا فهمتم حقيقة الغني ومعنى تسميته تعالى به، فقد تحققتم أنها صفة تنزيه، لأن ذلك راجع إلى الغنى عن الخلق أو إلى الدوام، وكلاهما صفة نفي للآفات، لا إثبات شيء من الصفات.\rفإن قيل: فهل يكون غنياً من الغناء وهي الكفاية بالشيء؟\r"], [431, "فالجواب: أنا نقول:\rأما ذلك فتصريف فعله: أغنى يُغني غَناءً فهو مغنٍ، فيكون هذا مفعلاً، وذلك فعيل من فاعل وهو غان، فبان أن تصريفهما مختلف ومعناهما متغاير، فلا يصح أن يكون معناهما واحداً، والباري تعالى له الغنى والغناء، كما قال: {إِن يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِن فَضْلِهِ} [النور: 32]، و {يُغْنِ اللَّهُ كُلًّا مِّن سَعَتِهِ} [النساء: 130]، لكن لم يأت فيه اسم المغني، وجاء فيه اسم الغني، فوقفنا في المورد كما ورد، وطردنا المعنى كيفما اطرد.\rالفصل الرابع: في التنزيل\r"]], "pg": [430, 431]}, "561.185": {"x": [[431, "إذا علمتم معنى الغني، فللباري تعالى في ذلك المنزلة العليا التي توجب له أحكاماً خمسة:\rالأول: أنه لا يوصف بالحاجة.\rالثاني: أنه لا تتعلق به قدرة.\rالثالث: أنه لا يفتقر إلى دعامة ولا علاقة.\rالرابع: أنك لا تتوهم حدوث شيء إلا وهو منه، من غير توقيف على حدوث حكم.\rالخامس: أن حدوث الحوادث لا يؤثر فيه.\r"], [432, "المنزلة السفلى للعبد\rتكون على ثلاث:\r[الأول]: أن يستغني بالله عن كل أحد.\rالثاني: أن يستغني بكتاب الله عن كل فائدة، كما قال صلى الله عليه وسلم: (ليس منا من لم يتغن بالقرآن)، في أحد القولين.\rالثالث: أن يقصر أمله وبصره عن مطامح الأطماع والمناظر، ويقتصر بما حصل عليه من قوت وملبس وإن قل، كما قال النبي صلى الله عليه وسلم: (ليس الغنى عن كثرة العرض، ولكن الغنى غنى النفس).\r"], [433, "القول في اسم رفيع الدرجات\rوهو الاسم التاسع عشر من أسماء التنزيه، وفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [431, 433]}, "561.186": {"x": [[433, "وهو اسم ورد به القرآن، قال تعالى: {رَفِيعُ الدَّرَجَاتِ ذُو الْعَرْشِ} [غافر: 15]، ولم يرد في السنة، لكن أجمعت عليه الأمة لكونه منصوصاً في كتاب الله المجتمع عليه صحة ونقلاً.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [433, 433]}, "561.187": {"x": [[433, "اعلموا - وفقكم الله - أن في هذا الاسم كلمتين:\rإحداهما: قولنا: رفيع؛ والأخرى: قولنا: الدرجات.\rفأما رفيع، فهو فعيل من الرفعة، وهي عبارة عن: كل مكان كان في جهة فوق، وضد الرفعة الخفض، وهذه هي حقيقة، وقد تستعمل في نقل الحديث ورفع المكانة مجازاً فيهما.\rوقد جاء اللفظ المذكور في المكان علواً، وفي المكانة عزاً، وهو فعيل من رافع، كقولنا: عليم من عالم، وقد يحتمل أن يكون فعيلاً بمعنى مفعول، كما نقول في أبنية كثيرة تأتي في أسماء الله، إن شاء الله.\r"], [434, "وأما الدرجات فهي عبارة عن: مكان فوق مكان، هذا أصله، ويستعمل مجازاً في موضع بين يدي موضع، ومكان أمام مكان، كما قال ذو البجادين يخاطب ناقة النبي صلى الله عليه وسلم:\rتعرضي مدارجاً وسومي ... تعرض الجوزاء للنجومِ\rهذا أبو القاسم فاستقيمي\rويقال: رجع على أدراجه، أي: طريقه الذي جاء عليها. وفي خطبة الحَجاج: (ليس هذا بعشك فادرُجي)، أي: تنقلي عنه، يُضرب مثلاً للمطمئن في غير وكنه.\rوكذلك أيضاً يستعمل لفظ الدرجات مجازاً في المكانات والمنازل العلية المعنوية، كما قال تعالى: {يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا مِنكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ} [المجادلة: 11]، وكما قال تعالى: {هُمْ دَرَجَاتٌ عِندَ اللَّهِ} [آل عمران: 163]، أي: طبقات في أحد القولين في الآيتين.\rالفصل الثالث: في شرحه عقيدة وحقيقة\r"]], "pg": [433, 434]}, "561.188": {"x": [[434, "وفيه ست مسائل:\r"], [435, "المسألة الأولى: في سرد أقوال العلماء\r"]], "pg": [434, 435]}, "561.189": {"x": [[435, "قد نقل عن العلماء - رحمة الله عليهم - في ذلك سبعة أقوال:\rالأول: معناه: رفيع السماوات.\rالثاني: رفيع المنازل في المثوبات.\rالثالث: رفيع درجات أنبيائه.\rالرابع: رفيع درجات أوليائه.\rالخامس: رفيع الصفات.\rالسادس: الكبرياء والعظمة.\rالسابع: أنه فوق السماوات.\rالمسألة الثانية: في تحقيق هذه المقالات\r"]], "pg": [435, 435]}, "561.190": {"x": [[435, "هذه الألفاظ السبعة المنقولة على ألسنة العلماء في تفسير هذه الآية ترجع إلى ثلاثة معانٍ:\rالأول: رفعة الصفات.\rالثاني: رفعة السماوات.\rالثالث: رفعة المنازل في المثوبات.\rفإن قولهم: رفيع درجات أنبيائه وأوليائه، يرجع إلى رفعة المنازل في المثوبات.\r"], [436, "وأما قولهم: إنها الكبرياء والعظمة، فيرجع إلى قولهم: رفعة الصفات، وكذلك قولهم: إنه فوق السماوات؛ يرجع إلى رفعة الصفات، على ما يأتي بيان ذلك وتحقيقه إن شاء الله.\rالمسألة الثالثة: في بيان حقائق هذه الأقوال وتركيبها على العق"]], "pg": [435, 436]}, "561.191": {"x": [[436, "ائد\rأما رفعة السماوات فمشاهَد ومعلوم، فإن السماء الدنيا من العلو بحيث لا تنال بالبصر في أحد القولين، أو بحيث لا يُشاهَد أعلى منها في المحسوسات المرئيات، وكذلك ما وراءها من السماوات، فإن بين كل سماء وسماء مسيرة خمسمائة عام كما روي عن الصادق المصدوق صلى الله عليه وسلم، وسيأتي تحقيق ذلك في قولنا في اسمه بذي المعارج.\rوأما رفعة المنازل في المثوبات فهي درجات الجنة، وتتفاوت بحسب تفاوت المراتب والأعمال للأنبياء والأولياء والعلماء والمؤمنين، كما قال تعالى: {هُمْ دَرَجَاتٌ عِندَ اللَّهِ} [آل عمران: 163]، وقال: {يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا مِنكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ} [المجادلة: 11] في أحد القولين، وقال صلى الله عليه وسلم: (إن أهل الجنة ليتراءون كما تتراءون الكوكب الدري الغابر في أفق السماء، وإن أبا بكر وعمر منهم وأنعما)، وروي أنه يقال لقارئ القرآن: (اقرأ وارقَ ورتل\r"], [437, "كما كنت ترتل في الدنيا، فلك بكل آية درجة، ويكون منزله عند آخر أية يتلوها).\rوأما رفعة الصفات، فبما لها من كمال الذوات، وكثرة المتعلقات والتنزه عن الآفات.\rبيانه:\rأن علم الله مثلاً كامل في نفسه، فإنه واجب الوجود من غير تعلم يكشف جميع المعلومات، ويحيط بمكنون الخفيات.\rوأما كثرة المتعلقات فإنه لا معلوم معدوم أو موجود إلا وعلم الله به محيط إلى غير غاية، ودون نهاية.\rوأما التنزيه عن الآفات فلا يقال: إنه حصل بتعلم، ولا يتطرق إليه سهو ولا ذهول، ولا يدركه فناء ولا زوال، وكذلك الترتيب في جميع الأحكام لجميع الصفات، فهذه رفعة صفاته.\r"], [438, "المسألة الرابعة: في معنى قولهم: إنه فوق السماوات\r"]], "pg": [436, 438]}, "561.192": {"x": [[438, "اعلموا أن هذا لفظ تكلمنا عليه في كتاب المشكلين، وبينا أنه ليس معناه فوقية المكان، وأن المراد به فوقية المكانة والمنزلة، ومعناه: أن السماوات محدودة، والله تعالى فوق ذلك فإنه غير محدود، والسماوات مؤلَّفة، والله فوق ذلك لأنه غير مؤلَّف، والسماوات في جهة، والله تعالى فوق ذلك، فإنه في غير جهة، والسماوات يقابل بعضها بعضاً، والله تعالى فوق ذلك، فإنه لا يقابِل ولا يقابَل، وهكذا، في كل صفة مخلوقة قدرناها في السماوات فالله منزه عنها، فيرجع ذلك إلى رفعة الصفات.\rالمسألة الخامسة: في المختار\r"]], "pg": [438, 438]}, "561.193": {"x": [[438, "الذي يقوى في النظر أن رفعة الدرجات وإن كان يحتمل ما تقدم، فالأقوى فيه أن المراد به رفعة الصفات لوجهين:\rأحدهما: أنه الأول، فإن رفعة الدرجات إنما كانت عن رفعة الصفات.\rالثاني: أنه الأولى، فإن رفعة الصفات أشرف أسبق في الجلال والعظمة، ويعضُد ذلك قوله في آخر الآية: {يُلْقِي الرُّوحَ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ} [غافر: 15] فبيَّن أن شرف صفاته وعظيم جلاله\r"], [439, "يلقي الشريف النفيس من أمره على من يشاء من عباده. وفي الروح أربعة أقوال:\rالأول: الوحي.\rالثاني: النبوة.\rالثالث: القرآن.\rالرابع: الرحمة.\rوكلها ترجع إلى شرف الصفات وكمالها.\rالمسألة السادسة:\r"]], "pg": [438, 439]}, "561.194": {"x": [[439, "في قول بعض العلماء: (إنه تعالى يوصف بأنه علي، ولا يوصف بأنه رفيع)، واحتج على ذلك بأن قال: (إن العلي كلمة تُنقل من علو المكان إلى علو الشأن، والرفيع لا يستعمل إلا في ارتفاع المكان).\rوهذا فاسد من وجهين:\rأحدهما: أنها دعوى، بل الرفيع يُستعمل في علو المكان والمكانة كما بيناه، وقد قال النبي صلى الله عليه وسلم مخبراً عن الله تعالى: (بيده القسط، يخفض ويرفع)، وقد جاء ذلك كثيراً في أشعار العرب وأمثالها.\r"], [440, "الثاني: أنه بعد ذلك بسطرين قال في تفسير قوله رفيع الدرجات: (رفيع الصفات)، وهو عبارة عن ارتفاع الشأن، فكيف ينفي في سطر ما يثبته بعده في سطرين؟\rوإنما الصحيح أن يقال: إن قولنا: (علي)، وقولنا: (رفيع)، كلمتان يشترك فيهما عند الإطلاق الخالق والمخلوق، فورد إطلاقها على الخالق مختلفاً فاتبعنا المورد، فجاء قوله: (علي) مطلقاً غير مضاف، وجاء قوله: (رفيع) مضافاً إلى الدرجات، فأطلقنا من الأسماء ما أطلق، وقيدنا ما قيد، فإنه تعالى أعلم بوجه الحسن فيهما، والأمر المحيط بوجه تصرفهما ومعانيهما.\rالفصل الرابع: في التنزيل\r"]], "pg": [439, 440]}, "561.195": {"x": [[440, "إذا علمتم أنه رفيع الدرجات فللباري تعالى في ذلك أحكام تختص به ثلاثة:\rالأول: أنه لا يُساوى في المرتبة.\rالثاني: أنه لا يُحط عن منزلة.\rالثالث: أنه لا يُؤتي المراتبَ سواه.\r"], [441, "المنزلة السفلى للعبد\rوهي لزوم الإيمان والعلم اللذين بهما ترفع الدرجات، حسب ما أخبر به من ذلك في كتابه.\r"], [442, "القول في اسم ذي الطَّوْلِ\rوهو الاسم الموفي عشرين من أسماء التنزيه، وفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [440, 442]}, "561.196": {"x": [[442, "ورد به القرآن، قال تعالى: {شَدِيدِ الْعِقَابِ ذِي الطَّوْلِ} [غافر: 3]، وورد في حديث أبي هريرة مفسَّراً من طريق عبد العزيز بن الحصين، وأجمعت عليه الأمة لصحة مورده وتحقيق أصله.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [442, 442]}, "561.197": {"x": [[442, "أما الطاء والواو واللام فإنها تتصرف في اللغة على أربعة معانٍ:\rالأول: الغِنَى.\rالثاني: القدرة.\rالثالث: الطول: الفضل.\rالرابع: الإشراف على الشيء، وفي الحديث: (تطاول عليهم الرب بفضله)، أي أشرف.\r"], [443, "الفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [442, 443]}, "561.198": {"x": [[443, "وفيه ثلاث مسائل:\rالمسألة الأولى: في سرد أقوال العلماء\r"]], "pg": [443, 443]}, "561.199": {"x": [[443, "وفيه سبعة أقوال:\rالأول: الطول: النعمة، قاله ابن عباس.\rالثاني: أن الطول: القدرة، قاله ابن زيد.\rالثالث: أن الطول: الغنى، قاله مجاهد.\rالرابع: أنه المن، قاله عكرمة.\rالخامس: الخير.\rالسادس: التفضل.\rالسابع: أن الطول: مأخوذ من الطُّول، كأنه طال بأنعامه، وطالت مدة إنعامه.\r"], [444, "المسألة الثانية: في الاعتقاد فيه\r"]], "pg": [443, 444]}, "561.200": {"x": [[444, "هذه الأقوال كلها صحيحة في حق الله تعالى، لأن هذه الأوصاف كلها صحيحة فيه، واجبة له، فالباري تعالى هو المنعم القادر الغني المنان المؤتي كل خير، المتفضل بكل نعمة، الذي طال إنعامه على الخلق، ودام دوام الحق.\rالمسألة الثالثة: في المختار\r"]], "pg": [444, 444]}, "561.201": {"x": [[444, "قد فهمتم معنى الطول في أقوال أهل اللغة وأقوال العلماء، والتحقيق فيه عندي: أن الطول هو: الفضل، أي الزيادة، إليه يرجع كل معنى تقدم تفسيره ومنه يخرج، وللباري تعالى على الخلق الزيادة في كل وصف ووجه يُقدَّر، وله الكمال ولهم النقص.\rالفصل الرابع: في التنزيل\r"]], "pg": [444, 444]}, "561.202": {"x": [[444, "إذا فهمتم معنى الطول، فلله تعالى الطول بكل وجه وعلى كل أحد، ومن الحق على العبد أن يكون له طول بما أذن له فيه الرب تعالى، وذلك بالعلم والعمل والعطاء، ويتضاءل فيما عدا ذلك ويتصاغر.\r"], [445, "القول في اسم ذي الفضل العظيم\rوهو الاسم الحادي والعشرون من أسماء التنزيه، فيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [444, 445]}, "561.203": {"x": [[445, "ورد به القرآن، قال الله تعالى: {وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ} [البقرة: 105] في عدة مواضع، وورد في حديث أبي هريرة المفسر من طريق عبد العزيز بن الحصين، وأجمعت الأمة عليه لكونه في القرآن المجمع عليه.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [445, 445]}, "561.204": {"x": [[445, "أما كلمة (ف ض ل) فإنها تتصرف في كثير من اللغة، لكن معناه يرجع إلى الزيادة، تقول العرب: رجل مفضال: إذا كان كثير الخير، وأفضلتُ من الطعام فضلة، وأبين منه قوله: {وَاللَّهُ فَضَّلَ بَعْضَكُمْ عَلَى بَعْضٍ فِي الرِّزْقِ} [النحل: 71]، يعني: جعل ما عنده أزيد وأكثر مما عند صاحبه، وقال النبي صلى الله عليه وسلم: (لا يُمنع فضل الماء ليُمنع به الكلأ).\r"], [446, "الفصل الثالث: في شرحه حقيقة وعقيدة\r"]], "pg": [445, 446]}, "561.205": {"x": [[446, "وفيه مسألتان:\rالمسألة الأولى: في تحقيق كونه اسماً له سبحانه\r"]], "pg": [446, 446]}, "561.206": {"x": [[446, "قد سبق من البيان معنى قولنا (ذو) مفرداً، ومعنى كونه مضافاً إذا قلت: (ذو كذا)، وبينا أنه لا فرق بين أن يُقال: فلان ذو علم، أو: فلان عالم، وأنها إضافة صفة لا إشكال في ذلك، لكن الخبر ورد بتسميته تعالى: ذو الفضل، ولم يرد بتسميته فاضلاً فوقفنا عند الخبر.\rالمسألة الثانية: في تحقيق تركيب المعنى الاعتقادي على اللغوي\r"]], "pg": [446, 446]}, "561.207": {"x": [[446, "اعلموا أنه إذا كان الفضل الزيادة في الشيء، فللباري تعالى الفضل المبين العظيم على المخلوقات في ذاته وصفاته، وتنزهه عن الآفات التي تنال لمخلوقاته من الوجوه التي له عليها منها الرفعة، حسب ما تقدم بيانه، فذاته تعالى تزيد على الذوات بأنها لا أول لها ولا آخر، وبأنها تتقدس عن الحوادث أن تحل بها، وكذلك صفاته ليس لها أول ولا لها آخر، ولا يصح أن تنالها آفة، فظهر المعنى فيه، وتبين وجه الاعتقاد الصحيح في معانيه.\rالفصل الرابع: في التنزيل\r"]], "pg": [446, 446]}, "561.208": {"x": [[446, "إذا ثبت معنى الفضل فللباري تعالى في ذلك أحكام ثلاثة يختص بها:\rالأول: أنه لا يُحصى فضله.\r"], [447, "الثاني: أنه لا يُساوى فيه.\rالثالث: أنه مؤتيه لمن يشاء من عباده ومعطيه، كما قال: {يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ} [البقرة: 105].\rالمنزلة السفلى للعبد\rوحكمه في ذلك يرتبط بنكتتين:\rإحداهما: أن يعلم أن الفضل بيد الله.\rالثانية: أن يتحقق أن فضله على مقدار زيادته على غيره في العلم والعمل.\r"], [448, "القول في اسم السيد\rوهو الاسم الثاني والعشرون من أسماء التنزيه، فيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [446, 448]}, "561.209": {"x": [[448, "لم يرد به القرآن، لكن قال ابن عباس في قوله: {الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ} [الفاتحة: 2]، معناه: سيد العالمين، واختار ذلك شيخنا أبو الحسن، وسيأتي بيانه في اسم الرب إن شاء الله، ووردت به السنة، قال النبي صلى الله عليه وسلم: (السيد الله)، وأجمعت عليه الأمة لشرفه.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [448, 448]}, "561.210": {"x": [[448, "السؤدَد: الشرف، وقد يُهمز وتضم الدال، يقال: سادهم واستادهم: إذا صار سيدهم، وهو الرئيس، وجمعه: سادة، وقيل: سادة جمع سائد، ولم يسمع كذلك، وسيد كل شيء: أشرفه، والقرآن سيد الكلام، والله سيد الخلق.\r"], [449, "الفصل الثالث: في شرحه حقيقةً\r"]], "pg": [448, 449]}, "561.211": {"x": [[449, "إذا كان حقيقة السؤدد الشرف والرياسة والقدم في الفضل والإرباء على النظراء والأقران في خصال الكمال، رجع ذلك إلى معنى الفضل الذي تقدم بيانه، فركبه عليه وافهمه منه، والله أعلم.\rالفصل الرابع: في التنزيل\r"]], "pg": [449, 449]}, "561.212": {"x": [[449, "إذا علمت أن لله المنزلة العليا في السؤدد فله في ذلك حكمان يختص بهما:\rالأول: أنه منفرد بالسؤدد، وهو خصال الشرف على الكمال.\rالثاني: أنه يفعل في عبيده ما شاء، من غير حَجر ولا منع.\rالمنزلة السفلى للعبد\rأن ينظر مَن بيده بعين الأخوة، وإن كان له عليه فضل السيادة، فإنها عارية بيده، محجورة مقصورة عليه، معرَّضة للزوال، قال صلى الله عليه وسلم: (إخوانكم خولكم، ملككم الله رقابَهم، فأطعموهم مما تأكلون، واكسوهم مما تلبَسون، ولا تكلفوهم من العلم ما لا يطيقون، فإن كلفتموهم فأعينوهم).\r"], [450, "القول في اسم الكريم\rوهو الاسم الثالث والعشرون من أسماء التنزيه، فيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [449, 450]}, "561.213": {"x": [[450, "قال الله تعالى: {فَإِنَّ رَبِّي غَنِيٌّ كَرِيمٌ} [النمل: 40]، وقال النبي صلى الله عليه وسلم: (لله تسعة وتسعون اسماً، من أحصاها دخل الجنة)، فعدد أبو هريرة الأسماء وذكر الكريم من طريق شعيب، وذكر من طريق عبد العزيز بن الحصين: الأكرم، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [450, 450]}, "561.214": {"x": [[450, "اعلموا - أرشدكم الله - أن هذا الاسم مما تردد فيه كلام العرب والأصوليين والخلق، وأخذوا بكل طرف منه، وحوموا عليه فما أشفوا، ونحن نذكر أقوال كل طائفة، ونعين المختار بفضل الله، فنقول:\rاختلف أهل اللغة في العبارة عنه على ستة أقوال:\rالأول: أن الكريم: الكثير الخير، والعرب تسمي الكثير الخير: كريماً.\r"], [451, "الثاني: أن الكريم: هو الذي يدوم نفعُه ولا ينقطع، ومنه يقال للناقة الصفي الغزيرة: كريمة، قال أعرابي يصف ناقة احتاج إلى بيعها وكانت على هذه الصفة:\rوقد تُخرِج الحاجاتُ يا أم مالكٍ ... كرائم من رب بهن ضَنينِ\rالثالث: أن الكريم: هو الذي يسهل تناول ما عنده، ومنه تقول العرب للنخلة إذا لم تكن سحوقاً وقرب تناول جناها: كريمة، ولذلك كانت العرب تقول للعنب: الكَرْم، لأنه يجمع خصالاً سبعاً:\rالأول: لطف شجرته.\rالثاني: طيب ثمرته.\rالثالث: عدم مضرته؛ فإنه غير شائك.\rالرابع: قرب تناوله، فإنه تحت اليد.\rالخامس: سهولة قطافه.\rالسادس: أنه يؤكل أخضر ويابساً.\rالسابع: أنه يُتغذى به طعاماً وشراباً.\rبخلاف النخل، فإنه وإن كان كريماً ولكنه بعيد المتناول، شائك عسير القطف؛ لجفاء العِثكال.\rالرابع: أن الكريم هو: الذي له قدر عظيم وخطر كبير، ومنه قول الله مخبراً عن قول ملكة سبأ: {إِنِّي أُلْقِيَ إِلَيَّ كِتَابٌ كَرِيمٌ} [النمل: 29]، قيل:\r"], [452, "لكرم صاحبه، وقيل: لختمه، وقيل: لأن الطير حملته، وليست العادة أن تكون رسل الآدميين، فدل على كرم الكتاب وفضل الكاتب، وقيل: لحسن خطه، وقيل: لبيانه، فإنه مختصر اللفظ بالغ المعنى، ومنه قول العرب: طِرْفٌ كريم: إذا حُمدت أخلاقه ورُضي نِجاره.\rالخامس: أن الكريم: هو المنزه عن الدناءات، المبرأ عن النقائص والآفات.\rالسادس: أن الكريم: بمعنى المكرِم، وفعيل بمعنى مفعل كثير في اللغة وفي أسماء الله تعالى.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [450, 452]}, "561.215": {"x": [[452, "وفيه خمس مسائل:\rالمسألة الأولى: في سرد الأقوال فيه\r"]], "pg": [452, 452]}, "561.216": {"x": [[452, "اعلموا أن علماءنا اختلفوا في ذكر العبارة عن الكريم من المتكلمين والزهاد وأكثروا، فحصرتُ منها ستة عشر قولاً:\rالأول: الكريم: هو الذي لا يتوقع عوضاً عما يعطي.\rالثاني: الكريم: هو الذي يعطي بغير سبب.\r"], [453, "الثالث: الكريم هو: الذي لا يحتاج إلى الوسيلة، كما يروى عن حاتم الجود أن رجلاً لقيه يعتفيه، فقال: من أنت؟ قال: الذي أحسنتَ إليه في العام الماضي، فقال: مرحباً بمن تشفَّع بنا إلينا.\rالرابع: أن الكريم هو: الذي لا يبالي من أعطى، كان مؤمناً أو كافراً، مقراً أو جاحداً.\rالخامس: أنه الذي يرى لمن أعطاه منةً عليه في قَبوله.\rالسادس: أنه الذي يعطي ويثني، يُحكى أن الجنيد سمع رجلاً يقرأ {إِنَّا وَجَدْنَاهُ صَابِرًا نِّعْمَ الْعَبْدُ إِنَّهُ أَوَّابٌ} [ص: 44]، فقال: (سبحان الله، أعطى وأثنى)، المعنى أنه الذي وهب الصبر وأعطاه ثم مدح به وأثنى.\rالسابع: أنه الذي يعم بعطائه من يحتاج ومن لا يحتاج.\rالثامن: أنه الذي يعطي من يلومه، روي أن ابن عباس قال: (لا يُزهدنك في المعروف كفرُ من كفره، فإنه يشكرك عليه من لم تصنعه له)، وقد أُنشِد بعض الكرماء:\r"], [454, "إن الصنيعة لا تكون صنيعةً ... حتى تصيب بها طريق المَصنعِ\rفقال: (هذا رجل يريد أن يبخِّل الناس، أمطر المعروف مطراً، فإن أصاب فهو الذي تريد، وإلا كنتَ أحق به).\rالتاسع: أنه الذي يعطي قبل السؤال؛ كما قال الشاعر:\rرأى خَلَّتي من حيث يخفى مكانُها ... فكانت قذى عينيه حتى تجلتِ\rالعاشر: أنه الذي يعطي بالتعرض، كما قال أمية بن أبي الصلت في عبد الله بن جُدعان:\r"], [455, "إذا أثنى عليك المرء يوماً ... كفاه من تعرضه الثناءُ\rالحادي عشر: أن الكريم: هو الذي تُرفع إليه كل حاجة صغيرةً كانت أو كبيرة.\rالثاني عشر: أن الكريم: هو الذي إذا قدر عفا.\rالثالث عشر: أن الكريم هو: الذي إذا وعد وفى، كما يروى أن إسماعيل حين وعد أباه إبراهيم عليهما السلام بالصبر عند الذبح وفى له بذلك.\rالرابع عشر: أن الكريم هو: الذي لا يُضيع من التجأ إليه.\rالخامس عشر: أن الكريم هو: الذي لا يعاقِب.\rالسادس عشر: أن الكريم هو: الذي لا يعاتِب.\rالمسألة الثانية: في تركيب المعنى الاعتقادي على الأقوال السالفة لأهل اللغة والعلماء\rأما إذا قلنا: إن الكريم هو: الكثير الخير، فمن أكثر خيراً من الله لعموم قدرته وسعة عطائه، قال سبحانه: {وَإِن مِّن شَيْءٍ إِلَّا عِندَنَا خَزَائِنُهُ وَمَا نُنَزِّلُهُ إِلَّا بِقَدَرٍ مَّعْلُومٍ} [الحجر: 21].\r"], [456, "وأما إن قلنا: إنه الدائم الخير فذلك بالحقيقة لله، فإن كل شيء ينقطع إلا الله وإحسانه، فإنه دائم متصل في الدنيا والآخرة.\rوأما إن قلنا: إنه الذي يسهل خيره، ويقرب تناول ما عنده، فهو الله بالحقيقة، فإنه ليس بينه وبين العبد حجاب، وهو قريب لمن استجاب، كما قال تعالى: {وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ فَلْيَسْتَجِيبُوا لِي} [البقرة: 186].\rوأما إن قلنا: إن الكريم هو الذي له قدر عظيم، وخطر كبير، فليس لأحد قدر بالحقيقة إلا الله تعالى، إذ الكل له خلقاً ومِلكاً، إليه يضاف كل شيء، ومن شرفه شرف كل شيء، وكرم كل كريم من كرمه.\rوأما إن قلنا إن الكريم هو المنزه عن النقائص والآفات، فهو الله وحده بالحقيقة، لأنه تقدس عن النقائص والآفات وحده على الإطلاق والتمام والكمال، من كل وجه وفي كل حال، بخلاف الخلق؛ فإنهم إن كرُموا من وجه سفُلوا من وجه آخر، كما قال تعالى: {لَقَدْ خَلَقْنَا الْإِنسَانَ فِي أَحْسَنِ تَقْوِيمٍ. ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ} [التين: 4 - 5].\rوأما إن قلنا: إن الكريم بمعنى المكرم، فمن المكرم إلا الله تعالى، فمن أكرمه الله أكرم، ومن أهانه أهين، على ما يأتي بيانه إن شاء الله تعالى.\rوأما إن قلنا: إن الكريم هو: الذي لا يتوقع عوضاً، فليس إلا الله، لأن كل شيء خلقُه وملكه، فما يعطي له، وما يأخذ له، وما يعطي كلُّ معطٍ أو يعمل كل عامل فبقدرته وإرادته، والعوض والمعوَّض خَلْقٌ له.\r"], [457, "وأما إن قلنا: إن الكريم هو: الذي يعطي لغير سبب، فهو الله وحده، لأنه بدأ الخلق بالنعم، وختم أحوالهم بالنعم، وإن جاء في الأخبار أنه أعطى كذا بكذا أو عمل كذا لكذا، فالعطاء منه والسبب جميعاً، فالكل عطاء بغير سبب.\rوأما إن قلنا: إن الكريم هو: الذي يعطي بغير وسيلة، فالأجواد يتفاضلون في ذلك، فمنهم من يعطي جِبلة، ومنهم من يعطي مراعاة لحق المتوسِّل، والباري يعطي بغير وسيلة، لأن حرمة النبي أو الولي الذي أعطى بها أعطاها بمجرد المشيئة من غير وسيلة، كما قال تعالى: {وَلَكِنَّ اللَّهَ يَمُنُّ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ} [إبراهيم: 11].\rوأما إن قلنا: إن الكريم هو: الذي لا يبالي من أعطى، فهو الله وحده، لأن الخلق جبلت قلوبهم على حب من أحسن إليها وبغض من أساء إليها، والباري يعطي الكافر والمؤمن، وربما خص الكافر في الدنيا بمزيد العطاء، ولكن الآخرة للمتقين.\rوأما إن قلنا: إنه الذي يرى للقابل لعطائه منة، فالباري مقدس عن تصور ذلك في حقه.\r"], [458, "وأما إن قلنا: إن الكريم هو: الذي يعطي من احتاج ومن لا يحتاج، فهو الله وحده، لأنه يعطي ويزيد على قدر الحاجة، ويعطي من لا يحتاج ما لا يحتاج، حتى يصب عليه الدنيا صباً.\rوأما إن قلنا: إن الكريم هو: الذي لا يُخص بكبير من الحوائج دون صغير، فهو الباري تعالى، وروي أنه يَسأل العبدُ ربه كل شيء في صلاته قال: (حتى الملح).\rوذكر القشيري أن موسى قال في مناجاته: (إلهي، إنه لتعرض لي الحاجة أحياناً فأستحيي أن أسألك فأسأل غيرك، فأوحى إليه لا تسل غيري وسلني حتى ملح عجينك وعلف شاتك)، وذلك لأن أمره بين الكاف والنون، فسواء عنده الصغير والكبير، بل الكبير عنده صغير، والعسير يسير، والصعب لين.\rوأما إن قلنا: إن الكريم هو: الذي إذا قدر عفا، فالقدرة لله سبحانه وحده.\r"], [459, "وأما إن قلنا: إنه الذي إذا وعد وفى، فإن كل من يعد يمكن أن يفي، ويمكن أن يقطع به عذرٌ ويحولَ بينه وبين الوفاء أمر، والباري صادق الوعد لعموم قدرته وعظيم ملكه، وأنه لا يُتصور أن يقطع به قاطع، ولا يحول بينه وبينه مانع.\rوأما إن قلنا: إن الكريم هو: الذي لا يضيِّع من التجأ إليه، فهو الله وحده، والالتجاء إليه التزام الطاعة وحسن العمل، وقد أخبر بذلك عن نفسه حين قال: {إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا} [الكهف: 30].\rوأما إن قلنا: إن الكريم هو: الذي لا يعاقِب، فكم من عاص يَغفرُ له.\rوأما إن قلنا: هو الذي لا يعاتِب، فقد قال الله تعالى: {عَرَّفَ بَعْضَهُ وَأَعْرَضَ عَن بَعْضٍ} [التحريم: 3]، وقد جعل الله للناس مراتب في العقاب والحساب والعتاب: بيناها في كتاب المشكلين.\rوأما إن قلنا: إن الكريم هو: الذي أعطى وزاد على المُنى، فهو الله وحده، فقد روي أنه: (يعطي أهل الجنة مناهم ويزيدهم على ما يعلمون)،\r"], [460, "وقد روي أنه قال سبحانه: (أعددت لعبادي الصالحين ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر، بَلْهَ ما أطلعتهم عليه).\rالمسألة الثالثة:\r"]], "pg": [452, 460]}, "561.217": {"x": [[460, "قد تقدم في وصف الباري سبحانه وتعالى بأنه كريم، من الأقوال والتركيب ما أشرف على التتميم، وقد تعين بيانُ المختار والمنقح من الأقوال؛ فنقول:\rهذا الاسم من الأسماء التي لها معنيان: أحدهما يرجع إلى الذات، والآخر يرجع إلى الفعل، فإن قلنا: إن الكرم هو: عظم القدر وشرف الخطر بالتنزه عن الآفات، وجمع الخصال والمكرمات، فإن ذلك يعود إلى صفات التنزيه.\rوإن قلنا: إنه الكثير الخير، الدائم العطاء، عاد إلى صفات الفعل، ولا إشكال في أن الكرم في لسان العرب إنما يتردد على هذين الأصلين:\rأحدهما: شرف القدر، ولذلك تقول العرب: جواد كريم، وطِرف كريم، وفلان كريم الطرفين، وقال تعالى: {أُلْقِيَ إِلَيَّ كِتَابٌ كَرِيمٌ} [النمل: 29].\r"], [461, "والثاني: كثرة الخير. وكل ما عدا هذين الوجهين فإليهما يرجع، ودليله الاختبار والاستقراء، فصار هذا الاسم بمعنى من صفات التنزيه، وبمعنى آخر من صفات الفعل، والله تعالى أعلم.\rالمسألة الرابعة:\r"]], "pg": [460, 461]}, "561.218": {"x": [[461, "قد تقدم في وصفه تعالى بأنه كريم معنيان؛ ذاتي وفعلي، وبينا أنه يكون أيضاً بمعنى: مكرِم بالتخفيف، فعيل بمعنى مفعل، وقد جاء في القرآن أيضاً بمعنى مكرِّم بالتشديد والتضعيف، لقوله تعالى: {وَلَقَدْ كَرَّمْنَا بَنِي آدَمَ} [الإسراء: 70]، وهذا كله يرجع إلى فعل يقتضي صفة مدح وجلال، فجاز صوغ صفة له منه واسم، فنقول: إنه كريم، وإنه مكرِم مخففاً، وإنه مكرِّم مشدداً مضاعفاً.\rوقد جاء أيضاً في كتاب الله تعالى وصفه بأنه (ذو الجلال والإكرام)، وهو من أحد الأسماء المعددة في حديث أبي هريرة، وقد تقدم بيانُ أكثره، والإكرام: مصدر أكرم فهو مكرم، وهذا نص، فهو سبحانه ذو الكرم، وهو ذو الإكرام.\rأما كرمه فقد تقدم شرحه بجميع وجوهه المتعلقة بالله تعالى وبالعباد.\r"], [462, "وأما إكرامه للعبد فهو ما يخصه به من كرامته، وهو أخص من الإنعام، لأنه يُنعم على من لا يكرم، ولا يكرم إلا من عليه ينعم، قال تعالى: {فَأَمَّا الْإِنسَانُ إِذَا مَا ابْتَلَاهُ رَبُّهُ فَأَكْرَمَهُ وَنَعَّمَهُ فَيَقُولُ رَبِّي أَكْرَمَنِ. وَأَمَّا إِذَا مَا ابْتَلَاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أَهَانَنِ. كَلَّا} [الفجر: 15 - 17].\rيعني أنه إذا منحه نعيماً في الدنيا يقول: ذلك دليل على كرامتي، وإذا قدر عليه رزقه يقول: ذلك دليل على هواني.\rوليس الأمر كذلك؛ فليس نعيم الدنيا دليلاً على نعيم الآخرة، ولا هوان الدنيا دليلاً على هوان الآخرة، وإكرامه للعبد يكون معجَّلاً في الدنيا ومؤجَّلاً في الآخرة، ويكون عموماً في الخليقة، وخصوصاً لأهل الحقيقة، قال تعالى: {وَلَقَدْ كَرَّمْنَا بَنِي آدَمَ} [الإسراء: 70]، فلأهل العموم في ذلك أقوال، ولأهل الخصوص فيه أقوال.\rفأما أقوال أهل العموم فلهم فيه ستة أقوال:\rالأول: خصصناهم بالعقل والتمييز.\rالثاني: فضلناهم بالتسليط على سائر الخلق؛ يسخِّرونهم كالفُلك والدواب، بدليل قوله: {وَحَمَلْنَاهُمْ فِي الْبَرِّ وَالْبَحْرِ} [الإسراء: 70].\rالثالث: بالمشي قائماً غير منكب، وسائر الحيوان منكب.\rالرابع: يحاولون معاشهم بأيديهم، ويرفعونه إلى أفواههم، وغيرهم يحاوله بفمه، ولا يصرف فيه يدَه.\r"], [463, "الخامس: عاملناهم معاملة الكريم، لأنا بدأناهم بالنعمة قبل الخدمة.\rالسادس: بالتكليف، لقوله: {وَرَزَقْنَاهُم مِّنَ الطَّيِّبَاتِ} [الإسراء: 70]، يعني: الحلال.\rفهذه أمهات أقوال أهل العموم.\rوأما أهل الخصوص، فقالوا:\rاللفظ عام في الكل، والمراد به الخصوص للمؤمنين، كقوله تعالى: {كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ} [آل عمران: 110]، جرت الصفة على جماعتهم من أجل من فيهم، والدليل على صحة ذلك أنه قال في صفة الكفار: {وَمَن يُهِنِ اللَّهُ فَمَا لَهُ مِن مُّكْرِمٍ} [الحج: 18]، والتكريم هو التكثير من الإكرام، فإذا مُنع الكافر الإكرام وهو الأصل فكيف يحصل له التكريم وهو التكثير المبني عليه؟\rفإن قيل: فما الحكمة في العدول عن لفظ العموم إلى الخصوص؟\rالجواب: أن بعض علمائنا قال: إنما ذكر الله بني آدم على العموم ولم يخص المؤمنين ولا العابدين ولا المجتهدين ونحو هذا من الخصال؛ لئلا يقابل الكرم عملٌ أو يعلل بوفاق أمر أو يضافَ إلى استحقاقٍ بسبب، حتى\r"], [464, "يكون ذكر الكرم مبتدءاً من الكريم مجرداً عن كل سبب، ووجوه التكرمة متعددة، الحاضر منها في الخاطر أربعة أوجه:\rالأول: أنه إذا تاب ثم نقض وجد القبول أبداً.\rالثاني: أنه إذا عثر أخذ بيده.\rالثالث: أنه أعطى قبل السؤال.\rالرابع: أنه قال لهم: {فَاذْكُرُونِي أَذْكُرْكُمْ} [البقرة: 152]، ولم يقلها لملك ولا لجني. وهي كثيرة تفوت إحصائي، والله أعلم.\rالمسألة الخامسة:\r"]], "pg": [461, 464]}, "561.219": {"x": [[464, "اعلموا - وفقكم الله لليقين - أن جماعةً من المبتدعة شكّوا فقالوا: أطنبتم في وصف الباري بالكرم، ونحن نرى منعه للمحتاجين عما هو غني عنه وبهم حاجة إليه، وليس هذا فعلَ الكريم.\rالجواب: أنا نقول: ليس هذا فعل كريم يجب عليه الإنعام والإكرام، فأما كريم لا يجب عليه كرم، وإنما شأنه أن يفعل ما يشاء، فما فعل من إنعامه ففضل، وما ترك أو فعل من ضده فعدل.\rفإن قيل: بل يجب عليه أن يفعل ما يصلح بالمحتاجين والخلق أجمعين، ففيه جوابان:\r"], [465, "الأول: أنا نقول: لا نسلم ذلك، ومن يوجبه عليه؟ وليس فوقه آمر ولا ناهي.\rالثاني: أنا نقول: لو وجب عليه ولم يفعله لكان بتركه ظالماً، ويتعالى عن ذلك.\rفإن قيل: لا نقول إنه يجب عليه بموجب فوقه، ولكنه يجب عليه من الحكمة.\rالجواب: أنا نقول: ليس للحكمة معنى إلا العلم، وقد تقدم بيان ذلك، وليس في علم العقل ولا في علم السمع ما يوجب عليه ذلك.\rفإن قيل: الحكمة وضع الشيء في موضعه.\rالجواب: أنا نقول: ذلك هو حد العدل، ونعم، لقد وضع الأشياء في مواضعها حسب ما يأتي بيانه في اسم العدل، وتمامه في كتاب المقسط.\rالفصل الرابع: في التنزيل\r"]], "pg": [464, 465]}, "561.220": {"x": [[465, "إذا علمتم معنى الكريم والكرم فإن المنزلة العليا لله تعالى يختص فيها بخمسة أحكام:\rالأول: أنه عام الإرادة.\r"], [466, "الثاني: أنه يعطي عن قدرة.\rالثالث: أنه يمنع عن حكمة.\rالرابع: أنه ابتدأ بالنعم، قال تعالى: {اقْرَأْ وَرَبُّكَ الْأَكْرَمُ. الَّذِي عَلَّمَ بِالْقَلَمِ} [العلق: 3 - 4]، وقال أيضاً: {وَاللَّهُ أَخْرَجَكُم مِّن بُطُونِ أُمَّهَاتِكُمْ لَا تَعْلَمُونَ شَيْئًا} [النحل: 78].\rالخامس: أن المن لا يخل بكرمه.\rالمنزلة السفلى للعبد\rوذلك أنه لا يكون كريماً إلا بعد خصال أربع:\rالأولى: الإيمان.\rالثانية: الإسلام.\rالثالثة: احتقار الدنيا.\rالرابعة: مخالفة الهوى.\r"], [467, "القول في اسم الطيب\rوهو الاسم الرابع والعشرون من أسماء التنزيه، هو اسم طيب اللفظ، طيب المعنى، فيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [465, 467]}, "561.221": {"x": [[467, "أما القرآن فليس له فيه ذكر، وأما السنة فقد روي عن النبي صلى الله عليه وسلم أنه قال: (إن الله طيب لا يقبل إلا طيباً)، خرجه مسلم عن أبي هريرة، واجتنبه كثير من الناس لأنهم لم يقدُروه قدرَه ولا علموا صحته، ونحن نوضحه ونشرحه.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [467, 467]}, "561.222": {"x": [[467, "أما الطيب فقيل: إنه فيعل من طاب، وقيل: هو فاعل من طاب: ذهبت عينه، ويقال: طاب بمعنى: طَيَّبَ، وهو عبارة عن أربعة معانٍ:\rالأول: الشرف، تقول العرب: بيت طيب، يُكنى به عن شرف نفسه وكريم فعاله.\rالثاني: الحلال، قال تعالى: {يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ} [المؤمنون: 51].\r"], [468, "الثالث: نفي الآفات والمكاره، يقال: عيش طيب، إذا كان خالياً عن المكاره والآفات، وطوبى: شجرة في الجنة، وقيل: هي الجنة، وقد جمعت الشرف والتنزه عن الآفات واللذة، قال النبي صلى الله عليه وسلم لعمار: (مرحباً بالطيب المطيب)، يعني: الطاهر، وقال علي بن أبي طالب، وقد مات رسول الله صلى الله عليه وسلم فغسله وحاول منه ما يحاول من الميت فلم يجده: فقال: (بأبي أنت وأمي، طبت حياً وميتاً)، وكذلك قال له الصديق إذا وقف عليه، وقال النبي صلى الله عليه وسلم في المدينة: (طيبة)، يعني: تنقي الخبث والخبيث.\rالرابع: اللذيذ، يقال: طاب الطعام واستطبته، وجدته طيباً وسألته طيباً، ومنه يقال: الأطيبان؛ الطعام والنكاح.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [467, 468]}, "561.223": {"x": [[468, "وفيه مسألتان:\r"], [469, "المسألة الأولى: في تحقيق المعنى فيه\r"]], "pg": [468, 469]}, "561.224": {"x": [[469, "فنقول - وبالله التوفيق -: إن لفظ (ط ي ب) وإن كان يتصرف فيما تقدمت أعدادُه في لسان العرب، فإن حقيقته السلامة عن الآفات، والتنزه عن المكروهات، ويتركب عليه اكتساب الشرف والمكرمات، فإنه إذا عدم الأول ثبت الثاني، ولذلك قيل للحلال: طيب، لعدم المكروهات فيه، وقيل: للجنة طوبى، وقيل لأهلها: {سَلَامٌ عَلَيْكُمْ طِبْتُمْ} [الزمر: 73]، أي: ذهبت عنكم الآفات، فاكتسبوا الشرف بنزول الجنات.\rالمسألة الثانية: في التركيب الاعتقادي على المعنى اللغوي\r"]], "pg": [469, 469]}, "561.225": {"x": [[469, "إذا ثبت ما قدمناه من معنى الطيب وحقيقته، فالباري تعالى طيب لتقدسه عن الآفات، ووجوب الجلال له في الذات والصفات، حسب ما تقدم بيانه.\rالفصل الرابع: في التنزيل\r"]], "pg": [469, 469]}, "561.226": {"x": [[469, "إذا عرفتم ما تقدم فللباري في المنزلة العليا حكمان:\rأحدهما: أنه لا تجوز عليه آفة.\rالثاني: لا ينقصه جلالٌ ولا عظمة.\rالمنزلة السفلى للعبد\rأن يجتهد في أمرين:\rأحدهما: التطهر عن الآفات.\rالثاني: اكتساب المكرمات.\r"], [470, "القول في اسم الأول\rوهو الاسم الخامس والعشرون من أسماء التنزيه.\rاعلموا - وفقكم الله - أن هذا اسم عظيم اللفظ، عظيم المعنى، اختلف أهل اللغة فيه، واتفق أهل التوحيد عليه، وهو ركن من التوحيد وثيق، واسم يحتاج المتكلم فيه إلى مزيد تحقيق، وفيه أربعة فصول:\rالفصل الأول: في مورده شرعاً\r"]], "pg": [469, 470]}, "561.227": {"x": [[470, "قال الله تعالى: {هُوَ الْأَوَّلُ وَالْآخِرُ} [الحديد: 3]، وكان النبي صلى الله عليه وسلم يقول في دعائه: (أنت الأول فليس قبلك شيء).\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [470, 470]}, "561.228": {"x": [[470, "وفيه خمس مسائل:\rالمسألة الأولى: في حروفه الأصلية\r"]], "pg": [470, 470]}, "561.229": {"x": [[470, "وهي واوان ولام، وهي نادرة، لأن فاء الفعل وعين الفعل لا يكون حرفاً متكرراً إلا في سبع كلمات مسموعة، وهي:\r"], [471, "دَدٌ، وددن، وبابوس، وسيسبان، وقيقبان، وكوكب، هذا مذهب البصريين، وقيل: بابوس على أحد الوجهين.\rوقال غيرهم: حروفه همزة وواو ولام، ولكنهم اختلفوا في تركيبها، فمنهم من جعل الهمزة فاء الفعل، ومنهم من جعلها عين الفعل.\rالمسألة الثانية: في وزنها\r"]], "pg": [470, 471]}, "561.230": {"x": [[471, "لا خلاف بينهم في أن وزنها أفعل، لكن البصريون يقولون: إن وزنه أَوْوَل، والآخرون يقولون: أصله أَأْوَل، من آل يؤول: إذا ساس أو رجع، والآخرون يقولون: أصله أوأل، من وأل، أي: لجأ.\rالمسألة الثالثة: في تحقيق وزنها\r"]], "pg": [471, 471]}, "561.231": {"x": [[471, "اعلموا أن مذهب البصريين هو الصحيح، إذ لا يصح أن يكون أاول من: آل يؤول، والتأويل: تفعيل منه، لأنه لو كان كذلك لكانت الهمزة فيه فاءً، فتقلب ألفاً إذا دخلت عليها همزة أفعل، كقولهم: ابن آوى.\r"], [472, "ولا يجوز أن يكون هذا على قولهم: سَوءة وضَوء، لأن هذا عكسه، لأن الهمزة في سوءة متأخرة عن الواو، والواو متقدمة، وأول بعكس ذلك.\rولا يصح أن يكون من وأل، لأنك لو خففت لقلت: أول، فلما شددوه دل على أنها أصلية، إذ لم تخفف إلا في باب سوءة، وهو نادر.\rوالتحقيق فيه: أنه لو كان أصله أوأل لحُقق ورُد إلى أصله، ولم يُسمع ذلك فيه.\rيزيده تأكيداً: أن مؤنثه أُولى، فلو كان من وأل لم يلزم إبدال الوال، لأن الواو الأولى المضمومة لا يلزم إبدالها، ويوضحه أمور كثيرة من تصريف اللسان لا يمكن التطويل في هذا الباب بذكرها.\rالمسألة الرابعة: في بيان كونها وصفاً أو اسماً\r"]], "pg": [471, 472]}, "561.232": {"x": [[472, "اعلموا - وفقكم الله - أن الحكم في الأسماء عند أهل العربية الذين هم العمدة في بيان اللسان أن ينظر إليها، فما كان منها لا يتصرف جعل اسماً، وما كان منها يتصرف جعل وصفاً، وقد تندر أسماء في الوجهين، لكن\r"], [473, "الأصل الشائع ما ذكرناه، وأسماء الباري تعالى كلها متصرفة، فلذلك قالت العلماء: إنها أوصاف، وقد بينا في ترديد كلماتنا فيها أن منها ما يكون وصفاً، ومنها ما يكون مصدراً سمس به، جرياً على حكم اللسان العربي الذي أنزل به القرآن المبين على محمد صلى الله عليه وسلم.\rوأول هذا المشروح الآن من جملة الأوصاف، إلا أنه لم يتصرف على الإطلاق لثقل حرف العلة فيه، كما لم يصرفوا أبيض وإن كان وصفاً، وقد قالوا: رجعل مدرهم، ولم يصرفوه.\rوالدليل على أنه وصف: قولهم في مؤنثه: أولى، وقد جاء اسماً في قولهم: مررت بأول منه، وقالوا: ما تركت له أولاً ولا آخراً، أي: قديماً ولا حديثاً، واتسعوا فيه فقالوا في الظرف: ما رأيته مذ عام أول، كما قال تعالى: {وَالرَّكْبُ أَسْفَلَ مِنكُمْ} [الأنفال: 42].\rالمسألة الخامسة:\r"]], "pg": [472, 473]}, "561.233": {"x": [[473, "إذا ثبت أنه وصف فإنه يتقدر بقولك: (من)، وقد تحذف (من) عنها وتكون مرادة وغير مرادة، فإن قدرت (من) معها وأضفتها إلى الباري تعالى\r"], [474, "كان تقديره: هو أول من كل شيء، كما تقول: أكبر من كل شيء، وإن حذفتها وأضفت قلت: هو أول الموجودات، ولا يصح تقديرها ها هنا، لأنها لا يصح أن تجتمع مع الإضافة.\rالفصل الثالث: في شرحه عقداً وتحقيقاً\r"]], "pg": [473, 474]}, "561.234": {"x": [[474, "فيه ثلاث مسائل:\rالمسألة الأولى: في سرد أقوال العلماء\r"]], "pg": [474, 474]}, "561.235": {"x": [[474, "ولهم في ذلك خمس عبارات:\rالأول: أنه الموجود قبل الخلق، كان ولا شيء قبله ولا معه، قاله ابن عباس.\rالثاني: أنه لا ابتداء له.\rالثالث: أنه الذي له كل شيء، وبه كل شيء، ومنه كل شيء، كما يقال: فلان أول هذا الأمر وآخره.\rالرابع: أنه الأول بصفاته.\rالخامس: أنه الأول بمحبته لأوليائه.\r"], [475, "المسألة الثانية: في تحقيق هذه الأقوال\r"]], "pg": [474, 475]}, "561.236": {"x": [[475, "أما من قال: إنه الموجود قبل الخلق، فصحيح.\rوأما الذي قال: إنه الذي لا ابتداء له، فأصح منه في المعنى، لكن لفظ أول لا يقتضيه بنفسه وإطلاقه، وإنما كان أصح منه في المعنى، لأنا وإن قلنا: إن الباري قبل كل شيء، فلا نقول: إنه قبله بمدة محدودة ولا ميقات معين، بل لا يتصور في الوهم ولا يتقدر في العقل وجود إلا والباري تعالى سابق له، حتى تنقطع الأوهام وتفنى التقديرات، والباري تعالى في ذلك كله موجود.\rوأما قول من قال: إنه له كل شيء كما يقال: فلان أول هذا الأمر وآخره، فهذا مجاز في اسم الأول، ولكنه صحيح في وصف الباري، فإن بيده ملكوت كل شيء، ويرجع ذلك إلى معنى المِلك.\rوأما قول من قال: إنه أول بصفاته، فصحيح أيضاً، لأنه لم يزل موجوداً بصفاته ولا يزال، وحال صفاته حال ذاته، كما جاء بيانه في موضعه.\rوأما قول من قال: إنه الأول لمحبته لأوليائه فباب طويل عريض، فإن ما كان من الله ومن العبد فالباري فيه سابق، والعبد لاحق متأخر، كالعلم والقدرة والإرادة والكلام والخلق والرزق، وكل ما كان مثله فاطرده في كل طريق، وأدره على قطب التحقيق.\r"], [476, "المسألة الثالثة: في المختار\r"]], "pg": [475, 476]}, "561.237": {"x": [[476, "لا يخفى على ذي علم أن الأسماء على ضربين: جامدة ومشتقة، ومن وجه آخر على ضربين: مطلقة ومضافة، فالجامد والمشتق قد سبق بيانه.\rوأما المطلق: فما يدل على ذاته، ولا يقتضي مقابلاً له، والمضاف: ما يقتضي مقابلاً له ويستدعي ثانياً، كقولنا: أب وطويل وكبير، وقولنا: (أول): من الأسماء المضافة، لأنه يقتضي آخراً، وحقيقته على ما سبق بيانه أن وجوده كان قبل وجود غيره، فلذلك قلنا: إن العبارة السديدة في الإعراب عنه أنه الموجود قبل الخلق، ومعناه: أن وجوده سبق وجود الخلق، وكونه سابقاً بغير مدة أمر لم يقتضه اللفظ، وإنما اقتضاه دليل آخر بيناه في أصول العقائد، وهو أنا لو قدرنا وجوداً مجرداً لكان مفتقراً إلى موجد، فلا بد من موجود لا موجد له، وهو مُصدر الموجودات.\rالفصل الرابع: في التنزيل\r"]], "pg": [476, 476]}, "561.238": {"x": [[476, "المنزلة العليا للرب في هذا الاسم تقتضي له أحكاماً ثلاثةً:\rالأول: أنه لم يزل.\rالثاني: أنه لا يكافأ على النعمة ولا يعارض في البلاء.\r"], [477, "الثالث: أنه لا يسبق بالفعل ولا بالمشيئة، لأن فعله قبل كل فعل، ومشيئته قبل كل مشيئة، وهذا أمر خص الله به أهل السنة، فإن المعتزلة يزعمون أن ما أراد الله مزحوم مسبوق بإرادة العبد.\rالمنزلة السفلى للعبد\rأن يجتهد في أن يكون أولاً في العلم والعمل، حتى يدخل في مضمار السابقين، وينادى بسمة المقربين.\r"], [478, "القول في اسم القديم\rوهو الاسم السادس والعشرون من أسماء التنزيه، وفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [476, 478]}, "561.239": {"x": [[478, "لم يرد به قرآن ولا سنة، لكن روى أبو داود عن النبي صلى الله عليه وسلم أنه إذا دخل المسجد قال: (أعوذ بالله العظيم وبوجهه الكريم وبسلطانه القديم من الشيطان الرجيم، فإذا قال ذلك، قال الشيطان: حُفظ مني سائر اليوم) لكن، علماؤنا قالوا: إنه أجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [478, 478]}, "561.240": {"x": [[478, "القديم: فعيل، من قولهم: قدُم فهو قديم، إذا تقدم في الوجود على غيره.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [478, 478]}, "561.241": {"x": [[478, "اعلموا - وفقكم الله - أن علماءنا عظموا قدر هذا الاسم، وأطنبوا فيه القول وادعوا عليه الإجماع، وقد درج الصحابة والتابعون، ولم يعرفوه ولا\r"], [479, "ذكروه، ولكن لما حدثت الأهواء، ودخل في الشريعة كلام الفلاسفة والأطباء، استعملوا هذه اللفظة، فلما لحظها علماؤنا لم يمكن ردها وقد شاعت، ورأوا لها وجهاً سائغاً فاستعملوه، ورتبوا له فصولاً، وبنوا عليه فروعاً، وقالوا: إن القديم: فعيل من قدُم، وهو عبارة عن مبالغة التقدم في الوجود.\rوَلَعَمْرُ الله لو كان من الأسماء الواردة في الشريعة لبسطنا فيه القول، وتتبعنا متعلقاته بالبيان، ولكن نذكر فيه قول علمائنا على رسم الحكاية من غير تقليد لعهدة شيء، فنقول: فيه أربع مسائل:\rالمسألة الأولى:\r"]], "pg": [478, 479]}, "561.242": {"x": [[479, "قال أكثر علمائنا: القديم لا معنى له أكثر من التقدم في الوجود على وصف المبالغة، وقال آخرون: هو قديم بقِدم، كما هو عالم بعلم، ولا نقول في صفاته إنها قديمة، والصحيح هو الأول، وقد قررنا ذلك في الأصول.\rالمسألة الثانية: في حقيقة القديم\r"]], "pg": [479, 479]}, "561.243": {"x": [[479, "قالت طائفة من المبتدعة: لا قديم في الحقيقة إلا الله، لأن المبالغة في التقدم ليست إلا له، ونازعهم في ذلك علماؤنا وقالوا: إن أهل اللغة قالوا:\r"], [480, "بناء قديم، وعرجون قديم، على طريقة واحدة، فدل على أنه حقيقة، ولم يصرفوه بوجهين، فيُدَّعى في أحدهما المجاز، وإنما علمنا تقدم الوجود إلى غير غاية في وصف الباري من غير هذه الطريقة.\rالمسألة الثالثة:\r"]], "pg": [479, 480]}, "561.244": {"x": [[480, "قال معمر القدري: (لا يوصف الباري تعالى بأنه قديم إلا بعد وجود المحدَث)، وقد أخطأ العبارة، وإنما صوابه أن يقال: إنه لا يوصف بأنه قديم إلا بالإضافة إلى المحدَث، كما لا يوصف بأنه أول إلا بالإضافة إلى الآخر.\rالمسألة الرابعة:\r"]], "pg": [480, 480]}, "561.245": {"x": [[480, "لا يوصف الباري بأنه أزلي، لأنها لفظة فلسفية لا يعضدها الاشتقاق، ولا تشهد لها اللغة، ولا تحتملها الشريعة.\r"], [481, "القول في اسم الآخر\rوهو الاسم السابع والعشرون من أسماء التنزيه، وفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [480, 481]}, "561.246": {"x": [[481, "قد ورد به القرآن، قال تعالى: {هُوَ الْأَوَّلُ وَالْآخِرُ} [الحديد: 3]، ووردت به السنة، قال صلى الله عليه وسلم: (اللهم أنت الآخر فليس بعدك شيء)، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [481, 481]}, "561.247": {"x": [[481, "وفيه أربع مسائل:\rالمسألة الأولى:\r"]], "pg": [481, 481]}, "561.248": {"x": [[481, "قال علماؤنا - رحمة الله عليهم -: إن آخراً وزنه فاعل، وتأنيثه الآخرة، كقولنا: ضارب وضاربة، ويقال: نظر فلان بمؤخر عينه، بكسر الخاء، ومؤخرة الرحل، بكسر الخاء أيضاً، وجاء فلان بأخَرَة بفتح الخاء.\r"], [482, "المسألة الثانية: في تصريفه\r"]], "pg": [481, 482]}, "561.249": {"x": [[482, "زل بعض العلماء فقال: إن أصله أُخْرَيائي، لكنهم أماتوا هذا التصريف، وهذا زلل ظاهر من وجهين:\rأحدهما: أنه دعوى.\rوالثاني: أنه لا نظير لما قال، ولا شاهد عليه ولا دليل؛ وما هو إلا كما بيناه، وكأن فعله لو تصرف: أَخَرَ يأخَر، لكنهم لم يصرفوه، كما لم يصرفوا رجل مدرهم، وكما قالوا: رجل آبل: إذا كان حسن القيام على إبله، ولم يُصرِّفوا منه فعلاً.\rالمسألة الثالثة: في قولنا: (آخر) بفتح الخاء\r"]], "pg": [482, 482]}, "561.250": {"x": [[482, "وهو في مقابلة أحد، كما أن آخِر بكسر الخاء في مقابلة أول، تقول: جاء أحد الرجلين ثم جاء الآخَر، بفتح الخاء، وجاء أول القوم ثم جاء الآخِر، بكسر الخاء.\rفأما كسر الخاء فقد تقدم بيانه، وأما فتحها فهو أفعل منه، ووزنه أأخر، وكان حقه أن يكون مستعملاً في الأكثر تأخيراً، كما يستعمل الأفضل\r"], [483, "من فاضل في الأكثر فضلاً، لكنهم نقلوه إلى الثاني، فقالو: هذا أحد الرجلين، وهذا الآخر، واستعملوه على باب الأحمر والأبيض، فإنه على وزن أفعل، ولكن على غير مراد الأكثر، وإن كانوا قد قالوا: محمرٌّ ومبيضٌّ.\rالمسألة الرابعة:\r"]], "pg": [482, 483]}, "561.251": {"x": [[483, "قال بعض علمائنا: الآخر - بفتح الخاء - تأنيثه الأخرى، والآخر - بكسر الخاء - تأنيثه الآخرة، وهذا فاسد، بل الأخرى تستعمل في تأنيث الآخِر، قال تعالى: {وَقَالَتْ أُولَاهُمْ لِأُخْرَاهُمْ} [الأعراف: 39]، وإنما ينبغي أن يقال: إن تأنيث الآخر يقال فيه: آخرة وأخرى، وتأنيث الآخر يقال فيه: الأخرى خاصة، وقد صُرِّفَ من الآخر - بكسر الخاء - فعل على غير مثاله، فيقال: تأخر فهو متأخر، وأما الآخر بفتح الخاء فلم يصرِّفوا منه فعلاً بحال.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [483, 483]}, "561.252": {"x": [[483, "وفيه أربع مسائل:\r"], [484, "المسألة الأولى: في سرد أقوال العلماء فيه\r"]], "pg": [483, 484]}, "561.253": {"x": [[484, "وهي نحو ما سبق في الأول، فإنه مقابله، ولهم في ذلك ست عبارات:\rالأول: أنه الموجود بعد الخلق فلا شيء بعده.\rالثاني: أنه الذي لا انتهاء له.\rالثالث: أنه الذي يرجع إليه كل شيء.\rالرابع: أنه الذي أخر الأواخر، قاله الضحاك، يعني: أنه الذي جعل لكل شيء آخراً.\rالخامس: أنه الآخر بقضائه وقدره.\rالسادس: أنه الآخر بإظهار محبته لأوليائه ونقمته لأعدائه.\rالمسألة الثانية: في تحقيق هذه الأقوال\r"]], "pg": [484, 484]}, "561.254": {"x": [[484, "أما قول من قال: إنه الموجود بعد الخلق، فصحيح.\rوأما قول من قال: إنه لا انتهاء له، فلفظ آخر لا يقتضيه، كما لم يقتض لفظ الأول ما لا ابتداء له، ولكن الباري هو الآخر لكل موجود\r"], [485, "متحقَّق، والآخر لكل موجود مقدَّر، كما أنه الأول لكل موجود متحقق، والأول لكل موجود مقدر، فهو الأول والآخر حقيقة.\rوأما قول من قال: إنه الذي يرجع إليه كل شيء، فصحيح في المعنى، لأن إلى ربك المنتهى، لكن اللفظ لا يقتضيه، فهو مجاز على بُعد.\rوأما قول من قال: هو آخر بقضائه وقدره، فلا وجه له، فإنه يصح أن يقال هو أول بقضائه وقدره.\rوأما قول من قال: إنه آخر بمعنى أنه أخر الأواخر، فهذا إنما كان يصح لو كان المؤخر، فأما الآخر فليس يشهد له تصريف ولا معنى.\rالمسألة الثالثة: في وهم بعض العلماء\r"]], "pg": [484, 485]}, "561.255": {"x": [[485, "كان بعض علمائنا يقول: إن معنى وصفنا للباري بأنه أول يرجع إلى الإضافة إلى المعرفة به، فإنه لم يكن وجوده بغيره، فكان أول الموجودات، وأما كونه آخراً فإن الناظر في معرفة الباري إذا لاحظ موجودات العالم وترقى في مراتب النظر في حدثه ومحدثه انتهى به النظر آخراً - إذا كان مُسْتَدّاً\r"], [486, "كاملاً - إلى الله تعالى، فهو آخر النظر ومنتهاه، وهو آخر بهذا المعنى. وهذا أمر لا يدفعه اشتقاق ولا ترده حقيقة، ولكن لا يصح أن يجعل هذا معناه الأظهر، فكيف أن يُخَصَّ بمعنى هذا الاسم دون ما سواه.\rوالدليل عليه أن النبي صلى الله عليه وسلم كان يقول في دعائه: (اللهم أنت الآخر فليس بعدك شيء)، ولا يصح أن يريد به أنت الآخر في المعرفة فليس بعد معرفتك شيء يُعرف، فإن بعد معرفته تتوجه المطالب وتفرض العلوم، وإنما المراد به؛ فليس بعد كونك شيء كائن، وهذا صحيح واجب.\rالمسألة الرابعة: في المختار\r"]], "pg": [485, 486]}, "561.256": {"x": [[486, "إذا علمتم ما سبق من البيان والتقسيم، فالصحيح في وصفه بالآخر، أنه الموجود الذي لا انتهاء له، وهذا يختص به سبحانه وحده على التحقيق، وهو حقيقة اللفظ، ولا يُمنع بعد هذا أن تكون له معان كثيرة، ولكن تُعرض المعاني على اشتقاق اللغة، واستمراره على الحقيقة، وسلامة الانتقاض، كما بيناه.\rالفصل الرابع: في التنزيل\r"]], "pg": [486, 486]}, "561.257": {"x": [[486, "المنزلة العليا لله تعالى\rيختص فيها بأربعة أحكام:\r"], [487, "الأول: أنه الدائم.\rالثاني: أنه يستحيل عليه العدم.\rالثالث: أنه إليه المنقلب.\rالرابع: أن عنده تحقيق المواعد.\rالمنزلة السفلى للعبد:\rإذا علم العبد معنى الآخر لزم حكمَ الأواخر، وذلك بالتبري من الحول والقوة والمشيئة، وجريان الأقضية والمقادير، والقيام بحسن التدبير والتواضع الذي يليق بالعباد.\rالمسألة الخامسة: في أسماء تتعلق بهذا الاسم من طريق المعنى وي"]], "pg": [486, 487]}, "561.258": {"x": [[487, "قرب تفسيرها منه\rوهي ثلاثة: الباقي، الوارث، الدائم.\r"], [488, "[الباقي]\rأما الباقي: فلم يرد به قرآن ولا سنة اسماً، لكن ورد في القرآن فعلاً، قال تعالى: {وَيَبْقَى وَجْهُ رَبِّكَ} [الرحمن: 27]، وقد بينا معناه في كتاب المشكلين، وأجمعت عليه الأمة، واختلفوا في معناه اختلافاً عظيماً بيناه في كتاب المقسط، والجملة فيه تحصره ثلاثة فصول:\rالأول: أن الباقي في اللغة هو: الموجود زمانين فما زاد، وهو في الشريعة عبارة عن ذلك المعنى بنفي التناهي، قال تعالى: {وَيَبْقَى وَجْهُ رَبِّكَ} [الرحمن: 27]، قال سبحانه: {وَالْبَاقِيَاتُ الصَّالِحَاتُ} [الكهف: 46].\rالثاني: وصف الباري بأنه باقٍ عبارة عن أنه لا انقطاع لوجوده، فلا باقي في الحقيقة إلا الله.\rالثالث: أن علماءنا اختلفوا في أن الباري باق ببقاء كما هو عالم بعلم أم لا؟ فقال بعضهم: له بقاء، وإن كان يوصف بأنه باق، وقد بينا ذلك في موضعه، وهو أمر قريب لا يضر في الاعتقاد.\r"], [489, "[الدائم]\rالدائم هو: بمعنى الباقي، يقال: دام وبقي بمعنى، لا فرق بينهما، وقد ورد الدائم في حديث أبي هريرة من طريق عبد العزيز.\r"], [490, "الوارث\rفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [487, 490]}, "561.259": {"x": [[490, "ورد به القرآن، قال تعالى: {وَإِنَّا لَنَحْنُ نُحْيِي وَنُمِيتُ وَنَحْنُ الْوَارِثُونَ} [الحجر: 23]، وقال: {إِنَّا نَحْنُ نَرِثُ الْأَرْضَ وَمَنْ عَلَيْهَا} [مريم: 40]، وجاء في حديث أبي هريرة المفسر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [490, 490]}, "561.260": {"x": [[490, "ومعناه في اللغة: الخالف غيره في حاله، وبذلك تسمي العرب المستحق للمال من بعد الميت: وارثاً، قالوا: وأصله من الإرث، وهو أصل الشيء، ومنه قول النبي صلى الله عليه وسلم: (اثبُتوا على مشاعركم، فإنكم على إرث من إرث إبراهيم)، المعنى: على بقية من شرعه أخذتموه منه.\r"], [491, "الفصل الثالث: في الحقيقة\r"]], "pg": [490, 491]}, "561.261": {"x": [[491, "والحقيقة فيه: أن الوارث هو: الكائن بصفة المستحق لحال الموروث، وإن لم يبق بعده، والباري تعالى وارث بالمعنيين:\rأحدهما: أنه المستحق للأشياء كلها.\rوالثاني: أنه الباقي بعد الخلق؛ كما قال صلى الله عليه وسلم: (إن الباري يقول بعد فناء المخلوقات: لمن المُلك اليوم؟ فلا يجيبه أحد، فيقول: لله الواحد القهار).\rفإن قيل: فهذا الاسم من صفات الذات والتنزيه، فكيف يكون وارثاً في الأزل وليس هنالك موروث؟\rقيل: لا يُنكَر أن يسمى وارثاً عند فناء الخلق، وهو وارث في الأزل، بمعنى أنه المستحق للإرث عند فناء الخلق، كما يقال: الابن وارث الأب، على معنى أنه المستحق لحاله، وكما قال بعض علمائنا: إنه تعالى يسمى آمراً عند وجود المأمورين، وإن كان كلامه لم يزل وليس له أول.\r"], [492, "الفصل الرابع: في التنزيل\r"]], "pg": [491, 492]}, "561.262": {"x": [[492, "المنزلة العليا للرب\rأنه الوارث لجميع المخلوقات.\rالمنزلة الثانية للعبد\rأن يجتهد في أن يكون وارثاً للجنة، إذ لا بد أن يكون موروثاً.\r"], [493, "القول في اسم الظاهر\rوهو الاسم الحادي والثلاثون من أسماء التنزيه، وفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [492, 493]}, "561.263": {"x": [[493, "قال تعالى: {هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ} [الحديد: 3]، ووردت به السنة، كان النبي صلى الله عليه وسلم يقول في دعائه: (اللهم أنت الأول فليس قبلك شيء، وأنت الآخر فليس بعدك شيء، والظاهر فليس فوقك شيء)، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [493, 493]}, "561.264": {"x": [[493, "قال علماؤنا - رحمة الله عليهم -: فيه أربع عبارات:\rالأول: ظهر بمعنى بدا، لما كان خفياً لا يُدرى.\rالثاني: ظهر بمعنى علا.\rالثالث: ظهر بمعنى غلب.\rالرابع: ظهر بمعنى زال.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [493, 493]}, "561.265": {"x": [[493, "وفيه أربع مسائل:\r"], [494, "المسألة الأولى: في سرد أقوال العلماء فيه\r"]], "pg": [493, 494]}, "561.266": {"x": [[494, "وهي كثيرة جداً، لكن أمهاتها خمسة:\rالأول: أنه الظاهر بدلائله.\rالثاني: أنه القاهر لعباده.\rالثالث: أنه الظاهر بقدرته.\rالرابع: أن الظاهر هو: العالي.\rالخامس: أنه الذي أظهر الظواهر.\rالمسألة الثانية: في حقيقة اللفظة\r"]], "pg": [494, 494]}, "561.267": {"x": [[494, "هي البُدوُّ، وكل شيء تصرف منه فإليه يرجع، لأن العلو بدو، إذ كل عال على شيء فهو أظهر منه، وكذلك الغالب؛ ظاهر باد على المغلوب، والرِّكاب تسمى ظَهراً لأن بها يكون الظهور إلى البلاد، كما قال تعالى: {وَتَحْمِلُ أَثْقَالَكُمْ إِلَى بَلَدٍ لَّمْ تَكُونُوا بَالِغِيهِ إِلَّا بِشِقِّ الْأَنفُسِ} [النحل: 7]، والظهيرة: بدو الحر.\rالمسألة الثالثة: في تحقيق الأقوال المتقدمة\r"]], "pg": [494, 494]}, "561.268": {"x": [[494, "قد بينا أن الظاهر هو: البادي، وبينا أن الأول والأولى في معنى ظهر: بدا، وما بعده به لاحق، فمن قال: إن الباري ظاهر بآياته، فقد صدق، فلولا مخلوقات الله ما علمه أحد غيره، فبما خلق وعلَّم ودلَّ ظهر.\r"], [495, "ومن قال: إنه ظاهر بقدرته، فإنما أراد أن المخلوقات حدثت عن القدرة، فنسب الظهور إلى السبب الذي كانت عنه الآيات التي ظهر بها، وذلك مجاز. ومن قال: إنه بمعنى العالي والقاهر، فقد قدمنا أنه ظهور كله.\rومن قال: إنه بمعنى إظهار الظواهر، فلا أعلم في اللغة فاعل بمعنى مفعل، وإنما المعلوم فيها فعيل بمعنى مفعل، وأما بعض أهل العربية فقد قال: إن فاعلاً يأتي بمعنى مفعول، كقوله: {لَا عَاصِمَ الْيَوْمَ مِنْ أَمْرِ اللَّهِ} [هود: 43]، أي: لا معصوم، وهذه دعوى باطلة.\rالمسألة الرابعة: في المختار\r"]], "pg": [494, 495]}, "561.269": {"x": [[495, "قد قدمنا أن الأسماء على ضربين: مطلقة كزيد، ومضافة كطويل وشبهه، وبينا حقيقة ذلك وانقسامه في الدلالة في تفسير اسم الأول، وقولنا: ظاهر، من الأسماء المضافة، لأنه يدل على مقابلة، وهو الباطن، فلولا الظاهر لم يكن باطناً، ولولا الباطن لم يكن ظاهراً.\rفإذا ثبت هذا فاعلموا أن الظاهر والباطن قد يكونان شيئين، وقد يكون الظاهر الباطن شيئاً واحداً من وجهين، ولا يصح أن يكون ظاهراً من وجه باطناً\r"], [496, "من ذلك الوجه، لأن ذلك قول بالجمع بين الضدين الذي قد تقررت استحالته عن العقلاء، والباري تعالى ظاهر بالأدلة والبراهين التي وضعها للاستدلال عليه بها.\rفإن قيل: كيف يكون الباري ظاهراً وقد استراب فيه كثير من الخلق، والجاهل به أضعاف العالم به بما لا يحصى؟\rالجواب: أنا نقول: هذا سؤال من لا يعرف الظاهر، وبيانه: أن الظاهر له مرتبتان:\rإحداهما: ظاهر للمحسوسات والبَدائِه.\rالثاني: ظاهر بالنظر في الأدلة والبحث في سبيل المعقولات.\rفأما القسم الأول فلا خفاء به على أحد، ولا اختلاف فيه عند بشر.\rوأما القسم الثاني فهو الذي يُختلف فيه ويُستراب به، فمن عرف الدليل والمدلول، وفهم مدارك العقول، ولم يذهل ولا جهل، ولا غلط في الوجه الذي منه يستدل، أفضى إلى المعرفة ووقف على الحقيقة، ولم يوفق لذلك إلا قليل، فلذلك كان العارف بالله تعالى قليلاً.\r"], [497, "وهم وتنبيه:\rقال بعض علمائنا قولاً لم أتحققه نقلاً، ولكني أورده بنصه، وأذكر ما يجب فيه، قال: (كون الباري ظاهراً للعقل غامض، إذ الظاهر ما لا يُتمارى فيه، وقد استراب خلق كثير بالله، فكيف يكون ظاهراً).\rثم قال: الجواب: (إنه إنما خفي مع ظهوره لشدة ظهوره، فظهوره سبب بطونه، وكل ما تجاوز حده انعكس إلى ضده، ومن استبعد هذا الكلام لم يفهمه إلا بمثال، وهو أن الناظر إلى كاتب كلمة محكمة يستدل بها على قدرته وعلمه وحياته وسمعه وبصره استدلالاً يقينياً، ولم يكن له دليل إلى كلمة واحدة، وكل ذرة في السماوات والأرض شاهدة على نفسها بالحاجة إلى مدبر، فلو كانت الأشياء مختلفة في الشهادة؛ يشهد بعضها ولا يشهد البعض، لكان اليقين حاصلاً للجميع، ولكن لما كثُرت الشهادة حتى اتفقت بجملتها خفيت لشدة الظهور.\rومثاله: أن أظهر الأشياء نور الشمس المشرق على الأجسام الذي به يظهر كل شيء، فما به يظهر كل شيء كيف لا يكون ظاهراً، وقد أشكل ذلك على خلق كثير حتى قالوا: الأشياء المتلونة ليس فيها إلا ألوانها فقط من سواد وحمرة، فأما أن يكون مع اللون ضوء ونور مفارق للون فلا، وهؤلاء إنما نُبهوا على قيام الألوان بالمتلونات بالتفرقة التي يدركونها بين الظل وموضع\r"], [498, "النور، وبين الليل والنهار، ولو دام نور الشمس ولم يغب لتعذر عليه معرفة كون النور شيئاً موجوداً زائداً على الألوان، ولو تصور لله تعالى عدمٌ لانهدت السماوات وعُلم وجوده قطعاً).\rقال الإمام الحافظ - رضي الله عنه وعن آبائه -: هذا كلام لم يصح نقله عندي عن قائله، ولا يصح في نفسه، وبيان فساده في فصول، جِماعها سبعة:\rالأول: قوله في السؤال: والظاهر ما لا يُتمارى فيه، وقد بينا أن الظاهر على قسمين:\rأحدهما: لا مدخل فيه للتماري.\rوالثاني: للتماري فيه مداخل.\rوشرحنا أن الباري تعالى من الظاهر الذي يُتمارى فيه، فكيف سأل بما لا يصح وقرره وأجاب عنه؟\r"], [499, "وإنما ينبغي أن يعتنى بالأسئلة ولا يُسامَح فيها، ويبين مداخل الغلط في مبانيها، فكيف يصح أن يُجعل الظاهر بأجاً واحداً، أم كيف يستقيم الإقرار عليه لقائله؟\rالثاني: قوله في الجواب: إنما خفي مع ظهوره لشدة ظهوره.\rوهذا من أفسد كلام ينطق به ناظر، فإن الخفي إذا ظهر عُلم، وكلما ازداد ظهوراً زاد علماً للعالم به، فكأنه يقول: إن العلم إذا زاد حصوله كان أقرب إلى الجهل، والقوة إذا زادت رجعت إلى العجز، وأقرب من هذا أن يعكس عليه القول فيقال: إن الخفي إذا اشتد خفاؤه وتضاعف استبطانه صار ظاهراً، وهذا ما لا يقوله أحد.\rالثالث: قوله: والشيء إذا تجاوز حده انعكس إلى ضده.\rوهذا كلام فاسد لا ينطق به إلا غبي أو كانت ليشحن به رسالته، والأغبياء لا ينتقدون ما يقولون، والكتّاب مبنى رسائلهم على التخييلات.\rالرابع: قوله: إن كلمة واحدة محكمة يستدل بها على صفات كاتبها الكاملة؛ وعدّدها وصدق، ولكن مهما كثرت كلماتُه ظهرت صفاته، وكل ذرّة\r"], [500, "في المخلوقات شاهدة بالصانع المدبر، فلا جرم أن دلالتها على قدرها، ولكن اختلف العقلاء في الصانع لاختلافهم في مأخذ النظر، وزيغهم عن سداد الفِكَرِ وطول الطريق، فمنهم من لم ير العالم صنعة، فلذلك لم يقر بالصانع، ولا صح أن يكون للعالم عنده شهادة به، ومنهم من رأى أنه صنعة وأقر بالصانع مطلقاً، ثم كانت حاله في الشهادة بصفات الصانع وأحكامه على مقدار تولجه في بحار النظر، واستقلاله بالسباحة، والصبر على أهوال الشكوك، حتى يخرج إلى ساحل اليقين، أو عدم تولجه وتوقفه عنه أو هلكته عند الإعياء بطول السبح وتقامس الأمواج.\rولا يخفى بعد هذا أن من نجا وحصل له العلم بالأمر كله على وجهه أن كل ذرة تشهد عنده لربه، ولا يحصل له بنمو الشهادة إلا زيادة في الاستفادة، قال تعالى: {فَأَمَّا الَّذِينَ آمَنُوا فَزَادَتْهُمْ إِيمَانًا} [التوبة: 124]، وقال: {لِيَزْدَادُوا إِيمَانًا مَّعَ إِيمَانِهِمْ} [الفتح: 4].\rالخامس: التمثيل بنور الشمس؛ ومع التحقيق لا مثال فيه، فإن نور الشمس متفق عليه للمبصرين؛ لكونه ظاهراً محسوساً، فأما انبثاث الأشعة\r"], [501, "إلى سطوح الأجسام فباب يفتقر إلى نظر، وله طرق معلومة، ولا نفتقر إليه فيما نحن فيه بحال.\rالسادس: قوله: ولو لم تغب الشمس لتعذر عليه معرفة كون النور زائداً على الألوان؛ وهذا أمر ليس على ما زعمه، فإن معرفة الألوان والتمييز بينها علم بالحس، وأدرك بنور العقل ونور البصر ونور الشمس المفرقة بين الأسود والأبيض، والأحمر والأصفر، غابت الشمس أو لم تغب، ويعلم أن نور الشمس غير نور البصر، غير نور العقل، غير اللون، وأن كل واحد منها مغايرٌ لصاحبه، وإنما الذي يتبين بغيبة الشمس كون نورها سبباً لمعرفة التفرقة، كما أن تغميض الأجفان يعرِّف أن نور البصر سبب لمعرفة التفرقة أيضاً، كما أن عدم نور العقل بالجنون يعرِّف أن نوره سبب للإدراك المذكور أيضاً، وهذا باب غير ما نحن بصدده.\rالسابع: - وهو أطمُّه - قوله: ولو تصوِّر عدم الباري لانهدت السماوات وعلم قطعاً، وهذا قول عظيم الاستحالة يظهر ذلك فيه من ثلاثة أوجه:\r"], [502, "أحدها: قوله: (لو تصور عدم الباري)، وعدمه مستحيل، والمستحيل لا يقدَّر ليركَّب عليه حكم، وهذا فن من النظر دقيق.\rالثاني: قوله: (لانهدت السماوات)، وهذا فاسد، فإنه لو تصور عدم الباري لما انهدت السماوات خاصة، بل كان يبطل العالم كله من غير تخصيص شيء فيه.\rالثالث: قوله: (وعلم قطعاً)، فليت شعري إذا انهد العالم وبطل الخلق وعُدم الكل من كان الذي يتقدر علمه بالرب؟ فقد بان أن هذا كلام فاسد لا يثبت نقله عمن نسب إليه، ولا يصح معناه للناظر فيه.\rالفصل الرابع: في التنزيل\r"]], "pg": [495, 502]}, "561.270": {"x": [[502, "المنزلة العليا للرب\rفي كونه ظاهراً له فيها أحكام يختص بها، وهي ثلاثة:\rالأول: أنه يصح إدراكه بالدليل قطعاً.\rالثاني: أنه المُفزَع عند الشدائد، كقوله: {ثُمَّ إِذَا مَسَّكُمُ الضُّرُّ فَإِلَيْهِ تَجْأَرُونَ} [النحل: 53]، وقوله: {أَمَّن يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ} [النمل: 62].\r"], [503, "الثالث: أنه يظهر على ما لا يظهر عليه العبد.\rالمنزلة السفلى للعبد\rأن يكون ظاهراً في العلم لقوله: {يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا مِنكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ} [المجادلة: 11]، ظاهراً بالعمل لقوله: {إِلَّا الَّذِينَ تَابُوا وَأَصْلَحُوا وَبَيَّنُوا} [البقرة: 160].\r"], [504, "القول في اسم الباطن\rوهو الثاني والثلاثون من أسماء التنزيه، فيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [502, 504]}, "561.271": {"x": [[504, "ورد به القرآن، قال تعالى: {هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ} [الحديد: 3]، ووردت به السنة، كان النبي صلى الله عليه وسلم يقول في دعائه: (اللهم أنت الأول فليس قبلك شيء، وأنت الآخر فليس بعدك شيء، وأنت الظاهر فليس فوقك شيء، وأنت الباطن فليس دونك شيء، اقضِ عني الدين، وأغنني من الفقر)، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [504, 504]}, "561.272": {"x": [[504, "الباطن في اللغة هو: الخفي، كبطن الإنسان، وبطن الأرض ما سفُل منها وما خفي.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [504, 504]}, "561.273": {"x": [[504, "وفيه ست مسائل:\r"], [505, "المسألة الأولى: في سرد أقوال العلماء فيه\r"]], "pg": [504, 505]}, "561.274": {"x": [[505, "ولهم فيه ست عبارات:\rالأول: أنه المحتجب عن أبصار الخلق.\rالثاني: أنه الذي لا يتوهم.\rالثالث: أنه المطلع على البواطن.\rالرابع: أنه الرحيم.\rالخامس: أنه العالم.\rالسادس: أنه خالق الباطن.\rالمسألة الثانية: في تحقيق هذه الأقوال\r"]], "pg": [505, 505]}, "561.275": {"x": [[505, "قد قدمنا شرحه لغة، والحقيقة متفقة مع هذا الاسم في اللغة، لأن الباطن والخفي لفظان متطابقان، فمن قال: إنه خفي، بمعنى أنه محتجب عن أبصار الخلق، فصدق، وكذلك صدق من قال: إنه لا يُتوهم، لكن الحجاب الأول يجوز أن يرتفع، فنراه سبحانه، وحجاب التوهم لا يصح ارتفاعه.\rوأما من قال: إنه العالم بالباطن، فظاهر صحيح، وهو أولى ممن قال: إنه العالم مطلقاً، وإن صح فيه إطلاق لفظ العالِم، على معنى أنه إذا علم الباطن فهو بالظاهر أعلم.\r"], [506, "وأما من قال: إنه الرحيم، فلا تقتضيه لغة ولا حقيقة.\rوأما من قال: إنه خالق الباطن، فمجاز بعيد لا تقتضيه اللغة ولا المعنى.\rالمسألة الثالثة: في المختار\r"]], "pg": [505, 506]}, "561.276": {"x": [[506, "لما ثبت اتفاق اللغة والحقيقة في اسم الباطن، فحقيقة البطون فيه سبحانه أنه لا يُتوهم، ويليه أنه لا يُرى، فدون الله سبعون حجاباً من النور.\rفإن قيل: كيف يكون حجابه النور وهو سبب الظهور؟\rالجواب: أنه إنما يكون سبب الظهور إذا خلقه للمتنور به، وأزال علته عنه حتى يستنير به، فمعلوم أن:\rفي كل شيء له آيةٌ ... تدل على أنه واحدٌ\r{وَكَأَيِّن مِّنْ آيَةٍ فِي السَّمَاوَاتِ وَالْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ} [يوسف: 105].\rوبيانه:\rأن نور البصر تدرَك به مدرَكات معلومة، لكنه نور تحجبه الظلمة، فيعضد بأقوى منه؛ وهي النار، فيتعاضدان وتنكشف بهما موجودات، وتعضد بأقوى منها؛ وهي نور الشمس، فتنكشف موجودات، ولكن بينهما بون، فإن نور الشمس أقوى من النار، ولذلك تخفى فيه، والنار أقوى من نور البصر، ولذلك ينكشف أكثر منه، فهذان حجابان من النور، والثالث أعظم، لكنه أبهم،\r"], [507, "فإذا كان نور الشمس معيناً لنور البصر على الإدراك ثم لا يمكن أن يدركه، وهو الحجاب الثاني، فكيف له بأن يخترق سبعين حجاباً فيرى الله، ولكن الآخرة دار قوة وكرامة.\rالمسألة الرابعة:\r"]], "pg": [506, 507]}, "561.277": {"x": [[507, "قال علماؤنا - رحمة الله عليهم -: إن الواو في قوله: {هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ} [الحديد: 3]، زائدة، والأول هو الآخر، والظاهر هو الباطن، والأول الآخر هو الظاهر الباطن، وكذلك على التقسيم، كل واحد منها هو الآخَر، ومجموعها إلا واحد هو الآخَر، وهذا صحيح، فإن الواو لم تجئ لعطف متغايرات بعضها على بعض، فالباري تعالى هو الأول بمعنى الأولية، وهو الآخر بعينه بمعنى الآخرية، وهو بعينه الظاهر بآياته، وهو بعينه الباطن عن مخلوقاته.\rوقد ضرب العلماء لذلك مثالاً، قالوا: إن الروح موجودة بالجسم، تظهر بأفعالها حتى لا يمكن إنكارها، وتخفى بذاتها حتى لا تُعلم كيفيتها، فإن طلبها أحد بالحس لم يجدها، وإن أراد إنكارها صدمته أفعالها فصدفته عن إنكارها، فيا عجباً لمن ينكر الباري لأجل خفائه مع ظهور أفعاله ويقر بالروح\r"], [508, "في جسده، وهذه حجة لله في أرضه لوجوده على خلقه، قال سبحانه: {وَفِي أَنفُسِكُمْ أَفَلَا تُبْصِرُونَ} [الذاريات: 21].\rالمسألة الخامسة:\r"]], "pg": [507, 508]}, "561.278": {"x": [[508, "قالت الجهمية: لا يصح لكم القول بأنه الآخر، فإنكم تزعمون أن نعيم الجنة وعذاب النار لا آخر لهما، وإنما يصح أن يكون الباري الآخر إذا قلتم إن كل شيء يفنى وهو تعالى يبقى، فيكون حينئذ الآخر حقيقة.\rالجواب: أنا نقول:\rلا يمتنع في مقتضى العقل موجودات لا نهاية لها، لكن تجوز عليها النهاية، والباري تعالى موجود لا تجوز عليه النهاية، ولا يدركه فناء، فيكون انفراده في الآخرية باستحالة الفناء، ويكون انفراده في الأولية باستحالة الابتداء، ودوام وجود الموجودات بإدامته، فلو شاء لقطعها ففنيت، وأنه شاء إدامتها فدامت، وأخبرنا بذلك فصدَّقْنا به لجوازه وتحقيق المعنى فيه.\rالمسألة السادسة\r"]], "pg": [508, 508]}, "561.279": {"x": [[508, "قال بعض علمائنا: قول النبي صلى الله عليه وسلم: (نحن الأولون الآخرون)، أراد بذلك: نحن الأولون في حكم النبوءة، والآخرون في إظهار البعثة\r"], [509, "والرسالة، لأنه روي أنه قيل له: (متى كنت نبياً، قال: وآدم بين الروح والجسد).\rقال الإمام الحافظ - رحمه الله ورضي عنه -: ليس كذلك روي الحديث، إنما نصه: (نحن الآخرون السابقون، بيد أنهم أوتوا الكتاب من قبلنا وأوتيناه من بعدهم، فهذا اليوم الذي اختلفوا فيه، فهدانا الله له، فغداً لليهود، وبعد غد للنصارى)، وأراد بقوله: (نحن الآخرون) زماناً، (السابقون) ثواباً ومكاناً، لقوله تعالى: {وَالسَّابِقُونَ السَّابِقُونَ. أُولَئِكَ الْمُقَرَّبُونَ} [الواقعة: 10 - 11].\rيوضحه قوله صلى الله عليه وسلم: (مثلكم ومثل من خلا من الأمم قبلكم كمثل رجل استأجر أجراء فقال: من يعمل لي إلى نصف النهار على قيراط؟ فعملت اليهود، ثم قال: من يعمل لي بقية النهار على قيراط؟ فعملت النصارى إلى العصر، ثم قال: من يعمل لي إلى مغرب الشمس؟ فعملنا فأوتينا قيراطين)، الحديث.\r"], [510, "الفصل الرابع: في التنزيل\r"]], "pg": [508, 510]}, "561.280": {"x": [[510, "المنزلة العليا للرب\rفي هذا الاسم أحكام يختص بها ثلاثة:\rالأول: أنه لا يدرَك باللمس والشم والذوق.\rالثاني: لا يُقصد بالضرر.\rالثالث: أنه لا يقف دون الخفيات بعلم.\rوقد قال بعض أهل المعرفة في الأول: إن البداية إليه، وفي الآخر: إن التناهي إليه، وفي الظاهر: إن إليه تسهيل الأحوال، وفي الباطن: إن به القصودَ والضمائر.\rالمنزلة السفلى للعبد\rوله في ذلك حكمان:\rأحدهما: إخلاص التوحيد للرب.\rالثاني: سلامة النية عن الشوب.\r"], [511, "القول في اسم اللطيف\rوهو الاسم الثالث والثلاثون من أسماء التنزيه، وفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [510, 511]}, "561.281": {"x": [[511, "هو اسم ورد به القرآن والسنة، قال تعالى: {وَهُوَ اللَّطِيفُ الْخَبِيرُ} [الأنعام: 103]، وقال: {اللَّهُ لَطِيفٌ بِعِبَادِهِ} [الشورى: 19]، وقال: {إِنَّ رَبِّي لَطِيفٌ لِّمَا يَشَاءُ} [يوسف: 100]، وورد في حديث أبي هريرة المفسر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [511, 511]}, "561.282": {"x": [[511, "قال علماؤنا: له في اللغة ثلاثة معان:\rأحدها: أن اللطيف هو: العارف بدقائق الأمور.\rالثاني: أن اللطيف هو: ما دق وصغُر من الأجزاء والأجسام.\rالثالث: أن اللطيف هو: المحسن.\rيقال: لطَف ولطُف وتلطَّف بمعنى واحد.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [511, 511]}, "561.283": {"x": [[511, "وفيه خمس مسائل:\r"], [512, "المسألة الأولى: في حقيقة اللطف\r"]], "pg": [511, 512]}, "561.284": {"x": [[512, "نقول: إن الذي استقر عليه منتهى النظر، أن اللطف هو: الخفاء، وكل شيء لطيف فهو: خفي، وإليه يرجع قولهم: لطف الشيء يلطف إذا دق وصغر، ولطف يلطف: إذا أوصل إليك ما تحب من حيث لا تعلم، قال الله تعالى: {وَقَدْ أَحْسَنَ بِي إِذْ أَخْرَجَنِي مِنَ السِّجْنِ وَجَاءَ بِكُم مِّنَ الْبَدْوِ مِن بَعْدِ أَن نَّزَغَ الشَّيْطَانُ بَيْنِي وَبَيْنَ إِخْوَتِي إِنَّ رَبِّي لَطِيفٌ لِّمَا يَشَاءُ} [يوسف: 100]، وقال: {اللَّهُ لَطِيفٌ بِعِبَادِهِ يَرْزُقُ مَن يَشَاءُ} [الشورى: 19]، معناه: الإتيان بالإحسان من الوجوه الخفية التي لا تظهر إلا له، فما يتعدى منه هو الذي لا يتعدى من الصغر والخفاء.\rالمسألة الثانية: في التركيب\r"]], "pg": [512, 512]}, "561.285": {"x": [[512, "إذا قلنا: إن اللطف هو: الخفاء، فقد تقدم بيانه في اسم الباطن، فهو تعالى خفي عن الأوهام، واضح بالإعلام، لا يدرَك بكيفية ولا كمية ولا أينية، وإنما يُعلم بالأدلة الإلهية.\rوأما إن قلنا: إنه: الموصل للإحسان والنافع من حيث لا يُعلم، فذلك بالحقيقة هو الله تعالى، وهذا من صفات الأفعال، وقد بينا في كتب الأصول أن من لطفه بعباده خلقه القدرة على الطاعة، ولا يعلم الأنام أنها بها، وتيسيره أسباب الذكاء والهداية، وإيصال المنافع والأرزاق إلى العباد، فلله ألطاف خفية كما له نعم باطنة وجلية.\r"], [513, "المسألة الثالثة\r"]], "pg": [512, 513]}, "561.286": {"x": [[513, "قال الأستاذ أبو إسحاق: (إن ذلك من صفات الأفعال، وإن معنى كونه لطيفاً أنه يفعل الفعل الدقيق، وعليه يدل قولهم: فلان لطيف الكف؛ إذا كان حاذقاً في الصنائع المشكِلة).\rوهذا وهم، فقد بينا احتماله للوجهين، وأنه من صفات التنزيه بالمعنى الظاهر الذي يتفق فيه مع معنى اسم الباطن، وأنه محتمل لمعنى الفعل بما يغني عن إيضاحه.\rالمسألة الرابعة\r"]], "pg": [513, 513]}, "561.287": {"x": [[513, "قال بعض علمائنا: إن قوله: لطيف، يرجع إلى العلم، لأنه يستعمل في العلم بدقائق الأمور ومشكلاتها، يقال: فلان لطيف الكف: إذا كان حاذقاً في صناعته.\rوهذا لا يصح، لأن العرب لم تنطق به، ولا ورد في مقاطعها، وإنما هذا كلام العرف العامي، ولا ينبني عليه حكم، وإنما يصح ما قدمناه في معناه.\rالمسألة الخامسة\r"]], "pg": [513, 513]}, "561.288": {"x": [[513, "قال علماؤنا: لطف الله مختص ببعض الخلق غير عام فيهم، وقالت المعتزلة: لطفه عام في جميع الخلق، وقد مهدناه في الأصول، والمقدار الذي\r"], [514, "يُحتاج إليه ها هنا، أن قولنا في وصفه: بأنه لطيف يحتمل التنزيه والتقديس، ويحتمل أن يكون من صفات الأفعال، فإن كان من صفات الأفعال فتعلقه مخصوص ببعض الخلق كما بيناه في كتاب الاعتقاد.\rالفصل الرابع: في التنزيل\r"]], "pg": [513, 514]}, "561.289": {"x": [[514, "إذا علمتم معنى اللطف واللطيف فللباري تعالى في ذلك أحكام سبعة يختص بها:\rالأول: أنه لا يُنال بوهم.\rالثاني: أنه يختص بدقائق الأفعال؛ كخلق الجنين في بطن أمه.\rالثالث: إيصاله النفع من حيث لا يُعلم.\rالرابع: تكليفهم دون الطاقة، لقوله: {وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ} [الحج: 78].\rالخامس: أنه أعطاهم فوق الحاجة.\rالسادس: إخراجه اللبن من الضَّرع من بين فرث ودم.\rالسابع: - وهو أغرب منه - تخليص الإيمان من الذنوب، ووجوه ذلك لا تُحصى، وفي هذا أصل يُغني عن الاستقصاء.\rالمنزلة السفلى للعبد\rأن يعلم لطف الله بعباده فيَرفُق هو بهم قولاً وفعلاً، ويعلم أن ربه لا يُتوهم.\r"], [515, "ص 516\r"], [516, "القول في صفات الإثبات\r"], [517, "ص 518\r"], [518, "قد نجز القول - بمعونة الله وحمده - في بيان صفات التنزيه، مع ما دخل فيها وارتبط بها وافتقرنا في بيانها إليه، وقد تعين بعدُ الشروع في بيان صفات الإثبات؛ وهي على ضربين:\rمنها: صفات ترجع إلى الذات، بمعان تدل عليها قائمة بها، وأحكام توجبها لها.\rومنها: صفات أفعال.\rفنبدأ أولاً بصفات الذات الدالة على المعاني القائمة بها، ثم نرجع بعدُ إلى بيان صفات الأفعال، فنقول:\rقد علمنا فيما سلف ترتيب معرفة الله سبحانه بالدلائل، وما يقتضيه سابقاً ومتأخراً عن معرفته، وعلى ذلك المنوال ننسج هذا البيان.\rولما كانت القدرة من أول المدلولات بالأدلة وجب التقدم بها.\r"], [519, "ص 520\r"], [520, "القول في أسامي القدرة:\rوفيها أحد عشر اسماً.\r"], [521, "ص 522\r"], [522, "القول في اسم القادر\rوهو الأول، وفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [514, 522]}, "561.290": {"x": [[522, "قد ورد به القرآن، قال الله تعالى: {قُلْ هُوَ الْقَادِرُ عَلَى أَن يَبْعَثَ عَلَيْكُمْ} [الأنعام: 65]، ووردت به السنة في حديث أبي هريرة المفسر وغيره، وقال النبي صلى الله عليه وسلم لأبي ذر وقد شاهد سُطاه على فتاه: (يا أيها القدير الله أقدر منك)، وأجمعت عليه الأمة، وكثر تَرداده في الشريعة اسماً وفعلاً لعظم خطره، وأنه أم أسماء الصفات.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [522, 522]}, "561.291": {"x": [[522, "هذا الاسم مشهور في اللغة والاعتقاد، والقادر عند العرب: كل من كان على صفة يتأتى معها منه الفعل، فمن كانت ذاته على هذه الصفات سمته قادراً قوياً مستطيعاً، والاستطاعة والقوة والقدرة بمعنى واحد، وقد يكون القادر فاعلاً من قدر أي: علم، ومن قدر أيضاً أي: قلَّل، على ما يأتي بيانه في باب العالِم، لكن لم يأت من هذين اسم، وإنما وردت أفعالاً، والاسم إنما ورد من: قدَرتُ على الشيء، من القدرة، وهي: القوة.\rالفصل الثالث في شرحه حقيقة وعقداً\r"]], "pg": [522, 522]}, "561.292": {"x": [[522, "فيه أربع مسائل:\rالمسألة الأولى: [الاختلاف في صفة القدرة، هل هي صفة زائدة على "]], "pg": [522, 522]}, "561.293": {"x": [[522, "الذات أم لا؟]\rهذا اسم اتفقت فيه اللغة والحقيقة، لكن اختلف الناس في القدرة؛ هل هي صفة زائدة على ذات القادر أو ليست بمعنى زائد على الذات؟\rوقد ساعدونا على ذلك في المخلوق وهو دليلنا، وقد ذكر الله أن له قوة، كما ذكر أن له عِلماً، فما أثبته لنفسه لأي شيء ننفيه عنه؟ وخبره حق، ودليل العقل قد دل عليه.\rوقال جماعة من علمائنا: القدرة عبارة عن معنى يوجد به الشيء متقدراً بتقدير الإرادة والعلم، واقعاً على وفقهما، ثم جهة الوجود تختلف إلى خلق مجرد، وإلى خلق وكسب معه.\r"], [523, "المسألة الثانية: في تركيب المعنى الاعتقادي على الحقيقي\r"]], "pg": [522, 523]}, "561.294": {"x": [[523, "قال علماؤنا: الباري تعالى هو القادر، على معنى: أن له صفة زائدة على ذاته، يتأتى معها وجود الموجود على قدر تعلق الصفات، وهي العلم والإرادة والكلام، فعلم وأراد، وقال: كن، فكان، متقدراً بصفة هي القدرة والقوة والاستطاعة، من شأنها وقوع الموجود على مقتضى هذه الصفات الثلاث، وهي العلم والإرادة والكلام، وهو القوي سبحانه على هذا المعنى والتركيب بعينه.\rوهذا غرض عظيم، وغور عميق، لا يقدره قدره، ولا يحقق أمره إلا العلماء، وقد مهدناه في كتاب المقسط، ويكفي فيه الآن أن تعلموا أن قولنا: عالم، كقولنا: له علم، لا فرق عند العرب التي نزل القرآن بلسانها بينهما، لا سيما وقد بينه بقوله تعالى: {أَنزَلَهُ بِعِلْمِهِ} [النساء: 166]، فإذا عضدتْه اللغة وجاء به القرآن فأي دفع فيه لموحِّد.\rالمسألة الثالثة: في وجه تعلق القدرة بالمقدور مع سائر الصفات\r"]], "pg": [523, 523]}, "561.295": {"x": [[523, "وهو أعظم مما تقدم وأمد إطناباً، قد مهدناه في كتاب المقسط، ونشير الآن إليه بنكتة، إذ لا نرى أن نُخليَكم منه لعظيم فائدته، فنقول:\r"], [524, "معلوم أن العلم لا يكفي وجوده للخلق، لأنه يتعلق بالموجود والمعدوم، فإن تعلق العلم بالمعلوم مطلقاً فهو علم، وتتعلق الإرادة بحال من أحواله المعلومة فهو القدَر، فإذا تعلق به من الكلام قوله: كن، والقائل بصفة من تتأتى منه الكينونة كان على كل حال، وعلى هذا يُحمل قوله: {فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ} [الأنبياء: 87]، أي لن نعلم فيه نفوذ ذلك بالقدرة على الوجه الذي ينفذ معه كل مقدور ويوجد كل موجود.\rالمسألة الرابعة: في فصل بديع\r"]], "pg": [523, 524]}, "561.296": {"x": [[524, "اعلموا - علمكم الله - أنا إذا سمينا الباري باسم أو وصفناه بصفة ثم بنينا له منه بناءً مبالغةً في اللغة كقدير وأقدر في قادر، أو عليم وأعلم في عالم، فإن المبالغة في حقه ليست على جهة المبالغة في حقنا، لأن المبالغة في حقنا إنما ترجع إلى كثرة العلوم والقُدَرِ، والمبالغة في حقه ترجع إلى وجهين:\rأحدهما: كثرة المقدورات والمعلومات، وكذلك في كل صفة كالسمع والبصر ونحوهما، قاله علماؤنا - رحمة الله عليهم -، وشرحه عندهم أن علم الباري تعالى علِمنا كونَه واحداً شرعاً، وقد كان من الجائز أن يكون له بعدد كل معلوم علم، لكن الأمة أجمعت على اتحاده.\r"], [525, "والصحيح عندي أن اتحاده عُلم عقلاً وشرعاً لأدلة مهدناها في كتب الأصول، جملتها أن تعدد علم المخلوق إنما كان لكونه حادثاً له أول، عرضاً لا يبقى، معرضاً للآفات؛ لجهل يعقُبه، وذهول يعترضه، فأما العلم المقدس عن ذلك كله فواجب اتحاده.\rالوجه الثاني: استحالة الآفات على قدرته وعلمه، فإنه لم يسبق عدمٌ لقدرته وعلمه، ولا يعقبها فناء، وقدرة الخلق وعلمهم ناقصة بالوجهين، لأنها منحصرة التعلق، معرضة لآفتي العدم أولاً، والفناء آخراً، متحقَّقٌ ذلك فيهما.\r"], [526, "الاسم الثاني: القدير\rوهو اسم ورد به القرآن، قال الله تعالى: {وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ} [المائدة: 120]، ووردت به السنة في حديث أبي هريرة وغيره، وهو فعيل من قدر، كما أن قولنا: قادر، فاعل من قدر، وقد تقدم بيانه، وقد يحتمل أن يكون قديرٌ مُقْدِراً؛ فعيل بمعنى مُفْعِل، كقوله: عذاب أليم بمعنى مؤلم، وذلك كثير في أسمائه تعالى.\r"], [527, "الاسم الثالث: المقتدر\rوفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [524, 527]}, "561.297": {"x": [[527, "وقد ورد به القرآن، قال تعالى: {وَكَانَ اللَّهُ عَلَى كُلِّ شَيْءٍ مُّقْتَدِرًا} [الكهف: 45]، وقال تعالى: {عِندَ مَلِيكٍ مُّقْتَدِرٍ} [القمر: 55]، ووردت به السنة في حديث أبي هريرة المفسر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [527, 527]}, "561.298": {"x": [[527, "قال بعض علمائنا: (المقتدر هو: التام القدرة الذي لا يمتنع عليه شيء، ولا يحتجز عنه بمنعة وقوة، فإن قولنا: اقتدر، أبلغ من قدر، فالقدرة مطلقة، والاقتدار: القدرة التامة)، وهذه دعوى لا تشهد لها لغة ولا معنى.\rوالصحيح أن مقتدراً: مفتعِل من قدر، كمقتدر ومستقدر فيه، وقولنا: افتعل، يأتي على أربعة أوجه في اللغة:\r"], [528, "الأول: بمعنى اتخذت فعلاً، كقولك: اشتوى، وفي الحديث: (أن نفراً من عُكْلٍ اجتووا المدينة)، وهو منه مأخوذ.\rالثاني: بمعنى: تصرف، كقولنا: اكتسب، من قولنا: كسب.\rالثالث: بمعنى: فعل، لا زيادة فيه، كقولنا: قرأ واقترأ.\rالرابع: بمعنى تفاعل، كقولنا: اقتتل القوم.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [527, 528]}, "561.299": {"x": [[528, "وفيه مسألتان:\rالمسألة الأولى:\r"]], "pg": [528, 528]}, "561.300": {"x": [[528, "قال علماؤنا: إذا ثبت معنى اقتدر وانقسامه، فلا يصح وصف الباري به بمعنى اتخذ، لأن الاتخاذ لا يكون إلا في المحدَث، والقدرة قديمة، ويصح وصفه بقولنا: اقتدر، بمعنى: تصرف، أي كان منه عمل بحكم القدرة؛ وهو الإيجاد والاختراع، فيرجع إلى الخالق، وسيأتي بيانه.\r"], [529, "ولا يصح وصفه منه بمعنى فَاعَلَ، لأنه اشتراك بين اثنين في الفعل، ولا شريك لله عندنا في شيء، وإنما يلزم ذلك القدرية الذي يزعمون أن العباد شركاؤه في القدرة. ويصح وصفه بأنه قدر، بمعنى: اقتدر، لأنه لا زيادة فيه.\rالمسألة الثانية: [في أن التاء في مقتدر، هي تاء التفرد والاخت"]], "pg": [528, 529]}, "561.301": {"x": [[529, "صاص]\rأما قولهم: اقتدر بمعنى تصرف، فتكون هذه هي تاء التصرف، فلا يجوز ذلك في حق الله، لأن التصرف معناه: اكتساب الفعل، وذلك غير صحيح في وصفه، ولكن نقول:\rإنه إن كان لا يصح أن يكون المعنى به اكتساب الفعل في حق الإله، فالمعنى فيه كما بيناه في اسم المتكبر أن هذه التاء هي تاء التفرد والاختصاص، فالمقتدر عبارة في حقه تعالى عن: المنفرد بالقدرة المتخصص بها، وهو الله وحده، لأن قدرة العبد له، هو أعطاها، وهو يسلُبها، وإنما تضاف إلى العبد إضافة محل، وهي مضافة إلى الله تعالى إضافة مِلك.\r"], [530, "الاسم الرابع: القوي\rفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [529, 530]}, "561.302": {"x": [[530, "وقد ورد به القرآن والسنة اسماً ووصفاً، قال تعالى: {الْقَوِيُّ الْعَزِيزُ} [هود: 66]، وقال: {ذُو الْقُوَّةِ الْمَتِينُ} [الذاريات: 58]، وورد مفسراً في حديث أبي هريرة، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [530, 530]}, "561.303": {"x": [[530, "القوة في اللغة هي: القدرة، مأخوذة من طاقات الحبل، وجمعه: قُوىً، يقال: فتل فلان حبله على أربع قوى، يعني: على أربع طاقات.\rالفصل الثالث: في حقيقته وعقده\r"]], "pg": [530, 530]}, "561.304": {"x": [[530, "وفيه أربع مسائل:\rالمسألة الأولى: في تحقيق اللفظة\r"]], "pg": [530, 530]}, "561.305": {"x": [[530, "وهي عندي القدرة بعينها، وهي أسماء مختلفة ترجع إلى مسمى واحد، ومن قال: إن القدرة سميت قوة مأخوذة من طاقات الحبل، فإنما سمي ما في الحبل قوى تشبيهاً بالقوة، فهو مجاز فيه، حقيقة في القوة، ولكن يدل - والله\r"], [531, "أعلم - على أن القوة عندهم قدرة زائدة متناهية، ولذلك شبهوا طاقات الحبل إذا تضاعفت بها.\rالمسألة الثانية: في سرد أقوال العلماء\r"]], "pg": [530, 531]}, "561.306": {"x": [[531, "للعلماء فيه ثلاث عبارات:\rالأولى: القوي: القادر.\rالثانية: التام القدرة.\rالثالثة: أن القوي بمعنى: المقوّي، فعيل بمعنى مفعل، كما قيل في البصير والسميع والكريم.\rالمسألة الثالثة: في تحقيق هذه العبارات\r"]], "pg": [531, 531]}, "561.307": {"x": [[531, "إذا قلنا: إن القوي: القادر، فقد تقدم بيانه؛ وإن كان: التام القدرة فليس التمام والكمال إلا لله؛ وإن كان بمعنى: المقوي، الذي يعطي عباده القوة، فمن المعطي إلا الله للقوة وغيرها؛ وعلى المعنيين الأولين هو من صفات الذات، وعلى الثاني هو من صفات الأفعال.\rالمسألة الرابعة: في المختار\r"]], "pg": [531, 531]}, "561.308": {"x": [[531, "الذي يصح عندي أن القوي هو: المتناهي القدرة، بدلالة اللغة كما قدمنا، وهو اختيار الأستاذ أبي بكر، قال: (القوي هو القادر العظيم المقدور؛ ومن تمام قدرته أنه الذي يعطيها للخلق).\r"], [532, "الاسم الخامس: المُقيت\rفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [531, 532]}, "561.309": {"x": [[532, "هو اسم من أسمائه الحسنى ورد به القرآن، قال الله تعالى: {وَكَانَ اللَّهُ عَلَى كُلِّ شَيْءٍ مُّقِيتًا} [النساء: 85]، وورد في حديث أبي هريرة المفسر، فذكر المُقيت.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [532, 532]}, "561.310": {"x": [[532, "للعلماء فيه ثلاثة أقوال:\rالأول: ما روي أن ابن عباس سئل عنه فقال: هو المقتدر، ألم تسمع قول الشاعر:\rوذي ضِغن كففتُ النفس عنه ... وكنتُ على مَساءته مُقيتاً\rالثاني: أنه الشاهد، قال الشاعر:\r"], [533, "ألي الفضل أم علي إذا حو ... سبتُ إني على الحساب مقيتُ\rأي: شاهد.\rالثالث: أنه الذي يقوم بأقوات الخلق، قاله الفراء: يقال: قاته وأقاته: إذا أعطاه قوته، وفي الحديث: (كفى بالمرء إثماً أن يضيِّع من يقوت)، ويروى: من يقيت، والمشهور فيه: من يعول.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [532, 533]}, "561.311": {"x": [[533, "وفيه ثلاث مسائل:\rالمسألة الأولى: [في ترجيح السماع على النظر في معنى مقيت]\r"]], "pg": [533, 533]}, "561.312": {"x": [[533, "لا خفاء بما قدمنا أن اللفظ الواحد يكون له في اللغة معنيان وأكثر، ولكن إذا تأملت هذا الاسم وجدت فيه غريبةً من اللغة، وهي أن اشتقاقه يُعطي أنه من القوت، وقد قال علماء اللسان: إنه بمعنى القادر، وليس فيه على هذا أكثر من السماع، فلو رجعنا إلى الاستقراء وتتبع مسالك النظر لجعلناه في موارده كلها بمعنى القوت، ولكن السماع يقضي على النظر، ولا بد من إبداء صفحة ذلك النظر، فنقول:\r"], [534, "حقيقة المقيت: معطي القوت، والقوت هو: ما به قِوام كل شيء، يقال: فلان مقيت على البناء، أي: يعطيه ما يكفيه من آلات وَمَرَمَّةٍ، وهذا معنى قوله: {وَكَانَ اللَّهُ عَلَى كُلِّ شَيْءٍ مُّقِيتًا} [النساء: 85]، معناه: يقابله بما يصلح له، وقوله:\rإني على الحساب مقيت\rمثله، معناه: أقابله من تطفيف ووفاء بما ينبغي، وقوله:\rوكنت على مساءته مقيتاً\rأي: مقابلها بما يصلح من الجزاء.\rالمسألة الثانية: في تركيب المعنى الاعتقادي على اللغوي\r"]], "pg": [533, 534]}, "561.313": {"x": [[534, "إذا قلنا: إن المقيت هو: القادر، فقد تقدم بيانه.\rوإن قلنا: إنه معطي القوت، فهو اسم للوهاب والرزاق، وسنذكره معه، ونبين التفصيل بينهما والمجتمِع لهما.\rوعلى القول بأنه: القادر، يكون من صفات الذات، وعلى القول بأنه: معطي القوت يكون من صفات الأفعال.\rالمسألة الثالثة:\r"]], "pg": [534, 534]}, "561.314": {"x": [[534, "إذا كان المقيت هو: معطي القوت - وهو أحد معنييه - فلكل مخلوق قوت، وخاصة الأبدان، فإن قوتها المأكول والمشروب على اختلاف\r"], [535, "أنواع ذلك وطرق اجتلابه، وكذلك الأرواح؛ فإن قوتها العلوم، وقوت الملائكة التسبيح، فلولا المأكول والمشروب لم يبق جسم، ولولا العلم لم تَغن روح، والتسبيح شغل الملائكة وعملهم.\rالفصل الرابع: في التنزيل\r"]], "pg": [534, 535]}, "561.315": {"x": [[535, "أما إذا كان بمعنى القادر فقد تقدم تنزيله، وأما إذا كان بمعنى معطي القوت فتنزيله في الوهاب والرزاق، والله أعلم.\r"], [536, "الاسم السادس: المتين\rوفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [535, 536]}, "561.316": {"x": [[536, "وقد ورد به القرآن والسنة، وأجمعت عليه الأمة، قال الله تعالى: {ذُو الْقُوَّةِ الْمَتِينُ} [الذاريات: 58]، وورد في حديث أبي هريرة مفسراً، واختلف في ضبطه، فمنهم من ضبطه المتين بالتاء المعجمة؛ باثنتين من فوقها، وبعدها ياء معجمة باثنتين من تحتها، وردّه إلى القوي، ومنهم من ضبطه بباء معجمة، بواحدة من تحتها، وبعدها ياء معجمة؛ باثنتين من تحتها، ورده إلى الكلام، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [536, 536]}, "561.317": {"x": [[536, "قال علماؤنا - رحمة الله عليهم - فيه قولان:\rأحدهما: أنه القوي.\rالثاني: أنه شديد القوة، تقول العرب: هذا أمتن من هذا: أي أصلب منه وأقوى، ومنه سمي الصلب متناً، لأن القوة فيه أكثر.\r"], [537, "الفصل الثالث: في حقيقته وعقده\r"]], "pg": [536, 537]}, "561.318": {"x": [[537, "وفيه أربع مسائل:\rالمسألة الأولى:\r"]], "pg": [537, 537]}, "561.319": {"x": [[537, "لعلمائنا فيه عبارتان، وهي اللتان تقدمتا في فصل اللغة، وزاد بعضهم ثالثة فقال: هو الذي لا تلحقه مشقة.\rفإن قلنا: إنه القوي، فقد تقدم بيانه.\rوإن قلنا: إنه الشديد القوة، فذلك يرجع إلى كثرة المقدورات في قول علمائنا لا إلى كثرة القُدَر.\rوإن قلنا: إنه الذي لا تلحقه مشقة، فقد بين ذلك بقوله: {وَلَقَدْ خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ وَمَا مَسَّنَا مِن لُّغُوبٍ} [ق: 38].\rالمسألة الثانية:\r"]], "pg": [537, 537]}, "561.320": {"x": [[537, "قال علماؤنا: لولا ورود الشرع بتسمية المتين ما سميناه به، فإنه بمطلق اللغة يوجب الصلابة، وذلك عنه منفي، ومنهم من قال: إنما المراد به تأكيد الوصف بالقوة، ولذلك أتبع في قوله: {ذُو الْقُوَّةِ} المتين، ومن الناس من قال: إنما سمي به اتساعاً ومجازاً.\r"], [538, "المسألة الثالثة: في المختار\r"]], "pg": [537, 538]}, "561.321": {"x": [[538, "نقول: لولا ورود الشرع بكل ما ورد من أسمائه ما سميناه به على أحد القولين، وعلى القول الثاني: يطلق ما لا إيهام فيه، ولا إيهام في المتين.\rوأما الصلابة فإنها عبارة عن تراكم الأجزاء حتى لا يؤثر في الشيء الصلب إلا بعد جهد، فلو جاء في وصفه على نحو ما جاء المتين لما كان في ذلك إيهام.\rالمسألة الرابعة: [في تحقيق المروي في خبر الأسماء، هل هو المت"]], "pg": [538, 538]}, "561.322": {"x": [[538, "ين أم المبين؟]\rروي في حديث أبي هريرة (المَتين)، واختلف فيه كما بيناه من قبل، هل هو بتاء معجمة باثنتين من فوقها أم بباء معجمة بواحدة من تحتها؟\rقال بعضهم: والصحيح أنه المبين بالباء، وكذلك جاء من طريق عبد العزيز بن الحُصين من حديث أبي هريرة، وإنما قلنا: إنه أصح، لأن المتين قد أفاده القوي، فكان المبين لفائدة زائدة، فلذلك كان أولى.\rوالصحيح من حديث أبي هريرة المتقدم من رواية شعيب بن أبي حمزة بالتاء، باثنتين من فوقها، وروايتها بالباء المعجمة بواحدة تقصير، ومن تعلق بذلك فقد وهم، فإن المبين بالباء المعجمة بواحدة قد تقدم في قوله: {الْحَقُّ الْمُبِينُ} [النور: 25]، فلا بد من أن يكون هذا غيره.\r"], [539, "الاسم السابع: المستطيع\rوفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [538, 539]}, "561.323": {"x": [[539, "لم يرد في قرآن ولا سنة اسماً، وقد ورد فعلاً، قال تعالى: {هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَائِدَةً مِّنَ السَّمَاءِ} [المائدة: 112]، وقد روي عن عائشة أنها قالت: (كان الحواريون أعرف بالله من أن يقولوا: هل يستطيع ربك)، تعني بالياء، وإنما هو: هل تستطيع ربَّك، بالتاء، والصحيح قراءة التاء حسب ما بيناه في كتاب المشكلين من تأويل وقراءة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [539, 539]}, "561.324": {"x": [[539, "وقد تقدم شرحه لغةً؛ لأن الاستطاعة هي: القدرة والقوة، وهي استفعال من طاع: إذا انقاد، فكأنه بما هو عليه من القدرة يطيعه كل موجود، كما\r"], [540, "قال تعالى: {فَقَالَ لَهَا وَلِلْأَرْضِ ائْتِيَا طَوْعًا أَوْ كَرْهًا قَالَتَا أَتَيْنَا طَائِعِينَ} [فصلت: 11].\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [539, 540]}, "561.325": {"x": [[540, "فيه ست مسائل:\rالأولى: [في وجه التسمية به مع أنه إنما ورد فعلاً]\rقال علماؤنا - رحمة الله عليهم -: لا يوصف الباري تعالى بأنه مستطيع، لأن أسماءه لا تؤخذ إلا توقيفاً، ولم يرد فيها مستطيع، ويلزمهم ألا يصفوه بالضار النافع، لأنه لم يرد به اسم توقيفاً، وإنما ورد به فعلاً، ولكنه لما كان عندهم فعل كمال ذكروا فيه اسماً، وكذلك يلزمهم في الاستطاعة، فإنها وصف كمال.\rالمسألة الثانية: في وصف الأَيْدِ\r"]], "pg": [540, 540]}, "561.326": {"x": [[540, "فإن قيل: فقد وصف الباري تعالى قوته بالأيد فقال: {وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ} [الذاريات: 47]، قال ابن عباس: يعني بقوة، فهلا قلتم منه أيِّد؟\rالجواب أنا نقول:\rالأيد هي: قوة اليد، ولما كان وصف الباري باليدين مما لا يدخل فيه تأويل عند أكثر العلماء، ويدخل عند بعضهم، فتتشعب وجوه التأويل فيه، لم\r"], [541, "يصح أن نشتق منه اسماً، لأنه كان يأتي على هذا تركيب محتمل على محتمل، وذلك يبعد في مسائل التكليف الظنية، فكيف في العقليات، فضلاً عن صفات الباري سبحانه، فوجب التوقف لذلك.\rالمسألة الثالثة: في وصف المُطيق\r"]], "pg": [540, 541]}, "561.327": {"x": [[541, "فإن قيل: فهو يوصف بأنه مطيق؟\rقلنا: الطاقة هي: القدرة بعينها، ولم يرد منها اسم، ولو ورد لقلنا به، لأنه ليس فيه نقص يتقدس عنه الخالق.\rالمسألة الرابعة: في وصف الجَلْدِ\r"]], "pg": [541, 541]}, "561.328": {"x": [[541, "فإن قيل: فقد جاء عن العرب: رجل جلد: إذا كان قوياً، فهل يصح وصف الباري به؟\rقلنا: لا يصح وصف الباري تعالى به، لأن الجلد عندهم هو: الذي يصبر على ما يحمل من مشقة، وذلك محال على الله تعالى، فاستحال وصف الباري به لأجل ذلك.\rالمسألة الخامسة: في المختار\r"]], "pg": [541, 541]}, "561.329": {"x": [[541, "نقول - وبالله التوفيق -: إن استطاع هو: استفعل من طاع، ولقولنا: استفعل في لسان العرب خمسة معان:\rمنها: أن تكون استفعلت بمعنى سألتُه الفعل؛ كقولك: استنجدتُ واستعنتُ.\r"], [542, "وتأتي بمعنى وجدته كذلك، كقولنا: استجدته أي: أصبته جيداً، واستكرمته: أصبته كريماً، فيكون على هذا معنى قوله: {هل تستطيع ربَّك}، بالتاء المعجمة باثنتين من فوقها في الأولى محتملاً للمعنيين جميعاً، فيجوز أن يكون معناه: هل تستدعي إجابته، والثاني: هل تجده مطيعاً، والوجهان جائزان.\rوأما من قرأ: {هَلْ يَسْتَطِيعُ رَبُّكَ} بالياء المعجمة باثنتين من تحتها في الأولى، فتكون استفعلتُ ها هنا بمعنى فعلت - وهو الثالث من وجوهها - ويكون معناه هل يقدر؟\rوالمعنى على ما تقدم هل يطيعه في ذلك إذا أراده؟\rفإن قيل: وكيف يجهلون ذلك حتى يسألوه، وهذا الذي أنكرت عائشة رضي الله عنها حسب ما تقدم؟\rالجواب: أن معناه قد مضى مستوفىً في كتاب المشكلين، والذي يقرُب منها أن يقال: إن علماءنا قالوا: إن ذلك كان قبل أن يكونوا مؤمنين، وهذا ضعيف: لقوله: {وَتَطْمَئِنَّ قُلُوبُنَا} [المائدة: 113].\rوقال بعضهم: معناه استكشاف تأتي الفعل، كما تقول لرجل: هل تستطيع أن تنهض معي في كذا، وأنت تعلم أنه مستطيع، ولكنك تريد استكشاف ما عنده.\r"], [543, "والصحيح أن معناه: هل يقدر ربك، المعنى: هل تتعلق قدرته بهذا الفعل إيجاداً وخَلقاً، وإن كانت قد تعلقت به صحة وتقديراً، فليس كل ما يصح أن تتعلق به القدرة يقع.\rالمسألة السادسة: في ترتيب أسماء القدرة\r"]], "pg": [541, 543]}, "561.330": {"x": [[543, "الأول منها: ما جاء من لفظ قدر، وهو: الفاعل، القادر، والفعيل، القدير، وهذه الأسماء الثلاثة جارية على تباين الأسماء المشتقة.\rوأما المقتدر فقد بينا أنه مفتعِل، وقلنا: إن هذه التاء هي تاء التخصيص في الباري تعالى، وتاء الاكتساب في العبد، وهو تالٍ لهذه الأسماء السابقة، وتابع لها لما فيه من الإشكال.\rوأما المستقدِر فلا يقال منه، لأنه لم يرد، كما لا يقال في صفاته مستكبر، ويقال متكبر.\rوأما القوي فهو بعدها، لأن القدرة أبين وأوضح من القوة، إذ القوة محمولة عليها، معتبَرة بها، وكذلك المتين محمول عليه، لأنه بما تقدم يُشرَح ومنه يُستوضَح.\r"], [544, "الفصل الرابع: في التنزيل\r"]], "pg": [543, 544]}, "561.331": {"x": [[544, "المنزلة العليا للرب\rمن علم القادر ومعناه علم أن للباري في ذلك أحكاماً يختص بها ثلاثة:\rالأول: أنه ذو القدرة والقوة، وهما بمعنى واحد.\rالثاني: أنه متمكن مما يريد.\rالثالث: أنه لا يرده عن مراده أحد.\rالمنزلة السفلى للعبد\rأن يعلم أنه لا حول ولا قوة إلا بالله، فالله يخلق له القدرة والعلم والإرادة والتيسير والفعل.\r"], [545, "القول في شديد المِحال\rوهو الاسم الثامن من أسماء القدرة، فيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [544, 545]}, "561.332": {"x": [[545, "ورد به القرآن، قال تعالى: {شَدِيدُ الْمِحَالِ} [الرعد: 13]، وجاء في الحديث عن إبراهيم الخليل أنه لم يكذب إلا ثلاث كذبات، وما منها كذبة إلا وهو يُماحل بها عن الإسلام.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [545, 545]}, "561.333": {"x": [[545, "ورد في اللغة على وجوه سبعة:\rالأول: المِحال: السعاية إلى السلطان.\rالثاني: أنه النقمة.\rالثالث: أنه القوة، قال الكِسائي: تقول العرب: محِّلني: أي: قوِّني.\r"], [546, "الرابع: أنه العقوبة.\rالخامس: الجدال.\rالسادس: المكر.\rالسابع: أنه المطاولة، ومنه قول علي: إن من ورائكم أموراً متماحلة، أي: طويلة.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [545, 546]}, "561.334": {"x": [[546, "وفيه ثلاث مسائل:\rالمسألة الأولى: في سرد أقوال العلماء\r"]], "pg": [546, 546]}, "561.335": {"x": [[546, "للعلماء فيه تسع عبارات:\rالأول: شديد القوة.\rالثاني: شديد العداوة.\rالثالث: شديد الحقد.\rالرابع: شديد الغضب.\rالخامس: شديد الحَيْل.\rالسادس: شديد الحَوْل.\rالسابع: شديد الإهلاك.\rالثامن: شديد الأخذ.\r"], [547, "التاسع: شديد الانتقام.\rالمسألة الثانية: في تحقيق القول فيه\r"]], "pg": [546, 547]}, "561.336": {"x": [[547, "وهو إذا تتبعته ألفيته يرجع إلى القوة، فإن مُحِلَ بالرجل إلى السلطان فقد قوي أمره، وكذلك الانتقام والمكر: قوة في السعي، والمطاولة: قوة في المقاصد، وصبر على المحاولة حتى تنجح، والمطلوب من القوة تصريفها في المنافع، فقوله في إبراهيم صلى الله عليه وسلم: (ماحل بها في الله) أي: دافع بقوة، وهو من ثمرات القوة، (والقرآن ماحل) أي: مدافِع عن صاحبه بقوة حجته.\rالمسألة الثالثة: في تخريج الأقوال على الوجه الجائز وتركيبها "]], "pg": [547, 547]}, "561.337": {"x": [[547, "على الحقائق\rأما قولهم: إنه شديد القوة، فقد تقدم بيان شديد القوة، وأما شديد العداوة فسيأتي بيانه في أسماء الإرادة.\r"], [548, "وأما شدة الحقد فمحال في حق الله، وكذلك الغضب؛ يأتي بيانه في أسماء الإرادة.\rوأما شدة الحَيل، فالحيل هو: الحوْل، لغةٌ فيه، والواو أعلى، وأما الحيل جمع حيلة فلا يجوز على الله تعالى.\rوأما الإهلاك فهو فائدة القوة، وكذلك الأخذ والانتقام.\rالفصل الرابع: في التنزيل\r"]], "pg": [547, 548]}, "561.338": {"x": [[548, "وهو نحو ما سبق في القوي المتين.\r"], [549, "الاسم التاسع: المحيط\rفيه أربعة فصول.\rالفصل الأول: في مورده\r"]], "pg": [548, 549]}, "561.339": {"x": [[549, "ورد به القرآن، قال تعالى: {وَكَانَ اللَّهُ بِكُلِّ شَيْءٍ مُّحِيطًا} [النساء: 126]، وقال: {وَاللَّهُ مِن وَرَاءِهِم مُّحِيطٌ} [البروج: 20]، وقال: {وَاللَّهُ مُحِيطٌ بِالْكَافِرِينَ} [البقرة: 19]، ووردت به السنة في حديث أبي هريرة المفسر من طريق عبد العزيز بن الحُصين، لا من طريق شعيب بن أبي حمزة، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [549, 549]}, "561.340": {"x": [[549, "فنقول: الإحاطة في كلام العرب هي: الاحتواء على الشيء، وهي: أخذه من جميع جوانبه؛ حتى يكون حاوياً له محيطاً به من جميع جوانبه، قال تعالى: {وَأُحِيطَ بِثَمَرِهِ} [الكهف: 42].\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [549, 549]}, "561.341": {"x": [[549, "وفيه ثلاث مسائل:\r"], [550, "المسألة الأولى: في حقيقته\r"]], "pg": [549, 550]}, "561.342": {"x": [[550, "أما حقيقته فهي لغته بعينها، وبعد هذا فله ثلاثة متعلَّقات.\rوهي:\rالمسألة الثانية:\r"]], "pg": [550, 550]}, "561.343": {"x": [[550, "الأول: أن يحيط به قدرةً، كقوله:: {وَاللَّهُ مُحِيطٌ بِالْكَافِرِينَ} [البقرة: 19].\rالثاني: أن يحيط به علماً، كقوله: {أَحَطتُ بِمَا لَمْ تُحِطْ بِهِ} [النمل: 22].\rالثالث: أن يحيط به قبضاً، وذلك يختص بالأجسام.\rالمسألة الثالثة: في شرح العقيدة\r"]], "pg": [550, 550]}, "561.344": {"x": [[550, "إذا علمتم اللغة والحقيقة، فاعلموا أن قدرة الله عامة في كل مقدور، لا يشذ عنه شيء، ولا يعجزه شيء، وعلمه عام في كل معلوم، على العموم والخصوص، في حال العدم والوجود، وعلى الجملة والتفصيل، كما سيأتي بيانه إن شاء الله تعالى، فهو محيط بالوجهين، وهو على هذين الوجهين من أوصاف الإثبات في الذات.\rوإذا قلنا: إنه محيط بالقبض، فقد قال تعالى: {وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ} [الزمر: 67] خبراً عن الآخرة، وقال خبراً عن حال الدنيا: {فَانفُذُوا لَا تَنفُذُونَ إِلَّا بِسُلْطَانٍ} [الرحمن: 33].\r"], [551, "الفصل الرابع: في التنزيل\r"]], "pg": [550, 551]}, "561.345": {"x": [[551, "إذا فهمت معنى الإحاطة في القدرة والعلم فأحكامه في القدرة قد سبقت، وبيانها في العلم سيأتي مقروناً ببيان منزلة العبد فيهما، إن شاء الله تعالى.\r"], [552, "الواسع والمُوسِع\rوهما الاسم العاشر والاسم الحادي عشر من أسماء القدرة. فيهما أربعة فصول:\rالفصل الأول: في موردهما\r"]], "pg": [551, 552]}, "561.346": {"x": [[552, "قال الله تعالى: {وَاللَّهُ وَاسِعٌ عَلِيمٌ} [البقرة: 261]، وقال: {إِنَّ رَبَّكَ وَاسِعُ الْمَغْفِرَةِ} [النجم: 32]، وقال: {وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ وَإِنَّا لَمُوسِعُونَ} [الذاريات: 47]، وقال في حديث أبي هريرة المفسر: الواسع، ولم يذكر الموسع.\rالفصل الثاني: في شرحهما لغة\r"]], "pg": [552, 552]}, "561.347": {"x": [[552, "قال علماؤنا: الواسع: فاعل من السَّعة، يقال: وسع الشيء واتسع، وحقيقته كل محلٍّ يحتمل من الأجزاء والأعيان أكثر مما يحتمله الآخر، ثم نقل مجازاً إلى القدرة والعلم والإرادة والكلام، قال تعالى: {وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ وَإِنَّا لَمُوسِعُونَ} [الذاريات: 47]، {رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَّحْمَةً وَعِلْمًا} [غافر: 7]، وقال: {مَّا فَرَّطْنَا فِي الْكِتَابِ مِن شَيْءٍ} [الأنعام: 38].\r"], [553, "وجاز أن يقال: قدرة واسعة، وعلم واسع، وإرادة واسعة، إذا كانت متعلَّقاتها أكثر من متعلقات غيرها، ومنه: ناقة وَساع: إذا كانت ذريعة المشي ممتدة الخطو، وَسَيْرٌ وسيع: إذا كان سريعاً يقطع من المسافة في زمن ما لا يقطع غيره في مثله من الزمن، ويقال: فلان ذو سعة، أي: غني يصل بما له من المتملَّكات إلى ما لا يصل أقل مالاً منه، والفعل منه: أوسع، أي: صار ذا سعة.\rوقال ابن الأنباري: الواسع: الذي يسع لما يُسأل، المحيط بكل شيء.\rوقال الشاعر:\rرعاكِ ضمانُ الله يا أم مالكٍ ... ولَلهُ عن يُشقيكِ أغنى وأوسعُ\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [552, 553]}, "561.348": {"x": [[553, "وفيه ثلاث مسائل:\rالمسألة الأولى: في تحقيق العقيدة فيه\r"]], "pg": [553, 553]}, "561.349": {"x": [[553, "قد تقدم بيان معناه، وحققنا لكم أن السعة في الأجسام عبارة عن احتمال كثرة الأجزاء، والسعة في المعاني عبارة عن كثرة المتعلقات،\r"], [554, "فالباري تعالى واسع، أي: وسع بقدرته وعلمه وإرادته وكلامه كل شيء، كما قال سبحانه: {رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَّحْمَةً وَعِلْمًا} [غافر: 7] وانتصبا على التمييز، وهو كثير في اللغة، ووسع رزقه جميع خلقه، ووسع كرسيه السماوات والأرض.\rفإن كان العلم - كما قال ابن عباس - فلإحاطته بكل معلوم، وإن كان الكرسي جسماً عظيماً كما روي في الأثر، حسب ما أوردناه في كتاب المشكلين، فمعناه أنه جسم ذو أبعاد؛ إذا طُرحتْ فيه السماوات والأرض احتمل أن يكون ظرفاً لها.\rالمسألة الثانية: في تركيب المعنى على اللفظ اعتقاداً\r"]], "pg": [553, 554]}, "561.350": {"x": [[554, "إذا قلنا: إنه واسع بمعنى: قادر أو عالم فقد ظهر، وهو من صفات الذات كذلك.\rوإن كان واسع الملك والعطاء بمعنى الكثرة فهو من صفات الفعل.\rوإن قلنا: إنه موسع، بمعنى: أنه ذو سعة، وهو الغني، فقد تقدم بيانه، ويكون من صفات التنزيه.\rوإن قلنا: إنه موسع، بمعنى: أنه وسَّع على غيره أو خلق الأجسام ذات سعة فهو من صفات الأفعال، وعليه جاء قوله: {وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ وَإِنَّا لَمُوسِعُونَ} [الذاريات: 47]، وقيل: جاء على وصف التنزيه، المعنى: وإنا لأغنياء عن المعونة في ذلك.\r"], [555, "المسألة الثالثة:\r"]], "pg": [554, 555]}, "561.351": {"x": [[555, "قد بينا أن الواسع والموسع يكون من أسماء الذات، ويكون من أسماء الأفعال، وحققناه وشرحناه.\rووهم فيه حبرٌ عظيم وهو الأستاذ أبو إسحاق، فعدده في جملة صفات الأفعال وجعله منها، وقال بعد أن عدده فيها: (هو الذي لا تتعذر عليه عطية)، وهذا هو الحجة عليه، فإنه إشارة إلى عموم القدرة، إذ التعذر نقيض الإمكان، والإمكان متعلق بالقدرة ومن أحكامها.\rوأيضاً فإن تخصيص ذلك بعموم القدرة دون العلم والإرادة مع تصريحه بقوله: {وَسِعْتَ كُلَّ شَيْءٍ رَّحْمَةً وَعِلْمًا} [غافر: 7]، لا معنى له، والتعميم في صفات الله وأسمائه، والكمال متى احتمله اللفظ أوجبه التفسير وعيَّنه التأويل.\r"], [556, "الفصل الرابع: في التنزيل\r"]], "pg": [555, 556]}, "561.352": {"x": [[556, "إذا علمتم الحقيقة للرب في هذا الاسم فله في ذلك أحكام يختص بها، وهي:\rسَعَةُ القدرة، والعلم، والإرادة، والقول، والخلق، والعطاء، حسب ما سبق بيانه في كثرة المتعلقات، ويضبطه أن صفاته العُلى على غاية التعلق ذاتاً وفعلاً.\rوعلى العبد في منزلته أن يسعى في كثرة متعلَّقات صفاته؛ من العلم والطاعة، وفي سعة أخلاقه بالاحتمال والصبر."]], "pg": [556, 557]}, "561.353": {"x": [[558, "ص 7\rالإسم الأول: العليم.\rوإنما بدأنا به لأن قولنا عالم وعلّام ورد مقيّدا، وقولنا عليم ورد مطلقا.\rوفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [558, 558]}, "561.354": {"x": [[558, "ورد به القرآن والسنة، وأجمعت عليه الأمة، قال تعالى: \"ذلك تقدير العزيز العليم\" (الأنعام: 97)، وقال: \"عالم الغيب والشهادة\" (الأنعام: 74)، وقال: \"علّام الغيوب\" (المائدة: 111)، وقال: \"إن ربّك هو أعلم من يضل عن سبيله\" (الأنعام: 118)، وورد في حديث أبي هريرة مفسَّرا من الطريقين جميعا ذكر العليم والعلّام، ولم يرد ذكر العالم، وفي الحديث: \"الله ورسوله أعلم\"، وأجمعت عليه الأمة.\r"], [559, "الفصل الثاني: في شرحه لغة وحقيقة\r"]], "pg": [558, 559]}, "561.355": {"x": [[559, "اعلموا –وفقكم الله- أنّ هذا الاسم هو العليم معلوم لدى القلوب والألسنة، عند العرب والعلما، ولكنّ الناس تفاوضوا فيه وتكلّموا في حدّه وتحزّبوا عليه حتى صار تحت خفاء الجهل، ولئن خفي العلم فما يظهر بعده، ولقد تكلّمنا عليه في الأصول بما يغني عن إعادته، ولكنا نشير إلى طرف منه فنقول على التقريب:\rالعلم عبارة عن اطلاع المرء على ما لم يطّلع عليه، وانكشاف ما غاب عنه إليه، وعالم فاعل من علم، وعليم وعلّام مبالغة فيه، وله أسماء كثيرة، منها: العقل، والفطنة، والدراية، والخبرة؛ في أخوات لها.\rالفصل الثالث: في بيانه عقداً\r"]], "pg": [559, 559]}, "561.356": {"x": [[559, "وفيه أربع مسائل:\rالمسألة الأولى: في بيان علمه تعالى\r"]], "pg": [559, 559]}, "561.357": {"x": [[559, "والذي اعتقده أهل السنة أن له علما كما أخبر عن نفسه، فقال: \"أنزله بعلمه\" (النساء: 165).\r"], [560, "والإحكام يدلّ على العلم على ما بيّنّاه في الأصول.\rالمسألة الثانية:\r"]], "pg": [559, 560]}, "561.358": {"x": [[560, "نقول: إن علم الباري تعالى واحد، به يعلم المعلومات، ويتعلّق بكل شيء على كل وجه يصحّ العلم به، وقد صحّ في الأثر أن الخضر قال لموسى عليهما السلام: \"ما نقص علمي وعلمك من علم الله إلا بمقدار ما نقص هذا العصفور من البحر\".\r"], [561, "قال علماؤنا: ويجوز أن تكون لله علوم لا تتناهى بعدد المعلومات، ويجوز أن تكون لله علوم لا تتناهى بعدد المعلومات، وإنما علمنا اتّحاده شرعا لقوله: \"أنزله بعلمه\" (النساء: 165)، \"وما تحمل من أنثى ولا تضع إلا بعلمه\" (فاطر: 11)، وقد تقدّم القول فيه وفي وجه المبالغة في معانيه.\rالمسألة الثالثة:\r"]], "pg": [560, 561]}, "561.359": {"x": [[561, "علم الله تعالى داخل تحت حدّ العلم وحقيقته، ولكنّه لا يصحّ أن يكون علم ضرورة لما في الضرر من النقص الذي يتعالى عنه ربنا، وليس بعلم نظرٍ لما في النظر من الحاجة إلى المقدّمات المحصِّلة للعلم، ولما في ذلك من افتتاح المعرفة، وعلم الله تعالى قديم.\rالمسألة الرابعة:\r"]], "pg": [561, 561]}, "561.360": {"x": [[561, "قال علماؤنا: لا نصف الباري بأنه عارف؛ وإن كان بمعنى عالم، لأنه لم يرد به توقيف.\r"], [562, "وقد بيّنّا في أصول الدين أن المعرفة والعلم مختلفان، وأن المعرفة علم واحد، والعلم معرفتان، هذه لغة العرب.\rوالسبب فيه –والله أعلم- أنه لمّا كان العلم أكمل من المعرفة سمّينا الباري تعالى بالأكمل، ويجوز أن يقال فيه عارف على معنى أنه عالم بالأوائل، ويقال أيضا عالم على معنى أنه يعرف الأوائل والأواخر، وأن المعارف كلّها له.\rالفصل الرابع: في التنزيل\r"]], "pg": [561, 562]}, "561.361": {"x": [[562, "لا يخفى على العبد العلم؛ لأنه قد احتوى منه على أنموذج يستدل به على ربه وعلى علم ربه، وهذه هي الحكمة في أن جُعلت فيه صفات تشترك في الأسماء مع صفات الخالق وأسمائه؛ ليكون عونا له في استدلاله عليه ومعرفته به، فإذا علم بإتقان المخلوقات علم ربه وتحقق أنه العالم الذي لا يخفى عليه شيء؛ فعند ذلك يتبيّن له أنه قد اختصّ تعالى في ذلك بأحكام جماعها عشرة:\r"], [563, "الأول: عدم الأولية في علمه؛ لاستحالة أن يكون مخلوقا، لأنه لا يُخلق –وهو محكم- إلا بمثله، فيتداعى ذلك إلى ما لا يتناهى.\rالثاني: استحالة العدم عليه لاستحالة عدم القديم.\rالثالث: أنه يعلم به جميع المعلومات، وعِلم العبد محصور بالمعلوم.\rالرابع: أنه يعلمه جملة وتفصيلا، وعِلم العبد يتعلّق بالجملة دون التفصيل.\rالخامس: أن علمه يتعلق بالتفريغ والتأصيل، وعلم العبد يتعلق بأصلٍ خاصة دون فروعه.\rالسادس: أن علم الله سابق الموجودات، وعلم العبد مسبوق بالمعلوم.\rالسابع: أنه لا يتطرّق إلى علمه آفة، وعلم العبد مُعرّض لكل آفة.\rالثامن: أن علم الرب بالمعلومات في غاية الكشف والإيضاح، وعلم العبد وإن بلغ غاية فإنه مُقصّر، كأنه من راء ستر، وقد بيّن ذلك بقوله: \"ولا يحيطون بشيء من علمه إلا بما شاء\" (البقرة 254).\rالتاسع: أنه لا يشغله شأن عن شأن.\rالعاشر: أن علم الرب أفاد الموجودات، وعلم العبد مستفاد من الموجودات.\r"], [564, "المنزلة الثانية للعبد:\rعلى العبد إن عَلِم عِلْم ربه حكمان:\rأحدهما: أن يفوّض إليه ويستسلم لسابق علمه.\rالثاني: أن يسعى في اكتساب العلم به من كل وجه، إذ هو أشرف المكتسبات، فكلما كثرت طرق العلم به زاد العلم به، فبذلك شرف علم الملائكة والأنبياء عليهم السلام على علم الخلق لكثرة دلائلهم.\r"], [565, "الاسم الثاني: وهو السميع.\rونذكر البصير معه لارتباطه به في الذكر، وجري عادة علمائنا –رحمة الله عليهم- بالجمع بينهما، وهو أيضا أربط للكلام، وأقرب للمرام، فنقول:\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [562, 565]}, "561.362": {"x": [[565, "ورد به القرآن، قال تعالى: \"السميع البصير\" (الإسراء 1)، فجمع ذكرهما، وأفرده أيضا في موضع آخر؛ وورد في السنة مفسَّرا في حديث أبي هريرة، وجاء في سائر الأحاديث ذكرهما معا؛ وأجمعت الأمة عليه، وإن كانوا قد تباينوا في المعنى على ما نذكره بعد إن شاء الله.\r"], [566, "الفصل الثاني: في شرحهما لغة\r"]], "pg": [565, 566]}, "561.363": {"x": [[566, "أما السمع والبصر فمشهوران في اللغة، وكذلك قولنا: سميع بصير، وهما بناء فعيل من سمع وبصر، واختُلف في بناء سميع على ثلاثة معان:\rالأول: أنه بمعنى سامع، وهو إدراك المسموعات.\rالثاني: أنه بمعنى مُسمع لغيره، كما قال عمرو بن معدي كرب:\rأمِن ريحانة الداعي السميع يؤرقني وأصحابي هُجوعُ\rأراد الداعي المُسمع.\rالثالث: أن يكون سميع بمعنى قابل، كما قال: \"سمع الله لمن حمده\"، أي قبله، وفي الحديث: \"اللهم إني أعوذ بك من دعاء لا يُسمع\"، ومنه قول الشاعر:\rدعوت الله حتى خفت ألّا *** يكون الله يسمع ما أقول.\r"], [567, "وأما البصير ففيه أيضا ثلاثة معان:\rأحدها: إدراك المبصرات ورؤيتها.\rالثاني: العلم بخفيّات الأمور ودقائق الأشياء، كما يقال: فلان بصير بكذا، أي خبير متحقّق به.\rالثالث: أنه بمعنى مُبصر، كما تقدّم في سميع.\rالفصل الثالث: في شرحهما حقيقة وعقدا\r"]], "pg": [566, 567]}, "561.364": {"x": [[567, "وفيه سبع مسائل:\rالمسألة الأولى: في تحقيق السمع والبصر\r"]], "pg": [567, 567]}, "561.365": {"x": [[567, "اختلف أصحابنا في سمعه وبصره؛ فمنهم من قال: إنهما نوعان من العلم بالوجود، أحدهما يقال له سمعٌ، والآخر يقال له بصرٌ، ولم ينكر إطلاق القول بأن لله علوما غير متماثلة، ولا يسدّ واحد منهم مسدّ صاحبه؛\rومنهم من قال: إن السمع إدراك المسموع، وقد اختلف في ذلك جواب شيخنا أبي الحسن في كتبه، فتارة قال: السمع إدراك المسموع، وردّ قول من قال: إنه العلم بالمسموع، وقال في بعض كتبه: إنه ضرب من العلم.\r"], [568, "قال الأستاذ أبو بكر بن فورك: \"الصحيح أنه إدراك المسموع، وأنه صفة تزيد على العلم، وكذلك القول في البصر: إنه صفة تزيد على العلم، وقد شرحنا ذلك في كتب الأصول.\rوالنكتة فيه أنه لو كان معنى يسمع ويبصر يعلم –وهو عالم بما كان ويكون- لكان سامعا ومبصرا لما كان ويكون، وذلك محال، وفي شمول العلم للموجود والمعدوم، واختصاص السمع والبصر بالموجود أعظم دليل على الفرق بينهما، وتميُّز كل واحد منهما بحقيقته ومُتعلّقه.\rالمسألة الثانية:\r"]], "pg": [567, 568]}, "561.366": {"x": [[568, "الباري تعالى عندنا سميع بسمْعٍ، بصير ببصرٍ، وخالفت في ذلك المبتدعة فقالوا: إن الباري تعالى سميع وبصير بمعنى أنه عالم، وقد بيّنّا أن السمع والبصر معنى يزيد على العلم المطلق، وأنه لا بدّ له من فائدة مجددة.\rالمسألة الثالثة:\r"]], "pg": [568, 568]}, "561.367": {"x": [[568, "نقول: إن الباري تعالى سميع حقيقة بكل معنى لغويّ، لأن اللغة في ذلك لا تأباه الحقيقة، وكل جائز في الحقيقة وردت به اللغة لا مردّ له.\rفإذا قلنا: إنه سميع بمعنى أنه عالم بالمسموعات فإن ذلك يرجع إلى صفات الذات والإثبات.\r"], [569, "وإن قلنا إنه سميع بمعنى أنه قابل فلذلك وجهان:\rأحدهما: أنه يرجع إلى مدحه له، فيعود إلى الكلام، وهو من صفات الذات أيضا.\rوالثاني: رجوعه إلى الثواب، فإن الكريم إذا قبل ورضي أثاب.\rوإذا كان سميعا بمعنى أنه مُسمِع فقد قال علماؤنا: إنه من صفات الأفعال، وذلك يعود إلى إسماعه لخلقه كلامه وكلام غيره.\rوإذا قلنا في كونه بصيرا إنه بمعنى إدراك المُبصَرات رجع إلى الذات، لأن الإدراك معنىً قائم بالمُدرِك.\rوإن قلنا إنه بمعنى العلم بخفيّات الأمور كما يقال: فلان بصير بكذا، فلا نجعله معناه الأخصّ به، لأنّ ذلك قول بمذهب المبتدعة في أنه بصير بمعنى أنه عالم، ولكنّه عندنا أحد معانيه، والأصل هو الإدراك فيه.\rوإن قلنا إنه بمعنى مُبصِر احتمل معنيين:\rأحدهما: أنه بمعنى فاعل أي باصر، لأنه العرب تقول: بصُرت به وأبصرته بمعنى رأيته، فتجعل فَعُلَ من هذا الباب وأفعل بمعنى واحد، فإذا أردت تعدية الفعل فيه عدّيته بالتضعيف، فتقول: بصّرته بتشديد الصاد.\r"], [570, "والثاني: أن يكون بمعنى أنه جعل غيره يُبصر، فيكون من صفات الأفعال، وتكون العبارة عنهما واحدة، كقول العرب رجعت، فإنه بالتعدية وعدم التعدية بلفظ واحد، يقال: رجعت أن ورجعت زيداً.\rالمسألة الرابعة\r"]], "pg": [568, 570]}, "561.368": {"x": [[570, "إذا ثبت أنه مدرِك للمبصرات بمعنى أنه راءٍ فإنه يقال له راءٍ كما يقال له بصير، لكن لم يرد بالاسم توقيف، وورد بالفعل، قال صلى الله عليه وسلم: \"أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك\"، والرؤية في كلام العرب تأتي على معنيين:\rأحدهما: رؤية العين، وهي إدراك المبصَرات، وهي تتعدى إلى مفعول واحد.\rوالمعنى الثاني: هو العلم، وهي على ذلك تتعدى إلى مفعولين، وقد بيّنّا ذلك كله في كتاب المشكلَين، والباري تعالى عندنا راءٍ بالوجهين لوجوبهما له.\rالمسألة الخامسة:\r"]], "pg": [570, 570]}, "561.369": {"x": [[570, "إذا علمتم معنى كونه سميعا بصيرا فاعلموا أنه سميع في الأزل لكلامه، بصير راءٍ لذاته، فكل ما خلق بعد ذلك من كلام أو موجود سمِعه ورآه.\r"], [571, "المسألة السادسة: في وصف الباري تعالى بإدراك الألم واللذة\r"]], "pg": [570, 571]}, "561.370": {"x": [[571, "قال علماؤنا: نقول إنه مدرك لسائر المدرَكات على كل وجه يصحّ أن يدرَك عليه المُدرَك، كما يصح أنه عالم بكل معلوم على كلّ وجه يُعلم به المعلوم، فهو يُدرك الألم واللذة بغيره كما يعلم الألم واللذة التي به.\rالمسألة السابعة: في التحقيق في الباب\r"]], "pg": [571, 571]}, "561.371": {"x": [[571, "ليس بخاف كما قدّمنا معنى العلم، وأنه كشقُ الحقائق والإطلاع عليها، وبينّا الفروق التي أدركناها بين علم الله تعالى وعلم المخلوق، من الأوجه العشرة التي بينّاها، وقررنا أن علم الله تعالى عامٌ في المعلومات، لا يحتاج إلى نظر ومقدّمات، وأن علم العبد بخلاف ذلك، ولم يهب الباري تعالى للمكلَّف إلا علما قاصرا ببعض المعلومات، وما نعلمه أيضا إنما نعلمه بطرقٍ ومقدّمات عددها سبعٌ:\rالأوّل: علمه بديهة.\rوالعلم الحاصل من جهة الحواسّ الخمس.\rفهذه ستّة طرق لا سابع لها.\r"], [572, "يحصل عنها علم سابع وهو النظري.\rفهذه طرق محصورة مقرونه بآفات ونقائص، وهذه المقدمات من جملة معلومات الباري، لا بهذه الطرق ولا على هذه الوجوه، مُعرّاة من الآفات، وجميع ذلك يرجع إلى طرق وضعها الباري تعالى أسبابا وآلة لإدراك تلك المعلومات، وهو سبحانهبهذا كلّه عالم دون تلك الطرق، فتبيّن أن علم الله سبحانه يتعلق بجميع المعلومات على اختلافها وتباين طرقها الحاصلة عنها، دون سبب ولا مقدّمة ولا حدوث آفة ولا نقيصة، ونقول: إنه سميع بصير لكمال أنواع العلوم كما علّمنا ونبّهنا ودلّ لنا.\rالفصل الرابع: في التنزيل\r"]], "pg": [571, 572]}, "561.372": {"x": [[572, "أما المنزلة العليا لله فقد تقدّم بيانها في اسم العالم.\rوأما المنزلة السفلى للعبد فإنه إذا علم أن ربه يسمع السر وأخفى فلا يُجري بخاطره ولا يهمس بلسانه إلا ما يرضاه، وكذلك إذا علمت أنه يراك\r"], [573, "فكُفّ عن المخالفة، فقد جاء في الصحيح أن جبري صلى الله عليه وسلم قال: \"ما الإحسان؟ قال رسول الله صلى الله عليه وسلم: أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك\".\r"], [574, "الاسم الرابع: الشهيد\rوفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [572, 574]}, "561.373": {"x": [[574, "قد ورد به القرآن، قال تعالى: \"وكفى بالله شهيدا\" (النساء 78)، وورد في حديث النبي صلى الله عليه وسلم مفسَّرا في حديث أبي هريرة المشروح، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [574, 574]}, "561.374": {"x": [[574, "فيه أربعة أقوال:\rالأول: أنه فعيلٌ من شهد الشيء إذا حضره واطّلع عليه، قال تعالى: \"فمن شهد منكم الشهر فليصمه\" (البقرة 184)، يعني في مُستقرِّه صحيحا.\rالثاني: الشهيد العليم، كقوله: \"شَهِدَ اللَّهُ أَنَّهُ لَا إِلَهَ إلا هُوَ وَالْمَلَائِكَة\" (آل عمران: 18).\rالثالث: الشهيد المبين، لما يقيم من البيّنة على حكمه، كقوله: \"والله على كل شيء شهيد\" (المجادلة: 6)، أي بيّن الله بما أقام من الأدلة على وحدانيته.\r"], [575, "الرابع: أنه شهيد بمعنى مشهود، أي مشهود له بالوحدانية، كقولنا: بديع وحكيم في أحد الوجهين، والشهيد في سبيل الله من هذا المعنى، فإنه فعيل بمعنى مفعول.\rالفصل الثالث: في حقيقته\r"]], "pg": [574, 575]}, "561.375": {"x": [[575, "فيه ثلاث مسائل:\rالمسألة الأولى: في حقيقة هذه اللفظة\r"]], "pg": [575, 575]}, "561.376": {"x": [[575, "اعلم أن \"ش هـ د\" كيفما تصرّف في الأخبار فإنه يرجع إلى ما حصل به العلم من المشاهدة، وهي الحواسّ عدا السمع، ولذلك قال: \"عالم الغيب والشهادة\" (الرعد: 10)، فالغيب ما لم تره ولا لمسته ولا ذقته ولا شممته، والشهادة عكسه، والغيب ما سمعته أو قسته، أو ما لم تسمع به ولا عبّرته، والشهادة عكسه.\rالمسألة الثاني: في تركيب اللغة على الاعتقاد\r"]], "pg": [575, 575]}, "561.377": {"x": [[575, "كل من قال إن شهد بمعنى حضر فصدق، وهو قوله: \"ما يكون من نجوى ثلاثة إلّا هو رابعهم\" (المجادلة 7)، الآية كلها، معناها أنه شاهد معهم ما شاهدوه من القول، سامع له كما سمعوه.\r"], [576, "ومن قال إنه شهيد بمعنى أنه عليم فصدق، لكنه فسّر الاسم الخاصّ بالعامّ، وهو تقصير، فالباري عليم بالغيب والشهادة، شهيد أي عالم بالشهادة.\rوأما من قال إنه بمعنى مُبيِّن، فإن الحجة في ذلك الآية التي ذكرناها، وأيضا فإن الشاهد يقول للحاكم: أشهد عندك بكذا: أي أُبيّنه.\rوالذي عندي أن قولنا شهيد لا يقتضي بَيَّنَ، على معنى أنه تفسيره بحال، وذلك يَبعد في اللغة، وإنما الذي هو تفسيره ما بيّنّاه من أنه علم مشاهِدا.\rوأما قول الشاهد للحاكم أشهد بكذا فليس بمعنى أبيّنُ ولا بمعنى أعلم، والدليل عليه إجماع الأمة أن الرجل لو قال للحاكم إذا شهد عنده أن أبيّنُ عندك كذا أو أعلم كذا بدل قوله: \"أشهد\" لما أصغى إليه، ولا قضى بقوله حتى يقول أشهد.\rوقد طال بحثي عن المعنى في ذلك عند الأحبار، وسؤالي فيه جميع المناظرين، فما وجدت عندهم معنى أكثر من أنها تعبد من الشرع\r"], [577, "بلفظة لا يجوز تبديلها، ولا يقوم غيرها مقامها، وقد بيّنّا ذلك في مسائل الإنصاف.\rوأما قوله: \"والله على كل شيء شهيد\" (المجادلة: 6)، أي مُطّلع، فالجواب عنه فيما بعده.\rوأما من قال: إنه شهيد بمعنى أنه مشهود أي مشهود له بالوحدانية، فإن اللغة تحتمله، ودليل العقل لا يردّه، والشريعة لا تأباه، ولكن لا يصحّ أن يكون هذا معناه الأصلي، فإنه الاسم إذا احتمل معنَيَين لا يقال إن المراد به أحدهما، لا سيما إذا تُرك الأظهر، والأظهر في هذا أن يكون الشهيد فعيلا من فاعل، فيكون من صفات الذات، وبعد ذلك لا يبعد أن يقال: إنه بمعنى مفعول، فيكون له المعنيان، وأحدهما –وهو هذا- تابع للآخر، وهو الأول، فيكون المعنى الأول صفات ذات، ويكون هذا الثاني بمنزلة مطاع ومعبود، لا يرجه إليه منه وصف.\rالمسألة الثالثة: في المختار\r"]], "pg": [575, 577]}, "561.378": {"x": [[577, "إذا علمتم معنى اللفظة لغة وحقيقة، وفهمتم وجه تركيب الاعتقاد على اللغة حسب ما بيّنّاه، فاعلموا أن قولنا شهيد معناه: العالم بما ظهر،\r"], [578, "والعليم العالم بما ظهر وخفي، هذا تحقيقه، ويصحّ أن يكون المراد به العالم باليقين التام العلم، الذي عنده كل شيء مشاهدة، ويكون ذلك استعارة على ما بينّاه.\rالفصل الرابع: في التنزيل\r"]], "pg": [577, 578]}, "561.379": {"x": [[578, "إذا علمتم هذا فالباري تعالى في المنزلة العليا من الشهادة، وله في ذلك حكمان:\rالأول: علمه بما ظهر.\rوالثاني: علمه الكامل الذي ليس وراءه خفاء ولا معه غطاء، ولا يتطرّق إليه ريب على الدوام والعموم.\rالمنزل الثانية للعبد:\rوعليه في ذلك حُكمان:\rأحدهما: أن يشهد الله فلا يغيب عنه: أي يكون معه حاضرا باعتقاده في كلّ حين.\rالثاني: أن يشهد لله كما قال تعالى: \"يَاأَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ\" (النساء 134).\r"], [579, "الاسم الخامس: الخبير\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [578, 579]}, "561.380": {"x": [[579, "قد ورد به القران: قال الله تعالى: \"والله بما تعملون خبير\" (البقرة 232)، وقال: \"إنه بعباده خبير بصير\" (الشورى 25)، وذلك كثير في القرآن، ووردت به السنة في حديث أبي هريرة المفسَّر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [579, 579]}, "561.381": {"x": [[579, "فيه ثلاثة أقوال:\rالقول الأول: أن الخبير العالم بما بطن.\rالثاني: أنه العلم بعد الإخبار أو الاختبار، يقال: خَبَرْتُهُ أي تتبّعت طلب الخبر عنه حتى علمته، ومنه قيل للأكّار خبير، لأنه يَخبر الأرض لمعرفة طيبها أو دناءتها.\rالثالث: الخبير بمعنى مُخبر، فعيل بمعنى مُفعل.\r"], [580, "الفصل الثالث: في حقيقته وعقده\r"]], "pg": [579, 580]}, "561.382": {"x": [[580, "فيه ثلاث مسائل:\rالمسألة الأولى:\r"]], "pg": [580, 580]}, "561.383": {"x": [[580, "ما تقدّم من أقوال أهل اللغة يرجع إلى معنيين:\rأحدهما: العلم بما بطن.\rوالثاني: العلم من جهة الخبر بالبحث والسؤال حتى يُخبَرَ به فيَخبُره.\rوحقيقته ترجع إلى معنى واحد، وهو العلم بعد الخبرة والبحث، يقال: خبرت الشيء، ولا يكون الاختبار إلا عن باطن، لأن الظاهر مكشوف لا يحتاج إلى اختبار، فلذلك قالوا: إنه العلم بما بطن، لكن من جهة الاختبار، ولذلك قال بعض علمائنا: إنّا إذا قلنا إنه العلم بما بطن جاز في حق الله سبحانه، وإذا قلنا إنه بمعنى الاختبار لم يجز في حق الله تعالى، لأن الاختبار للشيء لا يكون إلا للجاهل به، وذلك محال في حق الله سبحانه لعلمه بما يكون فبل أن يكون، فكيف بعلمه بما كان خفيَ، والعدم أخفى من الوجود الخفيّ.\r"], [581, "المسألة الثانية: في المختار\r"]], "pg": [580, 581]}, "561.384": {"x": [[581, "قد بيّنّا فيما سلف أن حكم اللغة في الألفاظ متى جوّزها العقل لم تُنف، فكيف إذا ورد بها الشرع، فإن الخبير في اللغة العليم بعد الخبرة، فلا ينبغي إنكاره، فإن الشرع قد ورد به، قال تعالى: \"ليبلوكم أيّكم أحسن عملاً\" (هود 7)، \"وَلَنَبْلُوَنَّكُمْ حَتَّى نَعْلَمَ الْمُجَاهِدِينَ مِنْكُمْ وَالصَّابِرِينَ وَنَبْلُوَ أَخْبَارَكُمْ\" (محمد 32)، قال الناس كلهم: معناه لنختبر.\rوالصحيح عندي أنه سبحانه خبير بمعنى أنه عليم ابتداء بما يعلمه الخلق بعد الخبرة، كما هو عليم بالنظريات ابتداء، وإن كان الخلق لا يعلمونه إلا بعد النظر، فهو خبير من غير خبرة، عليم من غير نظر.\rوالنكتة فيه أن علمه لا تقترن به آفة ولا يلحقه نقص كما بيّنّاه، وإنما هو مطلق كامل، وإن كان قد ورد لفظ الابتلاء مضافا إليه في قوله: \"ولنبلونّكم\"، لكن يرجع هذا اللفظ، الذي يجوز معناه في الخلق ويستحيل على الله، إلى علم المشاهدة، كما قال علماؤنا.\rوبيانه أن الباري تعالى عالم الغيب والشهادة؛ فيعلم الشيء قبل كونه وهو معدوم، فإذا وُجد عَلِمَه موجودا، وإذا عُدم عَلِمه معدوما، فالعلم مسترسل على أحواله الثلاث يتعلّق بها، والاختلاف يرجع إليها وهو على حاله.\r"], [582, "وإنما كان العلم بالاختبار نقصا في حق الجاهل به قبل الاختبار، كما كان علم الشهادة نقصا في حق الجاهل بعلم الغيب، ولهذا ضلّ جهم وجماعة من الفلاسفة فقالوا: للباري علوم حادثة، وظنّوا أن حدث المعلوم يوجب حدث العلم، وليس كذلك كما بيّناه.\rوقد ضرب بعض علمائنا لذلك مثالا يستروح إليه الطالب فقالوا: إن زيدا يعلم أن الشمس تطلع غدا، فعلمه يتعلّق بطلوع الشمس معدوما، فإذا بقيت حياته وعلمه إلى غد وعاين إلى طلوع الشمي تعلّق بها علمه موجودةً، فإذا غربت تعلّق علمه بها معدومة، لكن العبد يتجدد علمه في كل حالة، والباري سبحانه علمه دائم مستمر، فإذا قدّرت دوام العلم للعبد استتبّ لك المعنى وانكشف الغطاء، وهذا بيان ليس وراءه مطلب.\rالمسألة الثالثة: في التركيب\r"]], "pg": [581, 582]}, "561.385": {"x": [[582, "إذا قلنا إنه العالم بما بطن فقد تبيّن، وإن قلنا إنه الخبير بمعنى أنه المُخبر رجع إلى الكلام، وكان بمعنى المُبِن على ما يأتي بيانه إن شاء الله.\r"], [583, "الفصل الرابع: في التنزيل\r"]], "pg": [582, 583]}, "561.386": {"x": [[583, "المنزلة العليا للرب:\rإذا علم العبد بأن الباري خبير بمعنى أنه عالم بما بطن، فللباري في ذلك حكم، وهو علمه بما يكون قبل أن يكون.\rالمنزلة الثانية للعبد:\rفيها حكمان:\rأحدهما: أن يُسلّم في أموره كلها إليه، كما روي عن إبراهيم الخليل أنه قال: \"حسبي من سؤالي علمه بحالي\".\rالثاني: أن يكون خبيرا بأحواله وصفاته وبواطنه؛ حتى يميّز خيرها من شرّها، ونفعها من ضرّها.\r"], [584, "الاسم السادس: الطبيب\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [583, 584]}, "561.387": {"x": [[584, "هذا اسم لم يرد به القرآن، ولا ورد في حديث أبي هريرة المفسَّر، لكن صحّ أن أبا رمثة رفاعة بن يثربي قال للنبي صلى الله عليه وسلم: \"إني رجل طبيب، فقال النبي صلى الله عليه وسلم: لا طبيب إلا الله عز وجل\"، وفي رواية قال له: \"الله الطبيب، بل أنت رفيق\"، وقالت عائشة رضي الله عنها لأبي بكر الصديق في مرضه: \"ألا ندعوا لك طبيبا، فقال: الطبيب أمرضني\".\r"], [585, "الفصل الثاني: في شرحه لغة\r"]], "pg": [584, 585]}, "561.388": {"x": [[585, "الطبيب الحاذق بالشيء الفطن له، يقال: فلان طبٌّ بكذا، والطبّ السحر، كُنّي بالطب عن السحر كما كنّي بالسليم عن اللديغ، كأنه حرف من الأضداد.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [585, 585]}, "561.389": {"x": [[585, "إذا كان الطبيب في اللغة العالم بالشيء، فالباري تعالى هو العالم بكل شيء كما بيّنّاه، ولكن حقيقة الطب في اللغة العلم بالشيء الخفيّ الذي لا يبدو إلا بعد معاناة لفكر صافٍ ونظر وافٍ، والباري هو الذي علم الأمور الظاهرة والخفيّة واطّلع على الكل، من غير معاناة ولا فكر.\rالفصل الرابع: في التنزيل\r"]], "pg": [585, 585]}, "561.390": {"x": [[585, "يختصّ الباري في المنزلة العليا في هذا الاسم بأنه عالم بما يخفى.\rويختصّ العبد بأن يعلم بأن الطب بيده لا بيد أحد من خلقه، والناس رفقاء، والطبيب الله.\r"], [586, "الاسم السابع: المُحصي\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [585, 586]}, "561.391": {"x": [[586, "ورد به القرآن فعلاً، ولم يرد به اسماً، قال تعالى: \"وكلّ شيءٍ أحصيناه كتاباً\" (النبأ 29)، وقال: \"وأحصى كلَّ شيءٍ عدداً\" (الجن 28)، وقال في حديث أبي هريرة المفسَّر: المُحصي، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [586, 586]}, "561.392": {"x": [[586, "فيه لعلمائنا ثلاثة أقوال:\rالأول: أنه العلم، قال تعالى: \" أَحْصَاهُ اللَّهُ وَنَسُوهُ \" (المجادلة 6)، وقال النبي صلى الله عليه وسلم: \"ومن أحصاها دخل الجنة\"، يعني من علمها.\rالثاني: أنه العدد، ومنه: \" وَأَحْصَى كُلَّ شَيْءٍ عَدَدًا\" (الجن 28)، ومنه قوله: \"استقيموا ولن تُحصُوا\"، معناه ولن تعدّوا ثواب الاستقامة، ومنه قوله: \"من أحصاها دخل الجنة\"، أي علمها مُعدّدة في أحد القولين.\r"], [587, "الثالث: معناه القوّة، ومنه قوله: \"استقيموا ولن تحصوا\"، معناه ولن تطيقوا في القول الثاني.\rالفصل الثالث: في شرحه حقيقة وعَقْداً\"\r"]], "pg": [586, 587]}, "561.393": {"x": [[587, "وفيه مسألتان:\rالمسألة الأولى: في تركيب المعنى الاعتقادي على اللغوي\r"]], "pg": [587, 587]}, "561.394": {"x": [[587, "قال علماؤنا: إن كان المحصي هو العالم فقد تقدّم بيانه، وإن كان القادر فكذلك تقدّم بيانه أيضا، وإن قلنا إنه العادّ فذلك يرجع إلى إخباره عن العدد، وهو الكلام، كما قال: \" إِنَّمَا نَعُدُّ لَهُمْ عَدًّا\" (مريم 85).\rالمسألة الثانية: في المختار\r"]], "pg": [587, 587]}, "561.395": {"x": [[587, "قد تقدّم كلام علمائنا –رحمة الله عليهم- في المُحصي وهو قاصر، وقد ظنّ بعض المتأخرين منهم أن قوله: \"أحاط بكلّ شيءٍ علماً\" (الطلاق 12) هو قوله: \" وَأَحْصَى كُلَّ شَيْءٍ عَدَدًا\" (الجن 28).\rوالصحيح أن العلم إذا تعلق بالمعلومات من حيث كشفها وإيضاحها فهو علم، وإذا تعلق بها من حيث حصرها وتعلّق العلم بعددها من غير تقدير ذهول فهو عدّ وإحصاء، فالمتعلَّقان مختلفان، وقد خفي وجه اختلاف متعلَّقهما على الجميع، فالمُحصي هو العالم بالعدد.\r"], [588, "الفصل الرابع: في التنزيل\r"]], "pg": [587, 588]}, "561.396": {"x": [[588, "المنزلة العليا للربّ في هذا الاسم:\rوله فيها ثلاثة أحكام:\rالأول: -وهو المعظم- أنه يعلم عدد ما لا نهاية له.\rوالثاني: أنه لا تشغله الكثرة عن العلم؛ فسقوط الأوراق، وبَذْر الحبوب، وتبدّل الأحوال على الرطب واليابس؛ كل ذلك عنده محصىً معلوم.\rالثالث: أنه عنده مسطور على التفصيل مكتوب.\rالمنزلة الثانية للعبد:\rفينبغي له أن لا تكون أفعاله مهملة بأن تكون محصاة، فيُحصي الخير للعمل به، ويحصي الشرّ لاجتنابه، وقد قال صلى الله عليه وسلم للنساء: \"اعقدن بالأنامل فإنهنّ مسؤولات مستنطقات\"، وقيل: العاقل من عُدّت سقطاته.\r"], [589, "الاسم الثامن: المقدِّر\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [588, 589]}, "561.397": {"x": [[589, "هو من الأسماء التي لم يرد بها قرآن ولا سنة، وإنما ورد به فعلا، وأجمعت عليه الأمة إطلاقا، قال الله تعالى: \" فَقَدَرْنَا فَنِعْمَ الْقَادِرُونَ\" (المرسلات 23)، وقال: \" إِلَّا امْرَأَتَهُ قَدَّرْنَا إِنَّهَا لَمِنَ الْغَابِرِينَ\" (الحجر 60)، وقال النبي صلى الله عليه وسلم مخبرا عن موسى عليه السلام: \"أتلومني على أمر قد قدّره الله عليّ قبل أن أُخلق\".\rالفصل الثاني: في شرحه لغة\r"]], "pg": [589, 589]}, "561.398": {"x": [[589, "قال علماؤنا –رحمة الله عليهم- للتقدير ثلاثة معان:\rالأوّل الخبر، ومنه قوله: \"إِلَّا امْرَأَتَهُ قَدَّرْنَا إِنَّهَا لَمِنَ الْغَابِرِينَ\" (الحجر 60)، أي أخبرنا.\r"], [590, "الثاني: تخصيص الشيء بمقدار، كقوله: \"وقدّر فيها أقواتها\" (فصلت 9)، أي خلقها على مقدار، وقوله: \" فَقَدَرْنَا فَنِعْمَ الْقَادِرُونَ\" (المرسلات 23).\rالثالث: التضييق، كقوله: \" فظنّ أن لّن نقدر عليه\" (الأنبياء 86).\rالفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [589, 590]}, "561.399": {"x": [[590, "فيه مسائل، جماعها مسألة واحدة، وهي:\rالمسألة الأولى: في كشف حقيقة اللفظة\r"]], "pg": [590, 590]}, "561.400": {"x": [[590, "اعلموا –أرشدكم الله إلى المعلومات- أنّ قدّر بتشديد الدال مُضاعَف قَدَرَ بتخفيف الدال، وقولنا فعّل بتشديد العين يأتي على قسمين:\rأحدهما: بمعنى فَعَلْتُ، لا يراد بها التكثير، كقولنا: كلّمت وسوّيت.\rوقد تأتي ويراد بها التكثير، في كل فعل جرى على بناءٍ مخفّفا، وجاء على ذلك البناء مشدّدا.\rولقولنا قَدَر بتخقيق الدال في اللغة ثلاثة معان:\rأحدها: من القدرة، وسيأتي بيانه، والفعل منها يتعدّى بقولك \"على\"، تقول: قَدَرْت على الشيء.\r"], [591, "الثاني: قَدَرَ بمعنى قلّل، كقوله: \"فقدر عليه رزقه\" (الفجر 17).\rالثالث: قَدَرَ بمعنى علم، كقوله: \"وما قدروا الله حق قدره\" (الزمر 64)، وهو مقصودنا، وهو مضاف إلى المقدار.\rفيكون إذن قدر بمعنى علم مقدار الشيء، فإذا جاءت مطلقة كان هذا معناها، وإذا وردت مضاعفة رجع التضعيف إلى تأكيد المعنى الذي اقتضاه التخفيف في الثاني والثالث، ولم يرجع إلى الأول لأنه يتعدّى بحرف الجر، والفعل إذا تعدى بحرف الجر فضاعفْتَه خرج عن معناه لعلّة معلومة في التصريف ولكن رجوعه إلى الثاني مقيس غير مسموع، ورجوعه إلى الثالث مسموع، وإلى هذه المعاني الثلاثة يرجع كلّ ما في كتاب الله من هذه الألفاظ.\rفأما قوله: \"فظنّ أن لّن نقدر عليه\" (الأنبياء 86) فيرجع إلى القدرة في أحد القولين لمعنىً بديع، بيانه في كتاب المشكِلَين.\rإشارته:\rظن أن قدرتنا لم تتعلق بكونه في بطن الحوت، وترجع في القول الثاني إلى معنى التقليل، التقدير: فظنّ أن لن نقلّل مقداره ونصغّره.\rوأما قوله: \"وما قدروا الله حقّ قدره\" فمعناه ما عظّموه، أي ما علموا مقداره في الجلال، وقال: \"والذي قدّر فهدى\" (الأعلى 3) معناه علم\r"], [592, "المقادير، وقال: \"إنا كلّ شيءٍ خلقناه بقدر\" (القمر 49)، أي بعلم مقداره من خير وشر.\rيبيّنه قوله: \"وكلّ شيء فعلوه في الزبر وكل صغيرٍ وكبيرٍ مستطر\" (القمر 52 - 53)، وقال صلى الله عليه وسلم في هلال الشهر: \"فإن غُمّ عليكم فاقدروا له\"، أي اعلموا قدره بإضافته إلى الشهر الذي قبله، وقالت عائشة: \"فاقدروا قدر الجارية الحديث السن الحريصة على اللهو\"، وقال عن موسى: \"أتلومني على أمر قدّره الله عليه قبل أن أُخلق؟ \" فقوله قدّر هو تضعيف قوله قَدَرَ.\rوقد يستعمل قدر على معنى وضع الشيء على مقادير معلومة، لأن الوضع يكون عن القدرة والعلم، فسُمّي به كقوله: \" فَقَدَرْنَا فَنِعْمَ الْقَادِرُونَ\" (المرسلات 23) فجمع بين اللغتين، كما قال الشاعر:\r"], [593, "وأنكرتني وما كان الذي أنكرت *** من الحوادث إلا الشَّيْب والصَّلعا\rوقال آخر:\rأمّا ابن طوقٍ أوفى بذمّته *** كما وفى بقِلاصِ النّجم حاديها\rوأفاد بقوله \"فَقَدَرْنَا\" علمنا متعلَّق القدرة، وبقوله: \"فنعم القادرون\" تحقيق القدرة، وتقول: نزلت الشيء أي فعلت فيه النزول، ويقال: نزّلته بمعنى عرّفته المنازل، وفي الحديث الصحيح قال سلمة بن كُهيل: \"فنَزَلني زيد بن وهب منزلا منزلا حتى مررنا على قنطرة\" وذكر الحديث.\r"], [594, "فتبيّن من قوله: \"قدّر فهدى\" أنه علم مقادير أهل الشقاء والسعادة، ثم هدى من شاء منهم هُداه، ويُركَّب قوله قدّر مضاعفا على قوله قدَر مخففا، وكلاهما بمعنى عَلِم.\rوتحقيقه أن تسمية المقدار المعلوم قَدَرا، كما يسمّى المقدور المخلوق قدرةً، والمعلوم علما، فلذلك سمّينا الفعل الصادر المتعلَّق به علم المقدار تقديرا كما بيّنّاه في ملجئة المتفقهين، فهو موضعه.\rفإن قيل: فأين كلامكم مع القدرية في القدر، واختلافكم وإيّاهم فيه، وإطنابكم في شرحه وأدلّتكم عليه؟\rفأما إذا قلتم: إن القدر هو العلم، فلا تخالفكم القدرية فيه، فإنهم يقولون: إن الله عالم بكل شيء، وبكلّ مقدار.\rالجواب:\rأنّا نقول: ليس خلافنا معهم في شيء من ذلك، وإنما خفي على علمائنا طريق معرفة الألفاظ فبَنَوا القول معهم على التسامح فيها، وإنما الخلاف بيننا وبينهم في أصل واحد، وهو أن الله خالق أعمال العباد كلّها بقدرته،\r"], [595, "خيرها وشرّها، وهم يقولون: إن الله قدر الخير والشر، ولكنه لم يخلقه ولا أوجده، وإنما خلق للعباد قدرة يخلقون بها ما يشاؤون، ولهذا سُمّوا قدريّة؛ لأنهم جعلوا القدرة والخلق لأنفسهم، ويقولون كما نقول: آمنت بالقدر خيره وشرّه، وهو علم الله للأشياء عندهم، وخلقه لها عندنا.\rأما علمه بها فاتفاق منا ومنهم، وأما خلقه لها بقدرته وإرادته إياها، فخلقه بقدرته عندنا، ولم يخلقها عندهم، وأرادها عندنا، ولم يردها عندهم، فالخلاف بيننا وبينهم في تعلُّق القدرة والإرادة بالشرور والمعاصي، وقد خقّقنا ذلك في كتاب المُقسط، وقد اندرج القول في الاعتقاد في بينا الحقيقة وانكشف الغطاء عنه.\rالفصل الرابع: في التنزيل\r"]], "pg": [590, 595]}, "561.401": {"x": [[595, "للباري تعالى فيه المنزلة العليا التي لا تنبغي إلا له؛ بوضع المخلوقات على مقادير محكمة متناسبة لا يطّلع الخلق على جُمَلها، فكيف على تفاصيلها، والْحَظوا ذلك –قوّى الله أبصاركم وبصائركم- من الذرّة إلى العرش تروه كذلك.\rوعلى العبد في منزلته ألّا يرسل كلامه حتى يناسب عقده وفعله، وألّا يُقدم على اكتساب فعل حتى يعرضه على نيّته وكلامه، فيأتي حينئذ على قدر بفضل الله ورحمته.\r"], [596, "الاسم التاسع: الرقيب\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [595, 596]}, "561.402": {"x": [[596, "ورد به القرآن والسنة، قال الله تعالى: \"وكان الله على كلّ شيءٍ رقيباً\" (الأحزاب 52)، ووردت به السنة في حديث أبي هريرة المفسَّر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [596, 596]}, "561.403": {"x": [[596, "فيه لعلمائنا ثلاث عبارات:\rالأولى: قال الزجّاج: الرقيب الحافظ، يقال: رقبْتُه أرقُبُه رِقْبةً ورُقوباً.\rالثانية: المراقِب وهو المنتظر.\rوله ثلاثة أبنية، تقول: رقبتُه أرقبُه، وارتقبتُه أرتقبُه، وترقّبتُه أترقّبُه، قال تعالى: \"ما يلفظ من قولٍ إلا لديه رقيبٌ عتيدٌ\" (ق 18)، وقال: \"فارتقب يوم تأتي السمآء بدُخَانٍ مُّبينٍ\" (الدخان 9)، وقال: \"فخرج منها خآئفاً يترقّب\" (القصص 20).\r"], [597, "الثالثة: الرقيب الموكَّل.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [596, 597]}, "561.404": {"x": [[597, "وفيه أربعة مسائل:\rالمسألة الأولى: في تحقيق الرِّقبة\r"]], "pg": [597, 597]}, "561.405": {"x": [[597, "اعلموا –رزقكم الله المراقبة- أن كل من تكلّم في الرقبة إنما أخذ طرَفاً من معناها وترك الإيعاب بالبيان لها، ومن استولى عليها بالبيان –وهو نادر- قال: إن الرقبة تنتظم من ثلاثة معان:\rالأول: العلم بالمرقوب.\rالثاني: المحافظة على دوام العلم.\rالثالث: أن يقترن ذلك بمتعذِّر كونه أو ممنوع منه، فلا بدّ من حفظٍ وتعذُّر كونٍ أو منعٍ منه.\rوهذا القول وإن كان أوعب لمعنى الرقبة لكن فيه تجوُّز في المعنى والعبارة.\r"], [598, "والصحيح أن الرقبة علم دائم بالمرقوب، موجودا ومعدوما، حاضرا وغائبا.\rالمسألة الثانية: في العقد\r"]], "pg": [597, 598]}, "561.406": {"x": [[598, "إذا ثبت هذا في معنى الرقبة، فمعنى وصفنا الله تعالى بأنه رقيب؛ أي العالم الذي لا يذهب عليه شيء، ولا يفوته أمر؛ ولا يصحّ أن يوصف برِقْبة الانتظار أو التحرّز عن الغفلة، لأن ذلك كله إنما يكون من الجاهل الناسي، وذلك في وصفه تعالى محال، وإنما رِقبته علمه الدائم.\rالمسألة الثالثة: وصفه تعالى بالرِّقبة\r"]], "pg": [598, 598]}, "561.407": {"x": [[598, "مما يُشكِل أنه من صفات الذات أو من صفات الفعل، لأنك إذا نظرت إلى لفظ الرقبة وجدتها ترجع إلى العلم بالمرقوب، وأن ترى أن المرقوب مخلوق، فلا بدّ من وجوده في الظاهر في معنى الرقبة.\rوتحقيقه أن الرقبة عبارة عن علم يتعلّق بالموجود، فهو كقولنا عالم الشهادة، وهو عالم الغيب، وليس ذلك بتغيّر في العلم بين غيب وشهادة،\r"], [599, "ولا باختلاف صفة فيه، وإنّما يرجع الاختلاف إلى المعلوم، فهو إذن من صفات الذات، وما يُتوهّم في الرقبة من معنى الحفظ إنما يرجع إلى العلم كما بيّنّاه في اسم الحفيظ.\rالمسألة الرابعة:\r"]], "pg": [598, 599]}, "561.408": {"x": [[599, "ظنّ بعض علمائنا أن الرقبة من صفات الأفعال، وأنها راجعة إلى تأويل حفظه لئلّا تضيع، وهي وَهلة عظيمة، وقد بيّنّا أن حقيقة الرقبة العلم، وبيّنّا وجه الحفظ وأنه يرجع إلى معنى العلم، وأن الوجود لا يُشترط فيه، والعدم لا يمنع منه، كما لم يمنع من أن يكون عالما بالشهادة وهو عالم بالغيب، فيتغيّر المعلوم والعلم لا يتغيّر، كذلك يتغيّر المرقوب والرّقيب لا يتغيّر.\rالفصل الرابع: في التنزيل\r"]], "pg": [599, 599]}, "561.409": {"x": [[599, "إذا علم العيد وصف الرقبة في ربّه، وتحقَّقه في عقده، فليعلم أن للباري في ذلك أحكاما يختصّ بها، أهمّها:\rأنه لا يشغله شأن عن شأن، وإن كان كلّ يوم هو في شأن، لعموم العلم وسعة القدرة.\r"], [600, "المنزلة السفلى للعبد:\rيتعيّن عليه فيها فرض المراقبة، فإن الله يطّلع عليه من حيث لا يراه، كما قال صلى الله عليه وسلم: \"فإنك إن لم تكن تراه فإنه يراك\"، فعليه أن يكون هذا الاعتقاد عليه دائما، وأن يعمل بحَسَبه خشية الاطّلاع عليه، وقد أحسن الشاعر حين قال:\rإذا مل خلوْتَ الدهر يوماً فلا تقل *** خلوتُ ولكن قول عليّ رقيبُ\rولا تحسبنّ الله يغفُلُ ساعةً *** ولا أن ما يخفى عليه يغيبُ\rلَهَونا لعَمْر الله حتى تتابعت *** ذنوبُ على آثارهنّ ذنوبُ\r"], [601, "الاسم العاشر: القريب\rوفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [599, 601]}, "561.410": {"x": [[601, "ورد به القرآن، قال الله تعالى: \"وإذا سألك عبادي عنّي فإنّي قريبٌ\" (البقرة 185)، وورد في حديث أبي هريرة من طريق عبد العزيز بن الحُصَين، وجاء في الصحيح قال النبي صلى الله عليه وسلم: \"إنكم لا تدعون أصمّ ولا غائباً، ولكن تدعون سميعا قريبا، إنه بينكم وبين رؤوس رحالكم\".\rالفصل الثاني: في شرحه لغة\r"]], "pg": [601, 601]}, "561.411": {"x": [[601, "القرب في اللغة دُنوُّ الأجسام بعضها من بعض، وذلك بصغر الأبعاد التي تكون بينها، فإمّا أن تكون متصلة وإمّا أن تكون منفصلة، فإن كانت متصلة\r"], [602, "فهي التجاور أو الاختلاط، وإما أن تكون منفصلة بأن يكون بينها بعدٌ، فإن كان يسيرا كان ذلك قرباً، وإن كان كثيرا كان ذلك بعداً، ثم نُقل إلى قرب المعاني مجازا، فيقال: فلان قريب من فلان بالمودّة، وفلان بعيد من فلان بالعداوة، وفلان قريب من فلان بالعلم، وبعيد منه بالجهل.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [601, 602]}, "561.412": {"x": [[602, "أمّا وصف الباري بقرب المسافة وبُعدها فمُحالٌ، لأنه ليس بجسم مؤلَّف، وأما وصفه بقرب العلم والمحبة فصحيح، وعلى قرب العلم يدلّ قوله تعالى: \"وإذا سألك عبادي عنّي فإنّي قريبٌ\" (البقرة 185) يعني بالعلم، وقيل بالمحبة، وقد يقال في المخلوق: إنه قريب من الله، على معنى قربه من تعلّق القدرة، كما روي عن النبي صلى الله عليه وسلم أنه كان إذا رأى المطر أبرز له وجهه الشريف وذراعيه الكريمتين، ويقول: \"هذا قريب عهدٍ بربّه\"، وهذا بيّن جدا.\rالفصل الرابع: في التنزيل\r"]], "pg": [602, 602]}, "561.413": {"x": [[602, "إذا تحقّقت معنى القرب في وصفه فله في المنزلة العليا ثلاثة أحكام:\rالأول: أنه لا يختصّ بمكان.\r"], [603, "الثاني: أنه لا يتقدّر بقرب مسافة.\rالثالث: أنه لا يخفى عليه شيء.\rوعليك في المنزلة السفلى المراقبة له كما تقدّم، وألّا ترفع صوتا إذا قصدته بكلامك وحده، فإن أردت غيره فارفع صوتك لتُسمع، فقد روي في الحديث: \"أن أبا بكر كان يخفي صوته بالقراءة، ويجهر عمر بها، فقال لهما النبي صلى الله عليه وسلم في ذلك، فقال أبو بكر: أسمَعتُ من أناجي، وقال عمر: أُوقِظ الوَسْنان، وأطرد الشيطان، وأذكر الرحمن\"، وكلاهما غرضان حسنان.\r"], [604, "الاسم الحادي عشر: رابع ثلاثة وسادس خمسة\rوفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [602, 604]}, "561.414": {"x": [[604, "قد ورد به القرآن، قال الله تعالى: \"مَا يَكُونُ مِن نَّجْوَى ثَلَاثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ\" (المجادلة 7).\rالفصل الثاني: في شرحه لغة\r"]], "pg": [604, 604]}, "561.415": {"x": [[604, "العرب تقول: فلان رابع القوم، إذا كان مشاركا لهم في وجه، فتكون هذه الإضافة منبئةً عن تلك المشاركة.\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [604, 604]}, "561.416": {"x": [[604, "قد تقدّم ذلك في وصف القريب، قال تعالى: \"فإنّي قريبُ\" (البقرة 185)، والذي به كان قريبا به كان رابع ثلاثة وسادس خمسة، وهو العلم\r"], [605, "والإحاطة بالسرائر، كما قال في موضع آخر: \"يعلم سرّكم وجهركم\" (الأنعام 4)، وكما قال النبي صلى الله عليه وسلم: \"إنه بينكم وبين رؤوس رحالكم\"، فعاد ذلك إلى صفات الذات، وما هو لم يزل عليه، والعلم واحد على ما تقدّم بيانه في حقيقة تعلّق العلم بالمعدوم، والله أعلم، وإن لم يكن له ثانٍ في قِدمه، وذلك لأنه عالم بالغيب عالم بالشهادة، إذا وقعت فيختلف المعلوم، ولا يختلف العلم ويتعدّد.\rالفصل الرابع: في التنزيل\r"]], "pg": [604, 605]}, "561.417": {"x": [[605, "والتنزيل في الفصل الرابع كما سبق في اسم القريب حرفا حرفا، وأن الجهر عنده والإعلان سواء، كما روي عن ابن مسعود أنه قال: \"اجتمع عند البيت ثلاثة نفر؛ قرشيان وثقفي، أو ثقفيان وقرشي، قليلٌ فقه قلوبهم، كثيرٌ شحم بطونهم، فقال أحدهم: أترون أنه يسمع ما نقول؟ وقال الآخران: يسمع إن جهرنا ولا يسمع إن أخفينا، فأنزل الله: \"وما كُنْتُم تَستَتِرُونَ أن يَّشهدَ عَلَيكُمْ سَمْعُكُمْ\" الآية (فصلت 21).\r"], [606, "القول في اسم الحيّ\rوهو اسم مفرد ليس له نظير، وهو أربعة فصول:\r"], [607, "--\r"], [608, "الفصل الأول: في مورده\r"]], "pg": [605, 608]}, "561.418": {"x": [[608, "ورد به القرآن: قال الله تعالى: \"هُوَ الحَيُّ\" (غافر 65)، وقال تعالى: \"الحَيُّ القَيّومُ\" (البقرة 255)، ووردت به السنة في حديث أبي هريرة مفسَّرا، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [608, 608]}, "561.419": {"x": [[608, "اعلموا وفّقكم الله أن العرب ما كان يخفى عليها اسم الحياة والحيوان والحي، بل أكثرت التصريف له.\rيقال: حَيِيَ الرجل يحيى حياة، وحيَّ أيضا بتشديد الياء، وقيل حايِيٌ على وزن فاعل، والحِيّ بكسر الحاء الحيوان، وهو جنس الحَيّ، وقيل هو الحياة، واختلفوا فيه اختلافا كثيرا، والحيّ نحوٌ من القبيل، سُمّي به مجازا، لأن به يستعينون على حماية أنفسهم، وحياة مواشيهم بالخِصب ورَعْيِ الحيا وشربه وهو المطر.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [608, 608]}, "561.420": {"x": [[608, "وفيه خمس مسائل:\r"], [609, "المسألة الأولى: في تحقيق الحياة\r"]], "pg": [608, 609]}, "561.421": {"x": [[609, "وهي وصف للجسم، عرضٌ إذا وُجدت بالذات؛ جسما كان أو جوهرا، كان درّاكا فعّالا، وكانت العرب إذا رأت الإدراك والحسّ قالت: هذا حيّ.\rالمسألة الثانية:\r"]], "pg": [609, 609]}, "561.422": {"x": [[609, "اعلموا –وفقكم الله- أن الناس اختلفوا في الحياة والحي اختلافا كثيرا، منها القصد إلى تلبيس المعاني لتشيع البدع، وذلك الأكثر، أو جهلا بالأمر البيّن، وهو الأقل، وقد بيّنّا ذلك في كتاب المقسط.\rوالعقيدة فيه: أن الحي من له حياة في الشاهد؛ واختلف الناي في الغائب، فقال بعضهم: لا أقول إن الله حيٌّ بحياة، وإن قلت إنه عالم بعلم، من قِبَل أن التوقيف ورد بذلك في العلم، ولم يرد به في الحياة والسمع والبصر، والصحيح أنه حيّ بحياة كما بيّنّا في باب السمع والبصر.\rالمسألة الثالثة:\r"]], "pg": [609, 609]}, "561.423": {"x": [[609, "حياة الباري لا توصف بأنها روح، ولا يوصف هو تعالى بأنه روحاني، لوجهين:\r"], [610, "أحدهما: ما بيّنّاه في كتب الأصول، من الخلاف في الروح والحياة هل هما شيء واحد أم لا؟\rالثاني: أنه لا يرد في الشرع إذْن في ذلك فتوقفنا فيه.\rوالصحيح أنهما معنيان مختلفان، وقد بيّنّا ذلك في كتبه.\rالمسألة الرابعة:\r"]], "pg": [609, 610]}, "561.424": {"x": [[610, "قال الحارث بن أسد: إذا قلنا الحيّ فهو بالحقيقة المؤمن، لقول الله تعالى: \"لِّيُنذِرَ مَن كَانَ حَيًّاً وَيَحِقَّ الْقَوْلُ عَلَى الْكَافِرِينَ\" (يس 70).\r"], [611, "وقال: \"وَمَنْ كَانَ مَيْتًاً فَأَحْيَيْنَاهُ\" (الأنعام 122)، أي كافرا فأنعمنا عليه بالإيمان.\rوقال المتأخرون من علمائنا: هذا الذي قاله الحارث إنما هو على طريق التوسّع، لأن حياة الإيمان إنما شُبّهت بحياة الأبدان تمثيلا لا تحقيقا، ولكن المجاز قد يتّسع على مجرى الحقيقة، أو يربي عليه.\rالمسألة الخامسة: في المختار\r"]], "pg": [610, 611]}, "561.425": {"x": [[611, "قال كثير من علمائنا: إن الحيّ هو الفعّال الدرّاك، وهذا لا يصحّ من خمسة أوجه:\rالأول: أن الحي قد لا يفعل، وقد كان الباري تعالى في الأزل حيّا ولم يكن يفعل، وقد كان في الأزل ولم يكن فعلٌ، وكان مدركا لنفسه ولصفاته.\rالثاني: أن الإدراك معنىً غير الحياة وغير الفعل، فكيف يُفَسَّر معنىً بمعنىً مغاير له، وهذا تخليط للمعاني وإلباس على المريد للبيان.\r"], [612, "الثالث: أن أبا حامد قد قال: الحي الفعّال المُدرِك، وهو فاسد من وجهين:\rأحدهما: ما قدّمناه في الثاني.\rالرابع: -وهو الثاني- أن الإدراك معنىً يتقدّم على الفعل، فكيف يُفسَّر به.\rالخامس: -وهو الصحيح- كما تقدّم أن الحياة معنى إذا وُجد بالذات صحّ منه الإدراك والفعل، أما الإدراك فيلزمها؛ لأنه لا يصحّ حيّ غير مدرك، وأما الفعل فيصحّ منه، ولا يلزم فيه، وهذه غاية العبارة، فإنها معنى تعجز العبارة عنه، إذا لم يُوضع لها ما يدلّ على الخصوص عليها كالعلم، فإنه بيّن في القلوب، وليس له عبارة تخصّه بتمييز حقيقة، حسب ما رتّبناه في الأصول.\rالفصل الرابع: في التنزيل\r"]], "pg": [611, 612]}, "561.426": {"x": [[612, "اعلموا –وفّقكم الله- أن هذه الصفة –وهي الحياة- واجبة للباري تعالى، جائزة للعبد، يختصّ الباري تعالى فيها بأحكام خمسة:\rالاول: أنه لم تسبقها مَوَاتيَّةٌ، وهذا حكم يختصّ به.\r"], [613, "الثاني: أنه لا يلحقه موت، وهذا مثله؛\rالثالث: أنه لا يفتقر إلى بِنْيةٍ؛\rالرابع: أنه ليس له رطوبة ولا بِلّة؛\rالخامس: أنه لا يحتاج إلى غذاء، فإنه يُطعم ولا يُطعَم.\rالمنزلة الثانية للعبد:\rوهي أن كلّ حكم تقدّم لله من التقديس والكمال فهو للعبد على وصف النقصان، فإن حياته مسبوقة بالمواتيّة، مُعَقّبةٌ بالموت، وله البِنْية والرطوبة، ويحتاج إلى الغذاء.\r"], [614, "القول في وصف الإرادة\r"], [615, "--\r"], [616, "يتعلّق بهذا الوصف جملة من أسماء الباري تعالى وصفاته، فلا بدّ من ذكر مقدّمة تحصر الأسماء المتعلّقة بالإرادة حصرا جامعا مختصرا، ثم نعطف بعد ذلك على الأسماء بالبيان على الترتيب الأول إن شاء الله، فنقول:\rالحاضر في الخاطر من الأسماء المتعلقة بالإرادة ثلاثة وعشرون اسما:\rالأول: إرادة\rوهو أمّها، وحقيقته صفة شأنها تمييز الشيء عن مثله في الوجود وغيره.\rالثاني: مشيئة\rوقد فرّقت المبتدعة بينهما فرْقا لا يُعقل، وإن بينهما لفَرقا بيّنّاه في المتقدّم من أوصاف التنزيل، والإشارة إليه أنها الإرادة المتعلّقة بالوجود.\r"], [617, "الثالث: قَصْدٌ\rولم يرد به نص، لكن علماؤنا قالوا في قوله: \"ثُمَّ استَوَى إِلى السَّمَآء وَهِيَ دُخَانٌ\" (فصّلت 11)، أن معناه قصد، فالقصد على هذا عبارة عن تعلّق الإرادة بالوجود، فيكون القصد مع الإرادة كعلم الشهادة مع علم الغيب.\rالرابع: كراهية\rوهي عبارة عن إرادة عدم ما وُجد، أو وجود ما عُدم، فإذا وُجد الموجود بإرادة الوجود فالكراهية هي إرادة عدمه، فتعلّقت الإرادة بوجودٍ و عدم على هذا الوجه، فما اقترن من الوصفين بالقدرة فهو مُراد، وما عداه فمكروه على معنى أنه أريدَ به خلاف غيره، وهذه حقيقتهما في اللغة، أي إرادة عدم الموجود.\rالخامس: عزمٌ\rقال ابن فورك: \"لا يوصف به الباري لأنه لم يرد به نصّ كتابٍ ولا سنّة\"، ولم يعترض في معناه بنقض ولا آفة أكثر من عدم الإذن من\r"], [618, "الشرع في أطلاقه، وحقيقة العزم فينا عبارة عن جزم الإرادة بعد التردد فيها، والتردد في حق الباري محالٌ، فلمّا كان العزم يقتضي تقديم تردد اقتضى ذلك إيهاماً فامتنع علماؤنا عنه لأجله، على أنه قد ورد في الخبر إضافة التردد إلى الله تعالى في قوله: \"وما ترددت في شيء أنا فاعله تردُّدي في قبض روح عبدي المؤمن، يكره الموت وأنا أكره مساءَته\"، فلا وجه بعد هذا من امتناع إطلاقه، وقد بيّنّاه في كتاب المشكِلَين، وورد أيضا في حديث النبي صلى الله عليه وسلم خرجه مسلم عن أم سلمة أنها قالت: \"ثم عزم الله لي\"، وهذا نص يعرفه من قرأ الحديث وروى الكتاب.\rوفي الحديث الصحيح خرجه أبو داود وغيره، وذكر الحديث الذي فيه قال النبي صلى الله عليه وسلم: \"فإنا آخذوها وشطر مال، عزمة من عزمات ربنا\"، والله أعلم.\r"], [619, "السادس: رحمة\rوسنبيّن معناها في ذكر الرحمن الرحيم.\rالسابع: المحبّة\rوقد اختلف علماؤنا فيها على ثلاثة أقوال:\rالأول: أنها إرادة مطلقة.\rالثاني: أنها إرادة الثواب، فهو تعالى المريد لكل محدَث على الإطلاق، والمحبّ لما يريد أن يثيب عليه.\rالثالث: أنها مدح الشيء، فرجع ذلك إلى الكلام.\rالثامن: بُغضٌ\rوهو راجع عند علمائنا إلى إرادة ما يُعاقَب عليه، وهذا فيه نظر، لأنه قد يُضاف إلى الدنيا والشهوات المباحة في الأصل، وحقيقته عندي أنه\r"], [620, "إرادة ما يؤدي إلى العقاب، فإن المعصية تؤدي إليه بغير واسطة، والشهوات تؤدي إليه بواسطة وإن كانت مباحة، وفي الأثر: \"أبغض الحلال إلى الله الطلاق\".\rالتاسع: الرضى\rوفيه لعلمائنا ثلاثة أقوال:\rالأول: أنه الإرادة المطلقة.\rالثاني: أنه الإرادة لما يكون فوق الاستحقاق.\rالثالث: أن الرضى عبارة عن فعلٍ جميل، فرجع إلى صفات الفعل.\rالعاشر: السخط\rوهو عبارة عن إرادة خلاف الرضى كما تقدّم.\r"], [621, "الحادي عشر: المودّة\rقيل إنها الإرادة المطلقة.\rوقيل إنها المحبّة.\rوقيل هي عبارة عن فعل الجميل مع من يستحقه ومن لا يستحقّه، كقول النبي صلى الله عليه وسلم: \"مثل المسلمين في تراحمهم وتعاطفهم وتوادّهم كمثل الجسد، إذا اشتكى عضوٌ منه تداعى سائره بالحمّى والسهر\"، وكما قال أيضا: \"أن تصل من قطعك، وتعطي من حرمك، وتعفو عمّن ظلمك\".\rالثاني عشر: العفو.\rاختلفت فيه عبارة علمائنا على ثلاث عبارات:\rالاولى: الإرادة لمحو الحقوق.\rوقيل: هو الإرادة لتسهيل الأمور على أهل المعرفة به؛\rوقيل: هو إسقاط العقاب.\r"], [622, "الثالث عشر: الرأفة\rوهي عبارة هن شدة الرحمة، فهي ترجع إلى مبالغة في وصف الرحمة، وحقيقتها إرادة التخفيف بما على المرحوم في ثِقلٌ.\rالرابع عشر: ولايةٌ\rفهو الوليّ سبحانه، وذلك عبارة عن القرب بالمعنى، وهو نوع من الإرادة، يأتي بيانه إن شاء الله في اسم الولي.\rالخامس عشر: وصف العداوة.\rوهو عكسه.\rالسادس عشر: غضبٌ\rوهو يرجع إلى فعل العقاب، فيكون من صفات الفعل، ويدل عليه قوله: \"إن رحمتي سبقت غضبي\"، وقد يرجع إلى الإرادة على معنى التخصيص بحال العقاب.\rالسابع عشر: الاختيار.\rوقد بيّنّاه في كتاب المشكِلَين، فإنه من أشكَلِ لفظ، ومن علمائنا من قال: إنّ اختار فَعَلَ الخير، ومنهم من قال: إنّ اختار أراد الخير.\r"], [623, "الثامن عشر: اجتبى\rجعله بجهة وحيّز من الشر، مأخوذ من جبى الّركيّة.\rالتاسع عشر: اصطفى\rوهو يرجع إلى إرادة التطهير من العيب للمُطهَّر منه، افتعل من الصفوة.\rالمُوَفّي عشرين: الصبور\rوهو عبارة عن إرادة تأخير العقوبة عن من يستحقّ إنزالها به في الحال.\rالحادي والعشرون: الحِلم\rوهي عبارة عن إرادة إسقاط العقوبة عن من يستحقها.\rالثاني والعشرون: الكرم\rوهو إرادة إعطاء الخير الكثير لمن يستحقّ اليسير، ولكنه من صفات التنزيه، وقد بيّنّاه.\r"], [624, "الثالث والعشرون: البِرُّ\rوهو عبارة عن إرادة إكرام أهل الطاعة.\rوللباري تعالى بكلّ وصف من هذه الأوصاف اسم، وبها وبأمثالها تجاوز الأسماء عدد تسعة وتسعين، ولكن التعيين فيها لا يطّلع عليه أحد، وشرح هذه الأوصاف بمتعلّقاتها لا يفي بها الطوق، ولا يسعه الخلق، وفي هذه النبذة كفاية.\r"], [625, "الاسم الأول: مُريدٌ\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [612, 625]}, "561.427": {"x": [[625, "فنقول: هو اسم عظيم القدْر، إليه ردّ القاضي في الهداية الإثنين والعشرين اسماً المتقدمة وأمثالها، وزعم أنه لا معنى لها إلا الإرادة.\rوأقول لكم: إنه اسم لم يرد له في الكتاب ولا في السنة ذكر وإنما ورد مضافا إلى الله تعالى فعلا في قوله: \"يريد الله بكمُ اليسر\" (البقرة 185)، و \"إنما يريد الله ليُذهب الرّجس أهل البيت ويطهّركم تطهيراً\" (الأحزاب 33)، و أمثاله، وقد بيّنّا فيما سلف أن أسماء الله هل تقف على السمع في صيغ الأسماء أم تجوز بكلّ اسم\r"], [626, "كريم شريف، وذكرنا اختلاف علمائنا فيها، والصحيح عندي جوازه في الذكر، وأنه لا يُعدّ في الأسماء.\rأما جوازه في الذكر فلأمرين:\rأحدهما: ما فيه من الشرف والكرم والجلال.\rوالثاني: ما اتفق عليه أهل اللسان من أن كل بناء جاء منه فعلٌ فلا بدّ فيه من بناء فاعل، أو فاعل فلا بدّ فيه من بناء فعلٍ، أو فَعْلٌ ومصدر فلا بدّ فيه من بناء فِعل وفاعل إلا ما شذّ.\rالثالث: ما صحّ عن النبي صلى الله عليه وسلم أنه قال: قال الله: \"أنا الرحمن، وهي الرحِم، اشتققتُ لها اسماً من اسمي\"، فهذا نصٌّ في جواز الاشتقاق في كل وصف جلال وكمال.\rوقد قال ابن فورك رضي الله عنه كما قال القاضي: إن هذه الأسماء كلّها راجعةٌ إلى الإرادة؛ وقد بيّنّا في كتب الأصول أن هذا لا يصحّ، وأوضحنا أن الإرادة تتعلق بكل مراد صحيح أو فاسد، خير أو شر، طاعة أو معصية،\r"], [627, "إيمان أو كفر، والرضى والمحبة لا تتعلق بشيء من ذلك، فدلّ على صحة الاختلاف فيهما، وما تعلّقا به حتى اعتذرنا عنه في موضعه، وبيّنّا أنه لا حجّة فيه.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [625, 627]}, "561.428": {"x": [[627, "هو اسم مشهور عند الناس مفهوم عندهم، فلم يضعوا له شرحا، واختلف الناس فيه اختلافا كثيرا، فأمّا القاضي فقال: إنه القصد، وأن الإرادة والمشيئة وأمثالها بمعنىً واحد، وجرى في ذلك على عادته من تحديد الألفاظ بالألفاظ، كما قال في العلم المعرفة؛ والصحيح ما بيّنّاه في غير موضع من أنها صفة، شأنها تمييز الشيء عن مثله، وأنها معنى غير التمنّي والشهوة والتلهّف والأسف.\rالفصل الثاث: في شرحه حقيقة وعقدا\r"]], "pg": [627, 627]}, "561.429": {"x": [[627, "قد بيّنّا حقيقتها، واندرج الاعتقاد في أثنائها، وهي عندنا غاية في كل مخلوق، خير أو شرّ، نفع أو ضرّ، ولا يكون مخلوق إلا بإرادة الله.\r"], [628, "الفصل الرابع: في التنزيل\r"]], "pg": [627, 628]}, "561.430": {"x": [[628, "المنزلة العليا للربّ:\rأنه لا يكون إلا ما يريد\rالمنزلة السفلى للعبد:\rوذلك في حالتين:\rإحداهما: أن يعلم أنه لا يريد إلا أن يريد الله.\rالثانية: أن يرضى بعد ذلك بقضاء الله.\r"], [629, "الاسم الثاني: شاءٍ\rقولنا: شاءٍ من شاء.\rوالباري تعالى وإن كان قد اتفق جميع الأمة على وصفه بأنه قد شاء ويشاء، فلم يَرِد في كلامه ولا كلامهم شاءٍ، استغنوا عنه بقولنا مُريدٌ، وبكل وصف واسم ورد يتعلّق بالإرادة، وكذلك لم يصفوه بأنه قاصد، وإن كانت الإرادة هي القصد أو قريب منه، كما لم يصفوه بأنه عارف وبأنه ذاكر، استغنوا عنه بأنه عالم، هذا مع قولنا بأن لفظ عالم لا ينوب منابه اسمٌ كاملٌ مثله، وكذلك مريد لا ينوب منابه شاءٍ ولا قاصدٌ، حسب ما رتّبناه في كتب الأصول وبيّنّاه.\r"], [630, "الاسم الثالث والرابع: الرحمن الرحيم\rهما اسمان عظيمان بهما استفتح الله كتابه، حتى قال قوم: إن الرحمن هو اسم الله الأعظم، وهو المعنى المطلوب للخلق من الله، إليه حاجتهم، وهو رجاؤهم لا سيما وهو عامٌّ في الخلق كلّهم، على ما يأتي بيانه إن شاء الله، ولشرفهما قرنهما الله باسم الله، وقدّمهما على جميع الأسماء، وفيهما أربعة فصول:\rالفصل الأول: في موردهما\r"]], "pg": [628, 630]}, "561.431": {"x": [[630, "قد ورد بهما القرآن فاتحة كل سورة، ووصف نفسه في القرآن بأنه \"أَرْحَمُ الرَّاحِمِينَ\" (الأعراف 151)، و \"خَيْرُ الرّاحِمِينَ\" (المؤمنون 118)، ووردت به السنة، وروي عن رسول الله صلى الله عليه وسلم أنه قال: قال الله تعالى: \" أنا الرحمن، وهي الرحِم، اشتققتُ لها اسماً من اسمي، من وصلها وصلته، ومن قطعها بتتُّه\"، وأجمعت عليهما الأمة.\r"], [631, "الفصل الثاني: في شرحهما لغة\r"]], "pg": [630, 631]}, "561.432": {"x": [[631, "اختلف الناس فيهما، فمنهم من قال: إنهما مشتقّان من الرحمة، ومنهم من قال: إن الرحمن غير مشتقٍّ، والرحيم مشتق، والرحمة هي الرقة، يقال: رحمه رُحْما ورُحُما مثقّلة، ورحْمة ورحَمة مثقّلة ومَرْحَمَة، والاسم الرحمى، وقوله: \"إنّ رَحْمَتَ اللهِ قَرِيبٌ مِنَ المُحْسِنِينَ\" (الأعراف 56) قولٌ خارج على النسب، ويقال: رجل رَحُوم وامرأة رَحُوم، وما أقرب رُحْم فلان، أي ما أرحمه، وقد قال الله: \"\"وأقْرَبَ رُحْماً\" (الكهف 81)، وقرئت رُحُما، وأمّ الرُّحم مكة، والمدينة تسمّى المرحومة، والرحم أوشاج القرابة، وأصلها الرحم التي هي سبب الولد، وهي الرُّحم أيضا، وفي المثل: جزاك الله خيرا والرَّحم.\rالفصل الثالث: في شرحمها حقيقة وعقدا\r"]], "pg": [631, 631]}, "561.433": {"x": [[631, "فيه ستّ مسائل:\r"], [632, "المسألة الأولى: في سرد أقوال علمائنا\r"]], "pg": [631, 632]}, "561.434": {"x": [[632, "ولعظم هذا الاسم كثرت الأقوال فيه وتشعّبت، لكن نذكر الأشهر فيهما والمتأصِّل فنقول: فيهما على هذا الوجه تسعة أقوال:\rالأول: قال ابن عباس: هما اسمان رقيقان، أحدهما أرقّ من الآخر، ولم يعيّن الأرقّ.\rالثاني: قال الحسن: هما اسمان رقيقان، والرحيم أرقّ.\rالثالث: قال أبو عبيدة: الرحمن معناه ذو الرحمة، والرحيم هو الراحم، وربما سوّت العرب بين فَعْلان وفَعِيل، فقالوا: ندمان ونديم.\r"], [633, "الرابع: قال ثعلب: إنما جمع بينهما لأن الرحمن عبرانيّ الأصل، فجاء معه الرحيم العربي الأصل.\rالخامس: أن الرحيم تأكيد الرحمن.\rالسادس: أن رحمن عامّ في الخلق، ورحيم خاصّ بالمؤمنين.\rالسابع: قال عطاء: الرحمن في الرزق، والرحيم في المغفرة.\rالثامن: قال بعضهم: هو رحمن الدنيا والآخرة.\rالتاسع: هما بعنىً واحد، وقد تجمع العرب بين لفظين مشتقّين من أصل واحد وإن كان المعنى واحداً كقول الشاعر:\rوإن أدْنُ منه يَنْأَ عنّي ويبعُدِ\rالمسألة الثانية: في توجيه الأقوال اللغوية\r"]], "pg": [632, 633]}, "561.435": {"x": [[633, "أما من قال إنه غير مشتق فاحتجّ بأمور ثلاثة:\rالأول: قال: لو كان مشتقّا من الرحمة لاتّصل بذكر المرحوم، فقيل: الله رحمن بعباده، كما يقال رحيم بعباده.\r"], [634, "الثاني: أنه لو كان مشتقّا لما أنكرته العرب، حتى قال تعالى عنهم: \" وَإِذَا قِيلَ لَهُمُ اسْجُدُوا لِلرَّحْمَنِ قَالُوا وَمَا الرَّحْمَنُ\" (الفرقان 60).\rالثالث: أنه لو كان عربيا مشتقّا لم أتبعه بالرحيم قصد البيان فيه.\rوأما من قال إنه مشتقّ فاحتج بأمرين:\rأحدهما: أن (ر ح م ن) على وزن فَعْلان، ورحيم منها فعيل، كندمان ونديم.\rالثاني: أن معنى رحمن ذو الرحمة التي لا نظير لها، ولذلك لا يُثنّى ولا يُجمع، وبناء فَعلان بناء المبالغة، كما تقول: الإناء ملآن، والرجل شبعان، لغاية الامتلاء والشبع.\rالمسألة الثالثة: في توجيه أقوال العلماء في تفسيره\r"]], "pg": [633, 634]}, "561.436": {"x": [[634, "أما قول ابن عباس إن أحدهما أرقّ من الآخر فمعناه عنده أمران:\rأحدهما: أن الرحمن عامّ في الدنيا والآخرة، والمنافع والثواب، وأن الرحيم مختصّ بالثواب والعفو، فصار الرحمن خاصّاً في اللفظ لاختصاصه بالباري، عامّاً في المعنى، وصار الرحيم عامّاً في اللفظ لجواز تسمية غير الله به، خاصّاً في المعنى لأنه للمؤمنين في العفو والثواب.\rالثاني: أن تقدير رحمن كعطشان؛ إذا كان في تلك الساعة على تلك الحال، وإن لم يكن دائما، ووزن رحيم كقولك كريم، وهو نعتٌ دائم، فكان\r"], [635, "الدائم أرقّ من المؤقّت، ومن هذا المعنى قول الحسن، فإنه جعل الرحيم أرقّ لأنه خاصّ بالعفو عن الذنوب وتكثير الثواب؛ الذي هو المرء إليه أخوج وله أنفع.\rوأما قول ثعلب إنه عبرانيّ ولذلك أُتبع بالرحيم الذي هو عربي تبيانا له، فوجهه أن العرب لم تعلمه حتى قالت: وما الرحمن.\rوأما قول من قال إنهما متغايران؛ أحدهما عامٌّ والآخر خاصٌّ، فتابع لقول ابن عباس ومأخوذ منه.\rالمسألة الرابعة: في المختار من قول أهل اللغة\r"]], "pg": [634, 635]}, "561.437": {"x": [[635, "الذي يصحّ منها أنه مشتقّ، والدليل عليه الحديث الصحيح، قال النبي صلى الله عليه وسلم: قال الله: \"أنا الرحمن، وهي الرحم، اشتققت لها اسماً من اسمي، من وصلها وصلته\" الحديث المتقدم، وتدل عليه أيضا اللغة، فإن أهل العربية اتفقوا على أنه اسم موضوع للكثرة، يشهد لذلك البناء واللفظ، وذلك لأن رحمته وسمعت كل شيء.\rفأمّا قولهم: لو كان مشتقّا لاتّصل بذكر المرحوم فكذلك نقول، إنه يقال: الله تعالى رحمن بعباده، ورحيم بهم.\r"], [636, "وأما قولهم إن العرب أنكرته، ولو كان مشتقّا مما علموه لما أنكروه، فإن العرب لم تنكر معرفة الرحمن، لأنهم لو أنكروه لقالوا: ومن الرحمن، فلمّا قالوا: \"وما الرحمن\" دلّ على أنهم إنما سألوا عن صفته لا عن ذاته، وكيف ينكرونها وقد كانوا يقولون: رحمان اليمامة، وقال بعض شعراء الجاهلية:\rألا قَضَبَ الرحمن ربّي يمينها\rوأما إتباعه بالرحيم فعن ذلك جوابان:\rأحدهما: انه تأكيد للرحمة.\r"], [637, "فإن قيل: كيف بدأ بذكر الأبلغ وحكمه أن يكون تاليا؟\rالجواب: أنه إنما بدأ به لأنه خاصّ له شرعاً فكان أعرف فيه، فبدأ به لأنه إنما يُبدأ بالأسماء الأعلام، وبما كان أعرف، ثم يُعقَب بما بعده في الترتيب.\rالثاني: أنه إنما بُدئ به لأنه خاصٌّ معنىً، ليَخصّ به المؤمنين، كما قال: \"وكان بالمؤمنين رحيماً\" (الأحزاب 43).\rوالأول أصحّ لأنّا لا نقول: إن الرحمن أبلغ من الرحيم، ولا إن الرحمن أعمّ من الرحيم، فإن ذلك لا يثبت إلا بنقل صحيح أو لغة مستقرّة.\rوأما قول من قال إن تقدير رحمن كعطشان وهو مؤقّت، ورحيم كقولك كريم غير مؤقَّت، فلم يثبت التوقيت في الأول ولا انتفى عن الثاني لأمر يرجع إلى البناء، وإنما كان كذلك لأمر عاد إلى أحوال المعاني التي دلّ عليها البناء، فإنّ العطش غير لازم، والكرم في نفسه دائم.\rوأما قول ثعلب إنه عبرانيّ فخطأٌ بيّنٌ، بدليل جريانه في التصريف وإعرابه، وذلك قاطع، والصحيح أنهما بمعنىً واحد للتأكيد، كندمان ونديم.\r"], [638, "المسألة الخامسة: في المختار من أقوال العلماء في معناه الحقيق"]], "pg": [635, 638]}, "561.438": {"x": [[638, "ي\rاعلموا –وفقكم الله- أن ذلك يستدعي مقدمة في معنى الرحمة، وقد اختلف الناي فيها، فصار صائرون إلى أنها النعمة والإحسان، قالوا: والدليل عليه أمران:\rأحدهما: قوله صلى الله عليه وسلم: قال الله تعالى: \"إن رحمتي سبقت غضبي\"، ولا يكون التسابق إلا في الأفعال، وقوله صلى الله عليه وسلم: \"إن الله خلق مائة رحمة\"، وصفات الذات ليست بمخلوقة.\rالثاني: قالوا: إن الرحمة منا رِقّة وشفقة تقتضيها هَوادةٌ وميْلٌ، وذلك لا يجوز على الله تعالى، فدلّ أنها من صفات الأفعال.\rوالرحمة عند أهل السنة هي إرادة الإنعام، صفة من صفات الذات، لم تزل ولا تزال، كقولنا في علمه وقدرته، وقد دللنا على ذلك في كتب الأصول، وكيف يصحّ أن تكون الرحمة الإنعام وقد يُنعم من لا يرحم إذا أُكره على الإنعام، ولا يكون الراحم راحماً إلا إذا كان إنعامه على المُنعَم عليه بقصد إلى ذلك وإرادة له، فلذلك قلنا هو إرادة الإنعام.\rبلى، إن النعمة قد تسمّى رحمة؛ فإنها عن الرحمة صدرت، كما تُسمّى الأفعال قدرة وعلما لصدورها عن العلم والقدرة، ولذلك سُمّيت الجنة رحمة\r"], [639, "والنبوءة رحمة، فقال تعالى: \"وأدخلناه في رحمتنا\" (الأنبياء 75)، قيل الجنة، وقيل النبوءة، لقوله: \"يختصّ برحمته من يّشآء\" (البقرة 105)، يعني النبوءة في أحد الأقوال، وجميع نعم الله تعالى تسمّى رحمة، وتكون الرحمة منا شفقة ورقة تبعث على الإنعام والإحسان، وهي من الباري تعالى إرادة للإنعام والإحسان، وقد غَلِطَ ابن جنّي في هذه الآية غلطاً بيّنّاه في كتاب المشكلين.\rفإن قيل: إن الرحمة تستدعي مرحوماً فكيف نسمّيه راحماً في الأزل ولم يكن هنالك مرحوم؟\r"], [640, "الجواب: أن هذا تلبيس، فإن الرحمة وإن كانت تقتضي مرحوما فإن الرحمة لا تقتضيه بها مقرونا، كما يقتضي القادر المقدور والعالم المعلوم، وليس من شرطه أن يكون به مقرونا، فإن الباري تعالى كان في الأزل قادرا ولم يكن مقدور، كذلك يكون في الأزل راحما وإن لم يكن مرحومٌ.\rفإن قيل: فقولوا: إن معنى كونه راحماً نَفْيُ القسوة عنه، كما قال النجّار.\rقلنا: فقولوا: إن معنى كونه عالماً نفي الجهل، وكونه قادرا نفي العجز لا غير.\r"], [641, "ولمّا لم يصحّ ذلك في هذين لم يصحّ في مسألتنا، فإن تعلقوا بقوله: \"إن رحمتي سبقت غضبي\"، قلنا: لا يصحّ التعلّق به، فإن الرحمة والغضب عندنا يرجعان إلى إرادة الإنعام وإرادة العقوبة كما بيّنّاه، والشيء لا يصحّ أن يسبق نفسه، فإنما يرجع ذلك إلى أن الإنعام سبق الانتقام، فإن الباري تعالى بدأ الخلق بنعمته، وسُمّي الإنعام رحمةً لأنه صدر عن الرحمة، والانتقام غضبا، لأنه صدر عن الغضب، على معنى تسمية الشيء باسم مقدّمته وسببه الذي صدر عنه، وهو أحد قسمي المجاز.\rالمسألة السادسة: في معنى كونه أرحم الراحمين وخير الراحمين.\r"]], "pg": [638, 641]}, "561.439": {"x": [[641, "أما قوله أرحم فهو أفعل من رحم، كما أن رحيماً فعيلٌ من رحم، وهو عبارة عن مَزيّة في الرحمة، وذلك يرجع إلى ثلاثة أمور:\rأحدها: كمال الرحمة بنفي الآفات عن صفة الباري تعالى بها؛\rوالثاني: أن ذلك يرجع إلى كثرة ثمرة الرحمة، وهي الإنعام؛\rالثالث: أن كلّ راحم منّا يقترن برحمته غرضان:\rأحدهما: تحقيق الغرض بتوقّع العِوض في إنعامه، والباري تعالى لا يصحّ وصفه بغرضٍ في عِوض.\r"], [642, "الثاني: رفع الألم الذي يعتريه بالرقّة عند معرفة حاجة المحتاج، فهو إذا أنعم عليه الْتذّ برفع الألم الذي يعتريه والرقة التي يجدها لحاجة المحتاج، وذلك مما يتقدّس عنه الباري، فرحمته تعالى مقدّسة عن غرض في عِوض، أو عود نفعٍ إليه من ذلك، فصار أرحم الراحمين بهذه المعاني كلّها، وصار خير الراحمين بهذا المعنى الثالث حقيقة، ويصح من وجه أن يكون أيضا خير الراحمين بالوجوه كلها.\rفإن قيل: فكيف يكون أرحم الراحمين، وهو يرى المحتاجين والمساكين وأهل البلاء من العالمين، وهو قادر على أن يعُمّهم بالعافية، ويشملهم بالفضل في رفع الخِلّة وتمام المطلب ولم يفعل؟ والرحيم هو الذي لا يرى مُبتلىً ولا محتاجاً إلا وبادر إلى إماطة ذلك عنه؟\rأجاب عن ذلك بعض علمائنا بأن قال: \"إن الطفل الصغير ترقّ أمّه له فتمنعه من الحجامة والأب يحمله عليها مع شفقته الكاملة، لأنه يرى له فيها خيراً، وإن كانت بصورة الشر، وليس في الوجود شرّ إلا وفي طيّه خير، لو ارتفع ذلك الشرّ لبطل الخير الذي في طيّه وعاد ببطلانه شرٌّ أعظم من\r"], [643, "الأول\"، وضرب لذلك أمثلة ثم قال: \"فإن خطر لك شرّ ليس في طيّه خير فاتّهم عقلك في أن الشر المذكور ليس في طيّه خير، واتّهم عقلك في أن فعل الخير دون ذلك الشر ممكن، وبعد هذا كَشْف سرّ القدر المنهيّ عنه\"، وأنت أيها المخاطَب أظنّك عارفاً بسرّ القدر مُستغنياً عن هذه التمويهات والتنبيهات.\rقال الإمام الحافظ رضي الله عنه: عجباً لهذا العالم، على أنه رفيع العماد في العلم، كثير الانتقاد على ذوي الفَهم، ينتحي في جوابه هذا التوجيه، وينزل إلى الخامل الساقط عن الوجيه، بيْنا هو ينظر في الإله وصفاته، نزل إلى المخلوق ودناءاته، ولا يصحّ أن ينسبه إليه ولا يقيسه عليه.\rوقد كان علماؤنا الأوّلون قالوا: إن قياس الغائب على الشاهد لا يكون إلا في الطرق الأربعة المعلومة؛ وهي العلّة والحقيقة والشرط والدليل، وأباه الآخرون وقالوا: لا يُحمل الغائب على الشاهد بحال ولا في وجه، وكلّ\r"], [644, "حقيقة منهما في نفسها ذات استقلال، وهذا الإمام من أقواهم في ذلك شكيمة، وأمضاهم عزيمة، فكيف يسدّ هذا الباب في الحقائق والعلل ثم يفتحه في هذا الخلل بمثل ذلك من الزلل، ما أبعد الطفل من اللطيف، ويا بَوْن ما بين الحجامة والرحمة، وبعد أن نسْفُل معه عن هذا الغرض، ونعارضه فيما عرض، ونقارضه على ما اقترض.\rنقول: معتمد هذا الجواب على أربعة معانٍ:\rأحدها: أن كل شر ففي طيّه خير.\rالثاني: أن الشر الذي في طيّه خير لو قدّرنا زوال ذلك الشر لجاء شرّ أعظم منه.\rالثالث: أن شراً ليس في طيّه خير غير ممكن، فمن تصوّره فليتّهم عقله.\rالرابع: أن تحت كشف هذا الغطاء معرفة سرّ القدر الذي لا يُفشى.\rوهذه المعاني الأربعة كلّها تحكّمات باطلة، ودعاوٍ فاسدة.\rأما قوله إن كلّ شرّ ففي طيّه خير فلا يخلو أن يريد بقول في طيّه أنّ في\r"], [645, "عاقبته وخاتمته خيرا، أو يريد به أنه مقترن به ويصاحبه خير، أو يريد به أنه يشتمل على خير، فإن أراد به أنّ في عاقبته خيراً أو يقترن به خير فذلك باطل بعذاب أهل النار، فإنه شرّ ليس في عاقبته خير ولا يقترن به.\rوأما قوله –إن قاله- إنه يشتمل عليه فهذا بطال، فإن الضد لا يشتمل على الضدّ، ويبطل أيضا بعذاب أهل النار، فإنه شرّ لا يشتمل على خير، وكذلك في ضده نعيم أهل الجنة خير ليس فيه شرّ.\rوأما قوله لو قدّرنا زوال ذلك الشرّ لجاء شرّ أعظم منه فهذا باطل من وجهين:\rأحدهما: أنه دعوى.\rالثاني: أنّا نقول: يحتمل أن يكون يأتي شرّ أعظم منه، ويحتمل أن يأتي خير أعظم منه.\rوأمّا قوله: إن شرّا ليس في طيّه خير غير ممكن، فالأمر بالعكس، بل هو واجب، فإنّ الكفر بالله وعذاب الله، ومن وُلد كافرا، وعاش كافرا، ومات كافرا، ودام عليه عذاب النار، فهذا شرّ لا خير فيه، ولا يُعدّ على قول\r"], [646, "أحد، وإذا اتهمنا العقول فعلى أي شيء يكون التعويل؟ وهَبْك أنّا اتهمنا العقول فيما تكثر فيه مقدّمات النظر والدليل، فما يُعلم في الأوائل ويُتحقّق قطعاً من الدلائل كيف تُتّهم فيه العقول؟ وليس اتهام العقل فيما ذكرتَ أولى من اتهامه فيما ذكرنا، مما ثبت علمه وصح النظر فيه.\rوأما قوله: إن هذا سر القدر الذي لا يُفشى، والمُخاطَب به عارفٌ، فكل عالم يعلم سرّ القدر، وهو أن الله لا يُسأل عمّا يفعل، وإن زعمت أن له سرّا قيل لك: أتريد أن تردّ ما ظهر من الأدلة بما بطن من الدعاوي، هذا ما لا يرضاه حصيف.\rفإن قيل: فقد قال بعض الناس: إن أهل النار تحت رحمة الله ونعمته، فإنه كان في الممكن أن يكون العذاب أكثر مما عم فيه، فجَعْله على ذلك المقدار نوع من الرحمة، فنقول: هذا مما لم يقصده القائل المتقدِّم القول بقوله، فإنه ليس من الأسرار التي تُخفى ولا تُفشى، وإنما يدخل هذا في باب نعم الله التي لا تُحصى، وهذا القدر الذي حصل فيه أهل النار به هلكتهم، فما فوقه أمر لا يعود إلى رفقٍ بهم، فإنّ الجاني عندنا إذا ضُرب بالسياط حتى مات كان يمكن أن يُقطّع لحمه ويعذّب حتى يموت، ولا يقال إن ضربه\r"], [647, "بالسوط قصد الرفق به، وكذلك المرجوم بالحجارة مع المطعون بالحديد، بينهما تفاوت لا يقال إن طريقه الرفق، وإنما هي عقوبات وآلام واقعة بحسب الاتفاق عندنا، وعلى مقادير معلومة عند الله تعالى، وإن أراد القائل لما تقدّم هذا المعنى فبأيسر من التهويلات التي تقدمت يصل إلى هذا.\rفنقول: رحمة الله عامّة على أهل البلاء وعلى أهل العافية، ولكن يبقى عليه الداء الأعضل وهو أن يقال: لم ابتلاهم وهو قادر على أن يُعافيهم؟ والرحيم لا يبتلي ببلاء، لا سيما إذا لم يحتج إلى ذلك في دفع ضرّ أو جلب نفع.\rفإن قيل: لا يقدر على أكثر من ذلك، قيل له: لا خلاف بين أهل السنة أن الباري تعالى لو شاء لابتلى الخلق أجمعين، ولو شاء لعافاهم أجمعين، وإن شاء بتنويع الحال فهو أرحم الراحمين.\rوالمعنى الذي يحوم عليه هذا القائل أنا أعرف الناس به، وها أنا أجلوه لكم في منصًته، وأكشف خفيّ سريرته فأقول:\rإن قال هذا القائل لم ابتلى وهو أرحم الراحمين؟ قلنا له: لا يخلو أن تكون موحّدا مسترشدا أو معاندا ملحدا؛ فإن كنت معاندا ملحدا نكلّمك\r"], [648, "في الأسماء ولكنّا نشرع معك في الابتداء، وطريق الكلام مع الملحدة قد أوضحناه، وشرحه سائر العلماء في كتب الأصول.\rوإن كنت موحّدا مسترشدا فاعلم أن أسماء الله تعالى لا بدّ من تعلّق معانيها وأحكامها بالخلق، فلا تنظر إلى اسم دون اسم، ولا تتكلم في صفة دون صفة، فإن خصصت بعضها لم تكن ممن أحصاها، ولا كُتبتَ في أهل الجنة، كما وعد الصادق عليه السلام، ولكن انظر إلى جميع الأسماء ووفّها حقّها من المعنى، واعلم أن الخلق متصرّفون بين أسماء الله وأحكامها، دائرون بين متعلّقاتها لصحة معانيها ووجوبها، فإن كان ربّنا أرحم الراحمين فإنه شديد العقاب، وإن كان عفوّا فإنه منتقم، وإن كان هاديا فإنه مُضلّ، وإن كان غفّارا فإنه قهّارٌ، وهكذا في سائر الأسماء، فلو عافى جميع الخلق لما كان شديد العقاب ولا منتقما ولا مضلّاً ولا قهّارا، فكان تذهب متعلّقات هذه الصفات فتبطل في ذواتها وذلك محال، فتصرّف الخلق تحت أسماء الله تعالى، وأصاب كل فريق حكما من أحكامه ومعنى اسم من أسمائه، ولذلك\r"], [649, "كتب إلى الخلق كتابا كريما، وأرسله إليهم مع أمينه محفوظا مختوما، وعنونه لهم عنوانا محكما مختوما، فلمّا قرؤوه فإذا فيه: \"بسم الله الرحمن الرحيم حم تَنْزِيلُ الْكِتَابِ مِنَ اللَّهِ الْعَزِيزِ الْعَلِيمِ غَافِرِ الذَّنْبِ وَقَابِلِ التَّوْبِ شَدِيدِ الْعِقَابِ ذِي الطَّوْلِ لَا إِلَهَ إِلَّا هُوَ إِلَيْهِ الْمَصِيرُ\" (غافر 1 - 3)\rفإن قيل: ولم كانت أسماء الله تعالى على هذا التنويع؟ وهلّا كان أرحم الراحمين هادياً، ولم يكن في أسمائه ما يقتضي إلا الخير المطلق؟\rقلنا: قد شرطنا أنه لا يد من تعيين المتكلّم، فإمّا أن يكون موحّدا مسترشدا، فما سبق جوابه، أو يكون ملحدا، وهذا السؤال كلامه، والجواب له مشروح في كتب الأصول، وهو أيسر مَدْرَكاً وأخفّ مَحْملاً من الكلام مع الموحّد المسترشد بكثير.\rثم نقول له: وأي سرّ للقدر وكل صغير وكبير مستطر، وكل ما روي من الأخبار في ذكر سر القدر باطل لا أصلا له، فكيف يُتّخذ أصلا أمرٌ لا أصلا له، أم كيف يُبنى الاعتقاد على أسٍّ هارٍ؟\r"], [650, "يزيده تأكيدا أن هذا السر لا يخلو أن يكون مُدرَكا بالنظر أو بالخبر، فإن كان مدركا بالنظر فيجب أن يصل إليه كل ناظر، وكذلك نقول: إنه وصل إليه وحصل، وهو ما ذكرناه، وإن كان إنما يدرك بالخبر فليس فيه خبر صحيح، ولا أصلا ثابت.\rوقد أسرّ رسول الله صلى الله عليه وسلم إلى حذيفة أشياء لا يصح أن يكون هذا منها، فإن مثل عمر لا يخفى عليه أن لو كان سرّ القدر، وإنما كانت تلك الأسرار من معاني الولايات والفتن، اقتضت المصلحة إخفاءها عن عمر لكونه أحد الوُلاة، وهي لا يتعلّق بها حكم، حتى قد قيل: إن عمر أيضا كان يعلمها، وهذا كله لا يتعلق بما أشار إليه أصحاب هذا السرّ فاعلموه، ومن استراب فلينظر في موضعه يجده، وكم لي أن أطوي على هذه المُسْتَكِنّة، وأحمد الله على ما وهب من المعرفة به والمنّة، فقد خرجتُ لكم عنها، والله ينفع بها برحمته.\r"], [651, "الفصل الرابع: في التنزيل\r"]], "pg": [641, 651]}, "561.440": {"x": [[651, "اعلموا أن هذا الاسم على شرف مقداره واختصاصه به فقد أُمرنا أن نستَدِرّ معنى اسمه الأحسن وصفته العليا، ونتخلّق منها بما يصحّ لنا، قال النبي صلى الله عليه وسلم: \"إن الله لا يرحم من عباده إلا الرحماء\"، وللباري تعالى في هذا الاسم أحكام يختصّ بها ثلاثة:\rالأول: أنه يَعُمُّ بالرزق في دار الدنيا؛\rالثاني: أنه يُعافي أهل الجحود له ويرزقهم؛\rالثالث: أنه يغفر ذنوب من عرفه.\rوعلى العبد أن يَعُمَّ بنفعه مَن صاحبه وعاداه، ويُحسن إلى من أساء إليه، ويغفر لإخوانه.\r"], [652, "الاسم الخامس: الودود\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [651, 652]}, "561.441": {"x": [[652, "ورد به القرآن، قال الله تعالى: \"الغَفُورُ الوَدُودُ\" (البروج 14)، ووردت به السنة في حديث أبي هريرة المفسَّر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [652, 652]}, "561.442": {"x": [[652, "فنقول: اتفق أهل اللغة على أن المودة هي المحبة، فلا فرق عندهم بين قولهم ودود وبين قولهم محبّ، واختلف الناس في بناء فَعول هذا:\rفمنهم من قال: إنه بمعنى التكثير، كقولنا: ضَروب وقَتول.\rومنهم من قال: إنه بمعنى مودود، وهو مفعول؛\rومنهم من قال: إنه بمعنى مُفْعِل، أي يُوَدّد عباده إلى الناس، كما قال تعالى: \"سيجعلُ لهمُ الرّحمن وُدّاً\" (مريم 96).\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [652, 652]}, "561.443": {"x": [[652, "وفيه خمس مسائل:\r"], [653, "المسألة الأولى: في بيان ذكر أقوال علمائنا\r"]], "pg": [652, 653]}, "561.444": {"x": [[653, "وقد اختلف علماؤنا –رحمة الله عليهم- في المودّة والمحبّة على ستّة أقوال:\rالأول: أنها الإرادة المطلقة.\rالثاني: أنها إرادة الثواب، فالباري تعالى مُريد لكل مُحدَث، مُحبٌّ لما يريد أن يُثيب عليه.\rالثالث: أنها إرادة خالصة من الشوائب، مأخوذة من حَبَب الأسنان وهو صفاؤها.\rالرابع: أنه الإرادة الباقية، من قولهم أحبَّ بالمكان إذا أقام به.\rالخامس: أنها مدح الشيء، فرجع إلى الكلام.\rالسادس: أنها فعل الإنعام والإحسام، وكذلك قالوا في المودّة، إنها مأخوذة من الوَدّ، وهو العُود الثابت في الأرض.\rالمسألة الثانية: في ذكر احتجاجهم\r"]], "pg": [653, 653]}, "561.445": {"x": [[653, "أما القاضي وابن فورك في جماعة فزعموا أنّ كلّ وصف تقدّم ذكره راجع إلى الإرادة المطلقة، وتأوّلوا كلّ آية وردت وحديث روي.\r"], [654, "والذي عندي أن المحبة والرضى والمودّة لا ترجع إلى الإرادة المطلقة، وإنّما هي إرادة خاصة، بدليل تعلّق الإرادة بكل مُحدَث، وتعلّق المحبة والرضى ببعض المحدثات.\rالمسألة الثالثة: في المختار\r"]], "pg": [653, 654]}, "561.446": {"x": [[654, "الصحيح عندنا أن المحبة إرادة ما يُثاب عليه، فأما من قال إنها مشتقة من الصفاء أو الثبوت فهو قول يقرب من الصواب، ولكنه مائل إلى رسم التصوّف، قالوا: تصفيته على ثلاثة أوجه:\rالأول: تصفيته للأنبياء عن الكفر والمعصية والغفلة.\rالثاني: تصفيته للأولياء عن الكفر والمعصية، وإن كان فيهم عيب الغفلة.\rالثالث: تصفيته للموحّدين عن الكفر خاصّة، وإن كانت هنالك معصية وغفلة.\rفأما تصفيته للأنبياء فلا غبار عليها، لقوله: \"إِنَّ اللَّهَ اصْطَفَى آدَمَ وَنُوحًا\" (آل عمران 33).\r"], [655, "وأما تصفيته عن الكفر والمعصية يبقى كَدَرُ الغفلة فصفاؤه بالذرك.\rوأما تصفيته عن الكفر ويبقى كدر المعصية فتصفيته على ثلاثة أوجه:\rالأول: بالتوبة.\rالثاني: بالعفو.\rالثالث: بالنار، فيخلُصون من الذنوب كما يخلُص الذهب والفضة من الخبث، ويخرجون منها سبائك.\rوأما من قال إنها ترجع إلى الكلام، فضعيف، لأنه قد يُحبّ من لا يقول.\rوأما من زعم أنها فعل فمجازٌ، لأنه سمّى ما يصدر عن المحبة محبةً، وذلك جائز، لكنّا لا نردّ أسماء الله إليه، وربما نقول: إنه أحد معانيها حيث يًحسن ذلك فيها.\rوأما من قال إنه بمعنى مودود فقد أنكره بعض علمائنا، وقال: إنه لا يصح أن يكون فَعولا بمعنى مفعول، وإنما هو بمعنى فال، كقولنا شَكور، والصحيح أنه لا يمتنع ذلك في هذا الوصف.\r"], [656, "وقد زعموا أنه قد جاء فاعل بمعنى مفعول في قوله: \"لا عاصم اليوم من أمر الله\" (هود 43)، أي لا معصوم، وهذا لا يصح، وللآية معنى صحيح غير ما زعموا.\rوأما فعول بمعنى مفعول فكثير مُتصوَّر، كقولهم: ناقةٌ حلوبٌ، قال أهل اللغة: بمعنى محلوبة، وتحقيق هذا من لسان العرب يخرج بنا عن المقصود، فهو تعالى ودود مودود، وعنه عبّر بقوله تعالى: \"يُحبّهم ويُحبّونه\" (المائدة 54).\rوأمّا كونه بمعنى مُفعِل فقد أنكره بعضهم، ولا يمتنع لغة، والمعنى أنه يُوَدِّد أولياءه إلى خلقه، كما قال سبحانه: \"سيجعلُ لهم الرحمن وُدّاً\" (مريم 96).\rوالدليل على صحة ما اخترناه من أنها إرادة الثواب، أن الله أحبّ الأنبياء وابتلاهم بالمحن والأسقام، وأبغض الكفار ورزقهم في الدنيا العافية وتأتِّي الآمال، وما كان مع هذا مُحبّا في الأنبياء إلا لما أراد لهم من ثواب الآخرة، وقد بيّنّا من قبل في كتابنا هذا عموم الإرادة، فإذا خلُصت وتعيَّنت للخير وتعلّقت بالثواب فهي محبةٌ، وهذا معنى قول الصوفية إنه إرادة خالصة\r"], [657, "عن الشوائب والمحتمِلات، وتعيين متعلَّقها بالثواب، وإذا كانت صافية كذلك ثبتت واستقرت، والله أعلم.\rالمسألة الرابعة: في وجه تعلّق المحبة به تعالى\r"]], "pg": [654, 657]}, "561.447": {"x": [[657, "إذا كان معنى كونه ودودا محبوبا، فكيف تتعلّق المحبة به، وهي الإرادة أو نوع منها؟ والإرادة لا تتعلق إلا بالمُحدَث بخلاف العلم، فإنه يتعلق بالمُحدَث والقديم، لأن العلم لا يؤثر في تعلّقه بالمعلوم، فلذلك تعلّق بالقديم والمُحدَث، والإرادة لمّا كانت تؤثر تعلّقت بالمحدَث الذي يجوز عليه التأثير وحده، وكذلك لا نقول: أريد الله، فكيف يصح أن نقول: أحبّ الله؟\rالجواب: أنّا نقول: هذا سؤال كاع عنه بعض علمائنا، ووهم فيه بعضهم، ونحن نسفر عنه قناع القول؛\rفنقول: أما وهم هذا العالم ففي قوله بأنه يجوز أن نقول أريدُ الله وأحبّ الله، ولا فرق بينهما، والمعنى فيه: أريد تعظيمه، وهذا ضعيف.\rوالصحيح أن نقول: جاء الإذن الكريم بقول: \"يُحبّهم ويحبّونه\"، ولم يجئ في قولنا: أريد الله إذْنٌ.\r"], [658, "الثاني: أن نقول: قد قالت عائشة لرسول الله صلى الله عليه وسلم حين خيّرها: بل أختار الله ورسوله، المعنى: أراه خيرا لي من كل شيء من الدنيا، فجاء لفظ المحبة والاختيار مضافا إلى الله تعالى، ولم يجئ لفظ الإرادة لمعنىً صحيح، وهو الجواب.\rالثالث: أن الإرادة لمّا كانت تتعلق بالخير والشر، والطاعة والمعصية، لم تصح إضافتها إلى الله عز وجل، والمحبة لما كانت لا تضاف إلى الشر والمعصية أضيفت إليه سبحانه، وهذا هو الفرق الصحيح بين المحبة والإرادة، وكذلك يضاف الرضى إلى الله سبحانه، فقد روي عن النبي صلى الله عليه وسلم أنه كان يقول إذا سمع النداء: \"رضيت بالله ربّاً\".\rالمسألة الخامسة: أن الباري تعالى محبوب، فهل تتعلّق المحبة بذ"]], "pg": [657, 658]}, "561.448": {"x": [[658, "اته أم بأفعاله؟\rاختلف الناس في ذلك، فمنهم من قال: إنها تتعلق بذاته، وإليه صَغْوُ الصوفية، وقد أطنب فيه شيخنا أبو حامد في مقام المحبة، فشرح\r"], [659, "حقيقتها، ومهّد طريقتها، ثم جعل لها خمسة أسباب، وجعل الرابع منها محبة الشيء لذاته؛ لما يكون عليه من جلال وخلال، وجمال لذات الجلال، والخلال والجمال، وقال: إنّ الطباع مجبولةٌ على ذلك، والجمال ينقسم إلى قسمين: جمال ظاهر يُدرَك بنور البصر، وجمال باطن يُدرَك بنور البصيرة، كجمال الانبياء والعلماء؛ لعلمهم وفضلهم ودينهم، وأين هم من علم الله وجلاله؟ فيحقّ أن لا يُحبّ لذاته إلا الله، والمحبة بهذا السبب أقوى من الحبّ بالإحسان.\rثمّ جعل الخامس حبّ المناسبة؛ لكون الشيء منجذباً إلى شِبْهه، وأن المناسبة قد تكون في معنى ظاهر وهو الخلق، وقد تكون في معنى باطن وهي الأخلاق، وبين المخلوق والخالق مناسبة في المعاني الباطنة؛ وهي العلوم والقُدَر والإرادات، وهي الصورة التي خُلق عليها آدم، وبها استحقّ الخلافة، وإليه الإشارة بقوله: \"وَيَسْأَلُونَكَ عَنِ الرُّوحِ قُلِ الرُّوحُ مِنْ أَمْرِ رَبِّي\"، وبقوله: \"مرضت فلم تعدني\"، وبقوله: \"لا يزال العبد يتقرّب إليّ بالنوافل حتى أحبّه، فإذا أحببته كنت سمعه وبصره\"، فالله محبوب حقيقة لا مجازا بهذه الأسباب كلّها، هذا لُبَاب كلامه.\r"], [660, "قلت: يا ليته خبّأ هذا القول في جَنانه، وقبض دونه عنان لسانه، وترك كثيرا من هذا المقدار، اقتداء بقوله: قبور الأسرار صدور الأحرار، ولم يَخُض في شيء من هذه الأغراض، الجالبة إلى القلوب العللَ والأمراض، ولقد كان سيفه أحدّ، وسبقه أجدّ، من هذه الأغراض الفاترة، التي تدور بين طرفيْ نقيض، تصوّفٌ ليس له تصرّف، وتفلسف ليس بعده تعرّف.\rأما الأسباب التي ذكرها للمحبة فلا ضرورة تدعو إلى المناسبة فيها، والتطويل بتتبّع أغراضها ومعانيها، فلنبسط عليها رداء التسليم، ولا نخرج بها عن طُرِيق التعلم والتعليم.\rوأما الذي ذكره من السبب الرابع؛ وهو حب الجمال لذاته، فهو أمر منازَعٌ فيه، لا يُسلَّم له، سواء كان الجمال ظاهرا يدرك بنور البصر، أو باطنا يدرك بنور البصيرة، ودعواه بأن الطباع على ذلك مجبولة دعوى معكوسة، بل الطباع مجبولة على حبّ المرء نفسه خاصّة، وإنما يحبّ الجال لما يتوقّع فيه من منفعة نفسه.\rوأما الجمال الظاهر فلا شكّ أن محبته لمنفعة تعود إلى المحبّ، فإن كان لوناً فيحبّه مرئيّا للبصر لموافقته، أو يحبّه ملبوسا لموافقته الأغراض\r"], [661, "المعتادة، أو لملاينته، فلا يجب المرء الخضرة والماء الجاري –كما قال- إلا أن النفس تنشرح إليها بأحد وجهين:\rإمّا بغرابتها، فإن النادر له في القلب مكانة خلاف المعتاد.\rوإمّا لما في الخضرة من الإنذار باستقبال الزمان وعموم المنفعة؛ في الأقوات والشهوات ومآكل البهائم.\rوإمّا لأن نور البصر في أجمع، وهو لقوّته أحفظ.\rوإمّا بلين الملمس، وتصوّر القعود فيه، والاضطجاع عليه، بخلاف الهشيم، أو بمجموع ذلك، إلى غيرها من الوجوه التي لا يُحصيها الناظر، ولا يجمعها الخاطر الماهر، وإنما تظهر بعد الافتكار، وعند الاختبار، وكلها تعود إلى منفعة المحب وما يُتصوّر من نَيْل له فيه.\rوأما محبة الأنبياء والعلماء فلا خفاء فيه عند الإنصاف، إن محبتهم إنما هي لما هم فيه من المنفعة الدائمة المستمرة التي لا تشوبها مضرّة، من تعرّف طريق الهداية، والإنقاذ من ظلمات الغَواية، فليت شعري كيف خفي على\r"], [662, "هذا الحَبْر أن محبة الشيء إنما هي لعموم المنفعة به وشرف النيل فيه؟ وهل فضَل الأنبياء الخلق إلا بوساطتهم عن الله إليهم، فهي منفعة بيّنة لا يمكن جحدها.\rوأما حبّ المناسبة والمشاكلة فصهْ صَهْ، أيّ مناسبة بين العبد وبين الله؟ أبالمقدار الذي خلق له من العلم ما يناسب علمه؟ أم بوجه من القدرة خلقها فيه؟ أن بمعنى من الإرادة يسّرها له؟ أم بالحياة التي خصّصه بها؟\rتالله ما جُعِلت فيه هذه الصفات إلا ليتوصّل بها إلى معرفة استحالة المناسبة والمشاكلة بينه وبين ربّه، وانفراد الإله بخصائص الإلهية التي يستحيل كون الخلق على شيء منها، ولو كانت المشاكلة بالاتفاق في الأسماء لكانت المعاني كلها متشاكلة متناسبة، لما فيها من الاشتراك في وجه أو وجوه، وما استحقّ آدم الخلافة إلا بالفضل والنعمة، وما أُنعم عليه من المعرفة لا بالمناسبة، وما قال \"مرضت\" إلا كناية عن الولي، كما قال: \"مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنَاً\" (البقرة 245)، كناية عن المحتاج، والله هو الغني الذي لا يستقرض، كما هو القُدّوس الذي لا يمرض، وقوله: \"حتى أكون سمعه وبصره\"، كناية عن صيانة سمعه وبصره عن المحظورات والظواهر من العبارات والكنايات والمجازات، فكيف لا يؤخذ منها حقائق المعقولات، فيا\r"], [663, "له من عالم متبحّر في المعلومات يعوّل في الحقائق على المجازات، وكيف يجوز أن يقال إن المحبة والإرادة تتعلقّ بذات الباري، وهو سبحانه المتعالي عن التأثير، والإرادة صفة خاصّيتها التأثير، وذلكل لم تتعلّق بالمعدوم، وتعلّق العلم به لمّا لم يؤثِّر في المعلوم، حسب ما بيّنّاه من قبل وفي غير هذا الموضع، فكيف يعدل عن هذه الحقائق ويُعوّل على إطلاقات لا حقيقة وراءها؟\rوأمّا قوله: \"وَيَسْأَلُونَكَ عَنِ الرُّوحِ\" (الإسراء 85) فمعناها في غاية الوضوح، وليس من هذا كلّه بسبيل، وقد مهّدنا شرحها في كتاب المشكلين بغاية الدليل.\rالفصل الرابع: في التنزيل\r"]], "pg": [658, 663]}, "561.449": {"x": [[663, "أما إرادة الله تعالى محبّته وودّه فقد علمته كلّه بما تقدّم، وللباري تعالى في ذلك أحكام يختصّ بها ثلاثة:\rالأول: أنه يفعل ما يريد.\rالثاني: عموم الإرادة في الموجودات كلّها.\rالثالث: خصوص الودّ والمحبة لأهل الإيمان.\r"], [664, "المنزلة الثانية للعبد:\rفي محبته وهي على ثلاث درجات:\rالأولى: محبة خالصة غير مكدَّرة، كما قالت الصوفية، وهي أن تكون طاعة لا معصية معها، كما قال المنصور:\rتعصي الإله وأنت تُظهر حبّه *** هذا محالٌ في القياس بديعُ\rوزعم بعض الصوفية أن أعلى درجات المحبة أن لا يكون له طمع في جنة ولا خوف من نار، وذلك ما لا يُتصوَّر في الخلق.\rفإن قيل: فقد قال عمر: \"نعم العبد صُهيبٌ، لو لم يخف الله لم يعْصِه\"، قلنا: معناه لو لم يُخوّفه بالنار على المعصية لأطاعه رغبة في الثواب، لأن أكثر الخلق لو لم يُخوَّفوا بالعقاب لم يطيعوا، وإلا فلا معنى له.\rالثانية: وهي ثمرة الأولى، أن يكون الله ورسوله أحبّ إليه من نفسه وأهله وماله والخلق أجمعين، المعنى في حق الله أن يريد طاعة الله على ذلك كله، مثل أن يحب الجهاد والحج فيؤثرهما على الأهل ونحوه.\r"], [665, "وأما في حقّ رسول الله فأن يقدمه على نفسه وأهله وماله، فيلتزم طاعته فيما أمر به عن الله.\rالثالثة: أن يحبّ لله، ويبغض لله، وذلك مذكور في الرقائق.\r"], [666, "الاسم السادس: الرؤوف:\rوالكلام فيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [663, 666]}, "561.450": {"x": [[666, "ورد به القرآن في عدة مواضع، قال الله تعالى: \"إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَّحِيمٌ\" (البقرة 143)، ووردت به السنة في حديث أبي هريرة المفسَّر المتقدّم الذكر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [666, 666]}, "561.451": {"x": [[666, "للعلماء فيه خمسة أقوال:\rالأول: قال ابن فورك: الرأفة هي الرحمة نفسها.\rالثاني: أن الرأفة تعطُّفٌ برقّة، والرحمة تعطف بغير رقة، قاله الأخفش.\rالثالث: أن الرأفة هي شدة الرحمة، قاله الفرّاء.\rالرابع: أن الرأفة فعل ما لا كراهة فيه بما فيه المصلحة، قاله الخطّابي.\r"], [667, "الخامس: قال أبو عمْرو بن العلاء: الرأفة أكثر من الرحمة؛\rفأما تصريف فعله فيقال فيه: رَأَف ورَإِف يرأف ويرؤف رأفةً على وزن ضربة، ورآفة على وزن حمالة، ويقال: رؤف يرؤف ورأَفةً على وزن أَكَمَة، فهو رأْفٌ على وزن فَلْسٍ، ورؤوف على وزن شكور، وراُفٌ على وزن حَذُرٍ، قال الشاعر:\rوكان ذو العرش بنا أرافي\rأراد أرافيّاً، كقولك أحمريّ، فأبدل وسكّن، وذلك جائز معلوم، وقد قرأ أهل العراق إلا حفصا وأبا صالح عبد الحميد بن صالح: رَؤُفٌ على وزن حَذُرٍ، والباقون رؤوف على وزن ضَروب.\r"], [668, "الفصل الثالث: القول في حقيقته وعقيدته\r"]], "pg": [666, 668]}, "561.452": {"x": [[668, "وفيه مسائل:\rالمسألة الاولى: في تحقيق القول في الرأفة\r"]], "pg": [668, 668]}, "561.453": {"x": [[668, "وتعمّ مسائل، فأما قول الإمام أبي بكر بن فورك إن الرأفة هي الرحمة، فقد قدّمنا أن هذه الألفاظ كلّها وإن كانت ترجع إلى الإرادة إلا أن اختلافها يكون بحسب اختلاف متعلَّقاتها.\rوأمّا قول الأخفش إن الرأفة تعطّف برقّة فهو نظر إلى المعاني بخفش، لأنه تفسير الرأفة في حق الخلق، ويبقى تفسيرها في حق الحقّ، والتفسير إذا كان من العالم كان عامّا للحقيقة، فهذا تفسير قاصر إذن، وإن كان لا بدّ من تخصيصٍ فتخصيص الرأفة في حق الله أولى بالبيان من تفسيرها في حقّ الخلق.\rوأما قول الفرّاء إن الرأفة هي شدة الرحمة فهو أقرب إلى التخلّص، وكذلك قول أبي عمرو بن العلاء، فإن الرحمة هي إرادة الإنعام، فكلّما كان الإنعام أكثر كانت الرحمة أكثر، فتكون على هذا الوجه رأفة بكثرة متعلَّقات\r"], [669, "الإرادة ومصادرها لا بكثرتها في نفسها، فإنّ إرادة الله واحدة عقلا وسمعا باتفاق، وعلمه واحد سمعا كما تقدم.\rوأمّا من قال إن الرأفة هي رحمه في غير مكروه فهو قريب من الحق.\rوالمختار المُستوفي للمعنى على التحقيق والتخصيص، أن الرأفة عبارة عن تعلّق الإرادة بقصد التخفيف لما على المرحوم من ثقَل، يشهد له قوله تعالى: \"ولا تأخُذْكمْ بهمَا رأفةٌ في دينِ اللهِ\" (النور 2)، أي لا تأمروا، ولا ترضَوا بالتخقيق عنهما بعد أن وجب الثقل بالحدّ، وإليه يرجع القول الرابع، فإنّ فعل المكروه للمصلحة ثِقَل، وتركه تخفيف، وهي الرأفة، والباري تعالى رؤوف، بمعنى أنه خفف الثقل عن عباده في التكليف دُنْيا، وبالمغفرة في الآخرة وإسقاط الحقوق.\rالفصل الرابع: في التنزيل\r"]], "pg": [668, 669]}, "561.454": {"x": [[669, "إذا كانت الرأفة التخفيف فكم خفّف تعالى من ثِقْل ووضع من إصر، وكم من تخفيف سعى فيه رسول الله صلى الله عليه وسلم عن هذه الأمة، ووهبه الله لنا رحمة، فلهذا كان صلى الله عليه وسلم رؤوفا، ويحق للعبد أن يكون رؤوفا بسعيه للخلق في التخفيف والتيسير.\r"], [670, "الاسم السابع: حنّان\rوفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [669, 670]}, "561.455": {"x": [[670, "هذا اسم لم يرد به قرآن ولا حديث صحيح، وإنما جاء من طريق لا يُعَوّل عليها، \"روى أبو ظلال عن أنس بن مالك أن النبي صلى الله عليه وسلم قال: إن عبدا لينادي في جهنّم ألف سنة: يا حنّان يا منّان، قال: فيقول الله عز وجل لجبريل: اذهب ائتني بعبدي هذا، فينطلق جبريل فيجد أهل النار مُكبّين يبكون، فيرجع إلى ربه فيخبره فيقول: ائتني به فإنه في مكان كذا وكذا، فيجيء به فيوقفه على ربه فيقول له: يا عبدي كيف وجدت مكانا ومقيلا؟ فيقول: يا رب، شرّ مكان وشرّ مقيل، فيقول: ردّوا عبدي، فيقول: يا ربّ ما كنت أرجو إذ أخرجتني منها ان تردّني فيها، فيقول: دعوا عبدي\"، غير أن جماعة من الناس قبلوه وتأوّلوه، وكثُر إيراده في كتب التأويل والوعظ، فرأينا أن لا نخلي هذا الكتاب منه.\r"], [671, "الفصل الثاني: في شرحه لغة\r"]], "pg": [670, 671]}, "561.456": {"x": [[671, "الحنين بالحاء المهملة في اللغة عبارة عن ترديد الصوت عند الشوق، وهو بالخاء المعجمة عبارة عن ترديد الصوت ببكاء.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [671, 671]}, "561.457": {"x": [[671, "فيه ثلاث مسائل:\rالمسألة الأولى: هل يوصف الباري بالحنين؟\r"]], "pg": [671, 671]}, "561.458": {"x": [[671, "قال الجُبّائي: لا يصحّ وصف الباري تعالى بالحنين، لأنه ترديد الصوت عن رقّة نفس، ولا يوصف تعالى بالرقّة.\rالجواب: أنه يكون عن المحبة لا عن الرقة، وكلام الباري تعالى عندهم صوت وحرف، فلم لا يخلقْه في محلّ كما يقولون لمحبّته فيمن يشاء ويكون به حنّاناً، ويلزمه أيضا أن يقول: إن الباري يخلق الحنين والرق والأسف في قلب من يشاء من الأجسام، ويكون حنّاناً.\rوالمختار أن الله لا يوصف به، لأنه لا يصح مورده، ولو صحّ مورده لكان بمعنى الرأفة، والله أعلم.\rالمسألة الثانية: في الفرق بين الحنين والخنين والأنين\r"]], "pg": [671, 671]}, "561.459": {"x": [[671, "الذي صحّ في الحنين أنه ميل النفس برقة إلى جنس أو منفعة ملائمة، فإن ظهر أثره في العين والفم صار خنينا، فالخنين إذا دليل\r"], [672, "الحنين، وترديد الصوت إنما هو في الخاء المعجمة لا في الحاء المهملة، ومن ذلك قول الشاعر:\rحنّت قَلوصي إلى بابُوسها جزَعاً\rومنه المثل السائر: حرِّك حُوارها تحنّ، ونظير الخنين بالخاء المعجمة في الظاهر الأنين، وهو ثمرة الحنين في الباطن ودليله أيضا، فاختلط على من تكلم من أشياخنا الحنين بالحاء المهملة مع الخنين بالخاء المعجمة وبالأنين أيضا، فلم يُميزوا بينهما، ودليله ما نبّهنا عليه.\rالمسألة الثالثة:\r"]], "pg": [671, 672]}, "561.460": {"x": [[672, "قال تعالى: \"وَحَنَانًا مِّن لَّدُنَّا وَزَكَاةً \" (مريم 12)، فظهر لبعض المقصِّرين من قوله: \"وَحَنَانًا مِّن لَّدُنَّا\" فأضافه إليه أنها صفة له، وليس\r"], [673, "كذلك، فإنّا قد بينّا في كتب الأصول أن الإضافة إلى الله تعالى تكون في المِلك والخلق، كما تكون في الصفة، والآية كلها مبنية على ما آتى الله تعالى يحيى عليه السلام من صفات شريفة وخصال كريمة؛ حكمة وحنّة، وزكاة وبِرّ وتقوى، فدلّ بهذا أنها صفات شُرّف بها يحيى، وامتنّ عليه بخلقها فيه، لا يعود إلى الخالق منها وصف؛ على ما بيّنّاه من أن أفعاله تعالى لا توجب له صفة لم تكن له قبل، والله أعلم.\r"], [674, "الاسم الثامن: البَرّ\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [672, 674]}, "561.461": {"x": [[674, "قال الله تعالى: \"إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ\" (الطور 26)، وورد في حديث أبي هريرة المفسّر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [674, 674]}, "561.462": {"x": [[674, "قال أهلها: يقال برَرْتُه أبَرُّه بِرّاً فأنا به بارٌّ وبَرٌّ على وزن فَعْلٍ، كما يقال رجل طَبٌّ بكذا، ورجل فَلٌّ أي منهزم، ورجل كَرٌّ أي بخيل.\rالفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [674, 674]}, "561.463": {"x": [[674, "فيه ثلاث مسائل:\rالمسألة الأولى: في سرد أقوال العلماء\r"]], "pg": [674, 674]}, "561.464": {"x": [[674, "قال علماؤنا –رحمة الله عليهم-: فيه ثلاثة أقوال:\rالأول: أنه المحسِن، يقال: فلان برٌّ بأبويه إذا كان محسنا إليهما، قاله ابن فورك.\r"], [675, "الثاني: أن البرّ هو العَطوف على عباده، المحسن إليهم، عمّ ببرّه جميع خلقه، قاله القشيري.\rالثالث: أن البرّ هو المريد لإعزاز أوليائه، قاله الأستاذ أبو إسحاق الإسفراييني.\rالمسألة الثانية: في المختار منها\r"]], "pg": [674, 675]}, "561.465": {"x": [[675, "قال النبي صلى الله عليه وسلم: \"البِرّ حسنُ الخُلق\"، وقال صلى الله عليه وسلم: \"الصدق يهدي إلى البرّ\"، وقال أيضا: \"البرّ يهدي إلى الصدق\"، فإذا تأمّلت هذا علمت أن البرّ هو الكون على الصفات المأمور بها قولا وفعلا، وهي الخُلق الحسنة، فإذا لزم الصدق –وهو موافقة القول والعمل للاعتقاد- بَرَّ، وإذا برّ اتفق قوله مع فعله.\r"], [676, "المسألة الثالثة: في التركيب\r"]], "pg": [675, 676]}, "561.466": {"x": [[676, "أما من قال إن بِرّه عمّ جميع خلقه فهو قول فاسد، فإن البرّ مخصوص غير عامّ ولا مُعَمَّم، ألا ترى أنه يقال: أنعم الله على الكافرين، ولا يقال: برّهم، ولو قاله قائل لتبادرت ألسنة الخلف والسلف إلى إنكاره.\rوأمّا من قال إن بِرّه هو إحسانه، فالإحسان هو ثمرة البِرّ لا نفس البرّ.\rوالحيح أنه إرادته لإعزاز أوليائه وإكرامهم، والدليل عليه قوله: \"فَمَنَّ اللَّهُ عَلَيْنَا وَوَقَانَا عَذَابَ السَّمُومِ إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ\" (الطور 25 - 26)، فكان قوله: \" فَمَنَّ اللَّهُ عَلَيْنَا\" إشارة إلى إرادته إكرامهم، وهي المِنّة والبِرّ، وقوله: \" وَوَقَانَا عَذَابَ السَّمُومِ\" إشارة إلى فائدة البِرّ وهي الإكرام، وأتبعها بقوله: \" إِنَّهُ هُوَ الْبَرُّ\" بالإرادة، \" الرَّحِيمُ\" بالإحسان.\rوقد قال تعالى في ضدهم: \" الْيَوْمَ تُجْزَوْنَ عَذَابَ الْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى اللَّهِ غَيْرَ الْحَقِّ وَكُنتُمْ عَنْ آيَاتِهِ تَسْتَكْبِرُونَ\" (الأنعام 93)،\r"], [677, "ويجوز أن يسمّى الإكرام والإحسان بِرّاً، كما يُسمّى ما يصدر عن القدرة والعلم قدرة وعلما.\rفإن قيل: فكيف تقولون إنه يَبَرّ أولياءه وهو يرى الظلمة والكفرة يتولَّون فيهم أنواع العذاب والنّكال؟\rفالجواب: أننا نقول: قد تقدّم نحو هذا الأنموذج في اسم الرحمن، وتحقيقه أن ما يجري على الأولياء من جهة الأعداء بصورة الإهانة الجاري مثلها على الكفار بحقيقتها ليس بإهانة في التحقيق، وإنما هو بلاء ومحنة وتمحيص وفتنة، والإهانة في الحقيقة ما استوى ظاهره وباطنه، وكان في المآل كما هو في الحال، وما يجري على الأولياء من تسلّط الأعداء والابتداء بالبأساء يرفعهم الله به درجات ويجعله أسوة للخلق، وغرورا للظلمة، واستيفاء بيانه في كتب التعديل والتجوير.\r"], [678, "الفصل الرابع: في التنزيل\r"]], "pg": [676, 678]}, "561.467": {"x": [[678, "قال علماؤنا: يختص الباري تعالى في البِرّ بأحكام أربعة:\rالأول: إعزازه لأوليائه بالذكر الجميل.\rالثاني: تضعيف الثواب.\rالثالث: بالسَّتر على المعاصي.\rالرابع: بغُفران الخطايا.\rالمنزلة الثانية للعبد:\rوذلك في أربعة أحكام:\rالأول: بِرّه بربه ألّا يعصيه.\rالثاني: برّه بأبويه، فلا يقل لهما أفّ\rالثالث: برّه بمُعلّمه، بأن يكون بين يديه كالميّت بين يدي الغاسل.\rالرابع: برّه بكافّة الخلق، بطرح الجفاء عن قوله وفعله.\r"], [679, "الاسم التاسع: الحَفيّ\rالكلام فيه على أربعة فصول:\rالفصل الأول: في مورده:\r"]], "pg": [678, 679]}, "561.468": {"x": [[679, "اعلموا –وفّقكم الله- أن هذا الاسم لم يذكره أحد من علمائنا؛ مَن سلف منهم ومن خلف، ولكنّا استخرجناه من كتاب الله تعالى لما اسْتَقْرَيْنا الأسماء، والله ينفعنا به ويُنيلنا معناه برحمته، قال الله تعالى مُخبرا عن خليله صلى الله عليه وسلم: \"إنّهُ كَانَ بِي حَفِيَّاً\" (مريم 47).\rالفصل الثاني: في شرحه لغة\r"]], "pg": [679, 679]}, "561.469": {"x": [[679, "ذكر علماء هذا الفنّ أن له سبعة معانٍ:\rالأول: الحَفيّ: البَرّ الوَصول، قاله ابن الأعرابي، يقال: أحفى بصاحبه، وتحفّى به، وخفى بفتح العين وكسرها، واحتفى حَفاوة\r"], [680, "وحِفاوة وحَفاية وحِفاية، فهو حافٍ وحَفيّ؛ إذا بالغ في إكرامه وبِرّه، وحفا الله به حَفواً أكرمه ولطف به.\rالثاني: الحَفيّ المُعتني بالأمر، قاله ثعلبٌ، يقال: أحفى المسألة عن الشيء حتى علمه، أي ألحَفَ في السؤال، من قوله تعالى: \" فَيُحْفِكُمْ تَبْخَلُوا\" (محمد 37).\rالثالث: الحَفيّ العالم، قاله الأزهري.\rالرابع: الحَفيّ الفَرح.\rالخامس: الحَفيّ الحاكم، تقول العرب للحاكم الحافي، تحافَينا إلى فلان، أي تحاكمنا إليه.\r"], [681, "السادس: الحَفيّ المانع، والحَفْو المنع، يقال: حفا فلان فلانا من كل خير، إذا منعه منه، وأتاني يسألني فحَفَوْته، أي منعته.\rالسابع: حفاه أعطاه.\rالفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [679, 681]}, "561.470": {"x": [[681, "وفيه مسألتان:\rالمسألة الأولى: في التركيب للمعنى الاعتقادي على اللغوي\r"]], "pg": [681, 681]}, "561.471": {"x": [[681, "إذا قلنا إن الحَفيّ هو البَرّ فقد تقدّم ذكره وبيانه؛ وإذا قلنا: إن الحفيّ هو المعتني بالسؤال فهو سبحانه الذي يسأل عن عباده على العموم والخصوص، سؤال تقرير ومباهاة لا سؤال استفهام واستعلام، وذلك كثير جدا، كقوله صلى الله عليه وسلم: \"يتعاقبون فيكم ملائكةٌ بالليل وملائكة بالنهار، ويجتمعون في صلاة الصبح وصلاة العصر، ثم يعرج الذين باتوا فيكم فيسألهم وهو أعلم بهم، فيقول: كيف تركتم عبادي\" الحديث، وكقوله صلى الله عليه وسلم: \"لله ملائكة يطوفون في\r"], [682, "الطريق يلتمسون أهل الذكر، فإذا وجدوهم تنادَوا هلمّوا إلى حاجتكم، قال: فيحفّونهم بأجنحتهم إلى السماء الدنيا، فيسألهم ربهم وهو أعلم بهم، ما يقول عبادي\" الحديث بطوله.\rوأمّا إذا قلنا: إن الحفيّ هو العالم فقد تقدّم بيانه، وتسميته به مجازٌ، ووجهه أن السؤال يفتح باب العلم فسُمّي به.\rوإذا قلنا: إن الحفيّ هو الفرِح، فقد روي عن النبي صلى الله عليه وسلم أنه قال: \"لله أفرح بتوبة العبد من أحدكم ضلّت عنه راحلته بأرض دَوِّيَّةٍ مَهْلَكَةٍ، فلما يئس عنها نام تحت شجرة فاستيقظ، فإذا راحلته عند رأسه\"، وقد بيّنّاه في كتاب المشكلين؛ والفرح في لسان العرب هو سرور النفس ونشاطها عند الظفَر بالمحبوب أو عند استشعاره، وذلك مُحالٌ في حق الله، لكن من سُرّ أعطى، فسُمّي العطاء فرحاً، لأنه عنه يكون، وقد بيّنّاه في كتاب المشكلين.\rوإن قلنا: إنه الحاكم أو المانع أو المعطي فسيأتي بيانه في موضعه إن شاء الله.\r"], [683, "المسألة الثانية: في المختار\r"]], "pg": [681, 683]}, "561.472": {"x": [[683, "هذه المعاني كلها ظاهرة في لفظ الحفيّ، لا يمكن إنكارها لغة، ولكن ظاهر الآية التي تلوناها من قبل يدلّ على أن المراد به فيها البِرّ، وهي قوله: \"سَأَستَغفِرُ لَكَ رَبِّي إنّهُ كَانَ بِي حَفِيَّاً\" (مريم 47)، إشارة إلى برّه به، وكأنّ التحفّي غاية البرّ، وسائر المعاني سائغة فيه.\rالفصل الرابع: في التنزيل\r"]], "pg": [683, 683]}, "561.473": {"x": [[683, "وهو معنى تنزيل البَرّ بعينه، وكذلك منزلة العبد فيه، لكن لمّا اخترنا أن يكون التحفّي غاية البِرّ، وهو الباري تعالى موجود بجميع معانيه العَليّة ينبغي للعبد أن يُوجَد فيه البِرّ بجميع معانيه الممكنة.\r"], [684, "الاسم العاشر: الصبور\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [683, 684]}, "561.474": {"x": [[684, "لم يرد به قرآن، ووردت به السنة في حديث أبي هريرة المفسّر، وقال صلى الله عليه وسلم: \"لا أحد أصبر على أذىً من الله\"، وقال علماؤنا –رحمة الله عليه-: لسنا نقطع بهذه التسمية، وإن جوّزناها على معنىً دون معنى، وقد ذكروا أمثالها مما لم يرد به قرآن ولا سنة ولا خبر صحيح، وقد استعملوا ما فيه أثر ضعيف.\rفأمّا هذا الاسم فقد جاء أفْعَلُ فيه في الحديث الصحيح، وهو قوله: \"لا أحد أصبر على أذىً من الله\"، وإذا كانوا يُسمّون الله بأسماء الفاعل من فعل فتسميته باسم الفاعل من أفعل أقرب إلى الاشتقاق وأوضح في المعنى.\r"], [685, "الفصل الثاني: في شرحه لغة\r"]], "pg": [684, 685]}, "561.475": {"x": [[685, "قال علماؤنا: الصبر هو الحَبْس، يقال: قُتل فلان صَبراً، معناه محبوسا، ونهى النبي عليه السلام عن صبر البهائم، وسُمّي الصّوم صبرا لما فيه حبس النفس عن الشهوات، ولا خلاف فيه.\rالفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [685, 685]}, "561.476": {"x": [[685, "اعلموا –وفقكم الله- أنه إذا ثبت ما ذكرناه لغة فالكلام بعد ذلك في هذا الاسم تحصره ثلاث مسائل:\rالمسألة الاولى: في تحقيق إطلاقه\r"]], "pg": [685, 685]}, "561.477": {"x": [[685, "إذا كان معنى الصبر الحبس، فذلك محال في حق الله عقلا، ولم يَرد الاسم سمعا، وإنما ذُكر في حديث أبي هريرة المفسّر الذي لا يُقطع به من قول النبي صلى الله عليه وسلم ولا من قول أبي هريرة رضي الله عنه، وقد أسقطه سفيان بن عيينة حسب ما تقدّم عنه، وعوّض منه بما لم يرد في القرآن اسما، وإنّما وجده فعلا، ولكنّا وجدنا منه نحن في الحديث الصحيح أفعل، فجاز منه فاعل وفَعول.\rوحين رأى علماؤنا –رحمة الله عليهم- استحالة معناه على الله تعالى أجمعوا على تأويله وصرفه عن مقتضاه، واختلفوا في تأويله على ثلالة أقوال:\r"], [686, "الأول: أنه من صفات ذاته، وأنه بمعنى حليم، قاله ابن فورك والقشيري.\rالثاني: أنه من صفات الذات، ولكن يرجع إلى إرادة تأخير العقوبة، والحليم يرجع إلى إسقاطها حسب ما يأتي بيانه في وصف الحليم.\rالثالث: أنه من صفات الفعل، ويرجع إلى تأخير العقوبة، وإليه صَغْوُ أبي حامد شيخنا رضي الله عنه.\rالمسألة الثانية: في تحقيق هذه الأقوال\r"]], "pg": [685, 686]}, "561.478": {"x": [[686, "أما من قال: إنه بمعنى حليم فعجبٌ له، فإنّا في ألفاظ العرب إذا ترادفت ووجدنا لتحقيق الاختلاف فيها وجهاً لم نحكم بترادفها ولا قلنا باتّحاد معانيها،\r"], [687, "فكيف نحكم بذلك في حق الله تعالى، وليت شعري أيُّ ضرورة دعت هذين الحَبرَين إلى أن يقولا بذلك ويرُدّا الصبر إلى الحِلم في حق الله، وذلك فاسد من وجهين:\rأحدهما: تحقيق الفرق بينهما في حق العباد، فكيف يتّحدان في حق الله؟\rالثاني: أنه قد تبيّن أنه لا يجوز إطلاق الصبر على حقيقته الموجودة فيه في حقّ الله، ووجب تأويله وحمله على غير ما يُستعمل عليه عندنا، فكيف يُحمل بعد هذا على معنى الحليم ويختصّ به ويُحكَم باتّحادهما دون طلب الوجوه المحتملة فيه، واعتبار طرق النظر إليه؟ هذا تقصير بالغ لا يليق بمرتبة هذين الحَبرين.\rوأما من قال إنه من صفات الفعل فوجه فساده كوجه فساد من قال إن الحليم من صفات الأفعال، وسيأتي بيانه إن شاء الله.\rالمسألة الثالثة:\r"]], "pg": [686, 687]}, "561.479": {"x": [[687, "ليس العجب من المعتزلة في جعلهم الصبر والحلم من صفات الأفعال، إنما العجب من شيخنا أبي حامد في صَغوِه إلى ذلك، وقد تحقّق أن\r"], [688, "أوصاف الباري على قسمين؛ إثباتٌ ونفيٌ: فأمّا الإثبات فطرقه معلومة ومعانيه مفهومة حسب ما اطّرد في كل اسم منها.\rوأمّا النفي فهو من صفات التنزيه عن الآفات، والتقدّس عن النقائض، وذلك يرجع إلى الذات.\rفأمّا ترك الفعل ونفيه فلا يصح أن يكون منه حقيقة وصف لأحد، فكيف للباري! وهذه حقيقة لا يغوص عليها كل ناظر، ولا يصل إليها كل خاطر.\rفصحّ من هذا أن الصبور يرجع إلى إرادة تأخير العقوبة، وهو المختار، وذلك معنى قوله: \"لا أحد أصبر على أذىً من الله، فإنه يُعافيهم ويرزقهم، وهم\r"], [689, "يدّعون له الصحبة والولد\"، فإشار إلى تأخير العقوبة عن الكافر في الدنيا، إذ لا بد من معاقبته في الآخرة، وهذا نصٌّ في المسألة؛ وحقيقة معنى قوله صلى الله عليه وسلم: \"الحمدلله الذي لا يعجل شيءٌ آناه وقدّره\"، وقد اختلف في تفسير هذا الحديث وضبطه على وجوه بيانها في كتاب المشكلين.\rفرجع تحقيق وصف الصبر إلى أنه المُريد لتأخير العقوبة التي قدّر لها وقتا معلوما، وحدّ لها أجلا محدودا، وهذا المعنى موجود في قوله: \" وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِظُلْمِهِمْ مَا تَرَكَ عَلَيْهَا مِنْ دَابَّةٍ\" (النحيل 61)، وقوله: \" وَلَا تَحْسَبَنَّ اللَّهَ غَافِلاً عَمَّا يَعْمَلُ الظَّالِمُونَ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ الْأَبْصَارُ\" (إبراهيم 42)، في عدة آيات أمثال لهذه.\rالفصل الرابع: في التنزيل\r"]], "pg": [687, 689]}, "561.480": {"x": [[689, "إذا فهمتهم معنى الصبر وحقيقته ووجه إطلاقه على الله تعالى ووصفه به، فإن المنزلة العليا لله فيه يختصّ فيها بأحكامٍ ثلاثة:\r"], [690, "الأول: جواز إطلاقه عليه بما يصحّ من المعنى فيه.\rالثاني: صرفه عن الوجه المستحيل فيه عندنا، فإن لفظ الحبس لا يجوز على الله تعالى بحال، فكيف بما يُضاف إليه من مقاساة ومعاناة.\rالثالث: تأخير العقوبة عن المخالفة مع كمال القدرة ومعرفة العاقبة.\rالمنزلة السفلى للعبد:\rوله فيها أحكام جماعها ثلاثة:\rالأول: حبسه نفسه عن الشهوات.\rالثاني: حبسه نفسه عن كراهة المقادير\rالثالث: حبسه نفسه عن الضجر بالبلايا، وما يصيبه من مكروهات الحادثات، وهو المراد بقوله تعالى: \" إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ\" (الزمر 10)، وقد اختلف فيه، فقيل: الصابر من جمع هذه الخلال، وقيل: من حصل على خصلة منها بل على بعض خُلة منها فقد حاز جزءاً من الصبر، فوفّاه أجره بغير حساب، وهو الصحيح عندنا.\rوقد قال الزُّهّاد: خُلق الإنسان من عجل، فإذا تصبّر وقاسى وتكلّف حتى يعود له كالجِبْلة فهو الصبر المطلق، فإن سلم عن مقارنة الجزع\r"], [691, "والتسخّط بالقلب والشكوى إلى غير الله فهو الصبر الجميل؛ الذي تقلّد يعقوب صلى الله عليه وسلم عهدته، ولبس بُردته، ومَلَكَ حوزته، حيث قال: \"فَصَبْرٌ جَمِيلٌ\" (يوسف 18)، و \" أَشْكُو بَثِّي وَحُزْنِي إِلَى اللَّهِ\" (يوسف 86)، وفي ذلك تطويل وبلاغ في البيان، والأمثال ليس هذا بابه.\r"], [692, "الاسم الحادي عشر: الحليم\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [689, 692]}, "561.481": {"x": [[692, "ود به نصّ القرآن، قال الله تعالى: \"والله غفورٌ حليمٌ\" (البقرة 225)، وجاء في حديث أبي هريرة المفسَّر، وأجمعت عليه الامة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [692, 692]}, "561.482": {"x": [[692, "قال علماؤنا –رحمة الله عليهم-: يقال حلُم الرجل –بضم العين- حِلما –بكسر الحاء- إذا أخّر من العقوبة ما كان له أن يُعجِّل، وبناء حلُم بضم العين للتكسّب والتخلّق، وحَلَمَ بفتح العين في الماضي وضمّها في المستقبل إذا رأى في المنام، وحَلِم الأديم بكسر العين في الماضي وفتح الفاء والعين في المصدر إذا فسد في دباغه.\rالفصل الثاث: في شرحه حقيقة وعقيدة\r"]], "pg": [692, 692]}, "561.483": {"x": [[692, "وفيه ثلاث مسائل:\rالمسألة الأولى: في شرح معناه استعمالا:\r"]], "pg": [692, 692]}, "561.484": {"x": [[692, "الحليم عبارة عن شخص يكون على صفة لا يستفزّه غضبٌ، فيترك الجواب على الكلام ويدرأُ العقوبة على الذنب، مع القدرة على القول\r"], [693, "والفعل، وإن كان ترك الجواب عن عجز فهو عَيِيٌّ، وإن كان ترك العقوبة عن عجز فهو مَهينٌ، وربما ظنّ بعض الناشئة أن السفَهَ ضدّ الحِلم، وليس كذلك، إنما السفَهٌ ضدّ الحكمة، وإنما ضد الحلم الطيش، وقد أجاد بعض الشعراء في وصف هذه الحقيقة فقال الشاعر:\rلا يدرك المجد أقوامٌ وإن كرُموا *** حتّى يَذِلّوا وإن عَزّوا لأقوامِ\rويُشتَموا فترى الألوان مُسفرة *** لا صَفْحَ ذُلٍّ ولكن صفحَ أحلامِ\rوالحِلم في الخلق صفة لمِدحَةٍ، تجمع أشتاتاً كثيرة من الخير، وتضمّ نَشَراٍ عظيماً من الصلاح، ولمّا سأل الخليل ربّه الجليل هبة ولدٍ، قال: \"ربِّ هبْ لي من الصالحين\" (الصافات 100)، قال الله تعالى: \"فَبَشَّرْناهُ بِغُلامٍ حَلِيمٍ\" (الصافات 101)، فأعطاه أعلى مراتب ما سأل، وآتاه أفضل منازل ما طلب.\rالمسألة الثانية: في شرح معناه اعتقادا\r"]], "pg": [692, 693]}, "561.485": {"x": [[693, "اختلف الناس في وجه وصف الباري تعالى بالحلم على ثلاثة أقوال:\rالأول: أن الحلم عبارة عن نفي السفَه عنه، قاله النجّار من المبتدعة.\r"], [694, "الثاني: أن الحلم من صفات الفعل، يجري مجرى الإنعام والإحسان، قاله المعتزلة، وإليه أشار شيخنا أبو حامد.\rالثالث: أن الحلم إرادة تأخير العقوبة عن العصاة من الكفرة والفسقة، من الدنيا إلى الآخرة، ومن وقت إلى وقت.\rوأما قول النجّار إن الحلم ليس بمعنى، وإنّما يرجع إلى نفي السفهِ فعنه ثلاثة أجوبة:\rالاول: أنه يلزمه ذلك في كل صفة، بأن يقال له: إنها ليست عبارة عن معنى موجود، وإنما ترجع إلى نفي الآفة والنقص، كالعلم والقدرة، وليس له على هذا جواب ينفع.\rالثاني: أن نقول: ليس السفه نقيض الحلك، وإنما هو نقيض الحكمة، والذي هو نقيض الحلم الطيش والخفّة.\rالثالث: أنه لو كان الحلم نقيض السفه لكان الباري بتعجيل العقوبة سفيها، وقد عجّل العقوبة على قوم وأخّرها عن آخرين على مُقتضى الإرادة.\rوأما من قال إنه من صفات الفعل فيقال له:\rالأول: أيّ فعل هو؟ ما حقيقته؟ ما خاصّيته؟\r"], [695, "الثاني: أن نقول: إن المين في حال موته وبعد موته لا يُعاقَب عندكم، فهل يوصف الباري بالحلم عنه، ولا يصحّ ذلك منهم؛\rالثالث: أن الفعل إذا لم يكن له حاصل رجع ذلك إلى نفي العقوبة، وهو عدم الفعل، وعدم الفعل لا يُعدّ في جملة الأفعال.\rوأما من قال إنه إرادة تأخير العقوبة، فقد اختلط عليه الحلم بالصبر، فإن الحلم هو إرادة إسقاط العقوبة، والصبر هو إرادة تأخيرها.\rفإن قيل: فهل يحتمل أن يكون من صفات الفعل، فيكون هذا الاسم من الأسماء المحتملة للوجهين: أحدهما ما يرجع إلى الذات، والثاني ما يرجع إلى الفعل؟\rقلنا: هذا المقدار هو الذي أشكل على الضعفاء حتى توهّموه من صفات الفعل، ولا عجب منهم، إنّما العجب من شيخنا أبي حامد كيف أبهم أمره على جلالة قدره ومال إلى إنه من صفات الفعل؛ ونحن لا نقول ذلك، فإنّ الحلم من صفات الذات على ما بيّنّاه، ولو وُصف غير الباري بأنه حليم على\r"], [696, "معنى إسقاط العقوبة لجاز، ولكنه مجاز، والمجاز لا يُرجع إليه في حقّ الباري إلا إذا ورد به الخبر أو لضرورة دليل.\rالمسألة الثالثة: هل يوصف الباري تعالى بالحلم عن الكافرين والعصاة من المؤمنين مع قولكم: إن الحلم هو إرادة إسقاط العقوبة؟\rقلنا: الصحيح من الجواب فيه: أنه تعالى يوصف بالحلم عن الكفار الذين علم أنهم يموتون كفّارا؛ بما أسقط عنهم من عقوبة الدنيا، وأمّا العصار من المؤمنين فمن علم منهم أنه يعاقبه لا نقول فيه إنه حليم عنه، ومن علم أنه يغفر له فهو حليم عنه، ومن أجلى عبارةٍ فيه قول بعض علمائنا: إن العصاة لا يأمنون مع كون الباري صبرواً العقابَ، ويأمنون ذلك مع كونه حليماً، فهم متردّدون بين الأمري حتى يٌنفّذ الله سبحانه مُراده الذي علمه.\rالفصل الرابع: في التنزيل:\r"]], "pg": [693, 696]}, "561.486": {"x": [[696, "إذا فهمتم الحلم فإن الباري تعالى يختص فيه بأنه يُسقِط العقوبة مع القدرة على الاستيفاء وعدم خوف العواقب.\rويختصّ العبد في الحلم إذا اكتسبه بثلاثة أشياء؛ براحة الحَوْباءِ، واصطناع الأولياء، وطِيب الثناء.\r"], [697, "الاسم الثاني عشر: الوليُّ\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [696, 697]}, "561.487": {"x": [[697, "قال الله تعالى: \"اللهُ وليُّ الّذين آمنُوا\" (البقرة 257)، وقال: \"وهُوَ الوَليُّ الحَمِيدُ\" (الشورى 28)، وأمر نبيّه صلى الله عليه وسلم أن يقول: \" إِنَّ وَلِيِّيَ اللَّهُ الَّذِي نَزَّلَ الْكِتَابَ وَهُوَ يَتَوَلَّى الصَّالِحِينَ\" (الأعراف 169)، وقال سبحانه: \" وَمَا لَهُم مِّن دُونِهِ مِن وَالٍ\" (الرعد 12)، وورد مُعَدّداً مفسَّراً في حديث أبي هريرة، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [697, 697]}, "561.488": {"x": [[697, "ذكر العلماء هذا الفن في ستّة أقوال:\rالأول: أن الوليّ هو الناصر.\rالثاني: أن الولي هو الموْلى.\rالثالث: أنه المتولي للأمر القائم به، فَعيلٌ بمعنى فاعل، وهو الولي، يقال: ولي الشيء يلي ولايةً، بكسر الفاء في المصدر وفتحها، فهو والٍ، وعلى المبالغة وليٌّ.\r"], [698, "الرابع: أن الولي المحبّ.\rالخامس: أن يكون الوليّ بمعنى المُوالي، عَوداَ على بَدْءٍ، كما تقول: أكيلٌ بمعنى المؤاكل، وشريب بمعنى المُشارب، وخليطٌ بمعنى المُخالِ، مأخوذٌ من الوليّ، وهو المطر الثاني التالي للوَسْميّ، الذي هو مطر أول العام.\rالسادس: أن الوليّ القريب، مأخوذ من الوَلْيِ وهو القرب، ومنه قوله على أحد التأويلين: \"أَوْلى لَكَ فَأَوْلى\" (القيامة 34)، أي قريب منك ما كنت تحذر منه، ومنه قول ذي الرُّمّة:\rلِني وَلْيَةً تُمْرِعْ جَنابي فإنّني *** لِوَسْميّ ما أولَيْتني لك شاكرُ\rالفصل الثالث: في شرحه حقيقة وعقيدة\r"]], "pg": [697, 698]}, "561.489": {"x": [[698, "وفيه ستّ مسائل:\rالمسألة الأولى: في بيان حقيقة معنى اللفظ\r"]], "pg": [698, 698]}, "561.490": {"x": [[698, "قد قدّمنا عبارات أهل اللغة في ذلك، ومن أقوالهم مُتداخلٌ ومنه متباين، وأصله كلّه يرجع إلى معنيين:\rأحدهما: القرب، مأخوذ من الوَلْي بإسكان العين.\r"], [699, "والثاني: مأخوذ من الوليّ على وزن فعيل، وهو الذي يلي الوَسْمي، ويرجع إلى المبالغة، والمتابعة ترجع إلى القرب، لأن من تابع شيئا فهو قريب منه، فكلّ من تابع وواصل فقد قَرُب، وليس كلّ قريب مواصلا، فرجع الوصف إلى القرب؛\rثم نظرنا إلى سائر المعاني المذكورة فيه فوجدنا الناصر للمنصور قريبا منه بالنّصرة، والمُتولّي للأمور قريب منها، لأنه متمكّن من فعلها، ماضٍ حكمه فيها، وغيره بعيد منها، وذلك مقرون بالمحبة، فالمحبّ قريب منه محبوبه بإحسانه، فرجع الواو واللام والياء إلى القرب، إلّا أن مُتعلَّقات القرب تختلف على وجهين:\rأحدهما قربٌ بالمكان، والآخر قرب بالمكانة، وإلى هذا أشار القائل بقوله:\rفقلت وما تغني ديارٌ قريبة *** إذا لم يكن بين القلوب قريبُ\rوتختلف أيضا متعلَّقات القُرب بالمكانة على ثلاثة أوجه:\rالأول: قرب المحبة، وهي إرادة الخير.\rالثاني: قرب النصرة، وهو بالظهور على الأعداء.\r"], [700, "الثالث: قرب الموالاة، بمتابعة ذلك ومناصرته.\rوإلى هذه الأوجه الثلاثة يرجع كلّ وجه من التعلّق يُذكر لهذا المعنى، وإن اختلفت ألفاظه، وهذا تحقيق نسأل الله أن يُعرِّفنا قدْره، ويمنحنا شكره.\rالمسألة الثانية: في تحقيق الاعتقاد\r"]], "pg": [698, 700]}, "561.491": {"x": [[700, "إذا قلنا إنه الوليّ بمعنى القريب المواصل للمحبوب، فهو تعالى قريب منه إذا دعاه، قريب منه إذا أعطاه، قريب منه إذا عصاه.\rأمّا قُربه عند ذكره فبذكره لقوله: \"فاذْكُرُونِي أَذْكُرْكُمْ\"، ولقوله صلى الله عليه وسلم: \"من ذكرني في نفسه ذكرته في نفسي\"، الحديث.\rوأمّا قربه ممّن دعاه فبالإجابة، لقوله: \"فَإِنّي قًريبٌ أُجيبُ\" (البقرة 185).\rوأمّا قربه ممن أطاعه فبالثواب، وقربه ممن عصاه بالإحاطة والإحصاء، لكنه لفظُ مدح، فلا يضاف إلى المعاصي، وإنما يختص\r"], [701, "بالمُمَدَّحات من المعاني، وهذا معنى قوله: \"اللهُ وَليُّ الذين آمنوا\" (البقرة 256)، ومعنى قوله: \"لا إِنَّ أَوْلِيَاءَ اللَّهِ لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ\" (يونس 62).\rالمسألة الثالثة:\r"]], "pg": [700, 701]}, "561.492": {"x": [[701, "إذا ثبت هذا وعلمتم أن معنى الوليّ راجعٌ إلى القريب، وعرفتم متعلَّقات القرب، فاعلموا أنه راجع إلى الإرادة إذا كان بمعنى المحبة على ما بيّنّاه، وإن كان بمعنى النُّصرة كان من صفات الفعل، وكذلك هو من صفات الفعل بمعنى المتابعة.\rالمسألة الرابعة:\r"]], "pg": [701, 701]}, "561.493": {"x": [[701, "اعلموا –وفقكم الله- أنّ هذا الاسم مما يختصّ به أهل السنة، ليس للمبتدعة فيه حظ، ولا له عندهم معنى، لأنهم يعتقدون أن الخلق هم المُتَوَلّون لأعمالهم، القائمون بها خيرها وشرّها، فلا يصحّ على أصلهم هذا أن يقولوا إنه وليٌّ، لأنه إن أحبّ لم ينفع، وإن أبغض لم يضرّ.\r"], [702, "المسألة الخامسة:\r"]], "pg": [701, 702]}, "561.494": {"x": [[702, "إذا قلنا إنّ الوليّ بمعنى المَولى، فالمولى أيضا اسمٌ من أسماء الباري تعالى وهو:\rالثالث عشر: المَوْلى\rورد به القرآن والسنّة مطلقا ومضافا، قال الله تعالى: \"نِعْمَ المَوْلى\" (الأنفال 40)، وجاء في حديث أبي هريرة من طريق ابن الحُصَين، وهو في لسان العرب على ثمانية أوجه:\rالأول: المُعتِق.\rالثاني: المُعتَق.\rالثالث: الوليّ\rالرابع: ابن العم.\rالخامس: الأوْلى.\rالسادس: الحَليف\rالسابع: الجار\rالثامن: الصِّهر\rوتحقيقه إذا تدبّرت هذه المعاني التي ذكر علماء اللغة، وجدتها كلّها ترجع إلى معنى الوليّ الذي تقدّم بيانه؛ من المتابعة والقُرْب، فإن الجار وابن\r"], [703, "العم والمُعتِق والمعتَق والصّهر والحليف وجميع ما تقدّم قريب من صاحبه الذي نسب إليه مُتابعٌ له، فهو مَفْعَل من ذلك اسم مصدر، سُمّي به من أُطلق عليه، وإذا كان بمعنى الوليّ فلا نقول إنه مع المولى مترادفان، وكأن حقيقته وليّ ظهرت فائدة ولايته.\rالمسألة السادسة:\r"]], "pg": [702, 703]}, "561.495": {"x": [[703, "قال بعض علمائنا: المولى الناصر، وهذا ضعيف من وجهين:\rأحدهما: أن وَلِيَ وهو \" و ل ي\" ليس معنى \"ن ص ر\" بحال.\rالثاني: أن الله فرّق بينهم فقال: \"نِعْمَ المَوْلى وَ نِعْمَ النَّصِيرُ\" (الأنفال 40)، ولو كان بمعنى واحد ما فرّق بينهما، لأن ذلك لا يَرِد في الكلام الجزْل الفصيح.\rالفصل الرابع: في التنزيل:\r"]], "pg": [703, 703]}, "561.496": {"x": [[703, "إذا ثبت هذا فالمنزلة العُليا لله تعالى في هذا تُوجب له أحكاماً يختصّ بها خمسةً:\r"], [704, "الأول: محبّته لأوليائه.\rالثاني: نصرته لهم على الأعداء.\rالثالث: متابعة النصر.\rالرابع: صيانته في جميع الأحوال.\rالخامس: كفايته المهمات.\rالمنزلة الثانية للعبد:\rوذلك في حالة واحدة، وهي امتثال الأمر، وقد روى أبو أمامة عن النبي صلى الله عليه وسلم أنه قال: \"إن أغبط أوليائي مؤمن خفيف الحَاذِ، ذو حظّ من صلاة، أحسن عبادة ربّه وأطاعه في السرّ، وكان في الناس غامضاً لم يُشر إليه بالأصابع، وكان رزقه كَفافاً فصبر عليه، ثم نقر النبي بإصبعه وقال: وعُجّلَت منيّته، وقلّت بواكيه، وقلّ تراثه\".\r"], [706, "القول في وصف الكلام\r"], [708, "اعلموا –وفقكم الله- أن الخلق تقطّعوا في هذه الصفة أيادي سَبَا، وكّلهم عن سبيل الحق نبا، إلا أهل السنة؛ الذين عصمهم الله بتسديده، وأمدّهم بتأييده، وقد بينّا حقيقة القول فيها في كتاب المُقسِط، وهي صفة معقولة قام دليل العقل عليها، مسموعة ورد السمع بها، وقد أثبتها أهل الحق، ونفاها أهل الزيغ.\rواختلف علماؤنا في طريقها، فمنهم من قال: طريقها العقل، ومنهم من قال: طريقها الخبر، وعُلم ذلك بإجماع من المسلمين، وهو قولٌ زاهقٌ لا مُعوَّل عليه، وقد حقّقنا ذلك كلّها في كتاب المُقسط، وبينّا أن حقيقة الكلام المعنى القائم بالنفس، وأن الأصوات والحروف عبارة عنه، كالكِتبة والإشارة، والخلاف في الأصوات والحروف هل هي حقيقة أم لا بما يُغني عن إعادته، والأسماء الراجعة إلى معنى الكلام والأوصاف العائدة إليه اثنان وثلاثون اسماً:\r"], [709, "الاسم الأول: مُكَلِّمٌ\rإن الناس وإن كانوا قد اختلفوا في جهة وصفه بذلك فإنهم قد أجمعوا على جواز إطلاقه عليه، لوجود فعله المطلق في القرآن، قال الله تعالى: \"وكلَّمَ الله مُوسى تَكْليماً\" (النساء 163).\r"], [710, "الاسم الثاني: متكلِّمٌ\rقال علماؤنا: ويجوز وصفه به وإن لم يَرد فعله عند الناس، إلّا الإسكافي، فإنه قال: لا يجوز ذلك، لأنه على وزن متفعِّل، وهو الذي يكتسب الفعل، وذلك لا يليق بوصفه.\rوالجواب: أنه قد ورد به الفعل في حديث الإفك عن عائشة رضي الله عنها، قالت فيه: \"ولشأني في نفسي كان أحقر من أن يتكلّم الله فيّ بوحيٍ يُتلى\"\r"], [711, "ثم نقول: إن هذه تاء التخصيص لا تاء الاكتساب، كقوله: متكبِّر، وإنّما حمله على هذا جهله بحال التاء، وظنّه أن له باباً واحدا، وهو الاكتساب، وكل مُكتَسِبٍ لشيء يختصّ به، فعبّر بها عن الاختصاص الذي لم يتقدمه كَسْب.\rجواب آخر: وذلك أننا نقول: ينبغي أن لا تُسمّيَه معلوما ولا معبودا، لأنه على وزن مفعول.\r"], [712, "الاسم الثالث: قائلٌ\rفيه فصلان:\rالفصل الأول: في شرحه لغة\r"]], "pg": [703, 712]}, "561.497": {"x": [[712, "اختلف الناس في القول والكلام والخطاب هل هي شيء واحد أم لا؟\rفقال بعضهم: هي ألفاظ مترادفة ترجع إلى شيء واحد، وقال بعضهم: هي مختلفة، فالقول ما خفّ أفاد ولم يُفد، والكلام ما ثَقُل فأفاد، ومعلوم أنّ كل مُفيدٍ ثقيلٌ لكثرته، وما لا يفيد إذا ثقل كان خفيفا، والخطاب من الكلام ما كان له خَطْبٌ، ومن ذلك لا تجزء الخُطبة إلا بكلام له بالٌ، وهذا يُستقصى في أصول الدين والفقه.\rوالحق عندي أنهما شيء واحد لفساد القول بالفرق، وعدم الدليل على صحته، وقد عضدوا ذلك بأدلة من الاشتقاق كلّها فاسدة دعاوي، تكلّمنا عليها بما فيه كفاية.\r"], [713, "الفصل الثاني: في حقيقته وأقسامه\r"]], "pg": [712, 713]}, "561.498": {"x": [[713, "إذا ثبت أن القول والكلام شيء واحد فحقيقتهما واحدة، وهي المعنى القائم بالنفس على موافقة العلم، بخلاف الوسواس وأحاديث النفس الطارئة بالظنون والشكوك، ولذلك استحالت في الباري سبحانه لاستحالة الحوادث عليه.\rوأما أقسامه فقد استوفيناها بخلافها، وأدلتها في أصول الدين، لبابه أنها أربعة؛ وهي:\rالأمر، والنهي، والخبر، والاستخبار، فتعددت إلى ثمانية أسماء: مُكلِّم، متكلِّم، قائل، مخبِر، مستخبِر، مخاطِب، آمر، ناهٍ؛ أما المكلِّم والمتكلِّم والقائل فقد تقدّمت.\r"], [714, "الاسم الرابع: مخبِرٌ\rقد بينّا حقيقة الخبر في كتب أصول الفقه، وأنه أحد أقسام الكلام ينفرد عنها ويختص بها، فإنه يدخله الصدق والكذب، وقد أخبرنا الله تعالى بخبر من مضى ومن يأتي، وهو أيضا مستخبِرٌ فيه، فكان بذلك مُخبِرا.\rقال علماؤنا: وخبره وعده ووعيده، والقصص فيما مضى وما يأتي، وهو أيضا مستخبر فيه لا على معنى الاستعلام، ولكن على وجه التقرير، ليُركِّب على ذلك ما أراد من الحجة وقدّر من المصلحة، وهو الاسم الخامس.\r"], [715, "الاسم السادس: مُخاطِب\rوقد تقدّم\r"], [716, "الاسم السابع والثامن: آمرٌ ناهٍ\rوقد أمر تعالى ونهى، وأخبر بذلك عن نفسه في كتابه العزيز؛ وحقيقة الأمر اقتضاء الفعل بالقول من الأعلى، والنهي اقتضاء الترك، وقد أطنبنا في ذلك في أصول الفقه، لأنه بابه.\rفهذه مقدّمات أسماء الكلام وصدورها، وهي لبيان الحقائق لا للتضرّع والابتهال.\rوقد اختلف علماؤنا هل الباري في الأزل، ومن قبل أن يخلق الخلق، آمرٌ، ناهٍ، مُخبر، مستخبر، مكلِّم، مخاطب، أم لا؟ على قولين، بعد اتفاقهم على أنه في الأزل متكلّم قائل، وقد بيّنّا ذلك كلّه في كتب المقسِط والمتوسِّط.\r"], [717, "وهذه الأسماء الثمانية متفق بين علمائنا على جواز إطلاقها عليه سبحانه، لوجود أفعالها في الشريعة ووجود بعضها بصيغة الأسماء وأنها أوصاف كمال.\r"], [718, "الاسم التاسع: المُبِين\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [713, 718]}, "561.499": {"x": [[718, "قال الله تعالى: \"أَنَّ اللَّهَ هُوَ الْحَقُّ الْمُبِينُ\" (النور 25)، وورد في حديث أبي هريرة المفسّر ذكر المبين، واختلف الضابطون له، فمنهم من ضبطه بالتاء المعجمة؛ باثنتين من فوقها، من القوّة، ومنهم من ضبطه بالباء المعجمة بواحدة، وبالياء بعدها معجمة باثنتين من تحتها، من الإعراب والإبانة.\rوجاء في حديث أبي هريرة من طريق عبد العزيز بن الحُصين مفسَّرا مضبوطا، المبين بالباء المعجمة بواحدة.\r"], [719, "الفصل الثاني: في شرحه لغة\r"]], "pg": [718, 719]}, "561.500": {"x": [[719, "البيان في اللغة هو الفصل بين كل شيئين، يقال: بان أي فارق، وأبان أي فصل، والمعنى متقارب، وبان لك واستبان وأبان وبيّن وتبيّن بمعنى واحد، قال تعالى: \"هذا بيانٌ للناسِ\" (آل عمران 138)، أي فصْلٌ بين الحق والباطل، و \"خَلَقَ الإنْسانَ عَلَّمَهُ البَيانَ\" (الرحمن 3)، أي تمييز المعاني بعضها من بعض، وفصْل كلّ حقيقة من غيرها، والمبين فاعل من أبان، وأبان أفعل من بان، وبان عبارة عن انقطاع شيء من شيء، وانفصاله عنه وخروجه منه، وبه سُمّي البيان كما تقدّم.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [719, 719]}, "561.501": {"x": [[719, "فيه مسألتان:\rالمسألة الأولى: في حقيقته\r"]], "pg": [719, 719]}, "561.502": {"x": [[719, "إذا عرفتم معناه في اللغة، فإن حقيقته أيضا كذلك، لا اختلاف فيها، وإنما يختلف التعلُّق في الإبانة، فيقال لمن أعرب عن الشيء: أبان، فيعود إلى الكلام، ويقال لمن فصَل شيئا عن شيء يُمازجه: أبان، ويكون من صفات الأفعال، قال صلى الله عليه وسلم: \"ما أُبِين من حيّ فهو ميّتٌ\"، وكل ذلك حقيقة.\r"], [720, "المسألة الثاني: في عقيدته\r"]], "pg": [719, 720]}, "561.503": {"x": [[720, "إذا عرفتم الحقيقة، فالعقيدة متركّبة عليها، فإنّا إذا قلنا إن الباري مُبين بمعنى ذكر للأشياء بالتفصيل الموضِّح لها فهو مبينٌ بكلامه، كما قال سبحانه في صفة التوراة: \"وتَفْصِيلاً لّكلّ شَيْءٍ\" (الأنعام 154)، وهي في صفة القرآن: \"تَبْياناً لّكُلِّ شَيْءٍ\" (النحل 89)، وإذا نظرنا إلى إبانته لآياته وأدلّته الدالة على وحدانيته بما خلقها عليه من العبرة، ويسّر فيها من الفطرة، كان ذلك من صفات الفعل، وصار بذلك معنى المُبين والفاصل واحداً، وهو الاسم العاشر.\rالفصل الرابع: في التنزيل\r"]], "pg": [720, 720]}, "561.504": {"x": [[720, "الباري سبحانه يختص في منزلته العليا في هذا الاسم بحُكمين:\rأحدهما: بالبيان البالغ بالقول الذي لا يوصف بأنه مخلوق.\rالثاني: خلقه للأدلّة.\rوللعبد في المنزلة السفلى\rحكمان:\rأحدهما: تبيُّن العلوم وتعلّمها.\rالثاني: إبانتها بعد وإفاضتها.\r"], [721, "الاسم الحادي عشر: المُعلِّم\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [720, 721]}, "561.505": {"x": [[721, "قال تعالى: \"الرَّحْمَنُ عَلَّمَ الْقُرْآنَ خَلَقَ الْإِنْسَانَ عَلَّمَهُ الْبَيَانَ\" (الرحمن 1 - 3)، وورد في دعاء عبد المطلب في الاستسقاء بحضرة النبي صلى الله عليه وسلم وهو غلام يافع: \"اللهم سادّ الخَلّة، وكاشف الكربة، أنت معلِّمٌ غير مُعلَّم\".\rالفصل الثاني: في شرحه لغة\r"]], "pg": [721, 721]}, "561.506": {"x": [[721, "المعلّم فاعل من علّم، يقال: علّمت وأعلمت بمعنى واحد، وهو إيصال العلم إلى الغير.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [721, 721]}, "561.507": {"x": [[721, "الباري تعالى هو العالم الأول الأعظم، وهو المعلِّم الأكبر، فإنه أوصل العلم إلى العالمين من عباده، ويكون ذلك بخمس طرق:\r"], [722, "الأولى: أن يكون ما يخلق ابتداءً ف النفس؛ كعلم المبدإ والعاقبة إلى آخر العلوم الضرورية.\rالثانية: تعليم النظر والتركيب في المعارف، حتى يعلم ممّا عُلّم ما كان به جاهلا، وذلك للفرق بين الحق والباطل، والنافع والضارّ؛\rالثالثة: تعليمه التكلّم باللسان، والعبارة عمّا في الجَنان من الكلام.\rالرابعة: تعليمه الكتابة.\rالخامسة: خلْقُ العلم بالإلهام، وذلك جائز، إلا في باب الفرق بين الحق والباطل فلا؛ لثبوته، حسب ما بينّاه في كتب الأصول.\rفأمّا العلوم الضرورية، فهي مخلوقة في النفس ابتداءً، وأما سائر العلوم فإنما يعلمها العالم بالكلام، خلق الله الملَكَ وخلق له العلوم الضرورية، وكلّمه وخلق له العلم بالكلام ومعناه وفائدته.\rالفصل الرابع: في التنزيل:\r"]], "pg": [721, 722]}, "561.508": {"x": [[722, "المنزل العليا للربّ:\rفي أربعة أحكام:\rالأول: أنه المعلِّم الأول.\rالثاني: أنه لا يعلَّم.\r"], [723, "الثالث: أنه لا علم إلا منه.\rالرابع: أنه آخر المعلِّمين.\rالمنزلة السفلى للعبد:\rأن يعلم أن العلم كلّه لله، وأن يرى لمعلّمه ما لا يرى لوالده.\r"], [724, "الاسم الثاني عشر: الصادق:\rفيه أربعة فصول:\rالفصل الأول: في مورده\r\r"]], "pg": [722, 724]}, "561.509": {"x": [[724, "هو اسم لم يرد به القرآن، وجاء في السنة في حديث أبي هريرة من طريق عبد العزيز ابن الحُصين، وورد فعلا فيهما، وورد قوله: \"وَمَنْ أَصْدَقُ مِنَ اللَّهِ قِيلًا\" (النساء 122)، \"وَمَنْ أَصْدَقُ مِنَ اللَّهِ حَدِيثًاً\" (النساء 87)، وقال ابن مسعود: \"حدثني رسول الله صلى الله عليه وسلم وهو الصادق المصدوق\".\rالفصل الثاني: في شرحه لغة\r"]], "pg": [724, 724]}, "561.510": {"x": [[724, "اعلموا –وفقكم الله- أن الصّاد والدّال والقاف تتصرف في اللغة على معانٍ كثيرة؛ يجمعها من يشترط الجمع، ويُفرّقها من لا يرى ربط الألفاظ إلى معنى واحد، والمقصود منه الآن في مسألتنا هذه أنّ الصدق عبارة عن اتّفاق الخبر والمخبَر به واتّساق القول والفعل.\r"], [725, "الفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [724, 725]}, "561.511": {"x": [[725, "أما الحقيقة فقد قدّمناها، وأمّا العقيدة فإن جماعة ظنّوا أن الكذب إنما يتحقق بأن يقول: إن الكلام عبارة عن المعنى القائم بالنفس، واللسان يُعبّر عنه، فإذا وافق قول اللسان عَقْدَ الجنان فذلك الصدق، وإذا خالفه فهو الكذب، وليس كذلك، بل نقول –وهو الغاية في البيان والتحقيق-:\rإن الكلام هو المعنى القائم بالنفس، والعلم يتعلّق بالمعلوم على ما هو به، فإذا كان الكلام النفسيّ أو اللفظيّ موافقاً للعلم فهو الصدق، وإذا كان مخالفاً له فهو الكذب، وقد يكون الكذب بقصد و بغير قصد، والحقيقة فيه واحدة، وإنما تختلف في الأجر والوزْر، وما أخبر الله تعالى عنه فخبره موافق لعلمه لا يجوز غيره، فلذلك كان صادقا، والكذب عليه محال حسب ما بيّنّاه في المُقسِط.\rالفصل الرابع: في التنزيل\r"]], "pg": [725, 725]}, "561.512": {"x": [[725, "المنزلة العليا للربّ في هذا الاسم يختصّ بحكم واحد، وهو وجوب الصدق له، واستحالة الكذب عليه.\rالمنزلة الثانية للعبد:\rفرض الصدق عليه في القول والفعل، وتحريم الكذب عليه.\r"], [726, "الاسم الثالث عشر: الدّاعي\rوفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [725, 726]}, "561.513": {"x": [[726, "اعلموا –وفقكم الله- أن هذا الاسم ورد به القرآن فِعلا ولم يرد به اسماً، وله إخوةٌ، وهي: المنادي، والمناجي، والمجيب، والمستجيب، فهذه خمسة أسماء متقاربة مرتبطة إلا المجيب، فإنه ورد في القرآن، قال تعالى: \"إِنَّ رَبِّي قَرِيبٌ مُّجِيبٌ\" (هود 61)، وورد في حديث أبي هريرة المفسّر.\rوأما الداعي فقال تعالى: \"يَاأَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ\" (الأنفال 24)، وقال: \"ثُمَّ إِذَا دَعَاكُمْ دَعْوَةً مِّنَ الْأَرْضِ إِذَا أَنتُمْ تَخْرُجُونَ\" (الروم 25)؛ وكذلك المُنادي ورد في القرآن فِعلاً، قال تعالى: \"وَنَادَيْنَاهُ مِن جَانِبِ الطُّورِ الْأَيْمَنِ\" (مريم 52)، ولم يرد في السنة؛ وكذلك المُناجي، ورد نحوٌ منه في القرآن، قال تعالى: \"وَقَرَّبْنَاهُ نَجِيًّا\" (مريم 52)؛ وكذلك المستجيب، قال تعالى: \"وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ\" (غافر 60).\rالفصل الثاني: في شرح هذه الأسماء لغة\r"]], "pg": [726, 726]}, "561.514": {"x": [[726, "أمّا الدعاء فقال علماؤنا –رحمة الله عليهم-: له في اللغة معنيان: أحدهما الطلب، الثاني النداء، فالأوّل قوله: اهدنا واغفر لنا.\r"], [727, "الثاني كقوله: يا أيها الناس، يا أيها الذين آمنوا، والأول راجع إلى الثاني، فإن الطلب نداءٌ معنويّ، وقد يكون الدعاء بمعنى الترغيب، كقوله: \"وَاللَّهُ يَدْعُو إِلَى دَارِ السَّلامِ\" (يونس 25)، وقد يكون بمعنى التكوين، كقوله: \"ثُمَّ إِذَا دَعَاكُمْ دَعْوَةً مِّنَ الْأَرْضِ إِذَا أَنتُمْ تَخْرُجُونَ\" (الروم 25).\rوأما الإجابة فلها معنيان:\rأحدهما: قول المدعوّ لبّيك لمن دعاه؛\rالثاني: بذل المسؤول والمطلوب، وهي الاستجابة بعينها، غير أن تسمية البذل استجابةً مجازٌ، وإيّاه عَنَى سلامة بن جَنْدل بقوله:\rإنّا إذا ما أتانا صارخٌ فَزعٌ *** كان الصراخ له قرع الظّنابيب\rوأما النداء فهو الدعاء على بُعدٍ، والمناجاة المحاورة في السرّ.\rالفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [726, 727]}, "561.515": {"x": [[727, "وفيه مسألتان:\rالمسألة الأولى: في تركيب المعنى الاعتقادي على اللغوي\r"]], "pg": [727, 727]}, "561.516": {"x": [[727, "إذا قلنا إنّ الدعاء بمعنى الطلب فلا يصحّ ذلك في وصف الباري تعالى، لأنه يُطلب منه ولا يَطلب، كما أنه يُطعِم ولا يُطعَم.\r"], [728, "وإذا كان الدعاء بمعنى النداء فالباري تعالى نادى عباده في الأزل بكلامه: يا أيها الناس، يا أيها الذين آمنوا.\rوإذا قلنا إن الأجابة: قول القائل لبيك، فالباري مجيبٌ بنحوٍ من عشرين وجها بيّنّاها في كتاب المشكلين في باب الدعاء، فإن كانت الإجابة بذل المطلوب رجع إلى الفعل، فيكون على معنيين؛ تارة من صفات الذات، وتارة من صفات الفعل.\rوأمّا المناجاة فقد ناجى ربّنا موسى ومحمّدا صلى الله عليهما وسلم.\rالمسألة الثانية: في كيفية الإجابة.\r"]], "pg": [727, 728]}, "561.517": {"x": [[728, "وبيانها في المشكلين.\rالفصل الرابع: في التنزيل:\r"]], "pg": [728, 728]}, "561.518": {"x": [[728, "المنزل العليا للربّ:\rوله في ذلك أحكام ستّة:\rالأول: الإجابة قبل الدعاء\rالثاني: البذل قبل السؤال.\rالثالث: الإنالة فوق الاستنالة.\r"], [729, "الرابع: التعويض بالإفضال.\rالخامس: التقريب باختصاص الكلام دون سماعٍ.\rالسادس: ألّا يُخيّب داعياً.\rالمنزلة الثانية للعبد:\rله فيها أحكامٌ جِماعها الإخلاص في الدعاء والطاعة في العمل.\r"], [730, "الاسم الثامن عشر: الذّاكر\rهذا اسم يأتي بيانه في الأسماء الواجبة له سبحانه من غيره، عقب الكتاب إن شاء الله تعالى.\r"], [731, "الاسم التاسع عشر: المنّان\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [728, 731]}, "561.519": {"x": [[731, "لم يرد به كتاب ولا سنة في الأسماء، لكن ورد فعلا، قال سبحانه: \"وَلَكِنَّ اللَّهَ يَمُنُّ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ\" (إبراهيم 11)، وقال: \"فَمَنَّ اللَّهُ عَلَيْنَا وَوَقَانَا عَذَابَ السَّمُومِ\" (الطور 27)، وجاء في بعض الآثار الضعيفة أن الرجل يُنادي بصوت ضعيف: يا حنّان يا منّان.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [731, 731]}, "561.520": {"x": [[731, "المنّ ذِكْر النعم والاستعداد بها على المنعَم عليه، قال الله سبحانه: \"يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا\" (الحجرات 17) الآية.\rالفصل الثالث: في الحقيقة\r"]], "pg": [731, 731]}, "561.521": {"x": [[731, "المنّ حقيقةٌ في ذكر النعم، كما سبق شرحه في اللغة، ولكنّه ينطلق على نفس النعمة انطلاقا سائغا، قال الله سبحانه: \" فَمَنَّ اللَّهُ عَلَيْنَا وَوَقَانَا عَذَابَ السَّمُومِ\" (الطور 27)، ولكن الحقيقة فيه الذكر، فلذلك أدخلناه في\r"], [732, "باب الكلام، والباري تعالى قد ذكّر عباده نعمه في الدنيا وعدّدها عليهم فيها، وسيفعل ذلك في الآخرة، وذلك أمر يختصّ به الباري تعالى لا يجوز لغيره، فإن منّ أحد بشيء سواه كان ذلك قَدْحاً فيه، قال الله سبحانه: \" يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُبْطِلُوا صَدَقَاتِكُم بِالْمَنِّ وَالْأَذَى\" (البقرة 264)، على ما بيّنّاه في مسائل الإحباط من المشكلين.\rالفصل الرابع: في التنزيل\r"]], "pg": [731, 732]}, "561.522": {"x": [[732, "المنزلة العليا للربّ\rيختص فيها بأنه يَمُنّ بالعطاء.\rالمنزلة السفلى للعبد:\rالاعتراف بالمنّة لله وحده، كما روي أن النبي صلى الله عليه وسلم لما جمع الأنصار فذكّرهم وقال: \"ألم يكن أمركم شتيتاً فجمعه الله بي، ألم تكونوا عالةً فأغناكم الله بي، ألم تكون خائفين فأمّنكم الله بي\"، وهم في ذلك كلّه يقولون: الله ورسوله أمَنّ، الحديث إلى آخره، فاعترفوا لله ثم لرسوله بالمنّة، وولّوُا النعمة ربَّ النعمة، والله أعلم.\r"], [733, "الاسم المُوَفّي عشرين: الهادي\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [732, 733]}, "561.523": {"x": [[733, "ورد به القرآن اسماً وفعلاً، قال تعالى: \" وَكَفَى بِرَبِّكَ هَادِيًا وَنَصِيرًا\" (الفرقان 31)، والأفعال فيه كثيرة، وقد تردّد ذكر الهدى في القرآن في عدّة مواضع، وفي جامع الموطإ عن عبد الله بن الزبير أنه كان يقول: \"إن الله هو الهادي والفاتن\"، ذلك لتعلموا أن السلف كانوا يشتقّون الأفعال من الأسماء، والأسماء من الأفعال، فاقتدوا بهم تَرشُدُوا.\rالفصل الثاني: في شرحه لغة وعقدا\r"]], "pg": [733, 733]}, "561.524": {"x": [[733, "اتّفق علماء اللغة على أن الهدى هو الميْل، قالوا: فلا يتهادى في مشيه بين اثنين، إذا كان يتمايل، وردّوا كلّ شيء ورد من هذا اللفظ إلى هذا المعنى؛ من إهداء العروس إلى زوجها ونحوه.\r"], [734, "الفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [733, 734]}, "561.525": {"x": [[734, "وفيه ثلاث مسائل:\rالمسألة الأولى: في حقيقة الهداية\r"]], "pg": [734, 734]}, "561.526": {"x": [[734, "إذا ثبت أن حقيقة الهداية الإمالة، ففيها سرٌّ غريب، وذلك أن الميْل إذا كان إلى حالة محمودة كان هُدىً، وإذا كان إلى حالة مذمومة كان عِوَجاً، وينصرف إلى طريق غير ذلك، فبهذا سُمّيت دعوة الرسل هداية، كما قال تعالى: \" وَإِنَّكَ لَتَهْدِي إِلَى صِرَاطٍ مُّسْتَقِيمٍ\" (الشورى 52)، معناه تدعو، وكما قال تعالى: \" وَأَمَّا ثَمُودُ فَهَدَيْنَاهُمْ\" (فصلت 17)، معناه دعوناهم، وسُمّيت إمالة القلوب إلى الحق هداية كما قال تعالى: \" إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ\" (القصص 56)، قال علماؤنا: معلوم أن هذه الهداية غير تلك، وإلا فما كان لينفي عنه ما أثبت له؛ وقد زلّت المبتدعة في درَج هذا الاسم عن حقيقته إلى درك الخذلان فقالوا: إن \"الله يهدي\" بمعنى يدعو، ويُبيّن طريق الجنة خاصّة، وقد بيّنّا ذلك في كتاب المُقسِط.\r"], [735, "المسألة الثانية: في انقسام الهدى\r"]], "pg": [734, 735]}, "561.527": {"x": [[735, "وهو واردٌ في كتاب الله تعالى على ثمانية معانٍ بيّنّاها في كتاب المشكلين، والذي تحتاجون إليه وتُعوِّلون عليه أن الباري تعالى هادٍ بكّل معنىً، لا يخرج منه معنىً عن يده، ولا يرجع لفظٌ إلا إليه.\rالمسألة الثالثة: في كونه من صفات الذات أو من صفات الأفعال؟\r"]], "pg": [735, 735]}, "561.528": {"x": [[735, "وقد ذكرنا أنه بثمانية معانٍ:\rأحدها: الدعاء.\rوالثاني: البيان.\rوالثالث: خلق الأدلة الهادية إليه.\rفيكون تارة من صفات الذات، ويعود إلى الكلام، وتارة يكون من صفات الأفعال كسائر الأسماء المتقدمة المنقسمة إلى الوجهين.\rالفصل الرابع في التنزيل\r"]], "pg": [735, 735]}, "561.529": {"x": [[735, "إذا عرفتم –عرّفكم الله المراشد- معنى الهدى والهادي، فالباري تعالى يختص في ذلك في المنزلة العليا بأحكام ثلاثة:\r"], [736, "الأول: أن الهدى هدى الله كما أخبر سبحانه، يختصّ به من يشاء.\rالثاني أن هدى الخلق بيده؛\rالثالث: أن البيان إليه بقوله كلاما، وبقدرته خلقاً وإلهاما.\rالمنزلة السفلى للعبد:\rترتبط بحكمين:\rأحدهما: أن يعلم أن الهداية منه وبه.\rوالثاني: أن يجتهد في هداية الناس والبيان لهم.\r"], [737, "الاسم الحادي والعشرون: الرشيد\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [735, 737]}, "561.530": {"x": [[737, "ورد به الخبر خاصّة في حديث أبي هريرة المفسّر، ووقعت الإشارة في القرآن إليه.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [737, 737]}, "561.531": {"x": [[737, "اختلف فيه علماء هذا الشأن:\rفقال قوم: إن الرشيد فعيلٌ بمعنى مُفعِل، أرشَدَ إلى مصالح الخلق.\rالثاني: قال آخرون: رشيد بمعنى ذي الرُّشد، فعيل بمعنى فاعل، لاستقامة تدبيره، وإصابته في أفعاله.\rالفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [737, 737]}, "561.532": {"x": [[737, "فيه مسألتان:\r"], [738, "المسألة الأولى: في حقيقة اللفظ\r"]], "pg": [737, 738]}, "561.533": {"x": [[738, "لمّا قالت العرب رشَد يرشد رُشداً، فهو راشدٌ ورشيدٌ، وأرشده إذا هداه، وقال تعالى: \" مَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُ وَلِيّاً مُّرْشِداً\" (الكهف 17)، وقال تعالى: \" وَابْتَلُوا الْيَتَامَى حَتَّى إِذَا بَلَغُوا النِّكَاحَ فَإِنْ آنَسْتُمْ مِنْهُمْ رُشْدًا\" (النساء 6)، وروي في الحديث: أن قوماً جاؤوا إلى النبي صلى الله عليه وسلم فقالوا له: نحن بنو غيّان، فقال: بل أنتم بنو رشدان، فجعله مقابل الغيّ، ويقال: فلانٌ لرِشْدَةٍ، وفلان لزينة.\rاستقرينا من هذا أن حقيقة الرّشد والهدى متقاربتان، أو هما هما، ورجعت حقيقة الرّشد في الحصر إلى معنيين:\rأحدهما: استقامة الأحوال، كقوله تعالى: \" فَإِنْ آنَسْتُمْ مِنْهُمْ رُشْدًا\".\rوالثاني: البيان للصّواب، كقوله: \" فَلَن تَجِدَ لَهُ وَلِيّاً مُّرْشِداً\".\rالمسألة الثانية: في العقيدة فيه\r"]], "pg": [738, 738]}, "561.534": {"x": [[738, "أمّا الرشيد بمعنى استقامة الأفعال وسدادها، وجرْيِها على مقتضى الأمر والحدّ، فلا يوصف الباري تعالى به إلا على نوع مجازٍ، فإن أفعاله مطَّرِدةٌ\r"], [739, "على الحكمة، فإن قرنت الاستقامة بالاستقامة وعُبّر عن الحكمة بالرشد جاز، ولم أرَهُ ولا أستعملُهُ في حقّه.\rوأمّا إذا كان بمعنى البيان، وهو الإرشاد إلى المصالح كما أخبر عن نفسه تعالى، فقد كان ذلك بكلامه، وينقسم انقسام الهدى، ويترتّب ترتيبه.\rالفصل الرابع: في التنزيل\r"]], "pg": [738, 739]}, "561.535": {"x": [[739, "المنزلة العليا للربّ:\rوذلك بوجهين:\rأحدهما: تِبيانه للعباد، كما بيّن تعالى، ولا يصحّ أن يكون كما قال علماؤنا: له في ذلك حكم استداد الأفعال، لأنّ ذلك مجازٌ بعيدٌ لم أعلمه.\rالثاني: إرشاده الصغار من الأطفال والبهائم إلى المنافع، كالْتقام الثّدي ومصّ الضرع.\rالمنزلة السفلى للعبد:\rوذلك باستقامة الأحوال والأفعال على مُقتضى الأمر، وإرشاده غيره إلى مثل فعله.\r"], [740, "الاسم الثاني والعشرون: النّور\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [739, 740]}, "561.536": {"x": [[740, "قال الله تعالى: \" اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ\" (النور 35)، وورد في حديث أبي هريرة المفسّر النّور معدَّداً في جملة الأسماء، وكان النبي عليه السلام يقول في دعائه: \"اللهم لك الحمد، أنت نور السماوات والأرض ومن فيهن\".\rالفصل الثاني: في شرحه لغة\r"]], "pg": [740, 740]}, "561.537": {"x": [[740, "النور أنورُ من أن يُبيَّن بلفظ، أو يُدلَّ عليه بحدّ ورسم.\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [740, 740]}, "561.538": {"x": [[740, "وفيه ثلاث مسائل:\r"], [741, "المسألة الأولى: في سرد الأقوال فيه\r"]], "pg": [740, 741]}, "561.539": {"x": [[741, "اعلموا –أرشدكم الله- أن الناس بعد معرفتهم بالنور اختلفوا في وصفه تعالى بأنه نورٌ على سبعة أقوال:\rالأول: أن معناه هادٍ، قاله ابن عباس.\rالثاني: أن معناه مُنوّر، قاله ابن مسعود، وروي أن في مصحفه: الله منوِّر السماوات والأرض.\rالثالث: أنه مُزيٍّن، قاله أبيّ بن كعب.\rالرابع: أنه ظاهر.\rالخامس: أنه ذو النور.\rالسادس: أنه نورٌ لا كالأنوار، قاله الأشعري.\rالسابع: أنه لا يقال فيه إنه نور إلا بالإضافة، قاله المعتزلة.\rالمسألة الثانية: في توجيه الأقوال\r"]], "pg": [741, 741]}, "561.540": {"x": [[741, "إذا قلنا إنه نور بمعنى أنه هادٍ فقد تقدّم بيانه، وهو الهادي تعالى، وهُداه نورٌ كما قال: \" وَجَعَلْنَا لَهُ نُورًا يَمْشِي بِهِ فِي النَّاسِ\" (الأنعام 123)، وقال\r"], [742, "تعالى: \" اللَّهُ وَلِيُّ الَّذِينَ آمَنُوا يُخْرِجُهُم مِّنَ الظُّلُمَاتِ إِلَى النُّورِ\" (البقرة 227)، يعني من الضلالة إلى الهدى.\rوإذا قلنا إنه نورٌ بمعنى أنه مُنوِّرٌ فهو تعالى خالق الأنوار في السماوات والأرض، والدنيا والآخرة، لأنها كلها نورٌ، في القلب بمكاشفة التوحيد، وفي الأبصار والأبدان بالعبادات، فيكون كما قال تعالى: \" نُّورٌ عَلَى نُورٍ\" (النور 35)، وفي القبر عند المساءلة والتثبيت، وعلى الصراط.\rوإذا قلنا: إنه المُزَيّن فهو الذي زيّن الدنيا بمصابيح وبزينة الكواكب، وهو يرجع إلى النور، لأن الزينة من النور.\rوإذا قلنا إنه الظاهر فقد تقدّم بيانه.\rوإذا قلنا إنه ذو النور، فلا يخرج عمّا تقدّم، لأن العرب تُسمّي من فيه الشيء باسمه، كما يُسمّون العادل بالعَدْل، والزائر بالزَوْر، وقد قال الشاعر:\rتَرْتَعُ ما غَفَلَت حتى إذا ادَّكَرَت *** فإنّما هي إقبالٌ وإدبارُ\r"], [743, "يعني مقبلة ومدبرة، إلا أن بعض علمائنا قال: إذا قلنا إنه ذو النور، فليس النور صفة ذات له، كما يصحّ أن يُسمّى به في اسم السلام، وإنّما يكون صفة فِعل على معنى إضافة الفعل إليه، كالعدل، إذ هو خالق العدل والنور، فيكون النور المسمّى به فعلا، إمّا بما يخلق من الأنوار زينة كما تقدّم بيان جملته، وإمّا بما احتجب به من الأنوار، كما روي عن النبي صلى الله عليه وسلم أنه قال: حجابه النور، وروي: دونه سبعون حجابا من النور، وكما روي أن أبا ذر قال: \"سألت رسول الله صلى الله عليه وسلم: \"هل رأيت ربك؟ قال: أنّى أراه، رأيت نوراً\".\rويجوز أن يكون صفة ذاتٍ على معنى أن يكون النور الهدى، فإن الهادي بقوله سبحانه، وهو صفة ذاته، وعلى معنى أنه ذو الظهور وهو الظاهر بذاته وأدلّته، على ما بيّنّاه في موضعه.\rوإذا قلنا إنه نورٌ لا كالأنوار فإنّما ذهب في ذلك الشيخ أبو الحسن رضي الله عنه إلى ظاهر الكتاب والإطلاق الشرعي من غير نظرٍ في تأويل ولا صرفٍ عن ظاهر، كما قلنا: إنه موجود لا كالموجودات، حقٌّ ليس كسائر الحقائق.\r"], [744, "وأمّا قول المعتزلة إنه نورٌ بالإضافة كما ورد في القرآن، فإنما بَنَتْ ذلك على أنه من صفات الأفعال، وإلّا فإن استحال أن يقال فيه إنه نور مطلقاً استحال أن يقال فيه إنه نورٌ مضافا إلى شيء، لأنّ ما ثبت أنه يستحيل على الله صفة إذا أضيف يستحيل عليه وإن أُطلق.\rالمسألة الثالثة: في المختار\r"]], "pg": [741, 744]}, "561.541": {"x": [[744, "قد بيّنّا مقاصد الأقوال والقائلين، ومن تأمّلها بذكر حاضر ونظرٍ صافٍ أشرف بها على جميع ما أشرنا إليه في كتاب المشكلين؛ في تأويل قوله: \"\" اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ\" (النور 35).\rوالصحيح عندنا أنه نور لا كالأنوار لأنه الحقيقة، والعدول عن الحقيق إلى أنه هادٍ أو منوِّرٌ وما أشبه ذلك –وهو مجازٌ- من غير دليل لا يصحّ، ولأن الأثر الصحيح يعضده، ويصحّ أن يكون على هذا صفة ذاتٍ، ويصحّ أن يكون صفة فعل على معنى أنه ظاهر، إذ روح النور البيان والظهور، ويحتمل حينئذ الوجهين من صفات الذات والفعل كما تقدّم في نظائره، ولولا اتفاق الصحابة والسلف فيه على المجاز وجعله من الهدى والتزيين، ولم يكن لنعدل\r"], [745, "عن مقصد السلف فالتزمنا أنه الهادي، لأن الهدى قرين النور في كتاب الله ولزيمه أين وقع.\rالفصل الرابع: في التنزيل:\r"]], "pg": [744, 745]}, "561.542": {"x": [[745, "المنزلة العليا لله:\rفي هذا الاسم يختصّ فيها بأحكام ستّة:\rالأول: أحكام الهدى كلّها.\rالثاني: ها هنا زيادة انشراح للهدى باتّساع النور.\rالثالث: خلق الأنوار السماوية.\rالرابع: خلق الأنوار الأرضية.\rالخامس: خلق الأنوار الأخروية.\rالسادس: خلقها في الأبدان، وهاذا ممّا انفرد به أهل السنة، وأنكرته المعتزلة حرمها الله ذلك.\rالمنزلة السفلى للعبد:\rمن جهتين:\rالأولى: أن يكون ذا نور في نفسه لمعرفته وطاعته.\rالثانية: أن يكون مُنوّراً لغيره بأن يكون معلِّماً للخير، وذلك على الكمال للعبيد، وذلك بالحقيقة هو الذي سمّاه الله نورا وسراجا منيرا، محمد صلى الله عليه وسلم.\r"], [746, "الاسم الثالث والعشرون: المؤمن\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [745, 746]}, "561.543": {"x": [[746, "هو اسم ورد به القرآن، قال الله تعالى: \"السَّلَامُ الْمُؤْمِنُ\" (الحشر 23)، وفي حديث أبي هريرة المفسّر المعدَّد المؤمن.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [746, 746]}, "561.544": {"x": [[746, "اعلموا –وفقكم الله- أن له في اللغة معنيين:\rأحدهما: أن الإيمان بمعنى التصديق، قال تعالى: \"وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا\" (يوسف 17).\rالثاني: أن يكون المؤمن من الأمان، قال النابغة:\rوالمؤمن العائذات الطير تمسحُها *** ركبانُ مكّة بين الغِيل والسّند\r"], [747, "الفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [746, 747]}, "561.545": {"x": [[747, "وفيه ثلاث مسائل:\rالمسألة الأولى: في ذكر حقيقته\r"]], "pg": [747, 747]}, "561.546": {"x": [[747, "وقد علمتم أنّ له في اللغة معنيين:\rأحدهما: أنه يرجع إلى التصديق –وهو من فنّ الكلام- بقوله: صدقت، أو بما ينزل منزلة الكلام من الأفعال.\rوالثاني: يرجع إلى الأمان، وذلك يكون على وجهين:\rأحدهما: بالقول آمنْتُ.\rوالثاني: بالفعل، فيكون من قبيل المشترك، وهو حقيقةٌ فيهما، في التصديق والأمان، وهو مجازٌ في التصديق بالفعل.\rالمسألة الثانية: في شرحه اعتقاداً\r"]], "pg": [747, 747]}, "561.547": {"x": [[747, "إذا كان المؤمن المصدق فالباري تعالى مؤمنٌ بخمسة معانٍ:\rالأول: تصديقه لنفسه بقوله، وذلك حقيقة، قال الله سبحانه: \"شَهِدَ اللَّهُ أَنَّهُ لَا إِلَهَ إِلَّا هُو\" (آل عمران 18)، وصدق الله.\r"], [748, "الثاني: تصديقه لرسله بإظهار المعجزة الدّالّة على صدقهم على أيديهم، وذلك مجازٌ، لأنه فعلٌ نزل منزلة القول، كما بيّنّاه في كتاب المُتوسِّط والمُقسط.\rالثالث: تصديقه لأوليائه بإظهار الكرامة على أيديهم الدّالّة على كرامتهم، وهو مجازٌ أيضا.\rالرابع: تصديقه بفعله لوعده، كما قال الله سبحانه: \"الْحَمْدُ لِلَّهِ الَّذِي صَدَقَنَا وَعْدَهُ\" (الزمر 74).\rالخامس: تصديقه لعباده فيما يُخبرون به من حقٍّ، كما روي في الأخبار أن الله يقول: \"صدق عبدي\"، وكما يقول أيضا في الأخبار: \"كذَبْتَ، بل أردْتَ كذا وكذا\"، وإذا كان المؤمن هو واهب الأمان فالباري تعالى مؤمنٌ\r"], [749, "بقوله: \"الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُم بِظُلْمٍ أُولَئِكَ لَهُمُ الْأَمْنُ\" (الأنعام 82)، وبقوله: \"لا يَحْزُنُهُمُ الْفَزَعُ الأَكْبَرُ\" (الأنبياء 103)، وبقوله: \"يَا عِبَادِ لَا خَوْفٌ عَلَيْكُمُ الْيَوْمَ وَلَا أَنتُمْ تَحْزَنُونَ\" (الزخرف 68)، وبقوله: \"أنا عند ظن عبدي بي فليظنّ بي ما شاء\".\rوأمّا أمانه بالفعل، فبما وهب وأعطى من النّعم والعافية، والباري تعالى مؤمنٌ بالوجوه كلّها، ومعاني الإيمان بأجمعها.\rالمسألة الثالثة:\r"]], "pg": [747, 749]}, "561.548": {"x": [[749, "قال ابن فورك: وقد يكون إيمانه لعباده علمَه بصدقهم، وهذا على قول من قال: إن الإيمان هو العلم، وإنّما صار إلى هذا من صار إليه، لأن الكلام لا يكون صدقاً إلّا إذا وافق العلم، فإن لم يوافقه كان كذبا، فيكون مجازاً بعيداً.\rالفصل الرابع: في التنزيل\r"]], "pg": [749, 749]}, "561.549": {"x": [[749, "إذا عرفتم معناه فاعلموا أن للباري تعالى في ذلك أحكاما أربعة:\rالأول: أن الإيمان إليه، فمن أعطاه له كان مؤمناً.\r"], [750, "الثاني: أن التصديق والتكذيب به، لأنّ المؤمن هو المصدق لغةً كما بيّنّا، فمن آمن بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره فهو المؤمن، وإذا صدّق بهذه الأصول فالتكذيب بعدها يهون، وإذا كذّب بهذه فلا شيء معه.\rالثالث: أن الحقائق إليه ومعنماه أن كلّ حقيقة إذا علمتَ الإله تنكشف لك، وإن علمت أن الحقائق إليه لم يَخْفَ عليك ربّك، فالآيات توصل إليه، قال تعالى: \"أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ\" (فصلت 53).\rالرابع: أن الأمن يوجد منه، ومعناه أنه المؤمن؛ بمعنى أنه وَهَبَ الأمن كما بيّنّاه، وذلك أنه لا خوف إلا ويقابله أمنٌ، ولا يحصل ذلك الأمن إلّا به ومنه، ألا ترى أن العبد مَثَلاً يخاف في دنياه وفي آخرته، فخوفه في\r"], [751, "دنياه ما حصل له الأمن فيه إلا بالله، لأنه إن خاف الجوع والعطش فخالق القوت والماء الله، لا خالق له غيره، قال تعالى: \"أَفَرَأَيْتُمْ مَا تَحْرُثُونَ أَأَنْتُمْ تَزْرَعُونَهُ أَمْ نَحْنُ الزَّارِعُونَ\" (الواقعة 63 - 64)، وقال: \"أَفَرَأَيْتُمُ الْمَاءَ الَّذِي تَشْرَبُونَ أَأَنْتُمْ أَنْزَلْتُمُوهُ مِنَ الْمُزْنِ أَمْ نَحْنُ الْمُنْزِلُونَ\" (الواقعة 68 - 69)، وإن خاف البرج فلا أمن له منه إلا بالله، قال تعالى: \"أَفَرَأَيْتُمُ النَّارَ الَّتِي تُورُونَ أَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَا أَمْ نَحْنُ الْمُنشِئُونَ نَحْنُ جَعَلْنَاهَا تَذْكِرَةً وَمَتَاعًا لِّلْمُقْوِينَ\" (الواقعة 71 - 73)، وإن خاف الحرّ لم يأمن منه إلا بالله، قال تعالى: \"أَلَمْ تَرَ إِلَى رَبِّكَ كَيْفَ مَدَّ الظِّلَّ وَلَوْ شَاءَ لَجَعَلَهُ سَاكِنًا\" (الفرقان 45)، وإن خاف المرض فمن أنزل الدواء هو الذي أنزل الداء، أو خاف الأعداء فالجواح سلاحٌ، وفي ذلك تفصيل طويل.\rوأما أمن الآخرة فبما وهب من الإيمان ويسّر من العمل الصالح، ومنّ به من العصمة من الشيطان والمعاصي، حتى إذا عارضته الشكوك وهب اليقين، أو خطرت له الوساوس تفضّل بالتذكر، كما قال تعالى: \"نَّ الَّذِينَ اتَّقَوْا إِذَا مَسَّهُمْ طَائِفٌ مِنَ الشَّيْطَانِ تَذَكَّرُوا فَإِذَا هُمْ مُبْصِرُونَ\" (الأعراف 201).\rالمنزلة السفلى للعبد:\rإذا انتهى إلى هذا المقام فعليه أحكامٌ أربعة:\r"], [752, "الأول: أن يصدِّق ربّه.\rالثاني: أن يصدّق نبيّه.\rالثالث: أن يصدّق قوله بفعله.\rالرابع: أن يأمن الناسَ من شرّه، قال صلى الله عليه وسلم: \"من كان يؤمن بالله واليوم الآخر فليأمن جاره بوائقه\"، وفي البخاري، قال رسول الله صلى الله عليه وسلم: \"والله لا يؤمن، والله لا يؤمن، والله لا يؤمن، قيل: من يا رسول الله؟ قال: من لا يأمن جارُه بوائقه\".\r"], [753, "الاسم الرابع والعشرون: المُهَيْمِن.\rفيه أربعة فصول:\rالفصل الأول: في مورده:\r"]], "pg": [749, 753]}, "561.550": {"x": [[753, "ورد به نصّ القرآن، قال الله تعالى: \"الْمُؤْمِنُ الْمُهَيْمِنُ\" (الحشر 23)، وورد مفسّراً في حديث أبي هريرة، وقد قيل: إنه من أسمائه في الصحف والتوراة والإنجيل والزّبور.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [753, 753]}, "561.551": {"x": [[753, "اختلف الناس فيه على خمسة أقوال:\rالأوّل: أنّه الرقيب، والهيمنة الرعاية للشيء، قال الشاعر:\rألا إنّ خير الناس بعد نبيّه *** مهيمنُه التّالِيه في العُرْف والنّكرِ\r"], [754, "الثاني: الشهيد، قاله الكِسائي وقَتَادة والسُّدّي.\rالثالث: أن أصله مؤيمن، ثم قُلبت الهمزة هاءً، كما قالوا: أَرَقت وهرقت، وهِبْريةٌ وإبريةٌ لنُخالة الرأس، وهِيّاك وإيّاك.\rالرابع: أنّ المهيمن المصدِّق، قاله الحسن؛ قال الشاعر:\rإن الكتاب مهيمنٌ لنبيّنا *** والحقّ يعرفه ذوو الألبابِ\rالخامس: أنّ المهيمن الشريف، كما قال العباس يمدح النبي صلى الله عليه وسلم:\rحتى استوى بيتُك المهيمنُ من *** خِنْدِفَ علياءَ تحتها النُّطُقٌ\r"], [755, "الفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [753, 755]}, "561.552": {"x": [[755, "فيه ثلاث مسائل:\rالمسألة الأولى: في سرد أقوال العلماء فيه\r"]], "pg": [755, 755]}, "561.553": {"x": [[755, "وقد تقدّم قول أهل اللغة، وهو يتداخل مع قول العلماء، وللعلماء فيه زيادة على ما تقدّم أربعة أقوال:\rالأول: قال بعضهم: المهيمن الحافظ.\rالثاني: المهيمن الأمين، قاله ابن عباس.\rالثالث: المهيمن الدالّ، قاله عكرمة.\rالرابع: المهيمن القاضي، قاله الزبير.\rالمسألة الثانية: في بيان حقيقته\r"]], "pg": [755, 755]}, "561.554": {"x": [[755, "إذا علمتم معناه لغةً، وعلمتم أقوال علماء الدين فيه، فلا بد من النظر بعد ذلك في حقيقته، فنقول:\rاللفظة عربية فلا بد من ذكرها لغةً أوّلا، وبيان الحقّ فيها آخراً.\r"], [756, "أمّا قول المبرّد فضعيف، لأنه بناء تصغير، واسم الله عظيمٌ لا يُصغَّر، وإن ما عظم من المخلوقات وشَرُف لا يجوز تصغيره، كمصحف ومسجد، فكيف الله سبحانه؟\rوأمّا من قال إنه الشرف أخذه من قول العباس، فقد قيل في بيت العباس: إن معناه أيّها المهيمن؛ والصحيح عندي أنه راجع إلى ما تقدّم، وأنّ معناه: حتى استوى بيتك الذي هو على سائر البيوت بمنزلة الراعي من سائر الرعيّة.\rوسائر الأقوال إنما هي مُركَّبةٌ من قوله: \"مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِنًا عَلَيْهِ\" (المائدة 48)، فكلّ من نظر إلى هذا قال: معناه القاضي، كقضاء هذا الكتاب على سائر الكتب، وقال آخر: المصدِّق، وقد تقدّم ذكر المصدّق قبله.\rوقال آخر: الشاهد، وذلك لقربه من المصدّق، واتصاله بقوله: على، وإنّما هو لفظٌ جاء هكذا، كقوله مُسَيطرٌ ومُبيطرٌ لا تصغير فيه.\rالمسألة الثالثة: في المختار\r"]], "pg": [755, 756]}, "561.555": {"x": [[756, "إذا فهمتم هذا فرٍقبَة هذا الكتاب على الكتب تصديقه لما فيها من حقّ، وتكذيبه لما فيها من باطل، وذلك يعود إلى الكلام الحقّ والخبر عن\r"], [757, "العلوم، وذلك من أوصاف الذات كما تقدّم، وتطّرِد اللغة والحقيقة ويجتمع الأمران معاً، وذلك أقوى في المعنى، وأصوب في النّظر.\rالفصل الرابع: في التنزيل\r"]], "pg": [756, 757]}, "561.556": {"x": [[757, "المنزلة العليا للربّ:\rله سبحانه في هذا الاسم بكل قول من الأقوال المتقدّمة حكمٌ يختصّ به:\rالأول: أنه العالم الذي لا يخفى عليه شيء.\rالثاني: أنه الرقيب الذي أحصى كلّ شيء.\rالثالث: أنه الشهيد الذي لا يغيب.\rالرابع: أنه الحافظ بكلّ معنىً.\rالخامس: أنه يجب له الكمال.\rالسادس: أنه يستحيل عليه الزوال.\rالسابع: أنّ التصديق والتكذيب إليه، وهو الصادق الذي يستحيل عليه الكذب.\rالمنزلة السفلى للعبد:\rأن تُقابل كل صفة لمولاك من العُلوّ بما يجب لها من التواضع، وتَصْدُقَ في قولك وفعلك.\r"], [758, "الاسم الخامس والعشرون: الحميد\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [757, 758]}, "561.557": {"x": [[758, "ورد به نصّ القرآن في مواضع، قال الله تعالى: \"وَهُوَ الْوَلِيُّ الْحَمِيدُ\" (الشورى 28)، \"وَاللَّهُ غَنِيٌّ حَمِيدٌ\" (التغابن 6)، وورد مفسَّرا في حديث أبي هريرة المعدَّد، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة.\r"]], "pg": [758, 758]}, "561.558": {"x": [[758, "وفيه مسألتان:\rالمسألة الأولى: في معنى الحميد:\r"]], "pg": [758, 758]}, "561.559": {"x": [[758, "قال علماؤنا في هذا الشأن: فيه خمسة أقوال:\rالأول: الحَمْد هو الشكر، لفظان مترادفان.\rالثاني: أن الحمد هو الخبر عن الشيء بما فيه من صفاتٍ حسنة، والشكر هو الخبر عنه بما له من أفعال حسنة.\rواحتجّ من زعم بأنهما شيء واحد بأن العرب تقول: حمِدت فلاناً وشكرته، لا يُفرّقون بينهما، وعضَدوا ذلك بقول العرب: الحمد لله شكراً، فجعلوا الشكر مصدرا للحمد، ولولا أنهما شيء واحد ما صدروا به عنه.\r"], [759, "والصحيح هو القول الثاني، عليه اتّفق المحقّقون، وله تشهد الأدلّة، ومن قال إن العرب لا تُفرّق بينهما فقد قال مُحالا، وظنّ باطلا.\rوأما قولهم إنهم يقولون: حمِدت فلانا وشكرته، فقد صدقوا، وأمّا قولهم إن اعتقادهم فيهما أنهما شيء واحد فدعوى، فمن أين علمتم هذا الاعتقاد؟ ونحن نقول: إنما جمعوا بينهما ليُخبِروا أنهم أثنوا على صفاته وأفعاله معاً.\rوأمّا احتجاجهم بقولهم الحمد لله شُكراً فهو ضعيف، لأنّ العرب قد تُجري المصدر على غير الصدر، وتذكره من غير لفظ الفعل، كما يقال: قتله صبْراً، فالصبر غير القتل، ولكنه حمله عليه لفظا، وصرفه عنه معنىً، وذلك كثير،\rيؤكّده أن الحمد في مُقابلة الذمّ، والشكر في مقابلة الكفر، واختلاف نقيضهما دليل على اختلافهما في أنفسهما، قال تعالى: \"لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ وَلَئِن كَفَرْتُمْ إِنَّ عَذَابِي لَشَدِيدٌ\" (إبراهيم 7).\rومع هذا فلا يُنكَر أن العرب قد تضع أحدهما موضع الآخر لقُربه منه وارتباطه به، وأكثر ما يجعل الحمد موضع الشكر لأنه أعمّ منه، قال تعالى: \"الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنَّا الْحَزَنَ إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ\" (فاطر 34)، وقال: \"الْحَمْدُ لِلَّهِ الَّذِي صَدَقَنَا وَعْدَهُ\" (الزمر 74)، وشرّع رسول الله صلى الله عليه وسلم\r"], [760, "عند الفراغ من الطعام قول الحمد لله، وهذا كلّه خبرٌ عن الأفعال الجميلة والمكارم الجزيلة والصفات الجليلة.\rونهاية التحقيق فيه والنكتة أن الحمد يُستعمل كثيرا في الثناء بالقول، والشكر يُستعمل في الجزاء بالفعل، قال الله سبحانه: \"اعْمَلُوا آلَ دَاوُودَ شُكْرًا\" (سبأ 13)، وقال: \"رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَى وَالِدَيَّ\" (النمل 19).\rالمسألة الثانية: في معنى الحميد\r"]], "pg": [758, 760]}, "561.560": {"x": [[760, "ولعلمائنا فيه خمسة أقوال:\rالأوّل: أن يكون فَعيلاً من حامدٍ، كقولنا: عليمٌ من عالم، وحكيمٌ من حاكم.\rالثاني: أن يكون فَعيلاً بمعنى مفعول، كقولك كَفٌّ خضيبٌ، ورجلٌ قتيلٌ.\rالثالث: أن يكون فَعيلاً من الرضى بالوجهين، وقال بعضهم: الحمد هو الرضى من قولك: حمِدت كذا إذا خَبَرْته فرضيته، وأحمدته إذا وجدتَه محموداً، وفي الحديث: \"أحمد إليكم غسلَ الإحليل\"، أي أرضاه لكم، أقام \"إلى\" مقام اللام، كقوله: \"بِأَنَّ رَبَّكَ أَوْحَى لَهَا\" (الزلزلة 5).\r"], [761, "الرابع: أنه بمعنى الاختبار، كقولك حمِدت كذا وأحمدته.\rالخامس: أن يكون بمعنى السلامة، مأخوذٌ من قولك حُمادى أمرك كذا، أي سلامته، وجمعه حُمادياتٌ، وفي الحديث: \"حُمادياتُ النساء غضّ الطّرْف\".\rوالصحيح ما قدّمناه من أنه بمعنى الحمد الذي هو الثناء، وأنه يجوز أن يكون فَعيلاً من فاعل، وفعيلاً من مفعول، ويكون على الأوّل من قبيل الثناء، وهو الكلام، ويكون على الثاني من باب المعبود والمستعان، على ما يأتي بيانه إن شاء الله.\rالفصل الثالث: في بيان الحمد حقيقة وعقدا\r"]], "pg": [760, 761]}, "561.561": {"x": [[761, "وفيه ثلاث مسائل:\rالمسألة الأولى: في بيان الحقيقة\r"]], "pg": [761, 761]}, "561.562": {"x": [[761, "قد قدّمنا الأقوال والتوجيه والتصريف، وكل ذلك لا يصحّ فيه عن العرب شيء، إلّا أن الحمد هو الثناء لما بيّنّاه من قبل الأدلّة، فإن سُمّي الرضى حمدا فلأنّ من رضي شيئاً أثنى عليه، ومن سخطه ذمّه، وكذلك قال الزِّبرِقان\r"], [762, "بحضرة النبي صلى الله عليه وسلم: \"رضيت فقلت أحسن ما علمت، وسخطت فقلت أقبح ما علمت\"، وإن سُمّيت به العافية فلأن من كانت عاقبته عافية أثنى عليها، وكذلك إذا غضّت المرأة طَرْفها سلمت دنيا وآخرة، فحمِدَت أمرها في ذلك، أي أثنت عليها، فرجع الحمد إلى الثناء على اختلاف أنواعه، وصحّ أن تسمية الرضى والاختيار والسلامة والعافية حمداً لأنه يُمر الحمد ويُنتجه، فسُمّي مَجازاً به، والله أعلم.\rالمسألة الثانية: في تركيب الاعتقاد على المعنى\r"]], "pg": [761, 762]}, "561.563": {"x": [[762, "إذا كان الحميد هو الحامد فذلك في قول علمائنا على وجهين:\rأحدهما: هو حمد الله لنفسه وثناؤه عليها بما هو له أهلٌ؛\rالثاني: حمده لعباده وثناؤه عليهم، قال الجنيد لمّا سمع قوله تعالى: \"إِنَّا وَجَدْنَاهُ صَابِرًا نِّعْمَ الْعَبْدُ إِنَّهُ أَوَّابٌ\" (ص 43)، قال: أعطى وأثنى.\rوإن كان حميدا بمعنى محمود، فإن الخلق يحمدونه بأجمعهم، ناطقهم وصامتُهم، حيُّهم وميّتهم، مؤمنهم وكافرهم، في الدنيا والآخرة، في كلّ مقامٍ وزمان، وعلى كل فعل، وفي كل حال، إلّا أهل النار، فإنهم فاتَهُم الحمد وحيلَ بينهم وبينه، قال سبحانه مُبيّنا لذلك: \"وَإِن مِّن شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ\" (الإسراء 44).\rوأمّا الناطق فتسبيحه تسبيح مقالةٍ، والصامت تسبيحه تسبيحُ عِبرةٍ ودلالةٍ، والمؤمن تسبيحه بالمقال والحال، والكافر تسبيحه بالحال.\r"], [763, "وأمّا إذا كان الحمد بمعنى الرّضى فقد رضي عن عباده المؤمنين ورضُوا عنه.\rوأمّا إن كان بمعنى سلامة العاقبة فقد قال تعالى: \"فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى\" (الليل 5 - 6) الآية، قال: \"وَأَمَّا الَّذِينَ سُعِدُوا\" (هود 108) إلى قوله \"مَجْذُوذ\"، وإن كان بمعنى الاختبار فقد قال تعالى: \"لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا\" (هود 7).\rالمسألة الثالثة:\r"]], "pg": [762, 763]}, "561.564": {"x": [[763, "قال بعض علمائنا: إن الحميد هو المستحقّ للحمد والمدح والثناء والتمجيد، من غير أن يُضاف ذلك إلى حمد حامدٍ، وعلى هذا يكون من صفات الذات والتقديس، وهذا لا يصح من وجهين:\rأحدهما: أن هذا لا يخرج إلا على القول بأنه خالقٌ قبل أن يخلق الخلق، لأنه بصفة من يخلقه، لكونه حيّاً قادرا عالما مُريداً، وقد أبطلنا هذا القول وتكلّمنا عليه وبيّنّا حقيقته في بابه.\rالثاني: أن هذا القائل لمّا رأى تسميته حميداً وظنّ حميداً وظنّ أن الحامد له من الخلق هم المؤمنون خاصّة لجأ إلى حُكمٍ يقتضي له العموم، وهو استيجابه المَدْح، وقد بيّنّا كونه على العموم من الخلق بأجمعهم، وعلى الأحوال كلّها، وفي المقامات بأسرها.\r"], [764, "الفصل الرابع: في التنزيل\r"]], "pg": [763, 764]}, "561.565": {"x": [[764, "إذا ثبت هذا فالباري يختصّ في الحمد بأحكام ثلاثة:\rالأول: أنه لا يحمد بالحقيقة إلّا هو، كان النبي صلى الله عليه وسلم يقول في سجوده: \"لا أحصي ثناءً عليك، أنت كما أثنيت على نفسك\".\rالثاني: أن الحمد لا يُتصوّر حالياً من الذمّ إلا في حقّ الباري تعالى، فإنّ كُفْر الكافر به حمدٌ له.\rالثالث: أنه لا يحمدُ المحمود على غير فعله إلّا هو، فإنه حمِد الخلق وأثنى عليهم وليس لهم فعلٌ، إنّما الفعل له والحمد منه.\rالمنزلة الثانية للعبد:\rاعلموا أنه لا يكون العبد حميداً حتى يُخلّص عقائده عن الشكر، وأخلاقه عن الذمّ، وأقواله عن الباطل، وأعماله عن الفساد، وذلك بالكّلّية ليس إلا لمحمد صلى الله عليه وسلم، ويُدرِك كلّ مؤمن من هذه المرتبة بمقدار ما يُقدّر الله له.\r"], [765, "الاسم السادس والعشرون: الشّكور\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [764, 765]}, "561.566": {"x": [[765, "ورد به القرآن والسنة، قال تعالى: \"إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ\" (فاطر 34)، وقال: \"فَإِنَّ اللَّهَ شَاكِرٌ عَلِيمٌ\" (البقرة 158)، وفي حديث أبي هريرة المفسّر ذكر الشكور وحده، ولم يذكر الشاكر، وأجمعت عليه الأمة.\rالفصل الثاني: في معناه لغة\r"]], "pg": [765, 765]}, "561.567": {"x": [[765, "فيه ثلاثة أقوال:\rالأول: ما قدّمناه أن الثناء هو ذكر المذكور بما فيه من صفات جليلة، والشكر هو ذكره بما فيه من أفعال جزيلة، وهو قولٌ تشهد له اللغات والآثار؛\rالثاني: أنّ الشكر مأخوذ من قولهم: دابّة شَكور، إذا كانت تُظهر من السِّمَن فوق ما تأكل من العَلَف.\rالثالث: أن جزاء الشكر يُسمّى شُكرا لغة.\r"], [766, "الفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [765, 766]}, "561.568": {"x": [[766, "وفيه ثلاث مسائل:\rالمسألة الأولى: في معنى وصفه بأنه شكور\r"]], "pg": [766, 766]}, "561.569": {"x": [[766, "اختلف علماؤنا في ذلك على ثلاثة أقوال مبنيّة على الأقوال الثلاثة من الأقوال اللغوية المتقدمة:\rالأول: أنه شكورٌ بمعنى أنه يُثني على عباده بطاعتهم.\rالثاني: أنه يُجازيهم على شكرهم، فيُسمّى جزاء الشّكر شُكرا على معنى تسمية الشيء بما يتّصل به.\rالثالث: أنه شكور بمعنى أنه يُعطي على قليل العمل كثيرَ الجزاء.\rالمسألة الثانية: في التركيب للاعتقاد على اللغة\r"]], "pg": [766, 766]}, "561.570": {"x": [[766, "إذا قُلنا إن الباري تعالى شكور بمعنى أنه المُثني على من أطاعه وشَكَره فهو الذي مدح وهو الذي أعطى.\rوإذا قلنا إنه شكور بمعنى أنه يُعطي الكثير على القليل، من قولهم: دابّةٌ شَكور، فقد قال تعالى: \"وَقَالُوا الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنَّا الْحَزَنَ إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ\" (فاطر 34)، وشكر تعالى لرجل موسى عليه السلام خُطّى خطاها فقال: \"وَجَاءَ رَجُلٌ مِّنْ أَقْصَى الْمَدِينَةِ يَسْعَى\" (القصص 20).\rوإذا قلنا إنه شكور بمعنى أنه يُجازي، فإنه يُعطي على العمل الجزاء، كما قال تعالى: \"وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ اللَّهَ شَاكِرٌ عَلِيمٌ\" (البقرة 158).\r"], [767, "المسألة الثالثة: في المختار\r"]], "pg": [766, 767]}, "561.571": {"x": [[767, "نقول: إن الذي نَرتضيه، أنّ الشكور هو الذي يمدح على الفعل ويُثني به، وهذا حقٌّ وحقيقةٌ في وصف الإله، وقد علمنا ذلك فدلّ أنه من صفات الذات، وأنه يعود إلى الكلام، فأمّا الوجهان الآخران فغير منكورَين، لكن تسمية الجزاء شُكراً مجازٌ، وتسمية إعطاء الكثير على القليل يحتمل أن يكون حقيقةً فيكون هذا الاسم بمعنىً من صفات الذات، وهو الثّناء، ويرجع إلى الكلام، ويكون بمعنىً راجعاً إلى الثواب، فيكون من صفات الفعل.\rالفصل الرابع: في التنزيل\r"]], "pg": [767, 767]}, "561.572": {"x": [[767, "للباري تعالى في المنزلة العليا ثلاثة أحكامٍ يختصّ بها في هذا الاسم:\rالأول: أنه خالق العبد، خالق الطاعة، خالق القدرة، خالق النعمة، خالق كلّ صفةٍ فيه، ثم أضافها إلى العبد؛ وهي خلقُه ومِلكُه، ومَدَحه بها.\rالثاني: أنّ الشّكر في مقابلة النّعمة، ويستحيل ذلك في حقّ الله تعالى، ولكن مدحَنا بوجهين، وشكَرَنا على حالين:\rأحدهما: إحساننا لأنفسنا من الطاعة، وتخليصها من العذاب باجتناب المعصية.\r"], [768, "الثاني: إحساننا إلى غيرنا وإنعامُنا على سوانا، فهو بفضله العظيم الذي تقصُر الألسنة عن العبارة عنه والجوارح كلّها عن القيام بحقّه، يشكر ذلك الإنعام والإحسان إلى غيره، وقد رُوي عن النبي صلى الله عليه وسلم أنه قال: \"يقول الله تعالى: عبدي، مرضْتُ فلم تعدني، وجُعت فلم تطعمني، وعطشت فلم تسْقِني، فيقول: وكيف تمرض وأنت ربّ العالمين؟ فيقول: مرض عبدي فلانٌ فلم تَعُدْه، ولو عُدته لوجدتني عنده\"، وقال في معناه: \"إِنَّ الَّذِينَ يُؤْذُونَ اللَّهَ وَرَسُولَهُ\" (الأحزاب 57)، و \"إِنْ تَنْصُرُوا اللَّهَ يَنْصُرْكُمْ\" (محمد 8)، ويستحيل ذلك في حقّ الإله، ولكن ذلك راجع إلى أوليائه.\rالمنزلة الثانية للعبد:\rيجب عليه أن يتحقّق أن الشكر فرضٌ عليه، وهو يصل إليه بطرقٍ يكثر تَعدادها، وكنا نتعرّض لها لو كان من بابنا، ولكن جِماعها وجهان:\rأحدهما: -وهو الأعلى- شكر الله.\rوالثاني: -وهو أسفل منه- شكر الناس، لقول النبي صلى الله عليه وسلم: \"لا يشكر الله من لا يشكر الناس\".\r"], [769, "فأمّا المنزلة العليا للربّ فبوجهين:\rأحدهما: باللسان، وهو أن يحمد على كلّ حال، وأن يشكر على السرّاء خاصّة، قال الله تعالى: \"وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ\" (الضحى 11).\rوالثاني: شُكْر الأعمال، وهو أن لا يُصرِّف نعمه إلّا في طاعته، كما قال تعالى: \"اعْمَلُوا آلَ دَاوُودَ شُكْرًا\" (سبأ 13).\rوأمّا المنزلة الثانية للعبد بشُكر الناس فهو بأن يكافئ من أُسْديَت إليه يدٌ بمثلها، كما قال النبي صلى الله عليه وسلم: \"من أُزِلَّت إليه نعمةٌ فليشكرها، فإن لم يستطع فليُشِعها\"، وكما روي عن النبي صلى الله عليه وسلم أنه قال: \"من أُعطي عطاء فوجد فليُجاز به، فإن لم يجد فلْيُئْنِ، فمن أثنى فقد شكره، ومن كتمه فقد كفره\".\r"], [770, "الاسم السابع والعشرون: غَيورٌ\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [767, 770]}, "561.573": {"x": [[770, "الغيور اسمٌ لم يرد به قرآن ولا سنة، ولكن ذكره بعض علمائنا واعتمد على وجهين:\rأحدهما: أنه صفة مَدْحٍ.\rالثاني: أن الخبر الصحيح قد جاء عن النبي صلى الله عليه وسلم بأنه قال: \"لا شخصَ أغيرُ من الله\"، وقال صلى الله عليه وسلم: \"أتعجبون من غَيرة سعد؟ لأنّا أغير منه، والله أغيرُ منّا\"، وقال صلى الله عليه وسلم: \"إن الله يغار، والمؤمن يغار\"، فلمّا وجد منه ذكر أفْعَل أَطْلَق هُو فَعُولاً، كما تقدّم في قولنا صَبُورٌ.\r"], [771, "الفصل الثاني: في شرحه لغة\r"]], "pg": [770, 771]}, "561.574": {"x": [[771, "يقال: غار الرجل على أهله، والمرأة على زوجها، تغارُ غَيْرةً وغَيْراً وغِياراً، إذا كرهت معه غيرها، وفي مثلٍ: \"أَغْيَرُ من الحُمّى\"، لمُلازمتها البدن، كما تلازم الغيور زوجها.\rالفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [771, 771]}, "561.575": {"x": [[771, "فيه أربع مسائل:\rالمسألة الأولى: في ذكر أقوال علمائنا فيه\r"]], "pg": [771, 771]}, "561.576": {"x": [[771, "قال من ذكره منهم –وهو ابن فورك- قولان نصّهما:\rالأوّل: أنه بمعنى حليم.\rالثاني: أن الغيرة في أحدنا كراهة مشاركة من غيره في محبوبه؛ أن يكون له منها ما له منه، والله تعالى قد أحب أن يُخلص له عباده العبادة، وزجر عن الشرك، وكان زجره عن الشرك غيرةً منه على عبادة، وغيرتُنا عارضٌ ونوعٌ من التغيير، كصبرنا وصبره.\rالمسألة الثانية: في حقيقة القول فيها\r"]], "pg": [771, 771]}, "561.577": {"x": [[771, "اعلموا –وفّقكم الله- أن الغيرة ليست لها حقيقةٌ مطَّردةٌ في القديم والمحدَث، والخالق والمخلوق، كالعلم والحياة، فإنه لما كان حقيقة العلم\r"], [772, "معلومةً مطّردةً استمرّت في الخالق والمخلوق، وحقيقة الغيرة فينا تغيُّرُ النَّفس بما يطرأ عليها من المحبوب، فإن كانت في المال سُمّيت بُخلاً، وإن كانت الجاه سُمّيت أَنَفةً، وإن كانت في الحريم سُمّيت غيرةً وأُبقيت على اشتقاقها، وإذا تغيّرت النفس تكلّم اللّسان وتحرّكت الجوارح بمقتضى ذلك التغيّر، فسُمّي القول في ذلك والفعل الواقع فيه غَيْرة مجازاً، لأنهما عن الغيرة يكونان، وهذا هو الذي عنى رسول الله صلى الله عليه وسلم بقوله: \"أتعجبون من غَيْرة سَعدٍ، أنا أغْيَر منه، والله أغير منّا\"، المعنى: أنّ سعداً إذا عاين ما يكره قال وفَعَلَ، وأنا أقول فوق ما يقول، وأفعل فوق ما يفعل، وقول الله فوق كلّ قول، وفعله فوق كلّ فعل، فأمّا قوله فتحريمه للفواحش، وأمّا فعله فهو عقوبته لأهل المعاصي بالحدود والعذاب، ولهذه الحكمة –والله أعلم- وهو كون الغيرة مجازاً وردتْ إضافتها إلى الله سبحانه، ولم تَرِد في الأسماء.\rالمسألة الثالثة: في تتبّع الأقوال السابقة\r"]], "pg": [771, 772]}, "561.578": {"x": [[772, "أما القول بأن معنى غيورٍ حليمٌ فهو ضعيف جدا، بل هو ضدّه لأنّ الحلم يقتضي الإمساك عن القول والفعل، والغَيرة تقتضي القول والفعل، فهو ضدّه.\r"], [773, "وأما القول بأن غَيرتنا كراهة المشاركة في المحبوب، والله قد أحبّ أن يُخلص له عباده العبادة، وقد نصّ في كتبه وكلامه أن المحبة هي الإرادة بعينها، ثم يقول: قد أحب الله أ يُخلص له عباده العبادة، وهم لم يُخلصوا، فكيف يريد منهم ما لم يكن؟\rوأصل عقدنا أنّ الله تعالى لا يريد إلا ما يكون، وقوله: وزجر عن الشكر، فزجره عن الشرك صحيح، من وجه تفسير الغيرة، فاسدٌ من أنّ ذلك لا يعمّ غَيرته كلّها، فإنّ غَيرة الله سبحانه زجره عن جميع معاصيه، فلا معنى لتخصيص بعض النّواهي وهو الشرك.\rالمسألة الرابعة:\r"]], "pg": [772, 773]}, "561.579": {"x": [[773, "قال بعضهم: إذا كان النبي صلى الله عليه وسلم غَيورا كما يجب ويَصحّ ويعتقده كلّ مسلم فكيف جاء إليه رجلٌ فقال: يا رسول الله إن امرأتي لا تَردّ يد لامسٍ، فقال له: طلّقها، فقال: إني أحبها، فقال: استمتع بها\".\r"], [774, "الجواب عنه من أربعة أوجه:\rالأول: أن هذا ضعيف لا قَدَمَ تثبت له في الصحة، رواه النسائي وقال: إنه ليس بثابت، فكيف يُعترض به على ما صحّ نقلا وثبت معنىً.\rالثاني: أن النبي صلى الله عليه وسلم لما ثال له إني أحبها خشي على عقله فأمره بالتمسّك بها، دفعاً لأعظم الضررين بأهونهما، وهذا فاسد من وجهين:\rأحدهما: أن الحكم بمقتضى جنون الحب في الشريعة جنونٌ.\rالثاني: أن بقاءها معه زانية، تُفسد فراشه، وتخلط ماءه، معصيةٌ عظيمة، والمعاصي لا يُتداوى بها.\rالثالث: قال بعضهم: معنى قوله: \"لا تردّ يد لامسٍ\" ليس كنايةً عن الفجور، وإنما هو كنايةٌ عن السخاء والجود، فكلّ من التمس منها معروفاً أجابته، والجوز مكروهٌ في النساء، ولذلك يقال: خير خصال الرّجال شرّ خصال النساء، يعني السّماحة والجوز، فكأنّه قال له: امرأتي ستفقرني؟ قال له: طلّقها، وصُنْ مالك بطلاقها، فلمّا قال له أحبّها قال له: استمتع بها، المعنى: آثِرْها إذن على مالك؛ وهذا بعيدٌ، لأنه لو أراد ذلك لقال: لا تردّ يد مُلتمس، وهذا هو المعروف فيه.\r"], [775, "الرابع: قال له استمتع بها، المعنى: خُذ منها ما يأخذه الرجال من النساء إلا الجماع، وهذا ضعيف، فإن الاستمتاع إذا أُطلق فهو عامٌّ في كلّ مُلامسةٍ، ظاهرٌ في الوَطْء، قال تعالى: \"فَمَا اسْتَمْتَعْتُم بِهِ مِنْهُنَّ فَآتُوهُنَّ أُجُورَهُنَّ فَرِيضَةً\" (النساء 24) والمراد به الوطء، وإذا كان هذا كلّه بعيداً فالمعوَّل فيه على ضعف الحديث.\rالفصل الرابع: في التنزيل:\r"]], "pg": [773, 775]}, "561.580": {"x": [[775, "المنزلة العليا للربّ:\rأنه يختصّ بالتّحليل والتّحريم لا يكون ذلك لسواه.\rالمنزلة السفلى للعبد:\rأن لا ينتهك لغيره حُرمةً كما يكره ذلك لنفسه.\r"], [776, "الاسم الثامن والعشرون: المُصَلّي\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [775, 776]}, "561.581": {"x": [[776, "اعلموا –وفّقكم الله- أن القرآن لم يرد به اسماً ولا السنة، لكن ورد فعلا، قال تعالى: \"إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ\" (الأحزاب 56)، وأجمعت الأمة على معناه وفعله، وقد ذكره بعض علمائنا.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [776, 776]}, "561.582": {"x": [[776, "اعلموا –وفّقكم الله- أن الصلاة في اللغة هي الدعاء، وقد ذكروا لها معاني سوى الدعاء بيّنّاها في كتاب شرح الترمذي وغيره، وهي الاتّباع والتقويم، والأقعد بها معنى الدّعاء، وقد قدّمنا معنى ذلك في اسم الداعي، وقد قيل: صلاة الله رحمته، وإنمال قالوا ذلك لمعنى نذكره بعدُ إن شاء الله تعالى.\r"], [777, "الفصل الثالث: في شرحه حقيقة\r"]], "pg": [776, 777]}, "561.583": {"x": [[777, "فيه مسألتان:\rالمسألة الأولى: في حقيقة الصلاة\r"]], "pg": [777, 777]}, "561.584": {"x": [[777, "الصلاة لفظة لغوية لم يختلف أحبارها أنها الدعاء، وقد قيل: إن المصلّي من الخيل سُمّي به لأنه يتّبع السابق، وقد قيل: أبو بكر السابق وعمر المصلّي، فيكون على هذا الإتباع، ويقال: صَلَيْت العود إذا قوّمته على النار، فتكون الصلاة التقويم، من قوله: \"إِنَّ الصَّلَاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ\" (العنكبوت 45)، فصار لها ثلاثة معانٍ.\rالمسألة الثانية: في الاعتقاد\r"]], "pg": [777, 777]}, "561.585": {"x": [[777, "لمّا رأى علماؤنا قول الله تعالى: \": \"إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ\" (الأحزاب 56)، قالوا: صلاة الله رحمته، لأن الملائكة تصلي عليه بالدعاء والاستغفار، فأمّا الله فإنما يصلّي بالرحمة، وليس كذلك، لأنه إخراج للصلاة عن بابها وو الدعاء، وإنما معناه أن الله وملائكته يصلّون يدعون للنبي، ودعاء الله تعالى للنبي صلى الله عليه وسلم ذكره له على معنى التعظيم، كقوله: يا أيها الرسول، يا أيها النبي، فهذا تفسير صحيح يُبقي اللفظ على معناه في اللغة ويقوم بمعنى الآية.\r"], [778, "فإن قيل: فهل تُسمّى صلاة الله عليه رحمة؟\rقلنا: لا نمنع ذلك، فإن رحمة الله إرادته لتعظيمه وإجلاله، والحثّ على إكرامه من بعض الخلق الذي هداهم لذلك، إذ لا يصحّ أن يريده ممّن لم يفعله، فإنه لا يكون إلا ما يريد.\rالفصل الرابع: في التنزيل\r"]], "pg": [777, 778]}, "561.586": {"x": [[778, "المنزلة العليا للربّ\rقد تقدّمت في اسم الداعي، وها هنا تختصّ بتعظيم النبي صلى الله عليه وسلم.\rالمنزلة الثانية للعبد\rفي ثلاثة أحكام:\rالأوّل: إكثار الصلاة على النبي صلى الله عليه وسلم.\rالثاني: المحافظة على الصلاة.\rالثالث: التعلّق بذيل الدعاء، وقد تقدّم.\r"], [779, "الاسم التاسع والعشرون: الحكيم.\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [778, 779]}, "561.587": {"x": [[779, "ورد به القرآن، قال الله تعالى: \"الْعَزِيزُ الْحَكِيمُ\" (آل عمران 6)، وقد قال تعالى: \"خَيْرُ الْحَاكِمِينَ\" (الأعراف 87)، وقال: \"أَفَغَيْرَ اللَّهِ أَبْتَغِي حَكَمًا\" (الأنعام 114)، فهذه ثلاثة أبنية؛ الحكيم، والحاكم، والحَكَم؛ وورد منه في السنّة في حديث أبي هريرة المفسّر الحكيم، وروى أبو داود عن هاني بن مرثد بن نهيك لمّا وفد على النبي صلى الله علهي وسلم مع قومه يكْنونه بأبي الحكم، فدعاه الرسول صلى الله عليه وسلم فقال: \"إن الله هو الحكيم، وإليه الحُكم\"، وأجمعت الأمة على ذلك مُضمَّناً في كتاب الله سبحانه.\r"], [780, "الفصل الثاني: في شرحه لغة\r"]], "pg": [779, 780]}, "561.588": {"x": [[780, "فيه ثلاث مسائل:\rالمسألة الأولى: في بيان الحكم والحكمة\r"]], "pg": [780, 780]}, "561.589": {"x": [[780, "اعلموا أن الحكيم مأخوذ من الحكمة، وهو من له حكمٌ وحكمةٌ، وقد اختلف الناس في الحكمة على أقوال يكثر تعدادها، جماعها خمسة عشر قولا: الأول منها: أنها العقل.\rالثاني: العلم.\rالثالث: أشرف العلوم.\rالرابع: الفهم.\rالخامس: العلم بكتاب الله.\rالسادس: علم الدين.\rالسابع: علم السنّة.\rالثامن: الإيمان.\rالتاسع: النبوة.\rالعاشر: اجتماع العلم والعمل.\rالحادي عشر: صواب الأمر.\r"], [781, "الثاني عشر: القضاء بالحكم.\rالثالث عشر: ما يمنع الجهل.\rالرابع عشر: الكلام الموجز الدال على المعنى الكثير.\rالخامس عشر: ما وقع بقصد فاعله.\rوأما الحُكم ففيه ثلاثة أقوال:\rالأول: أنه الحكمة، كما يقال: نُعمٌ ونعمة.\rالثاني: أنه القول بالحكمة.\rالثالث: أنه العمل بالحكمة.\rالمسألة الثانية: في المختار\r"]], "pg": [780, 781]}, "561.590": {"x": [[781, "اعلموا أن بعض المحقّقين من علمائنا قال: إن حروف \"ح ك م\" كيف ما تصرّفت إنّما يرجع إلى العلم، والعقل نوع من العلم أو العلم كلّه، والفهم العلم بصفة، والدين علمٌ كلّه، والسنّة نوع من العلم، والعلم بالله والنبوّة علمٌ شريفٌ، واجتماع العلم والعمل علم، ولذلك قال صلى الله عليه وسلم: \"لا يزني الزاني حين يزني وهو مؤمن\".\r"], [782, "قد يُسمّى الفعل المنتظم حكمة، وكذلك القول الصائب حكمة، لأنه عن الحكمة التي هي العلم يصدر، كما يُسمّى المقدور قدرة، وقول المتكلمين: الحكمة ما وقع بقصد فاعله؛ إشارة إلى أن الفعل الوقع على وفق الإرادة يُسمّى حكمةً، لأنه لا يقع كذلك إلا موافقاً للعلم، والإرادة تابعةٌ له، ولكنّهم خصّوا الإرادة في الاقتران به لإصل بديع من أصول التّوحيد وهو أنّه لا يكون إلا ما يريد الله سبحانه.\rقال الإمام الحافظ رضي الله عنه: هذا قول مطَّردٌ يظهر في الباري، ويستمرّ في الظاهر.\rولكن من تتّبع ألفاظ القرآن وجد الأمر بخلاف هذا، قال الله تعالى: \"فَإِن جَاءُوكَ فَاحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْئًا وَإِنْ حَكَمْتَ فَاحْكُم بَيْنَهُم بِالْقِسْطِ\" (المائدة 42)، وكذلك قال الله تعالى: \"ذَلِكُمْ حُكْمُ اللَّهِ يَحْكُمُ بَيْنَكُمْ\" (الممتحنة 10)، وقال تعالى: \"وَإِنْ خِفْتُمْ شِقَاق بَيْنهمَا فَابْعَثُوا حَكَمًا مِنْ\r"], [783, "أَهْله وَحَكَمًا مِنْ أَهْلهَا\" (النساء 35)، ونزلت قُريظة على حكم سعد بن معاذ، فحكم على أن تُقتل مُقاتلتهم وتُسبى ذراريهم، فقال: لقد حكمْت فيهم بحكم الملك، وذلك كثير عدده، صحيح مدده، مبنيٌّ على أنّ الحكم هو الخبر عن صواب الأمر وسداد الشأن، ولكن الخبر عن ذلك لا يكون إلّا بعد العلم، فيصحّ أن يُسمّى العلم به، وكذلك يُسمّى صواب الأمر نفسه حُكما وحكمة، لأنه أُخبر به عنه، كما قيل في المثل: الصمت حكمٌ، وقليل فاعله، فتارةً يُطلَق الحَكم والحكمة على العلم الذي عنه يكون الخبر، وتارةً يُسمّى الصواب والسداد به، وكلا الطرفين مجازٌ، والحقيقة هو الخبر عن الصّواب، ويرجع ذلك إلى الكلام، ولذلك كان لقماء يُسمّى حكيماً، لأنّ كلماته كانت لا تصدر إلّا خبراً عن صواب.\r"], [784, "المسألة الثالثة: في بيان أبنية الأسماء فيه\r"]], "pg": [781, 784]}, "561.591": {"x": [[784, "أما الحكيم فهو فعيلٌ من الحكمة، ويحتمل أن يكون مُفعِلا ومفعولاً منها، وأما الحاكم فهو فاعل منها، وأما الحَكَم فهو فَعَلٌ منه، كما يقال: حدث الشيء يحدث فهو حادثٌ وحديثٌ وحدَثٌ، وكم يأتي بناء فَعَلٍ في الأسماء والصفات.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [784, 784]}, "561.592": {"x": [[784, "وفيه ثلاث مسائل:\rالمسألة الأولى: في تركيب الاعتقاد على الألفاظ\r"]], "pg": [784, 784]}, "561.593": {"x": [[784, "إذا عرفتم حقيقة الحكمة والحُكم والحاكم والحكيم والحَكم:\rفإذا قلنا إنه العالم فقد تقدّم بيانه.\rوإن قلنا العالم بأشرف العلوم فهو العالم بذاته ولا شيء مثلُه.\rوإن قلنا: إنه الحكيم بمعنى المُحكِم، لقد أحكم الأشياء وأتقن خلقها، وأحسن كلّ شيء خَلَقه، وليس يرجع ذلك إلى وثاقة الخِلقة، وإحكام البِنية والمنظر الرّائق، فإنّ البعوض والنّمل مُحكَم خلقها كخلق السماوات، وإنّما\r"]], "pg": [784, 784]}, "561.594": {"x": [[785, "يرجع ذلك إلى المعنى الذي خلقه على ما علمه وقدّره وأخبر به وقال له: كن فيكون، وهو الذي عبّر عنه بقوله: \"وَخَلَقَ كُلَّ شَيْءٍ فَقَدَّرَهُ تَقْدِيرًا\" (الفرقان: 2).\rوإذا قلنا إنه الحاكم يمعنى المانع لخلقه عن التظالم، فذلك يرجع إلى خبره عن الحكم وهو الحقيقة التي بيّنّاها، وهو معنى وصفه بأنه حاكمٌ وحكيمٌ وحَكَمٌ بالحقيقة، فإنه يرى الخلق يتظالمون ولا يصدّهم، ولو شاء لكان على ذلك قادرا، ولكنّه يرجع ذلك إلى خبره.\rوأمّا إذا قلنا إنّ الحكيم بمعنى المُحكِم فذلك محالٌ في حقّ الباري، ولكنّه صحيح في حق المخلوقات لتصوّر ذلك فيها.\rالمسألة الثانية: في بيانه كونه من صفات الأفعال أو من صفات الذات؟\rلا إشكال أنه إذا كان بمعنى العالم أو بمعنى المُخبِر –وهو الحقيقة- فهو من صفات الذات، وأمّا إذا كان بمعنى المُحكِم فهو مُشكلٌ جدّا، وقد اختلف فيه علماؤنا:\rفمنهم من قال: المحكم هو فاعل الفعل المحكَم، وهذا قول مُجمَل.\r"], [786, "ومنهم من قال: إن الحكيم هو الذي يفعل ما يريد، وهو قول الأستاذ أبي إسحق، وهذه دعوى، وإنما ظنّ أن الحكم فعل تقترن به الإرادة حسب ما تقترن به الأفعال، وليس كذلك، بل هو الخبر عن الصواب كما بيّنّاه.\rومنهم من قال: إن الحكيم هو الذي تقع أفعاله على مقتضى علمه وإرادته، وليس الإحكام فعلا ولا صفة فعل، وإنما هو عبارة عن وقوع المخلوق على حسب العلم والإرادة، فيدلّ وقوع الفعل على مقتضى العلم والإرادة على أنه حكيم، كما يدلّ خروجه من العدم إلى الوجود على أنه قادر، فلم يزل الباري حكيماً ولا يزال، كما لم يزل مُخبرا ومتكلّما ولا يزال، ولم يزل عالماً ولا يزال.\rالمسألة الثالثة: في كونه خير الحاكمين وأحكم الحاكمين\r"]], "pg": [785, 786]}, "561.595": {"x": [[786, "أما كونه خير الحاكمين فلأنه لا يقبل رشوة، ولا يقابِل بسطوة، ولا تُخاف منه هفوة.\rوأما كونه أحكم الحاكمين فلأنه لا يتطرّق إلى علمه سهوٌ، ولا يمكن في قضائه وحكمه نقضٌ.\r"], [787, "الفصل الرابع: في التنزيل\r"]], "pg": [786, 787]}, "561.596": {"x": [[787, "إذا علم العبد معنى كون ربّه حكيما، فالمنزلة العليا لله في ذلك تقتضي له أحكاماً:\rفإن كان الحكيم هو العالم فقد تقدّم بيان التنزيل فيه؛\rوإن كان الحكيم المُحكِم، فمن أحكم كل شيء إلا هو، فكل إحسانٍ منه مكتوب، وعليه محسوب؛\rوإذا كان بمعنى المُخبِر، فليس الإخبار عن الحقائق إلا له، لا مُعقّب لحكمه.\rالمنزلة الثانية للعبد:\rوهو بأن يكون قوله صواباً وفعله صدقاً.\r"], [788, "الاسم الموفّي ثلاثين: التوّاب\rفيه أربعة فصول:\rالفصل الأوّل: في مورده\r"]], "pg": [787, 788]}, "561.597": {"x": [[788, "ورد به نصّ القرآن، قال تعالى: \"إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ\" (البقرة 128)، وقال تعالى: \"وَأَنَّ اللَّهَ تَوَّابٌ حَكِيمٌ\" (النور 10)، وقال تعالى: \"غَافِرِ الذَّنبِ وَقَابِلِ التَّوْبِ\" (غافر 3)، وورد في السنّة في حديث أبي هريرة المفسّر، وأجمعت عليه الأمة.\rالفصل الثاني: في مورده لغة\r"]], "pg": [788, 788]}, "561.598": {"x": [[788, "أصل التوبة في اللغة الرجوع، يقال: تاب وآب وأناب بمعنى رجع.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [788, 788]}, "561.599": {"x": [[788, "إذا علمتم حقيقة التوبة، وهو الرجوع، فلعلمائنا في وصف الباري تعالى بذلك ثلاثة أقوال:\rالأول: لا يجوز أن يوصف الله بشيء من ذلك إلا بما وصف به نفسه، وهو أنه توّاب لأجل ورود النصّ بذلك، ويوصف العبد بأنه توّاب، ومعنى توبة\r"], [789, "الله على العبد عودتُهُ عليه بالتوفيق والعصمة، وتوبة العبد رجوعه عن الأحوال المذمومة إلى الأحوال المحمودة.\rالثاني: قال آخرون: بل يوصف الله بذلك حقيقة، وتوبة الله على العبد ردّه له من حالة المعصية إلى حالة الطاعة، يقال: تاب الله على العبد إذا رجعه عن السيئات إلى الحسنات.\rالثالث: قال آخرون: توبة الله على العبد قَبوله توبته.\rالمسألة الثانية: في المختار\r"]], "pg": [788, 789]}, "561.600": {"x": [[789, "أما من قال إن توبة الله على العبد رجوعه به من حالته المذمومة إلى حالته المحمودة، فأراد بذلك خلقَ التوبة له؛ وهي الاعتقاد الجميل والفعل الحسن، وكذلك قول من قال عودُه عليه بالتوفيق والعصمة.\rوأما من قال إنه قَبوله لتوبته فذلك محتمل لوجهين:\rأحدهما: يرجع إلى قوله قبِلتُ.\rوالثاني: يرجع إلى مَنّه بالثواب عليه، وكتبه له في ديوان المُنيبين.\rوالصحيح أن توبة الله على العبد ترجع إلى وجهين:\rأحدهما: الحكم.\rوالثاني: الفِعل.\r"], [790, "فإن قلنا: إنه بمعنى الحكم فالمراد أنه تعالى قد حكم في الابتداء بتوبته، وحكم الله كلامه، وذلك خبره عنه بما يكون منه.\rوإن قلنا إنه بمعنى الفعل فهو خلْقُه فيه الإنابة والعصمة، وذلك يعود إلى صفات الفعل، وهو جارٍ على المعنيين جميعا، صحيح فيهما.\rالفصل الرابع: في التنزيل\r"]], "pg": [789, 790]}, "561.601": {"x": [[790, "المنزلة العليا للربّ:\rيختصّ فيها بحكمين:\rأحدهما: خلقه للتوبة لا يخلقها سواه.\rالثاني: هبة العصمة.\rالمنزلة الثانية للعبد:\rأن يقبل عُذر من اعتذر إليه، ولو عاود الجناية عليه.\r"], [791, "الاسم الحادي والثلاثون: الفتّاح\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [790, 791]}, "561.602": {"x": [[791, "ورد به نصّ القرآن، قال سبحانه: \"هُوَ الْفَتَّاحُ الْعَلِيمُ\" (سبأ 26)، وقال: \"وَأَنتَ خَيْرُ الْفَاتِحِينَ\" (الأعرفا 89)، ووردت به السنة في حديث أبي هريرة المفسّر، وقال تعالى: \"إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا\" (الفتح 1)، وقال تعالى: \"مَّا يَفْتَحِ اللَّهُ لِلنَّاسِ مِن رَّحْمَةٍ\" (فاطر 2)، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [791, 791]}, "561.603": {"x": [[791, "الفتح في اللغة عبارة عن حلّ المغاليق كيفما تصرّفت، وقد يكون الفتّاح الحاكم؛ لأنه يفتح غَلَق الفصل بين المتخاصمين بقضائه، ومنه قوله: \"رَبَّنَا افْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِالْحَقِّ\" (الأعراف 89)، معناه احكُم.\rوسمّت العرب القاضي فتّاحاً، قال امرؤ القيس:\rأبَعْدَ الفاتح الوهّاب عمرٍو *** حليف الجود والحسب اللُّبابِ\r"], [792, "ويروى عن ابن عباس أنه قال: \"ما كنت أعلم ما معنى الفتّاح حتى سمعت أعرابيَّين يتنازعان مطلباً، فقال أحدهما لصاحبه: بيني وبينك الفتّاح\"\rوقد يكون بمعنى النّصر، قال الله سبحانه: \"إِنْ تَسْتَفْتِحُوا فَقَدْ جَاءَكُمُ الْفَتْحُ\" (الأنفال 19)، معناه تستنصروا.\rالفصل الثالث: في شرحه عقيدة.\r"]], "pg": [791, 792]}, "561.604": {"x": [[792, "قد بينّا لغة، أمّا تحقيقه، فيرجع إلى ما صدّرنا به القول من أنه حلّ كل غَلَقٍ؛ فإن كان حلّ التنازع بالحكم، فإنه قول وبيان للناس وجه الأحكام، وقوله كلامه، وإن كان بمعنى النصرة رجع إلى فعله، وذلك بيّنٌ في معنى النصير، وكذلك أيضا يرجع إلى الفعل فيما يفتح على العباد من رزق،\r"], [793, "ويفتح من بصائر وهدىً وغير ذلك من كلّ معنىً، وثبت أنه من صفات الذات؛ وهو الكلام بمعنىً، ومن صفات الفعل بالمعاني المذكورة.\rالفصل الرابع: في التنزيل\r"]], "pg": [792, 793]}, "561.605": {"x": [[793, "إذا علمْت معنى الفتح لغة، وتحقّقته عقيدة، فله متعلَّقات كثيرة؛\rالمنزلة العليا للباري تعالى:\rله فيها ثلاثة أحكام مخصوصة، عددها عشرة\rالأول: أنه يفتح غلق العدم بالوجود، وليس ذلك إلا له، وزعمت القدرية أنه يشاركه في ذلك العبد.\rالثاني: أنه يبيّن بكلامه كلّ مُشكل.\rالثالث: أنه يفتح مغاليق الرزق بالعطاء في كل نوع؛ من غيث على قحط، وغنىً على فقر، وفرج من همّ، وهدى من ضلال، وطاعة من معصية، وتوبة من إصرار، ونصر من خذلان، وعلمٍ عن جهل، فعنده مفاتح الغيب.\rالمنزلة الثانية للعبد:\rله فيها حالتان:\rالأولى: أن يلزن باب ربّه في جميع أحواله.\rالثانية: أن يفتح على غيره كلّ منغلق بفعله وكلامه وماله.\r"], [794, "الاسم الثاني والثلاثون: القاضي\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [793, 794]}, "561.606": {"x": [[794, "ورد به القرآن فعلا، وكذلك السنة، ولم يرد فيها اسم منه.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [794, 794]}, "561.607": {"x": [[794, "فيه مسألتان:\rالمسألة الأولى: في سرد أٌقوال العلماء\r"]], "pg": [794, 794]}, "561.608": {"x": [[794, "قال علماؤنا –رحمة الله عليهم-: له خمسة معانٍ:\rالأول: الحكم.\rالثاني: الخلق، لقوله: \"فَقَضَاهُنَّ سَبْعَ سَمَاوَاتٍ\" (فصّلت 12).\rالثالث: قضى بمعنى أعلم: كقوله: \"وَقَضَيْنَا إِلَى بَنِي إِسْرَائِيلَ فِي الْكِتَابِ\" (الإسراء 4).\r"], [795, "الرابع: القضاء بمعنى الأمر، كقوله تعالى: \"وَقَضَى رَبُّكَ أَلاَّ تَعْبُدُوا إِلاَّ إِيَّاهُ\" (الإسراء 23).\rالخامس: القضاء بمعنى الأداء، كقوله: \"فَإِذَا قَضَيْتُمُ الصَّلاةَ\" (النساء 103).\rالمسألة الثانية: في المختار\r"]], "pg": [794, 795]}, "561.609": {"x": [[795, "إذا رأيتم ما سبق من الأقوال، فالصحيح أن قضى بمعنى فرغ، قال أبو ذُؤيب:\rوعليهما مسرودتان قضاهما *** داوُد أو صَنَعُ السوابغ تُبّعُ\rوعليه يجري كل ما تقدّم منه؛ وقضاء القاضي فراغه من الحكم وإنفاذه له، وعليه يُحمَل قوله: \"إِنَّ رَبَّكَ يَقْضِي بَيْنَهُم بِحُكْمِهِ\" (النمل 78)، وقوله: \"\"وَقَضَيْنَا إِلَى بَنِي إِسْرَائِيلَ فِي الْكِتَابِ\" (الإسراء 4)، أعلمناهم إعلاما مفروغا من بيانه، وقوله: \"وَقَضَى رَبُّكَ أَلاَّ تَعْبُدُوا إِلاَّ إِيَّاهُ\" (الإسراء 23) يعني أنفذ حكمه وأمضى أمره، وقوله: \"فقضاهنّ\" فرغ منهنّ، وقوله: \"فَإِذَا قُضِيَتِ الصَّلَاةُ\" أي أُكملت، وقال تعالى: \" وَلَا تَعْجَلْ بِالْقُرْآنِ مِن قَبْلِ أَن يُقْضَى إِلَيْكَ وَحْيُهُ\" (طه 114) أي يَكمُل بيانه ويُفرَغ منه.\rوتقول العرب: قضى فلانٌ، أي مات وفرغ عمره، وعليه يدل قوله صلى الله عليه وسلم: \"أول ما خلق الله القلم، فقال له: اكتب، فكتب ما يكون إلى يوم\r"], [796, "القيامة\"، وقوله صلى الله عليه وسلم: \"فرغ ربكم، ما من نفس منفوسة إلا وقد كُتب مكانها من النار\"، وذلك إشارة إلى ما تكلّم سبحانه به، وكتب مجراه وحقيقته.\rالفصل الثالث: في شرحه عقيدة.\r"]], "pg": [795, 796]}, "561.610": {"x": [[796, "وفيه ثلاث مسائل:\rالمسألة الأولى: في حقيقته\r"]], "pg": [796, 796]}, "561.611": {"x": [[796, "تقدّمت في المسألة الثانية قبله، فالباري هو القاضي الذي قد أمضى حكمه وأنفذ قضاءه مقولاً مكتوبا، وأسْجل عليه في كتابه، وجعله فوق عرشه، فجرت المخلوقات على نصّه.\r"], [797, "المسألة الثاني:\r"]], "pg": [796, 797]}, "561.612": {"x": [[797, "إن قيل: هل تقولون إن قضاء الله هو مقضيّه كما قلتم: إن الخلق هو المخلوق؟\rأجاب عن ذلك ابن فورك بأن قال: اختلف أصحابنا في ذلك، فأما من قال: إن الخلق هو المخلوق فالقضاء عنده هو المقضيّ، ومن غاير بين ذَيْنك غير بين ذَيْن.\rوالجواب الصحيح: أنّا لا نقول: إن القضاء هو المقضي، لأن القضاء يتصرّف فيما يُخلق وما لا يُخلق، فإذا سأل عنه مطلقا فقال القضاء هو المقضيّ أو غيره لم يصحّ الجواب عنه، لأنّ كل لفظ مشترك بين معان متغايرة لا يصحَّ الجواب عنه إلا بالإفراد، حسب ما بيّنّاه في كتب الأصول، ولو قال: القضاء في المخلوق هو المقضي أو غيره لصحّ أن يُجاوب عنه بجواب ابن فورك.\r"], [798, "المسألة الثالثة:\r"]], "pg": [797, 798]}, "561.613": {"x": [[798, "إن قال قائل: أترضون بقضاء الله للكفر والمعصية؟\rقلنا: عنه جوابان:\rأحدهما: أنّا نقول: نعم، ومن أصول التّوحيد عندنا الرضى بالقضاء.\rالثاني: أنّ من أصحابنا من قال: أرضى بقضاء الله، ولا أقول أرضى بقضاء الله الكفر، وهو إقرار بعيدٌ لا يُحتاج إليه.\rالمسألة الرابعة:\r"]], "pg": [798, 798]}, "561.614": {"x": [[798, "إن قال قائل: أتقولون إن قضاء الله حقّ؟\rقلنا: نعم.\rفإن قال: أليس الكفر قضاءً؟ قلنا: نعم، قال: فيجيء من ذلك رضاكم بالكفر؟\rأجاب عن ذلك بعض علمائنا بأن قال: ذلك كما نقول: السحر حقّ، والسحر في الحقيقة باطل منهيّ عنه.\rوهذا جواب فاسد، فإنّ معنى قولنا إن السحر حقّ أنه حقيقة، لأن لفظ الحقّ ينطلق على الحقيقة التي هي وجود الشيء، وينطلق على الحقّ الذي هو\r"], [799, "ضدّ الباطل، فيكون معنى قولنا: السحر حقّ أنه حقيقة، لا على أنه حقٌّ الذي هو ضدّ الباطل، وإذا ثبت أنه حقيقة فالحقيقة قد تكون حقّا وقد تكون باطلا.\rوالجواب الصحيح من وجهين:\rأحدهما: أنّا نقول: قد قدّمنا بيان أن القضاء هو الفراغ والتّمام، وكلّ أمر فرغ الله منه فهو حقّ، لأنه سبحانه لا يقضي إلا بالحق، كما قال: \"يَقُصُّ الْحَقَّ وَهُوَ خَيْرُ الْفَاصِلِينَ\" (الأنعام 58)، وقضاؤه بكفر الكافر حقّ، وكفر الكافر باطل.\rالثاني: أنّا نقول: إذا قلنا في الجملة إن قضاء الله حقّ جاز، وإن كان كفر الكافر من قضائه، ولا نقول: إن الكفر حقّ كما نقول: إن ما دون الله ضعيف، والإسلام دون الله وليس بضعيف، لأنّا إذا قلنا الإسلام ضعيف كان خطأً، وإذا قلنا: في الجملة ما دون الله ضعيفٌ، اقتضى ذلك وصفه بالقدرة والسلطان، ومثل هذا في الكلام كثير.\rالفصل الرابع: في التنزيل\r"]], "pg": [798, 799]}, "561.615": {"x": [[799, "إذا ثبت هذا: فللّه سبحانه حكمٌ يختصّ به في هذا، وهو أنه لا يُرَدّ قضاؤه؛\rوللعبد حكم يختصّ به، وهو التزامه الرّضى بالقضاء.\r"], [800, "الاسم الثالث والثلاثون: خير الفاصلين\rفيه أربعة فصول:\rالفصل الأول: في مورده.\r"]], "pg": [799, 800]}, "561.616": {"x": [[800, "ورد به القرآن، قال الله سبحانه: \"يَقُصُّ الْحَقَّ وَهُوَ خَيْرُ الْفَاصِلِينَ\" (الأنعام 58)، ولم ترد به السنّة، لكن جاء في صفة كلام النبي صلى الله عليه وسلم: \"فصْلٌ لا نزْرٌ ولا هَذَرٌ\"، وأجمعت عليه الأمة لوروده في كتاب الله سبحانه، وورد به السنة فعلا، قال الله تعالى: \"رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ\" (السجدة 25)، وسمّى الله كلامه فَصْلاً فقال: \"إِنَّهُ لَقَوْلٌ فَصْلٌ\" (الطارق:\r"], [801, "13)، وقال: \"وَلَوْلا كَلِمَةُ الْفَصْلِ لَقُضِيَ بَيْنَهُمْ\" (الشورى 21)، وقال في باب منه: \"آيَاتٍ مُّفَصَّلَاتٍ\" (الأعراف 132)، فيجيء منه الفاصل.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [800, 801]}, "561.617": {"x": [[801, "الفصل التفريق والتمييز بين المعنيين، تقول: فصَلت بين الشيئين إذا فرّقت بينهما فانفصلا، ومنه قوله تعالى: \" إِنَّهُ لَقَوْلٌ فَصْلٌ\" (الطارق:13)، أي يُفرّق بين الحق والباطل، وقوله: \" وَفَصْلَ الْخِطَابِ\" (ص 20) هي قوله: البيّنة على المدَّعي واليمين على من أنكر، وهو التمييز بين الخصمين وأحوالهما، ومنه: \"\"آيَاتٍ مُّفَصَّلَاتٍ\" (الأعراف 132) أي مُبيَّنات.\rومنه قوله تعالى: \" وَلَوْلا كَلِمَةُ الْفَصْلِ لَقُضِيَ بَيْنَهُمْ\" (الشورى 21)، يعني ما تقدّم من إخبار الله أنه يفصل بينهم يوم القيامة، وهذا كلّه التفريق والتمييز.\rالفصل الثالث: في بيانه حقيقة وعقدا\r"]], "pg": [801, 801]}, "561.618": {"x": [[801, "إذا علمتم معنى الفصل، فالباري تعالى يفصل بين المعاني بقوله وبيانه، وبعلمه وكتابه، وبفعله وخلقه، وذلك قوله سبحانه: \" إِنِ الْحُكْمُ إِلا لِلَّهِ يَقُصُّ الْحَقَّ وَهُوَ خَيْرُ الْفَاصِلِينَ\" (الأنعام 58)، فبيّن أنه الحاكم القاضي الفاصل، فحكمه خبره عن الحقائق، وقضاؤه بيانه التامّ، وفصله تمييزه بالبيان بين الأشياء، فهذا فصله بكلامه.\r"], [802, "وأما فصله بعلمه وكتابه فإنه: \"لما خلق القلم قال له: اكتب، فكتب ما يكون إلى يوم القيامة\".\rوأمّا فصله بخلقه فذلك مشاهَد من تمييزه بين المختلفات، وتخصيصه لأوصاف الكائنات، وتفريقه بين الأعيان والذوات، وتفصيل الآيات والمعجزات.\rالفصل الرابع: في التنزيل\r"]], "pg": [801, 802]}, "561.619": {"x": [[802, "المنزلة العليا للرب:\rيختصّ فيها بأن الفصل الذي لا يُردّ له.\rويختصّ العبد بحُكمين:\rأحدهما: أن يكون كلامه فَصْلا؛ لا نَزْرا ولا هَذَراً، المعنى أن يكون كلامه مُبيَّناً، لا قليلا ناقصا ولا كثيرا مُشغِّباً، وذلك للنبي صلى الله عليه وسلم وحده، ويلحق الخلق منه بقدر درجاتهم عند الله وما يسّر لهم.\r"], [803, "الاسم الرابع والثلاثون: الكفيل\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [802, 803]}, "561.620": {"x": [[803, "ورد به القرآن، قال الله تعالى: \" جَعَلْتُمُ اللَّهَ عَلَيْكُمْ كَفِيلًا\" (النحل 91)، ووردت السنّة بفعله، قال النبي عليه السلام: \"تكفل الله لمن جاهد في سبيله\" الحديث، ووردت به أيضا اسماً في حديث الخشبة، حين قالوا: ايتنا بكفيل، قال: رضيت بالله كفيلا، وأجمعت عليه الأمة.\r"], [804, "الفصل الثاني: في شرحه لغة\r"]], "pg": [803, 804]}, "561.621": {"x": [[804, "اعلموا أن الكفيل في اللغة له معنيان متباينان، أحدهما الضّمان، يقال: كفل يكفُل، وتكفّل يتكفّل، إذا ضمن والتزم.\rالفصل الثالث: في حقيقته\r"]], "pg": [804, 804]}, "561.622": {"x": [[804, "وفيه مسألتان:\rالمسألة الأولى: في حقيقة الكفالة\r"]], "pg": [804, 804]}, "561.623": {"x": [[804, "وهي الالتزام، وذلك يكون بالقول، وذلك من صفات الكلام، وقد يقال للعائل كفيلا؛ لأنه إذا عال المرء وأنفق عليه كأنه فَعَل فِعْل الملتزم لذلك.\rالمسألة الثانية:\r"]], "pg": [804, 804]}, "561.624": {"x": [[804, "الباري تعالى كفيلٌ بالمعنيين المتقدمين جميعا، في باب الدنيا والدين: أما في الدين فبقوله: \" أَنِّي لَا أُضِيعُ عَمَلَ عَامِلٍ مِّنكُم\" (آل عمران: 195) وما أشبهه.\r"], [805, "وأما في الدنيا فبقوله: \" وَمَا مِن دَابَّةٍ فِي الْأَرْضِ إِلَّا عَلَى اللَّهِ رِزْقُهَا\" (هود 6)، وأمّا بالفعل فلأن الخلق عياله تعالى، يستدرّون خزائنه ويستعيذون نقمه.\rالفصل الرابع: في التنزيل\r"]], "pg": [804, 805]}, "561.625": {"x": [[805, "إذا علمتم أن الكفيل هو الملتزم، وتحقّقتم أن الله قد التزم ثواب الأعمال وضَمِن جريان الرزق، فاعلموا أنه قال: \" وَأَنْ لَيْسَ لِلْإِنْسَانِ إِلَّا مَا سَعَى\" (النجم 39)، فنفى التوكّل عن العمل، ودعا العباد إليه، وقال: \" وَمَا مِن دَابَّةٍ فِي الْأَرْضِ إِلَّا عَلَى اللَّهِ رِزْقُهَا\" (هود 6)، فأظهر الضمان، فعكس الشيطان هذا في حقّ الضعفاء، وقال للعصاة: توكّلوا على المغفرة، واجتهدوا في طلب الدنيا؛ وعلى العبد أن يقوم بحقّ الوعدين، ويجتهد في العمل، ويتوكّل في الرزق، وهي المنزلة الثانية له.\r"], [806, "الاسم الخامس والثلاثون: المُبرِم\rفيه أربعة فصول: في مورده\rورد به القرآن، قال تعالى: \" أَمْ أَبْرَمُوا أَمْرًا فَإِنَّا مُبْرِمُونَ\" (الزخرف 79).\rالفصل الثاني: في شرحه لغة\r"]], "pg": [805, 806]}, "561.626": {"x": [[806, "المبرِم في اللغة هو الذي عقد فأحكم، تقول: أبرمت الأمر إذا أحكمته، فهو مُبرَمٌ وبريمٌ، كقولك: عسلٌ مُعقَدٌ وعقيدٌ.\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [806, 806]}, "561.627": {"x": [[806, "وفيه مسألتان:\rالمسألة الأولى: في حقيقة الإبرام\r"]], "pg": [806, 806]}, "561.628": {"x": [[806, "وأصله عقد الحبل وإحكامه، والبريم الحبل المضفور، ثمّ استعير في المعاني، فيقال، أبرموا أمرهم إذا أحكموا رأيهم، ولذلك قيل للجيش الذين أبرموا أمرهم بريمٌ، قالت ليلى:\r"], [807, "ليَقُود من أهل الحجاز بَريما\rيعني في أحد التفسيرين: قوماً أحكموا رأيهم.\rالمسألة الثانية: في تحقيق وصفه به\r"]], "pg": [806, 807]}, "561.629": {"x": [[807, "اعلموا أن معنى وصفه بأنه مبرمٌ على معنى قولنا في الحبل بريمٌ، أنه أحكم الأفعال وربط الروابط، ونظم الموجودات، بحيث لا يتطرّق إليها زللٌ، ورتّب الأسباب والمسبَّبات بحيث لا ينتسب إليها خللٌ.\rوإذا قلنا إنه مبرِمٌ بمعنى إحكام الرأي، فلقد نظَم التدبير وأحسن التقدير، فحقّت كلمته، واتّسقت مقاديره وأقْضيته.\rالفصل الرابع: في التنزيل:\r"]], "pg": [807, 807]}, "561.630": {"x": [[807, "المنزلة العليا للربّ في هذا الاسم\rأنه لا يُردّ حكمه ولا يَفسُد نَظمه.\rوالمنزلة الثانية للعبد\rأن لا يلتفت إلى بشر في رجاء ولا خوف، لأن القضاء مُحكَمٌ والأمر مُبرَمٌ.\r"], [808, "الاسم السادس والثلاثون: مُنذرٌ، والاسم السابع والثلاثون: مُرسلٌ\rفيهما أربعة فصول:\rالفصل الأول: في موردهما:\r"]], "pg": [807, 808]}, "561.631": {"x": [[808, "ورد بهما القرآن، قال الله تعالى: \" إِنَّا كُنَّا مُرْسِلِينَ\" (الدخان 5) \" كُنَّا مُنذِرِينَ\" (الدّخان 3).\rالفصل الثاني: في شرحهما لغة\r"]], "pg": [808, 808]}, "561.632": {"x": [[808, "أما الإنذار فهو الإخبار بالعذاب عند المخالفة، والبشرى الإخبار عن الثواب عند الموافقة، وقد تُستعمل البشرى مكان الإنذار، قال الله تعالى: \" فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ\" (آل عمران 21).\rوأما الإرسالة فهو متابعة الخبر على المعنى، ومنه: الرَّسل، وهو اللبن الكثير عند متابعة الحَلَب، ومنه: جاؤوا أرسالاً؛ أي مُتتابعين، فالرسول نذير، ولا يكون النذير رسولاً حتى يُتابع.\r"]], "pg": [808, 808]}, "561.633": {"x": [[808, "الفصل الثالث: في الحقيقة\rالمسألة الأولى:\r"]], "pg": [808, 808]}, "561.634": {"x": [[808, "حقيقة الرسالة إبلاغ الكلام، ولا يكون إلا في قول الغير عن\r"], [809, "الغير، فلا بدّ في هذا الاسم من واسطة بخلاف الإنذار، فإنه يكون إخبار المتكلّم عن نفسه، وقد يكون عن غيره.\rوأبلغ دليل على كون الباري متكلّماً، ما ثبت من النظر إلى الخلق، وجواز أمرهم ونهيهم وإنذارهم وتبشيرهم، وعليه عوّل المحقّقون من المتأخّرين، فإنّهم قالوا: إنّ كلّ صفة جائزة في الخلق تستند إلى صفة واجبة للخالق.\rوصوابه عندي على حاله أن يقال فيه: كلّ صفة مخلوقة واجبة أو جائزة تستند إلى صفة واجبة للخالق.\rفالوجوب يتعيّن في صفة الخالق بكلّ حال، والانقسام إلى وصفي الجواز والوجوب يكون في صفات المخلوق.\r"], [810, "المسألة الثانية:\r"]], "pg": [808, 810]}, "561.635": {"x": [[810, "إذا علمتم أن الرسالة حقيقتها إبلاغ كلام الغير، والإنذار إبلاغ الكلام مُطلقاً كيفما كان، فقد جاءت رسالة الباري على حقيقتها بواسطة، وأمّا إنذاره فلم يأت إلا على أحد قسميه؛ وهو الإبلاغ مع الواسطة، وقد يكون الإنذار بالفعل فيما يُمتحن به الخلق من المصائب تذكرة لهم ليُنيبوا إلى الله.\rالفصل الرابع: في التنزيل\r"]], "pg": [810, 810]}, "561.636": {"x": [[810, "إذا علمتم معنى الإرسال والإنذار، فالباري يختصّ في المنزلة العليا في ذلك بثلاثة أحكام:\rالأول: حكم الدلالة بالمعجزة على الرسالة ليكون على الصدق دلالةً، لا يجوز ذلك لغيره.\rالثاني: أنه يعصم رسوله عن الكذب في المقالات.\rالثالث: أنه يعصمه عن الزلل في المخالفات.\rويختصّ العبد في المنزلة الثانية بأنه تلزمه ثلاثة أحكام:\rالأول: حُسْن الانقياد.\rالثاني: جميل القبول.\rالثالث: وجوب الامتثال، والله أعلم.\r"], [811, "الاسم الثامن والثلاثون: المُدبِّر\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [810, 811]}, "561.637": {"x": [[811, "جاء به القرآن فعلا، ولم يجئ به اسماً، قال تعالى: \" يُدَبِّرُ الْأَمْرَ مِنَ السَّمَاءِ إِلَى الْأَرْضِ\" (السجدة 5)، وورد في حديث أبي هريرة المفسّر من طريق عبد العزيز بن الحُصين.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [811, 811]}, "561.638": {"x": [[811, "اختلفت فيه عبارة علمائنا:\rفمنهم من قال: إن دبّر علم عواقب الأمور.\rومنهم من قال: إن دبّر نظر في عاقبة الأمر، واستدبر رأى في عاقبته ما لم يعرف في صدره، ويقال: الدَّبْرة على بني فلانٍ يعني العاقبة المذمومة، والدولة لبني فلان يعني الحالة المحمودة.\r"], [812, "الفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [811, 812]}, "561.639": {"x": [[812, "وفيه ثلاث مسائل:\rالمسألة الأولى: في شرح حقيقته\r"]], "pg": [812, 812]}, "561.640": {"x": [[812, "قد تقدّم من قول علمائنا فيها أنه العالم، ولا تشهد له اللغة، ولا يعضده الاشتقاق، وإنما الصحيح أنه نظر في الدبر وهي العاقبة، لكن لا يمتنع أن يُسمّى العلم بالعاقبة تدبيرا، قال تعالى: \" أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ وَلَوْ كَانَ مِنْ عِنْدِ غَيْرِ اللَّهِ لَوَجَدُوا فِيهِ اخْتِلافًا كَثِيرًا\" (النساء 81)، وقال: \" أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا\" (محمد 25)، المعنى أفلا ينظرون إلى آخر المعرفة به حتّى تذهب عنهم الشكوك العارضة فيه.\rوالنظر في العاقبة والفكر فيها إنما هو من قبيل الكلام النفسيّ، فهو التدبّر، فلا يزال يُديره ويُدبّره حتّى يُفضي النظر بعد تمامه وسداده إلى العلم المطلوب، فإن سُمّي به كان من باب تسمية الشيء بثمرته، وهو أحد قِسمي المجاز حسب ما بيّنّاه في كتب الأصول.\r"], [813, "المسألة الثانية: في الاعتقاد لما يُضاف إلى الباري فيه\r"]], "pg": [812, 813]}, "561.641": {"x": [[813, "إذا علمتم –وفّقكم الله- معنى التدبير، فوجه إضافته إلى الباري تعالى أنه علم العواقب وأخبر عنها خبرا صادقا، وانفرد منها بما لم يُطلِع عليه أحدا، فقوله: \"يُدَبِّرُ الْأَمْرَ\" (يونس 3)، اختلف علماؤنا في تأويله على أربعة أقوال:\rالأول: يقضيه.\rالثاني: يؤخّره.\rالثالث: يأمر به ويُمضيه.\rالرابع: يُنزله في مرتبته على أحكام عاقبته.\rفأمّا من قال إنه بمعنى يؤخّره فضعيف، لا لغة ولا اشتقاق يدلّ عليه.\r"], [814, "وأما من قال يأمر به فهو بعض التدبير، لأن الأمر من التدبير، والنهي منه، وكلّ أقسام الكلام.\rوأما من قال تنزيل الأمور في مراتبها على أحكام عواقبها، فإن أراد بالقول فهو الصحيح، وإن أراد بالفعل فذلك مجازٌ، لأنه لا فعل إلا منه، فقد أخبر تعالى بما هو بصفته عنه، فإن فُسّر به كان وهماً من وجهين:\rأحدهما: أنه تفسير لاسم الذات باسم الفعل.\rوالثاني: أنه صرف الحقيقة إلى المجاز من غير دليل.\rوالعبارة الخالصة المخلِّصة أنه القول المنزِّل للأمور في مراتبها على أحكام عواقبها، فالتّدبير في الإخبار عنها كالتقدير في الترتيب لها، وهي نكتةٌ عظمى نفع الله بها برحمته.\rالمسألة الثالثة:\r"]], "pg": [813, 814]}, "561.642": {"x": [[814, "هذا الاسم من الأسماء المشتركة التي أَذِن الشرع في تسمية المخلوق بها، وإن كان من أسماء الخالق الكريمة، وقد قال تعالى: \"فَالْمُدَبِّرَاتِ أَمْرًا\"\r"], [815, "(النازعات 5) اتّفق العلماء كلّهم عن بكرة أبيهم على أنّها الملائكة تنزل بالأمور المُدبَّرة المُحكمة من عند الله، فسُمّيت بما تنزل به.\rالفصل الرابع: في التنزيل\r"]], "pg": [814, 815]}, "561.643": {"x": [[815, "لا يخفى على ذي لُبٍّ أن الباري تعالى عالمٌ بالعواقب، فبذلك حَكَمَ، مُخبرٌ بالحقائق، فهذان حكمان لا يُشارَك فيهما.\rالمنزلة السفلى للعبد:\rهي بأن لا يُنفِذ قولاً ولا عملاً حتّى يفكّر في عاقبته، فمن أمثالهم: شرّ الرأي الدَّبَري.\r"], [816, "الاسم التاسع والثلاثون والمُوفّي أربعين والحادي والأربعون والثاني والأربعون: المُمتحِن، البالي، المُبتلي، المُبلي\rفيها أربعة فصول:\rالفصل الأول: في موردها\r"]], "pg": [815, 816]}, "561.644": {"x": [[816, "ذكر علماؤنا –رحمة الله عليهم- هذه الأسماء ولم يرد بها القرآن اسماً، لكن ورد بها فعلا، قال الله تعالى: \" أُولَئِكَ الَّذِينَ امْتَحَنَ اللَّهُ قُلُوبَهُمْ لِلتَّقْوَى\" (الحجرات 3)، وقال: \" وَنَبْلُوكُم بِالشَّرِّ وَالْخَيْرِ فِتْنَةً\" (الأنبياء 35)، وقال: \"وَلِيُبْلِيَ الْمُؤْمِنِينَ مِنْهُ بَلَاءً حَسَنًا\" (الأنفال 17)، وقال: \" فَأَمَّا الإنْسَانُ إِذَا مَا ابْتَلاهُ رَبُّهُ فَأَكْرَمَهُ وَنَعَّمَهُ\" (الفجر 15).\rالفصل الثاني: في شرحها لغةً\r"]], "pg": [816, 816]}, "561.645": {"x": [[816, "المحنة والابتلاء الاختبار، تقول محَنْتُ فلاناً وامتحنته، وبلوتُه أبلوهُ بَلواً وبلاءً، وأبليه وابتليته، أي اختبرته، وابتليت فلاناً فأبلاني، أي\r"], [817, "اختبرته فأخبرني، والبلاء يكون في الخير والشر، والمحنة تختصّ بالمشقّة والمكروه.\rالفصل الثالث: في حقيقته وعقده\r"]], "pg": [816, 817]}, "561.646": {"x": [[817, "إذا علمتم أن حقيقة هذه الأسماء الاختبار والاستعلام، فها هنا ثلاث مسائل:\rالمسألة الأولى:\r"]], "pg": [817, 817]}, "561.647": {"x": [[817, "أن الباري تعالى لا يختبر ليَستعلم كما يفعل أحدنا، فإنه العالم الذي لا يخفى عليه شيء، ولكن ذلك لفائدتين:\rإحداهما: أن يعلم مشاهدةً ما عَلِمه غيباً، فإنه عالم الغيب، ثم يُحضر ما غاب بقدرته فيتعلق به علمُه، وذلك ليس بحدوثٍ على ما بيّنّاه في الأصول.\rالثانية: أن ذلك ليُعلم عباده من الملائكة والجنّ والإنس ما شاء من علمه، فيكون معنى قوله حتّى نعلم أو حتّى نبلُوَ ونختبر، أي حتى يَبلُوَ عبادي ويعلَمَ من أردتُ إعلامه من خلقي.\r"], [818, "المسألة الثانية: قوله \"لِيَبْلُوَكُمُ\"\r"]], "pg": [817, 818]}, "561.648": {"x": [[818, "اعلموا –وفّقكم الله- أنه سبحانه يبلُو ويمتحن بوجهين:\rأحدهما: بالأمر والنهي وما توجّه من التكليف؛ حتى يُعلم الممتثل من المخالف، ويظهر من يُسِّر لليُسرى ويُسّر للعسرى، فيعود ذلك إلى صفة الكلام.\rالثاني: أنه يختبر بالأفعال، مثل الموت والحياة، والعطاء والمنع، والنفع والضرّ، حتى يُعلم الصابر من الساخط، والثابت من الساقط، فيكون ذلك من صفات الأفعال.\rالمسألة الثالثة:\r"]], "pg": [818, 818]}, "561.649": {"x": [[818, "قال بعض علمائنا: معنى قوله: \" وَلِيُبْلِيَ الْمُؤْمِنِينَ مِنْهُ بَلَاءً حَسَنًا\" (الأنفال 17)، أي يُعطي، وهذه دعوى في اللغة، وإنما هو على بابه من الاختبار، وذلك فيما أُنزل بهم من لقاء العدو، ولَقُوا من فتنة قتالهم، قال سبحانه: \" فَلَمْ تَقْتُلُوهُمْ وَلَكِنَّ اللَّهَ قَتَلَهُمْ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَكِنَّ اللَّهَ\r"], [819, "رَمَى وَلِيُبْلِيَ الْمُؤْمِنِينَ مِنْهُ بَلَاءً حَسَنًا\" (الأنفال 17) المعنى بلاءً تُحمج عاقبته، وهو بلاء الخير.\rفإمّا أن يعود ذلك إلى تكليف الجهاد والأمر باللقاء، فيعود ذلك إلى الكلام، وإمّا أن يعود ذلك إلى نفس القتال فيكون من صفات الأفعال، ويبقى الابتلاء على بابه كما بيّنّاه، والله أعلم.\rالفصل الرابع: في التنزيل\r"]], "pg": [818, 819]}, "561.650": {"x": [[819, "يختصّ الباري سبحانه في المنزلة العليا بحكمين:\rأحدهما: أنه ينفدر بعلم العاقبة، فلا يبتلي ليظهر ما كان خافياً، لكن ليظهر من كان مُطيعا ممّن كان عاصياً.\rالثاني: أنه يمتحن بالمصائب ابتداءً من غير حَجْر، وليس ذلك إلّا له.\rالمنزلة الثانية للعبد:\rوعليه في ذلك حكمان:\rأحدهما: أن يلتزم الطاعة بامتثال الأمر واجتناب النهي.\rالثاني: أن يصبر للنوائب.\r"], [820, "الاسم الثالث والأربعون: الفاتن\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [819, 820]}, "561.651": {"x": [[820, "هذا اسمٌ لم يرد به القرآن اسماً وإنما ورد به فعلاً، قال الله تعالى: \" وَلَقَدْ فَتَنَّا الَّذِينَ مِن قَبْلِهِمْ\" (العنكبوت 3)، \" وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ\" (الدخان 17)، وقال: \" وَظَنَّ دَاوُودُ أَنَّمَا فَتَنَّاهُ\" (ص 23)، وقال: \" وَفَتَنَّاكَ فُتُونًا\" (طه 40)، وقال: \" ثُمَّ لَمْ تَكُنْ فِتْنَتُهُمْ إِلا أَنْ قَالُوا وَاللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ\" (الأنعام 23)، وجاء في حديث عبد الله بن الزبير أن الله هو الهادي والفاتن، وأجمع عليه أهل السنة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [820, 820]}, "561.652": {"x": [[820, "الفتنة الخبرة، يقال: فتن الذهب أحرقه بالنار ليختبره، ويقال: الفتنة إعجابك بالشيء، يقال منه: فَتَنَه يفتِنُه فَتْناً وفُتُوناً وأَفتَنتهُ أنا، قال سيبويه: فَتَنَهُ جعل فيه فتنة، وأفتَنَهُ أوصل إليه فتنة، ويقال: الفتنة الضلال، والفاتن\r"], [821, "الشيطان، ويقال: أفتَنَهُ أقْدره على الضلال، قال الله تعالى: \" مَا أَنْتُمْ عَلَيْهِ بِفَاتِنِينَ\" (الصافات 162)، معناه قادرين، ولذلك جعل تعديته بحرف على، ويقال: الفتنة الكفر، كما قال: \" وَقَاتِلُوهُمْ حَتَّى لا تَكُونَ فِتْنَةٌ\" (البقرة 193).\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [820, 821]}, "561.653": {"x": [[821, "قد تقدّم شرح الفتنة لغة، وحقيقة الفتنة منها أنها عبارة عن كل فعل يظهر به حال المفتون في مآله، إلا أن حكمها يختلف في الكفّار والمؤمنين، فإنها في الكفار عبارة عن كل بلاء ومحنة يتوهّم به الخلاص فيوقع في الهلاك؛ وهي في المؤمنين عبارة عن كلّ بلاء يظهر به الصبر على القضاء للعوامّ، والرضى بالقضاء للخواصّ، والسرور بالقضاء لخواصّ الخواص.\rوفصل التنزيل قد امدرج في اسم المُبتلي قبله.\r"], [822, "الاسم الرابع والأربعون: المُنتقم\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [821, 822]}, "561.654": {"x": [[822, "قال الله تعالى: \" عَزِيزٌ ذُو انتِقَامٍ\" (آل عمران 4)، وقد بيّنّا أنه لا فرق بين قولك فلانٌ عالمٌ أو ذو علم، وجاء في القرآن فعلاً، قال الله تعالى: \" فَلَمَّا آسَفُونَا انتَقَمْنَا مِنْهُمْ\" (الزخرف 55)، وقد ورد في حديث أبي هريرة المفسّر.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [822, 822]}, "561.655": {"x": [[822, "اعلموا أن النِّقمة في اللغة ترد على وجهين:\rأحدهما: أن تكون بمعنى الذمّ والإنكار للأفعال القبيحة، بدليل قوله تعالى: \" هَلْ تَنقِمُونَ مِنَّا إِلَّا أَنْ آمَنَّا\" (المائدة 59).\rالثاني: المكافأة بالعقوبة، كقوله: \" فَلَمَّا آسَفُونَا انتَقَمْنَا مِنْهُمْ\" (الزخرف 55).\r"], [823, "الفصل الثالث: في شرحه حقيقة\r"]], "pg": [822, 823]}, "561.656": {"x": [[823, "إذا فهمتم هذا، فهو تعالى مُنتقمٌ بكلامه في ذمّه الكفّارَ ولعنه لهم، وهو منتقمٌ بعقوبته، فتارةً يكون من صفات الذات، وتارة يكون من صفات الفعل.\rالفصل الرابع: في التنزيل\r"]], "pg": [823, 823]}, "561.657": {"x": [[823, "إذا علمتم هذا فالباري تعالى يختصّ في هذا بحُكمين:\rأحدهما: أنه ينتقم من فعلٍ لهم هو خَلَقَه فيهم.\rالثاني: أنه ينتقم بعقوبةٍ تُرْبي على الذنب.\rويختصّ العبد في ذلك بحكمين:\rأحدهما: أن ينتقم بمثل الذنب لا بزيادة.\rالثاني: أنّ العفو له أحسن ليكون أجره على الله، فقد روي أن النّبي صلى الله عليه وسلم ما انتقم لنفسه قطّ إلّا أن تُنتَهَك حرمة الله.\rقد نجز القول في الأسماء المتعلّقة بالذات بعون الله وتأييده، والآن نشرع في الأسماء المتعلّقة بالأفعال المحضة إن شاء الله تعالى.\r"], [824, "القول في أسماء الأفعال وعددها سبعون اسماً\r"], [826, "لم يَخْف عليكم –أنار الله أفئدتكم- أن التوحيد إنما يتمّ بمعرف الذات وصفاتها، والأفعال وأحكامها، ونحن نقدّم لكم مقدّمتين قبل أن نشرع في بيان أسماء الأفعال، تفتح لكم كثيرا من مُنغَلَقاتها.\rالمقدمة الأولى: في أن الله تعالى لا يسمى من جهة الأفعال.\rأن تعلموا أن الله سبحانه لم تجب عليه تسميةٌ من جهة أفعاله، ولا لأجل أفعاله، وإن كانت وجبت عندها، وقد ذكرنا هذا الفصل في باب القضاء والقدر مشروحاً في كتب الأصول، فلا يوصف سبحانه، ولا يُسمّى من جهة الأفعال لأنه قد فعلها، إذ قد فعل أفعالا كثيرة ولم يُشتَقّ له منها اسمٌ، ولا يخرج من أن يكون فاعلاً لها، وإنما الأصل في ذلك الخبر.\rالمقدمة الثانية: في أن الإذن في ذكر الفعل إذنٌ في ذكر الاسم\rأنه قد ورد لفظ فَعَلَ ويضفعل في وصفه، فإن ذلك مُتضمِّنٌ مقتضٍ لوصفه بلفظ الاسم، لأنه صادرٌ عنه ومنه اشتُقّ، ولا خلاف في ذلك بين أهل السنّة، وأنكرت ذلك المعتزلة لبدعةٍ عظيمةٍ بيّنّاها في كتب الأصول، وذلك أن عندها\r"], [827, "إذا قيل فعل الظّلم فاشتقاقه أنه فاعلٌ للظلم لا أنه ظالم، لأنّ حروف الظالم، وهي الظاء واللام والميم لا توجد في فَعَل، وقد بينّا فساد ذلك في كتب الأصول، وثبت عندنا أن الإذن في ذكر الفعل إذنٌ في ذكر الاسم، وذلك مُتّفقٌ عليه كما بينّا، والله أعلم.\rإذا ثبت هذا، فإنّ أوصاف التنزيه، وأوصاف الذات، كالعلم والقدرة ونحوها، لم يزل تعالى موصوفاً بها في الأزل ولا يزال، لقيامها به ووجودها معه، حسبما بينّاه في كتب الأصول.\rفأمّا أوصاف الأفعال فإنه كان خالقاً بعد أن لم يكن، ومُوجداً ومُحيياً ومُميتاً، ولم يكن في الأزل كذلك.\rفإن قيل: فأنتم تقولون: إن كلامه أزليّ، وإن وصفه لنفسه وإخباره عنها بأنه خالقٌ ورازقٌ لم يزل، قبل أن يخلق الخلق بغير أمدٍ.\r"], [828, "قلنا: كذلك نقول، ولكن لا يلزمنا أن يكون خالقاً في الأزل لأجْل وصفه لنفسه بذلك، لأنّ معنى قوله إنه خالقٌ أي سيخلق، وقد جاء في لسان العرب: خالقٌ بمعنى يخلق، وفاعل بمعنى سيفعل كثيرا، وقد قال تعالى للملائكة: \"إِنِّي خَالِقٌ بَشَرًا مِّن طِينٍ\" (ص 71)، قبل أن يخلقه، وكان المعنى أنّي سأخلق، فالاسم قديمٌ والوصف لم يزل، والفعل حادثٌ، وإذا حدث الفعل لم يتجدّد اسمٌ، فافهموا ترشُدوا.\rوبعد هذا فافهموا –وفّقكم الله- أنه لمّا كانت أفعال الباري تعالى كثيرةً كانت الأسماء المتعلِّقة بها كثيرة، وهي لا يُحصيها إلا الربّانيّون والأحبار، لكونها في حدّ الإكثار، ولكنّا نذكر منها ما ورد بلفظ الأسماء ونُرْجئ ما سواها.\r"], [829, "القول في اسم الربّ\rوهو الأوّل، وفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [823, 829]}, "561.658": {"x": [[829, "اعلموا –علّمكم الله- أن هذا الاسم من أصول الأسماء وأمهات الصفات، وهو في أسماء الأفعال عَديل قولنا \"الله\" في أسماء الذات، وإن كان قولنا الله يُعطي الأسماء كلّها المتعلّقة بالذات وبالأفعال، ألا ترى أنك تقول: إله العالمين وإله السماوات والأرض، كما تقول رب العالمين ورب السماوات والأرض؛ وقد ورد به القرآن والسنة وأجمعت عليه الأمة، إلا أنه لم يرد في حديث أبي هرير المفسّر من طريق شُعيب، وورد من طريق عبد العزيز؛\rوعجباً لمن سرد الأسماء فيه، حيث أغفل هذا الاسم العظيم القَدْر، وقد قال تعالى مخبراً عن خليله إبراهيم: \"رَبِّيَ الَّذِي يُحْيِي وَيُمِيتُ\" (البقرة 258)، وقال: \"رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِنَ النَّاسِ\" (إبراهيم 38)، وقال مخبراً عن كليمه: \"رَبِّ أَرِنِي أَنظُرْ إِلَيْكَ\" (الأعراف 143)، \"رَبِّ اغْفِرْ لِي وَلِأَخِي\" (الأعراف 151)، وقال مخبراً عن صدّيقه: \"رَبِّ قَدْ آتَيْتَنِي مِنَ الْمُلْكِ\" (يوسف 101)، وقال لحبيبه وخليله: \"وَقُل رَّبِّ اغْفِرْ وَارْحَمْ\" (المؤمنون 118).\r"], [830, "الفصل الثاني: في شرحه لغة\r"]], "pg": [829, 830]}, "561.659": {"x": [[830, "قد ذكر علماؤنا فيه أربعة أقوال:\rالأول: أن الرب المالك، كما قال طَرَفة:\rكقنطرة الروميّ اقسَم ربُّها *** لتُكءتَنَفَنْ حتى تُشاد بقرْمدِ\rوالعرب تسمّي الملوك أربابا، ومنه قول يوسف الصدّيق: \"اذْكُرْنِي عِنْدَ رَبِّكَ\" (يوسف 42)، و \"ارْجِعْ إِلَى رَبِّكَ\"، و \"إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ\"، وعليه جاء الحديث في أشراط الساعة: \"أن تلد الأَمَة ربَّها وربّتها\"، يعني أن تلد من يكون نظير مولاها ومالكها في الحسَب، وهو ولدها، ومنه قول الشاعر:\rبقَتْل بني أسدٍ ربّهم *** ألا كلّ شيءٍ سواه جَلَلْ\rالثاني: الربّ السيّد، كما قال الأعشى:\rوأهلَكْنَ يوماً ربّ كِندةَ وابنه *** وربّ مَعَدٍّ بين خبْت وعرعرِ\r"], [831, "وكذلك فسّر ابن عبّاس ربّ العالمين، معناه سيّد العالمين، وهو اختيار الشيخ أبي الحسن الأشعري.\rالثالث: الربّ المعبود، يدلّ عليه حديث عذاب القبر، حيث يقال له: من ربّك؟ المراد من معبودك.\rالرابع: أن الربّ المصلح للشيء، القائم بتدبيره وإتمام ما لا بدّ له منه، يقال في تصريفه: ربّ الشيء يربّه ربابةً فهو ربٌّ، كما تقول: طبَّ فهو طبٌّ، الاسم والفعل الماضي سواءٌ، كقوله: برّه يبَرُه فهو بَرٌّ، ويقال: أديمٌ مربوبٌ أي مصلحٌ، وتقول العرب: ربّ البيت وربّة البيت، تعني القائم بأموره والمصلح له، وسُمّي العلماء ربّانيين لأنهم يُرَبّون الناس بصغار العلم قبل كباره، وعلى أنّ الربّ المصلح يجري قول علقمة:\r"], [832, "وأنت امرؤٌ أفْضَت إليك ربابتي *** وقبلك ربّتني فضِعتُ رُبُوبُ\rالفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [830, 832]}, "561.660": {"x": [[832, "فيه ثلاث مسائل:\rالمسألة الأولى: في تحقيق هذا الاسم\r"]], "pg": [832, 832]}, "561.661": {"x": [[832, "اعلموا –أرشدكم الله- أنه مهما وجدنا العلماء قد ذكروا في معاني الأسماء وجوهاً، ووجه الاشتقاق يعضد بعضها، فإنّ الذي يعضده الاشتقاق أقوى الوجوه فيه وأولاها به، والذي يدلّ عليه الاشتقاق وبعضده المعنى أن يكون الربّ هو المصلِح، وإليه يرجع معنى قولهم: إنه المالك أو السيّد، فإنّ كل مالك وسيّد ربٌّ مصلِحٌ؛ يقوم بالمعاش، ويرُبّ في صلاح الحال، ومنه ربّ البيت، أي المُقيم لأموره، والجالب لمصالحه، وتقول العرب: فلانة كانت ربّة بيت في الجاهلية، أي مُصلحتَه، وإليه يرجع قوله في القبر: من ربّك؟ أي من كان يدبّرك ويقوم بمصلحتك ويُرشدك إلى منافعك، فهذا وقت\r"], [833, "الإرشاد، ولذلك تقول العرب لزوج المرأة: هو ربّها، لأنه يتولّى مصالحها، وأحقّ الأرباب بالعبادة الربّ الأعظم الذي يَرُبّ كل ربٍّ، فيصحّ على هذا أن يُسمّى الربّ معبودا، والحقيقة ما ذكرناه.\rالمسألة الثانية: في التركيب\r"]], "pg": [832, 833]}, "561.662": {"x": [[833, "قال علماؤنا: إذا قلنا إن الربّ هو المالك، فإنما يكون الربّ مالكاً من بعض الوجوه، لأنه قد يملك ما لا يَربّ، وهو الجماد، وإنما يجتمع وصف المالك والربّ مضافاً إلى الأعيان التي يصح ملكها وتربيبها، وكذلك إذا قلنا إن الربّ هو السيّد، فإنما يختصّ بمِلك من يعقل، لأنه لا يصحّ في لسان العرب أن يقال: سيّد الشجر والجبال كما يقال: سيّد الناس.\rوإذا قلنا إن الربّ هو المصلِح القيّم بالأمور العائدة بحُسن التدبير على كلّ قليل وكثير، فهو الله سبحانه بالحقيقة وعلى العلموم، وعلى هذا يخرج أن يكون قوله: \"رَبِّ الْعَالَمِينَ\" على العموم في جميع المكوَّنات، ويكون العالمون متناوِلاً لجميع المخلوقات، على ما بيّنّاه في موضعه، وهو اختيار الشيخ أبي الحسن الأشعري في كتاب التفسير، الكتاب الكبير المسمى بالمختزن، في قوله: \" رَبِّ الْعَالَمِينَ\" أنه ربّ المربوبات.\r"], [834, "وعليه يدلّ قول فرعون: \" قَالَ فِرْعَوْنُ وَمَا رَبُّ الْعَالَمِينَ\" (الشعراء: 23)، \" قَالَ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِنْ كُنْتُمْ مُوقِنِينَ\" (الشعراء 23)، \" قَالَ رَبُّكُمْ وَرَبُّ آبَائِكُمُ الأَوَّلِينَ\"، \" قَالَ رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ\" (الشعراء 23)، فجعله ربَّ الكل على العموم، وربّ العاقلين على الخصوص، وربّ المشاهدة بالجميع، فهو إذاً ربّ من يعقل وما لا يعقل، وربّ ما غاب وحضر، ويرجع الخصوص إلى العموم، ويثبت المقصود المفهوم، ولا يخفى عليكم أن الجماد مُصلَحٌ مُربّلاً، كما أن الحيوان مصلَحٌ مُربّىً، وذلك بإدامة بقائهما وصيانتهم عن الآفات المتلفات، فثبت أن الربّ هو المصلح المُربّي، وأنّ ذلك على العموم في الصفات والأحوال والأعيان، والحمد لله وحده.\rالمسألة الثالثة:\r"]], "pg": [833, 834]}, "561.663": {"x": [[834, "إذا ثبت هذا فإذا كان معنى الربّ المصلح للشيء القائم بتدبيره، فذلك من صفات الأفعال، لأنه لا يُصلَح ولا يُدبَّر إلا الموجود دون المعدوم، فكلّ ما\r"], [835, "خلق فهو المربوب، ويكون اسم الربّ في الإضافة إلى جميع الأفعال كاسم الله في الإضافة إلى جميع الأسماء، فلذلك قلنا: إن الربّ في أسماء الأفعال عديل قولنا الله في أسماء الذات، لأن هذا يتناول جميع الأفعال كما يتناول ذلك جميع الأسماء، ولذلك فرّق بينهما في الحمد والتمجيد فقال: \" الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ\"؛ فقولك: \"الْحَمْد\"، يعمّ الثناء لجميع صفات الكمال وخلال الجلال.\rوقولك \"لله\" يعمّ جميع الأسماء.\rوقولك \"ربّ العالمين\" يعمّ جميع الأفعال.\rولهذا صار هذا الكلام فاتحة الكتاب، وخاتمة كلام أهل الجِنان، لعموم تناوله الخالق والمخلوق، والفاضل والمفضول.\rالحمد لله الذي هدانا لهذا وما كنّا لنهتدي لولا أن هدانا الله.\rالفصل الرابع: في التنزيل\r"]], "pg": [834, 835]}, "561.664": {"x": [[835, "اعلموا –رحمكم الله- أن للباري تعالى في هذا الاسم أحكاما يختصّ بها جَماعها أنّه لا موجود إلا منه، ولا مُنتهى إلا إليه.\rالمنزلة الثانية للعبد:\rتتحصّل بوجهين:\r"], [836, "أحدهما: أن يُفرد الله لهذا الاسم فلا يتحلّى به، ولا يصف به نفسه، فقد صحّ عن النبي صلى الله عليه وسلم أنه قال: \"لا يقولنّ أحدكم: عبدي وأمتي، ولا يقل المملوك: ربّي وربّتي، وليقل المالك: فتاي وفتاتي، وليقل المملوك: سيدي وسيدتي، أنتم المملوكون والربّ الله\".\rالثاني: أن يرى الأمور كلّها من الله، فيُفوّض إليه ويتوكّل عليه، ويلجأ في الكبير والصغير إلى ربه.\r"], [837, "الاسم الثاني: العَدْل\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [835, 837]}, "561.665": {"x": [[837, "لم يرد به القرآن فعلا ولا اسما، ولكن ورد في وصف القرآن، قال سبحانه: \"وَتَمَّتْ كَلِمَةُ رَبِّكَ صِدْقًا وَعَدْلا\" (الأنعام 115)، وورد في ضدّ العدل من الأوصاف ما يدلّ على وصفه تعالى به، قال تعالى: \"إِنَّ اللَّهَ لَا يَظْلِمُ النَّاسَ شَيْئًا\" (يونس 44)، وإذا لم يظلمهم وقد تصرّفوا على حكم فعله فقد عدل فيهم؛ وجاء في حديث أبي هريرة المفسّر المعدّد، وأجمعت عليه الأمة من مُؤالف ومخالف، وإن اختلفوا في معناه ومُتعلَّقِه.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [837, 837]}, "561.666": {"x": [[837, "قال علماؤنا: العد ضدّ الجَوْر، ورجل عَدْلٌ، إذا كان مستمرّ الطريقة، وهذا عِدْل هذا إذا كان مساوياً له، وأصل ما ورد على هذا اللفظ يرجع إلى ما سردنا عنهم.\r"], [838, "الفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [837, 838]}, "561.667": {"x": [[838, "فيه أربعة مسائل:\rالمسألة الأولى: في بيان حقيقته\r"]], "pg": [838, 838]}, "561.668": {"x": [[838, "إذا علمتم ما تقرّر في اللغة من معنى هذا اللفظ، وأنّ العدل هو الذي لا يميل به الهوى، ولا يجور في الحكم، فإنّ حقيقة العدلية مما اختلفت فيه عبارات علمائنا على ثلاثة أوجه:\rالأول: قالوا: العدل فعلُ ما للفاعل أن يفعله.\rالثاني: كلّ فعلٍ وقع لم يُتَعَدَّ فيه أمرُ آمر ولا نهيُ ناهٍ.\rالثالث: العدلُ ما فعله الفاعل وكان مالكاً لفعله.\rوالعبارة والأولى أوجز وأحقّ في البيان لأنها تعمّ المحدَث والقديم، وقد بيّنّا ذلك في الأصول.\rالمسألة الثانية: في وجه تسمية الباري تعالى به\r"]], "pg": [838, 838]}, "561.669": {"x": [[838, "اختلف في ذلك علماؤنا:\rفمنهم من قال: معناه ذو العدل.\r"], [839, "ومنهم من قال: إنه اسمٌ للفاعل سُمّي به الفعل، كقولنا: خَصْم وزَوْر وضَيْف، والمراد بقوله عند المحقّقين عدلٌ أنه وصف بجميع الجنس مبالغة، لأنّه استولى على الأفعال الحسنة، فوُصف بالجنس أجمع تمكيناً للوصف وتأكيدا، وأُفرد ليكون الإفراد أمارةً للمصدر وعلامةً عليه.\rالمسألة الثالثة: في وجه دخول خلق الآلام والمضرات في العدل\r"]], "pg": [838, 839]}, "561.670": {"x": [[839, "اعلموا أن العادل إذا كان من فعل ما له أن يفعله، والباري عندنا خالق الآلام والمضرات والمعاصي والكفر، وكل ذلك عدلٌ من الله، لأنّ له فعل ذلك، لا آمر فوقه، ولا مالك غيره، ولا معتَرض عليه، وإذا وقعت المعاصي من العبد كان ذلك جَوْراً وظُلماً.\rفإن قيل: وكيف يكون الفعل الواحد عدلاً وظلما في حالة واحدة؟\rقيل: إنّما يتناقض ذلك لو كان من جهة واحدة، بالإضافة إلى فاعلٍ واحد، فأمّا إذا كان من فاعلين أو من فاعلٍ واحد من جهتين فلا يتناقض ذلك.\r"], [840, "وكذلك عندنا، يكون الفعل الواحد حسناً وقبيحا في حالة واحدة من جهتين، معلوما مجهولاً من طريقين، وكذلك يجوز أن يكون الخبر صدقاً كذباً من جهتين، وقد حقّقنا ذلك في الأصول.\rالمسألة الرابعة: في وصف كلام الباري بأنه عَدلٌ\r"]], "pg": [839, 840]}, "561.671": {"x": [[840, "قد ثبت صحّة وصف الباري تعالى بالعدل، فأمّا وصف كلامه به فعلى وجهين:\rأحدهما: أنه متّسقُ الفصاحة، منتظمٌ في الجزالة، لا يقال: إنه جزْلٌ وهزْلٌ، وفصيحٌ وركيكٌ، بل هو في الجزالة والفصاحة على أوفى طريقةٍ بأجمعه، متناسب بجملته، وهذا هو العدل في لسان العرب؛\rالثاني: أنّه لا باطل فيه ولا ظلم، بل هو كلّه حقٌّ حسنٌ، قال الله تعالى: \"إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَى وَيَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ وَالْبَغْيِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ\" (النحل 90).\rالفصل الرابع: في التنزيل\r"]], "pg": [840, 840]}, "561.672": {"x": [[840, "إذا عرَفتم العدل، فاعلموا أن للباري تعالى أن يفعل ما يشاء ويحكم ما يريد، لا تتغيّر الأفعال بالنسبة إليه، وعن هذا وقعت العبارة بقوله: \"فَعَّالٌ لِّمَا\r"], [841, "يُرِيدُ\" (هود 107)، فلو عذّب الخلق أجمعين؛ من نبي مُرسل، وملَك مقرَّب، وعبد صالح، كتعذيبه للكفار والعصاة لكان ذلك عدلا منه، كما لو نعّم الجميع في جنانه لكان ذلك فضلا منه، وإذ نوّعهم نوعين، وفرّقهم فريقين؛ فريقاً في الجنة، وفريقاً في السعير، فتلك جكمةٌ بالغة، فعذابه للجميع عدلٌ، ورحمته للجميع فضلٌ، وتنويعه حكمةٌ فصلٌ، وعن هذا قال بعض علمائنا: نعوذ بالله من عدله، ونسأل الله من فضله، ونرغب إليه في أفضل وجْهَي حكمته.\rوبعد هذا فقد وجب أن نتكلّم عن أسمائه الفعليّة إن شاء الله.\rالمنزلة السفلى للعبد:\rعلى العبد في ذلك أمران:\rأحدهما: أن يُصمّم عقده على أنه لا يستقبح منه موجود.\rالثاني: أن يلزم الاستقامة في كلّ حال، وحينئذ يُسمّى عدلاً، ولذلك تحقيقٌ بيّنّاه في المسائل الفقهية.\r"], [842, "الاسم الثالث: الخالق\rاعلموا –أدام الله لكم التبصرة- أن الخالق اسم عظيم في ذاته، عظيم في متعلّقاته، يقرع من التوحيد باباً، ويهتك من المعارف حجابا، ويُغدف دون المقصّرين جلبابا، وفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [840, 842]}, "561.673": {"x": [[842, "قال الله تعالى: \"الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ\" (الحشر 24)، وقال: \"مِنْ خَالِقٍ غَيْرُ اللَّهِ\" (فاطر 3)، وقال: \"إِنَّ رَبَّكَ هُوَ الْخَلَّاقُ الْعَلِيمُ\" (الحجر 86)، ووردت به السنة في حديث أبي هريرة المفسّر، وأجمعت عليه الأمّة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [842, 842]}, "561.674": {"x": [[842, "ورد في اللغة على أربعة معانٍ:\r"], [843, "الأول: التقدير، ومنه قول زُهيْر:\rولَأنت تفْري ما خلقْتَ وبعـ *** ــض القوم يخلق ثمّ لا يفري\rيقول: إذا قدّرت شيئا قطعته، وغيرك يقدّر ما لا يقطعه.\rوعليه يُخرَّج \"فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ\" (المؤمنون 14)، ومن أمثاله: هذا ما فَرَتْه أيدي الخوالق، أي الأساكفة، ويُروى عن الحجّاج أنه قال: لا أعِدُ إلّا وفَيتُ، ولا خلقْتُ إلا فريْتُ.\rالثاني: الإنشاء والاختراع، وإليه الإشارة بقوله تعالى: \"هَلْ \"مِنْ خَالِقٍ غَيْرُ اللَّهِ\" (فاطر 3).\rالثالث: أنّ الخلق التصوير كقوله تعالى: \"أَنِّي أَخْلُقُ لَكُم مِّنَ الطِّينِ كَهَيْئَةِ الطَّيْرِ\" (آل عمران 49)، يعني أُصوّر.\rالرابع: الخَلق: الكذب، ومنه قوله تعالى: \"وَتَخْلُقُونَ إِفْكًا\" (العنكبوت 17)، وكقوله: \" إِنْ هَذَا إِلا خُلُقُ الأوَّلِينَ\" (الشعراء 137)، يعني كذب الأوّلين.\r"], [844, "الفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [842, 844]}, "561.675": {"x": [[844, "اعلموا –أرشدكم الله- أنّا قد بيّنّا وجوه تصرّف الخلق في اللغة، وعدّدناها عن أئمتنا على أربعة أنحاء.\rفأمّا الثلاثة منها فجائزة في حقّ الله تعالى، والرابع مستحيلٌ، وهو كون الخلق بمعنى الكذب.\rوتأويل الوجوه الثلاثة المذكورة وتصرّفها في حق الله تعالى تتعلّق بها معانٍ لا بدّ من تفصيلها بفصولٍ تميّز آحادها، وتشرح مقاصدها، ومسائل تُعيّنها، وعددها ثلاثة:\rالمسألة الأولى: في بيان حقيقة الخلق ووجه تركيب الحقائق المعنويّة على الألفاظ اللغوية\rفنقول: أمّا الخلق بمعنى الإبداع والاختراع فهو حقيقة، وهو لله وحده لا يَشرَكُهُ فيه غيره، على ما حقّقناه في كتاب المُقسِط والمتوسِّط والعقد الأصغر وغيرها، وكلّ ما وراءه مجازٌ حتى قول الله سبحانه: \"وَإِذْ تَخْلُقُ مِنَ الطِّينِ كَهَيْئَةِ الطَّيْرِ\" فإنه اتّساع، كما سمّاه مُبرئاً للأكمه، ولم يكن هو الذي يُبرئ، ولكنه نسب الفعل إليه لمّا كان مخلوقاً، بسبب دعائه، وكان هو المتحدّي به، وجاء شاهدا على صدقه، وكذلك قوله تبارك وتعالى: \"أَحْسَنُ\r"], [845, "الْخَالِقِينَ\" فإنّ الوجه فيه أنّ الله لمّا ذكر غيره مع نفسه أعطاه اسمه، كما يقال: العُمران والقَمَران والأسودان، وأحدهما عمر وقمر وأسود، والآخر ليس كذلك، فقوله: \"أَحْسَنَ الْخَالِقِينَ\" مثله، أحدهم خالق وباقيهم ليس بخالق، والدليل عليه قوله تعالى: \"هَلْ مِنْ خَالِقٍ غَيْرُ اللَّهِ\"، وقد قال تعالى في آية أخرى: \"أَمْ خُلِقُوا مِنْ غَيْرِ شَيْءٍ أَمْ هُمُ الْخَالِقُونَ\" (الطور 35)، فعظّم وصفهم لأنفسهم بأنهم خالقون، وأنكر دعواهم لذلك، ولو كان حقيقة لما جاز نفيه عنه، لأنّ الحقائق لا يجوز نفيُها عن مُسمّياتها، وكذلك تسميتُهم للكاذب خالقاً إنما هو اتّساعٌ، لأن الكاذب لمّا كان مُخبراً عن شيء لا أصل له كما ادّعاه في خبره سُمّي خالقا.\rوالباري تعالى هو الخالق بالحقيقة وحده، لأنّه يُخرج الأشياء من العدم إلى الوجود، وقد ضلّت القدريّة عن هذا الاعتقاد، حتى زعمت أن العبد خالقٌ بالحقيقة، مُخترِعٌ لأعيان الأفعال، مُخرجٌ لها من العدم إلى الوجود، فيا عجباً لهم كيف ذهلوا عن الحقائق العقلية، وأعرضوا عن الأدلّة الشرعية، حتى عن قوله: \"أَمْ جَعَلُوا لِلَّهِ شُرَكَاءَ خَلَقُوا كَخَلْقِهِ فَتَشَابَهَ الْخَلْقُ\r"], [846, "عَلَيْهِمْ قُلِ اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ الْوَاحِدُ الْقَهَّارُ\" (الرعد 16)، فكم في هذه الآية من حُجّة، لو شُرعت لهم فيها مَحَجّةٌ.\rوأمّا الخلق بمعنى التقدير، فقد قال بعض علمائنا: إنه لو كان الخلق بمعنى التقدير لكان كلّ مقدِّر خالقاً، وكل خالقٍ مقدّراً، والأمر بعكس ذلك، لأنّ العرب تقول: قدّرتُ في نفسي شِعراً، ولا تقول: خلقت في نفسي شِعراً، أو تقول: قدّرت الساحةَ والثّوبَ والبناء، ولا تقول في ذلك خلقتُ، فلو كان معنى الخلق معنى التقدير لتصرّف معه في جميع مواضعه، فعُلم أنه قد يكون غير الله مقدّراً ولا يكون خالقاً.\rقال الإمام الحافظ رضي الله عنه: هذا كلامٌ صحيحٌ في الردّ على القدرية الذين يزعمون أن غير الله خالق، ولكن لا نمنعُ من كون الخلق بمعنى التقدير كما ورد في اللغة، ويكون الخالق بمعنى المُقدِّر على علمٍ وتدبيرٍ، وإذا كان قدّر بغير علم كان خارقاً، كقوله تعالى: \"وَخَرَقُوا لَهُ بَنِينَ وَبَنَاتٍ بِغَيْرِ عِلْمٍ\" (الأنعام 100)، والله تعالى خالقٌ مقدِّرٌ، وغيره مقدِّرٌ غير خالقٍ، وكلّ خالق مقدّر، وليس كل مقدّر خالقاً، كالحمد والشكر وشِبههما.\rوأمّا الخلق بمعنى التصوير فقد وقعت الإشارة إليه بقوله: \"يَخْلُقُكُمْ فِي بُطُونِ أُمَّهَاتِكُمْ خَلْقًا مِنْ بَعْدِ خَلْقٍ فِي ظُلُمَاتٍ ثَلاثٍ\"\r"], [847, "(الزمر 6)، فنقلهم من صورة إلى صورة، ومن هيئة إلى هيئة، وقال أيضاً في صفة النطفة: \"مُّخَلَّقَةٍ وَغَيْرِ مُخَلَّقَةٍ\" (الحج 5)، أي مُصوّرة وغير مُصوّرة، وقد يكون الخالق المُصوّر بمعنيين، كقوله تعالى: \"وَلَقَدْ خَلَقْنَاكُمْ ثُمَّ صَوَّرْنَاكُمْ\" (الأعراف 11)، فيكون قوله \"خلقناكم\" إخباراً عن الخروج من العدم إلى الوجود، وقوله: \"صوّرناكم\" إشارة إلى الصورة الباطنة المختصِّ بها الآدميّ دون غيره.\rفثبت أن الخالق على الحقيقة والعموم هو الله وحده، ولذلك نقول في كل ما خلقه أحدثه وأوجده واخترعه، ولا يقال فيمن صدق في خبره: خلقه، ولا فيمن بنى ونجَر خلق بناءه ونجره، فانفرد بذلك الله وحده.\rالمسألة الثانية: في تسميته خالقاً في الأزل\r"]], "pg": [844, 847]}, "561.676": {"x": [[847, "قال علماؤنا: سمّى نفسه تعالى خالقاً في الأزل ثمّ خلق، فكان خالقاً عند وجود الخلق حقيقة، ونُسمّيه خالقاً قبل ذلك مجازاً، على معنى أنه سيخلق، كما قال تعالى: \"أَرَانِي أَعْصِرُ خَمْرًا\"، وكقولهم: حاجٌّ لمن قصد\r"], [848, "الحجّ، فالحقيقة إنما تكون عند وجود الخمر والحجّ، كذلك حقيقة كونه خالقاً؛ إنّما يكون ذلك عند وجود الخلق.\rفإن قيل: أليس كلامه عندكم غير مخلوق لم يزل؟ قلنا: أجل.\rقيل: فقد وصف نفسه بأنه خالقٌ في الأزل، فيجب أن يكون خالقاً فيه ويكون حقيقةً.\rقلنا: إن كان أخبر تعالى عن كونه خالقاً قبل أن يخلق، فإنّ الإخبار عن ذلك حقّ وحقيقةٌ، ووصفُهُ بذلك مجازٌ، كما قال تعالى للملائكة: \"إِنِّي خَالِقٌ بَشَرًا مِّن طِينٍ\" (ص 71)، معناه سأخلق، وهذا غرضٌ لا يتفطّن له إلا لبيبٌ، ومن قصّر عنه، نظره في كتاب المقسط، فإنّه تنكشف له حقيقته، وأقرب مثالٍ فيه الآن يُنبّهك عليه ولا يخرج عن الغرض أن تقول: في قِرابي سَيفٌ قاطعٌ، فقولك حقٌّ وحقيقةٌ، ووصف السيف بالقطع مجازٌ إذ لم يقطع بعد، وساغ ذلك فيه لأنّه بصفة القاطع، فإذا قطع كان وصف القاطع فيه حقيقة.\rفإن قيل: فهذا يُوجب أن يكون لله اسمٌ حادثٌ، وذلك يُجوّز حدوث كلّ اسم له.\r"], [849, "الجواب: أن نقول: إن أردت بالاسم المسمّى فهو غير حادثٍ، وإن أردتم التسمية له والإخبار عنه، فإنّ الأصل في التسمية له والإخبار عنه التّوقيف، وقد ورد به خبر الله فقلناه، وبيّنّا بعد ذلك معناه.\rالمسألة الثالثة: في اختصاص الباري تعالى بالخلق\r"]], "pg": [847, 849]}, "561.677": {"x": [[849, "ذهب جماعةٌ من المبتدعة إلى أن الباري تعالى يخلق الأجسام والجواهر وحدها، وأمّا خلق الأعراض فيشاركه في ذلك العبد، وعند أهل السنّة –ولله عليهم المنّة- أنه خالق كلّ شيء، لا شريك له في ذاته ولا صفاته ولا مخلوقاته، \"هَذَا خَلْقُ اللَّهِ فَأَرُونِي مَاذَا خَلَقَ الَّذِينَ مِن دُونِهِ\" (لقمان 11)، \"وَاللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ\" (الصافات 96)، وقال: \"اللَّهُ خَالِقُ كُلِّ شَيْءٍ\"، وقوله: \"أَمْ جَعَلُوا لِلَّهِ شُرَكَاءَ خَلَقُوا كَخَلْقِهِ فَتَشَابَهَ الْخَلْقُ عَلَيْهِمْ قُلِ اللَّهُ خَالِقُ كُلِّ شَيْءٍ\" (الرعد 16).\rوكيف يصحّ هذا، واسم الخالق أُمّ جميع أسماء الأفعال بعده، وإليه يرجع كلّ اسمٍ يعود إلى صفات الفعل أوّلا، ثمّ يختصّ بعد ذلك كلّ اسمٍ بحسب مُتعلَّقه من المخلوقات، وهذا سرٌّ بديعٌ فيه، فكيف يصحّ أن يكون أصل جميع أسماء أفعاله وتقع المشاركة فيه له.\r"], [850, "الاسم الرابع: الباري\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [849, 850]}, "561.678": {"x": [[850, "ورد به القرآن، قال الله تعالى: \"الْخَالِقُ الْبَارِئُ\" (الحشر 24)، وورد في حديث أبي هريرة المفسّر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [850, 850]}, "561.679": {"x": [[850, "البارئ هو الخالق، يُقال: برأ الله الخلق يبرؤهم بَرْءاً، والبريّة الخلق، فعيلةٌ بمعنى مفعولةٍ، وأصله الهمز، إلّا أنهم اتّفقوا على ترك الهمز، ويقال: أُخذت البريّة –إذا تُرك همزها- من بَرَيتُ القلم إذا قطعته وأصلحته، ويقال: أُخذت البريّة من البَرا، وهو التّراب، ولهذا المعنى صار لهذا اللفظ اختصاصٌ بالحيوان دون السماء والأرض وغيرهما، حتى كان عليٌّ يحلف: والذي فلق الحبّة وبرأ النَّسَمَة.\rالفصل الثالث: في شرحه عقيدة وحقيقة\r"]], "pg": [850, 850]}, "561.680": {"x": [[850, "وفيه ثلاث مسائل:\r"], [851, "المسألة الأولى: في التركيب\r"]], "pg": [850, 851]}, "561.681": {"x": [[851, "أما قول أهل اللغة إن الباري هو الخالق فليس يصحّ على الإطلاق، وإنما يصحّ أن يقال إن الباري هو الخالق في حالةٍ أو على صفةٍ أو لموصوف.\rفأمّا قولنا الباري هو الخالق في حالة، فنعني به الحالة الثانية، فإنه يكون خالقاً غير بارئٍ، ثم يكون بارئاً في قول، أو خالقاً بارئاً، على ما يأتي بيانه إن شاء الله.\rوأمّا الباري على صفةٍ فلأنّ الخالق المقدٍّر على نظامٍ وترتيبٍ المُخرج من العدم إلى الوجود هو الباري بالحقيقة دون غيره.\rوأمّا قولنا لموصوف فلوجهين:\rأحدهما: أن الباري هو الخالق للحيوان، لأنه مأخوذٌ من البَرَا، وهو التّراب، لقوله: \"وَمِنْ آيَاتِهِ أَنْ خَلَقَكُم مِّن تُرَابٍ ثُمَّ إِذَا أَنتُم بَشَرٌ\" (الروم 20).\r"], [852, "الثاني: أن الباري هو الخالق الخلق الحسَنَ المُتقَن، كقوله: \"لَقَدْ خَلَقْنَا الإنْسَانَ فِي أَحْسَنِ تَقْوِيمٍ\"، وقوله: \"وَنَفْسٍ وَمَا سَوَّاهَا\".\rالمسألة الثانية: في الاعتقاد الصحيح\r"]], "pg": [851, 852]}, "561.682": {"x": [[852, "إذا فهمت معنى الباري لغة، وعرفت التركيب المعنويّ الاعتقادي، فالباري تعالى بارئٌ بكل وجه منها، لأنه المقدِّر للمخلوقات قبل خلقها وتدبيرها كما بيّنّا، وعِلم الله سبحانه مُحيطٌ بالمخلوقات قبل وجودها، فكان خَلقها على مُقتضى علمه أولا، ثمّ أنشأها وأبدعها، منها أصولٌ مبتدَأةٌ من غير شيء، ومنها فروعٌ مبنيّة عليها ومخلوقةٌ بحكمه لا عن حاجة، وإلّا فالثاني في جوزا كونه خَلْقاً مستأنفا من غير شيء كالأوّل، والعلم به محيطٌ، والقدرة له متّسعة، فثبت جوازه، وخفيت الحكمة على الخلق في تكون ما يكون منه من شيء قبله.\rالمسألة الثالثة: في مزيد تحقيق يرجع إلى الاشتقاق\r"]], "pg": [852, 852]}, "561.683": {"x": [[852, "يصحّ في الاشتقاق أن يكون الباري من البَرا وهو التراب، ومن بَرَيت القلم إذا سوّيته للعمل المقصود، ولك إذا كان غير محموز، فأما إذا كان مهموزاً فلا يجّ أن يكون مُشتقّاً منهما، وإنما ورد في القرآن مهموزاً من برأ؛ إذا أنشأ\r"], [853, "وأوجد، واتّفق الناس على قراءته مهموزاً، ولم يُسهّله أحد في قوله: الباري، ولا في قوله: \"بارئكم\"، فعلى هذا يصحّ انحصار المعنى في تفسيره في الإنشاء دون التسوية والإصلاح.\rفأمّا الذي ورد منه في السنّة، ونطقت به الأمّة فيصح أن يكون مُسهّلاً، وكذلك في قوله: \"البريئة\"، فإنه قرئ مهموزاً وغير مهموزٍ، فيرجع اشتقاقه إلى ذلك، ويصحّ أن يكون مهموزاً، فيرجع إلى ما ورد في القرآن من همز البارئ وبارئكم، ويصحّ تسهيله، فيعود إلى قراءة من يُسهّل البريّة، ورجوعه إلى الإنشاء في قولنا البارئ أولى في المعنى، لأنه يفيد ما لا يفيده مُسهَّلاً لوجهين:\rأحدهما: أن يكون الخالق المقدِّر والمخترع أيضا، فيكون وصفه بذلك يُفيد مجموع الأمرين له كما بيّنّا، ويكون وصفه بالباري بعد ذلك يفيد المُنشئ لما قدّر وعلم.\rالثاني: أن يكون الخالق المنشئ على العموم لكلّ مخلوق، ويكون الباري المنشئ للحيوان على الخصوص دون غيره، لقول عليّ رضي الله عنه في يمينه: \"والذي فلق الحبة وبرأ النَسَمَة\"، فخصّها دون غيرها\r"], [854, "لقوله برأ معها، وتكون الفائدة في ذكر الاسم الأخصّ –وهو الباري بعد الأعمّ وهو الخالق- التنبيه على ما في الحيوان من بديع الصّنعة وغريب الدلالة.\rوإلى هذا المعنى وقعت الإشارة بقوله: \"وَفِي أَنْفُسِكُمْ أَفَلا تُبْصِرُونَ\" (الذاريات 21)، فنبّه بجميع المخلوقات على الاعتبار بالدلالة على الصانع، وخصّ النفس لما فيها من زيادة الاعتبار ببديع التركيب، وقد قال بعض علمائنا: إنه يجوز أن يكون الخالق البارئ إتْباعاً وتأكيداً، وما قدّمناه أولى، فإنه لا يُصار إلى التأكيد إلا بعد ضِيق المعنى.\r"], [855, "الاسم الخامس: المُصوِّر\rالفصل الأوّل: في مورده\r"]], "pg": [852, 855]}, "561.684": {"x": [[855, "قال تعالى: \"الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ\"، ووردت به السنة في حديث أبي هريرة المفسّر، وأجمعت عليه الأمة.\rالفصل الثالث: في شرحه لغة\r"]], "pg": [855, 855]}, "561.685": {"x": [[855, "نقل علماؤنا فيه أربع عبارات\rالأولى: المصوّر الذي أنشأ خلقه على صور مختلفة وهيئات متغايرة.\rالثانية: هو المُمَثّل، والصورة المثال.\rالثالثة: المُرَكِّب، والصورة التركيب، يقال: صوّره إذا فعله هكذا، وتقول العرب: فلانٌ صيِّرٌ شيِّرٌ، إذا كان ذا صورة وشارة حسنة.\rالرابعة: المُنهي للشيء المخلوق إلى غاية خلقه، كما يقال: صار الأمر إلى كذا أي انتهى إليه، ومنه قوله: \"وإليه المصير\"، وقوله: \"ألا إلى الله تصير الأمور\" (الشورى 53).\r"], [856, "الفصل الثالث: في شرحه عقيدة\r"]], "pg": [855, 856]}, "561.686": {"x": [[856, "فيه خمس مسائل:\rالمسألة الأولى: في التركيب\r"]], "pg": [856, 856]}, "561.687": {"x": [[856, "أما الأقوال التي سردناها قبل عن أهل اللغة فيه متداخلة، عند التحقيق ترجع إلى ثلاثة:\rالأوّل: أن يكون المصوِّر الموجِد على هيئةٍ، وهي التركيب، وهي الصورة؛\rالثاني: أن يكون المصوِّر هو الممثل، والصورة هي المثال.\rالثالث: أن يكون المصوّر هو المُنهي للشيء إلى غايته.\rوالباري تعالى هو المصوّر بهذه المعاني الثلاثة على التمام والكمال، بكل الوجوه وبجميع المعاني.\rأمّا إن قلنا إنّ المصوّر هو الموجِد على صور وهيئات، فهو الباري تعالى، لأنه الخالق أوّلا، وهو العالم المقدّر المدبّر، وهو الباري المنشئ المخترع ثانيا، وهو المصوّر ثالثا، أي المركِّب لما علم على هيئة وصفة، كان\r"], [857, "يجوز تقدير وجود الموجود على غيرها؛ من تفصيلات تقدير وجودها ومحتملاتها، فإنه:\rالأول: لا يخفى على لبيب أن الوجود المطلق غير الوجود على صفة وهيئة، وأن التركيب معنى غير الوجود، كما خلق الأرض قرارا، والسماء بناءً، والجماد والحيوان، والنامي وغير النامي.\rالثاني: أنه خلق آدم، ثم نام نومة فانتزع ضلعا من أضلاعه، فخلق منه حوّاء على نوعه، فكان لها مثالا ونوعا ليسكن إليها، ونبّه على ذلك بقوله: \"هُوَ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا\" (الأعراف 189)، ولو شاء لخلقها معه، ولكنه بدأ بآدم ثم خلقها على مثاله للحكمة التي أشار إليها.\rوأمّا إن قلنا إن الباري هو المصوّر أي المُمثِّل الموجِد على مقال، ففي ذلك فائدة بديعة، واعتقاد عظيم، وتنبيه على القدرة المقترنة بالحكمة غريب، وذلك أن كل فاعل فإنّما يربط صنعته بمثالٍ سابقٍ عليها بزيادة أو نقصان،\r"], [858, "وبمثلٍ أو اختلاف، ولا يُتصوَّر أن يفعل على غير ذلك لقصور علمه وقدرته، ولاحتياجه إلى الآلات الموصلة إلى ما يقصد فعله، والله تعالى فاعل بالوجهين على الطريقين؛ المبدع أوّلا، والممثّل ثانيا، فإنه خلق أصول العالم أوّلا من غير شيء، وإنما أخرجها من حالة العدم إلى حالة الوجود، ولو شاء تعالى أن يجعل فروع العالم كأصوله فتكون مخلوقةً من غير شيء منقولة من حالة العدم إلى صفة الوجود لفعل، ولكنّه بحكمته البالغة ومشيئته النافذة خلق الأصول من غير شيء، ثم ركّب الفروع على الأصول وأوجدها منها.\rفكلّ موجود من فَرع فإنّما يرجع في تمثيله إلى أصله الموجود منه، حتى تغلغل في ذلك بعضهم فقال ما لا يأتباه الشرع ولكنّه يقف دون إدراكه حقيقة العقل، وهو أن الإنسان مخلوق من أصول العالم، وهو على مثاله مفطورٌ، وأنّ العالم عالمان، الأكبر وهو السماوات والأرض وما بينها من كواكب وبحار، وأن الإنسان عالم أصغر، وأنه موجود فيه ما في العالم الأكبر.\rوهذا مما لو أدركنا حقيقته، وحصّلنا كيفيته، ورتّبنا النسب في الإنسان بما في العالم الأكبر حتى ننتهي إلى المطلوب في ذلك، لكان اعتبارا بديعاً، ولكنّا نقصر عنه، فلذلك وقفنا دونه.\r"], [859, "وأما إن قلنا: إن الباري هو المصوّر بمعنى أنه المُنهي للمخلوقات إلى نهايتها فإنه معنىً صحيح في حقّه تعالى مختصّ به، فإنه ابتدأ الخلق، فمنه ما أنهى الوجود فيه نهايته، ومنه ما سيُنهيه، والكلّ بيده، فما أنهى منه فعن قدرة وبحكمة لا عن حاجة، وما أخّر فبحكمة أخرى لا عن مَعجزة، وإليه وقعت الإشارة بقوله تعالى: \"وَإِلَيْهِ الْمَصِيرُ\"، وبقوله: \"وَأَنَّ إِلَى رَبِّكَ الْمُنتَهَى\"، وتكون تسميته تعالى بأنه مُصوّر بهذا المعنى يماثله من أسمائه الحسنى أنه بدئٌ، على ما يرد بيانه إن شاء الله تعالى.\rالمسألة الثانية:\r"]], "pg": [856, 859]}, "561.688": {"x": [[859, "وهي غاية في هذه الأسماء الثلاثة، وهي الخالق البارئ المصوّر.\rاعلموا أن قولنا خالقٌ مأذون في تسمية العبد به بثلاثة أوجه من الأربعة المتقدّمة، ممنوع في وجه منها، وهو كونه خالقاً بمعنى الإيجاد والاختراع، كما أن الباري تعالى يُسمّى بأنه خالق بثلاثة أوجه من الوجوه الأربعة أيضا، ممنوع تسميته بأنه خالق على معنى الاختلاق، لوجوب الصدق في خبره واستحالة الكذب عليه.\rوقد اقتحمت القدرية هذه الشنعاء فسمّت العبد خالقا بمعنى مُخترع، وأوجب ذلك له، وقد بيّنّا فساده في كتب الأصول.\r"], [860, "وأمّا قولنا خالق بمعنى مُقدِّر فجائز وصف العبد به، وكذلك كونه خالقا بمعنى مصوِّر، وفي ذلك تفصيل بديع، وهو أنه رُوي عن النبي صلى الله عليه وسلم أنه قال: \"لعن الله المصوّرين، وقال: إن أصحاب هذه الصور يُعذَّبون يوم القيامة، يقال لهم: أحيوا ما خلقتم\"، والحكمة في ذلك الجزاء على تعاطيهم التمثيل لما وجب التخصيص به لله سبحانه، ولذلك وردت الرخصة في كل ما لا روح فيه؛ من نبات أو جماد، ووقف النهي على ما فيه الروح لحكمة بديعة، وذلك أن كل مخلوق سوى الآدميّ فإنّما له صورة ظاهرة لا باطن لها، والآدميّ خُلق خلقاً بديعاً بأن جُعلت له صورةٌ ظاهرةٌ؛ وهي الخَلق، وصورة باطنة؛ وهي الخُلُق، ومدار الأمر فيه على الصفة الباطنة وهي الخُلُق لوجهين:\rأحدهما: أنّ دوام وجوده بها، حتى إذا فارقته تفكّك تركيبه وتفرّقت أبعاضه، وصار في الوجود أدوَنَ من الجمادات.\rالثاني: أن مدحه وذمّه وثوابه وعقابه إنّما يكون بها وعليها، وهي المعنى البديع والسرّ الغريب الذي تفرّد سبحانه بمعرفة جنسها يقينا، وهي الروح، فإنه اضطرّ الخلق إلى معرفتهم بها؛ وجوداً في ذواتهم، وحجب عنهم\r"], [861, "معرفتها ضرورة؛ تعجيزا وتنبيها، بقوله: \"وَفِي أَنفُسِكُمْ أَفَلَا تُبْصِرُونَ\" (الذاريات 21).\rفإذا تعاطى العبد تصوير ما لا باطن له مُكّن من ذلك رخصة، وإذا تعاطى تصوير ما له صورة باطنة مُنع من ذلك لثلاثة أوجه:\rالأول: ارتباط الصورة الباطنة بالظاهرة.\rالثاني: كونها طريقاً إلى المعجزة الظاهرة على يدي عيسى عليه السلام حين قال: \"وَإِذْ تَخْلُقُ مِنَالطِّينِ كَهَيْئَةِ الطَّيْرِ بِإِذْنِي فَتَنْفُخُ فِيهَا فَتَكُونُ طَيْرًا بِإِذْنِي\" (آل عمران 48).\rالثالث: كونها حِمىً للصورة الباطنة المعجوز عنها، وحكم الحمى حكم المحميّ في الامتناع منه.\rورُخّص فيما عدا الإنسان لوجهين:\rأحدهما: التخفيف من الله عزّ وجلّ على العباد في ترك عموم التضييق عليهم فيما تتعلّق به آمالهم، فهو سبحانه لو شاء لعمّ بحجره، ولكنّه لحكمته البالغة إن منع طريقا أباح آخر إبقاء على النفس المتمنّية.\r"], [862, "الثاني: التفريق بين ما له حرمة وبين ما لا حرمة له، فمنع من تصوير ما له حرمة بباطنه، وهو الآدمي، وعلى هذا نبّه بقوله صلى الله عليه وسلم: \"أحيوا ما خلقتم\"، كأنه يقال له: ما صوّرت ظاهره وأُقدمت عليه صوِّر إن استطعت باطنه، وأُذن في تصوير ما لا حرمة له تنبيهاً على تباين ما بين المنزلتين، وهذه بدائع رأينا أن لا نُخلي هذا الفصل منها.\rالمسألة الرابعة: في ترتيب هذه الأسماء\r"]], "pg": [859, 862]}, "561.689": {"x": [[862, "وهي تترتّب على التفسيرات المتقدمة الثلاثة، على ثلاث مراتب:\rأوّلها: الخالق المُقدّر للأشياء قبل خلقها، الباري المُوجد لما قدّر، المصوّر المظهر لتركيبها وصورها.\rالثانية: أنّه الخالق الموجد، المخترع الباري، المنشئ للنّسم، المصوّر الموجد للصور والهيئات.\r"], [863, "الثالثة: الخالق المخترع، الباري المسوّي لما خلق، المحسن له، المصوّر الجاعل له على هيئات مختلفة، وقد قرأ بعضهم: \"الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ\" بفتح الواو، ليربط الكل ويعلّق الآخر بالأول.\rالمسألة الخامسة: في الألفاظ الواردة في هذا الباب\r"]], "pg": [862, 863]}, "561.690": {"x": [[863, "الألفاظ الواردة في هذا الباب كثيرة أمّهاتها خمسة وعشرون لفظاً:\rالأول والثاني والثالث: الخالق الباري المصوّر.\rالرابع: الفاعل.\rالخامس: الصانع، العامل، الموجد، المنشئ، المكوِّن، المبدع، البديع، المبتدع، المُحدث، البادئ، البديء، المبتدئ، المبدئ، المعيد، الذارئ، الفاطر، الراتق، الفاتق، الجاعل، المصطنع، الفالق.\rوسنتكلم عن كل اسم منها بما حضر في الحال إن شاء الله تعالى.\r"], [864, "الفصل الرابع: في التنزيل\r"]], "pg": [863, 864]}, "561.691": {"x": [[864, "إذا انتهى العبد إلى هذا المقام، وعلم معاني قوله: \"الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ\" تحقق أن للباري تعالى بذلك أحكاما يختصّ بها، أمّهاتها ستّة أحكام.\rالأول: أنه المقدّر الذي لا يُردّ قدره، ولا يُخَطَّا تقديره.\rالثاني: أنه لا يُخرج من العدم إلى الوجود غيره.\rالثالث: أنه لا يُنشيء الحيوان سواه.\rالرابع: أنه لا يُنمي النامي غيره.\rالخامس: أنه يخلق على غير مثال.\rالسادس: أنه لا يُنهي المعاني غايتها إلا هو سبحانه.\rالمنزلة الثانية للعبد:\rوهو أن يراعي نفسه في اعتقاده وعلمه، وله في ذلك خمسة أحوال:\rالأول: أن يعتقد أن الباري تعالى خالق الأعيان والآثار وكلّ شيء، حتى الأعراض، ولا يخرج حادث عن قدرته، فيُريح نفسه من كدّ النصب.\r"], [865, "الثانية: أن لا يطرح عن نفسه ظاهر الشرع في الأمر والنهي، وإن كان الأمر كله لله، فإن العبد لا يخلو عن توجّه الأمر والنهي إليه، وتتطرّق المَحمدة والملامة إليه.\rالثالثة: أن لا يُعجب بنفسه، فإنه مخلوق أوّلا من تراب، وثانية من نطفة، فيحقّ التواضع لمن أوّلخ قَذَر وآخره دَفَر.\rالرابعة: أن يرى عجيب صنع الله كيف خلق الصورة الظاهرة للآدمي، وهي الخلق، فقطع كسبه عنها، فلا حيلة له فيخا، وخلق الصورة الباطنة وطرّق كسب العبد عليها، فتارة تَحسن باختياره وكسبه، وتارة تسور بذلك، وهو تحت إرادة الله ومشيئته، لقوله: \"وَمَا تَشَاءُونَ إِلَّا أَن يَشَاءَ اللَّهُ\".\rالخامسة: أن يرى أن الله حسّن خلق أكثر الخلق وعامّتهم، وقليل من حسّن خُلُقه، فتميّز الآدمي من البهائم بالصورة الباطنة، وهي الخُلُق، وتميّزت البهائم من النبات بمعرفة المنافع والمضرات، وتميّز النبات عن الجماد بالنماء، وأعظم المراتب منزلةً تحسين الخُلق، ولهذا أثنى الله سبحانه على\r"], [866, "نبيّه عليه السلام بها، حتى بلغ بفضله الغاية فيها، فقال: \"وَإِنَّكَ لَعَلى خُلُقٍ عَظِيمٍ\" (القلم 4).\rوأمّا في علمه فأن يعتبر في جميع المخلوقات بصورها وهيئاتها، وكيف تركيبها، وحكمة تصويرها وترتيبها؛ ما بين ظاهر وباطن عجائب لا تُحصى، فإنّ ظاهره مُلبَسٌ بالحواسّ، وفيها أمور من الحكمة عظيمة، وبدائع من الخِلقة كثيرة، كالعين وصفاتها، وكيفية تركيب طبقاتها ونورها، والفم وما فيه من لسان ينطق وأسنان تطحن، واليد وبطشها، والرجل وبسطها، وباطنه مشحونٌ بالغرائب؛ أوّلها القلب، ومن لك بعجائبه، وسائر الأعضاء وما فيها من المنفعة وكيف أعدها الله لتلك الخدمة، فالكبد يستحيل فيها كلّ مطعومٍ وإن اختلفت صفاته دماً على صفة واحدة، وما فيه من ثُفْلٍ وسواد يقذفه إلى الطحال فيقبله منه، وما فيه من رُغوة تقبله المرارة، وما فيه من مائيّة رقيقة تقبله الكلية، حتى يسري الدم إلى العروق صافيا، وتقذف الماء إلى المثانة،\r"], [867, "وما بقي من ثفل قبله المِعى، ثمّ خرج منه سهلا، ولذلك كان صلى الله عليه إذا خرج من الخلاء يقول: \"الحمد لله الذي أخرج عني خبثه، وأبقى فيّ طيّبه\".\rفكان صلى الله عليه وسلم يحمد ربه على ما سخّر له من الخدمة، ويسّر له من المنافع، ويسّر عليه من العسير، تنبيهاً لنا على السنّة، وقضاءً لما سبق من حقّ المنّة.\rفأمّا الفاعل والصانع والعامل، فهي ألفاظٌ حقيقتها تتصرّف إلى من يُخرج الشيء من العدم إلى الوجود، وتنطلق أيضا على المُكتسِب، فإذا وصفنا بذلك ربّنا رجع له الوصف بذلك إلى الحقيقة في الأسماء، وإذا أُضيفت إلى العبد وأُخبر به عنه كما ورد في الشرع وأُذن لنا فيه كقوله: \"وكذلك يفعلون\"، \"ويصنعون\"، \"ويعملون\"، عاد ذلك إلى معنى الكسب، إلا أن يُقيّد بما لا يليق إلا بالله، كقوله تعالى: \"فَعَّالٌ لِمَا يُرِيدُ\" (هود 107)، فعّال لما يشاء، فلا يرجع ذلك إلى إلى الله وحده لانفراده بذلك المعنى.\r"], [868, "وأما الموجد فهو عبارة عن مُخرج الشيء من العدم إلى الوجود حقيقة، ويعبَّر به عن المكتسب مجازا، ووصف المنشئ مثله، وكذلك المكوّن والمخترع، إلّا أني أتوقف في المكوِّن على قول علمائنا، ولا أرى فيه إلّا الانفراد لله وحده، لقوله تعالى: \"إِنَّمَا قَوْلُنَا لِشَيْءٍ إِذَا أَرَدْنَاهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ\" (النحل 40)، فما جاء في معرض التعظيم والمدح لله سبحانه لم يجُز أن يخبر به عنه.\rوأما المُبدع والمبتدع والبديع فهو الذي أنشأ على غير مثال، وأنا من قول المبتدع على نظر، وقد يأتي بديع بمعنى مبدع.\rوتحقيقه أن العرب تقول: بدع الشيء يبدعه إذا ابتدأه، فهو بديع، فعيلٌ بمعنى مفعول، والبِدْع المبتدأ الأول، ومنه قوله تعالى: \"قُلْ مَا كُنْتُ بِدْعًا مِنَ الرُّسُلِ\" (الأحقاف 9)، ويقال: شيء بديع أي معجِب، كأنه مفتَتَح لم يوجَد مثله في طريق الحُسن، ويقال أيضا: أبدع فهو بديع أي مبدع، فعيل بمعنى مُفعل، ويقال: ابتدع أتى ببدعة، ويستعمل في المحمود والمذموم، لكن جاء قوله: \"بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ\" (البقرة 117) مضافاً إليها، فوجب أن يكون بمعنى مُبدعها ومفتتح وجودها على غير مثالها، ولم يأت في وصفها بديع مطلقا، فيكون معناه معنى شيء بديع، واستنكفنا في وصفه بمبتدع لاشتراكه في الخير والشر، مع أنه لم يرد به أمر، والله أعلم.\r"], [869, "وأما المُحدِث فهو بمعنى الفاعل، ومثله المُبدي، وهو المُظهِر، والمعيد وهو الذي يردّ الشيء بعد عدمه ويرجعه بعد ذهابه.\rوأما المبدئ فهو بمعنى المنشئ، والذارئ بمعنى الخالق، يقال: ذرأ الله الخلق كله، \"وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِّنَ الْجِنِّ وَالْإِنسِ\" (الأعراف 179)، ومنه الذريّة.\rوأما الفاطر فهو بمعنى الخالق عند قوم، وعندي أنه من الفَطر، وهو الشقّ، وهو قوله: \"أَوَلَمْ يَرَ الَّذِينَ كَفَرُوآ أَنَّ السَّمَاوَاتِ وَالأَرْضَ كَانَتَا رَتْقًا فَفَتَقْنَاهُمَا\" (الأنبياء 30)، والرتق الضمّ والجمع، والفتق الفرق.\rوقال صلى الله عليه وسلم: \"كل مولود يولد على الفطر\"، أي الشقّ، وقال ابن عبّاس: ما كنت اعلم ما معنى قوله: \"فاطر السماوات\" (الأنعام 14) حتى\r"], [870, "اختصم إليّ أعرابيان في بئر، فقال: أنا فطرتها، ومنه فِطر الصائم أي ما يشقّه أولا.\rوأمّا الجاعل فله ثلاث معانٍ:\rالأول: المُحدث، كقوله: \"وَجَعَلَ الظُّلُمَاتِ وَالنُّورَ\" (الأنعام 1).\rالثاني: التسمية، كقوله: \"جَعَلْنَاهُ قُرْآنًا\" (فصلت 44)، وقوله: \"وَجَعَلُوا الْمَلَائِكَةَ الَّذِينَ هُمْ عِبَادُ الرَّحْمَنِ إِنَاثًا\" (الزخرف 19).\rالثالث: بمعنى النقل والتحويل، كقولك: جعلت قوبي في الصندوق، ويوصف بذلك القديم والمحدَث.\rوأمّا المصطنع فهو المفتعل من صنع، كالمقتدر من قدر، وقد تقدّم بيانه، وقد يقال لصاحب الحرفة صانع لما يظهر من الأشياء على يديه.\rومن هذه الأسماء أصول ومنها فروع، وسنأخذ في بيان الأصول منها على التفصيل المتقدّم.\r"], [871, "شرح المُبدئ (المُعيد)\rالفصل الأول: في مورده وشرحه لغة\r"]], "pg": [864, 871]}, "561.692": {"x": [[871, "فيه أربعة أبنية: المبدئ، والبادئ، والبديء، والمتبدئ، ولم يرد القرآن بشيء منها، لكن ورد بالفعل، قال الله تعالى: \"وَهُوَ الَّذِي يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ\" (الروم 27) وقال: \"إِنَّهُ هُوَ يُبْدِئُ وَيُعِيدُ\" (البروج 13)، فجمع في القرآن بين اللغتين؛ وتصريف فعله: بدأ الله الخلق وأبدأهم، فهو بادئهم ومبدئهم، كلّه مهموز، وورد في حديث أبي هريرة من طريق عبد العزيز بن الحُصين البادي بالدّال، فإن كان مهموزاً فقد تقدّم بيان معناه،\r"], [872, "وإن تركت الهمز كان البادي والمُبدي من قولك بدا إذا ظهر، فيكون معناه الظاهر المُظهر.\rالفصل الثاني: في شرحه حقيقة وعقدا\r"]], "pg": [871, 872]}, "561.693": {"x": [[872, "إذا قلنا إنّ المبدئ بالهمز من أبدأ، فهو بمعنى أنشأ وخلق، فهو سبحانه الخالق الذي يوجِد \"ليس\" حتّى يصير \"أَيْشْ\"، وهو بمعنى المكوّن.\rوإذا قلنا: إنه البادي بغير همز فقد تقدّم بيان الظاهر.\rوإذا قلنا: إنّ المبدي بغير همز هو المظهر، فهو سبحانه مظهر الخفيّات؛ بإخراجٍ من العدم إلى الوجود، وبإخراج من الغيبة إلى الشهود، وهذه عقيدة ينفرد بها أهل السنة.\r"], [873, "فإنّ القدرية وإخوانها قالوا: إن المعدوم في حال عدمه شيء، عين، ذات، جوهر إن كان جوهرا، أو عرَض إن عرَضاً، فبأيّ شيء تعلّقت أو أي معنىً للموجود أرادت؟ وإنّما غلِظوا في ذلك لأنّهم نظروا إلى أن الباري تعالى عالم قبل أن يخلق الخلق، مدبّر مقدّر، فتعلّق العلم والتدبير والتقدير في الأزل بالمخلوقات على أعيانها وأوصافها وذواتها، جواهرها وأعراضها، ثم كان الموجود على حسب العلم والتقدير، ولم يتحقّق لهم تعلّق العلم بالمعدوم المطلق إلا على تقدير الوجود، ولم يُفرّقوا بين الوجود المحقَّق والوجود المقدّر.\rالفصل الثالث: شرح المُعيد\r"]], "pg": [872, 873]}, "561.694": {"x": [[873, "المعيد في اللغة المُفعل، من أعاد يُعيد، ومعناه الموجد الموجود المسبوق بمثله والعقيدة فيه أن الوجود إذا لم يكن مسبوقا بمثله\r"], [874, "قيل ابتداء، وإذا كان مسبوقاً بمثله كان إعادة، فكيف إذا كان معاداً بعينه.\rوقد تكلّمنا على الإعادة بما يكشف حقيقتها في كتب الأصول، وأنّه يجوز أن يعيد الجواهر والأعراض والأوقات حتى يكون الوجود الثاني هو الأول بعينه وعرضه ووقته، ولا يختلف في وجه ولا على حال، ولكن ورد الخير بالإعادة في بعض الوجود لقوله تعالى: \"يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَاوَاتُ\" (إبراهيم 48)، ولو كان الوجود بعينه وصفته في وقته لما كان غيراً له، وقد قيل: ليس للأوقات بدل، وذلك مبيّنٌ في كتب الأصول.\rنكتة:\rأسماء الله تعالى على قسمين من وجه، وذلك أنه قد يكونان من معنيين متقابلين، وقد يكونان غير متقابلين، فإن كانا من معنيين متقابلين\r"], [875, "كقولنا: المبدئ المعيد، المحيي المميت، المعزّ المذل، القابض الباسط، فقد قال بعض علمائنا: إنّه يحسن في مثل هذا أن يقرن بين الاسمين ولا يُفردا؛ ليكون أنبأ عن القدرة، وأدلّ على الحكمة، فلذلك قرنّا بينهما، وسنسلك هذه السبيل في بقية الأسماء المتقابلة إن شاء الله.\rالفصل الرابع: في التنزيل فيهما\r"]], "pg": [873, 875]}, "561.695": {"x": [[875, "إذا تحقّق العبد معنى الإبداء والإعادة علم أن للباري أحكاما ستة:\rالأول: أنه يبدئ الخلق على غير مثال، ثم يعيدهم على ذلك المثال قدرة وحكمة لا حاجة.\rالثاني: يبدأ بالتفضّل على العباد وبالنعم، وقد يعيدها ويكررها، وقد يقطعها بحسب تحصينها بالشكر وإدامتها بالذكر أو التقصير فيه، كما قال تعالى: \"لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ وَلَئِن كَفَرْتُمْ إِنَّ عَذَابِي لَشَدِيدٌ\" (إبراهيم 7)، وكما روي عن عائشة أنها قالت: \"قيّدوا النّعم بالشكر، فقلّ ما نفرت عن قوم فعادت إليهم\".\r"], [876, "الثالث: أنه بدأ الخلق من آدم من تراب، ثم يعيدهم إلى التراب بالموت، فهي الإعادة الأولى، ثم يخرجهم من التراب، فهي الإعادة الثانية.\rالرابع: أنه بدأ بني آدم من ماء دافق، ثم أعادهم إلى التراب، ثم يخرجهم منه، فوقعت الإعادة في العين لا في الصفة.\rالخامس: أنه بدأهم من بطون الأمّهات فرادى، ثم يعيدهم في الحشر فرادى، كما قال: \"وَلَقَدْ جِئْتُمُونَا فُرَادَى كَمَا خَلَقْنَاكُمْ أَوَّلَ مَرَّةٍ\" (الأنعام 94).\rالسادس: أنه يحيي النطفة والعلقة والمضغة، ثم يعيد أن يحيي التراب، وجملة الأمر أنّ كلّ شيء منه بدأ وإليه يعود، حقيقة ومجازاً.\rالمنزلة الثانية للعبد:\rإذا تحقّق المرء للمُبدئ المعيد هذه الأحكام تعلّق بفضله فيها وتوسّل إليه بها، ألم تسمعوا قول الشاعر:\rوأعطى ثمّ أعطى ثمّ أعطى *** وأعطى ثم عُدتُ له فزادا\rمراراً لا أعود إليه إلا *** تبسّم ضاحكاً وثنى الوسادا\r"], [877, "فالله أحقّ بذلك وأولى، وقد قال بعض الناس: ليس للأوقات بدل، وأنّ من فاته وقت فليس له إليه وصول.\rوفي الإسرائيليات: أنّ داود بكى حتّى غفر الله له، ثم بكى بعد ذلك، فقيل له: ما يُبكيك؟ فقال: على قوات صفاء ذلك الوقت، فأوحى الله إليه: هيهات يا داود، ليس إلى ذلك سبيل.\rوهذا فصيل يحتاج إلى تدقيق بالغ فنقول:\rمن فاته وقت بخلوّه عن الطاعة ثم ندم عليه فإن ندمه ينسحب على الزمان الأول، فإن كان معمورا بمعصية محاها، وإن كان فارغاً عن شيء كُتب له حسنة، والندم عمارةٌ للزمان الثاني، فلو صادف الزمان الماضي معمورا بالحسنات لكان حسنة بنفسه، وإذا صادفه كما قدّمناه انسحب عليه، ولكن لا يكون كمن عَمَرَه بالحسنات أبدا، ولذلك قال تعالى: \"لَا يَسْتَوِي مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ الْفَتْحِ وَقَاتَلَ أُولَئِكَ أَعْظَمُ دَرَجَةً مِّنَ الَّذِينَ أَنفَقُوا مِن بَعْدُ وَقَاتَلُوا\" (الحديد 10)، وقال: \"وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنصَارِ\"\r"], [878, "(التوبة 100)، ومن جاء بعد ذلك فقد ندم، ولم يُلحقه النّدم بمن اكتسب الفضل المتقدِّم، وبالله التوفيق والعون، لا ربّ غيره.\r"], [879, "شرح فاطر السماوات والأرض\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [875, 879]}, "561.696": {"x": [[879, "هو اسم ورد به القرآن، قال الله تعالى: \"فَاطِرِ السَّمَاوَاتِ وَالْأَرْضِ\" (الأنعام 14)، ووردت به السنة، كان النبي عليه السلام يقول إذا هبّ: \"اللهم فاطر السموات والأرض، عالم الغيب والشهادة، أنت تحكم بين عبادك فيما كانوا فيه يختلفون، اهدني لما اختُلف فيه من الحق، إنّك تهدي من تشاء إلى صراطٍ مستقيم\"، وورد في حديث أبي هريرة المفسَّر من طريق عبد العزيز، ولم يذكره علماؤنا، ولا عذر لهم في تركه، لأنهم إن اعتذروا بعذر المعتزلة في أنه ورد مضافا فقد ذكروا العلّام والنور، وإنما وردا مضافين.\r"], [880, "الفصل الثاني: في شرحه لغة\r"]], "pg": [879, 880]}, "561.697": {"x": [[880, "اختلفت عباراتهم في ذلك:\rفمنهم من قال: إنّ الفاطر هو الخالق للشيء المبدئ له، يقال: فطر الله الخلق يَفطُرُهم خلقهم وبدأهم، ويقال للخليقة الفطرة، والفطرة ما فطر الله عليه من المعرفة به، وروي أن ابن عبّاس قال: ما كنت أعلم معنى فاطر حتى اختصم إلي أعرابيّان في بئر فقال أحدهما: أنا فطرتها، يعني أنا شققت أرضها عنها.\rومنهم من قال الفَطر: الشقّ، وجمعه فطور، وفي التنزيل: \"هَلْ تَرَى مِنْ فُطُورٍ\" (الملك 3)، وفطر ناب البعير شقّ لثته وبرز، ومنه أفطر الصائم، وقال عبيد الله الفقيه:\rشققتِ القلب ثمّ ذررتِ فيه *** هواك فليم فالتأم الفطور\rالفصل الثالث: في حقيقته وعقده\r"]], "pg": [880, 880]}, "561.698": {"x": [[880, "فيه ثلاث مسائل:\r"], [881, "المسألة الأولى: في حقيقته اللفظة\r"]], "pg": [880, 881]}, "561.699": {"x": [[881, "هذه اللفظة مشكلة على الأحبار، ألا ترى توقّف ابن عبّاس فيها، والذي عندي أنّ فطر بمعنى شقّ في كلّ معنى، وإليه يرجع كل مثال تقدّم مشكلاً، كقولهم: فطر الله الخلق، معناه أنّهم كانوا مضغة فشقّهم بالهيئة والأخلاق، وإليه يرجع \"كل مولود يولد على الفطرة\"، أي على الوجه الذي خلقه الله عليه وكتب أن يلحقه، ويُجري ذلك على يدي أبويه ويظهر بسببهما، وهو معنى قوله عزّ وجلّ: \"أَوَلَمْ يَرَ الَّذِينَ كَفَرُوآ أَنَّ السَّمَاوَاتِ وَالأَرْضَ كَانَتَا رَتْقًا فَفَتَقْنَاهُمَا\"، معناه كانتا مصمتتين لا فرجة فيهما ففتقناهما بوجهين:\rأحدهما: بأن جعلنا الدّخان وهو واحد سبع سماوات، وجعلنا الزبد وهو واحد سبع أرضين، فانشقّ الإثنان عن أربعة عشر جِرماً، وشققناهما بعد ذلك، هذه بالمطر والمعارج، وهذه بالنبات والوالج والمعارف، واختلاف الأقضية والمقادير والأرزاق.\r"], [882, "المسألة الثانية: في العقد\r"]], "pg": [881, 882]}, "561.700": {"x": [[882, "لا يخفى على ذي لبّ، بعد معرفة الحقيقة، أنّ هذا الاسم من أجلّ الأسماء الأفعاليّة قدرا، وأن حقّه ألّا يُغفل عنه، فهو بهذه الرتبة التي بينّا، فالباري تعالى هو الذي رتق السماوات والأرض، حتى لا ترى فيها من فطور، وهو الذي فطرها حتى لا يُرى فيها رتقا، فسبحان مُصرِّف المقادير ومدبّر الأمور.\rالمسألة الثالثة: في وصفه بالفاتق\r"]], "pg": [882, 882]}, "561.701": {"x": [[882, "وقد جاء به قوله تعالى: \"أَوَلَمْ يَرَ الَّذِينَ كَفَرُوآ أَنَّ السَّمَاوَاتِ وَالأَرْضَ كَانَتَا رَتْقًا فَفَتَقْنَاهُمَا\"، والفتق في اللغة هو تفريق المجتمِع، لكن غير مباين بالجملة ولا مَحوزٍ بطرف، وبهذه الدقيقة فارق الشقّ والفطر، وفتقه للسّماء بالمطر، والأرض بالنبات، وبه تصحّ اللغة ويطّرد الاشتقاق ويستقيم التأويل للآية.\r"], [883, "الاسم التاسع والعشرون والموفّي ثلاثين: المحيي ويقابله المميت:\rفيهما أربعة فصول:\rالفصل الأول: في موردهما\r"]], "pg": [882, 883]}, "561.702": {"x": [[883, "أما المحيي فقد ورد به القرآن، قال تعالى: \"إِنَّ الَّذِي أَحْيَاهَا لَمُحْيِي الْمَوْتَى\" (فصلت 39)، وأما المميت فلم يرد به القرآن اسماً، ولكن ورد به فعلاً، قال تعالى: \"الَّذِي يُحْيِي وَيُمِيتُ\" (المؤمنون 80)، وورد في حديث أبي هريرة المفسّر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [883, 883]}, "561.703": {"x": [[883, "أما الحياة والموت فمعلومان، وهما ينقسمان إلى الحقيقة والمجاز، أمّا الحقيقة في ذلك فمعلومة في الحيّ والميّت، وأمّا المجاز فيتنوّع أنواعاً كثيرةً؛ منها إحياء القلوب بنور الحكمة، فهي مجلّة لقمان: \"إن الله يحي القلوب بنور\r"], [884, "الحكمة كما يحيي الأرض الميّتة بوابل السماء\"، ومنها إحياء الأرض بأنواع النبات، كقوله تعالى: \"كَيْفَ يُحْيِي الْأَرْضَ بَعْدَ مَوْتِهَا\" (الروم 50)، وإحياء الشعراء بالغراسة، كقوله عليه السلام: \"من أحيا أرضا ميّتة فهي له\"، وإحياء الديار بعمارة أهلها، كما قال الشاعر:\rوإنّما الناس نفوس الديار\rوإماتتها كلها بضدّ ذلك.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [883, 884]}, "561.704": {"x": [[884, "فنقول: إنّ قولنا فيه إنّه يحيي، إنما يعود إلى إيجاد الحياة التي كان الحيّ بها حيّاً، فإذا كانت الصفة التي هي شرطٌ في وجود العلم والقدرة والإرادة في الجوهر، كان الإحياء حقيقةً، والحيّ أيضا حيّ حقيقة، والموت والمواتيّة\r"], [885, "بمعنىً واحد وحقيقة واحدة، وإنما يختلفان في الإطلاق، وهو أن المواتيّة عبارة عن صفة في جسم لم يتقدّم فيه وجود حياة، ويُعبَّر بالموت عن تلك الصفة إذا تقدّمَتها في الجسم حياةٌ، وليس من شرط الحياة وجود البِنية والبِلّة والرّطوبة كما توهّم المبتدعة، بل كل جوهر خلقه الله فلا بدّ من أن تكون فيه حياةٌ أو ضدّها من المواتيّة أو الموت، وعادة الله وإن جرت بخلق الحياة في الجسم الرّطب ذي الهيئة فيجوز خلقه لها في اليابس المُصمَت.\rألا ترى أنّ الجذع حنّ للنبي عليه السلام، وأنّ على فراقه مع بقاء الجذعية وعدم الرطوبة واللحميّة في الإطلاق تشبيهاً بما تقدّم.\r"], [886, "وإذا وصفنا إحياء القلوب بنور الحكمة وإحياء الأرض بالنبات ونحوه كان مجازا، وكان حقيقةً في نفسه ومن جنسه، ولولا أنّ الباري تعالى خلق الحياة والموت ما كان مُحيياً مميتاً، فإنّ المحييَ المميت خالق الموت والحياة، لا ما ظنّه النمرود وإخوانه من القدريّة، حيث حاجّه إبراهيم الخليل عليه السلام: \"رَبِّيَ الَّذِي يُحْيِي وَيُمِيتُ\" (البقرة 257)، فقال له الكافر: \"أَنَا أُحْيِي وَأُمِيتُ\"، وعمَد إلى رجل مسجون على الموت فأطلقه، وإلى حيّ فقتله، وقال: ها أنا قد أحييت وأمَتّ.\rوقد أبطل في هذا القول، فإنه لم يخلق حياة ولا موتا، وإنّما اكتسب ما يكتسبه غيره من المخلوقين، من تناوُل القتل والمنّة في العفو، وأعرض عن الدليل كدحاً في وجه الحجّة، وتلبيساً على العامّة، فعدل له الخليل إلى الأمر الذي لا يتعلّق به كسب، وهو تصريف الشمس ما بين مشرقٍ ومغرب، فبُهت في قوله وانقطعت حجّته.\r"], [887, "الفصل الرابع: في التنزيل\r"]], "pg": [884, 887]}, "561.705": {"x": [[887, "إذا عرفت المحيي المميت معنى ولغة، وعرفت عقيدتهما، فللباري تعالى في ذلك أحد عشر حكما:\rالأول: إحياؤه لآدم حين خلقه من تراب، ولا خلاف فيه بين أهل الشرع.\rالثاني: إحياؤه لذرّيته حين استخرجهم من صلبه كهيئة الذر، فقبض فيهم قبضتين، وأشهدهم على أنفسهم بالتوحيد.\rالثالث: إحياؤه للخلق في الأرحام، وليس في ذلك خلاف بين العقلاء، وكذلك كلّ حيوان من الملائكة والجنّ والبهائم والحشرات، هو خالق الحياة فيهم، وهذه حياة المشاهدة.\rالرابع: إحياؤه للمكلّفين في القبر، وسؤالهم حسب ما تظاهرت به الأخبار، ولا خلاف فيه بين أهل السنّة.\rالخامس: إحياؤه المكلّفين في الحشر، زلا يؤمن به إلا الموحّد؛\rالسادس: إحياء الشهداء، كما قال: \"وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا بَلْ أَحْيَاءٌ\" (آل عمران 169)، وقد قال بعضهم: إنّه إحياء ذكر لا إحياء حقيقة، وهذا باطل بقوله: \"يُرْزَقُونَ فَرِحِينَ بِمَا آتَاهُمُ اللَّهُ مِنْ فَضْلِهِ\"، وقوله: \"يَسْتَبْشِرُون\"، وهذا كله صفات الحقيقة لا المجاز.\r"], [888, "السابع: إحياؤه البهائم للقصاص، كما روي في الأثر: يُقتص من الشاة القرناء للشاة الجمّاء.\rالثامن: إحياؤه الأرض بالمطر.\rالتاسع: إحياؤه القلوب بنور الإيمان، وليس ذلك إلا له عند أهل السنة، قال تعالى: \"وَمَنْ كَانَ مَيْتًا فَأَحْيَيْنَاهُ وَجَعَلْنَا لَهُ نُورًا يَمْشِي بِهِ\" (الأنعام 122).\rالعاشر: إحياء القلوب الميّتة بالهمّ بالسّرور والفرح، والهمّ موتٌ في اللغة، قال الشاعر:\rليس من مات فاستراح بميْت *** إنّما الميْت ميّت الأحياء\rالحادي عشر: إحياؤه ذكر الصالحين، كما فعل بإبراهيم عليه السلام، قال تعالى: \"وَاجْعَل لِّي لِسَانَ صِدْقٍ فِي الْآخِرِينَ\" (الشعراء 84).\r"], [889, "المنزلة الثانية للعبد:\rوله في ذلك ثلاثة أحكام:\rالأول: إحياء قلبه بالإيمان، وجوارحه بالطاعة، والسعي في إبقاء ذكره، فإنه حياته الباقية وعمره الآخر، وقد أحسن بعض المتأخرين حين قال:\rذِكر الفتى عمره الثاني وحاجته *** ما قاته وفضول العيش أشغالُ\rتكملة:\rوقد قال بعض علمائنا: إنه تعالى:\r"], [890, "المُبقي: وهو الاسم الحادي والثلاثون\rوالمُفني: وهو الثاني والثلاثون\rفأما المبقي فهو فاعل البقاء لما يبقى، والذي يبقى هو الجواهر دون الأعراض، وقول الناس: أبقى الله لفلانٍ حياته وصحّته توسُّعٌ، ومعناه: خلق أمثالها، وأنه لم يفعل ما يضادّ ذلك فينفيه، وسمّي ذلك إبقاءً.\rوأمّا المُفني فهو المُعدم، والفناء هو العدم، وذلك عندنا بأن لا يخلق له بقاءً، وقال القلانسيّ من علمائنا: بأنه يخلق فيها فناء، وقد تُسمّى مفارقة الشيء للشيء فناء، كما يقال: فنيت النفقة وفني الزّاد، بمعنى فارق صاحبه أو فارق وعاءه، والله أعلم.\r"], [891, "الاسم الثالث والثلاثون: الباعث\rوفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [887, 891]}, "561.706": {"x": [[891, "ورد به القرآن فعلا، قال تعالى: \"ثُمَّ بَعَثْنَاكُمْ\" (البقرة 55)، و \"هُوَ الَّذِي بَعَثَ فِي الْأُمِّيِّينَ\" (الجمعة 2)، وورد في حديث أبي هريرة المفسّر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [891, 891]}, "561.707": {"x": [[891, "جاء في اللغة على ثلاثة معانٍ:\rالباعث المثير، بعث الشيء من مكانه إذا أثاره، ومنه بعث الموتى، وبه سمّي يوم القيام يوم البعث.\rالثاني: بعث الرسل، كما قال تعالى: \"هُوَ الَّذِي بَعَثَ فِي الْأُمِّيِّينَ رَسُولًا مِّنْهُمْ\".\rالثالث: البعث التحريض على الشيء، يقال: بعثتُ فلانا على الشيء إذا حرّضته عليه.\r"], [892, "الفصل الثالث: في شرحه حقيقة\r"]], "pg": [891, 892]}, "561.708": {"x": [[892, "وفيه مسألتان:\rالمسألة الأولى:\r"]], "pg": [892, 892]}, "561.709": {"x": [[892, "اعلموا أن حقيقة البعث تحريك الشيء بعد سكونه في إزعاج واستعجال، وإليه يرجع استعمال ما تقدّم، فالباري تعالى هو الذي يحرّك الموتى ويُظهرهم، وهو الذي حرّك الرسل لدعاء الخلق وأظهرهم، وهو الذي حرّك عباده إلى الطاعة، وهو الذي بعث عبادا له على بني إسرائيل، وهو الذي يبعث الكسير وينعشه، فعاد جميع ما بيّنّاه إلى الإظهار والتحريك، لكن سبب ذلك يختلف.\rالمسألة الثانية:\r"]], "pg": [892, 892]}, "561.710": {"x": [[892, "ظنّ بعض الناس أن الباعث من صفات الكلام، مأخوذ من قولك: بعث فلاناً على كذا، إذا حرّضه عليه، وذلك يكون بالكلام، وهذا ممّا قد أشرنا إلى الجواب عنه، وحقّقنا أن البعث من صفات الفعل، وأنه التحريك والإظهار، وشرحنا أن سبب ذلك يختلف، ومن أسبابه في بعض المواضع الكلام، فيجوز فيما بيّنّا أن يُسمّى القول المسبِّب\r"], [893, "للتحريك والإظهار بعثاً باسم التحريك والإظهار، ولكن يمتنع تسمية الباري تعالى به لوجهين:\rأحدهما: أن الحقيقة في أسمائه وأوصافه إذا وجدنا إليها سبيلاً لم نعدل إلى المجاز.\rوالثاني: أن هذا اسمٌ لم يرد بصيغة الأسماء، وإنّما أخذناه من الأفعال، فكيف يُحمل على وجهٍ من المجاز والحقيقة فيه ممكنة متأصّلة، والمجاز بعيد غير مقولٍ؟\rالفصل الرابع: في التنزيل\r"]], "pg": [892, 893]}, "561.711": {"x": [[893, "للباري تعالى المنزلة العليا في هذا الاسم، فإنه الفاعل لكل شيء؛ من إنشاء وحركة وسكون، وعطاء ومنع، وجلب ودفع.\rوعلى العبد في منزلته السفلى: أن يبعث قلبه على اليقين، ولسانه على الذكر، وجوارحه على العمل.\r"], [894, "الاسم الرابع والثلاثون: الجامع\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [893, 894]}, "561.712": {"x": [[894, "ورد به القرآن اسماً وفعلاً، قال الله تعالى: \"إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لا رَيْبَ فِيهِ\" (آل عمران 9)، وورد في حديث أبي هريرة المفسّر المعدَّد، وأجمعت عليه الأمّة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [894, 894]}, "561.713": {"x": [[894, "الجمع في اللغة عبارة عن ضمّ شيء إلى شيء، وهو التأليف، وقد يكون في الأجسام، كقوله تعالى: \"إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لا رَيْبَ فِيهِ\"، وقوله: \"إِنَّ اللَّهَ جَامِعُ الْمُنَافِقِينَ وَالْكَافِرِينَ فِي جَهَنَّمَ جَمِيعًا\" (النساء 140)، و \"يَوْمَ يَجْمَعُ اللَّهُ الرُّسُلَ\" (المائدة 109)، وجمع المعاني كقوله: \"فكما\r"], [895, "قال\"، وقد يكون جمع المعاني مع الأجسام، كما يكون بين الروح والجسد بعد افتراقهما، ومنه إجماع الأمة.\rالفصل الثالث: في حقيقته\r"]], "pg": [894, 895]}, "561.714": {"x": [[895, "فيه مسألتان:\rالمسألة الأولى:\r"]], "pg": [895, 895]}, "561.715": {"x": [[895, "اعلموا –وفّقكم الله- أنّ الأمّة أجمعت على أن الباري جامع، ولكن لم يُوَفّ هذا الاسم حقّه إلا جماعة السنّة، فإنهم قالوا: إن الباري هو الجامع وحده على الإطلاق ولكلّ مجتمِع، وقالت المبتدعة: ليس جامعا على الإطلاق إلا لجمع الروج والجسد، وسائر ذلك يفعله الخلق دونه أو معه، وقد مهّدْنا أنّ الله هو الخالق وحده، فلا جمع ولا تفريق إلا من الله، هو جمع المخلوقات في الخلق، والناس في الموت، والمبعث، والجنّة والنار، وهو مُفرّقهم في الصفات والأحوال، والمنازل والأعمال.\r"], [896, "المسألة الثانية:\r"]], "pg": [895, 896]}, "561.716": {"x": [[896, "قال بعض علمائنا: معنى وصفنا له تعالى بأنه جامعٌ نعني به جمع الفضائل، ووجوه الجلال، وأنواع الشرف والكمال، وهذا باطل من القول والتأويل، لأنّ ذلك كله في الباري موجود، وهو به موصوف، لكن لا يتعلّق به فعل، ولا هو صادر عن قدرة، وإنّما كانت كذلك لأنها من غير موجِبٍ ولا تعليل، لكن لَعَمر الله هو جامع ذلك لغيره، واهبٌ لمن شاء من عباده ما شاء منه.\rالفصل الرابع: في التنزيل\r"]], "pg": [896, 896]}, "561.717": {"x": [[896, "المنزلة العليا للرب قد تقدّمت في الحقيقة، وهو أنه المتوحّد بالجمع والتفريق.\rالمنزلة السفلى للعبد:\rفي ثلاثة أشياء:\rالأول: أن يعتقد ذلك لربّه\rالثاني: أن يجمع خصال الخير لنفسه.\rالثالث: أن يُفرّق خصال الشرع عنه.\r"], [897, "الاسم الخامس والثلاثون والسادس والثلاثون: المعزّ ومقابله المُذلّ.\rفي ذلك أربعة فصول:\rالفصل الأول: في موردهما\r"]], "pg": [896, 897]}, "561.718": {"x": [[897, "لم يرد بهما القرآن اسماً، ولكن ورد بهما فعلا، قال تعالى: \"وَتُعِزُّ مَن تَشَاءُ وَتُذِلُّ مَن تَشَاءُ\" (آل عمران 26)، ووردت بهما السنّة في حديث أبي هريرة مفسّرا، حين عدّد الأسماء فقال: المعزّ المذلّ، وأجمعت عليهما الأمة.\rالفصل الثاني: في شرحهما لغة\r"]], "pg": [897, 897]}, "561.719": {"x": [[897, "المُعزّ المُفعل من عزّ، وقد بيّنّا أن عزّ يتصرّف على أربعة معانٍ، فكذلك أعزّ يتصرّف بها، لأنّ أفعل من فعل مبنيّ عليه ومُركّب منه، والمُذلّ في مقابلة المُعزّ، كما أن الذلّ في مقابلة العزّة.\r"], [898, "الفصل الثالث: في شرحهما عقيدة\r"]], "pg": [897, 898]}, "561.720": {"x": [[898, "اعلم أن العزيز من صفات الذات، إلا إذا قلنا إنه بمعنى مُعزّ، فإنّه يكون حينئذٍ من صفات الأفعال، إذ المعنى أنه يُعزّ غيره بما يفعل فيه، وقد قال بعض علمائنا: إنّه يكون معزّاً من صفات الذات بمعنى أنه يُخبر عن عزّته، فيكون أعزّ نفسه، بمعنى أخبر عن عزّته، وهذا مما استبعده بعض علمائنا، وفيه نظرٌ دقيقٌ، ولكن رأينا أنّ الغالب فيه أنه من صفات الأفعال فحملناه عليه.\rالفصل الرابع: في التنزيل\r"]], "pg": [898, 898]}, "561.721": {"x": [[898, "إذا قلنا إن الباري تعالى مُعزّ بمعنى أنه يعزّ من يشاء كما أخبر فإنّ ذلك يكون بوجوه كثيرة، نذكر منها ما حضر في هذه العُجالة، وهي عشرةٌ:\rالأول: أنه يُعزّ أولياءه بمدحه لهم، كما قال تعالى: \"يُحِبُّهُمْ وَيُحِبُّونَهُ\" (المائدة 54)، ويُذلّ أعداءه بإظهار ذمّهم، كما قال: \"تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ\" (المسد 1) فمدح وذمّ.\r"], [899, "الثاني: أنه يعزّهم بمعنى أنه يخلق لهم توفيق الطاعة ويحرسهم عن المعاصي، فلا عزّ إلا عزّ طاعته، وأذلّ العاصين بخلانه حتى واقعوا المعصية.\rالثالث: عزّه لأوليائه بما منحهم من الغنائم، كما قال صلى الله عليه وسلم: \"جُعل رزقي تحت ظلّ رمحي، وجُعلتِ الذلّة والصَّغار على من خالف أمري\".\rالرابع: عزّه لأوليائه بالرؤية بإدناء المنزلة، وكشف الحجاب، وفتح مُبهمِ الأبواب، ويُذلّ أعداءه بإسدال الحجاب وغلق الباب.\rالخامس: عزّه بالمال، وإذلاله بالفقر.\rالسادس: إعزازه بالجاه، وإذلاله بالخمول.\rالسابع: إعزازه بالجمال، وإذلاله بالدّمامة.\rوهذه الاوجه الثلاثة تختلف الحال فيهم باختلاف الحكم، فإن كان المال والجاه والجمال عَوناً على الطاعة فهو عزّ، وإن كان عونا على المعصية\r"], [900, "فهو ابتلاء وذلّ، كما قال صلى الله عليه وسلم: \"إن الله لا ينظر إلى صوركم وأموالكم، وإنما ينظر إلى قلوبكم وأعمالكم\"، وقد قال الفقراء عن الأغنياء: \"يا رسول الله، ذهب أهل الدثور بالأجور\" الحديث، إلى أن قال: \"ذلك فضل الله يؤتيه من يشاء\".\rفإذا كان المال للاستغناء عن الأمثال والأشكال، والزيادة في تجارة الأعمال، وكان الجاه لدفع المظالم وحفظ المحارم، وكان الجمال في الباطن والظاهر، فقد كملت النعم بين الخلق، وقادت العبد إلى مجاورة الحق.\rالثامن: عزّ الزّهّاد، بما يخلق في قلوبهم من عزوف الخواطر عن الدنيا، كما يُروى عن حارثة أنه قال له عليه السلام: \"كيف أصبحت يا حارثة؟ قال: مؤمنٌ حقّاً، قال: إن لكل حقّ حقيقة، فما حقيقة إيمانك؟ قال: عزفت نفسي عن الدنيا، فاستوى عندي حجرها وذهبها\" الحديث.\r"], [901, "وهذا هو العزّ في الحقيقة، فإن الطّمع هو الذلّ، بل الحَتْف، أما ترى العُقاب عزيزة في مطارها، حتى إذا لاح لها طمعٌ وقعت في الشَّرّكة.\rالتاسع: أنه يُعزّ العابدين بالإخلاص، كما يُذلّ أهل الرياء.\rوجملة الحال –وإن كان هذا لا ينحصر كما قدّمنا- اعتقاد العبد أن كلّ عزّ وذُلّ في دينٍ أو دنيا فهو إليه، ومنه يظهر، وإليه يرجع، فاعتمِدْ هذه الجملة لتعلم بُطلان مذهب المبتدعة في اعتقادهم أن المؤمن عَزَّ نفسه بالإيمان.\rالعاشر: نقله لأوليائه إلى دار المُقامة في مهاد الكرامة بحُسن التلقّي، كما قال: \"يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً\" (الفجر 30 - 31)، وذُلُّهُ لأعدائه في تلك الحالة كما قال: \"فَتَنتُمْ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَارْتَبْتُمْ وَغَرَّتْكُمُ الْأَمَانِيُّ حَتَّى جَاءَ أَمْرُ اللَّهِ وَغَرَّكُم بِاللَّهِ الْغَرُورُ\" (الحديد 13)، وقد عرفتم عزّه وذلّه لأوليائه وأعدائه.\rالمنزلة الثانية للعبد:\rأن يطلب العزّ بالطاعة، ويحذر الذلّ بالمعصية.\r"], [902, "الاسم السابع والثلاثون: مُخزي الكافرين\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [898, 902]}, "561.722": {"x": [[902, "ورد به القرآن، قال الله تعالى: \"وَأَنَّ اللَّهَ مُخْزِي الْكَافِرِينَ\" (التوبة 2).\rالفصل الثاني: في شرحه لغة\r"]], "pg": [902, 902]}, "561.723": {"x": [[902, "يقال: خزي الرجل، وقع في بليّة وشهرة يذلّ بذلك، وأخزاه الله فعل به ذلك، وقد يقال: \"أخزاه الله\"، إذا أتى بما يُستحسن، معناه: وقاية العين، وفي الحديث: \"إنّ الحرم لا يُعيذ عاصياً ولا فارّاً بدمٍ ولا فارّاً بخزية\"،\r"], [903, "يعني بليّة، وقد قال تعالى: \"لَهُمْ فِي الدُّنْيَا خِزْيٌ\"، يعني القتل أو الجزية أو الرق.\rالفصل الثالث: في حقيقته\r"]], "pg": [902, 903]}, "561.724": {"x": [[903, "الخزي البلاء المكروه، ويقال لما يُستحسن: أخزاه الله، أي وقاه العين، كأنه لا يُستحسن، لأنّ العين إنّما يثور ضرره من الاستحسان، فيقال هذا نفوراً من الاستحسان قصد أن يقطع العين، والباري مُخزي الكافرين أي يُنزل بهم البلاء المكروه، من الأقسام التي تقدّم ذكرها.\rفإن قيل: فقد نرى الكافر ملكاً؟\rعنه جوابان: أنه خاصٌّ في بعض دون بعض.\r"], [904, "الثاني: أنه خاصّ في الأزمان، والمراد به زمان الخشر، فالخزي فيه يعمّهم.\rالفصل الرابع: في التنزيل\r"]], "pg": [903, 904]}, "561.725": {"x": [[904, "المنزلة العليا للرب:\rإنّ الكافر في خزيه وإن كان ملكاً، والمؤمن في عزّه وإن كان رقيقاً.\rالمنزلة الثانية للعبد:\rأن يعلم أن الخزي إنما هو مكروه يكون عن معصية، ولذلك قال صلى الله عليه وسلم لوفد عبد القيس: مرحباً بالوفد، غير خزايا ولا ندامى.\r"], [905, "الاسم الثامن والثلاثون: الغفّار\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [904, 905]}, "561.726": {"x": [[905, "ورد به القرآن، قال تعالى: \"أَلا هُوَ الْعَزِيزُ الْغَفَّارُ\" (الزمر 5)، وقال: \"نَبِّئْ عِبَادِي أَنِّي أَنَا الْغَفُورُ الرَّحِيمُ\" (الحجر 49)، وقال: \"غَافِرِ الذَّنبِ وَقَابِلِ التَّوْبِ\" (غافر 3)، وقال: \"وَأَنْتَ خَيْرُ الْغَافِرِينَ\" (الأعراف 155)، وورد الغفّار في حديث أبي هريرة المفسّر المعدّد، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [905, 905]}, "561.727": {"x": [[905, "اعلموا أن الغافر فاعل من غفر، وغفور فعول منه، وغفّار فعّال، وتصريف فعله: غفر يغفر غفْراً وغفراناً، وهو كيفما تصرّف يرجع إلى السَّتر، ويقال لجُنّة الرأس مِغْفَر، وغَفْر الثوب زِئبره الذي يستر سداه، ويقال: جاء\r"], [906, "القوم جمّاء غفيراً، أي جماعتهم، وغفارة الرأس رقعة عليه ساترة له، وقيل: هو مأخوذ من الغفر، نبْتٌ تُداوى به الجراح إذا ذُرّ عليها دملها وأبرأها.\rالفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [905, 906]}, "561.728": {"x": [[906, "وفيه أربعة مسائل:\rالمسألة الأولى:\r"]], "pg": [906, 906]}, "561.729": {"x": [[906, "لا خلاف بين المتشرّعين أنّ الباري كما أنه غفّار للذنوب ستّارٌ للعيوب، فهو شديد العقاب، وبذلك تمّت أوصاف الجلال، وصحّ الوجود على الكمال، وذلك من صفات الأفعال، ولذلك كانت العرب تتمدّح بجمع الصفتين وحيازة الخصلتين، قال الشاعر:\r"], [907, "ليثٌ تُهاب الأُسد صولته *** جمع العِقاب وأحسن الغَفْرا\rالمسألة الثانية:\r"]], "pg": [906, 907]}, "561.730": {"x": [[907, "إذا قلنا إن المغفرة من الغفر، وهو السَّتر، فمغفرة الله تعالى للعباد ذنوبهم ستره بفضله عليهم وبرحمته، لا باستحقاقهم ذلك منه، لمن شاء منهم إذا شاء كما شاء، وقد كشف البيان في ذلك بقوله: \"إِنَّ اللَّهَ لاَ يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَن يَشَاء\" (النساء 47).\rوإذا قلنا إنه من النبت الذي يُداوى به الجرح، فمغفرته سبحانه لهم ما وهبهم من الندم، وخَلَق لهم من الأسف على ما فرط من المعاصي والذنوب، حتى ذهب به ما كان بالمعاصي من الألم، وكلّ ذلك من صفات الأفعال.\rالمسألة الثالثة: في ترتيب هذه الأسماء الثلاثة\r"]], "pg": [907, 907]}, "561.731": {"x": [[907, "في ذلك ثلاثة أقوال:\rأحدها: أنّ غافراً من فاعل غفر، وأنّ قولنا غفور للمبالغة إذا تكرّر، وأنّ الغفّار أشد مبالغة منه.\rالثاني: أنّ قوله غافر بسَتره في الدنيا، وأن غفوراً بسَتره في\r"], [908, "الآخرة، وأنّ غفّاراً بستره عن أعين الخلائق وعن أعين المذنبين، ليكون لكل لفظ فائدةٌ يختصّ بها.\rالثالث: أن غافراً فاعل من غفر، وأن غفّارا فعّالٌ للكثرة، وأن غفوراً فعولٌ، إنباءً عن جودة الفعل وكماله وشموله.\rوالقول الأول هو الصحيح، وما بعده تحكّم لا تشهد له لغة ولا حقيقة.\rالمسألة الرابعة: في كونه خير الغافرين\r"]], "pg": [907, 908]}, "561.732": {"x": [[908, "وذلك بأنه يمنّ بالمغفرة، ويقبل المعذرة، ويُتبع كلّ ذنب بكلّ قبول عند الرجوع منه.\rالفصل الرابع في التنزيل\r"]], "pg": [908, 908]}, "561.733": {"x": [[908, "اعلموا أن هذا الاسم ممّا انفرد به أهل السنّة، وحُجب عنه المبتدعة من القدرية وإخوتهم، وزعموا أن الله لا يغفر إلا لمن تبا، وأمّا من مات على المعصية فهو مخلَّد في النار، وقد رددنا عليهم في كتب الأصول.\r"], [909, "ومن اطمأن قلبه من أهل السنة بهذا الاسم وتحقّقه في أوصاف الإله تعالى وأسمائه علم أن للباري تعالى في ذلك وجوهاً من المغفرة لا تُحصى، الحاضر منها في الخاطر سبعة:\rالأول: أنه يغفر الذنوب للعباد في الدنيا بإمهالهم بالعقاب على المعصية، وقد كان من حقّهم أن يُعاجَلوا بالعقوبة لعظيم ما يأتون به من المعاصي.\rالثاني: أنه يغفر الذنوب بمعنى أنه يستر على العصاة عصيانهم، مع علمه بهم، فلم يشهرهم ولا فضحهم؛\rالثالث: أنه يغفر لمن تاب، وذلك بإجماع، كما قال تعالى: \"وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ\" (طه 80).\rالرابع: أنه يغفر لمن استغفر، كما قال: \"ثُمَّ يَسْتَغْفِرِ اللَّهَ يَجِدِ اللَّهَ غَفُورًا رَحِيمًا\" (النساء 109).\rالخامس: سَتره العورة القبيحة وإظهاره الوجه الجميل، وذلك مغفرةٌ، فإن من عصى وسُترت عورته فقد غُفر له، ألا ترى أن آدم عليه السلام لمّا عصى بدت منه السوءة.\r"], [910, "السادس: سَتره للقذَر والنجاسة في باطن البدن، وإظهار الجلد واللون الحسن، فلم يفضح ابن آدم بأن أظهر له ما فيه من أقذار.\rالسابع: ستره ما في ابن آدم من أحقاد وسوء اعتقاد.\rالمنزلة السفلى للعبد:\rإذا تحقّق العبد وصف المغفرة للربّ سبحانه تعيّن عليه أمران:\rأحدهما: أن يغفر لغيره، كما قال: \"أَلَا تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ\" (النور 22).\rالثاني: أن يستر عورته، لقوله عليه السلام: \"من ستر على مسلم عورته ستر الله عليه عورته في الدنيا\".\r"], [911, "الاسم التاسع والثلاثون: العفوّ\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [908, 911]}, "561.734": {"x": [[911, "ورد به القرآن، قال تعالى: \"إِنَّ اللَّهَ لَعَفُوٌّ غَفُورٌ\"، وورد في حديث أبي هريرة المفسّر معدّدا، وأجمعت عليه الأمّة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [911, 911]}, "561.735": {"x": [[911, "اعلموا –وفّقكم الله- أن العرب تُطلق العفو على ستّة معانٍ:\rالاوّل: عفا الشيء يعفو إذا درس، غير متعدٍّ.\rالثاني: عفت الريح الرسم إذا محته، متعدّيا، واسم الفاعل من ذلك عافٍ، والكثير عفوٌّ.\rالثالث: أن العفو هو البذل، كما قال تعالى: \"فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ\" (البقرة 177) أي بُذل.\r"], [912, "الرابع: عفا الشيء كثُر، تقول العرب: عفا الشعَر يعفو إذا كثر.\rالخامس: عفا سأل، والعافي هو السائل.\rالسادس: عفا يعفو إذا سمح وأسقط، ومنه قوله عليه السلام: \"عفوتُ لكم عن صدقة الخيل والرقيق\".\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [911, 912]}, "561.736": {"x": [[912, "فيه مسألتان:\rالمسألة الأولى: في تركيب المعنى الاعتقادي على اللغوي\r"]], "pg": [912, 912]}, "561.737": {"x": [[912, "إذا عرفتم معاني العفو في اللغة فالباري تعالى عفوٌّ ببعض معانيه:\rفإنه إذا كان العفو من عَفَت أي درستْ، فلا اسم منه للباري لاستحالة ذلك فيه.\rوإذا قلنا إنه من عفت الريح الرسم، فهو تعالى يمحو الذنوب حتى كأنّها لم تكن، ولا سيما إن وهب التوبة.\rوإن كان العفو بمعنى البذل، فهو يبذل التوبة والثواب مع وجود الذنب، ويدخل في باب الوهّاب والمعطي.\r"], [913, "وإذا كان بمعنى كثُر أو سأل، لم يصحّ وصف الباري بشيء منه.\rوإذا كان بمعنى سمح وأسقط، فالباري سمح في حقوقه، وأسقط كثيراً منها عن عباده.\rوإنّما لم يصحّ وصف الباري تعالى بمعنى العفو الأوّل لاستحالة العدم عليه، ولا بمعنى الكثرة لأنه لا يتكثّر بشيء، ولا بمعنى السؤال لأنّه الغنيّ.\rالمسألة الثانية: في تحقيق هذا الاسم على مذاهب أهل السنة\r"]], "pg": [912, 913]}, "561.738": {"x": [[913, "اعلموا –نوّر الله بصائركم- أن القدرية وإخوانها لا يرون لكون الله تعالى عفوّاً معنًى، لأنّ المذنبين على ثلاثة أقسام؛ إمّا كافر، وإمّا عاصٍ بالكبائر، وإمّا عاصٍ بالصغائر.\rفأمّا الكافر ففي النار بالإجماع، لا يعلق به عفوٌ ولا مغفرة.\rوأما العاصي بالكبائر فهو عندهم كالكافر.\r"], [914, "وأمّا العاصي في الصغائر فهو عندهم في الجنة قطعاً، لا يجوز أن يُعذَّب، فأين عفوُ الله ومغفرته؟\rالفصل الرابع: في التنزيل\r"]], "pg": [913, 914]}, "561.739": {"x": [[914, "إذا تحقّق العبد أن الباري عفوّ بهذه المعاني، وتحقّق أنّ إليه منتهى العفو والمغفرة، علم أنّ للباري سبحانه من ذلك أحكاما تُشارِك أحكام كونه غفوراً:\rالأول: أنه يعفو ويصفح ذنب من تاب بلا خلاف.\rالثاني: أنه يمحو ذنب من ثقُلت موازينه، ولا خلاف فيه أيضا، فإنّ من وُضعت حسناته في كفّة الميزان، ووُضعت سيّئته في الكفّة الأخرى، فثقلت كفّة الحسنات لا يرى نارا أبدا، وهو مغفورٌ له قطعا.\rالثالث: من جاء بالكبائر فالعفو عنه جائز، ولم يرد خبر صحيح بالقطع على مغفرتها لأحد.\r"], [915, "المنزلة الثانية للعبد:\rإذا علم العبد ذلك من وصْف ربّه فقد نُدب إلى أن يتمثّله في نفسه، فمن اعتذر إليه تعيّن عليه قبول عذره، قال سبحانه: \"وَأَن تَعْفُوا أَقْرَبُ لِلتَّقْوَى\" (البقرة 235)، ومن كان من معارفه ظاهر الخير لديه سمح له في عثرته.\rفلستُ بمُستَبْقٍ أخاً لا تلُمُّهُ *** على شعَثٍ أيِّ الرجال المهذَّب\rوإن كان من أصحابه سيّئاته لديه ظاهرة فهو بالخيار فيه.\r"], [916, "الاسم الموفّي أربعين والحادي والأربعون والثاني والأربعون: القهّار والقاهر والغالب\rفيه أربعة فصول:\rالفصل الأول: في موردها\r"]], "pg": [914, 916]}, "561.740": {"x": [[916, "ورد بها القرآن، قال تعالى: \"هُوَ اللَّهُ الْوَاحِدُ الْقَهَّارُ\" (الرعد 18)، وقال: \"وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ\" (الأنعام 19)، وقال: \"وَاللَّهُ غَالِبٌ عَلَى أَمْرِهِ\" (يوسف 21)، ووردت بها السنّة في حديث أبي هريرة المفسَّر، وكلّها بمعنًى واحد، لكن القهّار ورد مُطلقاً مقطوعاً، والقاهر والغالب وردا مقرونين بحروف الخفض.\rالفصل الثاني في شرحهما لغة\r"]], "pg": [916, 916]}, "561.741": {"x": [[916, "القهر والغلبة في اللغة متقاربان أو هما بمعنىً واحد، وذلك عبارة عن منع الغير من مُراده بإنفاذ مراد المانع، فيكون ما أراد القاهر وكرهه المقهور، وقد\r"], [917, "قيل: إن الكَهْر في معناه، ومن أمثالهم: نهره فلمّا أبى كهره، المراد: نهاه أشدّ النهي، فلمّا أبى غلبه على مراده.\rالفصل الثالث: في شرحه عقيدة وحقيقة\r"]], "pg": [916, 917]}, "561.742": {"x": [[917, "فيه ستّ مسائل:\rالمسألة الأولى: في تحقيقه\r"]], "pg": [917, 917]}, "561.743": {"x": [[917, "إذا عرفتم معنى ذلك لغة، فالباري تعالى هو القهّار لأهل السماوات والأرض، أمّا لأهل السماوات فبالتسخير، وأما لأهل الأرض فبالعبد والتذليل، يقصم ظهور الجبابرة، ويذلّ رقاب الأكاسرة، ويقطع الآمال بالحافرة، ويتمنّى المرء أن يولد له فلا يولد له، وألّا يشيب فيشيب، ويريد أن يعزّ فيذلّ، ويستغني فيفتقر بقهرٍ من الله، وغلبةٍ تصدّه عن مراده، وتصرفه عن آماله، وذلك من آيات كمال القاهر الغالب، ونقص المقهور المغلوب، وفعَل ذلك فكان قاهراً، وكرّره فكان قهّارا بكثرته.\rالمسألة الثانية: في تخصيص هذا الاسم بأهل السنّة\r"]], "pg": [917, 917]}, "561.744": {"x": [[917, "اعلموا –وفّقكم الله- أن أهل السنّة مضت على هذا الاعتقاد كما سردناه من تحقيقه، وأفسدت القدرية والمعتزلة معنى هذا الوصف، فزعمت أن الله يكره أن يُعصَى فيُعصى، ويُحبّ أن يطاع فلا يُطاع، تعالى الله عن ذلك.\r"], [918, "ولا يخفى على ذي بصير أن كونه قهّارا من موجب الإلهية ومقتضى الوحدانية، لأنّه لو شاء فلم يكن، وأراد لم يَبلُغ، لَمَا كان بالغاً أمره، ولا قاهراً لعباده، وقد نبّه على دقيقة هذا المعنى بقوله: \" إِذًا لَّذَهَبَ كُلُّ إِلَهٍ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَى بَعْضٍ\" (المؤمنون 92).\rالمسألة الثالثة: في تخصيص قوله: \" وَهُوَ الْقَاهِرُ فَوْقَ عِ"]], "pg": [917, 918]}, "561.745": {"x": [[918, "بَادِهِ\"\rقال علماؤنا: هو إشارة إلى جهة لا يمكن دفع ما يأتي منها من العذاب والمكروه، وهي فوق، فإنّ ما يأتي يَمنةً أو يَسرةً تُمكن الحيلة فيه أو تعاطيها غالباً، وما يأتي من جهة فوق أو تحت لا تُمكن فيه حيلةٌ ولا تعاطيها، ولذلك يُروى في الصحيح أنه لما نزل قوله: \"قُلْ هُوَ الْقَادِرُ عَلَى أَنْ يَبْعَثَ عَلَيْكُمْ عَذَابًا مِنْ فَوْقِكُمْ\" (الأنعام 66)، قال عليه السلام: أعوذ بوجهك، فلمّا قال: أو من تحت أرجلكم، قال عليه السلام: أعوذ بوجهك، فلما سمع قوله: أو يُلبسكم شيعاً ويذيق بعضكم بأس بعض، قال: هذان أهون وأيسر\"، والحكمة فيه أنه إذا قهرهم من هذه الجهة وكانت بيده وإليه فله القهر في غيرها ممّا هو دونها، تنبيهاً من طريق الأَولى.\r"], [919, "المسألة الرابعة: في قوله: \" وَاللَّهُ غَالِبٌ عَلَى أَمْرِهِ"]], "pg": [918, 919]}, "561.746": {"x": [[919, "\"\rوقد ثبت أنّ الأمر ينطلق على معنيين:\rأحدهما: قول القائل: افعل، من أقسام الكلام.\rالثاني: الأمر بمعنى الفعل والشأن، كما قال تعالى: \" وَمَا أَمْرُ فِرْعَوْنَ بِرَشِيدٍ\" (هود 97)؛ وهذا القسم هو المراد ها هنا.\rالمعنى –الله أعلم-: الله غالبٌ على شأنه وفعله الذي يريد إيجاده وإنفاذه، لا مردّ لأمره، ولا مُعقّب لحكمه.\rالمسألة الخامسة: هل القهر صفةٌ قائمةٌ بذاته أم هو صفة فعل؟\r"]], "pg": [919, 919]}, "561.747": {"x": [[919, "اختلف العلماء هل القهر صفة قائمة بذاته أم هو صفة فعل لا يعود إلى الذات منه حكمٌ؟\rفظنّ قوم منهم أنه صفة ذاتٍ، وإنّما أشكل ذلك عليهم لكون القهر لا يكون إلا من القادر، والقدرة صفة الذات، فكذلك القهر، وهذا لا يصحّ، لما قدّمناه من أنه معتبرٌ بالغلبة، وإكمال المراد ومنع الغير من مراده، وذلك لا يكون إلا فعلا.\rالمسألة السادسة: حكم هذه الصفة في الخلق\r"]], "pg": [919, 919]}, "561.748": {"x": [[919, "إذا ثبت أنه صفة فعلٍ، فمن حكمه تقدّم المنازعة من الخلق، فإذا وقعت المعارضة منهم والمنازعة لأمر الباري فإنّه غالبٌ على أمره، وهو\r"], [920, "القاهر فوق عباده، يقصم ظهور الجبابرة، ويذلّ رقاب القياصرة، ويخلع لبوس الأكاسرة.\rومن تمام القهر والغلبة أن يتولّى ذلك تعالى في أعظم الجبّارين وأقواهم، بأضعف المخلوقات وأخضعهم، كما يروى أنه فعل بالنُّمرود –لعنه الله- حين عارض الخليل صلى الله عليه، فانتقم منه بأضعف المخلوقات؛ وهي بعوضة عرجاء.\rالفصل الرابع: في التنزيل\r"]], "pg": [919, 920]}, "561.749": {"x": [[920, "المنزلة العليا للربّ:\rله فيها أحد عشر حكما:\rالأول: أنه قهر الخلق بالإيجاد والاختراع، فقد كانوا عدماً ثمّ أخرجهم إلى الوجود، كما قال تعالى: \"هَلْ أَتَى عَلَى الْإِنسَانِ حِينٌ مِّنَ الدَّهْرِ لَمْ يَكُن شَيْئًا مَّذْكُورًا\" (الإنسان 1)، فلمّا سمعه عمر قال: ليته لم يكن.\rالثاني: أنه قهرهم بالصفات، فمنهم الحسن والقبيح، والأحمر والأسود، والجهوريّ والصحِل، فلم يستطيعوا لخلقه ردّاً، كما قال تعالى: \"وَمِنْ آَيَاتِهِ خَلْقُ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافُ أَلْسِنَتِكُمْ وَأَلْوَانِكُمْ\" (الروم 21).\r"], [921, "الثالث: أنه قهرهم بالحالات، فمنهم الصحيح والكسير، والغني والفقير، كما قال تعالى: \"أَهُمْ يَقْسِمُونَ رَحْمَةَ رَبِّكَ نَحْنُ قَسَمْنَا بَيْنَهُمْ مَعِيشَتَهُمْ فِي الْحَيَاةِ الدُّنْيَا\" (الزخرف 31).\rالرابع: أنه قهرهم بالهدى والضلال، كما قال سبحانه: \"مَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُ وَلِيًّا مُّرْشِدًا\" (الكهف 17)، وهذا حكمٌ يختصّ به أهل السنة.\rالخامس: أنه قهرهم بتعذّر الآمال، فيريد المرء أن يؤتى مُناه ويأبى الله إلّا ما أراد.\rالسادس: أنه قهرهم بالولاية والعزل، فيُولّي قوماً ويعزل آخرين، ويُديل من دولةٍ بدولةٍ، حسب ما اقتضت الحكمة وجرت به السنّة، فبينما المرء مسرور بولايته، مُغتبط بمنزلته، إذا بالتوقيع قد نزل من السماء بعزلته، وبينما الخامل في مذلّته، وتحت خمل عزّته، إذا بالمنشور قد نزل بولايته، الكلّ يشتغل بتدبيره، والقدر يضحك من حسابه وتقديره، حتّى يأتي ميعاد الصدق، فـ\"هُنَالِكَ الْوَلايَةُ لِلَّهِ الْحَقِّ\" (الكهف 44).\rالسابع: أنه قهر الخلق بالموت، وهذا حكمٌ تشترك فيه الخاصّة والعامّة، حتى جاءت الرواية: بأن مَلَكَ الموت إذا تولّى الله قبض نفسه بعد\r"], [922, "موت الخلائق، يقول: وعزّتك، لو علمت من سكرات الموت ما أعلم ما قبضتُ نفس مؤمن، ووردت الرواية بأنه لا تُقبض نفس نبيّ حتى يُخيَّر.\rولقد جاء ملك الموت إلى موسى عليه السلام ليقبض نفسه من غير تخيير فصكّه موسى صكّة، فأذهب عينه اليُمنى، فرجع إلى الله تعالى وقال: أرسلتني إلى عبد لا يريد الموت، فردّ الله إليه عينه، وقال له: ارجع إليه وقل له: يضع يده على متن ثورٍ، فما وقعت عليه يده فله بكلّ شعرة حسنة، فلمّا جاءه بذلك وقال له، قال موسى: ثم ماذا؟ قال: ثم الموت، قال له: فالآن، ولكن أدْنني من الأرض المقدّسة، فدنا منها، فقبض نفسه هنالك، قال عليه السلام: ولو كنت عنده لأريتكم قبره عند الكثيب الأعفر\".\r"], [923, "الثامن: أنه قهر الخلق بالبعث والنشور، وهذا حكمٌ يختصّ بمعرفته أهل التوحيد.\rالتاسع: أنه قهر الكافر بأن يُمشيه على وجهه إلى المحشر.\rالعاشر: أنه قهر الخلق بالجواز على الصراط، فمنهم الناجي، ومنهم المخدوش المُرسَل، ومنهم المُكردس في النار.\rالحادي عشر: أنه قهرهم بكشف السرائر في حالتين:\rإحداهما: في الدنيا، فإنه ما من عبد يُضمر خيراً إلّا أظهره الله عليه، وأبرز سيماه، أو اعتقد شرّاً إلّا ألبسه الله رداءه، قال النبي صلى الله عليه وسلم: من أسرّ سريرةً ألبسه الله رداءها.\rالحالة الأخرى: في الدار الأخرى، قال تعالى: \"يَوْمَ تُبْلَى السَّرَائِرُ\" (الطارق 9)، فلا تبقى مُخبّأة إلا نشرها، ولا باطنة إلا أظهرها.\rالمنزلة السفلى للعبد:\rبأن يقهر نفسه على غلبة شهواته، وإلّا هلك في جميع حالاته.\r"], [924, "الاسم الثالث والأربعون والرابع والأربعون: شديد العقاب سريع الحساب\rوفيهما أربعة فصول:\rالفصل الأول: في موردهما\r"]], "pg": [920, 924]}, "561.750": {"x": [[924, "ورد بهما القرآن، قال الله تعالى: \"شَدِيدُ الْعِقَابِ\" (غافر 2)، وقال: \"سَرِيعُ الْحِسَابِ\" (البقرة 200)، وأجمعت الأمّة عليهما.\rالفصل الثاني: في شرحهما لغة\r"]], "pg": [924, 924]}, "561.751": {"x": [[924, "وفيهما ثلاثة مسائل:\rالمسألة الأولى: في معنى العقاب\r"]], "pg": [924, 924]}, "561.752": {"x": [[924, "العقاب في اللغة مصدر عاقبه بذنبه معاقبةً وعقاباً، أخذه بجزاء الذنب وبعقِبِه، والاسم العقوبة، ويقال: أعقبه على ما صنع أي جازاه به.\r"], [925, "المسألة الثانية: في الشدّة\r"]], "pg": [924, 925]}, "561.753": {"x": [[925, "الشدّ في لسان العرب عبارة عن مضاعفة الربط، واستُعمل في زيادة القوّة في ذاتٍ على غيرها، والمراد به في حقّ الباري تعالى مضاعفة العقاب على شخص بالإضافة إلى غيره.\rالمسألة الثالثة: في السرعة\r"]], "pg": [925, 925]}, "561.754": {"x": [[925, "السرعة عبارة عن سبق شيء لشيء في معنى أو في معنيين متقاربين.\rالفصل الثالث: الحقيقة\r"]], "pg": [925, 925]}, "561.755": {"x": [[925, "وفيه خمس مسائل:\rالمسألة الأولى:\r"]], "pg": [925, 925]}, "561.756": {"x": [[925, "حقيقة \"ع ق ب\" معنى جاء بعد آخر، فكلّ ثانٍ تالي الأوّل يُعبَّر عنه بهذا البناء، لكن يختلف تصريف الحركات عليه والمصادر بحسب اختلاف المعاني قصداً من الواضع إلى التعريف.\rالمسألة الثانية:\r"]], "pg": [925, 925]}, "561.757": {"x": [[925, "عقاب الباري تعالى للخلق ما يكون من جزاء على فعل المذموم، وذلك على وجهين:\r"], [926, "أحدهما: في الدنيا، وذلك في حالتين:\rأحدهما: في الإنعام إذا كان استدراجاً.\rوالثاني: بالألم وذهاب الأموال وتعذّر الآمال، حتى رُوي عن بعض العارفين أنه قال: إنّي لأعرف ذنبي في سوء خُلُق غلامي ودابّتي.\rوالثاني: في الآخرة عند قبض الروح، وفي القبر، وكُرب الموقف، وروعات المبعث، إلى غير ذلك من الشدائد.\rالمسألة الثالثة:\r"]], "pg": [925, 926]}, "561.758": {"x": [[926, "إذا فهمتم معنى الشدّة والمضاعفة، فلا يصحّ أن تكون مضاعفةً من الباري على مقدار ما يُستحقّ من الذنب، فإنّ ذلك وإن كان سائغاً في العقل جائزاً في حكم الربّ بحقّ المِلك، فإنّ الخبر قد منع من ذلك بقوله: \"مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا\" (الأنعام 161)، وقوله في السيئة: \"فَلا يُجْزَى إِلا مِثْلَهَا\" (الأنعام 161).\rفإن قيل: فقد قال الله تعالى: \"يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ\" (الفرقان 69)، وقال في نساء النبيّ عليه السلام: \"مَنْ يَأْتِ مِنْكُنَّ بِفَاحِشَةٍ مُبَيِّنَةٍ يُضَاعَفْ لَهَا الْعَذَابُ ضِعْفَيْنِ\" (الأحزاب 30).\r"], [927, "الجواب: أنّا نقول: إنّما مضاعفة العذاب ها هنا على مقدار مضاعفة السيئات، بخلاف الحسنات، وأنّ مضاعفتها أكثر من مقدارها، على ما بيّنّاه في كتاب المقسِط والمُشكلين.\rفإن قيل: فالكافر يعصي في الدنيا خمسي عاماً فيُخلّد في النار إلى غير أمد، وذلك مضاعفة ظاهرة لا أمد فيها.\rالجواب: أنّا نقول: إنّما وقعت المعاقبة ها هنا على قدر النية، فإنّ الكافر يقول: لو عُمّرتُ كذا إلى غير غاية لكنت على اعتقاد هذا مستمرّا، وكذلك يقول المؤمن: لو عُمّرتُ إلى غير غاية لكنت على إيماني هذا مستمرّا، فجُعلت أجريتهما على قدر نيّاتهما.\rفإن قيل: وهل يؤاخذ العبد بنيّته، إنّما المعلوم أن يؤاخذ بفعله؟\rقلنا: هذا كلام جاهلٍ بمآخذ الشريعة، المؤاخذة في الشريعة بالنيّات والاعتقادات أكثر من المؤاخذة بالأعمال، وعقوبتها أكثر من عقوبة الأعمال.\rالمسألة الرابعة:\r"]], "pg": [926, 927]}, "561.759": {"x": [[927, "قد بيّنّا حقيقة السرعة، وسرعة عقاب الله يكون في حالتين:\r"], [928, "أحدهما: ما يعجَّل.\rوالثانية: ما يكون في الآخرة، وهو قريبٌ، لأنه آتٍ لا محالة، قال الله تعالى: \"إِنَّهُمْ يَرَوْنَهُ بَعِيدًا وَنَرَاهُ قَرِيبًا\" (المعارج 6 - 7).\rالمسألة الخامسة:\r"]], "pg": [927, 928]}, "561.760": {"x": [[928, "كُنتُ بالثّغر في محرس الكوفيين مع الشيخ الإمام أبي بكر الطُّرطوشي، فتذاكرنا قوله تعالى في الانعام: \"إِنَّ رَبَّكَ سَرِيعُ الْعِقَابِ وَإِنَّهُ لَغَفُورٌ رَّحِيمٌ\" (الأنعام 167)، وقال في سورة الأعراف: \"إِنَّ رَبَّكَ سَرِيعُ الْعِقَابِ\" (الأعراف 167)، فقلنا: ما الفائدة في دخول اللام في إحدى الآيتين مع سقوطها في الآية الأخرى؟\rفأجاب عن ذلك الشيخ الإمام أبو بكر الطرطوشي، فقال: حكم اللام التأكيد في لسان العرب، والآية التي في الأنعام دخلت الأمّة فيها في\r"], [929, "الخطاب، وكان أمةً مرحومة معصومة في الدنيا، لا تُعاقب إلّا في الآخرة، فسقطت اللام التي حُكمها التأكيد في الخبر عنها، والآية التي في الأعراف خوطب بها بنو إسرائيل، وقد عُجّلت عقوبتهم في الدنيا بالمسخ والخسف، فدخلت اللام التي حكمها التأكيد في الخبر عنها.\rالفصل الرابع:\r"]], "pg": [928, 929]}, "561.761": {"x": [[929, "إذا ثبت هذا فالباري تعالى يُعذر بالرّسل، ويُمدّ بالنِّعم، ثمّ يُعاقب.\rوعليك في المنزلة السفلى أمران:\rأحدهما: أن تتعرض لنفحات الرحمة.\rوالثاني: أن تتحفّظ من موجبات النِّقمة.\r"], [930, "الاسم الخامس والأربعون: الوهّاب\rفيه أربعة فصول:\rالفصل الأوّل: في مورده\r"]], "pg": [929, 930]}, "561.762": {"x": [[930, "ورد به القرآن في عدّة مواضع، قال الله تعالى: \"أَمْ عِندَهُمْ خَزَائِنُ رَحْمَةِ رَبِّكَ الْعَزِيزِ الْوَهَّابِ\" (ص 9)، وورد مفسّراً في حديث أبي هريرة المفسّر.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [930, 930]}, "561.763": {"x": [[930, "الهبة العطيّة بغير عِوض، فإن كانت بعوض فهي بيع، فإن فعلها مرّة فهو واهب، وإن فعلها مراراً فهو وَهوبٌ، قال الشاعر:\r"], [931, "الحمد لله الوَهوب المُجزلِ\rفإن تكرّر ذلك كثيرا فهو وهّاب.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [930, 931]}, "561.764": {"x": [[931, "فيه خمس مسائل:\rالمسألة الأولى: في تحقيق المعنى فيه\r"]], "pg": [931, 931]}, "561.765": {"x": [[931, "اختلف علماؤنا –رحمة الله عليه- هل هو من صفات الذات أو من صفات الفعل؟\rفمنهم من قال: إنه من صفات الفعل.\rومنهم من قال: إنه من صفات الذات.\rوالذي قال إنه من صفات الذات، رأى أن الهبة هي قول القائل وهبْتُ، وقد قال الباري تعالى: \"هُوَ الَّذِي خَلَقَ لَكُم مَّا فِي الْأَرْضِ جَمِيعًا\" (البقرة 29)، فرجع ذلك إلى القول، وكان من صفات الذات، وهذا لا يصحّ.\rفإنّ قول القائل وهبْتُ، إخبارٌ عن الهبة، وليس بالهبة حقيقةً، وإنّما الهبة نفس العطاء، وذلك يرجع إلى خصائص فضله وفواضل كرامته.\r"], [932, "المسألة الثانية: في تركيب المعنى الاعتقادي اللغوي\r"]], "pg": [931, 932]}, "561.766": {"x": [[932, "إذا ثبت أن الهية هي العطيّة بغير عوض، فالباري تعالى هو الوهّاب حقيقةً، لأنّه الذي يُعطي بغير عِوض ولا غرض، وكلّ من يُعطي سواه فإنّما يُعطي لعوض أو غرض في الدنيا أو في الدين، عاجل أو آجل، فإذاً لا تُتَصوَّر الهبة ولا يصحّ الوهّاب إلا في الله وحده.\rالمسألة الثالثة: في بيان وجه العطاء فيه\r"]], "pg": [932, 932]}, "561.767": {"x": [[932, "وذلك أنّا نقول: إن الفعل إذا وُجد منه تعالى فيُملّكه المرء ويُمكّنه فيه، فلا يكون هبة ولا عطاء، إلا أن يتعلّق بنوع ما يكون به مُنعماً مُحسناً، وذلك بما لا ألم فيه ولا ضرر.\rفإذا كان ما يخلق ضررا وألماً لم تكن هبةً، وهذا معنى قوله: \"وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ\" (آل عمران 8)، فعلّمهم وتعبّدهم كيف يسألونه الإنعام والإحسان على وجهٍ لا يكون فيه مكرٌ ولا استدراج، كما فعل بالكفّار حين خلق لهم ومكّنهم، ممّا كان فيه ضررهم وهَلَكَتهم، فالمطلوب منه هبةٌ يكون مآلها كحالها، لا تنفصل ولا تتغيّر ولا يقترن بها ضررٌ ولا ألمٌ.\r"], [933, "المسألة الرابعة:\r"]], "pg": [932, 933]}, "561.768": {"x": [[933, "اعلموا –وفّقكم الله- أن خلق الألم قد يكون نعمة للمؤمن، بما في جهته من الثواب الجزيل، والفضل العظيم، والعِوَض الكريم، والغفران العميم، وهو للكافر زيادة في عذابه، ومقدّمة في عقابه، فهو الإحسان للمؤمن، وانتقامٌ من الكافر، قال النبي صلى الله عليه وسلم: \"أشدّ الناس بلاءً الأنبياء ثمّ الأولياء، ثم الأمثل فالأمثل، وقال عليه السلام: \"إنّي أُوعَكُ كَوَعْك رجلين منكم\".\rالمسألة الخامسة: في الأسماء المتعلقة بهذا المعنى\r"]], "pg": [933, 933]}, "561.769": {"x": [[933, "وهي كثيرة، أمّهاتها أحد عشر اسماً: وهي:\rوهّابٌ، وسخيٌّ، وجوادٌ، ومعطٍ، ومانعٌ، وكريمٌ، ومُحسنٌ، ومُجمِلٌ، ومُفْضِلٌ، ومُنعمٌ، ومُغنٍ.\r"], [934, "فأمّا كريم فقد تقدّم الكلام عليه في أوصاف التنزيه؛ في تراجمها.\rوأمّا جواد وسخيٌّ فيأتي بيانه بعد إن شاء الله.\rوأمّا معطٍ ففي الحديث الصحيح أن النبي عليه السلام قال: \"اللهمّ لا مانع لما أعطيت ولا معطي لما منعت\"، فجاء منه الفعل نصّاً والاسم إشارة.\rوالإعطاء في اللغة هو المناولة، وهي المعاطاة، ومنه يقال: عطاء الشيء تناوله، والإعطاء قريب منه، عبّر به عن خلق الباري للعبد ما يخلق من مرغوبٍ فيه مُتعلَّقٍ للآمال يصل إليه، سواءً كان محمود العاقبة أم لا.\rوقد قال بعض علمائنا: إنما سمّي عطاءً إذا كان محمود العاقبة، وهذا باطل، بدليل قوله تعالى: \"مَّن كَانَ يُرِيدُ الْعَاجِلَةَ عَجَّلْنَا لَهُ فِيهَا\r"], [935, "مَا نَشَاءُ لِمَن نُّرِيدُ ثُمَّ جَعَلْنَا لَهُ جَهَنَّمَ يَصْلَاهَا مَذْمُومًا مَّدْحُورًا\"، إلى قوله: \"مَحْظُوراً\" (الإسراء 18).\rوأما المانع فهو خالق المنع، وقد غلط فيه بعضهم فظنّ أنه من صفات الذات، وهو قول: لا، لقولهم: سألته فحرمني ومنعني، أي قال لي: لا أعطيك، وقد بيّنّا أنّ هذا خبرٌ عن المنع، والمنع يكون بوجهين متّفق عليهما، وهو عدم المطلوب وفعل العجز المانع، كالقَعَد والعمى، والثالث فعلٌ ضدُّ الممنوع، كقول بعض علمائنا: إن الله حرَم الكافر الإيمان ومنعه منه؛ ومنع من هذا كثير من أصحابنا، وقد بيّنّاه في الأصول.\rوأما مُحسنٌ ومُجملٌ ومُفضلٌ فلم يرد بها توقيفٌ، ولكنّها ألفاظٌ كريمة المعاني، ولا يُسمّى إلا بما سمّى به نفسه، أكثر من أن الفعل منها قد جاء، والتصريف لها قد ورد، قال تعالى: \"وَقَدْ أَحْسَنَ بِي إِذْ أَخْرَجَنِي مِنَ السِّجْنِ\" (يوسف 100)، وجاء في الحديث: جميل، وقيل: إنه بمعنى مُجمِل، وجاء: ذو الفضل العظيم.\rوأمّا المُنعم فقد جاء فعله في القرآن كثيرا، قال تعالى: \"رَبِّ بِمَا أَنْعَمْتَ عَلَيَّ\" (القصص 17)، والنعمة عبارةٌ عن كل عطاءٍ فيه منفعةٌ، وإن لم تُحسن فيه\r"], [936, "العاقبة، والدليل عليه قوله تعالى للكفّار: \"فَاذْكُرُوا آلَاءَ اللَّهِ لَعَلَّكُمْ تُفْلِحُون\" (الأعراف 69).\rوأمّا المُغني فإنه يحتمل معنيين:\rأحدهما: أن يكون واهب الغَناء –بفتح الغين والمدّ- وهو الاستقلال بالشيء، وهو عبارة عن مُعطي القوة وخالق القدرة.\rوالثاني: أن يكون واهب الغِنى والثروة، وذلك بثلاثة أشياء:\rإمّا بكثرة العَرَض، ويشترك فيه الكافر والمسلم، وليس بمحمود إلّا لمن أنفقه في سبيل الله، وقال به هكذا وهكذا، لقوله عليه السلام: \"إنّ الأكثرين هم الأقلّون، إلا من قال هكذا وهكذا\".\rوإمّا بغنى النفس، لقوله عليه السلام: \"ليس الغنى عن كثرة العرَض، إنّما الغنى غنى النفس\"، وهي التي يُعبَّر بها عن القناعة.\r"], [937, "وإمّا بكثرة العلم فهو الغنى الأكبر، وهو بالحقيق الغنى والثروة، وقال عليه السلام: \"ليس منّا من لم يتغنّ بالقرآن\"، قيل: يرى أنه أغنى الخلق به.\rوقد قال بعض علمائنا: إنه يُغني بالعافية عن المرض، فلا فقر أعظم من عدم الصحّة.\rالفصل الرابع: في التنزيل\r"]], "pg": [933, 937]}, "561.770": {"x": [[937, "المنزلة العليا للربّ:\rإذا ثبت هذا وعلمتم معاني هذه الأسماء المرتبطة أحكامها المتقاربة معانيها فللباري تعالى في ذلك أحكامٌ ستّة:\rالأوّل: أنه يعطي بغير عِوَض ولا غرض، وتلك هي الهبة المحضة، وهو الوهّاب وحده على الحقيق.\rالثاني: عموم العطاء، فإنه يعطي حتى يغلب المتمنّي وتنقطع الأمانيّ، كما ورد في حديث آخِرِ أهل الجنّة دخولاً الجنّة أنه يقال له: تَمَنَّ، حتى تنقطع به الأمانيّ، الحديث.\r"], [938, "الثالث: دوام العطاء، فإنّ كلّ مُعطٍ قاطعٌ، وكلّ معطٍى مقطوعٌ إلا هو تعالى، وما كان منه فإنّه لا يقطع عطاءه ولا يُفني مُعطاه.\rوقد حُكي عن أبي عمر محمّد بن عبد الواحد اللغوي أنّ بعض الوُلاء أرسل إليه يقول له: اذكر ما يفوتُكَ لنجريه عليه، فقال للرسول: قل لصاحبك: أنا في جِراية من إذا غضب لم يقطع جرايته عنّي.\rالرابع: هبة الهدى، قال تعالى: \"قُلْ إِنَّ الْهُدَى هُدَى اللَّهِ أَنْ يُؤْتَى أَحَدٌ مِثْلَ مَا أُوتِيتُمْ\" (آل عمران 71).\rالخامس: أنه يهب الولد للعقيم، ما بين أنثى عفيفة أو ذكر كريم، قال تعالى: \"يَهَبُ لِمَنْ يَشَاءُ إِنَاثاً وَيَهَبُ لِمَنْ يَشَاءُ الذُّكُورَ أَوْ يُزَوِّجُهُمْ ذُكْرَاناً وَإِنَاثاً وَيَجْعَلُ مَنْ يَشَاءُ عَقِيماً\" (الشورى 46 - 47).\rالسادس: أنه يهب من غير سؤال، ويُنيل دون استينال.\r"], [939, "المنزلة الثانية للعبد:\rإذا تحقّق العبد أنه الوهّاب ومعناه فعليه:\rالأول: أن لا يسأل سواه.\rالثاني: ألّا يعبد غيره.\rالثالث: ألّا يشكر غيره، فإنّ العبد إذا كان الله يهبه ويشكر سواه، ويرزقه ويعبد غيره، ويعطيه ويسأل غيره، فقد أخطأ الطريق، وعدَل عن التحقيق.\r"], [940, "الاسم الموفّي خمسين: جواد\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [937, 940]}, "561.771": {"x": [[940, "لم يرد به قرآنٌ، ولا ورد في حديث أبي هريرة، ولا جاء به أثر صحيح، لكن رُوي عن أبي ذرّ أن النبي عليه السلام قال: \" قال الله: ذلك بأني جوادٌ ماجدٌ\" حسب ما تقدّم، وقد غلب على ألسنة الخطباء والصوفية، أمّا الخطباء فلجهلهم بالآثار، وأمّا الصوفيّة فلجهلهم بالآثار واللغة، مع أنّهم تاخموا الفلاسفة في معانٍ ظنّوا بهم أنهم يُحوِّمون على الحقائق.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [940, 940]}, "561.772": {"x": [[940, "قال أبو عمرو بن العلاء: الجواد الكريم، وتقول العرب: فرسٌ جوادٌ، إذا كان غزير الجري، ومطرٌ جودٌ إذا كان غزيراً، قال عنترة:\r"], [941, "جادت عليها كلّ عينٍ ثرّةٍ *** فتَرَكْنَ كلَّ حديقةٍ كالدّرهمِ\rوجاء في الحديث في صفة المطر الذي استسقاه عليه السلام: \"فما جاء أحد من جميع النواحي إلّا حدّث بالجَوْد\".\rالفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [940, 941]}, "561.773": {"x": [[941, "فيه أربع مسائل:\rالمسألة الأولى: في سرد أقوال أهل العقائد\r"]], "pg": [941, 941]}, "561.774": {"x": [[941, "ولهم فيه ثلاثة أقوال:\rالأول: أنه لم يزل جواداً بجودٍ قديم، وَجُوده صفة له كان بها جوادا، كالعلم والقدرة، قاله الثقات من أهل السنّة.\rالثاني: أنه لم يزل جوادا بجود قديم، وجوده صفةٌ له بها كان جوادا، وهو الشيء الذي إذا حصل لم يصعب عليه العطاء ولم يستكثره، وتُسمّي العرب ذلك المعنى سماحةً.\r"], [942, "الثالث: أن وصفه بأنّه جوادٌ ثابتٌ في الأزل، والباري لم يزل جوادا، لا على معنى أن له جواد، ولكن ذلك بمعنى أنه لا يصعب عليه العطاء ولا يكثر، قاله أبو الحسن الأشعري إمام السنّة، والنجّار من المبتدعة.\rالمسألة الثانية: في الصحيح من الأقوال:\r"]], "pg": [941, 942]}, "561.775": {"x": [[942, "وهي ترجع إلى أصلين:\rالأصل الأوّل: في حقيقة الجود.\r"]], "pg": [942, 942]}, "561.776": {"x": [[942, "والثاني: إطلاقه.\rأما الأصل الأول، فقد تقدّم في بيان معنى الكريم الذي هو من صفات الفعل، وهو هو نفسه، كِفّة بكفّة، ولذلك قال أبو عمرو بن العلاء: الجواد هو الكريم، وهو أصلٌ من أصول اللغة وفحلٌ من فحولها.\rأمّا الإطلاق فالاشتقاق يشهد بأنه محض العطاء وكثرته، فلا فرق بين قولنا جواد وبين قولنا كريم إذا كان بمعنى الفعل، فمن قال بعد هذا إن الجود عبارة عن تيسير العطاء وتسهيله، فهو تفسير بالنفي المحض، وعُدولٌ عن الإثبات، ولكلّ إثبات نفس، ولكل نفي إثبات، ولكن لا يُفسَّر أحدهما بالآخر، لأنّه يؤول إلى إفساد المعاني وقلبها.\r"], [943, "وأما من قال إن الجود عبارة عن صفة كان بها جوادا، وهي التي إذا حصلت لم يصعب عليه العطاء فكلام مُؤلَّف من صحيح وسقيم.\rأما قوله: إن الجود عبارة عن صفة كان بها جوادا، فصحيح، لكن تلك الصفة ليست قائمة به تعالى، فإن ذلك عبارة عن فعله، والإفعال لا تقوم به، وإن أراد الإرادة فليس الجود عبارة عنها، وإن كان الجود تمّ بها تمامه بالقدرة والعلم.\rوأما قوله: إذا حصل كان جواداً، فلا يقال في صفات الباري إذا حصل، وقد تكلّمنا عليه في قوله تعالى: \"إِنَّمَا قَوْلُنَا لِشَيْءٍ إِذَا أَرَدْنَاهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ\" (النحل 40)، وأيضا فإن العطاء إن عُبِّر عنه بالإرادة يليق به أن يُعبَّر عنه بالقدرة، وهو إفساد المعاني، فدلّ أنّ الصحيح أنه بمعنى الإنعام والإحسان والعطاء الغامر.\rالمسألة الثالثة: هل يوصف الله بأنه سخيٌّ؟\r"]], "pg": [942, 943]}, "561.777": {"x": [[943, "قال بعضهم: كما نقول إنه جواد نقول إنه سخيّ، أجاب عنه بعض الناس بأن قال: وصْفُ الباري بأنه جواد مأخوذ من مطرٍ جَوْدٍ، وفرس جواد، وذلك يرجع إلى الكثرة، فلذلك نقول: إنه جواد لأنه كثّر الإنعام والإحسان، وسخيٌّ مأخوذ من أرضٍ سخاويّة، إذا كانت سهلة ليّنة.\r"], [944, "وأجاب بعض علمائنا بأن قال: لا نصف الباري إلّا بالتوقيف، ولم يرد توقيف بوصف أنه سخيّ، فلم نصفه به.\rقال الإمام الحافظ رضي الله عنه: أمّا من وصفه بأنه سخيّ أخْذاً من قولهم أرض سخاويّة، كما أُخذ جواد من مطر جود، فهذا فاسد من وجهين:\rأحدهما: أنّا نقول: هذا بناءٌ على أصل فاسد، فإنّا لم نأخذ جوادا من مطر جود.\rالثاني: أن هذا الأصل لا يطّرد في اللغة على أحد القولين، فإذا كان الناس قد اختلفوا فيه في المُحدَث فكيف نُطلقه في الباري سبحانه؟\rوأما من قال من علمائنا إنه لم نصفه بأنه سخيّ لأنّه لم يرد به توقيفٌ؛ فهذا ضعيف من وجهين:\rأحدهما: أنه لم يرد أيضاً توقيف صحيح بجواد.\rالثاني: أنهم قالوا: إذا لم يكن في اللفظ نقص جاز إطلاقه.\rوالجواب الصحيح أن نقتصر في وصفه على الكريم، ونُعرض عن جواد وسخيّ وغيرهما، ففي الكريم أتمّ المعنى وأكمله.\r"], [945, "المسألة الرابعة:\r"]], "pg": [943, 945]}, "561.778": {"x": [[945, "قال بعض الناس: جوده تعالى سبب كلّ موجود، وقال مشيخة الصوفية: إنه خلق العالم بجوده، وقال شيخنا أبو حامد قولا عظيما انتقده عليه علماء العراق، وهو بشهادة الله موضع انتقاد، قال: ليس في القدرة أبدع من هذا العالم في الإتقان والحكمة، ولو كان في القدرة أبدع منه أو أحكم ولم يفعله لكان ذلك مناقضاً للجود، وذلك محالٌ يتقدّس الباري سبحانه عنه.\rالجواب: أنّا نقول: أمّا قول بعض الناس إن جوده سبب لكلّ موجود فعنه ثلاثة أجوبة:\rالأول: أن نقول لا نُسلِّم أنّ لوجود العالم سببا.\rالثاني: إن سلّمنا قولك: إنّ جوده سببٌ لكل موجود مبنيٌّ على\r"], [946, "معرفة الجود، فبيِّن ما هو حتى تضيف إليه وتُركّب عليه، فإنّ الأضافة إلى المجهول من مُضلّات العقول.\rالثالث: أن نُقسّم عليك فيقال: ماذا تريد بالجود؟\rهل تريد به الكرم الذي هو الفعل؟\rأم تريد به الإرادة؟\rأم تريد به العلم؟\rأم تريد به المقدرة؟\rأم تريد به سائر الصفات العُلى؟\rأم غير ذلك من الأسماء؟\rفإن أردتم به الفعل فمحالٌ، لأنّ الفعل لا يكون سبباً لنفسه؛\rوإن أردتم سائر الصفات فمحالٌ أيضاً، لأنه لا أثر له في الإيجاد، حسب ما تقرّر في كتب العقائد.\rوإن أردتم به القدرة، فأصبتم في المعنى وأخطأتم في العبارة، فلا يقال: إن القدرة سببٌ لوجود الفعل، فإنّ لفظ السبب مشتركٌ بين ما يقترن بالإيجاد، وبين ما يتقدّم عليه، والقدرة أو غيرها ممّا يصحّ أن يكون سبباً لو اقترن بالأفعال لكانت الأفعال قديمة.\r"], [947, "وأمّا قول الصوفية إنه خلق العالَمَ بجوده، ففي العبارة إشكالٌ، وذلك يصح على معنى أن يُفسَّر الجود بالكرم، ويعود ذلك إلى صفة الفعل، وهي الإنعام والفضل، فيكون تأويله خلق العالم بفضل، وكذلك كان، فإنه سبحانه مُتفضِّلٌ في ذلك كلّه.\rوأما شيخنا أبو حامد، فإنه ساعد في اعتقاد عموم القدرة، ونفي النهاية عن تقدير المقدورات المتعلِّقة بها، ولكن في تفاصيل هذا العالم المخلوق لا سواه، وهذا رأي فلسفيٌّ قصدت به الفلاسفة قلب الحقائق على الناس، وإفساد طرق النظر، ونسبة الإتقام إلى الحياة مثلاً، والجود إلى السمع والبصر، حتى لا يبقى في القلوب سبيل إلى الصواب.\rوقد أجمعت الأمّة على خلاف هذا الاعتقاد، وقالت عن بكرة أبيها: إن المقدورات لا نهاية لها لكلّ مُقدَّر الوجود لا لكلّ حاصل الوجود.\rوالدليل عليه أن القدرة إذا صلحت لإخراج الشيء من العدم إلى الوجود من وجهٍ صلحت من كلّ وجه، وقد ساعد هو على هذا المعنى، لكن زعم ما ليس بمَزعمٍ من أنّ القدرة قصُرت عن صحّة متعلّقها، لأنّ ذلك خلاف الجود، فنقسِّم عليه المعاني ونقول: ماذا أردت بالجود، كذا أو كذا؟ كما تقدّم، فيبقى حائراً.\r"], [948, "وهذه وهلة لا لَعَا لها، ومزلّة لا تماسك فيها، ونحن وإن كنّا نقطةً من بحره فإنّا لا نرُدّ عليه إلا بقوله، فسبحان من أكمل لشيخنا هذا فواضل الخلائق، ثم صدف به عن هذه الواضحة في الطرائق.\rالفصل الرابع: في التنزيل\r"]], "pg": [945, 948]}, "561.779": {"x": [[948, "إن قلنا بصحّة هذا الاسم في الأسماء فسبيله مُبيَّنٌ في سبيل الكريم، وإن نفيناه كُفيناه، والله أعلم.\r"], [949, "الاسم الحادي والخمسون: الرزّاق\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [948, 949]}, "561.780": {"x": [[949, "ورد به القرآن، قال الله تعالى: \"إِنَّ اللَّهَ هُوَ الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ\" (الطور 58)، وقال: \"وَأَنتَ خَيْرُ الرَّازِقِينَ\" (المائدة 116)، وورد في الحديث مُعدّدا في حديث أبي هريرة المفسّر، وأجمعت عليه الأمة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [949, 949]}, "561.781": {"x": [[949, "الرزق في اللغة هو الغذاء الذي به قِوام الأبدان حقيقة، ويُستعمل في المِلك مجازا، والرزّاق فعّال منه للتكثير، وقد تكلّمنا في كتب الأصول بحقائق تُغني عن الإعادة، ولكنّا نشير ها هنا إلى ما لا غنًى عنه في الإفادة.\r"], [950, "الفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [949, 950]}, "561.782": {"x": [[950, "فيه سبع مسائل:\rالمسألة الأولى: في حقيقته\r"]], "pg": [950, 950]}, "561.783": {"x": [[950, "حقيقة الرزّاق المُيَسِّر لغذاء الحيوان الذي يقوم به جسمه وتبقى به نفسه، والرزق هو ذلك الغذاء نفسه، وقال من لا بصر له بالحقيقة: الرزق هو المِلك، والرزّاق هو المالك، وهذا يبطل بثلاثة معانٍ:\rالأول: قوله: \"وَكَأَيِّنْ مِنْ دَابَّةٍ لَا تَحْمِلُ رِزْقَهَا اللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ\" (العنكبوت 60)، وقال تعالى: \"وَمَا مِن دَابَّةٍ فِي الْأَرْضِ إِلَّا عَلَى اللَّهِ رِزْقُهَا\" (هود 6)، وقال النبي عليه السلام: \" لو توكلتم على الله حقّ توكّله لرُزقتم كما تُرزق الطير، تغدو خماصاً وتروح بطاناً\"، فأضاف الرزق إلى من لا يصحّ منه المِلك، في معرض المدح والوعظ والتعليم، وهو يُبطل قول من قال إنه المِلك.\rالثاني: أنه قال تعالى: \"وَالنَّخْلَ بَاسِقَاتٍ لَّهَا طَلْعٌ نَّضِيدٌ رِّزْقًا لِّلْعِبَادِ\" (ق 11)، وقال: \"وَمِن ثَمَرَاتِ النَّخِيلِ وَالأَعْنَابِ تَتَّخِذُونَ مِنْهُ سَكَراً\r"], [951, "وَرِزْقاً حَسَناً\" (النحل 67)، يعني به غذاءً في الموضعين، وبتفسير بذلك ينتظم الكلام ويصحّ المرام.\rالثالث: أنه لو كان الرزق هو المِلك لكان آكل الحرام والبهائم والطير والحشرات خارجين عن أرزاق الله تعالى، مع تمدّحه بعموم الرزق في الكلّ بقوله: \"وَمَا مِن دَابَّةٍ فِي الْأَرْضِ إِلَّا عَلَى اللَّهِ رِزْقُهَا\" (هود 6)، وهذا ابتداعٌ عظيمٌ في الدين.\rومن الغريب أن علماءنا الأشعريّة يقولون: إن الآيات العامّة لا صيغة لها في العموم، ولا تُحمل على عمومها إلا بدليل، واتّفقوا على عموم هذه الآية لأنّها خرجت مخرج المدح الذي يقتضي التعميم، والقدرية قالوا بالعموم في آياتٍ كثيرة، منها الوعيد وغيرها، وخصّوا هذه الآية وأخرجوا عن رزق الله أكثر المخلوقات، فتعالى الله عمّا يقول الظالمون، وعمّا نسب إليه الملحدون عُلوّاً كبيرا.\rالمسألة الثانية: في متعلَّق الرزق\r"]], "pg": [950, 951]}, "561.784": {"x": [[951, "ممّا لا نكرة فيه عندنا أن الله يرزق المؤمن الإيمان ويرزق الكافر الكفر، على معنى أنه جعل ذلك حظّ كل واحد منهما، اتساعاً واستعارة، تشبيها بما هو\r"], [952, "رزق على الحقيقة، قال سبحانه: \"اللَّهُ لَطِيفٌ بِعِبَادِهِ يَرْزُقُ مَنْ يَشَاءُ وَهُوَ الْقَوِيُّ العَزِيزُ\" (الشورى 19)، معناه أنه يرزق لطفه من يشاء، ولطفه هو توفيقه للطاعة.\rالمسألة الثالثة: في كونه من صفات الأفعال\r"]], "pg": [951, 952]}, "561.785": {"x": [[952, "لا خلاف عندنا أن الباري تعالى كان رازقاً بعد أن لم يكن، كما كان خالقا بعد أن لم يكن، لإبطال كون الرزق بمعنى المِلك، ووجوب كونه بمعنى التغذية والتقوّت، وذلك لا يكون إلا بعد خلق الحيوان، فثبت معناه.\rالمسألة الرابعة: في الفرق بين وصفه بأنه مُقيتٌ وبين وصفه بأن"]], "pg": [952, 952]}, "561.786": {"x": [[952, "ه رزّاقٌ\rوقد تقدّم بيان وصفه بأنه المُقيت، وأنّ من معانيه إعطاء القوت، وبيّنّا معاني الرزّاق، وباستقراء ما شُرح في الموضعين تعلمون وجه افتراقهما وأين تلتقي معانيهما، لأن معنى كلّ واحد منهما يُصاقب الآخر في موضع ويزدحم معه في آخر، بيد أن علماءنا خصّوا ذلك بالذّكر، فاقتدينا بهم في إفراده، ليكون أشدّ تنبيهاً على الغرض وأوفى على المطلوب.\rوقال بعض علمائنا: \"المُقيت خالق الأقوات ومُوَصّلها إلى الأبدا؛ وهي الأطعمة، وإلى القلوب؛ وهي المعرفة، فيكون بمعنى الرزّاق إلا أنه أخصّ منه، إذ الرزق يتناول القول وغيره، والقوت ما يُكتفى به في قِوام البدن، وإمّا أن يكون معناه المُستولي على الشيء القادر عليه، والاستيلاء يتمّ بالقدرة والعلم، وعليه يدل قوله: \"وَكَانَ اللَّهُ عَلَى كُلِّ شَيْءٍ مُّقِيتًا\" (النساء 85)،\r"], [953, "أي مُطّلعاً قادراً، فيكون معناه راجعا إلى القدرة والعلم، وبهذا يخرج عن الترادف\".\rقال الإمام الحافظ رضي الله عنه: هذا قولٌ وإن كان صدر عن بحرِ لجّيٍّ ولكنه لم يعذُب مذاقه؛ لما فيه من المسامحة في الألفاظ والتناقض في المعنى.\rأنّا قوله إن المُقيت خالق الأقوات، ففاسد من وجهين:\rأحدهما: أنه لم يقُلْهُ أحدٌ من أهل اللغة والتحقيق؛\rالثاني: أنّ اللفظ يأباه، لأنه مُفعِل من أقات، وليس يدل إلا على إعطاء القوت، كما أن الرزّاق ليس يدلّ إلا على إعطاء الرزق.\rفأمّا خلقهما فإنه مأخوذ من لفظ الخالق، ولو جاز أن يفسَّر المُقيت بالخالق لجاز أن يُعبَّر به كلّ اسمٍ من الأسماء الأفعاليّة، لأنّ الفعل عن القدرة يصدر، فكانت المعاني تشترك، ويَفسُدُ النظام، ويذهب الإحصاء في الأسماء الذي هو المطلوب.\r"], [954, "وأما قوله: ومُوصّلها إلى الأبدان، فهو صحيح مُحقَّقٌ.\rوأمّا قوله: وإلى القلوب وهي المعرفة، فصحيح مجازاً.\rوأما قوله: فيكون بمعنى الرزّاق ففاسدٌ من وجهين:\rأحدهما: أنه جعل الرزق معلَّقاً بالقوت وغيره، وجعل القوت ممّا يُكتفى به في قوام البَدَن، وقال قبله بأحرف يسيرة: إن المُقيت خالق الأقوات والمعارف، فجعل المعرفة قوتاً، وقد قال بعد ذلك: إن القوت ما يكفي في قوام البدن، وهذا تناقضٌ ظاهرٌ متّصلٌ.\rوالثاني: قال بعد ذلك: وإمّا أن يكون معناه المُستولي على الشيء القادر عليه، فهذا فاسدٌ من ثلاثة أوجه:\rأحدها: أنه فصل بينهما، فعلى أيّ معنًى نُعوِّل؟\rالثاني: أنه لا يصحّ أن يكون معناه الخالق لما بيّنّاه، ولا يصحّ أن يكون معناه القادر أيضاً لما بيّنّاه.\rالثالث: أنا قد بيّنّا أن أصل هذه الأسماء الفعلية الخالق، وأصل الخالق القادر، وما كان أصلا لمعنى اللفظ عنه يصدر وبه يكون، لا يصحّ أن يُعبَّر به عنه على وجهٍ يخرج معناه منه.\rثم قال: والعلم، وعليه يدلّ: \"وَكَانَ اللَّهُ عَلَى كُلِّ شَيْءٍ مُّقِيتًا\" (النساء 84)، وهذا إنّما أخذه من قول من قال: إنه الشاهد، فيكون مُطّلعاً قادراً، وهذا فاسدٌ من خمسة أوجه:\r"], [955, "أحدها: أن هذا لم يدل عليه لفظ.\rالثاني: أنه لا يساعده اشتقاق.\rالثاث: أنه لا يقل به أحد.\rالرابع: -وهو أقواها- أنه ركّب على اللفظ معاني متعدّدة مختلفة لم تتحقق.\rالخامس: أنه شرّك بينهما، ثم جاء ببديعة فقال: ويكون لهذا المعنى وصف المقيت اسماً من صفة القادر وحده، والعالم وحده، لأنه دلّ على اجتماع المعنيين، ففرّق وجمَع، وشرّك وفصّل، وأخرج الاسم من الترادُف، وهو قد رتّب عليه أشدّ من الترادف، ولهذا العالم علينا رِقْبةُ التفهيم وحرمة التعليم، وإنّما اعترضنا عليه به، ورددنا قوله بقوله، فالكلّ له وفضله رضي الله عنها.\rالمسألة الخامسة: في المختار\r"]], "pg": [952, 955]}, "561.787": {"x": [[955, "قإن قيل: قد تتبّعتم الأقوال كلّها بالاعتراض فما اختياركم؟\r"], [956, "قلنا: مَدركه هيّنٌ بعدما تقدّم من التبيين والتأسيس، وقد سبق تبيانه، ونُجدّد الآن عهدا على الاختصار به فنقول: المُقيت مُعطي القوت، فهو أخصّ من الرزّاق، أخصّ من الوهّاب، أخصّ من المعطي.\rأما خصوصه عن الرزّاق فلما بيّنّاه فيه، يدلّ عليه قوله: \"اللَّهُ لَطِيفٌ بِعِبَادِهِ يَرْزُقُ مَنْ يَشَاءُ\" (الشورى 17)، ثم قال: \"لِيَجْزِيَهُمُ اللَّهُ أَحْسَنَ مَا عَمِلُوا وَيَزِيدَهُم مِّن فَضْلِهِ\" (النور 37)، والمزيد رؤية الله ورجاؤه، فسمّاها رزقاً، وليس ذلك بمطعوم، وأبين من ذلك قوله: \"مَا أُرِيدُ مِنْهُمْ مِنْ رِزْقٍ وَمَا أُرِيدُ أَنْ يُطْعِمُونِ\" (الذاريات 57)، ففصل بين الرزق والطَّعم، وبيّن أن الرزّاق أعمّ من المُطعم.\rفأمّا خصوص الرزّاق من الوهّاب فلأنّ الوهّاب يرجع إلى الذات والفعل، والرزّاق يختصّ بالفعل.\r"], [957, "وأمّا خصوص الوهّاب عن المعطي فبعموم العطاء في المحمود والمذموم، وخصوص الهبة في المحمود، قال تعالى: \"وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ\" (آل عمران 8)، وقال: \"نُمِدُّ هَؤُلَاءِ وَهَؤُلَاءِ مِنْ عَطَاءِ رَبِّكَ وَمَا كَانَ عَطَاءُ رَبِّكَ مَحْظُوراً\" (الإسراء 20).\rالمسألة السادسة:\r"]], "pg": [955, 957]}, "561.788": {"x": [[957, "المُقيت مُفعلٌ من أقات، وقد يقال قات كما بيّنّاه، فيكون اسم الفاعل منه قائتاً، فالاشتقاق يعطيه، واللفظ يقتضيه، لكن لم يرد به أثر، فعلى القول بالتوقيف في الأسماء لا نسمّيه به، وعلى القول بأنّ ذلك يجري في كلّ اسم كمالٍ جاء في الاشتقاق لا إيهام فيه يجوز ذلك فيه، والله أعلم.\rالمسألة السابعة: في كونه خير الرازقين\r"]], "pg": [957, 957]}, "561.789": {"x": [[957, "قد قدّمنا حقيقة الرزق والرزّاق، وبيّنّا أنه اسم ينطلق على القديم والمُحدَث كالخالق، وكان الباري تعالى أحسن الخالقين على ما بيّنّاه،\r"], [958, "كذلك هو خير الرازقين، ومعنى كونه خير الرازقين يتبيّن في أحكامٍ جماعها ستة:\rالأول: أنه يبدأ بالرزق قبل السؤال.\rالثاني: أنه لا يقطعه بالتقصير في الأعمال.\rالثالث: أنه يجعله فوق الحاجة.\rالرابع: أنه يُسوِّغه.\rالخامس: أنه يُخرج ما زاد على الغذاء بتسهيل.\rالسادس: أنه يجعل حسابه يسيراً.\rالفصل الرابع: في التنزيل:\r"]], "pg": [957, 958]}, "561.790": {"x": [[958, "المنزلة العليا للربّ تعالى:\rفي ذلك أحكام يختصّ بها عددها ثلاثةٌ:\rالأول: أنه خالق الرزق.\r"], [959, "الثاني: أنه مُيسّره حتى يُتغذّى به، لقد سمعت بعض العلماء يقول: إن الغذاء لا يتهيّأُ للمرء الانتفاع به إلا حتى يمُرَّ به على يدي نيّف وثلاثمائة مَلَك مسَخّرين فيه بأمر الله، وإن كان يمُرُّ على أيديهم فهو إليه منسوبٌ وعليه محسوبٌ، قال الله تعالى: \"أَفَرَأَيْتُمْ مَا تُمْنُونَ\"، \"مَّا تَحْرُثُونَ\"، \"أَفَرَأَيْتُمُ النَّارَ الَّتِي تُورُونَ\" (الواقعة 61 – 66 – 74).\rالثالث: أن يختصّ برزق المعاني كما يختصّ برزق الأجسام، فهو رازق الهدى والإيمان، والنظر السديد والفرقان، والذكر بالقلب واللسان، وفي الحديث: \"اللهم ارزقني قلباً شاكراً، ولساناً ذاكراً\".\rالمنزلة الثانية للعبد:\rإذا علم هذا من وَصْف ربّه تعيّن عليه أحكامٌ ثلاثةٌ:\r"], [960, "الأول: أنه لا يرتزق من غيره.\rالثاني: أن لا يطلب من سواه.\rالثالث: أن يقسم بالعدل ما يجري على يديه من رزقٍ، إن كان عالماً بذلك العلم، وإن كان غنيّا وفى بالوعد في أداء الحقّ، وإن كان خازناً أطاع الأمير، قال النبي عليه السلام: \"الخازن الأمين الذي يُعطي ما أُمر به كاملاً موفوراً طيّباً به نفسُه أحدُ المتصدّقين\".\r"], [961, "الاسم الثاني والثالث والخمسون: الخافض الرافع\rوفيهما أربعة فصول:\rالفصل الأول: في موردهما\r"]], "pg": [958, 961]}, "561.791": {"x": [[961, "هذان اسمان لم يرد بهما القرآن لفظاً، وإنما ورد بفعلهما، قال الله تعالى: \"وَرَفَعْنَاهُ مَكَانًا عَلِيًّا\" (مريم 57)، وقال: \"يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا مِنكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ\" (المجادلة 11)، وقال: \"بَلْ رَفَعَهُ اللَّهُ إِلَيْهِ\" (النساء 158)، ووردا في حديث أبي هريرة المفسّر معدَّدَين، وروي من طريق آخر: \"بيده القسط، يخفض ويرفع، والقيامة خافضة رافعة\"، على ما يأتي بيانه إن شاء الله.\rالفصل الثاني: في شرحهما عقيدة\r"]], "pg": [961, 961]}, "561.792": {"x": [[961, "لا خلاف بين العلماء أنّ هذا الاسم من صفات الأفعال، وأن الباري مذ خلق الخلق، خفض ورفع، ولا يزال يخض ويرفع إلى يوم القيامة، والوجه الذي يتعلّق به الخفض والرفع كما قدّمناه أمران:\r"], [962, "أحدهما: المكان.\rوالثاني: المكانة.\rفأمّا رفعه المكان وخفضه، فعلى وجوه:\rالأوّل: أنه رفع العرش وخفض الماء.\rالثاني: أنه رفع السماء بغير عمدٍ ترونها، وخفض الأرض بأوتادها، فتلك قارّةٌ في الجوّ لا تنخفض، وهذه قارّة سفلى لا تضطرب؛\rالثالث: أنه رفع السماء بين الأرض إلى السماء، وهكذا السماء الثانية، إلى آخر السماوات.\rالرابع: أنه قد رفع عيسى إلى السماء الثانية، فهو فيها إلى أن ينزل في الأرض، حَكَمَاً مُقسِطاً، فيكسر الصليب، ويقتل الخنزير، ويضع الجزية.\rالخامس: أنه رفع محمّداً صلى الله عليه وسلم ببدنه حتى انتهى إلى موضع يسمع فيه صريف الأقلام، وكلّمه ربّه بغير واسطة يُبلّغه الكلام.\rالسادس: أنه رفع ابن فُهيرة، فرُوي أنه لما طُعن أخذته الملائكة فرفعته إلى السماء عن أيدي الكفار.\r"], [963, "وهذه الثلاثة الأوجه فيها رفعة المكان لا رفعة المكانة.\rوأمّا رفعة المكانة:\rفقد رفع الآدميّ على سائر المخلوقات فقال: \"وَلَقَدْ كَرَّمْنَا بَنِي آدَمَ وَحَمَلْنَاهُمْ\" (الإسراء 70)، وقد تقدّم بيانه.\rالثاني: أنه رفع الأنبياء بدرجة النبوءة.\rالثالث: أنه رفع الملائكة بدرجة الملكيّة، وقد اختُلف في أرفع الدرجتين، حسب ما بيّنّاه في كتب الأصول.\rالرابع: أنه رفع المؤمنين فقال: \"يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا مِنكُمْ\".\r"], [964, "الخامس: أنه رفع العلماء بقوله: \"يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا مِنكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ\" (المجادلة 11).\rفأمّا رفعة المؤمن فبمكانة دينه وماله وعرضه، كما قال صلى الله عليه وسلم: \"إن دماءكم وأموالكم وأعراضكم وأبشاركم عليكم حرام كحرمة يومكم هذا، في بلدكم هذا\".\rوأمّا رفعة العلماء فبإنفاذ أقوالهم في الدين، وولايتهم في الذكر على جميع المسلمين، قال تعالى: \"فَاسْأَلُوا أَهْلَ الذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ\" (النحل 43).\rوالسادس: أنه رفع الحقّ كما قال تعالى: \"بَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ فَيَدْمَغُهُ فَإِذَا هُوَ زَاهِقٌ\" (الأنبياء 18).\r"], [965, "السابع: أنه رفع المتواضع، ورُوي: \"أن ناصية المتواضع بيد مَلَكٍ، كلّما تطأطأ رفعه\"، وعكسه المتكبّر.\rالثامن: أنه رفع أهل الطاعة بقبول قولهم، وخفض الفُسّاق بردّ قولهم.\rالفصل الرابع: في التنزيل\r"]], "pg": [961, 965]}, "561.793": {"x": [[965, "للباري تعالى في منزلته العليا أحكام يختصّ بها خمسةٌ:\rالأول: أنه يعطي المنازل، فذلك بيده لا يملكه غيره.\rالثاني: أنه يرفع الأعمال بالإخلاص، ويخفضها بالرياء.\rالثالث: أنه يرفع الأرواح بالتوحيد، ويخفضها بالشرك.\rالرابع: أنه يرفع العلماء بالعلم، ويخفض بالجهل.\rالخامس: أنه يرفع بالنصرة والظهور، ويخفض بالخذلان.\r"], [966, "وعلى العبد في المنزلة السفلى أن يرفع بالتقوى ويخفض بالمخالفة، وقد فاضل النبي صلى الله عليه وسلم في العطّة بين المؤلفة قلوبهم يوم حُنين، فقيل له:\rومن تخفِضُ اليوم لا يُرفع\rوكلّ ذلك مما عادت منفعته إلى التقوى.\r"], [967, "الاسم الرابع والخامس والخمسون: القابض الباسط\rفيهما أربعة فصول:\rالفصل الأول: في موردهما\r"]], "pg": [965, 967]}, "561.794": {"x": [[967, "ورد بهما القرآن فعلا، قال الله تعالى: \"وَاللَّهُ يَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ تُرْجَعُونَ\" (البقرة 245)، وقال تبارك وتعالى: \"وَلَوْ بَسَطَ اللَّهُ الرِّزْقَ لِعِبَادِهِ لَبَغَوْا فِي الأَرْضِ\" (الشورى 27)، وقال تعالى: \"وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ\" (الزمر 67)، وورد في الخبر مفسَّؤاً في حديث أبي هريرة المعدَّد، وأجمعت الأمة على أنه يقبض ويبسُط، ويُعطي ويمنع.\r"], [968, "الفصل الثاني: في شرحه لغة\r"]], "pg": [967, 968]}, "561.795": {"x": [[968, "فيه مسألتان:\rالمسألة الأولى: في ذكر أقوال الناس فيه\r"]], "pg": [968, 968]}, "561.796": {"x": [[968, "قال أكثرهم: هو يقبض ويبسط، أي يُعطي ويمنع.\rالثاني: أنه يقبض الصدقات ويبسط الجزاء.\rالثالث: أنه يبسط الرزق ويقبضه.\rالمسألة الثانية: في تحقيق معناه لغة\r"]], "pg": [968, 968]}, "561.797": {"x": [[968, "البسط عبارة عن توسُّع الجسم بكثرة أجزائه، فتكثر مساحته، والقبض عبارة عن تقليل أجزائه فتتقلّص مساحته، وقد يُستعمل في المعاني فيقال: فلان باسط، وقدرته باسطة؛ إذا كثُرت متعلَّقاتها، ومقبوضة إذا قلّت متعلّقاتها، والدليل على صحّة ذلك قوله تعالى: \"وَزَادَهُ بَسْطَةً فِي الْعِلْمِ وَالْجِسْمِ\" (البقرة 247).\rالفصل الثالث: في شرحه حقيقة وعقيدة\r"]], "pg": [968, 968]}, "561.798": {"x": [[968, "إذا علمتم حقيقة القبض والبسط، وأنّه يستعمل في الأجسام، وأن معناه تكثير الأجزاء وتوسيعها، فيعود معناه إلى معنى التوسُّع، كما تقدّم في اسم الواسع، وفي قوله: \"وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ وَإِنَّا لَمُوسِعُونَ\" (الذاريات 47).\r"], [969, "وأمّا إذا كان في المعاني، فلا يصحّ أن يتعلّق بالصفات الإلهية، فإنه من الأفعال المتعدّية، لا يصحّ أن تقول: بسط الله علمه، ولا بسط قدرته، وإنّما يتعلّق بالمعاني المخلوقة، فيقال: بسط علم عباده وقبضه، كما بسط علم موسى عليه السلام على الأحكام الظاهرة وقبضه عن الباطن، وبسط علم الخضر على الباطن وقبضه عن الأحكام الظاهرة،:قال الخضر لموسى: يا موسى إن على علم من علم الله لا أعلمه، وأنا على علم من علم الله لا تعلمه\".\rوأمّا تعلّقه بالمعاني المخلوقة فتكثر، أمّهاتها بَسْط المعارف وبسط الرزق، وعلى هذا كله هو من صفات الأفعال بكل حال.\r"], [970, "الفصل الرابع: في التنزيل\r"]], "pg": [968, 970]}, "561.799": {"x": [[970, "المنزلة العليا للربّ:\rفإنّ له الخلق والأمر والقبض والبسط.\rوللعبد في منزلته السفلى حكمان:\rأحدهما: أن يقبض بوهمه عن ربّه، وشهوته عن معصيته، ويبسُط معرفته عليه وطاعته إليه.\r"], [971, "الاسم السادس والسابع والخمسون: المقدِّم والمؤخِّر\rفيهما أربعة فصول:\rالفصل الأوّل: في موردهما\r"]], "pg": [970, 971]}, "561.800": {"x": [[971, "لم يرد بهما القرآن اسماً، لكن ورد بهما فعلا، قال تعالى: \"وَلَئِنْ أَخَّرْنَا عَنْهُمُ الْعَذَابَ إِلَى أُمَّةٍ مَعْدُودَةٍ\" (هود 8)، وقال: \"وَلَكِنْ يُؤَخِّرُهُمْ إِلَى أَجَلٍ مُسَمًّى\" (النحل 61)، وجاء ذكرهما في حديث أبي هريرة المفسّر المعدّد، وقال عليه السلام في النساء حال الصلاة: \"أخّروهنّ من حيث أخّرهنّ الله\"، وصح عن النبي عليه السلام أنه كان يقول في دعائه: \"أنت\r"], [972, "المقدّم، وأنت المؤخّر، لا إله إلا أنت\"، وعلى هذا الخبر هو المعوَّل في هذين الاسمين، وأجمعت عليهما الأمة.\rالفصل الثاني: في شرحهما لغة\r"]], "pg": [971, 972]}, "561.801": {"x": [[972, "أمّا اللغة فيهما فمعلومة، وليس لها إلا متعلَّقان:\rأحدهما: يتعلق بالزمان، كقوله: \" وَلَئِنْ أَخَّرْنَا عَنْهُمُ الْعَذَابَ إِلَى أُمَّةٍ مَعْدُودَةٍ\" (هود 8).\rوالثاني: يتعلّق بالرّتبة، كقوله عليه السلام: \"أخّروهنّ من حيث أخّرهنّ الله\".\rالفصل الثالث: في شرحهما حقيقة\r"]], "pg": [972, 972]}, "561.802": {"x": [[972, "فيه مسألتان:\rالمسألة الأولى:\r"]], "pg": [972, 972]}, "561.803": {"x": [[972, "الباري هو الفاعل لما يشاء، خالق كل شيء حقيقة، وقد قدّم بعض أفعاله على البعض، وأخّر بعضها عن بعض بإرادته، وقدّم طائفةً في\r"], [973, "الطاعة، وأخّر أُخرى عن العصمة، وأنبأ عن ذلك بقوله تعالى: \" عَلِمْنَا الْمُسْتَقْدِمِينَ مِنْكُمْ وَلَقَدْ عَلِمْنَا الْمُسْتَأْخِرِينَ\" (الحجر 24)، وأخّر المطلوب عن الطالب، والمرغوب عن الراغب بحكمته، وقدّم له المحنة بعدله وحُجّته.\rالمسألة الثانية:\r"]], "pg": [972, 973]}, "561.804": {"x": [[973, "قال بعض علمائنا: يحتمل أن يكون من صفات الذات، لأنه قدّم قوماً بالتعظيم، وأخّر آخرين بالذم والتهجين، وهذا القول ضعيف، فإن التقديم بالثناء، فائدة الثناء لا نفس الثناء، وكذلك التأخير في الذمّ.\rالفصل الرابع: في التنزيل.\r"]], "pg": [973, 973]}, "561.805": {"x": [[973, "للباري تعالى المنزلة العليا في هذا الاسم باختصاص التقديم والتأخير بيده، لا مُقدّم ولا مؤخّر سواه.\rوعلى العبد في منزلته السفلى أن يُسابق حتى يكون في أوّل السابقين لا في المتأخرين.\r"], [974, "الاسم الثامن والخمسون: المُقسط\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [973, 974]}, "561.806": {"x": [[974, "لم يرد به القرآن فعلا ولا اسماً، ولكن وردت به إشارةٌ إليه، وهي قوله: \" شَهِدَ اللَّهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ وَالْمَلَائِكَةُ وَأُولُو الْعِلْمِ قَائِمًا بِالْقِسْطِ لَا إِلَهَ إِلَّا هُوَ الْعَزِيزُ الحَكِيمُ\" (آل عمران 18)، وورد في حديث أبي هريرة المفسّر، وأجمعت عليه الأمّة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [974, 974]}, "561.807": {"x": [[974, "القسط هو العدل، وهو الحظّ والنصيب، يُقال أقسط إذا عدل، ولعلّه أعطاه حظّه ونصيبه، وقسط إذا جار، كأنّه قطع حظّه ونصيبه، وفي الصحيح: \"المقسطون يوم القيامة على منابر من نور، عن يمين الرحمن، وكلتا يديه\r"], [975, "يمينٌ، وهم الذين يعدلون في أنفسهم وأهليهم وما وَلُوا\"، ومنه التقسيط، وهو تمييز حظّ كلّ واحد من الشركاء في المتاع وتمييزه له.\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [974, 975]}, "561.808": {"x": [[975, "اللغة والحقيقة في سواء، لأنّ القسط هو إبراز الحظ، ومنه القسطاس، وهو أقوم الموازين، والباري تعالى أعطى كلّ ذي حقّ حقّه، وأبرز له قسمه وعيّنه لما كتبه له.\rقال النبي عليه السلام: \"لما خلق الله آدم مسح على ظهره بيمينه، فاستخرج ذؤّيته منه كهيئة الذرّ، ثم قبض فيهم قبضتين فقال: هؤلاء في الجنة ولا أُبالي، وهؤلاء في النار ولا أُبالي\"، وكلّ من قسط عدل.\r"], [976, "الفصل الرابع: في التنزيل\r"]], "pg": [975, 976]}, "561.809": {"x": [[976, "الباري يختصّ في ذلك بأحكامٍ ثمانية:\rالأول: أنه يقوم بالقسط في قوله كلّه، لأنّه الحقّ، وقوله الحقّ.\rالثاني: أنه المُقسِط في شهادته، لقوله: \" شَهِدَ اللَّهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ وَالْمَلَائِكَةُ وَأُولُو الْعِلْمِ قَائِمًا بِالْقِسْطِ\" (آل عمران 18).\rالثالث: انفراده بأقضية المقادير، واستبداده بإنفاذ التدبير، قال الله تعالى: \" وَاللَّهُ يَقْضِي بِالْحَقِّ وَالَّذِينَ يَدْعُونَ مِنْ دُونِهِ لَا يَقْضُونَ بِشَيْءٍ إِنَّ اللَّهَ هُوَ السَّمِيعُ الْبَصِيرُ\" (غافر 20).\rالرابع: تنفيذه الأحكام على حكم المشيئة، ومتعلَّق القول، ووَفْقِ العلم، كما قال تعالى: \" إِنَّمَا قَوْلُنَا لِشَيْءٍ إِذَا أَرَدْنَاهُ أَن نَّقُولَ لَهُ كُن فَيَكُونُ\" (النحل 40).\r"], [977, "الخامس: أنه يقوم بالقسط في إرادته وجود القاسط والمُقسِط، ولو شاء تعالى لما كان جَوْرٌ.\rالسادس: تقسيمه الخلق بين الجنة والنار، والنعيم والعذاب، لقوله في مساق آيات السياق؛ مُخبراً عن استقرار كلّ واحد منهما في منزلته التي حلّها بالعدل: \" وَقُضِيَ بَيْنَهُمْ بِالْحَقِّ وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ\" (الزمر 75).\rالسابع: تقسيم الخلق بين العافية والبلاء، مع صحة تعلّق القدرة بعموم العافية، كما قال تبارك وتعالى: \" وَلَنَبْلُوَنَّكُمْ حَتَّى نَعْلَمَ الْمُجَاهِدِينَ مِنكُمْ وَالصَّابِرِينَ\" (محمد 30)، وقال: \" وَلَنَبْلُوَنَّكُم بِشَيْءٍ مِّنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِّنَ الْأَمْوَالِ وَالْأَنفُسِ وَالثَّمَرَاتِ\" (البقرة 155).\rالثامن: تقسيمه الخلق بين الفقر والغنى، مع سعة الخزائن وإغناء الكلّ، حتى تنقطع بهم الأماني بعدله وحكمه، \" وَلَوْلَا أَنْ يَكُونَ النَّاسُ أُمَّةً وَاحِدَةً\" (الزخرف 33).\r"], [978, "وعلى العبد في المنزلة السفلى أن يقوم بالقسط في قوله وفعله، في نفسه أو غيره، قال تعالى: \" يَاأَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ وَلَوْ عَلَى أَنفُسِكُمْ أَوْ الْوَالِدَيْنِ وَالْأَقْرَبِينَ\" الآية (النساء 135)، فإذا امتثل ذلك نال المنزلة التي أخبر عنها الصادق: \"المقسطون يوم القيامة على منابر من نور، عن يمين الرحمن، وكلتا يديه يمين، وهم الذي يعدلون في أنفسهم وأهليهم ما وَلُوا\".\r"], [979, "الاسم التاسع والخمسون: النصير\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [976, 979]}, "561.810": {"x": [[979, "ورد به القرآن اسماً وفعلاً، قال الله تعالى: \" نِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ\" (الأنفال 40)، وقال أيضاً: \" بَلِ اللَّهُ مَوْلَاكُمْ وَهُوَ خَيْرُ النَّاصِرِينَ\" (آل عمران 150)، وقال: \"إِنْ تَنْصُرُوا اللَّهَ يَنْصُرْكُمْ\" (محمد 7)، وجاء في حديث أبي هريرة من طريق ابن الحُصين، وأجمعت عليه الأمّة.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [979, 979]}, "561.811": {"x": [[979, "فيه عباراتٌ:\rالأولى: النصر: المنع، لقوله: \" فَمَن يَنصُرُنِي مِنَ اللَّهِ إِنْ عَصَيْتُهُ\" (هود 63).\r"], [980, "الثانية: العَوْن، لقوله: \" وَهُمْ لَا يُنْصَرُونَ\" (فصلت 16)، المعنى عند علمائنا: لا يُعانون، ويقال: نَصَرَ المطرُ الخِصْبَ إذا أعانه على النبات.\rالثالثة: الانتقام، كقوله: \" وَلَمَنِ انْتَصَرَ بَعْدَ ظُلْمِهِ فَأُولَئِكَ مَا عَلَيْهِمْ مِنْ سَبِيلٍ\" (الشورى 41).\rالرابعة: النصر: الإتيان والمجيء، قال الشاعر:\rإذا دخل الشهر الحرام فودِّعي *** بلاد تميم وانصري أرض عامرِ\rالخامسة: النصر: العطاء، قاله بعض علمائنا، واستشهد عليه بقوله:\rإنّي وأَسْطارٍ سُطِرْنَ سَطْراً *** لقائلٌ يا نَصْرُ نَصْرٌ نَصْراً\rولعله راجعٌ إلى ما قبله.\rالفصل الثالث: في شرحه حقيقة وعقدا\r"]], "pg": [979, 980]}, "561.812": {"x": [[980, "فيه مسألتان:\rالمسألة الأولى: في تحقيق معنى النصر\r"]], "pg": [980, 980]}, "561.813": {"x": [[980, "اعلموا –بصّركم الله بالمعارف- أنّكم إذا تتبعتم معنى النصر وحقيقته وجدتموه كله يرجع إلى العون، فإنّ المانع مُعينٌ للممنوع منه،\r"], [981, "والمعطى مُعانٌ، وفي إتيان الأرض عونٌ لأهلها، والمُنتصر مُفتعلٌ من العون، كأنه أعان نفسه، وحقيقة العون هي إعطاء القوة على الفعل المحمود أو سببه الموصِل إليه، والباري تعالى هو الواهب للخلق القُدرة واليُسر لأسباب العلم.\rالمسألة الثانية: في قوله تعالى: \" إِنْ تَنْصُرُوا اللَّهَ يَنْصُرْكُمْ \" (محمد 7).\rقال علماؤنا: إن قال قائل: كيف جاز \" إِنْ تَنْصُرُوا اللَّهَ يَنْصُرْكُمْ\"، والنصر هو العون، والله سبحانه لا يجوز عَونُه قولاً ولا يُتصوَّر فعلاً؟\rالجواب عنه من أوجه؟\rأحدها: أن يقال: المعنى: إن تنصروا الله بالدعاء.\rالثاني: إن تنصروا دين الله بالجهاد عنه.\rالثالث: المعنى: إن تنصورا نبيّ الله، وأضاف النصر إلى الله تشريفاً للنبيّ صلى الله عليه وسلم وللدين، كما قال تعالى: \" مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا \" (الحديد 11)، فأذاف القرض إليه تسليةً للفقير.\r"], [982, "ولقد تكلّم أبو منصور ساتكين التركي المالكي وأبو الفضل عطاءٌ المقدسيّ بالمسجد الأقصى في هذه المسألة ليلةً من العِشاء إلى الصبح، وقد ذكرنا ذلك في كتاب \"عيان الأعيان\".\rالفصل الرابع: في التنزيل\r"]], "pg": [980, 982]}, "561.814": {"x": [[982, "الباري يختصّ في النصر بخلق القدرة على الطاعة.\rوعلى العبد أن ينصره بطاعته في نفسه، وتغيير المنكر على غيره.\r"], [983, "الاسم الموفّي ستّين: الشّافي\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [982, 983]}, "561.815": {"x": [[983, "هو اسم لم يرد به القرآن، لكن وردت به السنة، كان عليه السلام يقول في رُقْيته: \"واشفِ أنت الشافي\"، وأجمعت عليه الأمّة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [983, 983]}, "561.816": {"x": [[983, "تقول العرب: شفاه الله يَشْفيه، إذا أعاد صحّته وأذهب داءَه.\rالفصل الثالث: في حقيقته\r"]], "pg": [983, 983]}, "561.817": {"x": [[983, "ربّما ظنّ بعض الجهال بشفاه الله زوال الداء، وليس كما زعم، وإنما هو عَوْد الصحّة على حالها، ورجوعها إلى هيئتها، وإنما يسقط في هذا غافلٌ أو مبتدعٌ يعتقد أن الشفاء عدم الداء، كما أن الموت عنده عدم\r"], [984, "الحياة، والجهل عدم العلم، وهذه كلها اعتقادادت فاسدة قد بيّنّاها في كتب الأصول، وأنّ الصحيح من ذلك معاني صحيحةٌ متضادّةٌ، إذا عُدم واحدٌ وُجد آخر، فاستقرّ أن الحقيقة في الشفاء أنه صحّة ثانية بعد الداء، كما أن البعث حياة ثانية بعد الموت، والصحة معنًى، والألم معنًى، والشفاء صحّة بعد الألم.\rالفصل الرابع: في التنزيل\r"]], "pg": [983, 984]}, "561.818": {"x": [[984, "إذا ثبت هذا فالمنزلة العليا للباري تعالى قد بيّنها عليه السلام بقوله: \"لا شافي إلّا أنت\"، فيعتقد الشفاء، له وبه ومنه، وأن الأدوية المستعملة لا توجب شفاءً ولا تُحدث صحّةً، وإنما هي أسباب يخلق الله عقيبها فعله، وهي الصحة التي لا يخلقها حيّ سواه، فكيف ينسُبها عاقلٌ إلى جماد من الأدوية أو سواها، ولو شاء ربك لخلق الشفاء دون سبب، ولكن لما كانت الدنيا دار أسبابٍ جرت السنّة فيها –بمقتضى الحكمة- على تعليق الأحكام بالأسباب.\r"], [985, "وإلى هذا المعنى أشار جبريل عليه السلام، وإياه أوضح بقوله لرسول الله عليه السلام: \"بسم الله أَرقيك والله يشفيك\"، فبيّن أن الرُّقية منه، وهي سببٌ لفعل الله، وهو الشفاء، ولا يبقى بعد ذلك إشكال لذي لبٍّ.\rالمنزلة السفلى للعبد:\rأن يعلم أن الشفاء منه، فلا يشكر سواه، ولا ينتظره من عند غيره، وأعلى من كان في هذه المنزلة منزلة أبي بكر الصدّيق، حين قالت له عائشة رضي الله عنها في مرضه: \"ألا ندعوا لك طبيبا؟ فقال: الطبيب أمرضني\"، وفي رواية: \"قد رفعتُ إليه أمري فأجاب: بأني فعّال لما أريد\".\r"], [986, "وبعد هذا مرتبةٌ أخرى بيّنها عليه السلام بقوله: \"يدخل الجنة من أمتي سبعون ألفاً بغير حساب، وهم الذين لا يسترقون ولا يتطيّرون، وعلى ربهم يتوكلون\"، فهؤلاء لمّا تحقّقوا أن الشفاء بيده لم يتعلّقوا بالأسباب، وإنما أحالوا على المُسبّب لينالوا الشفاء دون واسطة، أو يقبضوا أكرم عِوَضٍ من الصحة في الآخرة.\rولمّا كان الخلق لا يحتملون هذا المقام بعمومهم رتّبهم الله منازل، فأدناهم من يتعلّق بالأدوية، وأعلاهم مرتبة الصدّيق، ولا رتبة بعد هذا إلّا لعاصٍ يعتقد أن الأسباب توجب الصحّة، أو لمبتدع يعتقد أنها تفعلها، والله يعصم من المقالة الفاسدة، ويهب التوفيق للحالة الجامدة برحمته.\r"], [987, "الاسم الحادي والستّون: مُقلّب القلوب\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [984, 987]}, "561.819": {"x": [[987, "هو اسمٌ لم يرد به القرآن، ولكن وردت به السنة، كان عليه السلام يقول في يمينه: \"لا ومقلّب القلوب\"، ويُروى \"مُصرّف القلوب\"، وروي عنه عليه السلام أنه قال: \"إن قلوب بني آدم كلّها بين إصبعين من أصابع الرحمن\"، كقلب واحدٍ يصرّفه كيف يشاء، ثم قال عليه السلام: \"اللهم مُصرّف القلوب اصرف قلوبنا إلى طاعتك\"، وأجمعت عليه الأمة.\r"], [988, "الفصل الثاني: في شرحه لغة\r"]], "pg": [987, 988]}, "561.820": {"x": [[988, "أمّا القلب في اللغة فمعلوم، والتقليب والتصريف هو استعمال الشيء من جميع جوانبه وجهاته المحتملة فيه.\rالفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [988, 988]}, "561.821": {"x": [[988, "وفيه ثلاث مسائل:\rالمسألة الأولى: في حقيقة القلب\r"]], "pg": [988, 988]}, "561.822": {"x": [[988, "اعلموا –وفّقكم الله- أن القلب قطعة من دم جامدة شكّلها الله بشكل حبّ الصنوبر، وخلقه على هيئته، لكنّه منكوس الخِلقة، لأنّ شكله المخروط إلى أسفل، وقاعدته في الأعلى، وطرفه المحدّد مائل إلى الجهة اليسرى، فلأجل ذلك يُرى ويُحسّ بنبض عرقه من الجهة اليسرى أو بتحركه.\rالمسألة الثانية: في كونه محلّا للعلم.\r"]], "pg": [988, 988]}, "561.823": {"x": [[988, "اعلموا –وفّقكم الله- أن القلب مَحَلٌّ يخلق الله فيه العلم والإرادة والكلام والعقل على اختلافٍ، والصحيح أن محلّه القلب حسب ما بيّنّاه في كتب الأصول، وما من حيوان إلّا وله قلب صنوبريّ، وله إدراك فيه،\r"], [989, "ولكنّ قلب الآدميّ يتميّز عن قبول البهائم بمزية التفكير والتقدير، والتمثيل والترتيب، والإرادة، والاستدلال على ما لا يُعلم بما يُعلم.\rوبهذه الصفات كلّها التي جعلها الله فيه، وجعله محلّاً لها، وبها ميّزه من سائر الحيوانات صار شريفاً كاملاً، لأنه صقله لها، ونهاه عن التعرّض لصدئه بالذنوب، فإن تعرّض فقد أمره بالصّقل بالتقوى والتّلاوة، فقال عليه السلام:\r\"إن هذه القلوب تصدأ كما يصدأ الحديد، فاجلوها بالتقوى والتلاوة\".\r"], [990, "المسألة الثالثة:\r"]], "pg": [988, 990]}, "561.824": {"x": [[990, "كما أنّ القلب محلٌّ لهذه الصفات الشريفة فإنه أيضا محلٌّ للصفات الذميمة، وبهذه الدقيقة تميّز القديم عن المُحدَث، فإنّ الوجود الإلهي موصوفٌ بكلّ صفة كمالٍ مقدَّسٌ عن صفات النقص، والموجود المحدَث موصوفٌ بوجهين، فهو وإن وُصف بكمالٍ فإنّه موصوفٌ بالنقصان؛ من شهوة وغضب وحقد، والحواسّ تُلقي إليه المعاني الذميمة، والعقل والعلم يحثّه على الصفات الكريمة، ويُبيّن له عاقبة الأوصاف الذميمة، ومَلَكٌ مُسخَّرٌ يعضُد العلم بنور النظر، وشيطان مُسخّر يعضد الشهوة بحكم الجِبِلّة، ولُطْف الله الذي يُسمّى توفيقا، وعدله الذي يسمّى خذلاناً قائمان، والقَدَر يجري\r"], [991, "على العبد بأحدهما حسب ما سبق في علمه، فلما تركّبت هذه الأخلاق زوجين، حسب تركيب مخلوقات الله تعالى، عبّر عليه السلام عن ذلك قَصْد البيان بقوله: \"قلب المؤمن بين إصبعين من أصابع الرحمن\"، وتعالى الله عن إصبع جارحة، ولكن كانت حكمته ما قدّمنا في كتاب المشكلين فذلك موضعه، وصار تصرُّف القلب بين هذه الأحوال تقليبا وتصريفا، وذلك بقدرة الله وحكمته، فكان مقلّب القلوب ومصرّفها سبحانه.\r"], [992, "الاسم الثاني والثالث والستّون: الضارّ النافع\rفيهما أربعة فصول:\rالفصل الأول: في موردهما\r"]], "pg": [990, 992]}, "561.825": {"x": [[992, "هو اسم ورد به القرآن على طريقٍ بديعةٍ، قال تعالى: \"وَيَعْبُدُونَ مِن دُونِ اللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ\" (يونس 18)، وقال مُخبراً عن الخليل في حُجّته على قومه: \"أَفَتَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لَا يَنْفَعُكُمْ شَيْئًا وَلَا يَضُرُّكُمْ أُفٍّ لَكُمْ\" (الأنبياء 67)، وقال تعالى: \"لَّا أَمْلِكُ لِنَفْسِي نَفْعًا وَلَا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ\" (الأعراف 188)، ولو لم يكن الباري تعالى\r"], [993, "ضارّا نافعاً لكانت الحُجج المتقدمة باطلة، واعتذار النبي عليه السلام ساقطاً، وذلك باطل، وورد في حديث أبي هريرة المعدّد، وأجمعت عليه الأمة، واختصّ به أهل السنة.\rالفصل الثاني: في شرحهما لغة\r"]], "pg": [992, 993]}, "561.826": {"x": [[993, "اعلموا –وفّقكم الله- أن الضرر في اللغة هو الضرر بعينه في الحقيقة، وهو:\rالفصل الثالث:\r"]], "pg": [993, 993]}, "561.827": {"x": [[993, "وقد أشكل الضرر والنفع على أكثر الخلق حتى ضلّوا فيه وأضلّوا، ونحن نكشف حقيقته على الاختصار، إذ كشفناها في المٌقسِط على طريق الاستبصار، فنقول:\rإن جماعةً من الجهّال –منهم المعتزلة- ظنّوا أن الضرر هو ضرّ ألمٍ وغمٍّ وحُزْنٍ ومشقّةٍ، فركّبوا من ذلك أصولا فاسدة، وركِبوا سبيلاً عن الحق حائدة، وحقيقة الضرر هو الألم والغمّ والحزن الذي لا نفع فيه، يوفي عليه أو\r"], [994, "يوازيه، وهو نقيض النفع الذي لا ضرر فيه، ولهذا لم يُوصف العلاج وشرب الأدوية النافعة ضررا لما يعقبه من المنفعة في الصحّة، ولا وُصفت العبادات الشاقة بأنه ضررٌ؛ بما فيها من إتعاب الأبدان وترك اللذّات لما يعقُبُها من الثواب، والنفع الذي لا ضرر فيه هو نعيم الجنة، والضرر الذي لا نفع فيه هو عذاب النار.\rالفصل الرابع: في التنزيل\r"]], "pg": [993, 994]}, "561.828": {"x": [[994, "إذا علمتم الضرر والنفع، فالباري تعالى هو المتخصّص بإيثار النفع والضرر.\rوعلى العبد أن يكون نافعاً لغيره غير ضارٍّ.\r"], [995, "الاسم الرابع والستون: ذو المعارج\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [994, 995]}, "561.829": {"x": [[995, "ورد به القرآن، قال الله تعالى: \"لَيْسَ لَهُ دَافِعٌ مِنَ اللَّهِ ذِي الْمَعَارِجِ\" (المعارج 3)، وروي في حديث أبي هريرة المفسّر من طريق عبد العزيز بن الحُصين، وأجمعت عليه الأمّة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [995, 995]}, "561.830": {"x": [[995, "العروج: الحركة إلى فوق، والنزول: الحركة إلى أسفل، يقال: عَرَج يعرُجُ، بفتح العين في الماضي وضمّها في المستقبل، عُرُوجاً، كما يقال في مقابلته: نزل نزولاً، والمعارج مفاعلٌ منه.\rالفصل الثالث: في حقيقته\r"]], "pg": [995, 995]}, "561.831": {"x": [[995, "فيه ثلاث مسائل:\r"], [996, "المسألة الأولى: في حقيقته\r"]], "pg": [995, 996]}, "561.832": {"x": [[996, "وحقيقته ولغته سواءٌ.\rالمسألة الثانية: في معنى قوله: \"ذي المعارج\"\r"]], "pg": [996, 996]}, "561.833": {"x": [[996, "اختلف الناس في معنى قوله ذي المعارج على أربع عبارات:\rالأولى: الدرجات.\rالثانية: الفواضل والنِّعَم.\rالثالثة: العوارج هي الملائكة.\rالرابعة: معارج السماء.\rالمسألة الثالثة: في تحقيق المراد\r"]], "pg": [996, 996]}, "561.834": {"x": [[996, "اعلموا أن المعارج مَفاعل، وهي جمع مَفعل بكسر العين وفتحها، الذي يُعبَّر عنه بالزمان والمكان والمصدر، وإذا كانت محتملةً لأن تكون جمع زمان العروج، وجمع مكانه، فيحتمل أن يكون المراد به جمع معارج السماء كما تقدّم، ويحتمل أن يكون يريد به زمان العروج، يريد القطع من الأرض إلى السماء السابعة –وهو مسافة عظيمة- في لحظة، وذلك بديعةٌ في الخِلقة تدلّ على القدرة، وتكون الفائدة فيه أمران عظيمان:\r"], [997, "أحدهما: أن الجهة التي تنزل منها الرحمة، وهي جهة فوق، منها ينزل العذاب بعينها.\rالثاني: نزول العذاب من ناحية العُروج، وهي جهة فوق التي ليس لأحد فيها حيلة ولا مُدافعة، بخلاف سائر الجهات؛ من يمين ويسار، وخلف وقُدّام، فإن النفس تتحدّث بهذه الجهات الأربع بحيلةٍ أو مدافعة، فإذا رأت الآية تنزل من فوقها ألقت بيدها.\rفأمّا قول من قال إن المعارج الدرجات أو الملائكة أو الفواضل، فإنّما رأى أن يُعبِّر بمكان الشيء عن الشيء، فإن المعارج مواضع العوارج، وموضع المنازل والدرجات، وموضع الفواضل، وذلك كلّه مجازٌ لا يُحتاج إليه، وإن دلّ الكلام عليه، فإنّ كلّ كلام يستقلّ معناه الحقيقي لا يُحمَل على مجازه القريب فكيف البعيد.\rالفصل الرابع: في التنزيل\r"]], "pg": [996, 997]}, "561.835": {"x": [[997, "إذا علمتم أن الباري مالك المنازل، فاعلموا:\rالأول: أنه منزّه عن التصرّف فيها بذاتٍ.\r"], [998, "الثاني: أنه يقسمها لمن شاء من غير اعتراض عليه.\rالمنزلة السفلى للعبد:\rله فيها ثلاثة أحكام:\rالأول: أن يكون نازلا بأعلاها.\rالثاني: أن يكون عامراً لها بالكلام الطيّب والعمل الصالح.\rالثالث: أن يجعل لروجه فيها مسلكاً، فإن الروح الطيبة تعرج إلى عليّين، والروح الخبيثة تنزل إلى سجّين.\r"], [999, "الاسم الخامس والستون: خير المُنْزِلين\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [997, 999]}, "561.836": {"x": [[999, "ورد به القرآن، قال تعالى: \"وَأَنْتَ خَيْرُ الْمُنْزِلِينَ\" (المؤمنون 29).\rالفصل الثاني: في شرحه لغة\r"]], "pg": [999, 999]}, "561.837": {"x": [[999, "النزول هو الكون بالموضع المعتَقد للاستقرار فيه، هذه حقيقته، ثم نُقل إلى المراتب المعنوية مجازاً.\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [999, 999]}, "561.838": {"x": [[999, "الحقيقة واللغة فيه سواء، والمنازل هي أحد أقسام الدرجات التي بيّنّاها في قوله تعالى: \"رَفِيعُ الدَّرَجَاتِ\" (غافر 15) إذا مُدِحَت، وهي كل محلٍّ نزله باعتقاد الاستقرار في المحسوس، وكلّ خَصلةٍ محمودة أو مذمومة اختصّ بها المختَصّ، وبهذا فارقت الدرجات، فإنّها المحمودة خاصّة.\r"], [1000, "الفصل الرابع: في التنزيل\r"]], "pg": [999, 1000]}, "561.839": {"x": [[1000, "المنازل لله تعالى يؤتيها من يشاء؛ إنْ محمودة فمحمودة، أو غيرها، فاعقِد أيها العبد أن ذلك بيده مِلكاً، ولا يصح أن تكون له صفة.\rالمنزلة السفلى للعبد:\rأن يجتهد لنفسه في أحسن المنازل ديناً، وذلك بنزول المساجد وحِلَق الذّكر، والاختصاص بالحُلى المحمودة.\r"], [1001, "الاسم السادس والستون: خير الماكرين\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [1000, 1001]}, "561.840": {"x": [[1001, "قال الله تعالى: \"وَمَكَرُوا وَمَكَرَ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ\" (آل عمران 54).\rالفصل الثاني: في شرحه لغة\r"]], "pg": [1001, 1001]}, "561.841": {"x": [[1001, "المكر في اللغة هو كلّ فِعلٍ يفعله العالم مع العالم أو العاقل، يقصد فيه أنه منفعة وهو له مضرّة.\rالفصل الثالث: في حقيقته\r"]], "pg": [1001, 1001]}, "561.842": {"x": [[1001, "الحقيقة فيه ما قلنا إنه لغةٌ، والباري تعالى يفعل مع الكفار فعلاً من الصحة والنّعمة يظنونهما منفعةً وهي مضرّةٌ، لأنّها أسبابٌ إلى الكُفر والمعصية، وفي هذا إشكالان:\r"], [1002, "الأول: أن الباري تعالى إنما ذكر المكر في طريق الجزاء لا في طريق الأسماء، كما قال: \"اللَّهُ يَسْتَهْزِئُ بِهِمْ\" (البقرة 15)، وقال: \"وَأَكِيدُ كَيْداً\" (الطارق 16)، فإنما جاء هذا كله في جزاء الأفعال، ويُسمّى جزاء الفعل باسم الفعل حسب ما بيّنّاه في كتاب المشكلين، وكذلك المَكر، فما كان هذا سبيله لا يُتّخذ اسماً.\rبيانه:\rأنّ المكر قد أضافه النبي عليه السلام إلى الباري تعالى ابتداءً، وكان يقول في دعائه: \"ربّ أعني ولا تُعِن عليّ، وامكُر لي ولا تمكُر عليّ\"، فإضافه إليه ابتداءً وسأله منه، فدلّ على أنّه من أوصافه وأسمائه.\rالإشكال الثاني: أن المكر مذموم، فإضافته إلى الله عزّ وجلّ مُشاقّةٌ.\rالجواب: أن المكر على قسمين:\rمحمودٌ: وهو ما يُفعَل مع الكفار أو للحِيلَة في تخليص النفس والمال من الظالم.\r"], [1003, "ومذمومٌ: وهو ما يُفعل على العموم مع المؤمنين.\rفالذي يوصي به الباري تعالى –وهو من أفعاله- هو المحمود، وهو الذي يجوز للمسلمين سلوكه، والمذموم لا يُوصَف به الباري فعلاً، ولا يجوز للمسلم ارتكابه، والله أعلم.\r"], [1004, "الاسم السابع والستون: مُتمٌّ نورَه\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [1001, 1004]}, "561.843": {"x": [[1004, "هو اسم ورد به القرآن، قال تعالى: \"وَاللَّهُ مُتِمُّ نُورِهِ\" (الصف 8)\rالفصل الثاني: في شرحه لغة، والفصل الثالث: في شرحه حقيقة\r"]], "pg": [1004, 1004]}, "561.844": {"x": [[1004, "قد تقدّم ذكر النور حقيقة ولغةً في تفسير قوله تعالى: \"اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ\" (النور 35)، فأمّا قوله: مُتمٌّ نورَه، فإنّ التمام من الأسماء المضافة كما قدّمناه، فلا يكون تامّاً إلا بالإضافة إلى ناقص، وقد بيّنّا أن لله سبعين حجاباً من نورٍ، أوّلها السّراج، وآخرها رداء الكبرياء، وهو النور الأعظم.\rإذا قلنا إنه من أسمائه؛ ومن أنواره مُجسَّمة ومنها معنويّةٌ، ومن أشرف المعنوية الرسل والكتب والملَك، فإذا أظهر الله تعالى\r"], [1005, "الملك، وبعث الرّسل، وأنزل الكتب، وصرف الكفّار عنها، وصدموا فيها قصْداً لإطفائها وإخفائها، أو تقصيرها وتوقيفها، فيأبى الله إلا أن يتمّ نوره وتمامه أن يبلغ إلى القدر الذي أراده فيه وكتمه ظاهراً منه، فافهموا ذلك ترشُدوا.\rوالتنزيه ووصفُ الله فيه وحظّ العبد منه قد تقدّم من قبل، والله أعلم.\r"], [1006, "الاسم الثامن والستّون: شفيعٌ\rعدّه بعض الناس اسماً لأجل قوله: \"مَا لَكُم مِّن دُونِهِ مِن وَلِيٍّ وَلَا شَفِيعٍ\" (السجدة 4)، ولأنّه جاء في الخبر الصحيح أن الله تعالى يشفع.\rومعنى الشفاعة ضمّ شيء إلى شيء، فهو يضمّ إلى أهل الجنة من شاء من أهل النار، على وجهٍ بيّنّاه في كتاب المشكلين والمقسط وغيرهما.\r"], [1008, "ذكر أسماء الباري تعالى التي وجبت له بفعل غيره\r"], [1010, "اعلموا –أفادكم الله المعارف- أن أسماء الباري تعالى على ما بيّنّاه من الترتيب والتقسيم، وهذا الباب خاتمة أسمائه حسب ما تقدّم بيانه في المقدّمات، وهي ذكر الأسماء التي وجبت له بفعل غيره.\rوقد قلنا في المتقدّم من كلامنا، إن أفعال الباري لا تُوجِبُ صفاتٍ لذاته فكيف أفعال غيره، وكما توجب أفعاله أسماءً، فكذلك أفعال غيره، توجب له أيضا أسماءً، وهو فنٌّ من التحقيق والتوحيد تكعُّ عنه قلوب الشادين، وتشمئزّ له نفوس الحاسدين، وتقشعرّ منه جلود القاصرين المتقاعدين.\rوهي جمّةٌ يكثُرُ تَعدادها، لكن نشير منها إلى أسماء:\r"], [1011, "الاسم الأول: الوكيل\rوفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [1004, 1011]}, "561.845": {"x": [[1011, "هو اسمٌ ورد به القرآن، قال الله تعالى: \"وَكَفَى بِرَبِّكَ وَكِيلًا\" (الاسراء 65)، وقال: \"أَلَّا تَتَّخِذُوا مِنْ دُونِي وَكِيلًا\" (الاسراء 2)، وقال مُخبراً عن المؤمنين: \"وَقَالُوا حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيل\" (آل عمران 173)، وجاء في حديث أبي هريرة المفسَّر، وأجمعت عليه الأمّة.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [1011, 1011]}, "561.846": {"x": [[1011, "اختلف أهل اللغة في العبارة عن معناه على أربعة أقوال:\rالأول: أنه الكفيل؛ قال الفرّاء، وأنشد:\rذكرتُ أبا أروى فبتُّ كأنّني بردِّ *** الأمور الماضيات وكيلُ\rالثاني: كافٍ\r"], [1012, "الثالث: المُقسط، قاله ابن عرفة.\rالرابع: حفيظ، رُوي عن الفرّاء أيضا.\r"]], "pg": [1011, 1012]}, "561.847": {"x": [[1012, "الفصل الثالث: في شرحه حقيقة وعقدا\rالمسألة الأولى:\r"]], "pg": [1012, 1012]}, "561.848": {"x": [[1012, "اعلموا –وفّقكم الله- أن الوكيل فعيلٌ من الوكالة، يقال: وكَلْتُ إليه أمري، أكِلُهُ ووكلتُ فلاناً، والوُكلُ والوكيل الضعيف البليد، والتواكل إظهار العجز والاعتماد على الغير.\rوإذا فهمتم هذا، فالوكيل هو الضعيف الذي يكِل أمره إلى غيره، ممّن يعجز كعجزه، ومنه قوله عليه السلام: \"لا تكِلنا إلى أنفسنا طرفة عينٍ فنهلِك\".\r"], [1013, "والمتوكّل هو الذي يُقرّ بعجزه ويُلقي مقاليد أمره إلى القادر عليه، فإذا فعل ذلك يقال: وكل أمره إليه وتوكّل عليه، وهو الوكيل؛ فعيلٌ بمعنى مفعول، لا معنى له سواه.\rفأمّا من قال: إنه الكافي أو الكفيل أو المُقسط أو الحفيظ، فليس ذلك من مُقتضيات اللفظ، وإنما هو مأخوذٌ من لوازم المعنى وفوائد ثمراتٍ تتعلّق به، وليس ذلك بتفسيرٍ ولا هو في حكم التفسير.\rالمسألة الثانية: في الرد على هشام الفُوطي\r"]], "pg": [1012, 1013]}, "561.849": {"x": [[1013, "اتّفق الناس على وصف الباري بأنه وكيلٌ، لكون ذلك وارداً في كتابه، إلّا هشاماً الفوطي، فإنه أبى ذلك، واحتج بأن هذه\r"], [1014, "صفة نقصٍ لأنه يوهم الخطأ كوكيل القرى والحوائج، وذلك لا يليق بالله سبحانه.\rوالجواب: أنّ هذا بعد ورود النصّ باسم الوكيل، كقول إبليس بعد ورود الأمر بالسجود: أنا خير منه.\rجوابٌ ثانٍ: وذلك أن الاشتراك في الأسماء لا يوجب الاشتراك في المعاني، كالجبّار والمتكبّر، أو لا ترى أن المشتَهى محبوبٌ، والبري محبوب، وكذلك الربّ اسمٌ عظيم من أسماء الله تعالى، ويشترك فيه مع ربّ الدابّة وربّ الدار، وذلك لا يصرّ في الاعتقاد إذا عُلم المعنى.\rالمسألة الثالثة: في تركيب المعنى الاعتقادي على اللغوي\r"]], "pg": [1013, 1014]}, "561.850": {"x": [[1014, "اعلموا –أرشدكم الله- أنّا إذا قلنا إن الوكيل هو من وكلتُ إليه الأمور وألقيت إليه المقاليد فهذا يقتضي أنه اسم فعلٍ، ومعلوم أن المقاليد كلّها لله، وإنما قال للعبد سلّم إليّ بقولك مالي بحقّي، وتخلّ عمّا ليس لك باعتقادك، وأنا الموفِّق لك في كل ذلك والمانع منه، وتوفيقي لك لذلك علامة نجاتك، ومنعي علامة هلاكك.\r"], [1015, "فقد تبيّن لكم أن الوكيل اسمٌ يرجع إلى الفعل، له معنًى حقيقيٌّ هو لله واجبٌ، فكَونُ المقاليد إليه والأمور بيده، أمرٌ واجبٌ لم يزل ولا يزال، وتسليم العباد ذلك له أمر حَدَثَ، فهو الملك بما وجب له، والوكيل بما صار إليه، والتسليم مضافٌ إلينا في المجاز، وهو له بالحقيقة، وهذا تحقيق بالغٌ لا يقدُرُهُ قدْرَهُ إلا ريّانُ من العلوم، جذلانُ من الإيمان.\rالفصل الرابع: في التنزيل\r"]], "pg": [1014, 1015]}, "561.851": {"x": [[1015, "إذا علمتم معنى الوكيل فلله في ذلك في منزلته العليا أحكامٌ يختصّ بها أربعةٌ:\rالأول: انفراده بحفظ الخلق.\rالثاني: انفراده بكفايتهم.\rالثالث: قدرته على ذلك كلّه.\rالرابع: أن جميع الأمور من خير وشرّ ونفع وضرّ وكلّ حادثٍ بيده.\r"], [1016, "المنزلة السفلى للعبد:\rوله في ذلك ثلاثة أحكام:\rأحدها: أن يتبرّأ من الامور إليه لتحصل له حقيقة التّوحيد، ويرفع عن نفسه شغب الوجود.\rالثاني: أن لا يستكثر ما يسأل، فإنّ الوكيل غنيٌّ، ولهذا قيل: من علامات التوحيد كثرة العيال على بساط التوكّل.\rالثالث: أنك إذا علمت أن وكيلك غنيٌّ وفيٌّ قادرٌ مليٌّ، فإعرض عن دُنياك وأقبِل على عبادة من يتولّاك.\r"], [1017, "الاسم الثاني: المَوئِل\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [1015, 1017]}, "561.852": {"x": [[1017, "قال الله تعالى: \"لَّن يَجِدُوا مِن دُونِهِ مَوْئِلًا\" (الكهف 58)، ولم يذكره علماؤنا، إلا أنّا وجدناه في كتاب الله استقراءً، فلم يتفطّنوا له.\rالفصل الثاني: في شرحه لغة\r"]], "pg": [1017, 1017]}, "561.853": {"x": [[1017, "الموئل الملجأ، يقال: وأل إليه يئل وأْلاً ووُؤولاً ووَئِيلاً، وواءل مُواءلةً ووِئالاً لجأ، والوأْل والمَوْئل الملجأ.\rالفصل الثالث: في شرحه عقيدة\r"]], "pg": [1017, 1017]}, "561.854": {"x": [[1017, "إذا كان الموئل الملجأ، فالباري تعالى هو ملجأ المهضومين ومفزع المظلومين، كما قال تعالى: \"أَمَّن يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ\" (النمل 62)، ولا خلاف في ذلك فيحتاج إلى دليل، ولا إشكال فيه فيفتقر إلى مزيد بيان.\r"], [1018, "الفصل الرابع: في التنزيل:\r"]], "pg": [1017, 1018]}, "561.855": {"x": [[1018, "المنزلة العليا للربّ:\rوله في ذلك ثلاثة أحكام:\rالأول: أنه لا ملجأ غيره.\rالثاني: أنه إذا لجأت إليه دون مقدّمة قبِلَكَ.\rالثالث: أنك إذا لجأت إليه مع المعاصي والإعراض قبل ذلك أغاثك.\rالمنزلة الثانية للعبد:\rأن يلزم الطاعة، ويُقدّم الأسباب الحسنة قدْر الاستطاعة، ليَجدها مفْزعاً عنده وقت الضرورة، فإنّ ذلك أصحّ له في الكفاية، وأنجح في العصمة، قال تعالى في يونس: \"فَلَوْلَا أَنَّهُ كَانَ مِنَ الْمُسَبِّحِينَ لَلَبِثَ فِي بَطْنِهِ إِلَى يَوْمِ يُبْعَثُونَ\" (الصافات 143 - 144).\rوقال علماؤنا: سبّح في الرخاء فأنجح في الشدّة، وقال عليه السلام: \"إن ثلاثة نفر ممن كان قبلكم آوَوا إلى غارِ حذار المطر، فانحدرت عليهم صخرةٌ سدّت فَمَ الغار وأيِسُوا من الخلاص، فقالوا\" الحديث، فكل واحد منهم إنّما توسّل بما تقدّم حالة الرخاء في حالة الشدّة.\r"], [1019, "الاسم الثالث: المُستعان\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [1018, 1019]}, "561.856": {"x": [[1019, "قال سبحانه: \"وَرَبُّنَا الرَّحْمَنُ الْمُسْتَعَانُ عَلَى مَا تَصِفُونَ\" (الأنبياء 112)، ولم يرد في حديث أبي هريرة، ولا ذكره علماؤنا، وهو من أشرف الأسماء لشرف متعلّقه، وقد تضمّنت فاتحة الكتاب معناه، فقال تعالى: \"إِيَّاكَ نَعْبُدُ وإِيَّاكَ نَسْتَعِينُ\".\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [1019, 1019]}, "561.857": {"x": [[1019, "الاستعانة في اللغة ممّا كثُر استعمالها في لفظهم لكثرة احتياجهم لها، لكنهم لم يُخلّصوا لها عبارة خاصّة، قالوا: العون الظهير، ويُسمّون الباء حرف الاستعانة، لأنك تقول: كتبتُ بالقلم، وضربتُ بالسيف، وبريتُ بالمُدْية.\rالفصل الثالث: في شرحه حقيقةً وعقدا\r"]], "pg": [1019, 1019]}, "561.858": {"x": [[1019, "فيه مسألتان:\r"], [1020, "المسألة الأولى: في حقيقة العَون\r"]], "pg": [1019, 1020]}, "561.859": {"x": [[1020, "قال علماؤنا: العَون هو القدرة على الشيء، يقال: أعانه إذا أقدره، والقدرة هي الصفة التي يتيسّر بها فعل الشيء، وهي المتعلّقة بوجود العدم، فسمّوا كلّ ما كان في العادة سبباً للشيء، أي مقترنا بوجوده ومُيسِّراً في العادة له عَوْناً، كالسكّين للبَرْي، والقلم للكتابة، والسيف للضرب.\rالمسألة الثانية:\r"]], "pg": [1020, 1020]}, "561.860": {"x": [[1020, "إذا عرفتم معنى العون فالاستعانة هي طلب العون وسؤاله، وذلك لا يكون إلا من الله وحده، لأنه هو خالق القدرة وميسّر الأسباب، وكذلك علّمنا ديننا، وبيّن لنا اعتقادنا فقال: \"إِيَّاكَ نَعْبُدُ وإِيَّاكَ نَسْتَعِينُ\"، لكنه أذن في نسبته إلى المخلوقين، ورخّص في سؤالهم ذلك بعد المعرفة بأنه سخّرهم وخلق القدرة لهم كخلقها لك.\rوالأفعال على قسمين:\rمنها ما يستقلّ به المرء؛ ومنها ما لا يستقلّ به.\rولها أيضا حالان:\rحالة يستقلّ فيها العبد بالفعل؛ وحالةٌ لا يستقلّ.\r"], [1021, "فرخّص له في طلب المعونة على فعلٍ لا يستقلّ به، إمّا بمعنىً يرجع إلى الفعل، أو بمعنًى يرجع إلى الحال، فإن ترخّص فذلك له توسعة، وإن حرم وردّ الأمر إلى أهله –وهو الله تعالى- فهو أقوم في الطريق، وأقوى في التوحيد والتحقيق كما رُوي.\rالفصل الرابع: في التنزيل\r"]], "pg": [1020, 1021]}, "561.861": {"x": [[1021, "المنزلة العليا للربّ:\rتتبيّن لكم في حُكمَين:\rأحدهما: أنه لا مُعين سواه.\rالثاني: أنه وإن كان يُعين فإنه لا يُعان ولا يستعين لاستحالة ذلك عليه.\rالمنزلة السفلى للعبد:\rتتبيّن لكم أيضاً في حكمين:\rأحدهما: أن لا يستعين بغير الله، كما تقدّم من قول الخليل لجبريل عليهما السلام وقد عرض له في المنجنيق \"فقال له: ألك حاجة؟ فقال: أمّا إليك فلا\".\r"], [1022, "الثاني: أن الاستعانة بغير الله على طاعته لله إذا قَدَرْته قَدْرة وتحقّقت أنه واسطةٌ لا يمنَعُ منها ولا يؤثّر في الاعتقاد.\r"], [1023, "الاسم الرابع: المعبود\rفيه أربعة فصول:\rالفصل الأوّل: في مورده\r"]], "pg": [1021, 1023]}, "561.862": {"x": [[1023, "وهو اسم لم يَرِد به قرآن ولا رأيته في السنّة، لكن لمّا جاء المستعان من يُستعان قلنا: المعبود يُعبَد، قدّمنا المستعان عليه لأنّه ورد مذكوراً بصيغة الأسماء، ولم يرد المعبود إلّا فعلاً، وأجمعت عليه الأمّة.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [1023, 1023]}, "561.863": {"x": [[1023, "تركيب \"عين باء دال\" في لسان العرب يُفيد معاني مفيدة، لكن المقصود من معانيها الآن عندنا أنّ العبد هو المملوك المربوب، يُقال: عبد عُبُودةً، وتعبد الرّجل صيّره كالعبد، ومنه قوله تعالى: \"وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَيَّ أَنْ عَبَّدتَّ بَنِي إِسْرَائِيلَ\" (الشعراء 22)، ويقال: بعيرٌ مُعبد وطريقٌ مُعبَّدٌ، وهو الذي لا صعوبة فيه، قد سهل بالرياضة للبعير، وكثرة المشي للطريق.\r"], [1024, "الفصل الثالث: في شرحه حقيقة وعقداً\r"]], "pg": [1023, 1024]}, "561.864": {"x": [[1024, "فيه مسألتان:\rالمسألة الأولى:\r"]], "pg": [1024, 1024]}, "561.865": {"x": [[1024, "أمّا الحقيقة فإنّي لما تتبّعتها ألْفَيتُها منتظمةً من التصرّف والاستعمال، وكان العبد هو المصرَّف بحكم السيّد، والسيّد هو المصرِّف للعبد بحُكم نفسه، وإليه يرجع عبيد الله، فإنه المصرِّف لهم، وعبيد القوم، لأنّهم بحكمهم، وبعيرٌ معبَّدٌ؛ قد كان صعباً فصار بحكم صاحبه، وطريقٌ مُعبد قد كان مُتحَزِّناً فعاد سهلاً.\rالمسألة الثانية:\r"]], "pg": [1024, 1024]}, "561.866": {"x": [[1024, "إذا ثبتت حقيقة حقيقة العبودية فاعلموا أن تصرفات الشريعة تنقسم إلى ما يظهر فيه غرض الآدمي، وإلى ما لا يظهر له فيه غرضٌ، فالأوّل كقضاء الدَّين، والثاني كالصلاة والصّوم.\rوأمّا القسم الأوّل فتعيّن الأمر فيه بالتصرّف على الآدمي مُطلقاً من غير قصد قُربةٍ.\r"], [1025, "فأمّا الثاني فأُمر بأن يقصد بالتصرّف التقرّب إلى الله؛ وهذا بابٌ اتّفق العلماء على تسميته عبادةً، لما فيه من التذلّل والخضوع المحض للمعبود، حين تجرّدت عن غرض الآدميّ، وانغلق باب الحظوظ فيها، فإذا أُدّيَت على هذا الوجه قيل: عبد الرجلُ ربّه، أي ذلّ له، وتعبد الرجل لربّه أي أقرّ لربّه بالعبوديّة قولاً وتذلّل فعلاً، وهذا معنى قوله: \"إِيَّاكَ نَعْبُدُ\".\rالفصل الرابع: في التنزيل\r"]], "pg": [1024, 1025]}, "561.867": {"x": [[1025, "المنزلة العليا للربّ فيه:\rأنّه مخصوصٌ به لا يجوز لغيره، ولا يجوز منه، ولا يُتصوَّر لتقدُّسه وتعاليه عن معناه.\rالمنزلة السفلى للعبد:\rأن يعبد ربّه بشرطين:\r"], [1026, "أحدهما: أن لا يُشرك به شيئا.\rالثاني: وأن يُخلِص له فعلاً، كما قال تعالى: \"وَمَا أُمِرُوا إِلا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ\" (البينة 3)، والله أعلم.\r"], [1027, "الاسم الخامس: المذكور\rفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [1025, 1027]}, "561.868": {"x": [[1027, "قال الله تعالى: \"فَاذْكُرُونِي أَذْكُرْكُمْ\" (البقرة 152)، وقال تعالى: \"وَالذَّاكِرِينَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتِ\" (الأحزاب 35)، فوَرَد فعلاً ولم يرد اسماً.\rالفصل الثاني: في شرحه لغةً\r"]], "pg": [1027, 1027]}, "561.869": {"x": [[1027, "قال علماؤنا: ذكرتُ الشيء بلساني وقلبي ذِكرا، واجعله منك على ذُكرٍ، أي لا تنساه، والذكْرُ الشرف، والذكر في الاعتبار، وعدّدوا في ذلك كثيراً.\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [1027, 1027]}, "561.870": {"x": [[1027, "التحقيق فيه: أن الذكر هو الكلام، وبحسب تصرّف الكلام يكون تصرّف الذكر، وكما أن الكلام على نوعين: نوع في القلب، ونوع في اللسان، فكذلك الذكر على ضربين: نوع من القلب، ونوع من اللسان، قال الله تعالى: \"من ذكرني في نفسه ذكرته في نفسي، ومن ذكرني في ملإٍ ذكرته في ملإٍ خيرٍ من\r"], [1028, "ملئه\"، وقد أطلقت العرب واستعملت الشريعة إطلاق الذكر على العِلْم الثاني المُتعَقِّب للذهول، لأن الذكر له في القلب، مقرونٌ به اقتران العلم بالكلام، حسب ما بيّنّاه في أصول الدين.\rكما أطلقت اسم الذكر على الفوائد المستفادة من الذكر، فقد قالت العلماء في قوله: \"فَاذْكُرُونِي أَذْكُرْكُمْ\" أي اذكروني بالطاعة أذكركم بالثواب، ونحو هذا، والكلّ قريب المأخذ، جائز الاستعمال، والله أعلم.\rالفصل الرابع: في التنزيل\r"]], "pg": [1027, 1028]}, "561.871": {"x": [[1028, "المنزلة العليا للربّ سبحانه:\rتقدّمت في أسماء الكلام، فإن ذِكر الله هو خَبَرُه عن كلّ ما أخبر عنه، ويتعلّق بالمحمود والمذموم، فتعلّقه بالمحمود كقوله: \"فَاذْكُرُونِي أَذْكُرْكُمْ\" (البقرة 151)، ويختصّ تعالى فيه بأنه السابق به.\r"], [1029, "المنزلة السفلى للعبد:\rأن لا يعمر قلبه بغير حبه، ولا يشغل لسانه بغير ذكره، ولا يستعمل جوارحه في غير خدمته، وإن كان يظهر في هذه الثلاثة توجُّه لغيره فهو المعنيُّ به والمُراد منه، والله أعلم.\r"], [1030, "الاسم السادس: أهل التقوى وأهل المغفرة\rوفيه أربعة فصول:\rالفصل الأول: في مورده\r"]], "pg": [1028, 1030]}, "561.872": {"x": [[1030, "ورد به القرآن، قال الله تعالى: \"هُوَ أَهْلُ التَّقْوَى وَأَهْلُ الْمَغْفِرَةِ\" (المدثر 56)، وفي حديث أنس بي مالك عن النبي عليه السلام أنه قال في تفسير هذه الآية: قال: \"قال الله تعالى: أنا أهلٌ أن اتّقى، فمن اتّقى فلم يجعل معي إلهاً فأنا أهلٌ أن أغفر له\"، رواه سهلٌ القُطَعي، وليس بالقويّ، لكن قد أجمعت الأمّة عليه لكونه في كتاب الله.\r"], [1031, "الفصل الثاني: في شرحه لغة\r"]], "pg": [1030, 1031]}, "561.873": {"x": [[1031, "اعلموا أن قول القائل أهلٌ يقال في وجوه: أهل المذهب من يَدين به، وأهل الأمر وُلاته، وأهل البيت سكّانه، ومكانٌ آهلٌ ومأهولٌ فيه أهل، ويقال: مرحباً وأهلاً، أي أتيت أهلا لا غرباء، وعلى هذا قال العلماء: المُلك لله أهل المُلك، وأهّله لهذا الأمر –بتشديد العين- وآهله رآه له أهلاً، واستأهله استوجبه، وكرهه بعضهم.\rالفصل الثالث: في شرحه حقيقة\r"]], "pg": [1031, 1031]}, "561.874": {"x": [[1031, "فيه مسألتان:\rالمسألة الأولى: في الحقيقة\r"]], "pg": [1031, 1031]}, "561.875": {"x": [[1031, "وإذا ثبت ما ذكرناه في الأهل، فحقيقة الأهليّة المحلّ الذي يتأتى فيه المقصود والمضاف إليه، ويختصّ بالوجه الذي يُحال به عليه، فإذا قلت: مكان آهل فمعناه يتأتّى فيه المُقام، وإذا قلت: فلان أهلٌ لكذا، فمعناه أنك تجد فيه ما تقصد له وتريده منه.\rالمسألة الثانية: في معنى قوله: \"أهل التّقوى\"\r"]], "pg": [1031, 1031]}, "561.876": {"x": [[1031, "إذا ثبت هذا فاختلف العلماء في معنى قوله: \"أهل التّقوى\" على قولين:\r"], [1032, "أحدهما: أنه أهلٌ أن يُتّقى، لجلاله وصفاته التي استحقّ بها الكمال في النعت، كما قال عمر: \"نِعْم العبد صهيبٌ، لو لم يخف الله لم يَعْصه\"، وقد تقدّم وجهه والقول فيه وتحقيقه.\rالثاني: قال كثير من علمائنا: معناه أن التقوى تجب له بعظيم قدرته، وشديد عقابه وسطوته، وهذا هو الذي أميل إليه وأُعوّل عليه.\rالمسألة الثالثة: يف معنى كونه أهل المغفرة\r"]], "pg": [1031, 1032]}, "561.877": {"x": [[1032, "المعنى: لتقدّسه عن حاجة إلى العذاب، وقيل: لأن رحمته سبقت غضبه، وبه أقول، قال عليه السلام: قال الله تعالى: \"لو لم تذنبوا لجاء الله بقوم يُذنبون حتى يغفر لهم\".\rقال الشاعر:\r"], [1033, "فلو لم يكن فينا مُسيءٌ ومُذنبٌ *** لجِئتَ بقوم يُذنبون لتغفرا\rوالقول في ذلك عريضٌ طويل يحتاج إلى تفصيل.\rالفصل الرابع: في التنزيل\r"]], "pg": [1032, 1033]}, "561.878": {"x": [[1033, "المنزلة العليا للرب:\rأنه لا يُتّقى سواه، ولا يُعبد غيره.\rالمنزلة الثانية للعبد:\rأن يتّقيه حقّ تقاته، فإن غُلب فما استطاع، وأن يغفر لغيره كما يُحبّ أن يُغفر له، ولذلك ندب الله تبارك وتعالى إليه النبي صلى الله عليه وسلم وحضّ عليه.\rتعظيم، ومدعوِّ ودخل في هذا الباب كل اسم وجب للباري سبحانه في غيره، كمُعَظَّمٍ من دعا، ومُتَضَرَّعٍ إليه من التضرُّع، ومشكورٍ من الشكر لنعمه، ومحمودٍ من الثناء عليه بما هو أهله، إلى أمثاله مما لا يُستقصى، وفي الذي أوردنا منه دلالةٌ على غيره لمن أحصى.\r"], [1034, "القطب الرابع:\rفي ذكر المُتمّمات التي يحصل بها المطلوب\r\rوذلك يَبين بسبع لواحقَ نُعدّد كلّ فصل من المتمّمات والتوابع فيها:\r"], [1036, "اللاحقة الأول: في بيان جوامع أغراض الكتاب\rاعلموا –وفّقكم الله- أن المؤلفين في هذا الباب، وإن كانوا على حالتين: منهم من اختصر واقتصر، ومنهم من أوعب واستظهر، فإنّهم لم يستنزلوا على جميع المقاصد، ولا شرعوا في جملة الموارد، وإنّما أخذ كل واحد بطرفٍ لواه وما استوفاه، وهذا الكتاب غدا مُوثَقَ المباني، وأتى على جميع المعاني، إذ رتّبنا القول فيه على أربعة عشر وجهاً:\rالأول: النظر في مورد الاسم قرآناً وسنّةً وإجماعاً، فعلاً أو اسماً، إفراداً أو جمعاً.\rالثاني: النظر في معناه لغةً.\rالثالث: القول في حقيقته ومعناه الخاص، للمعقول منه المضمون للفظه.\rالرابع: اختلاف الناس فيه.\rالخامس: المختار منه.\r"], [1037, "السادس: دفع الشبهة العارضة له.\rالسابع: وجه اختصاص الباري سبحانه فيه.\rالثامن: وجه اختصاص العبد بمعناه فيه.\rالتاسع: ضمّ الأسماء كلّها إلى الصفات السبع التي لا مزيد عليها في المعقول والمنقول جميعاً.\rالعاشر: حُسْن الوصف والترتيب في جميع ذلك، على وجهٍ يُقرّب على الناظر بعيد النّظر، ويُسدّدُه في مجاري الفكر، وهذه سبيلٌ لم نُسبَق إليها، ولم نُزحَم عليها، لا تُبقي نظراً ولا إلباساً.\rالحادي عشر: تنزيه القول في الأسماء عن تشبيهِ صارت إليه الحشويّة، وكثير ممن يُعاني الظاهر من الكتاب والسنّة وشُغِف به، دون الإشراف على المعاني والتطلّع إلى الحقائق.\rالثاني عشر: تنزيهها عن تعطيلٍ مال إليه كثيرٌ من الغالين، حتى ردّوا أسماء الله تعالى إلى اسمٍ واحد، والمعاني الكثيرة إلى معنًى واحد، جهلاً بالحقائق، أو عمداً للإلباس ونفي الصانع، فطهّرنا كتابنا من هذا كلّه، وأشرنا إلى جزء يسير من البيان في الطرفين، وما أشكل بيانه فهو في المُقسط والمشكلين.\rالثالث عشر: إعراضنا عن أغراض الصوفيّة من علمائنا، فإنّهم وإن كانوا أهل اعتقادٍ وتحقيقٍ، فإنّهم سلكوا في عباراتهم أوْعر طريقٍ، وأشدّ ما على\r"], [1038, "الطالب من ذلك؛ أنّهم إذا عبّروا عن الله تعالى، وعن صفاته العلى، سلكوا من الاستعارة والمجاز أقصى سبيلٍ سلكه شعراء العرب وفصحاء الكَلِم، ويعتقدون أنّ ذلك من أفضل القُرَب، وأبلغ وجوه البيان؛\rوقد استنكف سائر العلماء عن ذلك لوجهين:\rأحدهما: أنها سبيلٌ لم يسلكها السلف، فبقيَتْ مَجْهَلَةً مُوعرة لا تُفضي بقاصدها إلى مسلك، وربّما أُبدَعَ به فيها وهلك؛\rالثاني: أنّ فيها من الإلباس بطرفي التشبيه والتعطيل ما لا تسلم عنه عقائد المتبحّرين في العلم، فكيف المبتدئين، فتجانفنا عنه، عن علمٍ به وقراءة ومعرفة لحقائقه وخبرةٍ، اقتداءً بالسلف الماضين، ورغبة في احتذاء الأئمة المهتدين.\rالرابع عشر: ما ضمّنّاه من أحكام أسماء الله تعالى في فصل التنزيل من كلّ اسمٍ، وذلك أمرٌ بديعٌ عظيم القدْر، لو لم يكن في الكتاب سواه لكفاه، وستنتهي نيّفاً على ألف حُكمٍ، يأتي منها أَزيد من ألف اسمٍ، وهو بحرٌ لا يُنزَف، وخِضمٌّ لا ساحل له، وإنّما يأخذ كلُّ أحدٍ منه بمقدار علمه وما يفتح الله، فله الفضل والمنّة.\r"], [1039, "اللاحقة الثانية: في رجوع هذه الأسماء إلى سبع صفات\rلا استنكار في لغة العرب لرجوع أسماء كثيرة إلى معنًى واحد، فإنها باتّساع لسانها وتبحّرها في الألفاظ، بما وُضع لها أو تواضعته، جاء في لسانها للمعنى الواحد أسماءٌ كثيرةٌ، كالأسد مثلا والسيف، ولكن عبّرت عن وجود الذات بواحد، وأتت بسائر الأسماء على معنى التعبير عن الذات، ومعنًى كالخادر والخُنابس والهِرماس، وكالمُهنّد والعَضْب والصمْصامة، فكلّما كثرت المتعلَّقات والأوصاف حدثت العبارات قصد البيان لها والتمييز لآحادها عن جملتها.\rولا ذات أكبر من الذات الإلهية ولا أكرم، ولا تعلُّق أعظم من متعلَّقاتها، فأوجب ذلك كثرة الأسامي في التعبير عنها، فلو قلت إنها ألف اسمٍ أو ألفُ ألفٍ إلى ما لا يُحصى لم يقع التعبير لقصور العقل، فتعيّن الإحصاء لمورد الشرع، وانقطع الرجاء عمّا سواه والطّمع.\r"], [1040, "وكان الاسم المعبِّر عن الجميع المُستوفي لكلّ وجهٍ من التعلّق قولك: الله، فإنه عبارة عن الذات والصفات والمتعلَّقات، وكلّ ما تصوّره مُتصوِّر من المعاني أو يخفى عن العقول دَرْكه.\rفلا يُلتفتُ إلى من يقول: \"قولنا: الله عبارةٌ عن الوجود والذات خاصّة\"، فإنه تقصيرٌ ظاهرٌ، وقولٌ مع الجهل مُتَظاهِرٌ، ولذلك كان عليه السلام يقول: \"لا أُحصي ثناء عليه، أنت كما أثنيت على نفسك\".\rوالمقدار الذي اطّلع الخلق عليه وشرُفوا بمعرفته إنّما يرجع إلى ما دلّت العقول عليه، وذلك كون الباري تعالى: موجوداً، قادراً، عالماً، حيّاً، سميعاً، بصيراً، متكلّماً، مع ما يرتبط بذلك من نفيِ وإثبات، ويرجع إليه من جميع المتعلَّقات، لا يخرج وجهٌ من ذلك عنها، ولا تشذّ عبارة عن الاعتبار بها، فلأجل ذلك شحّرناها في ذلك المعيار، وسابقنا بها في هذا المضمار، ولم نقتصر على الإشارة والإجمال دون التفصيل، حتى تقع المعرفة بها على وجه يشفي الغليل.\r"], [1041, "اللاحقة الثالثة: في الشكوك الواردة على عدد الأسماء والجواب عنها\rقد علمتم ما وجدنا من الأسماء في القرآن وسردناه لكم، وما جاءت به السنّة ممّا حضرنا حالة الإملاء، وعلى ذلك أتى الشرح على جميع الاستيفاء، ولكن يتطرّق إلى ذلك خمسة شكوكٍ، من الحقّ أن نتعرّض لها بالبيان حتى تكمُل الفائدة بارتفاعها ويقع اليقين باندفاعها.\rالشكّ الأول: هل لله اسمٌ سوى التي أوردناها وشرحناها كما جاء في الكتاب والسنّة؟ وقد انفصلنا عنها في المقدّمات والسوابق، وفي الثانية من اللواحق.\rالثاني: أن يجري في الخاطر: ما فائدة الإحصاء في حديث أبي هريرة بتسعة وتسعين، وهي أكثر من ذلك؟\r"], [1042, "والجواب عنه: أن هذا مما لا يُتوصّل إلى معرفته بحالٍ، على طريق التحقيق، ولكن على طريق التخمين، لكنّ العلماء قد أوردوا في ذلك عبارات لا تُغني، منها:\rقول بعضهم: يجوز أن يكون لله تعالى تسعةٌ وتسعون اسماً، لها دلالة ليست لغيره؛\rوهذا قولٌ ضعيف، لأنه يقال له: هل هذه الأسماء المعلومة لنا أم في غيرها؟ فإن ادّعيت أنه في هذه المعلومة لدينا فذلك باطلٌ قطعاً، وإن ادّعيت أنه فيما لم يُعلَم فلم يتكلّم عليه السلام فيها ولا تعرّضنا نحن لها.\rوقال بعضهم: جهات الجلال والشرف انتهت إلى تسعة وتسعين فعبّر بها عنها.\rوهذا باطلٌ، لأنه إن أراد جهات الجلال والشرف في الأصل، فإنّ جهات الجلال والشرف انحصرت في سبع صفاتٍ كما بيّنّا، وكلّها ترجع إليها، وإن أراد في المتعلَّقات فإنه لا تُحصى عند الخلق.\r"], [1043, "فتبيّن أن هذا كلّه دعوى ولا برهان عليها، والحق أنه ليس مما يُدرَك بنظرٍ، ولا ورد به خبر، فالحزم الإمساك عنه.\rالثالث: أن يقال: هل في هذه الأسماء اسم الله الأعظم أم لا؟\rوقد قال بعض العلماء: يجوز أن يكون فيها، ويجوز أن يكون خارجاً عنها، وقد بيّنّا اسم الله الأعظم ومعنى وصفه به، وبذلك يظهر الجواب عن هذا التشكيك.\rالرابع: هل أحصى عليه السلام الأسماء وبيّنها أم لا؟\rأجاب عن ذلك بعض العلماء بأنّه كذلك نُقل، ونصر ذلك وقوّاه ودلّ عليه.\rوهذا باطلٌ، فإنّه لم يصحّ قطّ عن رسول الله صلى الله عليه في ذلك حرفٌ، وإنّما الذي عُلم بالخبر وجه الإحصار للعدد المذكور وفائدته، وهي دخول الجنة، ووُكِل الإحصاء إلى الملتقِطين له من الكتاب والسنّة والعالِمين به، ليقع البحث والاجتهاد، ويتفاوت الخلق فيه على الجوب والاستبداد، فتنفُذ الكلمة بالجنّة أو النار في المعاد.\r"], [1044, "الثانية: التمثيل بالكبائر في جملة المعاصي ليَعُمّ الاجتناب الكلّ، وبليلة القدر في ليالي الشهر ليَعُمّ الاجتهاد بالعبادة الجميع، كذلك يعُمّ الإحصاء والطللب لجميع الأسماء فيتضاعف الثواب ويحصل المطلوب.\rالخامس: هل فيها ما زعمه بعض الناس من قولهم: الدّهر ورمضان وديّان وسلطان أم لا؟\rقلنا: أمّا الدهر فقد بيّنّاه في كتاب المشكلين، في تفسير قوله: \"فإن الله هو الدهر\"، وأمّا رمضان وسلطان وديّان، فجاءت في أحاديث ضعيفة لا أصل لها، وعلى ألسنة قوم لا تحقيق عندهم، فلا يُلتفت إليه.\rفإن قيل: فلم لم تذكروا المطّلِب في الأسماء، وقد جاء في الحديث: \"أنا ابن عبد المطّلب\"، ومن أسمائه التي يُحلف بها الطّالب؟\r"], [1045, "الجواب من وجهين:\rأحدهما: أن نقول: أمّا الطالب فهو سبحانه؛ طالبٌ بقوله في التكليف، طالبٌ بفعله في التصريف، لكن لم يَردْ به أثرٌ والحلفُ به بدعة.\rالثاني: أن المُطّلب ليس من أسماء الله لأنّ وزنه مُتَفَعِّلٌ، ولا يُضاف منه إلى الباري إلّا ما جاء على طريق الاختصاص، كما قلنا في المتكبّر ونحوه، وأمّا تسميته جد النبي عليه السلام بعبد المطّلب، فإنّما يصحّ أن يُضاف عبد المطّلب إلى جدّه المطّلب لأنه ابنه، والابن عبد الأب إذا استويا في الدين، كافرين أو مسلمَين، بما يتعيّن عليه من البرّ الذي هو بمنزلة السيّد على العبد، والله أعلم.\r"], [1046, "اللاحقة الرابع: في كيفية الإحصار\rتحزّب الناس في ذلك أحزاباً، وآل اختلافهم إلى ثلاثة أقوال:\rفمنهم من قال: لا سبيل إليه.\rالثاني: أن ذلك لا يُوصَلُ إليه إلا بعُسرٍ، لأنّ الأسماء المطلقة غير المضافة ولا المتعلِّقة بالصفة يعزّ وجودها، ولا يُجمع منها إلا ما قلّ ممّا ورد في الحديث.\rوالصحيح: أنه سهلة سمحة، لأن ما في كتاب الله منها معلومٌ قطعاً سهلاً، وما في حديث رسول الله صلى الله عليه يُوصل إليه بروايته وقراءته،\r"], [1047, "فتتخرّج منه، وإذا قرأ العبد القرآن والسنّة دخل الجنّة، وهو فائدة قوله: \"من أحصاها دخل الجنة\"، ومعناه والمراد به؛ وهي الحثّ على قراءة القرآن والسنة، هذا هو المعنى الصحيح والفائدة العظمى، فافهموا ترشُدوا.\r"], [1048, "اللاحقة الخامسة: في ردّ قول من قال إن الأسماء كلها لقبية غير مشتقة ولا إضافية\rظنّ بعض الجهلة أن الأسماء كلّها لا تكون إلا كهيئة الألقاب، زَيدٍ وعمرٍو وبكرٍ، دون الكاتب والعالم، أو لا تكون إلا مطلقة مفردة، كقولنا: عالمٌ قادرٌ، لا مضافةً، ولا تكون مضافةً، كقولنا: فاطر السماوات، عالم الغيب والشهادة، وأراد أن يجمعها هكذا تسعة وتسعين، وهذه غباوة ظاهرة، وجهلٌ عظيم باللغة والشريعة وما سلكه السلف، وخلافٌ لما أجمعت عليه الأمّة.\rولا جواب له عندي إلا قوله تعالى: \"فَأَعْرِضْ عَنْ مَنْ تَوَلَّى عَنْ ذِكْرِنَا وَلَمْ يُرِدْ إِلَّا الْحَيَاةَ الدُّنْيَا ذَلِكَ مَبْلَغُهُمْ مِنَ الْعِلْمِ\" (النجم 29 - 30).\r"], [1049, "فمن انتهى إلى هذا المقدار سقطت مكالمته، ولم يُجعَل في من يُناظَر ويُرَدّ عليه، وليس العجب منه، إنّما العجب ممن تطوّق بطوق العلم، وتعصّب بتاجه من أهل المشرق، ثم قال: إنّ بعض حفّاظ المغرب ذكر أنّه أحصى من أسماء الله ثمانين اسماً، وما علم ولا يتصوّر أن يعلم أحدٌ لله اسماً لا يكون صفةً إلا قوله الله، على اختلافٍ فيه، لا ثاني له، فكيف يدّعي جاهلٌ أنّ له ثانياً، أو يظنّ عالمٌ أنّ أحداً جمعها ثمانين.\r"], [1050, "اللاحقة السادسة: في جواز حمل اللفظ على معانيه المختلفة بشرطه\rقد ذكرنا في تفسير أسماء الله المتقدمة، أن أكثرها له معاني كثيرةٌ مختلفةٌ، وبيّنّا جميع معانيها ووجوه محتملاتها، وأوضحنا صحّة المراد بكلّ واحد منها، واستعمال اللفظ الواحد على كثير من المعاني، وقد اختلف الناس في ذلك اختلافاً كثيراً بيّنّاه في أصول الفقه.\rبيد أنّ بعض المحقّقين من المتأخرين أتى بطريقين غريبين:\r"], [1051, "أحدهما: أنه أبى حمل اللفظ المشترك على جميع معانيه لغةً وجوّزه شرعاً، وهذا يبعدُ، لأنه إذا جاز شرعاً حملُ اللفظ المشترَك على جميع المعاني جاز ذلك لغةً، وهذا متوقّف على النقل وُرُودُه، وأما جوازه فهو في الكل على وجه واحد سواء، وحمل اللفظ الواحد على جميع المعاني إذا لم يكن فيه استحالةٌ فهو أبلغ في البيان وأكمل في المدح، والله أعلم.\rالثاني: أنه قسّم ذلك ونوّعه، فقال: أمّا لفظ السلام مثلاً فيجوز أن يُحمل على معنى السلامة مع النقائص، وسلامة الخلق منه.\rوأمّا لفظ المؤمن فلا يُحمل على التصديق والأمان، ولكن يقال: حمْله على الأمان أمدحُ من حمله على التصديق.\rوالصحيح: حمْله على المعنيين في كل واحد منهما، لما بيّنّاه من المبالغة في الشأن وكمال المدح، وذلك مُحقَّقٌ في أصول الفقه.\r"], [1052, "اللاحقة السابعة: تميم في مآخذ أسماء الله وصفاته\rقد بيّنّا مآخذ أسماء الله وصفاته في السوابق، وتكملة ذلك في اللواحق؛ أن بعض المتأخرين من علمائنا قال في طريق مآخذ أسماء الله وصفاته: إنّ كل ما كان منها يرجع إلى الاسم فذلك موقوفٌ على الإذن، وما يرجع إلى الوصف فذلك لا يقف على الإِذْن، ولكن ما صدق منه كان مُباحاً، وما كان كذباً كان محظوراً.\rقال: والفرق بين الاسم والصفة، أن الاسم هو الموضوع للدلالة على المسمّى كزيد، والصفة كقولك: أبيض وطويل، وكأنه يشير إلى أن ما كان مشتقّاً من معنًى هو فيه فهو صفة، وما لم يكن مشتقّاً فهو اسمٌ.\r"], [1053, "قال الإمام الحافظ رضي الله عنه: هذه دعوى، وقد مال إليه كثير من قَرَأةِ علم اللسان، والاسم ينطلق على الاسم والصفة، وقد قال تعالى: \"\" (يوسف 40)، فسمّاها أسماءً، وكانت مشتقّة كاللات والعُزّى وهُبَل ومناة وغيرها، ومن ذَكَرَ من النُّحاة الفرق بين الاسم والصفة فإن كان أراد أن يُقدِّر الفرق بين ما يقع مشتقّاً وبين ما يقع مُرتَجلاً ليفصل الحقيقة لا ليمتنع من صحّة الإطلاق فقد أصاب، وإن أراد غيرها فلا يصحّ ذلك له.\rوإذا تأمّل هذا المنصف اللبيب فإن علماءنا اختلفوا في الاسم والصفة اختلافاً واحداً كما تقدّم:\rفمنهم من قال: إنه يجوز أن يُسمّى من ذلك ما كان مدحاً وجلالاً صريحاً، دون ما كان فيه إيهام تشبيهٍ أو تعطيلٍ فيهما جميعاً.\rومنهم من قال: ذلك يقع على السّمع والإذْن، وليس ذلك موقوفاً على الصدق والكذب، فإنّا لو قلنا في الباري إنه عاقلٌ لصدَقْنا، ولكن لا نقول ذلك\r"], [1054, "لما فيه من الإيهام، ونقول إنه خير الماكرين بالإذن، وإن كان في ذلك إيهامٌ لمكر المخلوقين، ولكن قرأناه وتلوناه إذْناً، وتأوّلناه علماً، وهذا بيّنٌ من الكلام، ومأخذٌ يُوفي على التّمام.\r"], [1055, "اللاحقة الثامنة:\rقد جمعنا في هذا الكتاب من أقوال العلماء عيوناً، ونظمنا من فِقَرهم فنوناً، ولم يبق اسمٌ ذكروه إلا ذكرناه، ولا وصفٌ شرحوه إلا شرحناه حتى اجتمع منها مائتا اسم وسبعٌ وستّون اسماً هي أمّهات باقيها وشارحات معانيها، وكاشفات خفاياها، وفارجات زواياها، ونرجو من فضل الله أنه لا يبقى بعدها اسمٌ لطالب إلا وجده أو دليله، ولا مقصداً إلّا قد ارتفع علمه واتضحت سبيله، ولا نوعاً من علومها ومتعلَّقاتها إلّا أوضحنا جملته وتفصيله، فإذا قرأه أحدٌ فليأخذ منه ما يفتقر إليه، وليقف عند المُبهم عليه، ولا يَعِبْه بتطويل، فإنّ معه شفاء الغليل، وإن عاين وهْماً فسبحان المحيط قدرةً\r"], [1056, "وعلماً، فأمّا نحن فلم نعتمد منه حرفاً إلّا بعد أن رأينا عرفاً، ولكن لا نأمن الزّلّة، ولا نضمن العصمة.\rوقد انتهى الأمد، وحصل الاستيفاء إياه للعدد، ونرجو أنّ القول فيه إذا تأمّله اللبيب المُنصف رأى أنه غُنية الطالب، ومُنية الراغب، وإلى الله نضرع ونرغب أن ينفعنا به أُخْرى ودُنيا، ويُنيل به الدرجة العليا برحمته، إنّه مُنعِمٌ كريمٌ، وآخر دعوانا أن الحمد لله ربّ العالمين.\r"]], "pg": [1033, 1056]}}, "units": {"1": {"tit": "الأمد الأقصى - المجلد الأول", "lvl": 1, "pg": [1, 557]}, "406": {"tit": "الأمد الأقصى - المجلد الثاني", "lvl": 1, "pg": [557, 1056]}}};
